/// Appends each visited root to a checked type store.
const CheckedTypeRootAppender = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,

    /// Append one root.
    pub fn visit(self: *const CheckedTypeRootAppender, var_: Var) Allocator.Error!void {
        _ = try appendCheckedTypeRoot(self.allocator, self.module, self.store, self.active, var_);
    }

    /// Append a root checking must have recorded.
    pub fn visitRequired(self: *const CheckedTypeRootAppender, maybe_var: ?Var, comptime missing: []const u8) Allocator.Error!void {
        try self.visit(maybe_var orelse checkedModuleInvariant(missing, .{}));
    }

    /// Append a root that owns a source scheme. A source scheme occupies
    /// no store entry: its id is its root's (`CheckedSourceTypes.schemeForSourceVar`).
    pub fn visitScheme(self: *const CheckedTypeRootAppender, var_: Var) Allocator.Error!void {
        try self.visit(var_);
    }

    /// Append a local nominal declaration and the roots its annotation names.
    pub fn visitNominalDeclaration(self: *const CheckedTypeRootAppender, statement_idx: CIR.Statement.Idx, nominal: NominalDeclStatement) Allocator.Error!void {
        try appendCheckedNominalDeclarationFromStatement(
            self.allocator,
            self.module,
            self.names,
            self.imports,
            self.store,
            self.active,
            self.local_type_declarations,
            statement_idx,
            nominal.header,
            nominal.anno,
            nominal.is_opaque,
        );
    }
};

/// The payload of a nominal declaration statement.
pub const NominalDeclStatement = @FieldType(CIR.Statement, "s_nominal_decl");

/// The source inputs that select a module's checked source type roots.
pub const CheckedSourceTypeRootInputs = struct {
    module_index: *const ModuleIndex,
    selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot,
    promoted_local_procedures: []const hoist_roots.PromotedLocalProcedure,
};

/// Every source type root of a module's checked source types, in
/// enumeration order. Type-root enumeration and the sealed type view
/// (`sealed_type_view.zig`) both enumerate roots here, so the two cannot
/// disagree on the root set. A visitor provides `visit(Var)`,
/// `visitRequired(?Var, comptime []const u8)` (as `output_type_roots`
/// visitors do), `visitScheme(Var)` for a root that owns a source scheme, and
/// `visitNominalDeclaration(CIR.Statement.Idx, NominalDeclStatement)` for a
/// local nominal declaration statement.
pub fn forEachCheckedSourceTypeRoot(
    module: TypedCIR.Module,
    inputs: CheckedSourceTypeRootInputs,
    visitor: anytype,
) Allocator.Error!void {
    const module_index = inputs.module_index;
    const module_env = module.moduleEnvConst();

    var node_idx: u32 = 0;
    while (node_idx < module.nodeCount()) : (node_idx += 1) {
        // Every reached expr/pattern node gets a published type root,
        // because the body reader reports each one's type. That includes
        // nodes checking rewrote to runtime errors (tag `.malformed`, e.g.
        // via ambiguity poisoning): their type vars are real, and the body
        // reader still reports them so the user-facing diagnostics survive
        // to reporting.
        switch (module_index.nodeKind(node_idx)) {
            .expr => {
                const expr_idx: CIR.Expr.Idx = @fromBackingInt(@intCast(node_idx));
                try visitor.visit(module.exprType(expr_idx));
                try output_type_roots.forEachCallTypeRoot(module_env, expr_idx, visitor);
            },
            .pattern => {
                const pattern_idx: CIR.Pattern.Idx = @fromBackingInt(@intCast(node_idx));
                try visitor.visit(if (module_index.topLevelDef(pattern_idx)) |def| module.defType(def) else module.patternType(pattern_idx));
            },
            .statement, .unreached => {},
        }
    }

    // Static-dispatch evidence resolves constrained scheme instantiations
    // after type-root enumeration. Publish each recorded fresh variable now so
    // evidence nodes can name the exact concrete dispatcher type by a
    // checked type id rather than retaining checker-only variables.
    // Explicit scheme requirements may be absent from the public callable.
    // Publish their roots before the evidence schema names them.
    try output_type_roots.forEachRecordedTypeRoot(module_env, visitor);
    for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        if (!module_index.reachesStatement(statement_idx)) continue;
        switch (module.getStatement(statement_idx)) {
            .s_alias_decl => try visitor.visit(ModuleEnv.varFrom(statement_idx)),
            .s_nominal_decl => |nominal| try visitor.visitNominalDeclaration(statement_idx, nominal),
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    }

    for (module.requiresTypes()) |required_type| {
        const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (aliases) |alias| {
            const alias_statement = module_env.store.getStatement(alias.alias_stmt_idx);
            if (alias_statement != .s_alias_decl) {
                checkedModuleInvariant("platform for-clause alias metadata referenced a non-alias statement", .{});
            }
            try visitor.visit(ModuleEnv.varFrom(alias.alias_stmt_idx));
            try visitor.visit(ModuleEnv.varFrom(alias_statement.s_alias_decl.anno));
        }
    }

    try forEachStaticDispatchTypeRoot(module, module_index, visitor);

    // The method registry names each method binding's callable type and a
    // `to_inspect` procedure's checker-recorded inspect instance. A binding
    // bound by reference names the binding's own type when it reaches
    // another module's structural declaration, and its inspect instance when
    // it reaches a procedure.
    const method_classes = try static_dispatch.classifyMethodBindings(module.allocator, module, module_index);
    defer module.allocator.free(method_classes);
    for (method_classes) |class| switch (class) {
        .unsupported, .associated_value, .rejected => {},
        .target => |target| {
            try visitor.visit(target.callable_var);
            if (target.inspect_instance) |instance| try visitor.visit(instance);
        },
        .referenced => |referenced| {
            try visitor.visit(referenced.binding_var);
            if (referenced.inspect_instance) |instance| try visitor.visit(instance);
        },
    };

    // Evidence nodes retain exact checked callable instantiations. Publish
    // every fresh type participating in a recorded scheme use, including
    // the constraint function that identifies a selected dispatch target
    // or a per-use where-method callable.
    try output_type_roots.forEachSchemeUseTypeRoot(module_env, visitor);

    // A row-coerced result's coercion node has its widening copy's type;
    // the expression's own node keeps its own type
    // (`ModuleEnv.RowCoercedResult`).
    for (module_env.row_coerced_results.items.items) |result| {
        try visitor.visit(@fromBackingInt(result.wide_var));
    }

    try forEachCheckedSourceScheme(module, inputs, visitor);

    // An app's solution of a platform requirement names the solved
    // requirement type and each requirement identity variable's solution.
    for (module_env.platform_requirement_solutions.items.items) |solution| {
        switch (solution.outcome) {
            .checked_error => continue,
            .success => {},
        }
        for (module_env.platformRequirementIdentityVars(solution)) |identity_var| try visitor.visit(identity_var);
        try visitor.visit(solution.solved_var);
    }
}

/// Every source scheme of a module's checked source types: each root
/// `forEachCheckedSourceTypeRoot` publishes with a scheme of its own. A visitor
/// provides `visitScheme(Var)`.
pub fn forEachCheckedSourceScheme(
    module: TypedCIR.Module,
    inputs: CheckedSourceTypeRootInputs,
    visitor: anytype,
) Allocator.Error!void {
    const module_env = module.moduleEnvConst();
    for (module.requiresTypes()) |required_type| {
        try visitor.visitScheme(ModuleEnv.varFrom(required_type.type_anno));
    }

    for (module_env.store.sliceDefs(module_env.global_value_defs)) |def_idx| {
        try visitor.visitScheme(module.defType(def_idx));
    }

    // Selected roots own source schemes just like ordinary top-level
    // values. Publish them explicitly so const and callable templates can
    // name the exact scheme without relying on an unrelated definition
    // having the same canonical key.
    for (inputs.selected_hoisted_roots) |selected| {
        try visitor.visitScheme(if (selected.pattern) |pattern|
            ModuleEnv.varFrom(pattern)
        else
            module.exprType(selected.expr));
    }

    // A promoted local function is a procedure of its own, published
    // under its binding's generalized scheme like a top-level function.
    for (inputs.promoted_local_procedures) |promoted| {
        try visitor.visitScheme(ModuleEnv.varFrom(promoted.pattern));
    }
}

/// Public `ModuleEnvStorage` declaration.
pub const ModuleEnvStorage = union(enum) {
    checked_source: *ModuleEnv,
    static_builtin: *ModuleEnv,
    /// An environment relocated in place inside a loaded cache entry, which
    /// also backs the checked module. The storage owns the entry and the
    /// source; `release_entry` releases the entry with the env's allocator.
    cached_entry: struct {
        env: *ModuleEnv,
        entry: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
        release_entry: *const fn ([]align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8, Allocator) void,
        source: []const u8,
    },

    pub fn env(self: *const ModuleEnvStorage) *ModuleEnv {
        return switch (self.*) {
            .checked_source => |module_env| module_env,
            .static_builtin => |module_env| module_env,
            .cached_entry => |cached| cached.env,
        };
    }

    pub fn envConst(self: *const ModuleEnvStorage) *const ModuleEnv {
        return self.env();
    }

    pub fn deinit(self: *ModuleEnvStorage) void {
        switch (self.*) {
            .checked_source => |module_env| {
                const env_alloc = module_env.gpa;
                const source = module_env.common.source;
                module_env.deinit();
                if (source.len > 0) env_alloc.free(@constCast(source));
                env_alloc.destroy(module_env);
            },
            .static_builtin => |module_env| {
                module_env.common.idents.deinitTextRanks();
                module_env.gpa.destroy(module_env);
            },
            .cached_entry => |cached| {
                const env_alloc = cached.env.gpa;
                cached.env.deinitCachedModule();
                if (cached.source.len > 0) env_alloc.free(@constCast(cached.source));
                env_alloc.destroy(cached.env);
                cached.release_entry(cached.entry, env_alloc);
            },
        }
        self.* = undefined;
    }
};

/// Public `CheckedModuleKey` declaration: the checked module's
/// identity hash and nothing else, so its bits are its identity and every
/// keyed container agrees with `eql`. The hash inputs live on the module
/// (`CheckedModule.source_hash`, `module_identity`,
/// `checking_context_identity`, `direct_import_module_keys`). `extern` so it
/// can be a POD inline field of `CheckedModule.Serialized`.
pub const CheckedModuleKey = extern struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    /// Integer equality over the key's identity bytes: a single 256-bit
    /// compare, never a byte-wise comparison.
    pub fn eql(a: CheckedModuleKey, b: CheckedModuleKey) bool {
        return @as(u256, @bitCast(a.bytes)) == @as(u256, @bitCast(b.bytes));
    }

    /// The digest that references to this module carry. The constituent
    /// hashes live once, on the module's own key.
    pub fn digest(self: CheckedModuleKey) CheckedModuleDigest {
        return .{ .bytes = self.bytes };
    }

    pub fn compute(
        source: []const u8,
        module_identity: ModuleIdentity,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleKey,
    ) CheckedModuleKey {
        return computeFromSourceHash(
            hashBytes(source),
            module_identity,
            checking_context_identity,
            direct_import_module_keys,
        );
    }

    pub fn computeFromSourceHash(
        source_hash: [32]u8,
        module_identity: ModuleIdentity,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleKey,
    ) CheckedModuleKey {
        return computeFromIdentityHash(source_hash, hashModuleIdentity(module_identity), checking_context_identity, direct_import_module_keys);
    }

    pub fn computeFromIdentityHash(
        source_hash: [32]u8,
        module_identity_hash: [32]u8,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleKey,
    ) CheckedModuleKey {
        return .{ .bytes = computeCheckedModuleKeyBytes(
            source_hash,
            module_identity_hash,
            hashCheckingContextIdentity(checking_context_identity),
            hashDirectImportModuleKeys(direct_import_module_keys),
        ) };
    }
};

/// Stable identifier for a checked module: its module's identity digest.
pub const ModuleId = CheckedModuleDigest;

fn computeCheckedModuleKeyBytes(
    source_hash: [32]u8,
    module_identity_hash: [32]u8,
    checking_context_identity_hash: [32]u8,
    direct_import_module_keys_hash: [32]u8,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update(&source_hash);
    hasher.update(&module_identity_hash);
    hasher.update(&checking_context_identity_hash);
    hasher.update(&direct_import_module_keys_hash);
    return hasher.finalResult();
}

test "checked module key is a function of the program alone" {
    const source_hash = @as([32]u8, @splat(1));
    const module_identity_hash = @as([32]u8, @splat(2));
    const import_key = CheckedModuleKey{ .bytes = @as([32]u8, @splat(3)) };
    const checking_context = CheckingContextIdentity{};

    var expected = base.Sha256.init(.{});
    expected.update(&source_hash);
    expected.update(&module_identity_hash);
    expected.update(&hashCheckingContextIdentity(checking_context));
    expected.update(&hashDirectImportModuleKeys(&.{import_key}));

    const key = CheckedModuleKey.computeFromIdentityHash(
        source_hash,
        module_identity_hash,
        checking_context,
        &.{import_key},
    );
    try std.testing.expectEqualSlices(u8, &expected.finalResult(), &key.bytes);
}

/// Public `ModuleIdentity` declaration.
pub const ModuleIdentity = struct {
    stable_hash: [32]u8 = @as([32]u8, @splat(0)),
    module_idx: u32,
    module_name: canonical.ModuleNameId,
    display_module_name: canonical.ModuleNameId,
    kind: ModuleEnv.ModuleKind,
};

/// Public `ImportIdentity` declaration.
pub const ImportIdentity = struct {
    import_name_hash: [32]u8 = @as([32]u8, @splat(0)),
    module_key: ?CheckedModuleKey = null,
};

fn hashBytes(bytes: []const u8) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update(bytes);
    return hasher.finalResult();
}

fn hashU32(hasher: anytype, value: u32) void {
    hasher.update(&.{
        @as(u8, @truncate(value)),
        @as(u8, @truncate(value >> 8)),
        @as(u8, @truncate(value >> 16)),
        @as(u8, @truncate(value >> 24)),
    });
}

fn hashByteSlice(hasher: anytype, bytes: []const u8) void {
    hashU32(hasher, @intCast(bytes.len));
    hasher.update(bytes);
}

fn hashModuleSourceInputs(module_env: *const ModuleEnv) [32]u8 {
    const deps = module_env.file_dependencies.items.items;
    if (deps.len == 0) {
        return hashBytes(module_env.getSourceAll());
    }

    var hasher = base.Sha256.init(.{});
    hashByteSlice(&hasher, "roc-module-source-inputs-v2");
    hashByteSlice(&hasher, module_env.getSourceAll());
    hashU32(&hasher, @intCast(deps.len));
    for (deps) |dep| {
        hashByteSlice(&hasher, module_env.fileDependencyRelativePath(dep));
        hasher.update(&.{@backingInt(dep.state)});
        switch (dep.state) {
            .present => hasher.update(&dep.content_hash),
            .missing, .unreadable => {},
            .pending => unreachable, // the canonicalize task settles every file dependency before source inputs are hashed
        }
    }
    return hasher.finalResult();
}

fn hashModuleIdentity(identity: ModuleIdentity) [32]u8 {
    return identity.stable_hash;
}

/// A module's identity hash IS its deep content identity: a pure function of
/// the transitive closure's module names and source bytes (see
/// `base.module_identity`). No coordinator-assigned display strings, package
/// names, or paths participate—cache keys and serialized identities are
/// bit-identical no matter which pipeline built the module or what
/// directory the build ran in.
fn computeStableModuleIdentityHash(module_env: *const ModuleEnv) [32]u8 {
    const hash = module_env.contentIdentityHash() orelse {
        base.invariant(
            "checked module identity requested before module content identity was finalized for module '{s}'",
            .{module_env.module_name},
        );
    };
    return hash.*;
}

fn hashCheckingContextIdentity(identity: CheckingContextIdentity) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashCheckingContextPolicy(&hasher, identity, true);
    return hasher.finalResult();
}

/// The digest of the checking inputs of a module that its imports' and its
/// app pairing's implementations do not reach: its imports' names and
/// platform requirement context.
pub fn checkingContextPolicyHash(identity: CheckingContextIdentity) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashCheckingContextPolicy(&hasher, identity, false);
    return hasher.finalResult();
}

fn hashCheckingContextPolicy(hasher: *base.Sha256, identity: CheckingContextIdentity, include_keys: bool) void {
    if (identity.platform_requirement_context) |context| {
        hasher.update(&[_]u8{1});
        hasher.update(&context.bytes);
    } else {
        hasher.update(&[_]u8{0});
    }
    if (include_keys) {
        if (identity.platform_app_relation) |relation| {
            hasher.update(&[_]u8{1});
            hasher.update(&relation.bytes);
        } else {
            hasher.update(&[_]u8{0});
        }
    }
    hashU32(hasher, @intCast(identity.imports.len));
    for (identity.imports) |import_identity| {
        hasher.update(&import_identity.import_name_hash);
        if (!include_keys) continue;
        if (import_identity.module_key) |key| {
            hasher.update(&[_]u8{1});
            hasher.update(&key.bytes);
        } else {
            hasher.update(&[_]u8{0});
        }
    }
}

fn hashDirectImportModuleKeys(keys: []const CheckedModuleKey) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashU32(&hasher, @intCast(keys.len));
    for (keys) |key| hasher.update(&key.bytes);
    return hasher.finalResult();
}

/// Public `PlatformRequirementContextKey` declaration.
pub const PlatformRequirementContextKey = struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    pub fn compute(
        platform_identity: ModuleIdentity,
        platform_required_declarations_hash: [32]u8,
    ) PlatformRequirementContextKey {
        return computeFromParts(
            hashModuleIdentity(platform_identity),
            platform_required_declarations_hash,
        );
    }

    /// Compute the requirement context directly from the platform module's stable
    /// content-identity hash and the identity hash of its required declarations.
    /// `compute` folds these same two inputs through a `ModuleIdentity`, so the two
    /// entry points always agree byte-for-byte.
    pub fn computeFromParts(
        platform_content_identity_hash: [32]u8,
        platform_required_declarations_hash: [32]u8,
    ) PlatformRequirementContextKey {
        var hasher = base.Sha256.init(.{});
        hasher.update(&platform_content_identity_hash);
        hasher.update(&platform_required_declarations_hash);
        return .{ .bytes = hasher.finalResult() };
    }
};

/// Public `CheckingContextIdentity` declaration.
pub const CheckingContextIdentity = struct {
    imports: []ImportIdentity = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
    platform_app_relation: ?PlatformAppRelationKey = null,

    pub fn fromModule(
        allocator: Allocator,
        module_env: *const ModuleEnv,
        checked_imports: []const CheckedImport,
        platform_requirement_context: ?PlatformRequirementContextKey,
    ) Allocator.Error!CheckingContextIdentity {
        const imported_names = module_env.imports.imports.items.items;
        const imports = try allocator.alloc(ImportIdentity, imported_names.len);
        errdefer allocator.free(imports);

        for (imported_names, 0..) |str_idx, i| {
            const import_idx: CIR.Import.Idx = @fromBackingInt(@intCast(@as(u32, @intCast(i))));
            const resolved_module_idx = module_env.imports.getResolvedModule(import_idx);
            imports[i] = .{
                .import_name_hash = hashBytes(module_env.getString(str_idx)),
                .module_key = if (resolved_module_idx) |resolved|
                    checkedImportKeyForModule(checked_imports, resolved)
                else
                    null,
            };
        }

        return .{
            .imports = imports,
            .platform_requirement_context = platform_requirement_context,
        };
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `CheckedImport` declaration.
pub const CheckedImport = struct {
    module_idx: u32,
    key: CheckedModuleKey,
    view: ImportedModuleView,
};

/// The checked modules a module resolves named types against when it is opened.
pub const CheckedImportViews = struct {
    current_owner: ModuleId,
    direct: []const CheckedImport,
    available: []const ImportedModuleView = &.{},
    /// Platform relation modules: registry-visible for dispatch resolution
    /// even though they are neither imported nor in `available`.
    relations: []const ImportedModuleView = &.{},

    fn viewForKey(self: CheckedImportViews, key: ModuleId) ?ImportedModuleView {
        const view = dependencyViewByKey(key, self.direct, self.available, self.relations) orelse return null;
        return view.*;
    }

    /// A resolver over these views.
    pub fn resolver(self: *const CheckedImportViews) ModuleResolver {
        return .{ .context = self, .resolve_fn = resolveImportView };
    }

    fn resolveImportView(context: *const anyopaque, key: ModuleId) ?ImportedModuleView {
        const self: *const CheckedImportViews = @ptrCast(@alignCast(context));
        return self.viewForKey(key);
    }
};

/// Finds the checked module a module id names, for an analysis that reads
/// modules other than its own. A resolver resolves every module of the build.
pub const ModuleResolver = struct {
    context: *const anyopaque,
    resolve_fn: *const fn (context: *const anyopaque, key: ModuleId) ?ImportedModuleView,

    pub fn resolve(self: ModuleResolver, key: ModuleId) ?ImportedModuleView {
        return self.resolve_fn(self.context, key);
    }

    /// The module `key` names, which the resolver must resolve.
    fn require(self: ModuleResolver, key: ModuleId) ImportedModuleView {
        return self.resolve(key) orelse checkedModuleInvariant("a module analysis named a module its resolver does not resolve", .{});
    }
};

/// Checked modules that must be available to consume this module's public API.
/// This is semantic visibility, not lexical import visibility. A per-module
/// analysis (`ModuleAnalyses.publicApiDependencies`).
pub const PublicApiDependencies = struct {
    modules: []const ModuleId = &.{},
    type_owner_modules: []const ModuleId = &.{},

    pub fn deinit(self: *PublicApiDependencies, allocator: Allocator) void {
        allocator.free(self.modules);
        allocator.free(self.type_owner_modules);
        self.* = .{};
    }
};

/// Checked modules that must be materialized for post-check lowering of this
/// module's roots. A per-module analysis (`ModuleAnalyses.loweringVisibility`).
pub const LoweringVisibility = struct {
    module_ids: []const ModuleId = &.{},

    pub fn deinit(self: *LoweringVisibility, allocator: Allocator) void {
        allocator.free(self.module_ids);
        self.* = .{};
    }
};

/// The import views method-target lookup searches after the local registry:
/// the module's dispatch imports (`ModuleAnalyses.dispatchImports`), in their
/// order.
fn methodLookupViews(allocator: Allocator, views: []const ImportedModuleView) Allocator.Error![]const *const ImportedModuleView {
    const result = try allocator.alloc(*const ImportedModuleView, views.len);
    for (views, result) |*view, *entry| entry.* = view;
    return result;
}

/// The modules a module's dispatch resolution searches for method targets and
/// procedure schemes and resolves the types it reads in: every module its
/// direct imports and the owners of its types' names reach, transitively,
/// through those modules' own direct imports and type-name owners, which
/// `resolver` resolves. The module itself is not one. The order is the walk's
/// first-reach order from the module's direct imports, then its type-name
/// owners, so it is a function of the modules' checked data alone. A module
/// that reads no other module needs no resolver.
pub fn computeDispatchImports(
    allocator: Allocator,
    module: ModuleId,
    direct_imports: []const CheckedModuleKey,
    origins: []const sealed_type_view.SealedOriginRow,
    resolver: ?ModuleResolver,
) Allocator.Error![]ImportedModuleView {
    var reached = std.AutoHashMap([32]u8, void).init(allocator);
    defer reached.deinit();
    try reached.put(module.bytes, {});
    var order = std.ArrayList(ModuleId).empty;
    defer order.deinit(allocator);
    try appendDispatchImportKeys(allocator, &reached, &order, direct_imports, origins);
    var views = std.ArrayList(ImportedModuleView).empty;
    errdefer views.deinit(allocator);
    var next: usize = 0;
    while (next < order.items.len) : (next += 1) {
        const view = (resolver orelse checkedModuleInvariant("a module that reads other modules was given no resolver", .{})).require(order.items[next]);
        try views.append(allocator, view);
        const view_origins: []const sealed_type_view.SealedOriginRow = if (view.checked_types.sealed) |sealed| sealed.origins else &.{};
        try appendDispatchImportKeys(allocator, &reached, &order, view.direct_import_module_keys, view_origins);
    }
    return try views.toOwnedSlice(allocator);
}

fn appendDispatchImportKeys(
    allocator: Allocator,
    reached: *std.AutoHashMap([32]u8, void),
    order: *std.ArrayList(ModuleId),
    direct_imports: []const CheckedModuleKey,
    origins: []const sealed_type_view.SealedOriginRow,
) Allocator.Error!void {
    for (direct_imports) |key| {
        const id = key.digest();
        if ((try reached.getOrPut(id.bytes)).found_existing) continue;
        try order.append(allocator, id);
    }
    for (origins) |origin| {
        if (origin.has_owner == 0) continue;
        if ((try reached.getOrPut(origin.owner.bytes)).found_existing) continue;
        try order.append(allocator, origin.owner);
    }
}

/// What opening a checked module (`openCheckedModule`) reads beside its
/// `ModuleEnv`.
pub const OpenInputs = struct {
    module_env_storage: ModuleEnvStorage,
    /// The module's index in the module set it was checked in.
    module_idx: u32,
    /// Waits on the module's key slots when another thread is computing a key.
    io: std.Io,
    imports: []const CheckedImport = &.{},
    available_modules: []const ImportedModuleView = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
    explicit_roots: []const ExplicitRootRequestInput = &.{},
    /// The modules the module's analyses resolve. Null resolves exactly
    /// `imports` and `available_modules`.
    resolver: ?ModuleResolver = null,
    outputs: Outputs,

    /// Where the module's inference and evaluation outputs come from.
    pub const Outputs = union(enum) {
        /// Checking just completed: the module keeps a copy of this
        /// inference output, and its evaluation output starts with an entry
        /// awaiting evaluation for every compile-time root and constant
        /// template (`evaluateOpenedModule` evaluates them).
        checked: InferenceOutput,
        /// A cache entry or the baked Builtin blob: both outputs alias
        /// `backing`, which starts with their `Serialized` form. The module
        /// owns `backing` unless it is borrowed: static data, or a cache
        /// entry the module's environment storage owns.
        stored: struct {
            backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
            backing_borrowed: bool,
        },
    };
};

/// Public `CompileTimeFinalizer` declaration.
pub const CompileTimeFinalizer = struct {
    pub const Error = Allocator.Error || std.Thread.SpawnError || error{
        RuntimeError,
        /// The embedder abandoned the compilation (see `Options.cancel_request`
        /// in compile-time finalization).
        Canceled,
        EmptyCode,
        MmapFailed,
        MprotectFailed,
        UnsupportedPlatform,
        UnwindRegistrationFailed,
        VirtualAllocFailed,
        VirtualProtectFailed,
    };

    context: ?*anyopaque = null,
    finalize: *const fn (
        context: ?*anyopaque,
        allocator: Allocator,
        module: *CheckedModule,
        imports: []const CheckedImport,
        available_modules: []const ImportedModuleView,
        relation_modules: []const ImportedModuleView,
        problem_store: ?*problem.Store,
    ) Error!void,

    pub fn run(
        self: CompileTimeFinalizer,
        allocator: Allocator,
        checked: *CheckedModule,
        imports: []const CheckedImport,
        available_modules: []const ImportedModuleView,
        relation_modules: []const ImportedModuleView,
        problem_store: ?*problem.Store,
    ) Error!void {
        try self.finalize(self.context, allocator, checked, imports, available_modules, relation_modules, problem_store);
    }
};

/// Public `ExplicitRootRequestInput` declaration.
pub const ExplicitRootRequestInput = struct {
    kind: RootRequestKind,
    source: RootSource,
    abi: RootAbi,
    exposure: RootExposure,
};

/// A module's export rows (`ModuleAnalyses.exportRows`): the definitions it
/// exports, in export order, and the procedure templates, procedure bindings
/// and constant templates those definitions and the binders of its exposed
/// top-level destructures name. Export closures and platform relations index
/// the rows by their position.
pub const ExportRows = struct {
    defs: []const CIR.Def.Idx = &.{},
    procedure_templates: []const ExportedProcedureTemplate = &.{},
    /// Ordered by `binding.def`, which is unique per row
    /// (`computeExportRows`).
    procedure_bindings: []const ImportedProcedureBindingView = &.{},
    const_templates: []const ImportedConstTemplateView = &.{},

    /// The exported procedure binding of `def` with binding pattern
    /// `pattern`.
    pub fn procedureBinding(self: *const ExportRows, def: CIR.Def.Idx, pattern: CIR.Pattern.Idx) ?ImportedProcedureBindingView {
        const row = self.procedureBindingByDef(def) orelse return null;
        return if (row.binding.pattern == pattern) row else null;
    }

    /// The exported procedure binding of `def`.
    pub fn procedureBindingByDef(self: *const ExportRows, def: CIR.Def.Idx) ?ImportedProcedureBindingView {
        const found = store_serialize.binarySearchByKey(ImportedProcedureBindingView, CIR.Def.Idx, self.procedure_bindings, def, exportedBindingOrder) orelse return null;
        return found.*;
    }

    fn exportedBindingOrder(row: ImportedProcedureBindingView, def: CIR.Def.Idx) std.math.Order {
        return std.math.order(@backingInt(row.binding.def), @backingInt(def));
    }

    pub fn deinit(self: *ExportRows, allocator: Allocator) void {
        allocator.free(self.defs);
        allocator.free(self.procedure_templates);
        allocator.free(self.procedure_bindings);
        allocator.free(self.const_templates);
        self.* = .{};
    }
};

fn exportedBindingLessThan(_: void, lhs: ImportedProcedureBindingView, rhs: ImportedProcedureBindingView) bool {
    return @backingInt(lhs.binding.def) < @backingInt(rhs.binding.def);
}

/// The export rows of `owner`, read from its checked tables.
pub fn computeExportRows(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!*ExportRows {
    const env = owner.module_env;
    const module_idx = owner.module_identity.module_idx;
    const checked = owner.key.digest();
    const module_index = (try owner.bodies()).index();

    const defs = try collectExportDefs(allocator, env);
    errdefer allocator.free(defs);
    const binders = try collectExportBinders(allocator, env);
    defer allocator.free(binders);

    var procedure_templates = std.ArrayList(ExportedProcedureTemplate).empty;
    errdefer procedure_templates.deinit(allocator);
    for (defs) |def_idx| {
        const template = (try owner.checkedTables()).checked_procedure_templates.lookupByDef(def_idx) orelse continue;
        try procedure_templates.append(allocator, .{
            .def = def_idx,
            .source_scheme = sourceSchemeOfVar(env, ModuleEnv.varFrom(def_idx)),
            .template = template,
        });
    }

    // The callable-eval template of each selected hoisted callable root, by
    // the binder pattern it binds.
    var callable_by_pattern = collections.DenseMap(CIR.Pattern.Idx, CallableEvalTemplateId).init(allocator);
    defer callable_by_pattern.deinit();
    for ((try owner.checkedTables()).callable_eval_templates.view().templates) |template| try callable_by_pattern.put(template.pattern, template.id);

    var procedure_bindings = std.ArrayList(ImportedProcedureBindingView).empty;
    errdefer procedure_bindings.deinit(allocator);
    // A function bound by a top-level destructure is a promoted callable
    // root; its row is keyed by the binder node the importer reaches it
    // through.
    for (binders) |binder| {
        if (!module_index.reachesPattern(binder)) continue;
        const template_id = callable_by_pattern.get(binder) orelse continue;
        const template = (try owner.checkedTables()).callable_eval_templates.view().get(template_id);
        const resolution = env.bindingResolution(binder) orelse
            checkedModuleInvariant("an exported callable binder has no recorded resolution", .{});
        try procedure_bindings.append(allocator, .{
            .binding = .{
                .module = checked,
                .def = @fromBackingInt(@intCast(@backingInt(binder))),
                .pattern = binder,
            },
            .source_scheme = template.source_scheme,
            .body = switch (resolution.body) {
                .checked_error => |expr| .{ .checked_error = expr },
                .evaluated => .{ .callable_eval_template = template_id },
                .constant, .procedure => checkedModuleInvariant("an exported callable binder resolved to no evaluated value", .{}),
            },
            .intrinsic = null,
            .iterator_procedure = null,
            .runtime_result_provenance = null,
        });
    }
    for (defs) |def_idx| {
        const top_level = (try owner.checkedTables()).top_level_values.lookupByDef(def_idx) orelse continue;
        const binding_ref = switch (top_level.value) {
            .procedure_binding => |binding| binding,
            .const_ref => continue,
        };
        const binding = (try owner.checkedTables()).top_level_procedure_bindings.get(binding_ref);
        try procedure_bindings.append(allocator, .{
            .binding = .{
                .module = checked,
                .def = def_idx,
                .pattern = top_level.pattern,
            },
            .source_scheme = binding.source_scheme,
            .body = binding.body,
            .intrinsic = static_dispatch.intrinsicForEnvProcedureDef(env, def_idx),
            .iterator_procedure = static_dispatch.iteratorProcedureForEnvDef(env, def_idx),
            .runtime_result_provenance = runtimeResultProvenanceForEnvProcedureDef(env, def_idx),
        });
    }

    var const_templates = std.ArrayList(ImportedConstTemplateView).empty;
    errdefer const_templates.deinit(allocator);
    // A value bound by a top-level destructure is a hoisted extraction
    // root; its row is keyed by the binder node the importer reaches it
    // through.
    for (binders) |binder| {
        if (!module_index.reachesPattern(binder)) continue;
        const entry = (try owner.checkedTables()).hoisted_constants.lookupByPattern(binder) orelse continue;
        try const_templates.append(allocator, .{
            .module_idx = module_idx,
            .def = @fromBackingInt(@intCast(@backingInt(binder))),
            .pattern = binder,
            .const_ref = entry.const_ref,
            .source_scheme = entry.source_scheme,
            .template = (try owner.checkedTables()).const_templates.get(entry.const_ref),
        });
    }
    for (defs) |def_idx| {
        const top_level = (try owner.checkedTables()).top_level_values.lookupByDef(def_idx) orelse continue;
        const const_ref = switch (top_level.value) {
            .const_ref => |ref| ref,
            .procedure_binding => continue,
        };
        try const_templates.append(allocator, .{
            .module_idx = module_idx,
            .def = def_idx,
            .pattern = top_level.pattern,
            .const_ref = const_ref,
            .source_scheme = top_level.source_scheme,
            .template = (try owner.checkedTables()).const_templates.get(const_ref),
        });
    }

    // Rows are keyed by definition: a top-level destructure's row by its
    // binder node and every other row by its definition node, so no two
    // rows share one.
    std.mem.sort(ImportedProcedureBindingView, procedure_bindings.items, {}, exportedBindingLessThan);
    if (std.debug.runtime_safety) {
        for (procedure_bindings.items[0..procedure_bindings.items.len -| 1], procedure_bindings.items[@min(1, procedure_bindings.items.len)..]) |previous, next| {
            if (@backingInt(previous.binding.def) == @backingInt(next.binding.def)) {
                checkedModuleInvariant("two exported procedure bindings share definition {d}", .{@backingInt(next.binding.def)});
            }
        }
    }

    const result = try allocator.create(ExportRows);
    errdefer allocator.destroy(result);
    const templates_slice = try procedure_templates.toOwnedSlice(allocator);
    errdefer allocator.free(templates_slice);
    const bindings_slice = try procedure_bindings.toOwnedSlice(allocator);
    errdefer allocator.free(bindings_slice);
    result.* = .{
        .defs = defs,
        .procedure_templates = templates_slice,
        .procedure_bindings = bindings_slice,
        .const_templates = try const_templates.toOwnedSlice(allocator),
    };
    return result;
}

/// The source scheme a source variable owns: the scheme of its checked
/// representative.
fn sourceSchemeOfVar(env: *const ModuleEnv, var_: Var) CheckedTypeSchemeId {
    return @fromBackingInt(@backingInt(type_ids.fromVar(env.types.resolveVar(var_).var_)));
}

/// Public `ProvidedProcedureExport` declaration.
pub const ProvidedProcedureExport = struct {
    source_name: canonical.ExportNameId,
    ffi_symbol: canonical.ExternalSymbolNameId,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
    source_scheme: CheckedTypeSchemeId,
    binding: TopLevelProcedureBindingRef,
};

/// Public `ProvidedDataExport` declaration.
pub const ProvidedDataExport = struct {
    source_name: canonical.ExportNameId,
    ffi_symbol: canonical.ExternalSymbolNameId,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
    source_scheme: CheckedTypeSchemeId,
    const_ref: ConstRef,
