/// Finalize checker-only function-kind state for post-check source type identity.
pub fn finalizedFunctionKind(kind: CheckedFunctionKind) CheckedFunctionKind {
    return switch (kind) {
        .pure, .unbound => .pure,
        .effectful => .effectful,
