/// Public `CheckedAliasType` declaration.
pub const CheckedAliasType = CheckedAliasTypeOf(*const ModuleId);

/// The build form of `CheckedAliasType`, which owns its owner module id.
pub const CheckedAliasTypeBuild = CheckedAliasTypeOf(ModuleId);

fn CheckedAliasTypeOf(comptime OwnerModule: type) type {
    return struct {
        const Self = @This();

        name: canonical.TypeNameId,
        /// Deep content identity of the declaring module (dense id into this
        /// module's `canonical_names.module_identities`).
        origin_module: canonical.ModuleIdentityId,
        /// Checked module id of the module that owns this named type's
        /// checked declaration data. This is intentionally separate from
        /// `origin_module`. A read form aliases the stored id, like its
        /// slice fields alias pools; a build form owns it.
        owner_module: OwnerModule,
        source_decl: ?u32 = null,
        builtin_origin: bool = false,
        backing: CheckedTypeId,
        args: []const CheckedTypeId = &.{},

        /// A build form holding this read form's fields.
        pub fn toBuild(self: Self) CheckedAliasTypeBuild {
            return .{
                .name = self.name,
                .origin_module = self.origin_module,
                .owner_module = self.owner_module.*,
                .source_decl = self.source_decl,
                .builtin_origin = self.builtin_origin,
                .backing = self.backing,
                .args = self.args,
            };
        }
    };
}

/// Public `CheckedNominalDeclarationId` declaration.
pub const CheckedNominalDeclarationId = enum(u32) { _ };

/// Public `ImportedNominalDeclarationRef` declaration.
pub const ImportedNominalDeclarationRef = struct {
    module: CheckedModuleDigest,
    declaration: CheckedNominalDeclarationId,
};

/// The box payload capability a local nominal type reads with: the
/// capability of its instance in its module's interface capabilities.
pub const LocalBoxPayloadCapabilityRef = struct {
    capability: BoxPayloadCapabilityId,
};

/// Return the checked module id that owns an imported nominal declaration.
pub fn importedNominalDeclarationModuleId(ref: ImportedNominalDeclarationRef) ModuleId {
    return ref.module;
}

/// How a nominal type is represented, a function of the type alone: a
/// builtin by its builtin, a nominal another module declares by that
/// declaration, and a nominal its own module declares by that declaration
/// as the store holds it and by its instance's box payload capability as a
/// view reads it once the module's interface capabilities were demanded
/// (`CheckedTypeStoreView.payload`).
pub const CheckedNominalRepresentationRef = union(enum) {
    builtin: CheckedBuiltinNominal,
    local_declaration: CheckedNominalDeclarationId,
    imported_declaration: ImportedNominalDeclarationRef,
    local_box_payload_capability: LocalBoxPayloadCapabilityRef,
    opaque_without_backing,
};

/// Public `CheckedNominalType` declaration.
pub const CheckedNominalType = CheckedNominalTypeOf(*const ModuleId);

/// The build form of `CheckedNominalType`, which owns its owner module id.
pub const CheckedNominalTypeBuild = CheckedNominalTypeOf(ModuleId);

fn CheckedNominalTypeOf(comptime OwnerModule: type) type {
    return struct {
        const Self = @This();

        name: canonical.TypeNameId,
        /// Deep content identity of the declaring module (dense id into this
        /// module's `canonical_names.module_identities`).
        origin_module: canonical.ModuleIdentityId,
        /// Checked module id of the module that owns this named type's
        /// checked declaration data. This is intentionally separate from
        /// `origin_module`. A read form aliases the stored id, like its
        /// slice fields alias pools; a build form owns it.
        owner_module: OwnerModule,
        source_decl: u32,
        builtin: ?CheckedBuiltinNominal = null,
        is_opaque: bool,
        representation: CheckedNominalRepresentationRef,
        args: []const CheckedTypeId = &.{},
        /// Resolved types of the declaration's unnamed (`_` / `_name`)
        /// fields, in declared order. These are layout padding, excluded from
        /// the backing row; layout selection reserves `sizeof` of each. Empty
        /// for the common case of a nominal with no unnamed fields.
        padding_field_types: []const CheckedTypeId = &.{},
        /// Source-declared field order for nominal record layout. Empty for
        /// non-record nominal backings and for builtin nominals.
        declared_fields: []const CheckedDeclaredField = &.{},

        /// A build form holding this read form's fields.
        pub fn toBuild(self: Self) CheckedNominalTypeBuild {
            return .{
                .name = self.name,
                .origin_module = self.origin_module,
                .owner_module = self.owner_module.*,
                .source_decl = self.source_decl,
                .builtin = self.builtin,
                .is_opaque = self.is_opaque,
                .representation = self.representation,
                .args = self.args,
                .padding_field_types = self.padding_field_types,
                .declared_fields = self.declared_fields,
            };
        }
    };
}

fn checkedNominalTypeKey(nominal: CheckedNominalType) canonical.NominalTypeKey {
    return .{
        .module = nominal.origin_module,
        .source_decl = nominal.source_decl,
    };
}

/// A nominal type's declaration, read in the module that declares it.
pub const NominalDeclarationSite = struct {
    /// The declaring module.
    module: ModuleId,
    /// The declaring module's types, which the declaration's ids name.
    types: CheckedTypeStoreView,
    declaration: CheckedNominalDeclaration,
};

/// The declaration of `nominal`, a type of `reader` (the types of module
/// `reader_module`), read from the module its representation names, which
/// `resolver` resolves; null for a nominal with no declaration backing. A
/// box payload capability is read from its module's interface capabilities,
/// which a reader that meets one has demanded.
pub fn nominalDeclarationSite(
    reader_module: ModuleId,
    reader: CheckedTypeStoreView,
    resolver: ModuleResolver,
    nominal: CheckedNominalType,
) ?NominalDeclarationSite {
    switch (nominal.representation) {
        .opaque_without_backing => return null,
        .builtin => |builtin_nominal| {
            if (!builtinNominalHasDeclarationBacking(builtin_nominal)) return null;
            const module = nominal.owner_module.*;
            const module_types = moduleTypesForSite(reader_module, reader, resolver, module);
            const declaration = module_types.builtinNominalDeclaration(builtin_nominal) orelse
                checkedModuleInvariant("a builtin nominal's owner has no declaration for it", .{});
            return .{ .module = module, .types = module_types, .declaration = declaration };
        },
        .local_declaration => |declaration| return .{
            .module = reader_module,
            .types = reader,
            .declaration = reader.nominalDeclarationById(declaration),
        },
        .imported_declaration => |imported| {
            const module_types = moduleTypesForSite(reader_module, reader, resolver, imported.module);
            return .{ .module = imported.module, .types = module_types, .declaration = module_types.nominalDeclarationById(imported.declaration) };
        },
        .local_box_payload_capability => |capability_ref| {
            const capability = reader.demandedInterfaceCapabilities().boxPayloadCapability(capability_ref.capability);
            return .{ .module = reader_module, .types = reader, .declaration = reader.nominalDeclarationById(capability.declaration) };
        },
    }
}

fn moduleTypesForSite(reader_module: ModuleId, reader: CheckedTypeStoreView, resolver: ModuleResolver, module: ModuleId) CheckedTypeStoreView {
    if (module.eql(reader_module)) return reader;
    return resolver.require(module).checked_types;
}

/// The modules a walk over checked types has entered, by dense index, each
/// read through its own types. Index 0 is the module the walk starts in.
const WalkModules = struct {
    resolver: ModuleResolver,
    entries: std.ArrayListUnmanaged(Entry) = .empty,

    const Entry = struct { module: ModuleId, types: CheckedTypeStoreView };

    fn init(allocator: Allocator, module: ModuleId, module_types: CheckedTypeStoreView, resolver: ModuleResolver) Allocator.Error!WalkModules {
        var result = WalkModules{ .resolver = resolver };
        try result.entries.append(allocator, .{ .module = module, .types = module_types });
        return result;
    }

    fn deinit(self: *WalkModules, allocator: Allocator) void {
        self.entries.deinit(allocator);
    }

    fn typesOf(self: *const WalkModules, index: u32) CheckedTypeStoreView {
        return self.entries.items[index].types;
    }

    /// The declaring module (its walk index) and declaration of `nominal`,
    /// a type of module `index`.
    fn declaration(self: *WalkModules, allocator: Allocator, index: u32, nominal: CheckedNominalType) Allocator.Error!?struct { module: u32, declaration: CheckedNominalDeclaration } {
        const entry = self.entries.items[index];
        const site = nominalDeclarationSite(entry.module, entry.types, self.resolver, nominal) orelse return null;
        const module: u32 = for (self.entries.items, 0..) |existing, existing_index| {
            if (existing.module.eql(site.module)) break @intCast(existing_index);
        } else blk: {
            try self.entries.append(allocator, .{ .module = site.module, .types = site.types });
            break :blk @intCast(self.entries.items.len - 1);
        };
        return .{ .module = module, .declaration = site.declaration };
    }

    /// A key naming type `ty` of module `index`.
    fn key(index: u32, ty: CheckedTypeId) u64 {
        return (@as(u64, index) << 32) | @backingInt(ty);
    }
};

/// Whether the builtin's representation comes from its checked Roc declaration.
pub fn builtinNominalHasDeclarationBacking(builtin_nominal: CheckedBuiltinNominal) bool {
    return switch (builtinRuntimeEncoding(builtin_nominal)) {
        .primitive,
        .list,
        .box,
        .parse_tag_union_spec,
        .fields,
        .field,
        => false,
        .dict,
        .set,
        .bool_tag_union,
        .try_nominal,
        .iterator,
        .crypto_sha256_digest,
        .crypto_sha256_hasher,
        .crypto_blake3_digest,
        .crypto_blake3_hasher,
        => true,
    };
}

test "checked nominal payloads do not carry instantiated backing roots" {
    try std.testing.expect(!@hasField(CheckedNominalType, "backing"));
    try std.testing.expect(!@hasField(StoredNominal, "backing"));
}

/// Public `CheckedTypePayload` declaration (read form).
///
/// Reconstructed on demand by `CheckedTypeStore.payload`/`CheckedTypeStoreView.payload`;
/// every slice field aliases the store's pools. The internal stored form is
/// `StoredCheckedTypePayload` (POD ranges into the pools).
pub const CheckedTypePayload = union(enum) {
    pending,
    err,
    flex: CheckedTypeVariable,
    rigid: CheckedTypeVariable,
    alias: CheckedAliasType,
    record: CheckedRecordType,
    tuple: []const CheckedTypeId,
    nominal: CheckedNominalType,
    function: CheckedFunctionType,
    empty_record,
    tag_union: CheckedTagUnionType,
    empty_tag_union,
    /// The field kind a quantified kind variable was instantiated at
    /// (design.md "Field Kinds"): a substitution entry, never part of a type.
    field_kind: CheckedCommittedKind,

    /// Whether this variable payload stands for no specialization input of
    /// its own: an unconstrained flex row tail carrying a row default and no
    /// numeric default, which lowering seals to that default
    /// (`lowerCheckedTypeVariable`). A rigid, an undefaulted flex, a
    /// numeric-defaulting flex, and a constrained flex each stand for one.
    /// This is the variable half of the `direct_closed` rule (design.md
    /// "Static Dispatch In Monotype"), shared by the checked module's
    /// classification and Monotype's sealed-cell guard so the two cannot
    /// drift; whether an enclosing scheme quantifies the variable is the
    /// classification's own question. Ask only at `.flex` or `.rigid`.
    pub fn variableSealsToRowDefault(self: CheckedTypePayload) bool {
        return switch (self) {
            .flex => |variable| (variable.constraints.len() == 0 or variable.row_default_discharges_constraints) and
                variable.numeric_default_phase == null and
                variable.row_default != null,
            .rigid => false,
            .pending,
            .field_kind,
            .err,
            .alias,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => checkedModuleInvariant("row-default sealing was asked of a non-variable checked type", .{}),
        };
    }
};

/// Build form of `CheckedTypePayload`: slice fields carry individually-allocated
/// memory and `tag_union` carries build-form tags. Builders construct this; the
/// store's commit path copies it into the pools (freeing the build memory).
pub const CheckedTypePayloadBuild = union(enum) {
    pending,
    err,
    flex: CheckedTypeVariableBuild,
    rigid: CheckedTypeVariableBuild,
    alias: CheckedAliasTypeBuild,
    record: CheckedRecordTypeBuild,
    tuple: []const CheckedTypeId,
    nominal: CheckedNominalTypeBuild,
    function: CheckedFunctionType,
    empty_record,
    tag_union: CheckedTagUnionTypeBuild,
    empty_tag_union,
    field_kind: CheckedCommittedKind,
};

/// POD form of `CheckedTypeVariable`: `name` is an optional `var_names`
