pub const StoredNominal = struct {
    name: canonical.TypeNameId,
    origin_module: canonical.ModuleIdentityId,
    owner_module: ModuleId,
    source_decl: u32,
    builtin: ?CheckedBuiltinNominal = null,
    is_opaque: bool,
    representation: CheckedNominalRepresentationRef,
    args: CheckedTypeRange = .{},
    padding_field_types: CheckedTypeRange = .{},
    declared_fields: CheckedTypeRange = .{},
};

/// POD form of `CheckedRecordType`: `fields` is a range into `record_field_pool`.
pub const StoredRecord = struct {
    fields: CheckedTypeRange = .{},
    ext: CheckedTypeId,
};

/// POD form of `CheckedFunctionType`: `args` is a range into `type_id_pool`.
pub const StoredFunction = struct {
    kind: CheckedFunctionKind,
    args: CheckedTypeRange = .{},
    ret: CheckedTypeId,
};

/// POD form of `CheckedTagUnionType`: `tags` is a range into `tag_pool`.
pub const StoredTagUnion = struct {
    tags: CheckedTypeRange = .{},
    ext: CheckedTypeId,
};

/// Internal, relocation-invariant (POD) form of `CheckedTypePayload`: variant
/// slices are replaced by ranges into the store's flat pools. The public
/// `CheckedTypePayload` (with slices) is reconstructed on demand by `payload`.
pub const StoredCheckedTypePayload = union(enum) {
    pending,
    err,
    flex: StoredTypeVariable,
    rigid: StoredTypeVariable,
    alias: StoredAliasId,
    record: StoredRecord,
    tuple: CheckedTypeRange,
    nominal: StoredNominalId,
    function: StoredFunction,
    empty_record,
    tag_union: StoredTagUnion,
    empty_tag_union,
    field_kind: CheckedCommittedKind,
};

/// A row of a type store's `alias_row_pool`. Alias and nominal payloads are
/// far larger than the others, so they are held out of line and a stored
/// payload names their row.
pub const StoredAliasId = enum(u32) { _ };

/// A row of a type store's `nominal_row_pool`.
pub const StoredNominalId = enum(u32) { _ };

/// Materialize a live checked type value of type `Live` (a
/// `CheckedTypePayload` or one of its parts) from its stored POD form: a
/// `CheckedTypeRange` becomes the slice of the pool holding its element type,
/// a variable name id its interned text, and every other field is copied.
/// `pool_owner` is a `CheckedTypeStore` or `CheckedTypeStoreView`. Slice fields
/// alias the pools; no allocation.
///
/// ALIASING INVARIANT: returned slices and owner-module pointers borrow the
/// store's pools and payload array. A caller must not retain a returned slice
/// across a subsequent pool-growing call (`appendPool`/`commitPayload`/…):
/// growth copies a still-borrowed column into owned memory and may reallocate
/// an owned one, either of which dangles the slice. Snapshot or `dupe` first
/// (as `cloneCheckedTypeRootSubstituting` and `instantiateNominalBacking` do).
fn reconstructTypeData(comptime Live: type, pool_owner: anytype, stored: anytype) Live {
    const Stored = @typeInfo(@TypeOf(stored)).pointer.child;
    const info = @typeInfo(Live);
    if (comptime Stored == Live) {
        return stored.*;
    } else if (comptime info == .pointer and info.pointer.size == .one and info.pointer.child == Stored) {
        // A read form aliases the stored value rather than copying it.
        return stored;
    } else if (comptime Stored == CheckedTypeRange and (info == .@"struct" or info == .@"union")) {
        return Live.fromPool(pool_owner, stored.*);
    } else if (comptime Stored == CheckedTypeRange) {
        return storePool(pool_owner, info.pointer.child)[stored.start .. stored.start + stored.len];
    } else if (comptime Stored == OptionalVarNameId) {
        return pool_owner.varName(stored.*);
    } else if (comptime Stored == StoredAliasId) {
        return reconstructTypeData(Live, pool_owner, &storePool(pool_owner, StoredAlias)[@backingInt(stored.*)]);
    } else if (comptime Stored == StoredNominalId) {
        return reconstructTypeData(Live, pool_owner, &storePool(pool_owner, StoredNominal)[@backingInt(stored.*)]);
    } else if (comptime info == .@"struct") {
        var live: Live = undefined;
        inline for (info.@"struct".field_names, info.@"struct".field_types) |name, FieldType| {
            @field(live, name) = reconstructTypeData(FieldType, pool_owner, &@field(stored.*, name));
        }
        return live;
    } else {
        inline for (comptime std.enums.values(std.meta.Tag(Live))) |tag| {
            const name = @tagName(tag);
            if (stored.* == @field(std.meta.Tag(Stored), name)) {
                return @unionInit(Live, name, reconstructTypeData(@FieldType(Live, name), pool_owner, &@field(stored.*, name)));
            }
        }
        unreachable; // Stored and Live share tag names, and the loop above returns for each tag
    }
}

// Builtin identity selects its declaration directly, independently of the
// declaring module's source statement numbering. Zero means absent; stored
// declaration ids are offset by one so the index is compact serializable POD.
const BuiltinNominalDeclarationIndex = [@typeInfo(CheckedBuiltinNominal).@"enum".field_names.len]u32;
const empty_builtin_nominal_declarations: BuiltinNominalDeclarationIndex = @splat(0);

/// Read-only view over a `CheckedTypeStore`: reconstructed payloads
/// (`payload`) and range accessors (`CheckedTag.args`,
/// `CheckedTypeScheme.generalizedVars`, `CheckedNominalDeclaration.formalArgs`)
/// read the store's columns at the time of each read, so a view sees the
/// types a module analysis synthesizes after the view was taken.
pub const CheckedTypeStoreView = struct {
    /// Reusable scratch for checked type equality queries. Every query
    /// clears it on entry, so one scratch serves any number of queries of
    /// any mode; clearing is proportional to what the previous query used.
    pub const EqualityScratch = struct {
        allocator: Allocator,
        assumed: CheckedTypePairSet,
        /// The variable bijection of an alpha-exact query, in both directions.
        left_variables: collections.DenseMap(CheckedTypeId, CheckedTypeId),
        right_variables: collections.DenseMap(CheckedTypeId, CheckedTypeId),
        pending: std.ArrayListUnmanaged(CheckedTypeExactPair) = .empty,

        pub fn init(allocator: Allocator) EqualityScratch {
            return .{
                .allocator = allocator,
                .assumed = CheckedTypePairSet.init(allocator),
                .left_variables = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator),
                .right_variables = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator),
            };
        }

        pub fn deinit(self: *EqualityScratch) void {
            self.assumed.deinit();
            self.left_variables.deinit();
            self.right_variables.deinit();
            self.pending.deinit(self.allocator);
        }

        fn clear(self: *EqualityScratch) void {
            self.assumed.clearRetainingCapacity();
            self.left_variables.clearRetainingCapacity();
            self.right_variables.clearRetainingCapacity();
            self.pending.clearRetainingCapacity();
        }
    };

    /// The store whose synthesized types the view reads. Its columns grow
    /// while other threads read them (`collections.PublishedList`), so every
    /// read goes through the store and sees each type created before an id
    /// naming it reached the reader. Null for a view of no synthesized types.
    store: ?*CheckedTypeStore = null,
    builtin_nominal_declarations: *const BuiltinNominalDeclarationIndex = &empty_builtin_nominal_declarations,
    /// The module's source types, read from its sealed solver store; null
    /// for a store holding only synthesized types.
    sealed: ?sealed_type_view.SealedTypeView = null,
    /// The key slots of the module's source types.
    sealed_keys: ?*sealed_type_keys.SealedTypeKeys = null,
    /// The key slots of the store's synthesized types.
    synthesized_keys: ?*SynthesizedTypeKeys = null,
    /// The name store the store's types name, which synthesized types' keys
    /// read; null for a view that computes no synthesized key.
    names: ?*const canonical.CanonicalNameStore = null,
    /// The platform/app pairing a platform's types are read under; null for
    /// a view of a module's own types.
    pairing: ?*PairingOverlay = null,

    /// The type `id`, a type of the module's own checked data, reads as:
    /// its image under the view's pairing, or itself.
    pub fn pairedType(self: CheckedTypeStoreView, id: CheckedTypeId) Allocator.Error!CheckedTypeId {
        const pairing = self.pairing orelse return id;
        return try pairing.image(id);
    }

    /// The scheme `id`, a scheme of the module's own checked data, reads
    /// as: the scheme of its root's image under the view's pairing, or
    /// itself.
    pub fn pairedScheme(self: CheckedTypeStoreView, id: CheckedTypeSchemeId) Allocator.Error!CheckedTypeSchemeId {
        const pairing = self.pairing orelse return id;
        return try pairing.schemeImage(id);
    }

    /// Text of a stored variable name id, or null when absent.
    pub fn varName(self: CheckedTypeStoreView, id: OptionalVarNameId) ?[]const u8 {
        const name_id = id.get() orelse return null;
        const store = self.store orelse checkedModuleInvariant("a variable name was read from a view without a store", .{});
        return store.varNameText(@backingInt(name_id));
    }

    pub fn schemeRows(self: CheckedTypeStoreView) []const CheckedTypeScheme {
        return if (self.store) |store| store.schemes.items() else &.{};
    }

    pub fn storedPayloads(self: CheckedTypeStoreView) []const StoredCheckedTypePayload {
        return if (self.store) |store| store.payloads.items() else &.{};
    }

    pub fn aliasRows(self: CheckedTypeStoreView) []const StoredAlias {
        return if (self.store) |store| store.alias_row_pool.items() else &.{};
    }

    pub fn nominalRows(self: CheckedTypeStoreView) []const StoredNominal {
        return if (self.store) |store| store.nominal_row_pool.items() else &.{};
    }

    pub fn nominalDeclarationRows(self: CheckedTypeStoreView) []const CheckedNominalDeclaration {
        return if (self.store) |store| store.nominal_declarations.items() else &.{};
    }

    pub fn typeIdPool(self: CheckedTypeStoreView) []const CheckedTypeId {
        return if (self.store) |store| store.type_id_pool.items() else &.{};
    }

    pub fn recordFieldPool(self: CheckedTypeStoreView) []const CheckedRecordField {
        return if (self.store) |store| store.record_field_pool.items() else &.{};
    }

    pub fn declaredFieldPool(self: CheckedTypeStoreView) []const CheckedDeclaredField {
        return if (self.store) |store| store.declared_field_pool.items() else &.{};
    }

    pub fn nominalRecordFieldPool(self: CheckedTypeStoreView) []const CheckedNominalRecordField {
        return if (self.store) |store| store.nominal_record_field_pool.items() else &.{};
    }

    pub fn constraintPool(self: CheckedTypeStoreView) []const CheckedStaticDispatchConstraint {
        return if (self.store) |store| store.constraint_pool.items() else &.{};
    }

    pub fn tagPool(self: CheckedTypeStoreView) []const StoredTag {
        return if (self.store) |store| store.tag_pool.items() else &.{};
    }

    fn sealedView(self: CheckedTypeStoreView) sealed_type_view.SealedTypeView {
        return self.sealed orelse checkedModuleInvariant("a checked source type was read from a store without its sealed solver store", .{});
    }

    fn sealedKeys(self: CheckedTypeStoreView) *sealed_type_keys.SealedTypeKeys {
        return self.sealed_keys orelse checkedModuleInvariant("a checked source type key was requested from a store without key slots", .{});
    }

    fn synthesizedKeys(self: CheckedTypeStoreView) *SynthesizedTypeKeys {
        return self.synthesized_keys orelse checkedModuleInvariant("a synthesized checked type key was requested from a store without key slots", .{});
    }

    /// The number of distinct checked types the view holds: an upper bound
    /// on the length of any acyclic chain through them.
    pub fn typeCount(self: CheckedTypeStoreView) usize {
        const source_count: usize = if (self.sealed) |sealed| sealed.var_facts.len else 0;
        return source_count + self.storedPayloads().len;
    }

    /// Whether `id` names a type of this view: a synthesized entry it holds,
    /// or a reached checked representative of its sealed store.
    pub fn containsId(self: CheckedTypeStoreView, id: CheckedTypeId) bool {
        if (type_ids.isSynthesized(id)) return type_ids.synthesizedIndex(id) < self.storedPayloads().len;
        const sealed = self.sealed orelse return false;
        const var_ = type_ids.asVar(id);
        if (@backingInt(var_) >= sealed.var_facts.len) return false;
        return sealed.reaches(var_) and sealed.representative(var_) == var_;
    }

    fn synthesizedIndex(self: CheckedTypeStoreView, id: CheckedTypeId) usize {
        const index = type_ids.synthesizedIndex(id);
        if (index >= self.storedPayloads().len) checkedModuleInvariant("synthesized checked type id is out of range", .{});
        return index;
    }

    /// Materialize the public read-form payload for `id`. Slice fields alias the
    /// view's pools or the module's sealed solver store; no allocation.
    pub fn payload(self: CheckedTypeStoreView, id: CheckedTypeId) CheckedTypePayload {
        var result = if (!type_ids.isSynthesized(id))
            self.sealedView().payload(type_ids.asVar(id))
        else
            reconstructTypeData(CheckedTypePayload, self, &self.storedPayloads()[self.synthesizedIndex(id)]);
        if (result == .nominal) switch (result.nominal.representation) {
            // A nominal type its own module declares reads with its
            // instance's box payload capability once the module's
            // capabilities were demanded.
            .local_declaration => if (self.store) |store| {
                if (store.publishedCapabilities()) |capabilities| {
                    result.nominal.representation = capabilities.representationOf(store, id, result.nominal);
                }
            },
            .local_box_payload_capability => checkedModuleInvariant("a checked type store holds a box payload capability", .{}),
            .builtin, .imported_declaration, .opaque_without_backing => {},
        };
        return result;
    }

    /// The interface capabilities a consumer already demanded: a reader
    /// that meets a box payload capability representation reads a type of a
    /// module whose capabilities were demanded.
    pub fn demandedInterfaceCapabilities(self: CheckedTypeStoreView) *const ModuleInterfaceCapabilities {
        const store = self.store orelse checkedModuleInvariant("interface capabilities were read from a view without a store", .{});
        const source = store.capability_source orelse checkedModuleInvariant("interface capabilities were read from a store without module analyses", .{});
        return source.analyses.peekInterfaceCapabilities() orelse checkedModuleInvariant("interface capabilities were read before they were demanded", .{});
    }

    /// The interface capabilities of the module whose types the view reads,
    /// computed on first demand. Reads of the module's nominal types carry
    /// them from then on.
    pub fn interfaceCapabilities(self: CheckedTypeStoreView) Allocator.Error!*const ModuleInterfaceCapabilities {
        const store = self.store orelse checkedModuleInvariant("interface capabilities were demanded from a view without a store", .{});
        const source = store.capability_source orelse checkedModuleInvariant("interface capabilities were demanded from a store without module analyses", .{});
        return source.analyses.interfaceCapabilities(store, source.current_module);
    }

    /// Whether `id` is a nominal or alias type.
    pub fn isNamed(self: CheckedTypeStoreView, id: CheckedTypeId) bool {
        return switch (self.payload(id)) {
            .alias, .nominal => true,
            .pending, .field_kind, .err, .flex, .rigid, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => false,
        };
    }

    /// A checked type keyed `key`: the lowest source type with that key, or
    /// else the lowest synthesized one. Each key index is built on its first
    /// demand.
    pub fn rootForKey(self: CheckedTypeStoreView, key: canonical.CanonicalTypeKey) Allocator.Error!?CheckedTypeId {
        if (self.sealed) |sealed| {
            if (try self.sealedKeys().varForKey(sealed, key)) |var_| return type_ids.fromVar(var_);
        }
        if (self.rootRows().len == 0) return null;
        const store = self.store orelse return null;
        return try self.synthesizedKeys().rootForKey(self, key, store.completeRootCount());
    }

    pub fn rootRows(self: CheckedTypeStoreView) []const CheckedTypeRoot {
        return if (self.store) |store| store.roots.items() else &.{};
    }

    /// The key of `root` and the facts its encoding found, computed on the
    /// first demand through the root's key slot.
    pub fn rootInfo(self: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        if (!type_ids.isSynthesized(root)) return try self.sealedKeys().info(type_ids.asVar(root));
        return try self.synthesizedKeys().info(self, root);
    }

    /// Whether `root` reaches a flex or rigid variable, found by walking the
    /// types it reaches; no key is computed. The walk records the fact for
    /// every type whose result it proves, not only for `root`, so asking
    /// about each level of a deep type in turn walks each level once.
    pub fn rootHasIdentityVariables(self: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!bool {
        if (self.knownIdentity(root)) |known| return known;
        var scan = CheckedTypeViewIdentityScan{ .view = self };
        var traversal = checked_traverse.BoolPredicateTraversal(CheckedTypeId, CheckedTypeViewIdentityScan).init(self.scanAllocator(), &scan);
        defer traversal.deinit();
        const result = try traversal.visit(root);
        if (!scan.saw_pending) traversal.reportDecided(result, IdentityRecorder{ .view = self });
        return result;
    }

    const IdentityRecorder = struct {
        view: CheckedTypeStoreView,

        pub fn decided(self: IdentityRecorder, ty: CheckedTypeId, value: bool) void {
            self.view.recordIdentity(ty, value);
        }
    };

    /// The identity-variable fact of `root` a previous walk recorded.
    fn knownIdentity(self: CheckedTypeStoreView, root: CheckedTypeId) ?bool {
        if (type_ids.isSynthesized(root)) {
            const keys = self.synthesized_keys orelse return null;
            return keys.knownIdentity(type_ids.synthesizedIndex(root));
        }
        const keys = self.sealed_keys orelse return null;
        return keys.knownIdentity(type_ids.asVar(root));
    }

    fn recordIdentity(self: CheckedTypeStoreView, root: CheckedTypeId, value: bool) void {
        if (type_ids.isSynthesized(root)) {
            if (self.synthesized_keys) |keys| keys.recordIdentity(type_ids.synthesizedIndex(root), value);
        } else if (self.sealed_keys) |keys| keys.recordIdentity(type_ids.asVar(root), value);
    }

    /// A thread-safe allocator owned by the module the view reads.
    fn scanAllocator(self: CheckedTypeStoreView) Allocator {
        if (self.synthesized_keys) |keys| return keys.allocator;
        if (self.sealed_keys) |keys| return keys.allocator;
        checkedModuleInvariant("a checked type walk was requested from a store without key slots", .{});
    }

    /// The id that stands for `id`'s type in this view: `id` itself for a type
    /// that reaches an identity variable, and otherwise the type `rootForKey`
    /// finds for its key, so every root of one identity-free type shares one
    /// id.
    /// Each type's answer is recorded once its identity fact is decided, so
    /// a repeated request is one atomic load.
    pub fn canonicalId(self: CheckedTypeStoreView, id: CheckedTypeId) Allocator.Error!CheckedTypeId {
        if (self.knownCanonical(id)) |known| return known;
        const result = if (try self.rootHasIdentityVariables(id))
            id
        else
            (try self.rootForKey(try self.rootKey(id))) orelse
                checkedModuleInvariant("an identity-free checked type has no root for its own key", .{});
        if (self.knownIdentity(id) != null) self.recordCanonical(id, result);
        return result;
    }

    /// The canonical id of `id` a previous request recorded.
    fn knownCanonical(self: CheckedTypeStoreView, id: CheckedTypeId) ?CheckedTypeId {
        if (type_ids.isSynthesized(id)) {
            const keys = self.synthesized_keys orelse return null;
            return keys.knownCanonical(type_ids.synthesizedIndex(id));
        }
        const keys = self.sealed_keys orelse return null;
        return keys.knownCanonical(type_ids.asVar(id));
    }

    fn recordCanonical(self: CheckedTypeStoreView, id: CheckedTypeId, canonical_id: CheckedTypeId) void {
        if (type_ids.isSynthesized(id)) {
            if (self.synthesized_keys) |keys| keys.recordCanonical(type_ids.synthesizedIndex(id), canonical_id);
        } else if (self.sealed_keys) |keys| keys.recordCanonical(type_ids.asVar(id), canonical_id);
    }

    /// Whether `left` and `right` are one checked type of this view: the same
    /// id, or two types with one key that reach no identity variable. A key
    /// with variables identifies a type only together with where its
    /// variables come from, so such types are one type only by id.
    pub fn sameType(self: CheckedTypeStoreView, left: CheckedTypeId, right: CheckedTypeId) Allocator.Error!bool {
        if (left == right) return true;
        if (try self.rootHasIdentityVariables(left)) return false;
        if (try self.rootHasIdentityVariables(right)) return false;
        return std.meta.eql(try self.rootKey(left), try self.rootKey(right));
    }

    /// The checked type of the source variable `var_`, or null when
    /// publication never reached it.
    pub fn sourceTypeRoot(self: CheckedTypeStoreView, var_: Var) ?CheckedTypeId {
        const sealed = self.sealed orelse return null;
        if (!sealed.reaches(var_)) return null;
        return type_ids.fromVar(sealed.representative(var_));
    }

    /// The scheme `id` names: a source scheme is named by its root, a
    /// source variable, and a synthetic scheme by its row of the store's
    /// synthetic schemes, in the synthesized id space.
    pub fn scheme(self: CheckedTypeStoreView, id: CheckedTypeSchemeId) CheckedTypeScheme {
        const as_type: CheckedTypeId = @fromBackingInt(@backingInt(id));
        if (!type_ids.isSynthesized(as_type)) return .{ .id = id, .domain = .source, .root = as_type };
        const index = type_ids.synthesizedIndex(as_type);
        if (index >= self.schemeRows().len) checkedModuleInvariant("checked type scheme id is out of range", .{});
        return self.schemeRows()[index];
    }

    /// The canonical key of the scheme `id` names, computed from its root's
    /// key.
    pub fn schemeKey(self: CheckedTypeStoreView, id: CheckedTypeSchemeId) Allocator.Error!canonical.CanonicalTypeSchemeKey {
        const row = self.scheme(id);
        const root_key = try self.rootKey(row.root);
        return switch (row.domain) {
            .source => canonical_type_keys.schemeKeyForType(root_key),
            .synthetic => syntheticSchemeKeyForType(root_key),
        };
    }

    /// Returns the canonical key for a checked type root in this view.
    pub fn rootKey(self: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!canonical.CanonicalTypeKey {
        return (try self.rootInfo(root)).key;
    }

    /// Returns the canonical key after expanding transparent aliases at the
    /// root. Dispatch syntax can retain an alias wrapper while the constraint
    /// relation names its backing root; both denote the same structural codec
    /// shape, unlike a nominal wrapper which remains part of the key.
    pub fn structuralRootKey(self: CheckedTypeStoreView, raw_root: CheckedTypeId) Allocator.Error!canonical.CanonicalTypeKey {
        var root = raw_root;
        while (true) {
            switch (self.payload(root)) {
                .alias => |alias| root = alias.backing,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .record,
                .tuple,
                .nominal,
                .function,
                .tag_union,
                .empty_record,
                .empty_tag_union,
                => return try self.rootKey(root),
            }
        }
    }

    /// Exact same-store equality for published checked types. Canonical keys
    /// are the fast bucket identity, while this graph comparison is the
    /// collision authority for producer contracts that intentionally merge
    /// repeated closed obligations.
    pub fn rootExactEql(
        self: CheckedTypeStoreView,
        scratch: *EqualityScratch,
        left: CheckedTypeId,
        right: CheckedTypeId,
    ) Allocator.Error!bool {
        scratch.clear();
        return try checkedTypeRootSliceEql(.exact, .named, .stored, self, &.{left}, &.{right}, scratch);
    }

    /// Same-store equality of the types two roots denote: transparent aliases
    /// are expanded at every depth, while nominal types, variables, and all
    /// other structure compare exactly as in `rootExactEql`.
    pub fn rootAliasTransparentEql(
        self: CheckedTypeStoreView,
        scratch: *EqualityScratch,
        left: CheckedTypeId,
        right: CheckedTypeId,
    ) Allocator.Error!bool {
        scratch.clear();
        return try checkedTypeRootSliceEql(.exact, .transparent, .stored, self, &.{left}, &.{right}, scratch);
    }

    /// Exact same-store equality modulo a bijective renaming of flex/rigid
    /// identities. Generated-codec snapshots copy one checked relation into
    /// independently owned graphs, so the corresponding open variables have
    /// distinct ids even though their sharing, constraints, and surrounding
    /// structure must remain identical.
    pub fn rootAlphaExactEql(
        self: CheckedTypeStoreView,
        scratch: *EqualityScratch,
        left: CheckedTypeId,
        right: CheckedTypeId,
    ) Allocator.Error!bool {
        return try self.rootsAlphaExactEql(scratch, &.{left}, &.{right});
    }

    /// Alpha-exact equality for a relation with multiple roots. All roots
    /// share one variable bijection so cross-root identity and sharing remain
    /// part of the comparison.
    pub fn rootsAlphaExactEql(
        self: CheckedTypeStoreView,
        scratch: *EqualityScratch,
        left: []const CheckedTypeId,
        right: []const CheckedTypeId,
    ) Allocator.Error!bool {
        if (left.len != right.len) return false;
        for (left, right) |left_root, right_root| {
            if (!std.meta.eql(try self.rootKey(left_root), try self.rootKey(right_root))) return false;
        }
        scratch.clear();
        return try checkedTypeRootSliceEql(.alpha, .named, .stored, self, left, right, scratch);
    }

    /// Bucket key for `rootAliasTransparentEql`: a hash of the alias-resolved
    /// root's own constructor and labels, which every alias-transparent-equal
    /// type shares. Canonical keys retain alias identity, so callers bucket
    /// alias-transparent comparisons by this key instead.
    pub fn aliasTransparentBucketKey(self: CheckedTypeStoreView, raw_root: CheckedTypeId) u64 {
        const root = checkedTypeEqualityRoot(.transparent, self, raw_root);
        const root_payload = self.payload(root);
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, std.meta.activeTag(root_payload));
        switch (root_payload) {
            .alias => unreachable, // checkedTypeEqualityRoot(.transparent) resolves past every alias
            .pending, .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => std.hash.autoHash(&hasher, root),
            .record => |record| {
                std.hash.autoHash(&hasher, record.fields.len());
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    std.hash.autoHash(&hasher, field.name);
                }
            },
            .tuple => |items| std.hash.autoHash(&hasher, items.len),
            .nominal => |nominal| {
                std.hash.autoHash(&hasher, nominal.name);
                std.hash.autoHash(&hasher, nominal.origin_module);
                std.hash.autoHash(&hasher, nominal.builtin);
                std.hash.autoHash(&hasher, nominal.args.len);
            },
            .function => |function| {
                std.hash.autoHash(&hasher, finalizedFunctionKind(function.kind));
                std.hash.autoHash(&hasher, function.args.len);
            },
            .tag_union => |tag_union| {
                std.hash.autoHash(&hasher, tag_union.tags.len());
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    std.hash.autoHash(&hasher, tag.name);
                    std.hash.autoHash(&hasher, tag.args.len);
                }
            },
        }
        return hasher.final();
    }

    /// Alpha-exact equality of the types a multi-root relation denotes, with
    /// transparent aliases expanded at every depth as in
    /// `rootAliasTransparentEql`. Canonical keys retain alias identity, so no
    /// key prefilter applies.
    pub fn rootsAliasTransparentAlphaEql(
        self: CheckedTypeStoreView,
        scratch: *EqualityScratch,
        left: []const CheckedTypeId,
        right: []const CheckedTypeId,
    ) Allocator.Error!bool {
        if (left.len != right.len) return false;
        scratch.clear();
        return try checkedTypeRootSliceEql(.alpha, .transparent, .stored, self, left, right, scratch);
    }

    pub fn nominalDeclaration(
        self: CheckedTypeStoreView,
        nominal: canonical.NominalTypeKey,
    ) ?CheckedNominalDeclaration {
        for (self.nominalDeclarationRows()) |declaration| {
            if (canonicalNominalTypeKeyEql(declaration.nominal, nominal)) return declaration;
        }
        return null;
    }

    /// The name `declaration` declares.
    pub fn nominalDeclarationName(self: CheckedTypeStoreView, declaration: CheckedNominalDeclaration) canonical.TypeNameId {
        return switch (self.payload(declaration.declaration_root)) {
            .nominal => |nominal| nominal.name,
            .pending, .field_kind, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => base.invariant("a nominal declaration's root is no nominal type", .{}),
        };
    }

    pub fn nominalDeclarationById(
        self: CheckedTypeStoreView,
        id: CheckedNominalDeclarationId,
    ) CheckedNominalDeclaration {
        const index: usize = @backingInt(id);
        if (index >= self.nominalDeclarationRows().len) {
            checkedModuleInvariant("checked nominal declaration id is out of range", .{});
        }
        const declaration = self.nominalDeclarationRows()[index];
        if (declaration.id != id) {
            checkedModuleInvariant("checked nominal declaration id disagrees with declaration slot", .{});
        }
        return declaration;
    }

    /// Direct declaration access from checked builtin identity. Intrinsic
    /// builtins need not have a source declaration in this store.
    pub fn builtinNominalDeclaration(
        self: CheckedTypeStoreView,
        builtin_nominal: CheckedBuiltinNominal,
    ) ?CheckedNominalDeclaration {
        const entry = self.builtin_nominal_declarations[@backingInt(builtin_nominal)];
        if (entry == 0) return null;
        return self.nominalDeclarationById(@fromBackingInt(@intCast(entry - 1)));
    }

    /// The declaration of `nominal`, a nominal type this view's module
    /// declares; another module's nominal type is read in its declaring
    /// module (`nominalDeclarationSite`).
    pub fn nominalDeclarationForPayload(
        self: CheckedTypeStoreView,
        nominal: CheckedNominalType,
    ) ?CheckedNominalDeclaration {
        if (nominal.builtin) |builtin_nominal| return self.builtinNominalDeclaration(builtin_nominal);
        return self.nominalDeclaration(checkedNominalTypeKey(nominal));
    }

    /// The backing template of `nominal`, a nominal type this view's module
    /// declares.
    pub fn nominalBackingTemplateForPayload(
        self: CheckedTypeStoreView,
        nominal: CheckedNominalType,
    ) ?CheckedTypeId {
        if (nominal.representation == .opaque_without_backing) return null;
        if (nominal.builtin) |builtin_nominal| {
            if (!builtinNominalHasDeclarationBacking(builtin_nominal)) return null;
        }
        const declaration = self.nominalDeclarationForPayload(nominal) orelse {
            checkedModuleInvariant("checked nominal payload referenced a missing nominal declaration", .{});
        };
        return declaration.backing;
    }
};

const CheckedTypeExactPair = struct {
    left: CheckedTypeId,
    right: CheckedTypeId,
};

/// The type pairs one equality query assumes equal. Pairs are indexed by
/// their left type; the right types paired with one left type form a chain.
const CheckedTypePairSet = struct {
    first_by_left: collections.DenseMap(CheckedTypeId, u32),
    rows: std.ArrayListUnmanaged(Row) = .empty,

    const no_row = std.math.maxInt(u32);
    const Row = struct {
        right: CheckedTypeId,
        next: u32,
    };

    fn init(allocator: Allocator) CheckedTypePairSet {
        return .{ .first_by_left = collections.DenseMap(CheckedTypeId, u32).init(allocator) };
    }

    fn deinit(self: *CheckedTypePairSet) void {
        self.rows.deinit(self.first_by_left.allocator);
        self.first_by_left.deinit();
    }

    fn clearRetainingCapacity(self: *CheckedTypePairSet) void {
        self.first_by_left.clearRetainingCapacity();
        self.rows.clearRetainingCapacity();
    }

    /// Add `pair`, reporting whether it was already present.
    fn insert(self: *CheckedTypePairSet, pair: CheckedTypeExactPair) Allocator.Error!bool {
        const row_index = std.math.cast(u32, self.rows.items.len) orelse return error.OutOfMemory;
        if (row_index == no_row) return error.OutOfMemory;
        try self.rows.ensureUnusedCapacity(self.first_by_left.allocator, 1);
        const head = try self.first_by_left.getOrPut(pair.left);
        const first = if (head.found_existing) head.value_ptr.* else no_row;
        var cursor = first;
        while (cursor != no_row) {
            const row = self.rows.items[cursor];
            if (row.right == pair.right) return true;
            cursor = row.next;
        }
        self.rows.appendAssumeCapacity(.{ .right = pair.right, .next = first });
        head.value_ptr.* = row_index;
        return false;
    }
};

/// How checked type equality treats transparent alias wrappers. `named`
/// compares an alias by its declaration identity; `transparent` compares only
/// the types aliases denote, at every depth. Nominal types keep their
/// declaration identity in both modes.
const CheckedAliasEquality = enum { named, transparent };

/// How checked type equality compares nominal types. `stored` compares
/// everything a nominal payload holds, its representation included;
/// `declaration_args` compares only its declaration and its arguments, the
/// type's own identity, whose representation, padding types and declared
/// fields follow from them.
const CheckedNominalEquality = enum { stored, declaration_args };

fn checkedTypeEqualityRoot(
    comptime aliases: CheckedAliasEquality,
    view: CheckedTypeStoreView,
    root: CheckedTypeId,
) CheckedTypeId {
    if (aliases == .named) return root;
    var current = root;
    while (true) switch (view.payload(current)) {
        .alias => |alias| current = alias.backing,
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .record,
        .tuple,
        .nominal,
        .function,
        .tag_union,
        .empty_record,
        .empty_tag_union,
        => return current,
    };
}

/// Equality of every root pair. Pairs are compared in source order from an
/// explicit work list; a pair already assumed is equal by assumption, which is
/// what lets a cyclic type answer at all. `.alpha` shares one variable
/// bijection across all of the pairs. The caller clears `scratch`.
fn checkedTypeRootSliceEql(
    comptime mode: CheckedTypeEqlMode,
    comptime aliases: CheckedAliasEquality,
    comptime nominals: CheckedNominalEquality,
    view: CheckedTypeStoreView,
    left: []const CheckedTypeId,
    right: []const CheckedTypeId,
    scratch: *CheckedTypeStoreView.EqualityScratch,
) Allocator.Error!bool {
    const pending = &scratch.pending;
    if (!try appendCheckedTypePairs(scratch.allocator, pending, left, right)) return false;
    std.mem.reverse(CheckedTypeExactPair, pending.items);
    while (pending.pop()) |pair| {
        const start = pending.items.len;
        if (!try checkedTypePairEqlStep(mode, aliases, nominals, view, pair, scratch)) return false;
        std.mem.reverse(CheckedTypeExactPair, pending.items[start..]);
    }
    return true;
}

/// Queue `left[i]` against `right[i]` in order; false on a length mismatch.
fn appendCheckedTypePairs(
    allocator: Allocator,
    pending: *std.ArrayListUnmanaged(CheckedTypeExactPair),
    left: []const CheckedTypeId,
    right: []const CheckedTypeId,
) Allocator.Error!bool {
    if (left.len != right.len) return false;
    for (left, right) |left_ty, right_ty| {
        try pending.append(allocator, .{ .left = left_ty, .right = right_ty });
    }
    return true;
}

fn checkedDeclaredFieldsExactEql(
    left: []const CheckedDeclaredField,
    right: []const CheckedDeclaredField,
) bool {
    if (left.len != right.len) return false;
    for (left, right) |left_field, right_field| {
        if (!std.meta.eql(left_field, right_field)) return false;
    }
    return true;
}

const CheckedTypeEqlMode = enum { exact, alpha };

/// Compare one pair's own structure, queueing its child pairs in order.
/// `.alpha` relates flex/rigid identities through `scratch`'s bijection;
/// `.exact` treats distinct variable ids as distinct.
fn checkedTypePairEqlStep(
    comptime mode: CheckedTypeEqlMode,
    comptime aliases: CheckedAliasEquality,
    comptime nominals: CheckedNominalEquality,
    view: CheckedTypeStoreView,
    pair: CheckedTypeExactPair,
    scratch: *CheckedTypeStoreView.EqualityScratch,
) Allocator.Error!bool {
    const allocator = scratch.allocator;
    const pending = &scratch.pending;
    const left = checkedTypeEqualityRoot(aliases, view, pair.left);
    const right = checkedTypeEqualityRoot(aliases, view, pair.right);
    if (mode == .exact and left == right) return true;
    const left_payload = view.payload(left);
    const right_payload = view.payload(right);
    if (mode == .alpha) {
        if (std.meta.activeTag(left_payload) != std.meta.activeTag(right_payload)) return false;
        // Variable identity still participates in the bijection when the two ids
        // happen to be numerically equal. Returning early for that pair could hide
        // a sharing mismatch after the same left variable was already mapped to a
        // different right variable.
        switch (left_payload) {
            .flex => |left_variable| return try checkedTypeVariableAlphaStep(left, left_variable, right, right_payload.flex, scratch),
            .rigid => |left_variable| return try checkedTypeVariableAlphaStep(left, left_variable, right, right_payload.rigid, scratch),
            .pending,
            .field_kind,
            .err,
            .empty_record,
            .empty_tag_union,
            .alias,
            .record,
            .tuple,
            .nominal,
            .function,
            .tag_union,
            => {},
        }
        if (left == right) return true;
    }
    if (try scratch.assumed.insert(.{ .left = left, .right = right })) return true;
    if (mode == .exact and std.meta.activeTag(left_payload) != std.meta.activeTag(right_payload)) return false;

    switch (left_payload) {
        .pending, .field_kind, .err, .empty_record, .empty_tag_union => return true,
        // Distinct published variable ids are distinct checker identities;
        // equality-by-id returned above handles repeated references to one.
        .flex, .rigid => switch (mode) {
            .exact => return false,
            .alpha => unreachable, // the alpha-mode switch above returns for every flex and rigid pair
        },
        .alias => |left_alias| {
            if (aliases == .transparent) unreachable; // checkedTypeEqualityRoot(.transparent) resolved both sides past their aliases
            const right_alias = right_payload.alias;
            if (left_alias.name != right_alias.name or
                left_alias.origin_module != right_alias.origin_module or
                !std.meta.eql(left_alias.owner_module.*, right_alias.owner_module.*) or
                left_alias.source_decl != right_alias.source_decl or
                left_alias.builtin_origin != right_alias.builtin_origin or
                !try appendCheckedTypePairs(allocator, pending, left_alias.args, right_alias.args))
            {
                return false;
            }
            try pending.append(allocator, .{ .left = left_alias.backing, .right = right_alias.backing });
            return true;
        },
        .record => |left_record| {
            const right_record = right_payload.record;
            if (left_record.fields.len() != right_record.fields.len()) return false;
            for (0..left_record.fields.len()) |field_index| {
                const left_field = left_record.fields.get(field_index);
                const right_field = right_record.fields.get(field_index);
                if (left_field.name != right_field.name) return false;
                switch (mode) {
                    .exact => if (!std.meta.eql(left_field.kind, right_field.kind)) return false,
                    .alpha => {
                        const left_kind = left_field.kind;
                        const right_kind = right_field.kind;
                        if (left_kind.tag != right_kind.tag or !std.meta.eql(left_kind.default, right_kind.default)) return false;
                        const left_variable = left_kind.variable.get();
                        const right_variable = right_kind.variable.get();
                        if ((left_variable == null) != (right_variable == null)) return false;
                        if (left_variable) |left_ty| {
                            try pending.append(allocator, .{ .left = left_ty, .right = right_variable.? });
                        }
                    },
                }
                try pending.append(allocator, .{ .left = left_field.ty, .right = right_field.ty });
            }
            try pending.append(allocator, .{ .left = left_record.ext, .right = right_record.ext });
            return true;
        },
        .tuple => |left_items| return try appendCheckedTypePairs(allocator, pending, left_items, right_payload.tuple),
        .nominal => |left_nominal| {
            const right_nominal = right_payload.nominal;
            const same_declaration = left_nominal.name == right_nominal.name and
                left_nominal.origin_module == right_nominal.origin_module and
                std.meta.eql(left_nominal.owner_module.*, right_nominal.owner_module.*) and
                left_nominal.source_decl == right_nominal.source_decl and
                left_nominal.builtin == right_nominal.builtin and
                left_nominal.is_opaque == right_nominal.is_opaque;
            return switch (nominals) {
                .stored => same_declaration and
                    checkedNominalRepresentationEql(mode, view, left_nominal.representation, right_nominal.representation) and
                    checkedDeclaredFieldsExactEql(left_nominal.declared_fields, right_nominal.declared_fields) and
                    try appendCheckedTypePairs(allocator, pending, left_nominal.args, right_nominal.args) and
                    try appendCheckedTypePairs(allocator, pending, left_nominal.padding_field_types, right_nominal.padding_field_types),
                .declaration_args => same_declaration and
                    try appendCheckedTypePairs(allocator, pending, left_nominal.args, right_nominal.args),
            };
        },
        .function => |left_function| {
            const right_function = right_payload.function;
            if (finalizedFunctionKind(left_function.kind) != finalizedFunctionKind(right_function.kind) or
                !try appendCheckedTypePairs(allocator, pending, left_function.args, right_function.args))
            {
                return false;
            }
            try pending.append(allocator, .{ .left = left_function.ret, .right = right_function.ret });
            return true;
        },
        .tag_union => |left_union| {
            const right_union = right_payload.tag_union;
            if (left_union.tags.len() != right_union.tags.len()) return false;
            for (0..left_union.tags.len()) |tag_index| {
                const left_tag = left_union.tags.get(tag_index);
                const right_tag = right_union.tags.get(tag_index);
                if (left_tag.name != right_tag.name or
                    !try appendCheckedTypePairs(allocator, pending, left_tag.args, right_tag.args))
                {
                    return false;
                }
            }
            try pending.append(allocator, .{ .left = left_union.ext, .right = right_union.ext });
            return true;
        },
    }
}

/// Whether two nominal types, whose declarations and arguments the caller
/// compares, carry one representation. A box payload capability names an
/// instance, so `.exact`, under which equal arguments are one instance,
/// compares capabilities themselves, while `.alpha`, under which equal
/// arguments may be instances over renamed variables, compares the
/// declarations the capabilities are of.
fn checkedNominalRepresentationEql(
    comptime mode: CheckedTypeEqlMode,
    view: CheckedTypeStoreView,
    left: CheckedNominalRepresentationRef,
    right: CheckedNominalRepresentationRef,
) bool {
    switch (mode) {
        .exact => return std.meta.eql(left, right),
        .alpha => switch (left) {
            .local_box_payload_capability => |left_capability| {
                const right_capability = switch (right) {
                    .local_box_payload_capability => |capability| capability,
                    .builtin, .local_declaration, .imported_declaration, .opaque_without_backing => return false,
                };
                const capabilities = view.demandedInterfaceCapabilities();
                return capabilities.boxPayloadCapability(left_capability.capability).declaration ==
                    capabilities.boxPayloadCapability(right_capability.capability).declaration;
            },
            .builtin, .local_declaration, .imported_declaration, .opaque_without_backing => return std.meta.eql(left, right),
        },
    }
}

/// Relate two variables through the bijection, queueing their constraint
/// types when this is the first time either is seen.
fn checkedTypeVariableAlphaStep(
    left_id: CheckedTypeId,
    left: CheckedTypeVariable,
    right_id: CheckedTypeId,
    right: CheckedTypeVariable,
    scratch: *CheckedTypeStoreView.EqualityScratch,
) Allocator.Error!bool {
    if (scratch.left_variables.get(left_id)) |mapped| return mapped == right_id;
    if (scratch.right_variables.get(right_id)) |mapped| return mapped == left_id;
    try scratch.left_variables.put(left_id, right_id);
    try scratch.right_variables.put(right_id, left_id);

    if (left.numeric_default_phase != right.numeric_default_phase or
        left.row_default != right.row_default or
        left.bounded_row_ext != right.bounded_row_ext or
        left.constraints.len() != right.constraints.len())
    {
        return false;
    }
    for (0..left.constraints.len()) |constraint_index| {
        const left_constraint = left.constraints.get(constraint_index);
        const right_constraint = right.constraints.get(constraint_index);
        if (left_constraint.fn_name != right_constraint.fn_name or
            !std.meta.eql(left_constraint.origin, right_constraint.origin) or
            !std.meta.eql(left_constraint.numeral, right_constraint.numeral))
        {
            return false;
        }
        try scratch.pending.append(scratch.allocator, .{ .left = left_constraint.fn_ty, .right = right_constraint.fn_ty });
    }
    return true;
}

/// Compare tag labels that may come from different canonical name stores.
pub fn tagLabelsMatch(
    source_names: *const canonical.CanonicalNameStore,
    source_tag: canonical.TagLabelId,
    target_names: *const canonical.CanonicalNameStore,
    target_tag: canonical.TagLabelId,
) bool {
    if (source_names == target_names and source_tag == target_tag) return true;
    return Ident.textEql(
        source_names.tagLabelText(source_tag),
        target_names.tagLabelText(target_tag),
    );
}

/// Public `CheckedNominalDeclaration` declaration.
///
/// `fa_start`/`fa_len` are a range into `CheckedTypeStore.type_id_pool` (POD).
/// Use `formalArgs` to obtain the backing slice.
pub const CheckedNominalDeclaration = struct {
    id: CheckedNominalDeclarationId,
    nominal: canonical.NominalTypeKey,
    /// CIR statement index of the declaration in its (content-identified)
    /// declaring module. A decl LOCATOR for reading declared field order from
    /// the module's CIR—never part of identity. Stable across modules
    /// because equal content identities imply byte-identical module source.
    source_statement: u32,
    declaration_root: CheckedTypeId,
    backing: CheckedTypeId,
    fa_start: u32 = 0,
    fa_len: u32 = 0,

    /// Range into `CheckedTypeStore.type_id_pool` for the resolved types of the
    /// declaration's unnamed (`_` / `_name`) padding fields, in declared order.
    /// Consumed by Monotype to reserve layout padding; excluded from the backing
    /// row. Use `paddingFieldTypes` to obtain the backing slice.
    pf_start: u32 = 0,
    pf_len: u32 = 0,

    /// Range into `CheckedTypeStore.declared_field_pool` for the source-declared
    /// nominal record field order.
    df_start: u32 = 0,
    df_len: u32 = 0,

    /// Range into `CheckedTypeStore.nominal_record_field_pool` for the
    /// declaration's top-level record field sequence.
    rf_start: u32 = 0,
    rf_len: u32 = 0,

    /// The declaration's formal args within its store's `type_id_pool`.
    pub fn formalArgs(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedTypeId {
        return storePool(pool_owner, CheckedTypeId)[self.fa_start .. self.fa_start + self.fa_len];
    }

    /// The declaration's padding field types within its store's `type_id_pool`.
    pub fn paddingFieldTypes(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedTypeId {
        return storePool(pool_owner, CheckedTypeId)[self.pf_start .. self.pf_start + self.pf_len];
    }

    /// The declaration's source-declared nominal record field order.
    pub fn declaredFields(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedDeclaredField {
        return storePool(pool_owner, CheckedDeclaredField)[self.df_start .. self.df_start + self.df_len];
    }

    /// The declaration's top-level record field sequence.
    pub fn declaredRecordFields(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedNominalRecordField {
        return storePool(pool_owner, CheckedNominalRecordField)[self.rf_start .. self.rf_start + self.rf_len];
    }
};

const CheckedStructuralRootEntry = struct {
    domain: CheckedStructuralKeyDomain,
    root: CheckedTypeId,
    next_plus_one: u32,
};

/// A module's source types as its checked tables read them: each source
/// variable type-root enumeration reached, at its checked type id, and each source
/// scheme (`forEachCheckedSourceScheme`) at its root's id.
pub const CheckedSourceTypes = struct {
    store: *CheckedTypeStore,
    /// The view of the module's types that computes keys against its names.
    view: CheckedTypeStoreView,
    /// The checked module the types belong to.
    current_owner: ModuleId,
    /// Resolves the modules the types name.
    resolver: ModuleResolver,
    /// The resolved variables of the module's source schemes, kept in debug
    /// builds only.
    source_schemes: SourceSchemes,

    const SourceSchemes = if (std.debug.runtime_safety) collections.DenseMap(Var, void) else void;

    pub fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        inputs: CheckedSourceTypeRootInputs,
        store: *CheckedTypeStore,
        view: CheckedTypeStoreView,
        current_owner: ModuleId,
        resolver: ModuleResolver,
    ) Allocator.Error!CheckedSourceTypes {
        var result = CheckedSourceTypes{
            .store = store,
            .view = view,
            .current_owner = current_owner,
            .resolver = resolver,
            .source_schemes = if (std.debug.runtime_safety) collections.DenseMap(Var, void).init(allocator) else {},
        };
        if (std.debug.runtime_safety) {
            errdefer result.source_schemes.deinit();
            const collector = SourceSchemeCollector{ .module = module, .schemes = &result.source_schemes };
            try forEachCheckedSourceScheme(module, inputs, &collector);
        }
        return result;
    }

    pub fn deinit(self: *CheckedSourceTypes) void {
        if (std.debug.runtime_safety) self.source_schemes.deinit();
    }

    const SourceSchemeCollector = struct {
        module: TypedCIR.Module,
        schemes: *collections.DenseMap(Var, void),

        pub fn visitScheme(self: *const SourceSchemeCollector, var_: Var) Allocator.Error!void {
            try self.schemes.put(self.module.typeStoreConst().resolveVar(var_).var_, {});
        }
    };

    /// The source scheme of `var_`, whose root publication published with a
    /// scheme of its own.
    pub fn schemeForSourceVar(self: *const CheckedSourceTypes, module: TypedCIR.Module, var_: Var) CheckedTypeSchemeId {
        const resolved = module.typeStoreConst().resolveVar(var_).var_;
        if (std.debug.runtime_safety and !self.source_schemes.contains(resolved)) {
            checkedModuleInvariant("source scheme was not published", .{});
        }
        return @fromBackingInt(@backingInt(type_ids.fromVar(resolved)));
    }

    /// The checked type of the source variable `var_`, or null when
    /// publication never reached it.
    pub fn rootForSourceVar(self: *const CheckedSourceTypes, module: TypedCIR.Module, var_: Var) ?CheckedTypeId {
        return self.store.reachedSourceRoot(module.typeStoreConst(), var_);
    }

    /// The checked type of a method binding's callable value, which type
    /// publication reached from the binding's class
    /// (`static_dispatch.classifyMethodBindings`).
    pub fn methodCallableType(self: *const CheckedSourceTypes, module: TypedCIR.Module, var_: Var) CheckedTypeId {
        return self.rootForSourceVar(module, var_) orelse
            checkedModuleInvariant("a method binding's callable type was not reached by type publication", .{});
    }
};

/// Where a store's interface capabilities are computed: a slot of its
/// module's analyses, over the store that owns the module's types.
pub const CapabilitySource = struct {
    analyses: *ModuleAnalyses,
    current_module: canonical.ModuleIdentityId,
    /// The checked module whose types the store holds.
    module: ModuleId,
};

/// Public `CheckedTypeStore` declaration.
///
/// Recursive types are stored as cyclic `CheckedTypeId` graphs with no implicit
/// tree structure, so every traversal of a store root must guard against cycles.
/// New `CheckedTypeId` traversals must be expressed through `checked_traverse.zig`
/// (`BoolPredicateTraversal`), which owns the visited/active memo and
/// guarantees the memo is written before a root is descended. Hand-rolled
/// visited/active sets are prohibited: they make
/// "read the memo but forget the write" compile cleanly and only fail on
/// recursive inputs.
pub const CheckedTypeStore = struct {
    /// Transient projection state (never serialized): non-null while a
    /// nominal use's backing template is being projected. Nested template
    /// references (including mutual recursion between declarations) must
    /// share this private id space so in-progress cycles close on their
    /// pending ids; when null, a nominal use forks a fresh private space—
    /// sharing template ids ACROSS uses would let Monotype's instantiation
    /// graphs bind one use's formals to another use's monos.
    template_use_active: ?*std.AutoHashMap(Var, CheckedTypeId) = null,

    /// Build-only immediate-payload interner. The fast hash selects a collision
    /// chain; equality is always checked against the stored payload, so this is
    /// exact even if two distinct payloads have the same hash. Child ids are
    /// already interned, making this the DAG's structural-consing index.
    structural_root_heads: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    structural_root_entries: std.ArrayListUnmanaged(CheckedStructuralRootEntry) = .empty,
    /// Build-only record of the identity instance each substitution-cloned
    /// flex or rigid root was minted from (clone → source). Substituting an
    /// identity-bearing root reserves distinct roots for the variables it
    /// leaves unsubstituted (`reserveDistinctSyntheticTypeRoot`), so a
    /// consumer relating an instantiated callable's variables back to the
    /// scheme that quantifies them reads through `identityOrigin`.
    identity_origins: collections.DenseMapUnmanaged(CheckedTypeId, CheckedTypeId) = .empty,
    /// Build-only set of every variable root filled through the synthetic
    /// path (`fillSyntheticTypeRoot`). Each must declare its origin in
    /// `identity_origins`; `identityOrigin` refuses one that has not.
    synthetic_variable_roots: collections.DenseMapUnmanaged(CheckedTypeId, void) = .empty,
    roots: collections.PublishedList(CheckedTypeRoot) = .empty,
    schemes: collections.PublishedList(CheckedTypeScheme) = .empty,
    /// Build-only scheme of each root and domain, so a root asked for its
    /// scheme twice names one scheme.
    scheme_by_root: std.AutoHashMapUnmanaged(SchemeRootKey, CheckedTypeSchemeId) = .empty,
    payloads: collections.PublishedList(StoredCheckedTypePayload) = .empty,
    /// Out-of-line rows of `alias` and `nominal` payloads.
    alias_row_pool: collections.PublishedList(StoredAlias) = .empty,
    nominal_row_pool: collections.PublishedList(StoredNominal) = .empty,
    nominal_declarations: collections.PublishedList(CheckedNominalDeclaration) = .empty,
    builtin_nominal_declarations: BuiltinNominalDeclarationIndex = empty_builtin_nominal_declarations,
    /// Flat pool of `CheckedTypeId`s for alias/nominal/function args, tuples,
    /// tag args, scheme generalized vars, and decl formal args.
    type_id_pool: collections.PublishedList(CheckedTypeId) = .empty,
    /// Flat pool of record fields backing record payloads.
    record_field_pool: collections.PublishedList(CheckedRecordField) = .empty,
    /// Flat pool of source-declared nominal record layout fields.
    declared_field_pool: collections.PublishedList(CheckedDeclaredField) = .empty,
    /// Flat pool of declared-order nominal record fields.
    nominal_record_field_pool: collections.PublishedList(CheckedNominalRecordField) = .empty,
    /// Flat pool of static-dispatch constraints backing flex/rigid variables.
    constraint_pool: collections.PublishedList(CheckedStaticDispatchConstraint) = .empty,
    /// Flat pool of (range-form) tags backing tag_union payloads.
    tag_pool: collections.PublishedList(StoredTag) = .empty,
    /// The text of every variable name the store's types hold, concatenated
    /// in id order; `var_name_ends` holds each name's end offset.
    var_name_bytes: collections.PublishedList(u8) = .empty,
    var_name_ends: collections.PublishedList(u32) = .empty,
    /// Writer-only: the id of each interned variable name, by its text (an
    /// owned copy). Rebuilt from the columns before the first insert into a
    /// store whose names were loaded or borrowed.
    var_name_ids: std.StringHashMapUnmanaged(u32) = .empty,
    /// Serializes the creation of synthesized types once other threads can
    /// read the store. A creation holds it from its first append until every
    /// type it made is complete, and never waits on a slot while holding it.
    writer_mutex: std.Io.Mutex = .init,
    /// Whether a creation holds `writer_mutex`; its roots are incomplete
    /// until it ends.
    creation_active: std.atomic.Value(bool) = .init(false),
    /// The number of roots complete when the last creation ended.
    committed_roots: std.atomic.Value(usize) = .init(0),
    /// Per column, the number of items the store held when it was
    /// published (`markPublished`); null while it is being built.
    published_counts: ?PublishedCounts = null,
    /// Where the module's interface capabilities are computed; null while
    /// the store is being published.
    capability_source: ?CapabilitySource = null,
    /// The canonical names the module's identifiers stand for in its sealed
    /// checked types, by identifier (`sealed_type_view.SealedNameRow`).
    sealed_names: std.ArrayList(sealed_type_view.SealedNameRow) = .empty,
    /// The checked identity and owner of each module identity the module's
    /// sealed types name, by the module's identity index.
    sealed_origins: std.ArrayList(sealed_type_view.SealedOriginRow) = .empty,
    /// The checked facts of each nominal declaration of the module's solver
    /// store, by declaration index.
    sealed_nominals: std.ArrayList(sealed_type_view.SealedNominalRow) = .empty,
    /// Per solver variable: whether publication reached it, and through which
    /// row-tail positions.
    sealed_var_facts: std.ArrayList(sealed_type_view.SealedVarFacts) = .empty,
    /// The module's environment, whose sealed solver store source ids name.
    sealed_env: ?*const ModuleEnv = null,
    /// The key slots of the module's source types, owned by its module.
    sealed_keys: ?*sealed_type_keys.SealedTypeKeys = null,
    /// The key slots of the store's synthesized types, owned by the store.
    synthesized_keys: ?*SynthesizedTypeKeys = null,
    /// The name store the store's types name while the store is being built
    /// in place; a view of a finished module names its own name store
    /// (`CheckedModule.typesView`).
    key_names: ?*const canonical.CanonicalNameStore = null,
    /// Build-only projection of each imported checked type into this store,
    /// by importing module and imported id, so an imported type projected
    /// twice names one root.
    projected_imports: std.AutoHashMapUnmanaged(ProjectedImportKey, CheckedTypeId) = .empty,
    /// The projection into this store of each declaration of another
    /// module whose backing a creation instantiated here, by declaring
    /// module and declaration. Read and written under the creation lock.
    projected_declarations: std.AutoHashMapUnmanaged(ProjectedDeclarationKey, ProjectedDeclaration) = .empty,

    const SchemeRootKey = struct { root: CheckedTypeId, domain: CheckedTypeSchemeDomain };
    const ProjectedImportKey = struct { module: [32]u8, ty: CheckedTypeId };
    const ProjectedDeclarationKey = struct { module: [32]u8, declaration: CheckedNominalDeclarationId };
    /// A declaration's formals and backing, projected together.
    const ProjectedDeclaration = struct { formals: []const CheckedTypeId, backing: CheckedTypeId };

    const Column = enum {
        roots,
        payloads,
        alias_row_pool,
        nominal_row_pool,
        schemes,
        nominal_declarations,
        type_id_pool,
        record_field_pool,
        declared_field_pool,
        nominal_record_field_pool,
        constraint_pool,
        tag_pool,
        var_name_bytes,
        var_name_ends,
        sealed_names,
        sealed_origins,
        sealed_nominals,
        sealed_var_facts,
    };

    /// Whether `column` is a `collections.PublishedList`, which tracks its
    /// own borrowing.
    fn isPublishedColumn(comptime column: Column) bool {
        return @hasField(@FieldType(CheckedTypeStore, @tagName(column)), "published_len");
    }

    /// Give a column that borrows its items storage of its own before it
    /// grows.
    fn ownColumn(self: *CheckedTypeStore, allocator: Allocator, comptime column: Column) Allocator.Error!void {
        if (comptime isPublishedColumn(column)) try @field(self, @tagName(column)).own(allocator);
    }

    /// The module's interface capabilities when a consumer has demanded
    /// them.
    fn publishedCapabilities(self: *const CheckedTypeStore) ?*const ModuleInterfaceCapabilities {
        const source = self.capability_source orelse return null;
        return source.analyses.peekInterfaceCapabilities();
    }

    const PublishedCounts = [@typeInfo(Column).@"enum".field_names.len]usize;

    /// Begin creating synthesized types in a store other threads read. The
    /// caller finishes the creation with `finishCreation` before any id it
    /// created leaves it, and waits on no slot in between; a creation that
    /// fails ends with `endCreation`, and the next creation to finish
    /// settles what it made.
    pub fn beginCreation(self: *CheckedTypeStore, io: std.Io) void {
        self.writer_mutex.lockUncancelable(io);
        collections.HeldLocks.acquired();
        if (std.debug.runtime_safety) CreationLedger.push(self);
        self.creation_active.store(true, .seq_cst);
    }

    /// Settle the representation of every type the store holds past the
    /// settled ones (`ModuleInterfaceCapabilities`), creating the
    /// capabilities of the local nominal instances first met there, then
    /// end the creation. Every type created since the module's interface
    /// capabilities were demanded is settled before its id can reach
    /// another thread.
    pub fn finishCreation(self: *CheckedTypeStore, allocator: Allocator, io: std.Io) Allocator.Error!void {
        if (self.capability_source) |source| {
            if (source.analyses.growableInterfaceCapabilities()) |capabilities| {
                var scratch = CheckedTypeStoreView.EqualityScratch.init(allocator);
                defer scratch.deinit();
                try capabilities.settleSynthesized(allocator, self, &scratch, null);
            }
        }
        self.endCreation(io);
    }

    /// End a creation. A creation that succeeded ends through
    /// `finishCreation`, which settles the types it made first.
    pub fn endCreation(self: *CheckedTypeStore, io: std.Io) void {
        self.committed_roots.store(self.roots.count(), .release);
        self.creation_active.store(false, .seq_cst);
        if (std.debug.runtime_safety) CreationLedger.pop(self);
        collections.HeldLocks.released();
        self.writer_mutex.unlock(io);
    }

    /// Whether this thread holds the store's creation, in debug builds.
    fn createdOnThisThread(self: *const CheckedTypeStore) bool {
        return CreationLedger.holds(self);
    }

    /// The stores whose creation each thread holds, innermost last; kept
    /// in debug builds only.
    const CreationLedger = struct {
        threadlocal var stores: [8]?*const CheckedTypeStore = @splat(null);
        threadlocal var len: u8 = 0;

        fn push(store: *const CheckedTypeStore) void {
            if (len == stores.len) checkedModuleInvariant("a thread nested more type store creations than the ledger holds", .{});
            stores[len] = store;
            len += 1;
        }

        fn pop(store: *const CheckedTypeStore) void {
            if (len == 0 or stores[len - 1] != store) checkedModuleInvariant("a type store creation ended out of order", .{});
            len -= 1;
            stores[len] = null;
        }

        fn holds(store: *const CheckedTypeStore) bool {
            for (stores[0..len]) |held| if (held == store) return true;
            return false;
        }
    };

    /// The number of leading roots whose types are complete: every root,
    /// unless a creation is under way in another thread.
    pub fn completeRootCount(self: *const CheckedTypeStore) usize {
        const count = self.roots.count();
        if (self.creation_active.load(.seq_cst)) return @min(count, self.committed_roots.load(.acquire));
        return count;
    }

    /// Text of a stored variable name id, or null when absent.
    pub fn varName(self: *const CheckedTypeStore, id: OptionalVarNameId) ?[]const u8 {
        const name_id = id.get() orelse return null;
        return self.varNameText(@backingInt(name_id));
    }

    /// The text of the variable name `id`. Safe from any thread.
    fn varNameText(self: *const CheckedTypeStore, id: u32) []const u8 {
        const ends = self.var_name_ends.items();
        const start = if (id == 0) 0 else ends[id - 1];
        return self.var_name_bytes.items()[start..ends[id]];
    }

    /// Materialize the public read-form payload for `id`. Slice fields alias the
    /// store's pools or the module's sealed solver store; no allocation.
    pub fn payload(self: *const CheckedTypeStore, id: CheckedTypeId) CheckedTypePayload {
        return self.view().payload(id);
    }

    /// The entry a synthesized id names.
    fn synthesizedIndex(self: *const CheckedTypeStore, id: CheckedTypeId) usize {
        const index = type_ids.synthesizedIndex(id);
        if (index >= self.payloads.items().len) checkedModuleInvariant("synthesized checked type id is out of range", .{});
        return index;
    }

    /// Append `items` to the pool holding `T`, returning their range.
    fn appendPool(self: *CheckedTypeStore, allocator: Allocator, comptime T: type, items: []const T) Allocator.Error!CheckedTypeRange {
        // Growth is where build-time aliasing slices are invalidated (see the
        // `payload`/`formalArgs` aliasing-invariant docs).
        const field = comptime poolField(CheckedTypeStore, T);
        if (items.len == 0) return .{ .start = 0, .len = 0 };
        try self.ownColumn(allocator, @field(Column, field));
        const pool = &@field(self, field);
        const start = std.math.cast(u32, pool.count()) orelse return error.OutOfMemory;
        const len = std.math.cast(u32, items.len) orelse return error.OutOfMemory;
        if (len > std.math.maxInt(u32) - start) return error.OutOfMemory;
        try pool.appendSlice(allocator, items);
        return .{ .start = start, .len = len };
    }

    /// Intern a variable name, returning its optional interner id (`.none`
    /// for an unnamed variable).
    fn internVarName(self: *CheckedTypeStore, allocator: Allocator, name: ?[]const u8) Allocator.Error!OptionalVarNameId {
        const text = name orelse return .none;
        const known = self.var_name_ends.count();
        if (self.var_name_ids.count() < known) {
            for (self.var_name_ids.count()..known) |id| {
                const owned = try allocator.dupe(u8, self.varNameText(@intCast(id)));
                errdefer allocator.free(owned);
                try self.var_name_ids.putNoClobber(allocator, owned, @intCast(id));
            }
        }
        if (self.var_name_ids.get(text)) |id| return .some(@fromBackingInt(id));
        const id = std.math.cast(u32, known) orelse return error.OutOfMemory;
        const end = std.math.cast(u32, self.var_name_bytes.count() + text.len) orelse return error.OutOfMemory;
        const owned = try allocator.dupe(u8, text);
        errdefer allocator.free(owned);
        try self.var_name_ids.ensureUnusedCapacity(allocator, 1);
        try self.ownColumn(allocator, .var_name_bytes);
        try self.ownColumn(allocator, .var_name_ends);
        try self.var_name_bytes.appendSlice(allocator, text);
        try self.var_name_ends.append(allocator, end);
        self.var_name_ids.putAssumeCapacityNoClobber(owned, id);
        return .some(@fromBackingInt(id));
    }

    /// Copy a build payload into the store's pools. The build's own slices
    /// are released only once every copy succeeded, so a failing commit leaves
    /// the build intact for its owner to release exactly once.
    fn commitPayload(self: *CheckedTypeStore, allocator: Allocator, raw_build: CheckedTypePayloadBuild) Allocator.Error!StoredCheckedTypePayload {
        const build = self.storedRepresentationBuild(raw_build);
        const stored: StoredCheckedTypePayload = switch (build) {
            .tag_union => |tu| blk: {
                const tags_start: u32 = @intCast(self.tag_pool.items().len);
                if (tu.tags.len != 0) try self.ownColumn(allocator, .tag_pool);
                try self.tag_pool.ensureUnusedCapacity(allocator, tu.tags.len);
                for (tu.tags) |tag| {
                    const args = try self.appendPool(allocator, CheckedTypeId, tag.args);
                    self.tag_pool.appendAssumeCapacity(.{ .name = tag.name, .args = args });
                }
                break :blk .{ .tag_union = .{
                    .tags = .{ .start = tags_start, .len = @intCast(tu.tags.len) },
                    .ext = tu.ext,
                } };
            },
            .pending,
            .field_kind,
            .err,
            .flex,
            .rigid,
            .alias,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .empty_tag_union,
            => try self.commitTypeData(allocator, StoredCheckedTypePayload, build),
        };
        freeOwned(allocator, build);
        return stored;
    }

    /// `build` as the store holds it: a nominal type read with its
    /// instance's box payload capability is held by its declaration, so the
    /// store's own representation of a type never depends on when the
    /// capabilities were demanded. The build's slices are shared.
    fn storedRepresentationBuild(self: *const CheckedTypeStore, build: CheckedTypePayloadBuild) CheckedTypePayloadBuild {
        if (build != .nominal) return build;
        const capability = switch (build.nominal.representation) {
            .local_box_payload_capability => |capability| capability.capability,
            .builtin, .local_declaration, .imported_declaration, .opaque_without_backing => return build,
        };
        const capabilities = self.publishedCapabilities() orelse
            checkedModuleInvariant("a nominal type read with a box payload capability was copied into a store whose capabilities were never demanded", .{});
        var stored = build;
        stored.nominal.representation = .{ .local_declaration = capabilities.boxPayloadCapability(capability).declaration };
        return stored;
    }

    /// The stored form of a build-form type value: each slice is copied into
    /// the pool holding its element type and each variable name is interned.
    /// The build stays owned by the caller.
    fn commitTypeData(self: *CheckedTypeStore, allocator: Allocator, comptime Stored: type, build: anytype) Allocator.Error!Stored {
        const Build = @TypeOf(build);
        if (comptime Stored == Build) {
            return build;
        } else if (comptime Stored == CheckedTypeRange) {
            return self.appendPool(allocator, @typeInfo(Build).pointer.child, build);
        } else if (comptime Stored == OptionalVarNameId) {
            return self.internVarName(allocator, build);
        } else if (comptime Stored == StoredAliasId or Stored == StoredNominalId) {
            const Row = if (Stored == StoredAliasId) StoredAlias else StoredNominal;
            const column: Column = if (Stored == StoredAliasId) .alias_row_pool else .nominal_row_pool;
            const row = try self.commitTypeData(allocator, Row, build);
            try self.ownColumn(allocator, column);
            const pool = &@field(self, @tagName(column));
            const id: Stored = @fromBackingInt(@intCast(pool.count()));
            try pool.append(allocator, row);
            return id;
        } else if (comptime @typeInfo(Stored) == .@"struct") {
            var stored: Stored = undefined;
            inline for (@typeInfo(Stored).@"struct".field_names) |name| {
                @field(stored, name) = try self.commitTypeData(allocator, @FieldType(Stored, name), @field(build, name));
            }
            return stored;
        } else {
            inline for (comptime std.enums.values(std.meta.Tag(Build))) |tag| {
                const name = @tagName(tag);
                if (comptime !store_serialize.comptimeStrEq(name, "tag_union")) {
                    if (build == tag) return @unionInit(Stored, name, try self.commitTypeData(allocator, @FieldType(Stored, name), @field(build, name)));
                }
            }
            unreachable; // commitPayload commits .tag_union itself; the loop above returns for every other tag
        }
    }

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        current_owner: ModuleId,
        imports: []const CheckedImport,
        available: []const ImportedModuleView,
        module_index: *const ModuleIndex,
        selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot,
        promoted_local_procedures: []const hoist_roots.PromotedLocalProcedure,
        sealed_keys: *sealed_type_keys.SealedTypeKeys,
    ) Allocator.Error!CheckedTypeStore {
        const import_views = CheckedImportViews{
            .current_owner = current_owner,
            .direct = imports,
            .available = available,
        };
        var store = CheckedTypeStore{};
        errdefer store.deinit(allocator);
        try sealed_type_view.buildColumns(allocator, module.moduleEnvConst(), names, import_views, store.sealedColumns());
        store.attachSealedTypes(module.moduleEnvConst(), sealed_keys, try SynthesizedTypeKeys.create(sealed_keys.allocator, sealed_keys.io, 0));
        store.key_names = names;
        var active = try CheckedSourceTypeRoots.init(allocator, module);
        defer active.deinit();
        var local_type_declarations = try LocalTypeDeclarationIndex.init(allocator, module, module_index);
        defer local_type_declarations.deinit();
        const publisher = CheckedTypeRootAppender{
            .allocator = allocator,
            .module = module,
            .names = names,
            .imports = import_views,
            .store = &store,
            .active = &active,
            .local_type_declarations = &local_type_declarations,
        };
        const root_inputs = CheckedSourceTypeRootInputs{
            .module_index = module_index,
            .selected_hoisted_roots = selected_hoisted_roots,
            .promoted_local_procedures = promoted_local_procedures,
        };
        try forEachCheckedSourceTypeRoot(module, root_inputs, &publisher);
        return store;
    }

    /// The record fields the store held when it was published.
    pub fn publishedRecordFields(self: *const CheckedTypeStore) @TypeOf(self.record_field_pool.items()) {
        const counts = self.published_counts orelse checkedModuleInvariant("a store's published record fields were read before it was published", .{});
        return self.record_field_pool.items()[0..counts[@backingInt(Column.record_field_pool)]];
    }

    /// The checked type of source variable `var_` of the store's module, or
    /// null when type-root enumeration never reached it.
    pub fn reachedSourceRoot(self: *const CheckedTypeStore, source_types: *const types.Store, var_: Var) ?CheckedTypeId {
        const resolved = source_types.resolveVar(var_).var_;
        if (!self.sealed_var_facts.items[@backingInt(resolved)].reached) return null;
        return type_ids.fromVar(resolved);
    }

    pub fn view(self: *const CheckedTypeStore) CheckedTypeStoreView {
        return .{
            // Readers never write through the view; a slot analysis that
            // creates types does so through the store under its writer lock.
            .store = @constCast(self),
            .builtin_nominal_declarations = &self.builtin_nominal_declarations,
            .sealed = if (self.sealed_env) |env| self.sealedView(env) else null,
            .sealed_keys = self.sealed_keys,
            .synthesized_keys = self.synthesized_keys,
            .names = self.key_names,
        };
    }

    /// The number of distinct checked types the store holds: an upper bound
    /// on the length of any acyclic chain through them.
    pub fn typeCount(self: *const CheckedTypeStore) usize {
        return self.view().typeCount();
    }

    pub fn rootForKey(self: *const CheckedTypeStore, key: canonical.CanonicalTypeKey) Allocator.Error!?CheckedTypeId {
        return try self.view().rootForKey(key);
    }

    pub fn rootKey(self: *const CheckedTypeStore, root: CheckedTypeId) Allocator.Error!canonical.CanonicalTypeKey {
        return try self.view().rootKey(root);
    }

    pub fn rootInfo(self: *const CheckedTypeStore, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        return try self.view().rootInfo(root);
    }

    /// Attach the module's sealed solver store and its key slots, which
    /// source ids read through, and its synthesized types' key slots, which
    /// the store owns from here on and which cover every root it holds.
    pub fn attachSealedTypes(self: *CheckedTypeStore, env: *const ModuleEnv, keys: *sealed_type_keys.SealedTypeKeys, synthesized: *SynthesizedTypeKeys) void {
        self.sealed_env = env;
        self.sealed_keys = keys;
        self.attachSynthesizedKeys(synthesized);
    }

    /// Give the store key slots for its synthesized types, covering every
    /// root it holds. The store owns them from here on.
    pub fn attachSynthesizedKeys(self: *CheckedTypeStore, synthesized: *SynthesizedTypeKeys) void {
        std.debug.assert(self.synthesized_keys == null);
        std.debug.assert(synthesized.slots.count() >= self.roots.count());
        self.synthesized_keys = synthesized;
    }

    /// Append a synthesized root row and its key slot.
    fn appendRootRow(self: *CheckedTypeStore, allocator: Allocator, recipe: CheckedTypeKeyRecipe) Allocator.Error!CheckedTypeId {
        const id: CheckedTypeId = type_ids.fromSynthesized(self.roots.items().len);
        try self.ownColumn(allocator, .roots);
        if (self.synthesized_keys) |keys| try keys.cover(self.roots.items().len + 1);
        try self.roots.append(allocator, .{ .id = id, .recipe = recipe });
        return id;
    }

    /// The checked types of `env`'s sealed solver store, the module this
    /// store was published for.
    pub fn sealedView(self: *const CheckedTypeStore, env: *const ModuleEnv) sealed_type_view.SealedTypeView {
        return .{
            .env = env,
            .names = self.sealed_names.items,
            .origins = self.sealed_origins.items,
            .nominals = self.sealed_nominals.items,
            .var_facts = self.sealed_var_facts.items,
        };
    }

    fn sealedColumns(self: *CheckedTypeStore) sealed_type_view.SealedTypeColumns {
        return .{
            .names = &self.sealed_names,
            .origins = &self.sealed_origins,
            .nominals = &self.sealed_nominals,
            .var_facts = &self.sealed_var_facts,
        };
    }

    /// The child roots a substituting clone of `root` rewrites.
    fn appendSubstitutionChildren(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        out: *std.ArrayList(CheckedTypeId),
    ) Allocator.Error!void {
        switch (self.payload(root)) {
            .pending, .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => |variable| for (0..variable.constraints.len()) |constraint_index| {
                const constraint = variable.constraints.get(constraint_index);
                try out.append(allocator, constraint.fn_ty);
            },
            .alias => |alias| {
                try out.append(allocator, alias.backing);
                try out.appendSlice(allocator, alias.args);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try out.append(allocator, field.ty);
                    if (field.kind.undeterminedVariable()) |variable| try out.append(allocator, variable);
                }
                try out.append(allocator, record.ext);
            },
            .tuple => |items| try out.appendSlice(allocator, items),
            .nominal => |nominal| {
                try out.appendSlice(allocator, nominal.args);
                try out.appendSlice(allocator, nominal.padding_field_types);
            },
            .function => |function| {
                try out.appendSlice(allocator, function.args);
                try out.append(allocator, function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try out.appendSlice(allocator, tag.args);
                }
                try out.append(allocator, tag_union.ext);
            },
        }
    }

    pub fn rootIsComposable(self: *const CheckedTypeStore, root: CheckedTypeId) Allocator.Error!bool {
        return (try self.rootInfo(root)).composable;
    }

    /// Whether `root` reaches a flex or rigid variable, found by walking the
    /// types it reaches; no key is computed.
    pub fn rootContainsIdentityVariables(self: *const CheckedTypeStore, root: CheckedTypeId) Allocator.Error!bool {
        return try self.view().rootHasIdentityVariables(root);
    }

    /// The identity instance a variable root stands for: the source a
    /// substitution cloned it from, followed through nested clones, or the
    /// root itself when it was published from a source variable or declared
    /// a fresh instance (`declareIdentityInstance`). A synthetic variable
    /// root that declared neither is refused rather than read as its own
    /// origin: a forgotten origin would make a cloned, quantified tail look
    /// unquantified and let a defaultable one classify `direct_closed`.
    /// Build-time only: serialized stores carry no origins.
    pub fn identityOrigin(self: *const CheckedTypeStore, root: CheckedTypeId) CheckedTypeId {
        var current = root;
        var remaining = self.identity_origins.count();
        while (true) {
            const source = self.identity_origins.get(current) orelse {
                if (self.synthetic_variable_roots.contains(current)) {
                    checkedModuleInvariant("synthetic checked variable root declared no identity origin", .{});
                }
                return current;
            };
            if (source == current) return current;
            if (remaining == 0) checkedModuleInvariant("checked identity origin chain was cyclic", .{});
            remaining -= 1;
            current = source;
        }
    }

    /// Declare a synthetic variable root a fresh identity instance (its own
    /// origin): a projection of an imported or viewed variable into this
    /// store, which no scheme of this module quantifies through another id.
    pub fn declareIdentityInstance(self: *CheckedTypeStore, allocator: Allocator, root: CheckedTypeId) Allocator.Error!void {
        try self.identity_origins.put(allocator, root, root);
    }

    fn structuralRootForPayload(
        self: *const CheckedTypeStore,
        domain: CheckedStructuralKeyDomain,
        fingerprint: u64,
        build_payload: CheckedTypePayloadBuild,
    ) ?CheckedTypeId {
        var entry_plus_one = self.structural_root_heads.get(fingerprint) orelse return null;
        while (entry_plus_one != 0) {
            const entry = self.structural_root_entries.items[entry_plus_one - 1];
            if (entry.domain == domain and
                checkedTypePayloadBuildEqlStored(build_payload, self.payload(entry.root))) return entry.root;
            entry_plus_one = entry.next_plus_one;
        }
        return null;
    }

    fn indexStructuralRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        domain: CheckedStructuralKeyDomain,
        root: CheckedTypeId,
        fingerprint: u64,
    ) Allocator.Error!void {
        const head = try self.structural_root_heads.getOrPut(allocator, fingerprint);
        if (!head.found_existing) head.value_ptr.* = 0;
        errdefer {
            if (!head.found_existing) _ = self.structural_root_heads.remove(fingerprint);
        }
        const previous_plus_one = head.value_ptr.*;
        const entry_index: u32 = @intCast(self.structural_root_entries.items.len);
        try self.structural_root_entries.append(allocator, .{
            .domain = domain,
            .root = root,
            .next_plus_one = previous_plus_one,
        });
        // Set the head only after the entry exists.
        head.value_ptr.* = entry_index + 1;
    }

    pub fn scheme(self: *const CheckedTypeStore, id: CheckedTypeSchemeId) CheckedTypeScheme {
        return self.view().scheme(id);
    }

    /// The scheme of `domain` over `root`. A source scheme is its root, a
    /// source variable, and has no row; a synthetic scheme's row is added
    /// the first time it is asked for. Row allocation preserves existing rows
    /// on failure.
    pub fn internScheme(
        self: *CheckedTypeStore,
        allocator: Allocator,
        domain: CheckedTypeSchemeDomain,
        root: CheckedTypeId,
    ) Allocator.Error!CheckedTypeSchemeId {
        switch (domain) {
            .source => {
                if (type_ids.isSynthesized(root)) checkedModuleInvariant("a source scheme was given a synthesized root", .{});
                return @fromBackingInt(@backingInt(root));
            },
            .synthetic => {},
        }
        const entry = try self.scheme_by_root.getOrPut(allocator, .{ .root = root, .domain = domain });
        if (entry.found_existing) return entry.value_ptr.*;
        errdefer _ = self.scheme_by_root.remove(.{ .root = root, .domain = domain });
        try self.ownColumn(allocator, .schemes);
        const id: CheckedTypeSchemeId = @fromBackingInt(@backingInt(type_ids.fromSynthesized(self.schemes.items().len)));
        try self.schemes.append(allocator, .{ .id = id, .domain = domain, .root = root });
        entry.value_ptr.* = id;
        return id;
    }

    pub fn appendSyntheticFunctionRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        kind: CheckedFunctionKind,
        args: []const CheckedTypeId,
        ret: CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const finalized_kind = finalizedFunctionKind(kind);
        var contains_identity_variables = try self.rootContainsIdentityVariables(ret);
        for (args) |arg| {
            contains_identity_variables = contains_identity_variables or try self.rootContainsIdentityVariables(arg);
        }
        const build_payload = CheckedTypePayloadBuild{ .function = .{
            .kind = finalized_kind,
            .args = args,
            .ret = ret,
        } };
        const fingerprint = if (!contains_identity_variables)
            checkedTypePayloadStructuralFingerprint(.synthetic_function, build_payload)
        else
            null;
        if (fingerprint) |value| {
            if (self.structuralRootForPayload(.synthetic_function, value, build_payload)) |existing| return existing;
        }
        try self.ownColumn(allocator, .payloads);
        try self.payloads.ensureUnusedCapacity(allocator, 1);
        const args_range = try self.appendPool(allocator, CheckedTypeId, args);
        const id = try self.appendRootRow(allocator, .synthetic_function);
        self.payloads.appendAssumeCapacity(.{ .function = .{
            .kind = finalized_kind,
            .args = args_range,
            .ret = ret,
        } });
        errdefer {
            _ = self.payloads.pop();
            _ = self.roots.pop();
        }
        if (fingerprint) |value| try self.indexStructuralRoot(allocator, .synthetic_function, id, value);
        return id;
    }

    pub fn appendSyntheticPayloadRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!CheckedTypeId {
        var owned_payload = build_payload;
        var payload_owned = true;
        errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

        const structurally_internable = !try checkedTypePayloadBuildContainsIdentityVariables(self, owned_payload);
        const fingerprint = if (structurally_internable)
            checkedTypePayloadStructuralFingerprint(.checked_payload, owned_payload)
        else
            null;
        if (fingerprint) |value| {
            if (self.structuralRootForPayload(.checked_payload, value, owned_payload)) |existing| {
                deinitCheckedTypePayloadBuild(allocator, &owned_payload);
                payload_owned = false;
                return existing;
            }
        }

        try self.ownColumn(allocator, .payloads);
        try self.payloads.ensureUnusedCapacity(allocator, 1);

        const stored = try self.commitPayload(allocator, owned_payload);
        payload_owned = false;
        const id = try self.appendRootRow(allocator, .payload);
        self.payloads.appendAssumeCapacity(stored);
        errdefer {
            _ = self.payloads.pop();
            _ = self.roots.pop();
        }
        if (fingerprint) |value| try self.indexStructuralRoot(allocator, .checked_payload, id, value);
        return id;
    }

    pub fn ensureEmptyRecordRoot(self: *CheckedTypeStore, allocator: Allocator) Allocator.Error!CheckedTypeId {
        return try self.appendSyntheticPayloadRoot(allocator, .empty_record);
    }

    /// Reserve a checked type root whose payload will be filled after recursive
    /// cloning has finished. Every reservation is a distinct root: two roots
    /// may hold one type, and a consumer that needs one entry per type asks
    /// `canonicalId` or `sameType`.
    ///
    /// A root later filled with a variable payload must declare its identity
    /// origin: the source variable it clones (`cloneCheckedTypeRootSubstituting`
    /// records it) or itself when it is a fresh instance
    /// (`declareIdentityInstance`). `fillSyntheticTypeRoot` marks every such
    /// root and `identityOrigin` refuses one without a declaration, so a
    /// producer that forgets fails loudly instead of letting a cloned,
    /// quantified row tail read as unquantified.
    pub fn reserveSyntheticTypeRoot(self: *CheckedTypeStore, allocator: Allocator) Allocator.Error!CheckedTypeId {
        return try self.reserveSyntheticTypeRootWithRecipe(allocator, .payload);
    }

    fn reserveSyntheticTypeRootWithRecipe(self: *CheckedTypeStore, allocator: Allocator, recipe: CheckedTypeKeyRecipe) Allocator.Error!CheckedTypeId {
        try self.ownColumn(allocator, .payloads);
        try self.payloads.ensureUnusedCapacity(allocator, 1);
        const id = try self.appendRootRow(allocator, recipe);
        self.payloads.appendAssumeCapacity(.pending);
        return id;
    }

    /// Fill a previously reserved checked type root with its explicit payload.
    pub fn fillSyntheticTypeRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!void {
        const index: usize = self.synthesizedIndex(root);
        if (self.payloads.items()[index] != .pending) {
            checkedModuleInvariant("synthetic checked type fill referenced an already-filled root", .{});
        }

        var owned_payload = build_payload;
        var build_owned = true;
        errdefer if (build_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);
        if (owned_payload == .flex or owned_payload == .rigid) {
            try self.synthetic_variable_roots.put(allocator, root, {});
        }
        try self.ownColumn(allocator, .payloads);
        const stored = try self.commitPayload(allocator, owned_payload);
        // A successful commit consumed the build's slices.
        build_owned = false;
        self.payloads.items()[index] = stored;
        errdefer self.payloads.items()[index] = .pending;
    }

    pub fn replaceTypeRootPayload(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!void {
        const index: usize = self.synthesizedIndex(root);

        var owned_payload = build_payload;
        var payload_owned = true;
        errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);
        const stored = try self.commitPayload(allocator, owned_payload);
        payload_owned = false;
        try self.ownColumn(allocator, .payloads);
        self.payloads.items()[index] = stored;
    }

    pub fn nominalDeclaration(
        self: *const CheckedTypeStore,
        nominal: canonical.NominalTypeKey,
    ) ?CheckedNominalDeclaration {
        for (self.nominal_declarations.items()) |declaration| {
            if (canonicalNominalTypeKeyEql(declaration.nominal, nominal)) return declaration;
        }
        return null;
    }

    /// The declared name of `declaration`'s type, read from its declaration
    /// root's nominal payload. Display metadata only: nominal identity
    /// (`canonical.NominalTypeKey`) never includes it.
    pub fn nominalDeclarationName(
        self: *const CheckedTypeStore,
        declaration: CheckedNominalDeclaration,
    ) canonical.TypeNameId {
        const root_payload = self.payload(declaration.declaration_root);
        if (root_payload != .nominal) {
            checkedModuleInvariant("nominal declaration root was not a nominal checked type", .{});
        }
        return root_payload.nominal.name;
    }

    pub fn nominalDeclarationById(
        self: *const CheckedTypeStore,
        id: CheckedNominalDeclarationId,
    ) CheckedNominalDeclaration {
        return self.view().nominalDeclarationById(id);
    }

    /// The backing of `nominal`, a type of this store (the types of module
    /// `module`), instantiated at its arguments in this store; null for a
    /// nominal with no declaration backing. A declaration of another module,
    /// which `resolver` resolves, is projected into this store once, its
    /// formals and backing together.
    pub fn ensureInstantiatedNominalBackingRootForPayload(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *canonical.CanonicalNameStore,
        module: ModuleId,
        resolver: ModuleResolver,
        nominal: CheckedNominalType,
    ) Allocator.Error!?CheckedTypeId {
        const site = nominalDeclarationSite(module, self.view(), resolver, nominal) orelse return null;
        if (site.module.eql(module)) return try self.ensureInstantiatedNominalBackingRoot(allocator, site.declaration, nominal.args);

        // nominal.args aliases type_id_pool, which projection may grow.
        const actuals = try allocator.dupe(CheckedTypeId, nominal.args);
        defer allocator.free(actuals);
        const projected = try self.projectDeclaration(allocator, names, resolver.require(site.module), site.declaration);
        if (projected.formals.len != actuals.len) {
            checkedModuleInvariant("nominal backing instantiation arity did not match declaration", .{});
        }
        if (checkedTypeIdSliceEql(projected.formals, actuals)) return projected.backing;
        var substitution = CheckedTypeSubstitution.init(allocator, projected.formals, actuals);
        defer substitution.deinit();
        return try self.cloneCheckedTypeRootSubstituting(allocator, projected.backing, &substitution);
    }

    /// The projection of `declaration`, a declaration of module `owner`,
    /// into this store.
    fn projectDeclaration(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *canonical.CanonicalNameStore,
        owner: ImportedModuleView,
        declaration: CheckedNominalDeclaration,
    ) Allocator.Error!ProjectedDeclaration {
        const key = ProjectedDeclarationKey{ .module = owner.key.digest().bytes, .declaration = declaration.id };
        if (self.projected_declarations.get(key)) |known| return known;
        var projector = CheckedTypeStoreImportProjector.init(allocator, self, names, owner);
        defer projector.deinit();
        const owner_formals = declaration.formalArgs(&owner.checked_types);
        const formals = try allocator.alloc(CheckedTypeId, owner_formals.len);
        errdefer allocator.free(formals);
        for (owner_formals, formals) |owner_formal, *formal| formal.* = try projector.project(owner_formal);
        const projected = ProjectedDeclaration{ .formals = formals, .backing = try projector.project(declaration.backing) };
        try self.projected_declarations.put(allocator, key, projected);
        return projected;
    }

    pub fn ensureInstantiatedNominalBackingRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        declaration: CheckedNominalDeclaration,
        actual_args: []const CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const formal_args = declaration.formalArgs(self);
        if (formal_args.len != actual_args.len) {
            checkedModuleInvariant("nominal backing instantiation arity did not match declaration", .{});
        }
        if (checkedTypeIdSliceEql(formal_args, actual_args)) return declaration.backing;

        // formalArgs and nominal args alias type_id_pool, which cloning may grow/reallocate; copy.
        const formals_copy = try allocator.dupe(CheckedTypeId, formal_args);
        defer allocator.free(formals_copy);
        const actuals_copy = try allocator.dupe(CheckedTypeId, actual_args);
        defer allocator.free(actuals_copy);

        var substitution = CheckedTypeSubstitution.init(allocator, formals_copy, actuals_copy);
        defer substitution.deinit();
        return try self.cloneCheckedTypeRootSubstituting(allocator, declaration.backing, &substitution);
    }

    /// Instantiate a declaration's unnamed padding field types with `actual_args`,
    /// returning a freshly-allocated slice the caller owns (in declared order).
    /// Mirrors `ensureInstantiatedNominalBackingRoot` for the padding channel so a
    /// type-parameterized padding field reserves its instantiated size.
    pub fn ensureInstantiatedPaddingFieldTypes(
        self: *CheckedTypeStore,
        allocator: Allocator,
        declaration: CheckedNominalDeclaration,
        actual_args: []const CheckedTypeId,
    ) Allocator.Error![]const CheckedTypeId {
        const padding_field_types = declaration.paddingFieldTypes(self);
        if (padding_field_types.len == 0) return &.{};
        const formal_args = declaration.formalArgs(self);
        if (formal_args.len != actual_args.len) {
            checkedModuleInvariant("nominal padding instantiation arity did not match declaration", .{});
        }
        const out = try allocator.alloc(CheckedTypeId, padding_field_types.len);
        errdefer allocator.free(out);
        if (checkedTypeIdSliceEql(formal_args, actual_args)) {
            @memcpy(out, padding_field_types);
            return out;
        }

        // paddingFieldTypes/formalArgs/actualArgs may alias type_id_pool, which cloning may
        // grow/reallocate; copy before the substitution loop.
        const padding_copy = try allocator.dupe(CheckedTypeId, padding_field_types);
        defer allocator.free(padding_copy);
        const formals_copy = try allocator.dupe(CheckedTypeId, formal_args);
        defer allocator.free(formals_copy);
        const actuals_copy = try allocator.dupe(CheckedTypeId, actual_args);
        defer allocator.free(actuals_copy);

        var substitution = CheckedTypeSubstitution.init(allocator, formals_copy, actuals_copy);
        defer substitution.deinit();
        for (padding_copy, 0..) |padding_ty, i| {
            out[i] = try self.cloneCheckedTypeRootSubstituting(allocator, padding_ty, &substitution);
        }
        return out;
    }

    /// The synthetic scheme naming `root`.
    pub fn ensureSchemeForRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
    ) Allocator.Error!CheckedTypeSchemeId {
        return try self.internScheme(allocator, .synthetic, root);
    }

    pub fn deinit(self: *CheckedTypeStore, allocator: Allocator) void {
        self.structural_root_entries.deinit(allocator);
        self.structural_root_heads.deinit(allocator);

        self.identity_origins.deinit(allocator);
        self.synthetic_variable_roots.deinit(allocator);
        self.scheme_by_root.deinit(allocator);
        self.projected_imports.deinit(allocator);
        var projected_declarations = self.projected_declarations.valueIterator();
        while (projected_declarations.next()) |projected| allocator.free(projected.formals);
        self.projected_declarations.deinit(allocator);
        var names = self.var_name_ids.keyIterator();
        while (names.next()) |name| allocator.free(name.*);
        self.var_name_ids.deinit(allocator);
        if (self.synthesized_keys) |keys| keys.destroy();
        inline for (@typeInfo(Column).@"enum".field_names) |field_name| {
            @field(self, field_name).deinit(allocator);
        }
        self.* = .{};
    }

    /// Record which types the store holds once it is published. A store is
    /// published before any other thread reads it, so the backings growth
    /// replaced so far are freed here.
    pub fn markPublished(self: *CheckedTypeStore) void {
        var counts: PublishedCounts = @splat(0);
        inline for (@typeInfo(Column).@"enum".field_names, 0..) |field_name, index| {
            if (comptime isPublishedColumn(@field(Column, field_name))) {
                counts[index] = @field(self, field_name).count();
            }
        }
        self.published_counts = counts;
    }

    /// Free the backings growth replaced while only the publishing thread
    /// could read the store.
    pub fn releaseSuperseded(self: *CheckedTypeStore, allocator: Allocator) void {
        inline for (@typeInfo(Column).@"enum".field_names) |field_name| {
            if (comptime isPublishedColumn(@field(Column, field_name))) @field(self, field_name).releaseSuperseded(allocator);
        }
    }

    /// Clone `source` with every formal replaced by its actual. Each cloned
    /// root is an explicit frame whose children are cloned in order, so the
    /// depth of the cloned type never becomes native call depth.
    fn cloneCheckedTypeRootSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        source: CheckedTypeId,
        substitution: *CheckedTypeSubstitution,
    ) Allocator.Error!CheckedTypeId {
        const Frame = struct {
            target: CheckedTypeId,
            snapshot: CheckedTypePayloadBuild,
            children_start: usize,
            next: usize,
            results_start: usize,
        };
        var frames: std.ArrayListUnmanaged(Frame) = .empty;
        defer {
            for (frames.items) |*frame| deinitCheckedTypePayloadBuild(allocator, &frame.snapshot);
            frames.deinit(allocator);
        }
        var children: std.ArrayListUnmanaged(CheckedTypeId) = .empty;
        defer children.deinit(allocator);
        var results: std.ArrayListUnmanaged(u32) = .empty;
        defer results.deinit(allocator);

        var pending_source: ?CheckedTypeId = source;
        while (true) {
            if (pending_source) |next_source| {
                pending_source = null;
                switch (try self.enterSubstitutingClone(allocator, next_source, substitution)) {
                    .done => |id| {
                        if (frames.items.len == 0) return id;
                        try results.append(allocator, @backingInt(id));
                    },
                    .clone => |clone| {
                        const children_start = children.items.len;
                        try appendCheckedTypeBuildChildren(allocator, &children, clone.snapshot);
                        try frames.append(allocator, .{
                            .target = clone.target,
                            .snapshot = clone.snapshot,
                            .children_start = children_start,
                            .next = children_start,
                            .results_start = results.items.len,
                        });
                    },
                }
                continue;
            }

            const frame = &frames.items[frames.items.len - 1];
            if (frame.next < children.items.len) {
                pending_source = children.items[frame.next];
                frame.next += 1;
                continue;
            }

            var cloned = CheckedTypeProjectResults{ .items = results.items[frame.results_start..] };
            const cloned_payload = try cloneCheckedTypeBuildPayload(allocator, frame.snapshot, &cloned);
            std.debug.assert(cloned.next == cloned.items.len);
            try self.fillSyntheticTypeRoot(allocator, frame.target, cloned_payload);

            var finished = frames.pop().?;
            deinitCheckedTypePayloadBuild(allocator, &finished.snapshot);
            children.shrinkRetainingCapacity(finished.children_start);
            results.shrinkRetainingCapacity(finished.results_start);
            if (frames.items.len == 0) return finished.target;
            try results.append(allocator, @backingInt(finished.target));
        }
    }

    fn cloneCheckedTypeIdSliceSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        ids: []const CheckedTypeId,
        substitution: *CheckedTypeSubstitution,
    ) Allocator.Error![]const CheckedTypeId {
        if (ids.len == 0) return &.{};
        // Cloning appends to the store's pools, which `ids` may alias.
        const out = try allocator.dupe(CheckedTypeId, ids);
        errdefer allocator.free(out);
        for (out) |*id| {
            id.* = try self.cloneCheckedTypeRootSubstituting(allocator, id.*, substitution);
        }
        return out;
    }

    /// A source that needs no new root answers at once; otherwise reserve its
    /// target root and snapshot its payload for the frame that clones it.
    fn enterSubstitutingClone(
        self: *CheckedTypeStore,
        allocator: Allocator,
        source: CheckedTypeId,
        substitution: *CheckedTypeSubstitution,
    ) Allocator.Error!union(enum) { done: CheckedTypeId, clone: struct { target: CheckedTypeId, snapshot: CheckedTypePayloadBuild } } {
        for (substitution.formals, substitution.actuals) |formal, actual| {
            if (source == formal) return .{ .done = actual };
        }
        if (substitution.images.get(source)) |existing| return .{ .done = existing };
        if (substitution.reaching) |reaching| {
            const reaches = reaching.get(source) orelse checkedModuleInvariant("a substituting clone reached a type its reach classification never saw", .{});
            if (!reaches) return .{ .done = source };
        }

        // A closed root cannot contain any formal. Reusing it is both the
        // semantic result and the DAG-preserving representation; hashing and
        // cloning it would manufacture an equal tree for no substitution.
        if (!try self.rootContainsIdentityVariables(source)) return .{ .done = source };

        const target = try self.reserveSyntheticTypeRoot(allocator);
        try substitution.images.put(source, target);

        // Snapshot the source into owned build memory: cloning its children
        // appends to the store's pools, which can reallocate slices that
        // alias them.
        var snapshot = try checkedTypePayloadToBuild(allocator, self.payload(source));
        errdefer deinitCheckedTypePayloadBuild(allocator, &snapshot);
        if (snapshot == .pending) checkedModuleInvariant("checked type substitution reached pending payload", .{});
        if (snapshot == .flex or snapshot == .rigid) {
            try self.identity_origins.put(allocator, target, source);
        }
        return .{ .clone = .{ .target = target, .snapshot = snapshot } };
    }

    fn checkedTypeSliceContainsIdentityVariables(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        roots: []const CheckedTypeId,
    ) Allocator.Error!bool {
        var context = CheckedTypeIdentityScan{ .store = self };
        return try checked_traverse.checkedTypeSliceContainsIdentityVariables(
            CheckedTypeId,
            CheckedTypeIdentityScan,
            allocator,
            &context,
            roots,
        );
    }

    fn checkedTypeContainsIdentityVariables(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        var context = CheckedTypeIdentityScan{ .store = self };
        return try checked_traverse.checkedTypeContainsIdentityVariables(
            CheckedTypeId,
            CheckedTypeIdentityScan,
            allocator,
            &context,
            root,
        );
    }
};

/// A build payload owning a copy of every slice `read` references, one level
/// deep (child type ids stay references). Free it with
/// `deinitCheckedTypePayloadBuild`.
fn checkedTypePayloadToBuild(allocator: Allocator, read: CheckedTypePayload) Allocator.Error!CheckedTypePayloadBuild {
    return switch (read) {
        // Read forms alias their owner module id; the build form owns it.
        .alias => |alias| .{ .alias = try dupeOwned(allocator, alias.toBuild()) },
        .nominal => |nominal| .{ .nominal = try dupeOwned(allocator, nominal.toBuild()) },
        .flex => |variable| .{ .flex = try variable.toBuild(allocator) },
        .rigid => |variable| .{ .rigid = try variable.toBuild(allocator) },
        .record => |record| .{ .record = try record.toBuild(allocator) },
        .tag_union => |tag_union| .{ .tag_union = try tag_union.toBuild(allocator) },
        inline .pending,
        .field_kind,
        .err,
        .tuple,
        .function,
        .empty_record,
        .empty_tag_union,
        => |value, tag| @unionInit(CheckedTypePayloadBuild, @tagName(tag), try dupeOwned(allocator, value)),
    };
}

/// The child type ids of a build payload, in the order a clone relates them.
fn appendCheckedTypeBuildChildren(
    allocator: Allocator,
    children: *std.ArrayListUnmanaged(CheckedTypeId),
    payload: CheckedTypePayloadBuild,
) Allocator.Error!void {
    switch (payload) {
        .pending, .field_kind, .err, .empty_record, .empty_tag_union => {},
        .flex, .rigid => |variable| for (variable.constraints) |constraint| try children.append(allocator, constraint.fn_ty),
        .alias => |alias| {
            try children.append(allocator, alias.backing);
            try children.appendSlice(allocator, alias.args);
        },
        .record => |record| {
            for (record.fields) |field| {
                try children.append(allocator, field.ty);
                if (field.kind.undeterminedVariable()) |variable| try children.append(allocator, variable);
            }
            try children.append(allocator, record.ext);
        },
        .tuple => |elems| try children.appendSlice(allocator, elems),
        .nominal => |nominal| {
            try children.appendSlice(allocator, nominal.args);
            try children.appendSlice(allocator, nominal.padding_field_types);
        },
        .function => |function| {
            try children.appendSlice(allocator, function.args);
            try children.append(allocator, function.ret);
        },
        .tag_union => |tag_union| {
            for (tag_union.tags) |tag| try children.appendSlice(allocator, tag.args);
            try children.append(allocator, tag_union.ext);
        },
    }
}

/// Assemble a snapshot payload over its cloned children, read in the order
/// `appendCheckedTypeBuildChildren` listed them.
fn cloneCheckedTypeBuildPayload(
    allocator: Allocator,
    payload: CheckedTypePayloadBuild,
    cloned: *CheckedTypeProjectResults,
) Allocator.Error!CheckedTypePayloadBuild {
    return switch (payload) {
        .pending => unreachable, // enterSubstitutingClone rejects pending snapshots before they are cloned
        .err => .err,
        .field_kind => |kind| .{ .field_kind = kind },
        .empty_record => .empty_record,
        .empty_tag_union => .empty_tag_union,
        .flex => |flex| .{ .flex = try cloneCheckedTypeBuildVariable(allocator, flex, cloned) },
        .rigid => |rigid| .{ .rigid = try cloneCheckedTypeBuildVariable(allocator, rigid, cloned) },
        .alias => |alias| blk: {
            const backing = cloned.typeId();
            break :blk .{ .alias = .{
                .name = alias.name,
                .origin_module = alias.origin_module,
                .owner_module = alias.owner_module,
                .source_decl = alias.source_decl,
                .builtin_origin = alias.builtin_origin,
                .backing = backing,
                .args = try cloned.typeIds(allocator, alias.args.len),
            } };
        },
        .record => |record| blk: {
            const fields: []const CheckedRecordField = if (record.fields.len == 0) &.{} else fields_blk: {
                const out = try allocator.alloc(CheckedRecordField, record.fields.len);
                for (record.fields, out) |field, *slot| {
                    const ty = cloned.typeId();
                    slot.* = .{
                        .name = field.name,
                        .ty = ty,
                        .kind = if (field.kind.undeterminedVariable() != null)
                            .undetermined(cloned.typeId())
                        else
                            field.kind,
                    };
                }
                break :fields_blk out;
            };
            break :blk .{ .record = .{ .fields = fields, .ext = cloned.typeId() } };
        },
        .tuple => |elems| .{ .tuple = try cloned.typeIds(allocator, elems.len) },
        .nominal => |nominal| blk: {
            const args = try cloned.typeIds(allocator, nominal.args.len);
            errdefer if (args.len != 0) allocator.free(args);
            const padding_field_types = try cloned.typeIds(allocator, nominal.padding_field_types.len);
            errdefer if (padding_field_types.len != 0) allocator.free(padding_field_types);
            break :blk .{ .nominal = .{
                .name = nominal.name,
                .origin_module = nominal.origin_module,
                .owner_module = nominal.owner_module,
                .source_decl = nominal.source_decl,
                .builtin = nominal.builtin,
                .is_opaque = nominal.is_opaque,
                .representation = nominal.representation,
                .args = args,
                .padding_field_types = padding_field_types,
                .declared_fields = try allocator.dupe(CheckedDeclaredField, nominal.declared_fields),
            } };
        },
        .function => |function| blk: {
            const args = try cloned.typeIds(allocator, function.args.len);
            break :blk .{ .function = .{
                .kind = finalizedFunctionKind(function.kind),
                .args = args,
                .ret = cloned.typeId(),
            } };
        },
        .tag_union => |tag_union| blk: {
            const tags: []const CheckedTag = if (tag_union.tags.len == 0) &.{} else tags_blk: {
                const out = try allocator.alloc(CheckedTag, tag_union.tags.len);
                for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
                errdefer freeOwned(allocator, out);
                for (tag_union.tags, out) |tag, *slot| {
                    slot.name = tag.name;
                    slot.args = try cloned.typeIds(allocator, tag.args.len);
                }
                break :tags_blk out;
            };
            break :blk .{ .tag_union = .{ .tags = tags, .ext = cloned.typeId() } };
        },
    };
}

fn cloneCheckedTypeBuildVariable(
    allocator: Allocator,
    variable: CheckedTypeVariableBuild,
    cloned: *CheckedTypeProjectResults,
) Allocator.Error!CheckedTypeVariableBuild {
    const name = if (variable.name) |name_text| try allocator.dupe(u8, name_text) else null;
    errdefer if (name) |owned| allocator.free(owned);
    const constraints: []const CheckedStaticDispatchConstraint = if (variable.constraints.len == 0) &.{} else blk: {
        const out = try allocator.alloc(CheckedStaticDispatchConstraint, variable.constraints.len);
        for (variable.constraints, out) |constraint, *slot| {
            slot.* = .{
                .fn_name = constraint.fn_name,
                .fn_ty = cloned.typeId(),
                .origin = constraint.origin,
                .numeral = constraint.numeral,
            };
        }
        break :blk out;
    };
    return .{
        .name = name,
        .constraints = constraints,
        .numeric_default_phase = variable.numeric_default_phase,
        .row_default = variable.row_default,
        .row_default_discharges_constraints = variable.row_default_discharges_constraints,
        .bounded_row_ext = variable.bounded_row_ext,
    };
}

const CheckedTypeIdentityScan = struct {
    store: *const CheckedTypeStore,

    pub fn visit(
        self: *@This(),
        children: anytype,
        root: CheckedTypeId,
    ) Allocator.Error!?bool {
        return try checked_traverse.checkedTypePayloadIdentityVariableChildren(
            .forbid,
            children,
            root,
            self.store.payload(root),
            self,
        );
    }
};

/// Free a build-form payload's individually-allocated slices/name.
fn deinitCheckedTypePayloadBuild(allocator: Allocator, payload: *CheckedTypePayloadBuild) void {
    freeOwned(allocator, payload.*);
    payload.* = .pending;
}

/// The finalized local type declaration each relative type name refers to.
pub const LocalTypeDeclarationIndex = struct {
    const FinalizedRelativeName = union(enum) {
        unique: CIR.Statement.Idx,
        ambiguous,
    };

    finalized_by_relative_name: std.AutoHashMap(Ident.Idx, FinalizedRelativeName),

    pub fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_index: *const ModuleIndex,
    ) Allocator.Error!LocalTypeDeclarationIndex {
        var finalized_by_relative_name = std.AutoHashMap(Ident.Idx, FinalizedRelativeName).init(allocator);
        errdefer finalized_by_relative_name.deinit();

        const module_env = module.moduleEnvConst();
        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            if (!module_index.reachesStatement(statement_idx)) continue;
            const statement = module.getStatement(statement_idx);
            const header_idx, const anno_idx = switch (statement) {
                .s_alias_decl => |alias| .{ alias.header, alias.anno },
                .s_nominal_decl => |nominal| .{ nominal.header, nominal.anno },
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_where_alias_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => continue,
            };
            if (anno_idx == .placeholder) continue;

            const header = module.moduleEnvConst().store.getTypeHeader(header_idx);
            if (finalized_by_relative_name.getPtr(header.relative_name)) |existing| {
                switch (existing.*) {
                    .unique => |existing_stmt| if (existing_stmt != statement_idx) {
                        existing.* = .ambiguous;
                    },
                    .ambiguous => {},
                }
            } else {
                try finalized_by_relative_name.put(header.relative_name, .{ .unique = statement_idx });
            }
        }

        return .{ .finalized_by_relative_name = finalized_by_relative_name };
    }

    pub fn deinit(self: *LocalTypeDeclarationIndex) void {
        self.finalized_by_relative_name.deinit();
    }

    pub fn finalizedStatementForReference(
        self: *const LocalTypeDeclarationIndex,
        module: TypedCIR.Module,
        statement_idx: CIR.Statement.Idx,
    ) CIR.Statement.Idx {
        const statement = module.getStatement(statement_idx);
        const header_idx, const anno_idx = switch (statement) {
            .s_alias_decl => |alias| .{ alias.header, alias.anno },
            .s_nominal_decl => |nominal| .{ nominal.header, nominal.anno },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => checkedModuleInvariant("checked declaration template lookup referenced a non-type declaration", .{}),
        };
        if (anno_idx != .placeholder) return statement_idx;

        const header = module.moduleEnvConst().store.getTypeHeader(header_idx);
        return switch (self.finalized_by_relative_name.get(header.relative_name) orelse {
            checkedModuleInvariant("checked declaration template lookup referenced an unfinalized associated type placeholder", .{});
        }) {
            .unique => |finalized| finalized,
            .ambiguous => checkedModuleInvariant("checked declaration template lookup referenced an ambiguous associated type placeholder", .{}),
        };
    }
};

fn appendCheckedNominalDeclarationFromStatement(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    statement_idx: CIR.Statement.Idx,
    header_idx: CIR.TypeHeader.Idx,
    anno_idx: CIR.TypeAnno.Idx,
    _: bool,
) Allocator.Error!void {
    if (anno_idx == .placeholder) return;
    if (!localNominalDeclarationIsValid(module.moduleEnvConst(), statement_idx)) return;

    const statement_root = try appendCheckedTypeRoot(
        allocator,
        module,
        store,
        active,
        ModuleEnv.varFrom(statement_idx),
    );
    const statement_payload = store.payload(statement_root);
    if (statement_payload != .nominal) {
        checkedModuleInvariant(
            "nominal declaration statement root was not a nominal checked type (source content {s})",
            .{@tagName(module.typeStoreConst().resolveVar(ModuleEnv.varFrom(statement_idx)).desc.content)},
        );
    }
    const statement_nominal = statement_payload.nominal;

    const module_env = module.moduleEnvConst();
    const header = module_env.store.getTypeHeader(header_idx);
    const header_args = module_env.store.sliceTypeAnnos(header.args);

    const formal_args = if (header_args.len == 0) &.{} else blk: {
        const out = try allocator.alloc(CheckedTypeId, header_args.len);
        errdefer allocator.free(out);
        for (header_args, 0..) |arg_anno, i| {
            out[i] = try appendCheckedTypeRoot(
                allocator,
                module,
                store,
                active,
                ModuleEnv.varFrom(arg_anno),
            );
        }
        break :blk out;
    };
    var formal_args_owned = formal_args.len != 0;
    errdefer if (formal_args_owned) allocator.free(formal_args);

    const declaration_formals = if (header_args.len == 0) &.{} else blk: {
        const out = try allocator.alloc(DeclarationFormal, header_args.len);
        errdefer allocator.free(out);
        for (header_args, formal_args, 0..) |arg_anno, formal_arg, i| {
            const arg = module_env.store.getTypeAnno(arg_anno);
            out[i] = .{
                .name = switch (arg) {
                    .rigid_var => |rigid| rigid.name,
                    .apply,
                    .rigid_var_lookup,
                    .underscore,
                    .lookup,
                    .tag_union,
                    .tag,
                    .tuple,
                    .record,
                    .@"fn",
                    .parens,
                    .malformed,
                    => checkedModuleInvariant("nominal declaration header argument was not a rigid type variable", .{}),
                },
                .root = formal_arg,
            };
        }
        break :blk out;
    };
    defer if (declaration_formals.len != 0) allocator.free(declaration_formals);

    const declared_record_fields = try declaredRecordFieldsFromDeclarationAnno(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        local_type_declarations,
        declaration_formals,
        anno_idx,
    );
    defer if (declared_record_fields.len != 0) allocator.free(declared_record_fields);

    const backing = try appendCheckedTypeRootFromDeclarationAnno(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        local_type_declarations,
        declaration_formals,
        anno_idx,
    );
    const padding_field_types = try paddingFieldTypesFromDeclaredRecordFields(allocator, declared_record_fields);
    var padding_field_types_owned = padding_field_types.len != 0;
    errdefer if (padding_field_types_owned) allocator.free(padding_field_types);

    const declared_fields = try declaredFieldsFromDeclarationAnno(
        allocator,
        module,
        names,
        padding_field_types,
        anno_idx,
    );
    var declared_fields_owned = declared_fields.len != 0;
    errdefer if (declared_fields_owned) allocator.free(declared_fields);

    const nominal_payload = CheckedTypePayloadBuild{ .nominal = .{
        .name = statement_nominal.name,
        .origin_module = statement_nominal.origin_module,
        .owner_module = statement_nominal.owner_module.*,
        .source_decl = @backingInt(statement_idx),
        .builtin = statement_nominal.builtin,
        .is_opaque = statement_nominal.is_opaque,
        .representation = if (statement_nominal.builtin) |builtin_id|
            .{ .builtin = builtin_id }
        else
            .{ .local_declaration = active.scratch.?.local_nominal_declarations.get(statement_idx) },
        .args = formal_args,
        .padding_field_types = padding_field_types,
        .declared_fields = declared_fields,
    } };
    formal_args_owned = false;
    padding_field_types_owned = false;
    declared_fields_owned = false;

    const declaration_root = try appendNominalDeclarationRootPayload(
        allocator,
        store,
        nominal_payload,
    );
    if (builtin.mode == .debug) {
        // The declaration's formals are exactly the roots its backing was
        // built over, so instantiating them substitutes into that backing.
        const declared_args = store.payload(declaration_root).nominal.args;
        std.debug.assert(declared_args.len == declaration_formals.len);
        for (declared_args, declaration_formals) |declared_arg, formal| {
            std.debug.assert(declared_arg == formal.root);
        }
    }
    try appendCheckedNominalDeclarationFromPayload(allocator, store, declaration_root, backing, declared_record_fields);
}

const DeclarationFormal = struct {
    name: Ident.Idx,
    root: CheckedTypeId,
};

fn declarationFormalRoot(formals: []const DeclarationFormal, name: Ident.Idx) ?CheckedTypeId {
    for (formals) |formal| {
        if (formal.name == name) return formal.root;
    }
    return null;
}

/// Build the checked type a type declaration's annotation denotes, with each
/// formal replaced by its root. Each composite annotation is an explicit
/// frame whose ops (child annotations and label interning) run in source
/// order, so annotation depth never becomes native call depth.
fn appendCheckedTypeRootFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error!CheckedTypeId {
    var walk = DeclarationAnnoWalk{
        .allocator = allocator,
        .module = module,
        .names = names,
        .imports = imports,
        .store = store,
        .active = active,
        .local_type_declarations = local_type_declarations,
    };
    defer walk.deinit();
    return try walk.run(declaration_formals, anno_idx);
}

/// A local alias expanded by declaration output: the alias statement and the
/// checked roots bound to its formals. The expansion depends on nothing else,
/// so a module publishes it once and every later reference reuses that root.
const AliasExpansionKey = struct {
    statement: CIR.Statement.Idx,
    args: []const CheckedTypeId,
};

const AliasExpansionContext = struct {
    /// Hash of the alias statement and its argument roots.
    pub fn hash(_: AliasExpansionContext, key: AliasExpansionKey) u64 {
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, key.statement);
        std.hash.autoHash(&hasher, key.args.len);
        for (key.args) |arg| std.hash.autoHash(&hasher, arg);
        return hasher.final();
    }

    /// Whether both keys expand the same alias at the same argument roots.
    pub fn eql(_: AliasExpansionContext, a: AliasExpansionKey, b: AliasExpansionKey) bool {
        if (a.statement != b.statement or a.args.len != b.args.len) return false;
        for (a.args, b.args) |left, right| {
            if (left != right) return false;
        }
        return true;
    }
};

const AliasExpansions = std.HashMapUnmanaged(AliasExpansionKey, CheckedTypeId, AliasExpansionContext, std.hash_map.default_max_load_percentage);

fn checkedRecordFieldLabelLessThan(names: *const canonical.CanonicalNameStore, lhs: CheckedRecordField, rhs: CheckedRecordField) bool {
    return names.recordFieldLabelTextLessThan(lhs.name, rhs.name);
}

fn checkedTagBuildLabelLessThan(names: *const canonical.CanonicalNameStore, lhs: CheckedTag, rhs: CheckedTag) bool {
    return names.tagLabelTextLessThan(lhs.name, rhs.name);
}

/// What a nominal declaration's annotation walk (`DeclarationAnnoWalk`) does
/// at one annotation, with parentheses stripped. The sealed type view reads
/// the same classification to enumerate the source roots the walk publishes.
pub const DeclarationAnnoNode = union(enum) {
    /// A leaf the walk publishes as the root of this source variable.
    leaf: Var,
    /// A rigid variable: the walk's formal of that name when it binds one,
    /// otherwise the root of `var_`. `name` is null for a lookup that does
    /// not refer to a rigid variable annotation.
    rigid: struct { name: ?Ident.Idx, var_: Var },
    /// A bare reference to a local alias, which the walk expands as its body.
    local_alias: struct { anno: CIR.TypeAnno.Idx, statement: CIR.Statement.Idx },
    /// A composite annotation the walk builds from its children.
    composite: CIR.TypeAnno.Idx,
};

/// Classify one declaration annotation for `DeclarationAnnoWalk`.
pub fn declarationAnnoNode(
    module: TypedCIR.Module,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    anno_idx: CIR.TypeAnno.Idx,
) DeclarationAnnoNode {
    const module_env = module.moduleEnvConst();
    var current = anno_idx;
    while (true) {
        switch (module_env.store.getTypeAnno(current)) {
            .parens => |parens| current = parens.anno,
            .tag_union, .tuple, .record, .@"fn", .apply => return .{ .composite = current },
            .lookup => |lookup| switch (lookup.base) {
                .local => |local| {
                    const finalized = local_type_declarations.finalizedStatementForReference(module, local.decl_idx);
                    if (module.getStatement(finalized) != .s_alias_decl) return .{ .leaf = ModuleEnv.varFrom(finalized) };
                    return .{ .local_alias = .{ .anno = current, .statement = finalized } };
                },
                .builtin,
                .external,
                .external_identity,
                .pending,
                => return .{ .leaf = ModuleEnv.varFrom(current) },
            },
            .rigid_var => |rigid| return .{ .rigid = .{ .name = rigid.name, .var_ = ModuleEnv.varFrom(current) } },
            .rigid_var_lookup => |lookup| return .{ .rigid = .{
                .name = switch (module_env.store.getTypeAnno(lookup.ref)) {
                    .rigid_var => |rigid| rigid.name,
                    .apply,
                    .rigid_var_lookup,
                    .underscore,
                    .lookup,
                    .tag_union,
                    .tag,
                    .tuple,
                    .record,
                    .@"fn",
                    .parens,
                    .malformed,
                    => null,
                },
                .var_ = ModuleEnv.varFrom(lookup.ref),
            } },
            .underscore,
            .tag,
            .malformed,
            => return .{ .leaf = ModuleEnv.varFrom(current) },
        }
    }
}

/// What a declaration annotation walk does with an applied type once its
/// arguments are walked.
pub const DeclarationApplyBase = union(enum) {
    /// The root of this source variable, used as written.
    leaf: Var,
    /// A local alias, which the walk expands as its body at the arguments.
    alias: CIR.Statement.Idx,
    /// A generic nominal whose root, the root of this source variable, the
    /// walk instantiates at the arguments.
    template: Var,
};

/// Classify the base of the applied type annotation `apply_anno`.
pub fn declarationApplyBase(
    module: TypedCIR.Module,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    apply_anno: CIR.TypeAnno.Idx,
    apply: @FieldType(CIR.TypeAnno, "apply"),
    arg_count: usize,
) DeclarationApplyBase {
    switch (apply.base) {
        .local => |local| {
            const finalized = local_type_declarations.finalizedStatementForReference(module, local.decl_idx);
            const statement = module.getStatement(finalized);
            if (arg_count == 0 and statement != .s_alias_decl) return .{ .leaf = ModuleEnv.varFrom(finalized) };
            switch (statement) {
                .s_alias_decl => return .{ .alias = finalized },
                .s_nominal_decl => {
                    if (finalized != local.decl_idx) {
                        checkedModuleInvariant("checked declaration template generic nominal application referenced an associated-type placeholder", .{});
                    }
                    return .{ .template = ModuleEnv.varFrom(finalized) };
                },
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_where_alias_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => checkedModuleInvariant("checked declaration template generic application referenced a non-type declaration", .{}),
            }
        },
        .builtin,
        .external,
        .external_identity,
        .pending,
        => return .{ .template = ModuleEnv.varFrom(apply_anno) },
    }
}

const DeclarationAnnoWalk = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    frames: std.ArrayListUnmanaged(Frame) = .empty,
    ops: std.ArrayListUnmanaged(Op) = .empty,
    results: std.ArrayListUnmanaged(u32) = .empty,

    const Op = union(enum) {
        /// An annotation walked under the frame's formals.
        child: CIR.TypeAnno.Idx,
        field_name: Ident.Idx,
        tag_name: Ident.Idx,
        /// This module's canonical identity, for a defaulted field's kind.
        default_module,
        /// The closed row an annotation without an extension ends in.
        empty_record,
        empty_tag_union,
    };

    /// A composite annotation whose ops occupy `ops[ops_start..]` and their
    /// results `results[results_start..]`.
    const Frame = struct {
        anno: CIR.TypeAnno.Idx,
        formals: []const DeclarationFormal,
        ops_start: usize,
        next: usize,
        results_start: usize,
        /// Set once a reference to a local alias has its arguments (at once
        /// for an unapplied one): the alias body then walks under these
        /// formals, which the frame owns.
        alias_body: ?AliasBody = null,
    };

    const AliasBody = struct {
        statement: CIR.Statement.Idx,
        formals: []DeclarationFormal,
        alias: CheckedAliasTypeBuild,
    };

    fn deinit(self: *DeclarationAnnoWalk) void {
        for (self.frames.items) |frame| {
            if (frame.alias_body) |body| if (body.formals.len != 0) self.allocator.free(body.formals);
        }
        self.frames.deinit(self.allocator);
        self.ops.deinit(self.allocator);
        self.results.deinit(self.allocator);
    }

    fn run(self: *DeclarationAnnoWalk, root_formals: []const DeclarationFormal, root: CIR.TypeAnno.Idx) Allocator.Error!CheckedTypeId {
        if (try self.enter(root_formals, root)) |id| return id;
        while (true) {
            const index = self.frames.items.len - 1;
            const frame = self.frames.items[index];
            if (frame.next < self.ops.items.len) {
                const op = self.ops.items[frame.next];
                self.frames.items[index].next += 1;
                const result: u32 = switch (op) {
                    .child => |child| if (try self.enter(self.childFormals(frame), child)) |id| @backingInt(id) else continue,
                    .field_name => |name| @backingInt(try self.names.internRecordFieldIdent(self.module.identStoreConst(), name)),
                    .tag_name => |name| @backingInt(try self.names.internTagIdent(self.module.identStoreConst(), name)),
                    .default_module => @backingInt(try self.names.internModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(self.module.moduleEnvConst().selfModuleIdentity()))),
                    .empty_record => @backingInt(try appendExplicitCheckedTypePayload(self.allocator, self.store, .empty_record)),
                    .empty_tag_union => @backingInt(try appendExplicitCheckedTypePayload(self.allocator, self.store, .empty_tag_union)),
                };
                try self.results.append(self.allocator, result);
                continue;
            }

            const id = (try self.finish(index)) orelse continue;
            const finished = self.frames.pop().?;
            if (finished.alias_body) |body| if (body.formals.len != 0) self.allocator.free(body.formals);
            self.ops.shrinkRetainingCapacity(finished.ops_start);
            self.results.shrinkRetainingCapacity(finished.results_start);
            if (self.frames.items.len == 0) return id;
            try self.results.append(self.allocator, @backingInt(id));
        }
    }

    /// Child annotations walk under the frame's formals, except an alias body,
    /// which walks under the alias's own.
    fn childFormals(_: *const DeclarationAnnoWalk, frame: Frame) []const DeclarationFormal {
        if (frame.alias_body) |body| return body.formals;
        return frame.formals;
    }

    /// The root a leaf annotation denotes, or null after pushing the frame
    /// that builds a composite one.
    fn enter(self: *DeclarationAnnoWalk, formals: []const DeclarationFormal, anno_idx: CIR.TypeAnno.Idx) Allocator.Error!?CheckedTypeId {
        const gpa = self.allocator;
        const module_env = self.module.moduleEnvConst();
        const ops_start = self.ops.items.len;
        const current = switch (declarationAnnoNode(self.module, self.local_type_declarations, anno_idx)) {
            .leaf => |var_| return try self.appendRoot(var_),
            .rigid => |rigid| {
                if (rigid.name) |name| if (declarationFormalRoot(formals, name)) |formal| return formal;
                return try self.appendRoot(rigid.var_);
            },
            .local_alias => |local_alias| {
                // A bare local alias walks its body like an alias
                // application with no arguments (checking rejects a bare
                // reference that leaves formals unapplied): the alias
                // declaration's own root keeps its output rows deferred
                // for its use sites, while a declaration body closes them
                // as written.
                if (self.publishedAliasExpansion(local_alias.statement, &.{})) |id| return id;
                const body = try self.beginAliasApplication(local_alias.statement, &.{});
                try self.ops.append(gpa, .{ .child = body.anno });
                try self.frames.append(gpa, .{
                    .anno = local_alias.anno,
                    .formals = formals,
                    .ops_start = ops_start,
                    .next = ops_start,
                    .results_start = self.results.items.len,
                    .alias_body = body.alias_body,
                });
                return null;
            },
            .composite => |composite| composite,
        };
        switch (module_env.store.getTypeAnno(current)) {
            .tag_union => |tag_union| {
                for (module_env.store.sliceTypeAnnos(tag_union.tags)) |tag_anno_idx| {
                    const tag = switch (module_env.store.getTypeAnno(tag_anno_idx)) {
                        .tag => |tag| tag,
                        .apply,
                        .rigid_var,
                        .rigid_var_lookup,
                        .underscore,
                        .lookup,
                        .tag_union,
                        .tuple,
                        .record,
                        .@"fn",
                        .parens,
                        .malformed,
                        => checkedModuleInvariant("nominal declaration tag union contained a non-tag annotation", .{}),
                    };
                    try self.ops.append(gpa, .{ .tag_name = tag.name });
                    for (module_env.store.sliceTypeAnnos(tag.args)) |arg| try self.ops.append(gpa, .{ .child = arg });
                }
                try self.ops.append(gpa, if (tag_union.ext) |ext| .{ .child = ext } else .empty_tag_union);
            },
            .record => |record| {
                // Unnamed (`_` / `_name`) fields are layout padding, not real fields; they
                // stay in the canonical record annotation (declared order) but are excluded
                // from the backing row here so they are never name-resolved or unified.
                for (module_env.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                    const field = module_env.store.getAnnoRecordField(field_idx);
                    if (field.is_unnamed) continue;
                    try self.ops.append(gpa, .{ .field_name = field.name });
                    try self.ops.append(gpa, .{ .child = field.ty });
                    if (!field.is_optional and field.default_value != null) try self.ops.append(gpa, .default_module);
                }
                try self.ops.append(gpa, if (record.ext) |ext| .{ .child = ext } else .empty_record);
            },
            .tuple => |tuple| for (module_env.store.sliceTypeAnnos(tuple.elems)) |elem| try self.ops.append(gpa, .{ .child = elem }),
            .@"fn" => |func| {
                for (module_env.store.sliceTypeAnnos(func.args)) |arg| try self.ops.append(gpa, .{ .child = arg });
                try self.ops.append(gpa, .{ .child = func.ret });
            },
            .apply => |apply| for (module_env.store.sliceTypeAnnos(apply.args)) |arg| try self.ops.append(gpa, .{ .child = arg }),
            .parens,
            .lookup,
            .rigid_var,
            .underscore,
            .rigid_var_lookup,
            .tag,
            .malformed,
            => unreachable, // declarationAnnoNode classifies these as leaves, rigid variables or bare local aliases
        }
        try self.frames.append(gpa, .{
            .anno = current,
            .formals = formals,
            .ops_start = ops_start,
            .next = ops_start,
            .results_start = self.results.items.len,
        });
        return null;
    }

    fn appendRoot(self: *DeclarationAnnoWalk, var_: Var) Allocator.Error!CheckedTypeId {
        return try appendCheckedTypeRoot(self.allocator, self.module, self.store, self.active, var_);
    }

    /// Build the frame's root from its op results; null when an alias
    /// application must first walk its alias body.
    fn finish(self: *DeclarationAnnoWalk, index: usize) Allocator.Error!?CheckedTypeId {
        const gpa = self.allocator;
        const frame = self.frames.items[index];
        const module_env = self.module.moduleEnvConst();
        var results = CheckedTypeProjectResults{ .items = self.results.items[frame.results_start..] };
        switch (module_env.store.getTypeAnno(frame.anno)) {
            .tag_union => |tag_union| {
                const tag_annos = module_env.store.sliceTypeAnnos(tag_union.tags);
                const tags: []const CheckedTag = if (tag_annos.len == 0) &.{} else blk: {
                    const out = try gpa.alloc(CheckedTag, tag_annos.len);
                    for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
                    errdefer freeOwned(gpa, out);
                    for (tag_annos, out) |tag_anno_idx, *slot| {
                        const tag = module_env.store.getTypeAnno(tag_anno_idx).tag;
                        slot.name = @fromBackingInt(@intCast(results.take()));
                        slot.args = try results.typeIds(gpa, module_env.store.sliceTypeAnnos(tag.args).len);
                    }
                    // A checked row is in lexicographic label order (design.md
                    // "Row, Nominal, Alias, And Opaque Authority"); the
                    // annotation lists its tags in source order.
                    std.sort.pdq(CheckedTag, out, @as(*const canonical.CanonicalNameStore, self.names), checkedTagBuildLabelLessThan);
                    break :blk out;
                };
                const ext = results.typeId();
                // A row with no tags over the closed empty row is that row.
                if (tags.len == 0 and self.store.payload(ext) == .empty_tag_union) return ext;
                // The payload owns `tags` and releases it on failure.
                return try appendExplicitCheckedTypePayload(gpa, self.store, .{ .tag_union = .{
                    .tags = tags,
                    .ext = ext,
                } });
            },
            .record => |record| {
                var named_count: usize = 0;
                for (module_env.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                    if (!module_env.store.getAnnoRecordField(field_idx).is_unnamed) named_count += 1;
                }
                const fields: []const CheckedRecordField = if (named_count == 0) &.{} else blk: {
                    const out = try gpa.alloc(CheckedRecordField, named_count);
                    var out_index: usize = 0;
                    for (module_env.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                        const field = module_env.store.getAnnoRecordField(field_idx);
                        if (field.is_unnamed) continue;
                        const name: canonical.RecordFieldLabelId = @fromBackingInt(@intCast(results.take()));
                        const ty = results.typeId();
                        out[out_index] = .{
                            .name = name,
                            .ty = ty,
                            // The annotation pins the kind concretely (design.md "Field
                            // Kinds"): `?:` publishes `optional`, `??` publishes `defaulted`
                            // with this module's canonical identity (design.md "Defaulted
                            // Fields"), plain `:` publishes `required`. `?:` and `??` never
                            // combine—canonicalization rejects `a ?: T ?? d` outright.
                            .kind = if (field.is_optional)
                                .optional
                            else if (field.default_value) |default_expr_idx|
                                .defaultedFromParts(@fromBackingInt(@intCast(results.take())), @backingInt(default_expr_idx))
                            else
                                .required,
                        };
                        out_index += 1;
                    }
                    // A checked row is in lexicographic label order; the
                    // annotation lists its fields in source order. A nominal
                    // declaration's source order is published separately as
                    // its declared fields (design.md "Nominal Record Field
                    // Order").
                    std.sort.pdq(CheckedRecordField, out, @as(*const canonical.CanonicalNameStore, self.names), checkedRecordFieldLabelLessThan);
                    break :blk out;
                };
                const ext = results.typeId();
                // A row with no fields over the closed empty row is that row.
                if (fields.len == 0 and self.store.payload(ext) == .empty_record) return ext;
                // The payload owns `fields` and releases it on failure.
                return try appendExplicitCheckedTypePayload(gpa, self.store, .{ .record = .{
                    .fields = fields,
                    .ext = ext,
                } });
            },
            .tuple => |tuple| {
                // The payload owns `elems` and releases it on failure.
                const elems = try results.typeIds(gpa, module_env.store.sliceTypeAnnos(tuple.elems).len);
                return try appendExplicitCheckedTypePayload(gpa, self.store, .{ .tuple = elems });
            },
            .@"fn" => |func| {
                const args = try results.typeIds(gpa, module_env.store.sliceTypeAnnos(func.args).len);
                // The payload owns `args` and releases it on failure.
                return try appendExplicitCheckedTypePayload(gpa, self.store, .{ .function = .{
                    .kind = if (func.effectful) .effectful else .pure,
                    .args = args,
                    .ret = results.typeId(),
                } });
            },
            .apply => |apply| return try self.finishApply(index, apply, &results),
            .lookup => {
                // Only a bare local alias pushes a lookup frame; its op is
                // the walked alias body.
                const body = frame.alias_body.?;
                var alias = body.alias;
                alias.backing = results.typeId();
                return try self.publishAliasExpansion(body.statement, alias);
            },
            .parens,
            .rigid_var,
            .underscore,
            .rigid_var_lookup,
            .tag,
            .malformed,
            => unreachable, // enter returns these leaf annotations' roots directly and pushes frames only for composite ones
        }
    }

    fn finishApply(
        self: *DeclarationAnnoWalk,
        index: usize,
        apply: @FieldType(CIR.TypeAnno, "apply"),
        results: *CheckedTypeProjectResults,
    ) Allocator.Error!?CheckedTypeId {
        const gpa = self.allocator;
        const frame = self.frames.items[index];
        const arg_count = self.module.moduleEnvConst().store.sliceTypeAnnos(apply.args).len;
        if (frame.alias_body) |body| {
            // The arguments, then the alias body walked under their formals.
            // The payload owns `payload_args` and releases it on failure.
            const payload_args = try results.typeIds(gpa, arg_count);
            const backing = results.typeId();
            var alias = body.alias;
            alias.backing = backing;
            alias.args = payload_args;
            return try self.publishAliasExpansion(body.statement, alias);
        }

        const actual_args = try results.typeIds(gpa, arg_count);
        defer if (actual_args.len != 0) gpa.free(actual_args);
        switch (declarationApplyBase(self.module, self.local_type_declarations, frame.anno, apply, arg_count)) {
            .leaf => |var_| return try self.appendRoot(var_),
            .alias => |statement| {
                if (self.publishedAliasExpansion(statement, actual_args)) |id| return id;
                const body = try self.beginAliasApplication(statement, actual_args);
                self.frames.items[index].alias_body = body.alias_body;
                try self.ops.append(gpa, .{ .child = body.anno });
                return null;
            },
            .template => |var_| {
                const generic_root = try self.appendRoot(var_);
                if (actual_args.len == 0) return generic_root;
                return try appendInstantiatedNamedApplicationFromTemplate(gpa, self.store, generic_root, actual_args);
            },
        }
    }

    /// Bind an alias declaration's formals to an application's arguments and
    /// publish its generic root; the reference then walks the alias body.
    fn beginAliasApplication(
        self: *DeclarationAnnoWalk,
        statement_idx: CIR.Statement.Idx,
        actual_args: []const CheckedTypeId,
    ) Allocator.Error!struct { alias_body: AliasBody, anno: CIR.TypeAnno.Idx } {
        const gpa = self.allocator;
        const alias = self.module.getStatement(statement_idx).s_alias_decl;
        if (alias.anno == .placeholder) {
            checkedModuleInvariant("checked declaration template alias application resolved to an unfinalized alias declaration", .{});
        }

        const module_env = self.module.moduleEnvConst();
        const header = module_env.store.getTypeHeader(alias.header);
        const header_args = module_env.store.sliceTypeAnnos(header.args);
        if (header_args.len != actual_args.len) {
            checkedModuleInvariant("checked declaration template alias application arity mismatch", .{});
        }

        const declaration_formals: []DeclarationFormal = if (header_args.len == 0) &.{} else blk: {
            const out = try gpa.alloc(DeclarationFormal, header_args.len);
            for (header_args, actual_args, out) |arg_anno, actual_arg, *slot| {
                slot.* = .{
                    .name = switch (module_env.store.getTypeAnno(arg_anno)) {
                        .rigid_var => |rigid| rigid.name,
                        .apply,
                        .rigid_var_lookup,
                        .underscore,
                        .lookup,
                        .tag_union,
                        .tag,
                        .tuple,
                        .record,
                        .@"fn",
                        .parens,
                        .malformed,
                        => checkedModuleInvariant("alias declaration header argument was not a rigid type variable", .{}),
                    },
                    .root = actual_arg,
                };
            }
            break :blk out;
        };
        errdefer if (declaration_formals.len != 0) gpa.free(declaration_formals);

        const generic_root = try self.appendRoot(ModuleEnv.varFrom(statement_idx));
        const generic_payload = self.store.payload(generic_root);
        if (generic_payload != .alias) {
            checkedModuleInvariant("checked declaration template alias application root was not an alias", .{});
        }
        const generic_alias = generic_payload.alias;
        return .{
            .alias_body = .{
                .statement = statement_idx,
                .formals = declaration_formals,
                .alias = .{
                    .name = generic_alias.name,
                    .origin_module = generic_alias.origin_module,
                    .owner_module = generic_alias.owner_module.*,
                    .source_decl = generic_alias.source_decl,
                    .builtin_origin = generic_alias.builtin_origin,
                    .backing = undefined,
                    .args = &.{},
                },
            },
            .anno = alias.anno,
        };
    }

    /// The root already published for this alias at these argument roots.
    fn publishedAliasExpansion(self: *DeclarationAnnoWalk, statement_idx: CIR.Statement.Idx, args: []const CheckedTypeId) ?CheckedTypeId {
        return self.active.scratch.?.alias_expansions.get(.{ .statement = statement_idx, .args = args });
    }

    /// Publish a walked alias expansion, which owns `alias.args`, and record
    /// it for every later reference at the same argument roots.
    fn publishAliasExpansion(self: *DeclarationAnnoWalk, statement_idx: CIR.Statement.Idx, alias: CheckedAliasTypeBuild) Allocator.Error!CheckedTypeId {
        const scratch = &self.active.scratch.?;
        const key_args: []const CheckedTypeId = if (alias.args.len == 0) &.{} else scratch.allocator.dupe(CheckedTypeId, alias.args) catch |err| {
            self.allocator.free(alias.args);
            return err;
        };
        errdefer if (key_args.len != 0) scratch.allocator.free(key_args);
        const id = try appendExplicitCheckedTypePayload(self.allocator, self.store, .{ .alias = alias });
        try scratch.alias_expansions.putNoClobber(scratch.allocator, .{ .statement = statement_idx, .args = key_args }, id);
        return id;
    }
};

fn appendInstantiatedNamedApplicationFromTemplate(
    allocator: Allocator,
    store: *CheckedTypeStore,
    generic_root: CheckedTypeId,
    actual_args: []const CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const generic_payload = store.payload(generic_root);
    return switch (generic_payload) {
        .alias => |alias| blk: {
            if (alias.args.len != actual_args.len) {
                checkedModuleInvariant("checked declaration template alias application arity mismatch", .{});
            }

            const formals = try allocator.dupe(CheckedTypeId, alias.args);
            defer allocator.free(formals);

            // Cloning appends to the store's pools, which the read form's
            // owner module aliases.
            const owner_module = alias.owner_module.*;
            var substitution = CheckedTypeSubstitution.init(allocator, formals, actual_args);
            defer substitution.deinit();
            const backing = try store.cloneCheckedTypeRootSubstituting(allocator, alias.backing, &substitution);

            // The payload owns `payload_args` and releases it on failure.
            const payload_args = if (actual_args.len == 0) &.{} else try allocator.dupe(CheckedTypeId, actual_args);

            break :blk try appendExplicitCheckedTypePayload(allocator, store, .{ .alias = .{
                .name = alias.name,
                .origin_module = alias.origin_module,
                .owner_module = owner_module,
                .source_decl = alias.source_decl,
                .builtin_origin = alias.builtin_origin,
                .backing = backing,
                .args = payload_args,
            } });
        },
        .nominal => |nominal| blk: {
            if (nominal.args.len != actual_args.len) {
                checkedModuleInvariant("checked declaration template nominal application arity mismatch", .{});
            }

            const formals = try allocator.dupe(CheckedTypeId, nominal.args);
            defer allocator.free(formals);
            // Cloning appends to the store's pools, which the read form's
            // owner module and declared fields alias.
            const owner_module = nominal.owner_module.*;
            const declared_fields = if (nominal.declared_fields.len == 0) &.{} else try allocator.dupe(CheckedDeclaredField, nominal.declared_fields);
            var declared_fields_owned = true;
            errdefer if (declared_fields_owned and declared_fields.len != 0) allocator.free(declared_fields);

            var substitution = CheckedTypeSubstitution.init(allocator, formals, actual_args);
            defer substitution.deinit();
            const padding_field_types = try store.cloneCheckedTypeIdSliceSubstituting(allocator, nominal.padding_field_types, &substitution);
            var padding_owned = true;
            errdefer if (padding_owned and padding_field_types.len != 0) allocator.free(padding_field_types);

            const payload_args = if (actual_args.len == 0) &.{} else try allocator.dupe(CheckedTypeId, actual_args);
            var payload_args_owned = true;
            errdefer if (payload_args_owned and payload_args.len != 0) allocator.free(payload_args);

            // The payload owns all three slices from here and releases them on failure.
            padding_owned = false;
            payload_args_owned = false;
            declared_fields_owned = false;
            break :blk try appendExplicitCheckedTypePayload(allocator, store, .{ .nominal = .{
                .name = nominal.name,
                .origin_module = nominal.origin_module,
                .owner_module = owner_module,
                .source_decl = nominal.source_decl,
                .builtin = nominal.builtin,
                .is_opaque = nominal.is_opaque,
                .representation = nominal.representation,
                .args = payload_args,
                .padding_field_types = padding_field_types,
                .declared_fields = declared_fields,
            } });
        },
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .record,
        .tuple,
        .function,
        .empty_record,
        .tag_union,
        .empty_tag_union,
        => checkedModuleInvariant("checked declaration template application did not resolve to a named type", .{}),
    };
}

/// Records a nominal declaration's top-level record fields in declared order.
/// Named fields refer to backing row entries by label; unnamed (`_` / `_name`)
/// fields carry their resolved type because they are layout padding, excluded
/// from the backing row.
fn declaredRecordFieldsFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error![]const CheckedNominalRecordField {
    // The backing record may be wrapped in parentheses; unwrap before reading its
    // fields (mirrors the parens handling in appendCheckedTypeRootFromDeclarationAnno).
    var record_anno = anno_idx;
    const record = while (true) {
        switch (module.moduleEnvConst().store.getTypeAnno(record_anno)) {
            .parens => |parens| record_anno = parens.anno,
            .record => |record| break record,
            .apply,
            .rigid_var,
            .rigid_var_lookup,
            .underscore,
            .lookup,
            .tag_union,
            .tag,
            .tuple,
            .@"fn",
            .malformed,
            => return &.{},
        }
    };
    const fields = module.moduleEnvConst().store.sliceAnnoRecordFields(record.fields);
    if (fields.len == 0) return &.{};
    const out = try allocator.alloc(CheckedNominalRecordField, fields.len);
    errdefer allocator.free(out);
    for (fields, 0..) |field_idx, index| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        out[index] = if (field.is_unnamed)
            .{ .padding = try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, field.ty) }
        else
            .{ .named = try names.internRecordFieldIdent(module.identStoreConst(), field.name) };
    }
    return out;
}

fn paddingFieldTypesFromDeclaredRecordFields(
    allocator: Allocator,
    declared_record_fields: []const CheckedNominalRecordField,
) Allocator.Error![]const CheckedTypeId {
    var padding_count: usize = 0;
    for (declared_record_fields) |field| {
        switch (field) {
            .named => {},
            .padding => padding_count += 1,
        }
    }
    if (padding_count == 0) return &.{};

    const out = try allocator.alloc(CheckedTypeId, padding_count);
    errdefer allocator.free(out);
    var out_index: usize = 0;
    for (declared_record_fields) |field| {
        switch (field) {
            .named => {},
            .padding => |ty| {
                out[out_index] = ty;
                out_index += 1;
            },
        }
    }
    return out;
}

fn declaredFieldsFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    padding_field_types: []const CheckedTypeId,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error![]const CheckedDeclaredField {
    var record_anno = anno_idx;
    const record = while (true) {
        const anno = module.moduleEnvConst().store.getTypeAnno(record_anno);
        if (anno == .parens) {
            record_anno = anno.parens.anno;
        } else if (anno == .record) {
            break anno.record;
        } else return &.{};
    };
    const fields = module.moduleEnvConst().store.sliceAnnoRecordFields(record.fields);
    if (fields.len == 0) return &.{};

    const out = try allocator.alloc(CheckedDeclaredField, fields.len);
    errdefer allocator.free(out);
    var padding_cursor: u32 = 0;
    for (fields, 0..) |field_idx, i| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        out[i] = if (field.is_unnamed) blk: {
            if (padding_cursor >= padding_field_types.len) {
                checkedModuleInvariant("nominal declaration had more unnamed fields than recorded padding types", .{});
            }
            defer padding_cursor += 1;
            break :blk .{ .padding = padding_cursor };
        } else .{
            .named = try names.internRecordFieldIdent(module.identStoreConst(), field.name),
        };
    }
    if (padding_cursor != padding_field_types.len) {
        checkedModuleInvariant("nominal declaration recorded padding types that were missing from declared field order", .{});
    }
    return out;
}

fn checkedTypeIdsContainIdentityVariables(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    ids: []const CheckedTypeId,
) Allocator.Error!bool {
    var context = CheckedTypeIdentityScan{ .store = store };
    return try checked_traverse.checkedTypeSliceContainsIdentityVariables(
        CheckedTypeId,
        CheckedTypeIdentityScan,
        allocator,
        &context,
        ids,
    );
}

fn checkedTypeContainsIdentityVariablesPayloads(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var context = CheckedTypeIdentityScan{ .store = store };
    return try checked_traverse.checkedTypeContainsIdentityVariables(
        CheckedTypeId,
        CheckedTypeIdentityScan,
        allocator,
        &context,
        root,
    );
}

fn appendExplicitCheckedTypePayload(
    allocator: Allocator,
    store: *CheckedTypeStore,
    build_payload: CheckedTypePayloadBuild,
) Allocator.Error!CheckedTypeId {
    var owned_payload = store.storedRepresentationBuild(build_payload);
    var payload_owned = true;
    errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

    const structurally_internable = !try checkedTypePayloadBuildContainsIdentityVariables(store, owned_payload);
    const fingerprint = if (structurally_internable)
        checkedTypePayloadStructuralFingerprint(.checked_payload, owned_payload)
    else
        null;
    if (fingerprint) |value| {
        if (store.structuralRootForPayload(.checked_payload, value, owned_payload)) |existing| {
            deinitCheckedTypePayloadBuild(allocator, &owned_payload);
            payload_owned = false;
            return existing;
        }
    }

    try store.ownColumn(allocator, .payloads);
    try store.payloads.ensureUnusedCapacity(allocator, 1);
    const stored = try store.commitPayload(allocator, owned_payload);
    payload_owned = false;
    const id = try store.appendRootRow(allocator, .payload);
    store.payloads.appendAssumeCapacity(stored);
    if (fingerprint) |value| try store.indexStructuralRoot(allocator, .checked_payload, id, value);
    return id;
}

fn appendNominalDeclarationRootPayload(
    allocator: Allocator,
    store: *CheckedTypeStore,
    build_payload: CheckedTypePayloadBuild,
) Allocator.Error!CheckedTypeId {
    var owned_payload = build_payload;
    var payload_owned = true;
    errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

    if (owned_payload != .nominal) {
        checkedModuleInvariant("nominal declaration root payload was not nominal", .{});
    }
    try store.ownColumn(allocator, .payloads);
    try store.payloads.ensureUnusedCapacity(allocator, 1);
    const stored = try store.commitPayload(allocator, owned_payload);
    payload_owned = false;
    const id = try store.appendRootRow(allocator, .payload);
    store.payloads.appendAssumeCapacity(stored);
    return id;
}

fn appendCheckedNominalDeclarationFromPayload(
    allocator: Allocator,
    store: *CheckedTypeStore,
    root: CheckedTypeId,
    backing: CheckedTypeId,
    declared_record_fields: []const CheckedNominalRecordField,
) Allocator.Error!void {
    const declarations = &store.nominal_declarations;
    const root_payload = store.payload(root);
    if (root_payload != .nominal) {
        checkedModuleInvariant("nominal declaration root was not a nominal checked type", .{});
    }
    const nominal = root_payload.nominal;

    const nominal_key = checkedNominalTypeKey(nominal);
    for (declarations.items()) |existing| {
        if (canonicalNominalTypeKeyEql(existing.nominal, nominal_key)) {
            if (existing.backing == backing and
                try checkedTypeRootKeySliceEql(store, existing.formalArgs(store), nominal.args) and
                try checkedTypeRootKeySliceEql(store, existing.paddingFieldTypes(store), nominal.padding_field_types) and
                checkedDeclaredFieldSliceEql(existing.declaredFields(store), nominal.declared_fields) and
                try checkedNominalRecordFieldRootKeySliceEql(store, existing.declaredRecordFields(store), declared_record_fields))
            {
                indexBuiltinNominalDeclaration(store, nominal.builtin, existing.id);
                return;
            }
            checkedModuleInvariant("checked module attempted to publish conflicting nominal declarations", .{});
        }
    }

    // nominal.args / nominal.padding_field_types alias type_id_pool; copy before
    // appending into that pool (appends may reallocate and dangle the aliases).
    const args_copy = try allocator.dupe(CheckedTypeId, nominal.args);
    defer allocator.free(args_copy);
    const padding_copy = try allocator.dupe(CheckedTypeId, nominal.padding_field_types);
    defer allocator.free(padding_copy);
    const declared_copy = try allocator.dupe(CheckedDeclaredField, nominal.declared_fields);
    defer allocator.free(declared_copy);
    const fa = try store.appendPool(allocator, CheckedTypeId, args_copy);
    const pf = try store.appendPool(allocator, CheckedTypeId, padding_copy);
    const df = try store.appendPool(allocator, CheckedDeclaredField, declared_copy);
    const rf = try store.appendPool(allocator, CheckedNominalRecordField, declared_record_fields);
    const declaration_id: CheckedNominalDeclarationId = @fromBackingInt(@intCast(@as(u32, @intCast(declarations.count()))));
    try store.ownColumn(allocator, .nominal_declarations);
    try declarations.append(allocator, .{
        .id = declaration_id,
        .nominal = nominal_key,
        .source_statement = nominal.source_decl,
        .declaration_root = root,
        .backing = backing,
        .fa_start = fa.start,
        .fa_len = fa.len,
        .pf_start = pf.start,
        .pf_len = pf.len,
        .df_start = df.start,
        .df_len = df.len,
        .rf_start = rf.start,
        .rf_len = rf.len,
    });
    indexBuiltinNominalDeclaration(store, nominal.builtin, declaration_id);
}

fn indexBuiltinNominalDeclaration(
    store: *CheckedTypeStore,
    builtin_nominal: ?CheckedBuiltinNominal,
    declaration_id: CheckedNominalDeclarationId,
) void {
    const owner = builtin_nominal orelse return;
    const slot = &store.builtin_nominal_declarations[@backingInt(owner)];
    const entry = @backingInt(declaration_id) + 1;
    if (slot.* != 0 and slot.* != entry) {
        checkedModuleInvariant("builtin identity referenced conflicting nominal declarations", .{});
    }
    slot.* = entry;
}

fn checkedTypeIdSliceEql(a: []const CheckedTypeId, b: []const CheckedTypeId) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (left != right) return false;
    }
    return true;
}

fn checkedDeclaredFieldSliceEql(a: []const CheckedDeclaredField, b: []const CheckedDeclaredField) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (!std.meta.eql(left, right)) return false;
    }
    return true;
}

fn checkedTypeRootKeySliceEql(store: *const CheckedTypeStore, a: []const CheckedTypeId, b: []const CheckedTypeId) Allocator.Error!bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (!std.meta.eql((try store.rootKey(left)).bytes, (try store.rootKey(right)).bytes)) return false;
    }
    return true;
}

const CheckedStructuralKeyDomain = enum {
    source,
    checked_payload,
    synthetic_function,
};

/// Non-cryptographic on purpose: this fingerprint only selects a
/// `structural_root_heads` chain, and `structuralRootForPayload` accepts an
/// entry only after `checkedTypePayloadBuildEqlStored` compares the full
/// payload, so a crafted collision costs a chain walk and never an identity.
/// It is never serialized. Identity across modules and caches is the SHA-256
/// `CheckedTypeRoot.key`.
fn checkedTypePayloadStructuralFingerprint(
    domain: CheckedStructuralKeyDomain,
    payload: CheckedTypePayloadBuild,
) u64 {
    var hasher = std.hash.Wyhash.init(0x726f635f74797065);
    std.hash.autoHash(&hasher, domain);
    std.hash.autoHashStrat(&hasher, payload, .DeepRecursive);
    return hasher.final();
}

fn checkedTypePayloadBuildContainsIdentityVariables(
    store: *const CheckedTypeStore,
    payload: CheckedTypePayloadBuild,
) Allocator.Error!bool {
    return switch (payload) {
        .pending => true,
        .flex, .rigid => true,
        .field_kind, .err, .empty_record, .empty_tag_union => false,
        .alias => |alias| blk: {
            if (try store.rootContainsIdentityVariables(alias.backing)) break :blk true;
            for (alias.args) |arg| {
                if (try store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            break :blk false;
        },
        .record => |record| blk: {
            for (record.fields) |field| {
                if (field.kind.undeterminedVariable()) |variable| {
                    if (try store.rootContainsIdentityVariables(variable)) break :blk true;
                }
                if (try store.rootContainsIdentityVariables(field.ty)) break :blk true;
            }
            break :blk try store.rootContainsIdentityVariables(record.ext);
        },
        .tuple => |items| blk: {
            for (items) |item| {
                if (try store.rootContainsIdentityVariables(item)) break :blk true;
            }
            break :blk false;
        },
        .nominal => |nominal| blk: {
            for (nominal.args) |arg| {
                if (try store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            for (nominal.padding_field_types) |padding| {
                if (try store.rootContainsIdentityVariables(padding)) break :blk true;
            }
            break :blk false;
        },
        .function => |function| blk: {
            for (function.args) |arg| {
                if (try store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            break :blk try store.rootContainsIdentityVariables(function.ret);
        },
        .tag_union => |tag_union| blk: {
            for (tag_union.tags) |tag| {
                for (tag.args) |arg| {
                    if (try store.rootContainsIdentityVariables(arg)) break :blk true;
                }
            }
            break :blk try store.rootContainsIdentityVariables(tag_union.ext);
        },
    };
}

fn checkedRecordFieldSliceEql(a: []const CheckedRecordField, b: CheckedRecordFields) bool {
    if (a.len != b.len()) return false;
    for (a, 0..) |left, index| {
        const right = b.get(index);
        if (left.name != right.name or left.ty != right.ty or !std.meta.eql(left.kind, right.kind)) return false;
    }
    return true;
}

fn checkedTagBuildSliceEqlStored(build_tags: []const CheckedTag, stored_tags: CheckedTags) bool {
    if (build_tags.len != stored_tags.len()) return false;
    for (build_tags, 0..) |build_tag, index| {
        const stored_tag = stored_tags.get(index);
        if (build_tag.name != stored_tag.name or !checkedTypeIdSliceEql(build_tag.args, stored_tag.args)) return false;
    }
    return true;
}

fn checkedTypePayloadBuildEqlStored(build: CheckedTypePayloadBuild, stored: CheckedTypePayload) bool {
    return switch (build) {
        .pending => stored == .pending,
        .err => stored == .err,
        .field_kind => |kind| stored == .field_kind and stored.field_kind == kind,
        .empty_record => stored == .empty_record,
        .empty_tag_union => stored == .empty_tag_union,
        .flex, .rigid => checkedModuleInvariant(
            "identity-bearing payload reached the closed structural interner",
            .{},
        ),
        .alias => |left| blk: {
            if (stored != .alias) break :blk false;
            const right = stored.alias;
            break :blk left.name == right.name and
                left.origin_module == right.origin_module and
                left.owner_module.eql(right.owner_module.*) and
                left.source_decl == right.source_decl and
                left.builtin_origin == right.builtin_origin and
                left.backing == right.backing and
                checkedTypeIdSliceEql(left.args, right.args);
        },
        .record => |left| blk: {
            if (stored != .record) break :blk false;
            const right = stored.record;
            break :blk left.ext == right.ext and checkedRecordFieldSliceEql(left.fields, right.fields);
        },
        .tuple => |left| blk: {
            if (stored != .tuple) break :blk false;
            break :blk checkedTypeIdSliceEql(left, stored.tuple);
        },
        .nominal => |left| blk: {
            if (stored != .nominal) break :blk false;
            const right = stored.nominal;
            break :blk left.name == right.name and
                left.origin_module == right.origin_module and
                left.owner_module.eql(right.owner_module.*) and
                left.source_decl == right.source_decl and
                left.builtin == right.builtin and
                left.is_opaque == right.is_opaque and
                std.meta.eql(left.representation, right.representation) and
                checkedTypeIdSliceEql(left.args, right.args) and
                checkedTypeIdSliceEql(left.padding_field_types, right.padding_field_types);
        },
        .function => |left| blk: {
            if (stored != .function) break :blk false;
            const right = stored.function;
            break :blk finalizedFunctionKind(left.kind) == finalizedFunctionKind(right.kind) and
                left.ret == right.ret and
                checkedTypeIdSliceEql(left.args, right.args);
        },
        .tag_union => |left| blk: {
            if (stored != .tag_union) break :blk false;
            const right = stored.tag_union;
            break :blk left.ext == right.ext and
                checkedTagBuildSliceEqlStored(left.tags, right.tags);
        },
    };
}

fn checkedNominalRecordFieldRootKeySliceEql(
    store: *const CheckedTypeStore,
    a: []const CheckedNominalRecordField,
    b: []const CheckedNominalRecordField,
) Allocator.Error!bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        switch (left) {
            .named => |left_name| switch (right) {
                .named => |right_name| if (left_name != right_name) return false,
                .padding => return false,
            },
            .padding => |left_ty| switch (right) {
                .named => return false,
                .padding => |right_ty| if (!try checkedTypeRootKeySliceEql(store, &.{left_ty}, &.{right_ty})) return false,
            },
        }
    }
    return true;
}

const CheckedKeyEngine = type_key_engine.Engine(CheckedTypeKeyAdapter);

/// Keys checked types through the canonical type-key engine. Classes and
/// keys persist across requests, so a digester must not outlive a change to
/// any payload it has described; a new root appended to the store changes
/// none, and no key describes a pending payload.
const CheckedTypeKeyDigester = struct {
    adapter: CheckedTypeKeyAdapter,
    engine: CheckedKeyEngine,

    fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        view: CheckedTypeStoreView,
    ) CheckedTypeKeyDigester {
        return .{
            .adapter = CheckedTypeKeyAdapter.init(allocator, names, view),
            .engine = CheckedKeyEngine.init(allocator, canonical_type_keys.key_engine_tags),
        };
    }

    fn deinit(self: *CheckedTypeKeyDigester) void {
        self.engine.deinit();
        self.adapter.deinit();
    }

    fn keyInfo(self: *CheckedTypeKeyDigester, source: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        // A failed request can leave partial classes behind.
        errdefer self.engine.reset();
        return keyInfoOf(try self.engine.summarize(&self.adapter, CheckedTypeKeyAdapter.nodeOf(source)));
    }

    fn keyInfoOf(summary: type_key_engine.Summary) canonical_type_keys.TypeKeyInfo {
        return .{
            .key = .{ .bytes = summary.key },
            .contains_identity_variables = summary.contains_identity,
            .composable = summary.composable,
        };
    }
};

/// Canonical keys of any checked types in one store, published roots or
/// not. Keys persist across requests, so the store must not change while
/// this is alive.
pub const CheckedTypeKeys = struct {
    store: *const CheckedTypeStore,
    digester: CheckedTypeKeyDigester,

    pub fn init(allocator: Allocator, names: *const canonical.CanonicalNameStore, store: *const CheckedTypeStore) CheckedTypeKeys {
        return .{ .store = store, .digester = CheckedTypeKeyDigester.init(allocator, names, store.view()) };
    }

    pub fn deinit(self: *CheckedTypeKeys) void {
        self.digester.deinit();
    }

    pub fn key(self: *CheckedTypeKeys, ty: CheckedTypeId) Allocator.Error!canonical.CanonicalTypeKey {
        self.digester.adapter.view = self.store.view();
        return (try self.digester.keyInfo(ty)).key;
    }
};

/// The key slots of one store's synthesized types. Each synthesized root
/// owns a write-once key slot claimed by the first consumer that needs the
/// root's key; computations share one key writer, held only while a
/// claimant computes. The store appends a slot for every root it appends,
/// which happens only while the store is built, before any other thread
/// reads it. Keys are never serialized: a store loaded from a cache entry
/// starts with every slot empty.
pub const SynthesizedTypeKeys = struct {
    const unknown_canonical = std.math.maxInt(u32);

    allocator: Allocator,
    io: std.Io,
    /// One slot per root; a slot never moves once the root exists.
    slots: collections.StableList(KeySlot) = .empty,
    /// Per root: 0 while unknown, else 1 + whether a walk found the root
    /// reaches an identity variable.
    identity: collections.StableList(std.atomic.Value(u8)) = .empty,
    /// Per root: its canonical id (`CheckedTypeStoreView.canonicalId`) once
    /// recorded, else `unknown_canonical`.
    canonical: collections.StableList(std.atomic.Value(u32)) = .empty,
    /// The lowest root of each key among the first `indexed` roots, extended
    /// on demand to cover roots created since. Read and extended under
    /// `index_mutex`; `indexed` is also read without it.
    index: KeyIndex = .empty,
    indexed: std.atomic.Value(usize) = .init(0),
    index_mutex: std.Io.Mutex = .init,
    writer_mutex: std.Io.Mutex = .init,
    writer: ?CheckedTypeKeyDigester = null,

    const KeySlot = collections.OnceSlot(canonical_type_keys.TypeKeyInfo, .synthesized_type_key);
    const KeyIndex = std.AutoHashMapUnmanaged([32]u8, CheckedTypeId);

    /// Key slots for a store holding `count` synthesized roots. `allocator`
    /// must be safe to use from every thread that reads the store.
    pub fn create(allocator: Allocator, io: std.Io, count: usize) Allocator.Error!*SynthesizedTypeKeys {
        const keys = try allocator.create(SynthesizedTypeKeys);
        keys.* = .{ .allocator = allocator, .io = io };
        errdefer keys.destroy();
        try keys.cover(count);
        return keys;
    }

    pub fn destroy(self: *SynthesizedTypeKeys) void {
        const allocator = self.allocator;
        self.index.deinit(allocator);
        if (self.writer) |*writer| writer.deinit();
        self.slots.deinit(allocator);
        self.identity.deinit(allocator);
        self.canonical.deinit(allocator);
        allocator.destroy(self);
    }

    /// Give every one of the store's `count` roots a slot. The store calls
    /// this before a new root's id exists.
    fn cover(self: *SynthesizedTypeKeys, count: usize) Allocator.Error!void {
        if (self.slots.count() >= count) return;
        try self.identity.growTo(self.allocator, count, .init(0));
        try self.canonical.growTo(self.allocator, count, .init(unknown_canonical));
        try self.slots.growTo(self.allocator, count, .empty);
    }

    fn knownCanonical(self: *const SynthesizedTypeKeys, index: usize) ?CheckedTypeId {
        std.debug.assert(index < self.canonical.count());
        const raw = self.canonical.at(index).load(.acquire);
        if (raw == unknown_canonical) return null;
        return @fromBackingInt(raw);
    }

    fn recordCanonical(self: *SynthesizedTypeKeys, index: usize, id: CheckedTypeId) void {
        std.debug.assert(index < self.canonical.count());
        self.canonical.at(index).store(@backingInt(id), .release);
    }

    fn knownIdentity(self: *const SynthesizedTypeKeys, index: usize) ?bool {
        std.debug.assert(index < self.identity.count());
        return switch (self.identity.at(index).load(.acquire)) {
            0 => null,
            1 => false,
            else => true,
        };
    }

    fn recordIdentity(self: *SynthesizedTypeKeys, index: usize, value: bool) void {
        std.debug.assert(index < self.identity.count());
        self.identity.at(index).store(if (value) 2 else 1, .release);
    }

    /// The key of the synthesized root `root` of `view` and the facts its
    /// encoding found.
    fn info(self: *SynthesizedTypeKeys, view: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        const index = type_ids.synthesizedIndex(root);
        if (index >= self.slots.count()) checkedModuleInvariant("a synthesized checked type has no key slot", .{});
        return try self.slots.at(index).getOrCompute(self.io, Allocator.Error, KeyRequest{ .keys = self, .view = view, .root = root }, KeyRequest.compute);
    }

    const KeyRequest = struct {
        keys: *SynthesizedTypeKeys,
        view: CheckedTypeStoreView,
        root: CheckedTypeId,

        fn compute(request: KeyRequest) Allocator.Error!canonical_type_keys.TypeKeyInfo {
            const keys = request.keys;
            const view = request.view;
            const names = view.names orelse checkedModuleInvariant("a synthesized checked type key was requested from a view without its name store", .{});
            // A synthesized function's source children are keyed through
            // their own slots before the writer is taken, so the writer is
            // never held while waiting on a slot.
            if (view.rootRows()[type_ids.synthesizedIndex(request.root)].recipe == .synthetic_function) {
                const function = syntheticFunctionPayload(view, request.root);
                for (function.args) |arg| if (!type_ids.isSynthesized(arg)) {
                    _ = try view.rootInfo(arg);
                };
                if (!type_ids.isSynthesized(function.ret)) _ = try view.rootInfo(function.ret);
            }
            keys.writer_mutex.lockUncancelable(keys.io);
            defer keys.writer_mutex.unlock(keys.io);
            if (keys.writer == null) keys.writer = CheckedTypeKeyDigester.init(keys.allocator, names, view);
            keys.writer.?.adapter.view = view;
            keys.writer.?.adapter.names = names;
            return try keys.computeLocked(view, request.root);
        }
    };

    /// `root`'s key, computed by the held writer. A synthesized function's
    /// synthesized children are computed here too, never waited on.
    fn computeLocked(self: *SynthesizedTypeKeys, view: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        const index = type_ids.synthesizedIndex(root);
        if (self.slots.at(index).peek()) |known| return known;
        return switch (view.rootRows()[index].recipe) {
            .payload => try self.writer.?.keyInfo(root),
            .synthetic_function => try self.syntheticFunctionInfo(view, root),
        };
    }

    fn childInfoLocked(self: *SynthesizedTypeKeys, view: CheckedTypeStoreView, child: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        if (!type_ids.isSynthesized(child)) return try view.rootInfo(child);
        return try self.computeLocked(view, child);
    }

    fn syntheticFunctionInfo(self: *SynthesizedTypeKeys, view: CheckedTypeStoreView, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
        const function = syntheticFunctionPayload(view, root);
        const allocator = self.allocator;
        const arg_infos = try allocator.alloc(canonical_type_keys.TypeKeyInfo, function.args.len);
        defer allocator.free(arg_infos);
        for (function.args, arg_infos) |arg, *arg_info| arg_info.* = try self.childInfoLocked(view, arg);
        const ret_info = try self.childInfoLocked(view, function.ret);
        var contains_identity_variables = ret_info.contains_identity_variables;
        var composable = ret_info.composable;
        for (arg_infos) |arg_info| {
            contains_identity_variables = contains_identity_variables or arg_info.contains_identity_variables;
            composable = composable and arg_info.composable;
        }
        const finalized_kind = finalizedFunctionKind(function.kind);
        if (composable) {
            const arg_keys = try allocator.alloc(canonical.CanonicalTypeKey, arg_infos.len);
            defer allocator.free(arg_keys);
            for (arg_infos, arg_keys) |arg_info, *key| key.* = arg_info.key;
            const effectful = switch (finalized_kind) {
                .pure => false,
                .effectful => true,
                .unbound => unreachable, // finalizedFunctionKind maps .unbound to .pure
            };
            return .{
                .key = try canonical_type_keys.composedFunctionKey(allocator, effectful, arg_keys, ret_info.key),
                .contains_identity_variables = contains_identity_variables,
                .composable = true,
            };
        }
        var hasher = TypeDigestHasher.init();
        hashByteSlice(&hasher, "checked_synthetic_function");
        hashByteSlice(&hasher, @tagName(finalized_kind));
        hashU32(&hasher, @intCast(arg_infos.len));
        for (arg_infos) |arg_info| hasher.update(&arg_info.key.bytes);
        hasher.update(&ret_info.key.bytes);
        return .{
            .key = .{ .bytes = hasher.finalResult() },
            .contains_identity_variables = contains_identity_variables,
            .composable = false,
        };
    }

    fn syntheticFunctionPayload(view: CheckedTypeStoreView, root: CheckedTypeId) CheckedFunctionType {
        return switch (view.payload(root)) {
            .function => |function| function,
            .pending, .field_kind, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => checkedModuleInvariant("a synthesized function root's payload was not a function", .{}),
        };
    }

    /// The lowest synthesized root of `view` among its first `bound` roots
    /// whose key is `key`, if any. The index grows on demand: the keys of the
    /// roots it does not cover yet are computed through their slots before
    /// the index lock is taken.
    fn rootForKey(self: *SynthesizedTypeKeys, view: CheckedTypeStoreView, key: canonical.CanonicalTypeKey, bound: usize) Allocator.Error!?CheckedTypeId {
        const roots = view.rootRows()[0..bound];
        const indexed = self.indexed.load(.acquire);
        if (indexed < bound) {
            for (roots[indexed..]) |row| _ = try self.info(view, row.id);
        }
        self.index_mutex.lockUncancelable(self.io);
        defer self.index_mutex.unlock(self.io);
        var covered = self.indexed.load(.monotonic);
        while (covered < bound) : (covered += 1) {
            const row = roots[covered];
            const info_ = self.slots.at(type_ids.synthesizedIndex(row.id)).peek() orelse
                checkedModuleInvariant("a synthesized checked type's key was indexed before it was computed", .{});
            const entry = try self.index.getOrPut(self.allocator, info_.key.bytes);
            if (!entry.found_existing) entry.value_ptr.* = row.id;
            self.indexed.store(covered + 1, .release);
        }
        const found = self.index.get(key.bytes) orelse return null;
        if (type_ids.synthesizedIndex(found) >= bound) return null;
        if (std.debug.runtime_safety) {
            const found_info = self.slots.at(type_ids.synthesizedIndex(found)).peek() orelse
                checkedModuleInvariant("a synthesized key index holds a root whose key was never computed", .{});
            if (!std.meta.eql(found_info.key.bytes, key.bytes)) checkedModuleInvariant("a synthesized key index answered a key with a root of another key", .{});
        }
        return found;
    }
};

/// Lists the children whose identity variables a checked type reaches, for a
/// walk over a view. A pending payload counts as reaching one, and the walk
/// records that it saw one so its result is not remembered.
const CheckedTypeViewIdentityScan = struct {
    view: CheckedTypeStoreView,
    saw_pending: bool = false,

    pub fn visit(self: *@This(), children: anytype, root: CheckedTypeId) Allocator.Error!?bool {
        if (self.view.knownIdentity(root)) |known| return known;
        switch (self.view.payload(root)) {
            .pending => {
                self.saw_pending = true;
                return true;
            },
            .flex, .rigid => return true,
            .field_kind, .err, .empty_record, .empty_tag_union => return false,
            .alias => |alias| {
                try children.add(alias.backing);
                try children.addSlice(alias.args);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try children.add(field.ty);
                    if (field.kind.undeterminedVariable()) |variable| try children.add(variable);
                }
                try children.add(record.ext);
            },
            .tuple => |items| try children.addSlice(items),
            .nominal => |nominal| {
                try children.addSlice(nominal.args);
                try children.addSlice(nominal.padding_field_types);
            },
            .function => |function| {
                try children.addSlice(function.args);
                try children.add(function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| try children.addSlice(tag_union.tags.get(tag_index).args);
                try children.add(tag_union.ext);
            },
        }
        return null;
    }
};

/// One substitution applied across any number of clones into one store:
/// each formal stands for its actual. It keeps each cloned source root's
/// image, so a root reached again reuses it.
pub const CheckedTypeSubstitution = struct {
    images: collections.DenseMap(CheckedTypeId, CheckedTypeId),
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
    /// When set, whether each root the clone can reach reaches a formal; a
    /// root that reaches none is its own image.
    reaching: ?*const collections.DenseMap(CheckedTypeId, bool) = null,

    /// `formals` and `actuals` must outlive the substitution.
    pub fn init(
        allocator: Allocator,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
    ) CheckedTypeSubstitution {
        if (formals.len != actuals.len) {
            checkedModuleInvariant("checked type substitution arity mismatch", .{});
        }
        return .{
            .images = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator),
            .formals = formals,
            .actuals = actuals,
        };
    }

    pub fn deinit(self: *CheckedTypeSubstitution) void {
        self.images.deinit();
    }
};

/// Describes checked type-store nodes to the key engine: the same encoding as
/// source types, plus each named type's owning module and each nominal's
/// padding and declared fields.
const CheckedTypeKeyAdapter = struct {
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    view: CheckedTypeStoreView,
    field_rank_scratch: base.TextRankCache,
    tag_rank_scratch: base.TextRankCache,
    field_ranks: []const u32 = &.{},
    tag_ranks: []const u32 = &.{},
    fields: std.ArrayList(RecordFieldForKey) = .empty,
    tags: std.ArrayList(TagForKey) = .empty,
    field_sort_scratch: std.ArrayList(RecordFieldForKey) = .empty,
    tag_sort_scratch: std.ArrayList(TagForKey) = .empty,
    row_seen: collections.DenseMap(CheckedTypeId, void),

    const Sink = type_key_engine.Sink;
    const KeyTag = canonical_type_keys.KeyTag;

    const RecordFieldForKey = struct {
        name: canonical.RecordFieldLabelId,
        ty: CheckedTypeId,
        kind: CheckedFieldKind,
    };

    const TagForKey = struct {
        name: canonical.TagLabelId,
        args: []const CheckedTypeId,
    };

    fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        view: CheckedTypeStoreView,
    ) CheckedTypeKeyAdapter {
        return .{
            .allocator = allocator,
            .names = names,
            .view = view,
            .field_rank_scratch = base.TextRankCache.init(allocator),
            .tag_rank_scratch = base.TextRankCache.init(allocator),
            .row_seen = collections.DenseMap(CheckedTypeId, void).init(allocator),
        };
    }

    fn deinit(self: *CheckedTypeKeyAdapter) void {
        self.field_sort_scratch.deinit(self.allocator);
        self.tag_sort_scratch.deinit(self.allocator);
        self.fields.deinit(self.allocator);
        self.tags.deinit(self.allocator);
        self.field_rank_scratch.deinit();
        self.tag_rank_scratch.deinit();
        self.row_seen.deinit();
    }

    /// The key engine's node for `id`: the id's bits rotated so source and
    /// synthesized ids interleave into one dense node space.
    fn nodeOf(id: CheckedTypeId) u32 {
        return std.math.rotl(u32, @backingInt(id), 1);
    }

    fn idOf(node: u32) CheckedTypeId {
        return @fromBackingInt(std.math.rotr(u32, node, 1));
    }

    pub fn resolve(_: *CheckedTypeKeyAdapter, node: u32) u32 {
        return node;
    }

    /// Whether `node` is known to reach no identity variable: a walk already
    /// recorded that fact for it. Unknown nodes are entered.
    pub fn identityFree(self: *const CheckedTypeKeyAdapter, node: u32) bool {
        const known = self.view.knownIdentity(idOf(node)) orelse return false;
        return !known;
    }

    fn storedPayload(self: *const CheckedTypeKeyAdapter, id: CheckedTypeId) CheckedTypePayload {
        return self.view.payload(id);
    }

    fn child(_: *const CheckedTypeKeyAdapter, sink: *Sink, id: CheckedTypeId) Allocator.Error!void {
        try sink.child(nodeOf(id));
    }

    fn tag(sink: *Sink, comptime key_tag: KeyTag) Allocator.Error!void {
        try sink.byte(@backingInt(key_tag));
    }

    pub fn describe(self: *CheckedTypeKeyAdapter, node: u32, sink: *Sink) Allocator.Error!type_key_engine.NodeKind {
        const id = idOf(node);
        return switch (self.storedPayload(id)) {
            .flex => |variable| try self.describeIdentity(sink, .flex, variable),
            .rigid => |variable| try self.describeIdentity(sink, .rigid, variable),
            .record => |record| blk: {
                self.fields.clearRetainingCapacity();
                try self.appendRecordFields(record.fields);
                try self.describeRecord(sink, id, record.ext);
                break :blk .content;
            },
            .tag_union => |tag_union| blk: {
                self.tags.clearRetainingCapacity();
                try self.appendTags(tag_union.tags);
                try self.describeTagUnion(sink, id, tag_union.ext);
                break :blk .content;
            },
            inline .pending,
            .field_kind,
            .err,
            .alias,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .empty_tag_union,
            => |inner, payload_tag| try self.describeContent(sink, @unionInit(CheckedTypePayload, @tagName(payload_tag), inner)),
        };
    }

    fn describeContent(self: *CheckedTypeKeyAdapter, sink: *Sink, payload: CheckedTypePayload) Allocator.Error!type_key_engine.NodeKind {
        switch (payload) {
            .pending => checkedModuleInvariant("checked type key reached pending payload", .{}),
            .flex,
            .rigid,
            .record,
            .tag_union,
            => unreachable, // describe and describeBuild handle flex, rigid, record and tag_union before delegating here
            .err => try tag(sink, .err),
            .field_kind => |kind| switch (kind) {
                .required => try tag(sink, .presence_required),
                .optional => try tag(sink, .presence_optional),
            },
            .alias => |alias| {
                try tag(sink, .alias);
                try self.namedSourceIdentity(sink, alias.origin_module, alias.name, alias.source_decl);
                try sink.text(alias.owner_module.bytes[0..]);
                try self.child(sink, alias.backing);
                try sink.varint(@intCast(alias.args.len));
                for (alias.args) |arg| try self.child(sink, arg);
            },
            .tuple => |tuple| {
                try tag(sink, .tuple);
                try sink.varint(@intCast(tuple.len));
                for (tuple) |elem| try self.child(sink, elem);
            },
            .nominal => |nominal| {
                try tag(sink, .nominal);
                try self.namedSourceIdentity(sink, nominal.origin_module, nominal.name, nominal.source_decl);
                try sink.text(nominal.owner_module.bytes[0..]);
                try sink.boolean(nominal.is_opaque);
                try sink.varint(@intCast(nominal.args.len));
                for (nominal.args) |arg| try self.child(sink, arg);
                try sink.varint(@intCast(nominal.padding_field_types.len));
                for (nominal.padding_field_types) |padding_type| try self.child(sink, padding_type);
                try sink.varint(@intCast(nominal.declared_fields.len));
                for (nominal.declared_fields) |field| switch (field) {
                    .named => |name| {
                        try tag(sink, .named);
                        try sink.text(self.names.recordFieldLabelText(name));
                    },
                    .padding => |index| {
                        try tag(sink, .padding);
                        try sink.varint(index);
                    },
                };
            },
            .function => |func| {
                switch (finalizedFunctionKind(func.kind)) {
                    .pure => try tag(sink, .fn_pure),
                    .effectful => try tag(sink, .fn_effectful),
                    .unbound => unreachable, // finalizedFunctionKind maps .unbound to .pure
                }
                try sink.varint(@intCast(func.args.len));
                for (func.args) |arg| try self.child(sink, arg);
                try self.child(sink, func.ret);
            },
            .empty_record => try tag(sink, .empty_record),
            .empty_tag_union => try tag(sink, .empty_tag_union),
        }
        return .content;
    }

    /// A type variable: its header (kind, name, constraint count), then each
    /// constraint's method name, callable, and origin.
    fn describeIdentity(
        self: *CheckedTypeKeyAdapter,
        sink: *Sink,
        comptime key_tag: KeyTag,
        variable: CheckedTypeVariable,
    ) Allocator.Error!type_key_engine.NodeKind {
        try tag(sink, key_tag);
        try sink.boolean(variable.name != null);
        if (variable.name) |text| try sink.text(text);
        try sink.varint(@intCast(variable.constraints.len()));
        sink.constraint_count = @intCast(variable.constraints.len());
        var constraints = variable.constraints.iterator();
        while (constraints.next()) |constraint| {
            try sink.text(self.names.methodNameText(constraint.fn_name));
            try self.child(sink, constraint.fn_ty);
            try sink.text(@tagName(constraint.origin));
            try sink.boolean(constraint.binopNegated());
            const maybe_num_literal = constraint.numeralInfo();
            try sink.boolean(maybe_num_literal != null);
            if (maybe_num_literal) |num_literal| try sink.bytes(&num_literal.keyBytes());
        }
        return .identity;
    }

    fn appendRecordFields(self: *CheckedTypeKeyAdapter, source: CheckedRecordFields) Allocator.Error!void {
        var fields = source.iterator();
        while (fields.next()) |field| {
            try self.fields.append(self.allocator, .{ .name = field.name, .ty = field.ty, .kind = field.kind });
        }
    }

    fn appendTags(self: *CheckedTypeKeyAdapter, source: CheckedTags) Allocator.Error!void {
        var tags = source.iterator();
        while (tags.next()) |source_tag| {
            try self.tags.append(self.allocator, .{ .name = source_tag.name, .args = source_tag.args });
        }
    }

    /// Follow a row's extension chain while it continues the same kind of
    /// row, starting after `row` itself so a chain looping back ends there.
    fn rowTail(self: *CheckedTypeKeyAdapter, row: ?CheckedTypeId, ext: CheckedTypeId, comptime kind: enum { record, tag_union }) Allocator.Error!?CheckedTypeId {
        self.row_seen.clearRetainingCapacity();
        if (row) |row_id| try self.row_seen.put(row_id, {});
        var tail: ?CheckedTypeId = ext;
        while (tail) |tail_id| {
            if ((try self.row_seen.getOrPut(tail_id)).found_existing) break;
            switch (self.storedPayload(tail_id)) {
                .empty_record => if (kind == .record) return null else break,
                .empty_tag_union => if (kind == .tag_union) return null else break,
                .record => |record| {
                    if (kind != .record) break;
                    try self.appendRecordFields(record.fields);
                    tail = record.ext;
                },
                .tag_union => |tag_union| {
                    if (kind != .tag_union) break;
                    try self.appendTags(tag_union.tags);
                    tail = tag_union.ext;
                },
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .tuple,
                .nominal,
                .function,
                => break,
            }
        }
        return tail;
    }

    fn recordFieldRank(self: *CheckedTypeKeyAdapter, field: RecordFieldForKey) u32 {
        return self.field_ranks[@backingInt(field.name)];
    }

    fn tagRank(self: *CheckedTypeKeyAdapter, tag_for_key: TagForKey) u32 {
        return self.tag_ranks[@backingInt(tag_for_key.name)];
    }

    /// A record row normalized across its extension chain (`self.fields`
    /// holds the head): fields sorted by label, then the row's tail.
    fn describeRecord(self: *CheckedTypeKeyAdapter, sink: *Sink, row: ?CheckedTypeId, ext: CheckedTypeId) Allocator.Error!void {
        const tail = try self.rowTail(row, ext, .record);
        const fields = self.fields.items;
        if (fields.len > 1) {
            self.field_ranks = try self.names.recordFieldLabelTextRanks(&self.field_rank_scratch);
            try base.TextRankCache.sortByRank(RecordFieldForKey, fields, &self.field_sort_scratch, self.allocator, self, recordFieldRank);
        }
        if (tail == null and fields.len == 0) {
            try tag(sink, .empty_record);
            return;
        }

        try tag(sink, .record);
        try sink.varint(@intCast(fields.len));
        for (fields, 0..) |field, index| {
            if (index > 0 and self.names.recordFieldLabelTextEql(fields[index - 1].name, field.name)) {
                checkedModuleInvariant("checked type key row normalization found duplicate record fields", .{});
            }
            try sink.text(self.names.recordFieldLabelText(field.name));
            try self.describeFieldKind(sink, field.kind);
            try self.child(sink, field.ty);
        }
        if (tail) |tail_id| {
            try self.child(sink, tail_id);
        } else {
            try tag(sink, .empty_record);
        }
    }

    fn describeFieldKind(self: *CheckedTypeKeyAdapter, sink: *Sink, kind: CheckedFieldKind) Allocator.Error!void {
        switch (kind.tag) {
            .required => try sink.boolean(false),
            .optional => try tag(sink, .presence_optional_field),
            .defaulted => {
                const origin_module = kind.default.origin() orelse
                    checkedModuleInvariant("checked defaulted field kind carried no default identity", .{});
                try tag(sink, .field_default);
                try sink.text(self.names.moduleIdentityBytes(origin_module));
                try sink.varint(kind.default.expr_node);
            },
            .undetermined => {
                const variable = kind.undeterminedVariable() orelse
                    checkedModuleInvariant("checked undetermined field kind carried no variable identity", .{});
                try tag(sink, .presence_variable);
                try self.child(sink, variable);
            },
            .err => try tag(sink, .err),
        }
    }

    /// A tag-union row normalized across its extension chain (`self.tags`
    /// holds the head): tags sorted by name with their payloads, then the
    /// row's tail.
    fn describeTagUnion(self: *CheckedTypeKeyAdapter, sink: *Sink, row: ?CheckedTypeId, ext: CheckedTypeId) Allocator.Error!void {
        const tail = try self.rowTail(row, ext, .tag_union);
        const tags = self.tags.items;
        if (tags.len > 1) {
            self.tag_ranks = try self.names.tagLabelTextRanks(&self.tag_rank_scratch);
            try base.TextRankCache.sortByRank(TagForKey, tags, &self.tag_sort_scratch, self.allocator, self, tagRank);
        }
        if (tail == null and tags.len == 0) {
            try tag(sink, .empty_tag_union);
            return;
        }

        try tag(sink, .tag_union);
        try sink.varint(@intCast(tags.len));
        for (tags, 0..) |tag_for_key, index| {
            if (index > 0 and self.names.tagLabelTextEql(tags[index - 1].name, tag_for_key.name)) {
                checkedModuleInvariant("checked type key row normalization found duplicate tags", .{});
            }
            try sink.text(self.names.tagLabelText(tag_for_key.name));
            try sink.varint(@intCast(tag_for_key.args.len));
            for (tag_for_key.args) |arg| try self.child(sink, arg);
        }
        if (tail) |tail_id| {
            try self.child(sink, tail_id);
        } else {
            try tag(sink, .empty_tag_union);
        }
    }

    fn namedSourceIdentity(self: *CheckedTypeKeyAdapter, sink: *Sink, origin_module: canonical.ModuleIdentityId, name: canonical.TypeNameId, source_decl: ?u32) Allocator.Error!void {
        try sink.text(self.names.moduleIdentityBytes(origin_module));
        try sink.boolean(source_decl != null);
        if (source_decl) |decl| {
            try sink.varint(decl);
        } else {
            try sink.text(self.names.typeNameText(name));
        }
    }
};

/// Computes the identity variables reachable from checked type roots, in the
/// order their canonical keys encode them, reusing its storage across roots.
pub const CheckedIdentityOrderer = struct {
    allocator: Allocator,
    store: *const CheckedTypeStore,
    adapter: CheckedTypeKeyAdapter,
    scratch: type_key_engine.IdentityOrderScratch = .{},
    order: std.ArrayListUnmanaged(u32) = .empty,

    pub fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        store: *const CheckedTypeStore,
    ) CheckedIdentityOrderer {
        return .{
            .allocator = allocator,
            .store = store,
            .adapter = CheckedTypeKeyAdapter.init(allocator, names, store.view()),
        };
    }

    pub fn deinit(self: *CheckedIdentityOrderer) void {
        self.adapter.deinit();
        self.scratch.deinit(self.allocator);
        self.order.deinit(self.allocator);
    }

    /// The identity variables reachable from `root`, in key order. The slice
    /// is valid until the next call.
    pub fn identityRoots(self: *CheckedIdentityOrderer, root: CheckedTypeId) Allocator.Error![]const CheckedTypeId {
        self.order.clearRetainingCapacity();
        // The store may have grown since the last call.
        self.adapter.view = self.store.view();
        try type_key_engine.appendIdentityOrder(CheckedTypeKeyAdapter, &self.adapter, self.allocator, &self.scratch, CheckedTypeKeyAdapter.nodeOf(root), &self.order);
        for (self.order.items) |*node| node.* = @backingInt(CheckedTypeKeyAdapter.idOf(node.*));
        return @ptrCast(self.order.items);
    }
};

fn forEachStaticDispatchTypeRoot(
    module: TypedCIR.Module,
    module_index: *const ModuleIndex,
    visitor: anytype,
) Allocator.Error!void {
    var node_idx: u32 = 0;
    while (node_idx < module.nodeCount()) : (node_idx += 1) {
        const tag = module.nodeTag(@fromBackingInt(@intCast(node_idx)));
        if (tag != .expr_dispatch_call and
            tag != .expr_interpolation and
            tag != .expr_type_dispatch_call and
            tag != .expr_type_dispatch_call_dispatcher and
            tag != .expr_method_eq) continue;

        const expr_idx: CIR.Expr.Idx = @fromBackingInt(@intCast(node_idx));
        if (!module_index.reachesExpr(expr_idx)) continue;
        try output_type_roots.forEachStaticDispatchTypeRoot(module.moduleEnvConst(), expr_idx, visitor);
    }

    for (module.moduleEnvConst().for_loop_dispatch_plans.items.items) |plan| {
        if (!module_index.reachesLoop(plan.node_idx)) continue;
        try output_type_roots.forEachForLoopDispatchTypeRoot(plan, visitor);
    }

    try output_type_roots.forEachLiteralDispatchTypeRoot(module.moduleEnvConst(), visitor);
}

/// A function over composed children has exactly the key a source function
/// node with those children has, so the two share one root. Otherwise the
/// children's keys depend on their context and the synthetic root is keyed
/// by its own construction.
fn syntheticSchemeKeyForType(key: canonical.CanonicalTypeKey) canonical.CanonicalTypeSchemeKey {
    var hasher = TypeDigestHasher.init();
    hashByteSlice(&hasher, "checked_synthetic_type_scheme");
    hasher.update(&key.bytes);
    return .{ .bytes = hasher.finalResult() };
}

/// A module's source types as its checked tables read them: the checked type each source
/// variable stands for (its class's checked representative), and the scratch
/// the module's declaration walks share.
pub const CheckedSourceTypeRoots = struct {
    scratch: ?struct {
        allocator: Allocator,
        local_nominal_declarations: LocalNominalDeclarationIds,
        /// Every local alias expansion declaration output has published,
        /// shared by all of the module's declaration walks. Keys own their
        /// argument slices.
        alias_expansions: AliasExpansions = .empty,
        imported_origins: ImportedOriginIndex,
    },

    fn init(allocator: Allocator, module: TypedCIR.Module) Allocator.Error!CheckedSourceTypeRoots {
        return .{
            .scratch = .{
                .allocator = allocator,
                .local_nominal_declarations = try LocalNominalDeclarationIds.init(allocator, module),
                .imported_origins = ImportedOriginIndex.init(allocator),
            },
        };
    }

    fn releaseScratch(self: *CheckedSourceTypeRoots) void {
        if (self.scratch) |*scratch| {
            var expansions = scratch.alias_expansions.keyIterator();
            while (expansions.next()) |key| if (key.args.len != 0) scratch.allocator.free(key.args);
            scratch.alias_expansions.deinit(scratch.allocator);
            scratch.imported_origins.deinit();
            scratch.local_nominal_declarations.deinit();
        }
        self.scratch = null;
    }

    fn deinit(self: *CheckedSourceTypeRoots) void {
        self.releaseScratch();
    }

    /// The checked type the source variable `var_` stands for.
    fn get(_: *const CheckedSourceTypeRoots, module: TypedCIR.Module, var_: Var) CheckedTypeId {
        return type_ids.fromVar(module.typeStoreConst().resolveVar(var_).var_);
    }
};

/// The checked type of the source variable `var_`, which publication reaches
/// from here on.
fn appendCheckedTypeRoot(
    allocator: Allocator,
    module: TypedCIR.Module,
    store: *CheckedTypeStore,
    active: *const CheckedSourceTypeRoots,
    var_: Var,
) Allocator.Error!CheckedTypeId {
    try sealed_type_view.reach(allocator, module.moduleEnvConst(), store.sealed_var_facts.items, var_, null);
    return active.get(module, var_);
}

/// The facts a checked type variable carries besides its name, constraints
/// and row default.
pub const CheckedVariableFacts = struct {
    numeric_default_phase: ?NumericDefaultPhase,
    row_default_discharges_constraints: bool,
    bounded_row_ext: bool,
};

/// A flex variable's facts. `bounded_row_ext` is its class's
/// `DescriptorFlags.bounded_row_ext`.
pub fn flexVariableFacts(module_env: *const ModuleEnv, flex: types.Flex, bounded_row_ext: bool) CheckedVariableFacts {
    return .{
        .numeric_default_phase = numericDefaultPhaseForFlex(module_env, flex),
        .row_default_discharges_constraints = rowDefaultDischargesConstraints(module_env, flex.constraints),
        .bounded_row_ext = bounded_row_ext,
    };
}

/// A rigid variable's facts. Only an implicitly opened flex row is bounded.
pub fn rigidVariableFacts(module_env: *const ModuleEnv, rigid: types.Rigid) CheckedVariableFacts {
    return .{
        .numeric_default_phase = numericDefaultPhaseForConstraints(module_env, rigid.constraints),
        .row_default_discharges_constraints = rowDefaultDischargesConstraints(module_env, rigid.constraints),
        .bounded_row_ext = false,
    };
}

/// The row default a variable takes when reached through a row-tail position
/// offering `candidate`; see `checkedTypeVariableRowDefault`.
pub fn checkedRowDefaultForContent(module_env: *const ModuleEnv, content: types.Content, candidate: ?RowDefault) ?RowDefault {
    return checkedTypeVariableRowDefault(content, candidate, switch (content) {
        .flex => |flex| rowDefaultDischargesConstraints(module_env, flex.constraints),
        .rigid, .err, .alias, .field_presence, .structure => false,
    });
}

/// A row-tail occurrence supplies a close-to-empty default only when its
/// variable has no static-dispatch requirements. A constrained row must stay
/// open so each use can instantiate both the row and its evidence together.
/// `flex_constraints_discharged` is `rowDefaultDischargesConstraints` of a
/// flex `content`'s constraints.
pub fn checkedTypeVariableRowDefault(
    content: types.Content,
    candidate: ?RowDefault,
    flex_constraints_discharged: bool,
) ?RowDefault {
    const default = candidate orelse return null;
    return switch (content) {
        .flex => |flex| if (flex.constraints.len() == 0 or flex_constraints_discharged) default else null,
        .rigid => |rigid| if (rigid.constraints.len() == 0) default else null,
        .err, .alias, .field_presence, .structure => null,
    };
}

/// Whether closing a row satisfies every constraint on its flex tail: each is
/// an `is_eq` or `to_hash`, which the empty row derives.
pub fn rowDefaultDischargesConstraints(module_env: *const ModuleEnv, constraints: types.StaticDispatchConstraint.SafeList.Range) bool {
    if (constraints.len() == 0) return false;
    const idents = &module_env.idents;
    for ((&module_env.types).sliceStaticDispatchConstraints(constraints)) |constraint| {
        if (!constraint.fn_name.eql(idents.is_eq) and !constraint.fn_name.eql(idents.to_hash)) return false;
    }
    return true;
}

/// The numeric default phase a flex variable's constraints give it.
pub fn numericDefaultPhaseForFlex(module_env: *const ModuleEnv, flex: types.Flex) ?NumericDefaultPhase {
    return numericDefaultPhaseForConstraints(module_env, flex.constraints);
}

/// The numeric default phase a variable with these constraints takes.
pub fn numericDefaultPhaseForConstraints(
    module_env: *const ModuleEnv,
    constraints_range: types.StaticDispatchConstraint.SafeList.Range,
) ?NumericDefaultPhase {
    const constraints = (&module_env.types).sliceStaticDispatchConstraints(constraints_range);
    const idents = module_env.idents;
    return types.literal_defaulting.numericDefaultPhase(.{
        .plus = idents.plus,
        .minus = idents.minus,
        .times = idents.times,
        .div_by = idents.div_by,
        .div_trunc_by = idents.div_trunc_by,
        .rem_by = idents.rem_by,
        .negate = idents.negate,
    }, .{
        .from_numeral = idents.from_numeral,
        .from_quote = idents.from_quote,
        .from_interpolation = idents.from_interpolation,
    }, constraints);
}

/// Whether a record's extension is the closed empty record.
pub fn checkedRecordExtIsEmpty(module_env: *const ModuleEnv, ext: Var) bool {
    return switch ((&module_env.types).resolveVar(ext).desc.content) {
        .structure => |flat| flat == .empty_record,
        .flex, .rigid, .alias, .field_presence, .err => false,
    };
}

/// Whether a tag union's extension is the closed empty tag union.
pub fn checkedTagUnionExtIsEmpty(module_env: *const ModuleEnv, ext: Var) bool {
    return switch ((&module_env.types).resolveVar(ext).desc.content) {
        .structure => |flat| flat == .empty_tag_union,
        .flex, .rigid, .alias, .field_presence, .err => false,
    };
}

/// Imported origin modules a type-root enumeration has resolved, by the
/// publishing module's identity index. Every nominal and alias a published
/// type mentions names its origin module, and resolving an origin examines
/// every import view and indexes the owner's nominal declarations. The index
/// does that once per origin, so publication work grows with the number of
/// named types plus the size of the imports, not with their product.
pub const ImportedOriginIndex = struct {
    allocator: Allocator,
    /// The import views every resolution in this index reads; fixed by the
    /// first resolution.
    imports: ?CheckedImportViews = null,
    slots: collections.DenseMap(base.ModuleIdentity.Idx, u32),
    origins: std.ArrayList(ImportedOrigin) = .empty,
    /// Import views examined while resolving origins.
    view_visits: u64 = 0,
    /// Nominal declarations examined while indexing owners' declarations.
    declaration_visits: u64 = 0,

    const no_declaration = std.math.maxInt(u32);

    const ImportedOrigin = struct {
        /// The first import view carrying the origin's identity. Every view
        /// with that identity is the same checked module. Null when no
        /// import view carries it.
        view: ?*const ImportedModuleView,
        /// The view's nominal declarations by source statement, built on the
        /// first declaration lookup: `first` maps a statement to its first
        /// declaration index and `next` chains declarations that share one.
        first: std.AutoHashMapUnmanaged(u32, u32) = .empty,
        next: []u32 = &.{},
        declarations_indexed: bool = false,
    };

    pub fn init(allocator: Allocator) ImportedOriginIndex {
        return .{
            .allocator = allocator,
            .slots = collections.DenseMap(base.ModuleIdentity.Idx, u32).init(allocator),
        };
    }

    pub fn deinit(self: *ImportedOriginIndex) void {
        for (self.origins.items) |*origin| {
            origin.first.deinit(self.allocator);
            self.allocator.free(origin.next);
        }
        self.origins.deinit(self.allocator);
        self.slots.deinit();
    }

    fn resolve(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        origin_module: base.ModuleIdentity.Idx,
    ) Allocator.Error!*ImportedOrigin {
        if (self.imports) |bound| {
            std.debug.assert(bound.direct.ptr == imports.direct.ptr and bound.direct.len == imports.direct.len);
            std.debug.assert(bound.available.ptr == imports.available.ptr and bound.available.len == imports.available.len);
        } else self.imports = imports;
        if (self.slots.get(origin_module)) |slot| return &self.origins.items[slot];

        const origin_hash = module_env.moduleIdentityHash(origin_module);
        var view: ?*const ImportedModuleView = null;
        for (imports.direct) |*import| {
            self.view_visits += 1;
            if (!importedViewIdentityMatches(&import.view, origin_hash)) continue;
            view = uniqueOwnerView(view, &import.view);
        }
        for (imports.available) |*available| {
            self.view_visits += 1;
            if (!importedViewIdentityMatches(available, origin_hash)) continue;
            view = uniqueOwnerView(view, available);
        }
        const slot: u32 = @intCast(self.origins.items.len);
        try self.origins.append(self.allocator, .{ .view = view });
        errdefer _ = self.origins.pop();
        try self.slots.put(origin_module, slot);
        return &self.origins.items[slot];
    }

    fn uniqueOwnerView(existing: ?*const ImportedModuleView, next: *const ImportedModuleView) *const ImportedModuleView {
        const found = existing orelse return next;
        if (!CheckedModuleKey.eql(found.key, next.key)) {
            checkedModuleInvariant("checked named type source origin resolved to multiple owner modules", .{});
        }
        return found;
    }

    /// The module that owns a named type from `origin_module`.
    pub fn owner(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        origin_module: base.ModuleIdentity.Idx,
    ) Allocator.Error!ModuleId {
        if (origin_module == module_env.selfModuleIdentity()) return imports.current_owner;
        const origin = try self.resolve(module_env, imports, origin_module);
        const view = origin.view orelse checkedModuleInvariant(
            "checked named type source origin had no available checked owner module {any}",
            .{module_env.moduleIdentityHash(origin_module).*},
        );
        return view.key.digest();
    }

    /// The module that owns a named type from `origin_module`, or null when
    /// no import view carries that module.
    pub fn ownerIfAvailable(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        origin_module: base.ModuleIdentity.Idx,
    ) Allocator.Error!?ModuleId {
        if (origin_module == module_env.selfModuleIdentity()) return imports.current_owner;
        const origin = try self.resolve(module_env, imports, origin_module);
        const view = origin.view orelse return null;
        return view.key.digest();
    }

    /// The builtin a nominal names, if any.
    pub fn builtinNominal(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        nominal: types.NominalType,
    ) Allocator.Error!?CheckedBuiltinNominal {
        if (!nominal.originIsBuiltin()) return null;
        const source_decl = nominal.sourceDeclOptional() orelse return null;
        if (module_env.module_role == .builtin and
            moduleEnvIdentityMatches(module_env, module_env.moduleIdentityHash(nominal.origin_module)))
        {
            return checkedBuiltinNominalForSourceDecl(module_env, source_decl);
        }
        const origin = try self.resolve(module_env, imports, nominal.origin_module);
        const view = origin.view orelse return null;
        return checkedBuiltinNominalForMatchingView(view, source_decl);
    }

    /// The imported declaration of the nominal declared at `source_decl` in
    /// `origin_module`: a nominal is identified by its declaring module's
    /// content identity and its declaring statement. A module also embeds
    /// declarations of nominals other modules declare, so the declaration's
    /// own module identity is compared.
    fn nominalDeclaration(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        origin_module: base.ModuleIdentity.Idx,
        source_decl: u32,
    ) Allocator.Error!ImportedNominalDeclarationRef {
        return (try self.nominalDeclarationIfAvailable(module_env, imports, origin_module, source_decl)) orelse checkedModuleInvariant(
            "checked nominal representation referenced a missing imported nominal declaration for owner identity {any} statement {d}",
            .{ module_env.moduleIdentityHash(origin_module).*, source_decl },
        );
    }

    /// `nominalDeclaration`, or null when no import view carries the origin
    /// module or its view holds no such declaration.
    fn nominalDeclarationIfAvailable(
        self: *ImportedOriginIndex,
        module_env: *const ModuleEnv,
        imports: CheckedImportViews,
        origin_module: base.ModuleIdentity.Idx,
        source_decl: u32,
    ) Allocator.Error!?ImportedNominalDeclarationRef {
        const origin_hash = module_env.moduleIdentityHash(origin_module);
        const origin = try self.resolve(module_env, imports, origin_module);
        const view = origin.view orelse return null;
        const declarations = view.checked_types.nominalDeclarationRows();
        if (!origin.declarations_indexed) {
            const next = try self.allocator.alloc(u32, declarations.len);
            errdefer self.allocator.free(next);
            var first: std.AutoHashMapUnmanaged(u32, u32) = .empty;
            errdefer first.deinit(self.allocator);
            try first.ensureTotalCapacity(self.allocator, @intCast(declarations.len));
            // Chain in reverse so each statement's chain runs in table order.
            var index = declarations.len;
            while (index > 0) {
                index -= 1;
                self.declaration_visits += 1;
                const head = first.getOrPutAssumeCapacity(declarations[index].source_statement);
                next[index] = if (head.found_existing) head.value_ptr.* else no_declaration;
                head.value_ptr.* = @intCast(index);
            }
            origin.first = first;
            origin.next = next;
            origin.declarations_indexed = true;
        }

        var found: ?CheckedNominalDeclarationId = null;
        var cursor = origin.first.get(source_decl) orelse no_declaration;
        while (cursor != no_declaration) : (cursor = origin.next[cursor]) {
            const declaration = declarations[cursor];
            if (!base.ModuleIdentity.eql(view.canonical_names.moduleIdentityBytes(declaration.nominal.module), origin_hash)) continue;
            if (found) |existing| {
                if (existing != declaration.id) {
                    checkedModuleInvariant("checked nominal representation import declaration resolution was ambiguous", .{});
                }
            } else {
                found = declaration.id;
            }
        }
        return .{
            .module = view.key.digest(),
            .declaration = found orelse return null,
        };
    }
};

fn categorizeBuiltinNominal(module: TypedCIR.Module, imports: CheckedImportViews, nominal: types.NominalType) ?CheckedBuiltinNominal {
    if (!nominal.originIsBuiltin()) return null;

    const source_decl = nominal.statement();
    const module_env = module.moduleEnvConst();
    const origin_hash = module_env.moduleIdentityHash(nominal.origin_module);

    if (module_env.module_role == .builtin and moduleEnvIdentityMatches(module_env, origin_hash)) {
        return checkedBuiltinNominalForSourceDecl(module_env, source_decl);
    }
    if (checkedBuiltinNominalForSource(CheckedImport, imports.direct, origin_hash, source_decl)) |builtin_nominal| return builtin_nominal;
    return checkedBuiltinNominalForSource(ImportedModuleView, imports.available, origin_hash, source_decl);
}

/// The one builtin nominal that `items` (import entries or bare views) resolve
/// the source declaration to, if any.
fn checkedBuiltinNominalForSource(
    comptime Item: type,
    items: []const Item,
    origin_hash: *const [32]u8,
    source_decl: u32,
) ?CheckedBuiltinNominal {
    var found: ?CheckedBuiltinNominal = null;
    for (items) |*item| {
        const view: *const ImportedModuleView = if (Item == CheckedImport) &item.view else item;
        if (checkedBuiltinNominalForView(view, origin_hash, source_decl)) |builtin_nominal| {
            if (found) |existing| {
                if (existing != builtin_nominal) {
                    checkedModuleInvariant("checked builtin nominal source resolved to multiple builtin declarations", .{});
                }
            } else {
                found = builtin_nominal;
            }
        }
    }
    return found;
}

fn checkedBuiltinNominalForView(view: *const ImportedModuleView, origin_hash: *const [32]u8, source_decl: u32) ?CheckedBuiltinNominal {
    if (!importedViewIdentityMatches(view, origin_hash)) return null;
    return checkedBuiltinNominalForMatchingView(view, source_decl);
}

/// The builtin a nominal names, given the import view whose identity is the
/// nominal's origin.
fn checkedBuiltinNominalForMatchingView(view: *const ImportedModuleView, source_decl: u32) ?CheckedBuiltinNominal {
    if (sourceDeclTypeIdent(view.module_env, source_decl) == null) return null;
    if (view.module_env.module_role != .builtin) return null;
    return checkedBuiltinNominalForSourceDecl(view.module_env, source_decl);
}

fn checkedBuiltinNominalForSourceDecl(module_env: *const ModuleEnv, source_decl: u32) ?CheckedBuiltinNominal {
    if (module_env.module_role != .builtin) return null;
    const type_ident = sourceDeclTypeIdent(module_env, source_decl) orelse return null;
    return checkedBuiltinNominalForIdent(module_env, type_ident);
}

fn sourceDeclTypeIdent(module_env: *const ModuleEnv, source_decl: u32) ?base.Ident.Idx {
    if (source_decl >= module_env.store.nodes.len()) return null;
    const node: CIR.Node.Idx = @fromBackingInt(@intCast(source_decl));
    const node_tag = module_env.store.nodes.get(node).tag;
    if (node_tag != .statement_alias_decl and node_tag != .statement_nominal_decl) return null;
    const statement_idx: CIR.Statement.Idx = @fromBackingInt(@intCast(source_decl));
    const statement = module_env.store.getStatement(statement_idx);
    const header_idx = if (statement == .s_nominal_decl)
        statement.s_nominal_decl.header
    else if (statement == .s_alias_decl)
        statement.s_alias_decl.header
    else
        return null;
    return module_env.store.getTypeHeader(header_idx).name;
}

fn checkedBuiltinNominalForIdent(module_env: *const ModuleEnv, ident: base.Ident.Idx) ?CheckedBuiltinNominal {
    const common = module_env.idents;
    if (ident.eql(common.bool) or ident.eql(common.bool_type)) return .bool;
    if (ident.eql(common.@"try") or ident.eql(common.builtin_try)) return .try_;
    if (ident.eql(common.str) or ident.eql(common.builtin_str)) return .str;
    if (ident.eql(common.u8) or ident.eql(common.u8_type)) return .u8;
    if (ident.eql(common.i8) or ident.eql(common.i8_type)) return .i8;
    if (ident.eql(common.u16) or ident.eql(common.u16_type)) return .u16;
    if (ident.eql(common.i16) or ident.eql(common.i16_type)) return .i16;
    if (ident.eql(common.u32) or ident.eql(common.u32_type)) return .u32;
    if (ident.eql(common.i32) or ident.eql(common.i32_type)) return .i32;
    if (ident.eql(common.u64) or ident.eql(common.u64_type)) return .u64;
    if (ident.eql(common.i64) or ident.eql(common.i64_type)) return .i64;
    if (ident.eql(common.u128) or ident.eql(common.u128_type)) return .u128;
    if (ident.eql(common.i128) or ident.eql(common.i128_type)) return .i128;
    if (ident.eql(common.f32) or ident.eql(common.f32_type)) return .f32;
    if (ident.eql(common.f64) or ident.eql(common.f64_type)) return .f64;
    if (ident.eql(common.dec) or ident.eql(common.dec_type)) return .dec;
    if (ident.eql(common.u8x16_type)) return .u8x16;
    if (ident.eql(common.i8x16_type)) return .i8x16;
    if (ident.eql(common.u16x8_type)) return .u16x8;
    if (ident.eql(common.i16x8_type)) return .i16x8;
    if (ident.eql(common.u32x4_type)) return .u32x4;
    if (ident.eql(common.i32x4_type)) return .i32x4;
    if (ident.eql(common.u64x2_type)) return .u64x2;
    if (ident.eql(common.i64x2_type)) return .i64x2;
    if (ident.eql(common.list) or ident.eql(common.builtin_list)) return .list;
    if (ident.eql(common.box) or ident.eql(common.builtin_box)) return .box;
    if (ident.eql(common.dict) or ident.eql(common.builtin_dict)) return .dict;
    if (ident.eql(common.set) or ident.eql(common.builtin_set)) return .set;
    if (ident.eql(common.iter) or ident.eql(common.builtin_iter)) return .iter;
    if (ident.eql(common.stream) or ident.eql(common.builtin_stream)) return .stream;
    if (ident.eql(common.builtin_encoding_parse_tag_union_spec)) return .parse_tag_union_spec;
    if (ident.eql(common.builtin_encoding_field_names)) return .fields;
    if (ident.eql(common.builtin_encoding_field_name)) return .field;
    if (ident.eql(common.builtin_crypto_sha256_digest)) return .crypto_sha256_digest;
    if (ident.eql(common.builtin_crypto_sha256_hasher)) return .crypto_sha256_hasher;
    if (ident.eql(common.builtin_crypto_blake3_digest)) return .crypto_blake3_digest;
    if (ident.eql(common.builtin_crypto_blake3_hasher)) return .crypto_blake3_hasher;
    return null;
}

fn testTypeDeclSourceDeclForIdent(module_env: *const ModuleEnv, type_ident: base.Ident.Idx) error{MissingTestTypeDecl}!u32 {
    for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        const source_decl = @backingInt(statement_idx);
        const candidate = sourceDeclTypeIdent(module_env, source_decl) orelse continue;
        if (candidate.eql(type_ident)) return source_decl;
    }
    return error.MissingTestTypeDecl;
}

const ExpectSingleNominalBackingPayloadError = Allocator.Error || error{
    WriteFailed,
    TestExpectedEqual,
    TestUnexpectedResult,
    CorruptEmbeddedBuiltins,
    ExpectedNominalStatement,
    ExpectedNominalRoot,
    ExpectedNominalPayload,
    ExpectedNominalBacking,
};

fn expectSingleNominalBackingPayload(allocator: Allocator, module_name: []const u8, source: []const u8, expected: CheckedTypePayload) ExpectSingleNominalBackingPayloadError!void {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");

    var test_env = try TestEnv.init(module_name, source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();

    const module = modules.module(0);
    const module_env = module.moduleEnvConst();
    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(module_env, &names);

    const module_name_id = try names.internModuleName(module_env.module_name);
    const display_module_name = try names.internModuleIdent(module.identStoreConst(), module_env.display_module_name_idx);
    const module_identity = ModuleIdentity{
        .stable_hash = computeStableModuleIdentityHash(module_env),
        .module_idx = module.moduleIndex(),
        .module_name = module_name_id,
        .display_module_name = display_module_name,
        .kind = module_env.module_kind,
    };
    _ = try names.internModuleIdentity(&module_identity.stable_hash);

    var checking_context_identity = try CheckingContextIdentity.fromModule(allocator, module_env, &.{}, null);
    defer checking_context_identity.deinit(allocator);
    const module_key = CheckedModuleKey.computeFromSourceHash(
        hashModuleSourceInputs(module_env),
        module_identity,
        checking_context_identity,
        &.{},
    );

    var module_index = try ModuleIndex.build(allocator, module.moduleEnvConst(), &.{});
    defer module_index.deinit(allocator);

    const checked_keys = try SealedTypeKeys.create(allocator, std.testing.io, module.moduleEnvConst());

    defer checked_keys.destroy();

    var publication = try CheckedTypeStore.fromModule(allocator, module, &names, module_key.digest(), &.{}, &.{}, &module_index, &.{}, &.{}, checked_keys);
    defer publication.deinit(allocator);

    const nominal_stmt = for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        switch (module_env.store.getStatement(statement_idx)) {
            .s_nominal_decl => break statement_idx,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_alias_decl,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    } else return error.ExpectedNominalStatement;

    const nominal_root = publication.reachedSourceRoot(module.typeStoreConst(), ModuleEnv.varFrom(nominal_stmt)) orelse return error.ExpectedNominalRoot;
    const nominal_payload = publication.payload(nominal_root);
    if (nominal_payload != .nominal) return error.ExpectedNominalPayload;
    const nominal = nominal_payload.nominal;
    const backing = publication.view().nominalBackingTemplateForPayload(nominal) orelse return error.ExpectedNominalBacking;
    try testing.expectEqual(expected, publication.payload(backing));
}

test "checked type publication normalizes closed empty tag union backing" {
    try expectSingleNominalBackingPayload(std.testing.allocator, "Foo", "Foo := []", .empty_tag_union);
}

test "checked type publication normalizes closed empty record backing" {
    try expectSingleNominalBackingPayload(std.testing.allocator, "Foo", "Foo := {}", .empty_record);
}

test "required record canonical keys agree across solver and checked representations" {
    const allocator = std.testing.allocator;

    var env = try ModuleEnv.init(allocator, "");
    defer env.deinit();
    const head_name = try env.insertIdent(Ident.for_text("head"));
    const tail_name = try env.insertIdent(Ident.for_text("tail"));

    var source_store = try types.Store.initCapacity(allocator, 32, 16);
    defer source_store.deinit();
    const field_var = try source_store.freshFromContent(.{ .structure = .empty_record });
    const ext_var = try source_store.freshFromContent(.{ .structure = .empty_record });
    const source_tail_fields = try source_store.appendRecordFields(&.{.{
        .name = tail_name,
        .presence = .required(field_var),
    }});
    const source_tail = try source_store.freshFromContent(.{ .structure = .{ .record = .{
        .fields = source_tail_fields,
        .ext = ext_var,
    } } });
    const source_head_fields = try source_store.appendRecordFields(&.{.{
        .name = head_name,
        .presence = .required(field_var),
    }});
    const source_record = try source_store.freshFromContent(.{ .structure = .{ .record = .{
        .fields = source_head_fields,
        .ext = source_tail,
    } } });
    const source_record_key = try canonical_type_keys.fromVar(allocator, &source_store, &env, source_record);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    const checked_head_name = try names.internRecordFieldLabel("head");
    const checked_tail_name = try names.internRecordFieldLabel("tail");

    var checked_store = CheckedTypeStore{};
    defer checked_store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &checked_store, &names);
    const checked_empty = try appendExplicitCheckedTypePayload(allocator, &checked_store, .empty_record);
    const checked_tail_fields = try allocator.alloc(CheckedRecordField, 1);
    checked_tail_fields[0] = .{ .name = checked_tail_name, .ty = checked_empty };
    const checked_tail = try appendExplicitCheckedTypePayload(allocator, &checked_store, .{ .record = .{
        .fields = checked_tail_fields,
        .ext = checked_empty,
    } });
    const checked_head_fields = try allocator.alloc(CheckedRecordField, 1);
    checked_head_fields[0] = .{ .name = checked_head_name, .ty = checked_empty };
    const checked_record = try appendExplicitCheckedTypePayload(allocator, &checked_store, .{ .record = .{
        .fields = checked_head_fields,
        .ext = checked_tail,
    } });
    const checked_record_key = (try checked_store.rootKey(checked_record));

    try std.testing.expectEqualSlices(u8, &source_record_key.bytes, &checked_record_key.bytes);
}

