/// The one `*_pool` field of `Owner` (a checked type store or its view)
/// whose elements are `T`.
fn poolField(comptime Owner: type, comptime T: type) []const u8 {
    comptime {
        var found: ?[]const u8 = null;
        const owner = @typeInfo(Owner).@"struct";
        for (owner.field_names, owner.field_types) |name, FT| {
            if (name.len < 5 or !store_serialize.comptimeStrEq(name[name.len - 5 ..], "_pool")) continue;
            if (FT != collections.PublishedList(T) and FT != std.ArrayList(T) and FT != []const T) continue;
            if (found != null) @compileError("two pools of " ++ @typeName(Owner) ++ " hold " ++ @typeName(T));
            found = name;
        }
        return found orelse @compileError("no pool of " ++ @typeName(Owner) ++ " holds " ++ @typeName(T));
    }
}

/// The pool of `T` elements in a checked type store or its view.
fn storePool(pool_owner: anytype, comptime T: type) []const T {
    const Owner = @TypeOf(pool_owner);
    const Base = if (@typeInfo(Owner) == .pointer) @typeInfo(Owner).pointer.child else Owner;
    if (Base == CheckedTypeStoreView) {
        const store = pool_owner.store orelse return &.{};
        return storePool(store, T);
    }
    const pool = &@field(pool_owner, poolField(Base, T));
    const Pool = @TypeOf(pool.*);
    if (Pool == collections.PublishedList(T)) return pool.items();
    if (Pool == std.ArrayList(T)) return pool.items;
    return pool.*;
}

/// Whether a value of `T` can own a slice: one held directly or through a
/// struct, union, or optional, or by a slice element.
fn ownsSlice(comptime T: type) bool {
    comptime {
        const info = @typeInfo(T);
        if (info == .pointer) {
            if (info.pointer.size != .slice) @compileError("owned checked data holds a non-slice pointer: " ++ @typeName(T));
            return true;
        }
        if (info == .optional) return ownsSlice(info.optional.child);
        const field_types = if (info == .@"struct") info.@"struct".field_types else if (info == .@"union") info.@"union".field_types else return false;
        for (field_types) |field_type| {
            if (ownsSlice(field_type)) return true;
        }
        return false;
    }
}

/// Free every slice `value` owns, recursively through struct and union
/// payloads, optionals, and slice elements.
fn freeOwned(allocator: Allocator, value: anytype) void {
    const T = @TypeOf(value);
    const info = @typeInfo(T);
    if (comptime !ownsSlice(T)) {
        return;
    } else if (comptime info == .pointer) {
        if (comptime ownsSlice(info.pointer.child)) {
            for (value) |item| freeOwned(allocator, item);
        }
        allocator.free(value);
    } else if (comptime info == .optional) {
        if (value) |payload| freeOwned(allocator, payload);
    } else if (comptime info == .@"struct") {
        inline for (info.@"struct".field_names) |name| freeOwned(allocator, @field(value, name));
    } else {
        inline for (comptime std.enums.values(std.meta.Tag(T))) |tag| {
            if (value == tag) return freeOwned(allocator, @field(value, @tagName(tag)));
        }
        unreachable; // the loop covers every tag of T
    }
}

/// Copy every slice `value` references into memory owned by the result,
/// recursively through struct and union payloads and optionals. Slice
/// elements are copied as they are. Release the result with `freeOwned`.
fn dupeOwned(allocator: Allocator, value: anytype) Allocator.Error!@TypeOf(value) {
    const T = @TypeOf(value);
    const info = @typeInfo(T);
    if (comptime !ownsSlice(T)) {
        return value;
    } else if (comptime info == .pointer) {
        return allocator.dupe(info.pointer.child, value);
    } else if (comptime info == .optional) {
        return if (value) |payload| try dupeOwned(allocator, payload) else null;
    } else if (comptime info == .@"struct") {
        var owned: T = value;
        inline for (info.@"struct".field_names, 0..) |name, i| {
            @field(owned, name) = dupeOwned(allocator, @field(value, name)) catch |err| {
                inline for (info.@"struct".field_names[0..i]) |copied| freeOwned(allocator, @field(owned, copied));
                return err;
            };
        }
        return owned;
    } else {
        inline for (comptime std.enums.values(std.meta.Tag(T))) |tag| {
            if (value == tag) return @unionInit(T, @tagName(tag), try dupeOwned(allocator, @field(value, @tagName(tag))));
        }
        unreachable; // the loop covers every tag of T
    }
}

fn directProcedureTargetForCall(
    refs: *const ResolvedValueRefTable,
    callee: CIR.Expr.Idx,
    local_module: CheckedModuleKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!?ResolvedValueId {
    const ref_id = refs.lookupIdByExpr(callee) orelse return null;
    const raw = @backingInt(ref_id);
    if (raw >= refs.records.len) {
        checkedModuleInvariant("checked direct call target referenced a missing resolved value", .{});
    }
    return if (try resolvedValueCanBeCalledDirectly(
        refs,
        refs.records[raw].ref,
        local_module,
        local_procedure_bindings,
        local_callable_eval_templates,
        imports,
        available_modules,
        relation_modules,
    )) ref_id else null;
}

/// A call through an exact procedure alias, local or top-level, is direct when
/// the alias reaches a directly callable procedure: it forwards to the
/// alias's lookup inside the alias's evidence scope.
fn resolvedValueCanBeCalledDirectly(
    refs: *const ResolvedValueRefTable,
    ref: ResolvedValueRef,
    local_module: CheckedModuleKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!bool {
    return switch (ref) {
        .local_proc => |local| if (local.is_alias) blk: {
            const final = local.alias_target orelse
                checkedModuleInvariant("callable alias has no published target", .{});
            break :blk try resolvedValueCanBeCalledDirectly(
                refs,
                refs.records[@backingInt(final)].ref,
                local_module,
                local_procedure_bindings,
                local_callable_eval_templates,
                imports,
                available_modules,
                relation_modules,
            );
        } else true,
        .hosted_proc => true,
        .top_level_proc, .promoted_top_level_proc => |proc| try procedureUseCanBeCalledDirectly(
            proc,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .imported_proc => |proc| try procedureUseCanBeCalledDirectly(
            proc,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .platform_required_proc => |required| try procedureUseCanBeCalledDirectly(
            required.procedure,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .selected_hoisted_const,
        .top_level_const,
        .imported_const,
        .platform_required_declaration,
        .platform_required_checked_error,
        .platform_required_const,
        => false,
    };
}

fn procedureUseCanBeCalledDirectly(
    proc: ProcedureUseTemplate,
    local_module: CheckedModuleKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!bool {
    const body = try procedureUseBody(proc, local_module, local_procedure_bindings, imports, available_modules, relation_modules) orelse return true;
    return switch (body.body) {
        .direct_template => true,
        .checked_error => false,
        .callable_eval_template => |template| (if (body.view) |view|
            (try view.checkedTables()).callable_eval_templates.view().templates[@backingInt(template)]
        else
            local_callable_eval_templates.get(template)).forwarded_lookup != null,
    };
}

/// The binding body of a procedure use and the checked module view that owns
/// it, or null for the local module. Hosted procedures have no binding body.
const ProcedureUseBody = struct {
    body: ProcedureBindingBody,
    view: ?ImportedModuleView,
};

fn procedureUseBody(
    proc: ProcedureUseTemplate,
    local_module: CheckedModuleKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!?ProcedureUseBody {
    const top_level: ModuleTopLevelProcedureBindingRef = switch (proc.binding) {
        .top_level => |top_level| top_level,
        .platform_required => |required| .{ .module = required.module, .binding = required.procedure_binding },
        .hosted => return null,
        .imported => |imported| {
            const view = dependencyViewByKey(imported.module, imports, available_modules, relation_modules) orelse
                checkedModuleInvariant("imported direct-call target referenced an unavailable checked module", .{});
            const binding = (try view.exportRows()).procedureBinding(imported.def, imported.pattern) orelse
                checkedModuleInvariant("imported direct-call target was not exported by its checked module", .{});
            return .{ .view = view.*, .body = binding.body };
        },
    };
    if (top_level.module.eql(local_module.digest())) {
        return .{ .view = null, .body = local_procedure_bindings.get(top_level.binding).body };
    }
    const view = dependencyViewByKey(top_level.module, imports, available_modules, relation_modules) orelse
        checkedModuleInvariant("direct-call target referenced an unavailable checked module", .{});
    return .{ .view = view.*, .body = (try view.checkedTables()).top_level_procedure_bindings.get(top_level.binding).body };
}

/// The alias-chased builtin nominal of a literal's target type, treating a
/// still-open flex/rigid variable as not builtin: an open variable's
/// instantiations are not known yet.
pub fn checkedConcreteBuiltinForLiteralTarget(view: CheckedTypeStoreView, root: CheckedTypeId) ?CheckedBuiltinNominal {
    var current = root;
    while (true) {
        switch (view.payload(current)) {
            .alias => |alias| current = alias.backing,
            .nominal => |nominal| return nominal.builtin,
            .flex, .rigid => return null,
            .pending => checkedModuleInvariant("checked builtin lookup reached a pending type payload", .{}),
            .field_kind,
            .err,
            .record,
            .tuple,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return null,
        }
    }
}

fn isStatementNodeTag(tag: CIR.Node.Tag) bool {
    return Ident.textStartsWith(@tagName(tag), "statement_");
}

