/// Give each callable-eval template the lookup checking found it forwards to
/// (`ModuleEnv.BindingResolution.forwarded_lookup`), and make each
/// callable-eval binding checking resolved to a checked error one.
fn applyBindingResolutions(
    env: *const ModuleEnv,
    templates: *CallableEvalTemplateTable,
    bindings: *TopLevelProcedureBindingTable,
) void {
    for (templates.templates.items) |*template| {
        const resolution = env.bindingResolution(template.pattern) orelse
            checkedModuleInvariant("a callable-eval binding has no recorded resolution", .{});
        template.forwarded_lookup = resolution.forwarded_lookup;
    }
    for (bindings.bindings.items) |*binding| {
        const template = switch (binding.body) {
            .callable_eval_template => |template| templates.get(template),
            .direct_template, .checked_error => continue,
        };
        switch (env.bindingResolution(template.pattern).?.body) {
            .checked_error => |expr| binding.body = .{ .checked_error = expr },
            .evaluated => {},
            .constant, .procedure => checkedModuleInvariant("a callable-eval binding resolved to no evaluated value", .{}),
        }
    }
}

/// Checked-tables-only index for callable values produced by selected pattern
/// extraction roots. The durable identity lives in the compile-time root,
/// callable-eval template, and top-level procedure binding tables; this index
/// only connects source lookups to those identities while resolved refs are
/// being computed.
const SelectedHoistedCallableTable = struct {
    by_pattern: []?TopLevelProcedureBindingRef = &.{},
    /// Procedure bindings of promoted local functions, by binding pattern.
    promoted_by_pattern: []?TopLevelProcedureBindingRef = &.{},

    fn fromRoots(
        allocator: Allocator,
        module: TypedCIR.Module,
        roots: *const CompileTimeRootTable,
        callable_eval_templates: *CallableEvalTemplateTable,
        procedure_bindings: *TopLevelProcedureBindingTable,
        checked_source_types: *const CheckedSourceTypes,
        promoted_templates: []const PromotedProcedureTemplateEntry,
    ) Allocator.Error!SelectedHoistedCallableTable {
        const by_pattern = try allocator.alloc(?TopLevelProcedureBindingRef, module.nodeCount());
        errdefer allocator.free(by_pattern);
        @memset(by_pattern, null);
        const promoted_by_pattern = try allocator.alloc(?TopLevelProcedureBindingRef, module.nodeCount());
        errdefer allocator.free(promoted_by_pattern);
        @memset(promoted_by_pattern, null);

        for (promoted_templates) |promoted| {
            const checked_pattern = promoted.pattern;
            const binding = try procedure_bindings.appendDirect(
                allocator,
                checked_source_types.schemeForSourceVar(module, ModuleEnv.varFrom(promoted.pattern)),
                .{ .module = promoted.template.module, .proc_base = promoted.template.proc_base },
                promoted.template,
            );
            const slot = &promoted_by_pattern[@backingInt(checked_pattern)];
            if (slot.* != null) checkedModuleInvariant("promoted local procedure was published more than once", .{});
            slot.* = binding;
        }

        for (roots.roots) |root| {
            if (root.kind != .callable_binding) continue;
            switch (root.source) {
                .hoisted => {},
                .def, .expr, .statement, .required_binding, .literal => continue,
            }

            const source_pattern = root.source_pattern orelse
                checkedModuleInvariant("selected callable root had no source pattern", .{});
            if (!sourceTypeIsFunction(module, ModuleEnv.varFrom(source_pattern))) {
                checkedModuleInvariant("selected callable root source pattern was not function-typed", .{});
            }
            const checked_pattern = root.pattern orelse
                checkedModuleInvariant("selected callable root had no checked pattern", .{});
            const source_scheme = checked_source_types.schemeForSourceVar(module, ModuleEnv.varFrom(source_pattern));
            const callable_template = try callable_eval_templates.append(
                allocator,
                module.moduleIndex(),
                checked_pattern,
                root.id,
                source_scheme,
                root.checked_type,
            );
            const binding = try procedure_bindings.appendCallableEval(
                allocator,
                source_scheme,
                callable_template,
            );
            const slot = &by_pattern[@backingInt(checked_pattern)];
            if (slot.* != null) {
                checkedModuleInvariant("selected callable pattern was published more than once", .{});
            }
            slot.* = binding;
        }

        return .{ .by_pattern = by_pattern, .promoted_by_pattern = promoted_by_pattern };
    }

    fn lookupByPattern(self: *const SelectedHoistedCallableTable, pattern: CIR.Pattern.Idx) ?TopLevelProcedureBindingRef {
        const raw = @backingInt(pattern);
        if (raw >= self.by_pattern.len) return null;
        return self.by_pattern[raw];
    }

    /// The procedure binding of the promoted local function a binding pattern
    /// declares.
    fn lookupPromotedByPattern(self: *const SelectedHoistedCallableTable, pattern: CIR.Pattern.Idx) ?TopLevelProcedureBindingRef {
        const raw = @backingInt(pattern);
        if (raw >= self.promoted_by_pattern.len) return null;
        return self.promoted_by_pattern[raw];
    }

    fn deinit(self: *SelectedHoistedCallableTable, allocator: Allocator) void {
        allocator.free(self.by_pattern);
        allocator.free(self.promoted_by_pattern);
        self.* = .{};
    }
};

/// Public `ImportedProcedureBindingRef` declaration.
pub const ImportedProcedureBindingRef = struct {
    module: CheckedModuleDigest,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
};

/// Public `ProcedureUseTemplate` declaration.
pub const ProcedureUseTemplate = struct {
    binding: ProcedureBindingRef,
    source_fn_ty_payload: ?CheckedTypeId = null,
    /// Producer-recorded intrinsic identity for this exact procedure use.
    /// Post-check consumers must not derive this by walking binding bodies or
    /// exported template closures.
    intrinsic: ?IntrinsicId = null,
    /// Producer-recorded semantic role for compiler-owned iterator procedures.
    iterator_procedure: ?IteratorProcedureId = null,
    /// Producer-owned reachability fact for a compiler-provided result.
    runtime_result_provenance: ?RuntimeResultProvenance,
};

/// An immutable checked-evidence vector owned by one checked module.
pub const CheckedEvidenceSpan = struct {
    checked_module: CheckedModuleDigest,
    span: static_dispatch.EvidenceSpan,
};

/// Public `LocalProcedureBinding` declaration.
pub const LocalProcedureBinding = struct {
    /// An alias owns an instantiation scope, but forwards an existing callable
    /// instead of introducing a checked function body.
    is_alias: bool = false,
    /// Final callable lookup reached through the alias's explicit RHS edges.
    /// Resolution compresses these identity edges once; type substitutions
    /// remain owned by the individual checked scheme scopes.
    alias_target: ?ResolvedValueRefId = null,
    binder: CIR.Pattern.Idx,
    expr: CIR.Expr.Idx,
    /// Exact generalized-local dispatch scope owned by this procedure, if it
    /// has one. Consumers use this producer-recorded identity directly; they
    /// must not rediscover scope ownership by scanning checked expressions.
    dispatch_scope: ?DispatchScopeId = null,
};

/// Return the checked module id that owns a top-level procedure binding.
pub fn topLevelProcedureModuleId(ref: ModuleTopLevelProcedureBindingRef) ModuleId {
    return ref.module;
}

/// Return the checked module id that owns an imported procedure binding.
pub fn importedProcedureModuleId(ref: ImportedProcedureBindingRef) ModuleId {
    return ref.module;
}

/// Return the checked module id that owns a hosted procedure template.
pub fn hostedProcedureTemplateModuleId(ref: HostedProcRef) ModuleId {
    return .{ .bytes = canonical.procTemplateModuleDigest(ref.template).bytes };
}

/// Return the checked module id that owns a required application procedure.
pub fn requiredProcedureModuleId(ref: RequiredAppProcedureRef) ModuleId {
    return ref.module;
}

/// Public `PlatformRequiredConstResolvedRef` declaration.
pub const PlatformRequiredConstResolvedRef = struct {
    binding: PlatformRequiredBindingId,
    const_use: ConstUseTemplate,
};

/// Public `PlatformRequiredProcedureResolvedRef` declaration.
pub const PlatformRequiredProcedureResolvedRef = struct {
    binding: PlatformRequiredBindingId,
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
};

/// Public `SelectedHoistedConstUse` declaration.
pub const SelectedHoistedConstUse = struct {
    local: LocalBindingRef,
    const_use: ConstUseTemplate,
};

/// Public `ResolvedValueRef` declaration.
pub const ResolvedValueRef = union(enum) {
    local_param: LocalBindingRef,
    local_value: LocalBindingRef,
    local_mutable_version: LocalBindingRef,
    pattern_binder: LocalBindingRef,
    local_proc: LocalProcedureBinding,
    selected_hoisted_const: SelectedHoistedConstUse,

    top_level_const: ConstUseTemplate,
    imported_const: ConstUseTemplate,

    top_level_proc: ProcedureUseTemplate,
    imported_proc: ProcedureUseTemplate,
    hosted_proc: ProcedureUseTemplate,
    platform_required_declaration: PlatformRequiredDeclarationId,
    /// The app-side check for this platform requirement failed. This is an
    /// executable checked fact and lowers to a crash if the lookup is reached.
    platform_required_checked_error,
    platform_required_const: PlatformRequiredConstResolvedRef,
    platform_required_proc: PlatformRequiredProcedureResolvedRef,
    promoted_top_level_proc: ProcedureUseTemplate,
};

/// Public `ResolvedValueRefRecord` declaration.
pub const ResolvedValueRefRecord = struct {
    expr: CIR.Expr.Idx,
    ref: ResolvedValueRef,
    checked_ty: CheckedTypeId,
    scope_depth: u32,
    /// Checking proved that this lookup targets a member of an on-stack
    /// recursive binding group. Monotype may join it to that procedure's
    /// in-progress specialization only when its recorded scheme substitution
    /// is the active specialization's substitution.
    recursive_reference: bool = false,
};

/// One call's direct procedure target (`ResolvedValueRefTable.call_direct_targets`).
pub const CallDirectTarget = extern struct {
    call: CIR.Expr.Idx,
    target: ResolvedValueId,

    fn order(entry: CallDirectTarget, key: CIR.Expr.Idx) std.math.Order {
        return std.math.order(@backingInt(entry.call), @backingInt(key));
    }
};

/// The resolved value references of a checked module's lookups, and the
/// by-node facts reference resolution decides for its expressions.
pub const ResolvedValueRefTable = struct {
    /// One record per reached lookup expression, ascending by expression.
    records: []ResolvedValueRefRecord = &.{},
    template_refs: []ResolvedValueRefId = &.{},
    /// Expressions lowering evaluates as runtime errors because reference
    /// resolution rejected them: uses of rejected bindings, calls of a
    /// callee lowering evaluates as a runtime error, and the uses and calls
    /// those rejections propagate to through callable bindings. One bit per
    /// node of the module, 64 nodes per word.
    retired_exprs: []u64 = &.{},
    /// Each call that targets a directly callable procedure, with that
    /// procedure's reference, ascending by call.
    call_direct_targets: []CallDirectTarget = &.{},

    /// The module's resolved value references, which its checked tables
    /// compute on demand from the value-reference resolution checking
    /// recorded (`ModuleEnv.value_references`, `retired_exprs` and
    /// `direct_procedure_calls`), naming each target by the module's
    /// procedure-binding, template and constant ids. Nothing caches them.
    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_key: CheckedModuleKey,
        imports: []const CheckedImport,
        available_modules: []const ImportedModuleView,
        templates: *const CheckedProcedureTemplateTable,
        platform_required_declarations: PlatformRequiredDeclarationTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        top_level_values: *const TopLevelValueTable,
        selected_hoisted_callables: *const SelectedHoistedCallableTable,
        hoisted_constants: *const HoistedConstTable,
        checked_types: *const CheckedSourceTypes,
    ) Allocator.Error!ResolvedValueRefTable {
        const env = module.moduleEnvConst();
        const references = env.value_references.items.items;

        var recursive_reference_nodes = collections.DenseMap(u32, void).init(allocator);
        defer recursive_reference_nodes.deinit();
        for (env.scheme_uses.items.items) |record| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.recursive_reference)) continue;
            try recursive_reference_nodes.put(record.node_idx, {});
        }

        const records = try allocator.alloc(ResolvedValueRefRecord, references.len);
        var table = ResolvedValueRefTable{ .records = records };
        errdefer table.deinit(allocator);
        for (references, records) |reference, *record| {
            var resolved_ref = try resolvedValueRefFor(
                module,
                module_key,
                reference,
                imports,
                available_modules,
                templates,
                platform_required_declarations,
                platform_required_bindings,
                top_level_values,
                selected_hoisted_callables,
                hoisted_constants,
            );
            const checked_ty = checked_types.rootForSourceVar(module, module.exprType(reference.expr)) orelse {
                base.invariant("checked module invariant violated: resolved value ref type root was not published", .{});
            };
            try attachUseTypePayload(&resolved_ref, checked_ty);
            record.* = .{
                .expr = reference.expr,
                .ref = resolved_ref,
                .checked_ty = checked_ty,
                .scope_depth = 0,
                .recursive_reference = recursive_reference_nodes.contains(@backingInt(reference.expr)),
            };
        }
        for (references, records) |reference, *record| {
            if (reference.target != .local_procedure) continue;
            const alias_target = reference.target.local_procedure.alias_target orelse continue;
            record.ref.local_proc.alias_target = table.lookupIdByExpr(alias_target) orelse
                checkedModuleInvariant("a callable alias target has no resolved lookup", .{});
        }

        table.retired_exprs = try retiredWords(allocator, module.nodeCount());
        for (env.retired_exprs.items.items) |expr| setRetired(table.retired_exprs, expr);

        const direct_calls = env.direct_procedure_calls.items.items;
        table.call_direct_targets = try allocator.alloc(CallDirectTarget, direct_calls.len);
        for (direct_calls, table.call_direct_targets) |call, *target| {
            const callee = env.store.getExpr(call).e_call.func;
            target.* = .{
                .call = call,
                .target = table.lookupIdByExpr(callee) orelse
                    checkedModuleInvariant("a direct procedure call's callee has no resolved lookup", .{}),
            };
        }
        return table;
    }

    /// The reference of a lookup expression.
    pub fn lookupIdByExpr(self: *const ResolvedValueRefTable, expr: CIR.Expr.Idx) ?ResolvedValueRefId {
        const index = store_serialize.binarySearchIndexByKey(ResolvedValueRefRecord, CIR.Expr.Idx, self.records, expr, struct {
            fn order(record: ResolvedValueRefRecord, key: CIR.Expr.Idx) std.math.Order {
                return std.math.order(@backingInt(record.expr), @backingInt(key));
            }
        }.order) orelse return null;
        return @fromBackingInt(@intCast(@as(u32, @intCast(index))));
    }

    /// Whether lowering evaluates `expr` as a runtime error because reference
    /// resolution rejected it.
    pub fn exprIsRetired(self: *const ResolvedValueRefTable, expr: CIR.Expr.Idx) bool {
        const raw: u32 = @backingInt(expr);
        std.debug.assert(raw >> 6 < self.retired_exprs.len);
        return self.retired_exprs[raw >> 6] & (@as(u64, 1) << @intCast(raw & 63)) != 0;
    }

    /// The bit-packed node words of a module with `node_count` nodes.
    pub fn retiredWords(allocator: Allocator, node_count: usize) Allocator.Error![]u64 {
        const words = try allocator.alloc(u64, (node_count + 63) / 64);
        @memset(words, 0);
        return words;
    }

    pub fn setRetired(words: []u64, expr: CIR.Expr.Idx) void {
        const raw: u32 = @backingInt(expr);
        words[raw >> 6] |= @as(u64, 1) << @intCast(raw & 63);
    }

    /// The direct procedure target of a call, if it has one.
    pub fn callDirectTarget(self: *const ResolvedValueRefTable, call: CIR.Expr.Idx) ?ResolvedValueId {
        const found = store_serialize.binarySearchByKey(CallDirectTarget, CIR.Expr.Idx, self.call_direct_targets, call, CallDirectTarget.order) orelse return null;
        return found.target;
    }

    /// The original callable identity of a procedure reference. Alias use
    /// types and substitutions still belong to the requesting record.
    pub fn callableTarget(self: *const ResolvedValueRefTable, id: ResolvedValueRefId) ResolvedValueRefRecord {
        const record = self.records[@backingInt(id)];
        if (record.ref == .local_proc and record.ref.local_proc.is_alias) {
            const target = record.ref.local_proc.alias_target orelse
                checkedModuleInvariant("callable alias has no published target", .{});
            return self.records[@backingInt(target)];
        }
        return record;
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};
/// Short name for the resolved checked value table.
pub const ResolvedValueTable = ResolvedValueRefTable;

/// A recorded value reference's target in the module's ids.
fn resolvedValueRefFor(
    module: TypedCIR.Module,
    module_key: CheckedModuleKey,
    reference: ModuleEnv.ValueReference,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    templates: *const CheckedProcedureTemplateTable,
    platform_required_declarations: PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    top_level_values: *const TopLevelValueTable,
    selected_hoisted_callables: *const SelectedHoistedCallableTable,
    hoisted_constants: *const HoistedConstTable,
) Allocator.Error!ResolvedValueRef {
    return switch (reference.target) {
        .local_param => |binder| .{ .local_param = .{ .binder = binder } },
        .local_value => |binder| .{ .local_value = .{ .binder = binder } },
        .local_mutable_version => |binder| .{ .local_mutable_version = .{ .binder = binder } },
        .pattern_binder => |binder| .{ .pattern_binder = .{ .binder = binder } },
        .local_procedure => |procedure| .{ .local_proc = .{
            .binder = procedure.binder,
            .expr = procedure.expr,
            .is_alias = procedure.alias_target != null,
        } },
        .top_level => |def| categorizeTopLevelValueRef(
            module,
            module_key,
            top_level_values.lookupByDef(def) orelse checkedModuleInvariant("a top-level lookup target is not a top-level value", .{}),
            templates,
        ),
        .hoisted_procedure => |pattern| .{ .top_level_proc = .{
            .binding = .{ .top_level = .{
                .module = module_key.digest(),
                .binding = selected_hoisted_callables.lookupByPattern(pattern) orelse
                    checkedModuleInvariant("a hoisted procedure lookup has no published binding", .{}),
            } },
            .runtime_result_provenance = null,
        } },
        .promoted_procedure => |pattern| .{ .promoted_top_level_proc = .{
            .binding = .{ .top_level = .{
                .module = module_key.digest(),
                .binding = selected_hoisted_callables.lookupPromotedByPattern(pattern) orelse
                    checkedModuleInvariant("a promoted procedure lookup has no published binding", .{}),
            } },
            .runtime_result_provenance = null,
        } },
        .hoisted_constant => |pattern| selectedHoistedConstUse(
            hoisted_constants.lookupByPattern(pattern) orelse
                checkedModuleInvariant("a hoisted constant lookup has no published constant", .{}),
            .{ .binder = pattern },
        ),
        .imported => blk: {
            const imported = module.expr(reference.expr).data.e_lookup_external;
            break :blk try categorizeImportedValueRef(module, imported.module_idx, imported.target_node_idx, imports);
        },
        .associated => try categorizeResolvedAssociatedValueRef(
            module,
            module.expr(reference.expr).data.e_lookup_associated_resolved.module_identity,
            module.expr(reference.expr).data.e_lookup_associated_resolved.target_def_idx,
            imports,
            available_modules,
        ),
        .required => |requires_idx| categorizeRequiredValueRef(
            requires_idx,
            platform_required_declarations,
            platform_required_bindings,
        ),
    };
}

fn attachUseTypePayload(
    ref: *ResolvedValueRef,
    checked_ty: CheckedTypeId,
) Allocator.Error!void {
    switch (ref.*) {
        inline .top_level_const, .imported_const => |*use| {
            use.requested_source_ty_payload = checked_ty;
        },
        .selected_hoisted_const => |*selected| {
            selected.const_use.requested_source_ty_payload = checked_ty;
        },
        .platform_required_const => |*required| {
            if (required.const_use.requested_source_ty_payload == null) {
                checkedModuleInvariant("platform-required const use missing relation-owned requested payload", .{});
            }
        },
        inline .top_level_proc, .imported_proc, .hosted_proc => |*use| {
            use.source_fn_ty_payload = checked_ty;
        },
        .platform_required_proc => |*required| {
            if (required.procedure.source_fn_ty_payload == null) {
                checkedModuleInvariant("platform-required procedure use missing relation-owned requested payload", .{});
            }
        },
        .promoted_top_level_proc => |*use| {
            use.source_fn_ty_payload = checked_ty;
        },
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .platform_required_declaration,
        .platform_required_checked_error,
        => {},
    }
}

fn categorizeTopLevelValueRef(
    module: TypedCIR.Module,
    module_key: CheckedModuleKey,
    entry: TopLevelValueEntry,
    templates: *const CheckedProcedureTemplateTable,
) ResolvedValueRef {
    return switch (entry.value) {
        .const_ref => |const_ref| .{ .top_level_const = .{
            .const_ref = const_ref,
        } },
        .procedure_binding => |binding| if (hostedProcedureTemplate(module, templates, entry.def)) |template|
            .{ .hosted_proc = .{
                .binding = .{ .hosted = .{
                    .module_idx = module.moduleIndex(),
                    .def = entry.def,
                    .proc = .{ .module = template.module, .proc_base = template.proc_base },
                    .template = template,
                } },
                .intrinsic = null,
                .iterator_procedure = null,
                .runtime_result_provenance = null,
            } }
        else
            .{ .top_level_proc = .{
                .binding = .{ .top_level = .{
                    .module = module_key.digest(),
                    .binding = binding,
                } },
                .intrinsic = intrinsicForProcedureDef(module, entry.def),
                .iterator_procedure = iteratorProcedureForDef(module, entry.def),
                .runtime_result_provenance = runtimeResultProvenanceForProcedureDef(module, entry.def),
            } },
    };
}

fn selectedHoistedConstUse(
    entry: HoistedConstEntry,
    local: LocalBindingRef,
) ResolvedValueRef {
    return .{ .selected_hoisted_const = .{
        .local = local,
        .const_use = .{
            .const_ref = entry.const_ref,
        },
    } };
}

fn categorizeImportedValueRef(
    module: TypedCIR.Module,
    import_idx: CIR.Import.Idx,
    target_node_idx: u32,
    imports: []const CheckedImport,
) Allocator.Error!ResolvedValueRef {
    const resolved_module_idx = module.resolvedImportModule(import_idx) orelse {
        base.invariant(
            "checked module invariant violated: external lookup import {d} has no resolved module",
            .{@backingInt(import_idx)},
        );
    };
    const import_module = checkedImportForModule(imports, resolved_module_idx) orelse {
        base.invariant(
            "checked module invariant violated: external lookup import {d} resolved to module {d} without a checked module key",
            .{ @backingInt(import_idx), resolved_module_idx },
        );
    };

    const target_def: CIR.Def.Idx = @fromBackingInt(@intCast(@as(u32, @intCast(target_node_idx))));
    if (try importedProcedureBindingForDef(import_module.view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (try importedConstTemplateForDef(import_module.view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
        } };
    }

    base.invariant(
        "checked module invariant violated: external lookup target {d} in module {d} was not exported by the imported checked module",
        .{ target_node_idx, resolved_module_idx },
    );
}

fn categorizeResolvedAssociatedValueRef(
    module: TypedCIR.Module,
    module_identity: base.ModuleIdentity.Idx,
    target_def: CIR.Def.Idx,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
) Allocator.Error!ResolvedValueRef {
    const origin_hash = module.moduleEnvConst().moduleIdentityHash(module_identity);
    const target_view = importedViewForOriginHash(imports, available_modules, origin_hash) orelse
        checkedModuleInvariant("resolved associated lookup target has no available checked module", .{});

    if (try importedProcedureBindingForDef(target_view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (try importedConstTemplateForDef(target_view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
        } };
    }

    return checkedModuleInvariant("resolved associated lookup target was not exported by its checked module", .{});
}

fn importedViewForOriginHash(
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    origin_hash: *const base.ModuleIdentity.Hash,
) ?ImportedModuleView {
    var found: ?ImportedModuleView = null;
    for (imports) |*import| {
        if (!importedViewIdentityMatches(&import.view, origin_hash)) continue;
        found = uniqueImportedView(found, import.view);
    }
    for (available_modules) |*view| {
        if (!importedViewIdentityMatches(view, origin_hash)) continue;
        found = uniqueImportedView(found, view.*);
    }
    return found;
}

fn uniqueImportedView(existing: ?ImportedModuleView, next: ImportedModuleView) ImportedModuleView {
    if (existing) |found| {
        if (!CheckedModuleKey.eql(found.key, next.key)) {
            checkedModuleInvariant("module identity resolved to multiple checked modules", .{});
        }
        return found;
    }
    return next;
}

fn importedProcedureBindingForDef(view: ImportedModuleView, def: CIR.Def.Idx) Allocator.Error!?ImportedProcedureBindingView {
    return (try view.exportRows()).procedureBindingByDef(def);
}

fn importedConstTemplateForDef(view: ImportedModuleView, def: CIR.Def.Idx) Allocator.Error!?ImportedConstTemplateView {
    for ((try view.exportRows()).const_templates) |template| {
        if (template.def == def) return template;
    }
    return null;
}

/// The definitions a module exports, in export order: its `exports`, then
/// each exposed item that names a definition.
pub fn collectExportDefs(
    allocator: Allocator,
    module_env: *const ModuleEnv,
) Allocator.Error![]CIR.Def.Idx {
    var defs = std.ArrayList(CIR.Def.Idx).empty;
    errdefer defs.deinit(allocator);

    const node_count = module_env.store.nodes.len();
    const seen = try allocator.alloc(bool, node_count);
    defer allocator.free(seen);
    @memset(seen, false);

    for (module_env.store.sliceDefs(module_env.exports)) |def_idx| {
        try appendExportDef(allocator, &defs, seen, def_idx);
    }

    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= node_count) {
            base.invariant(
                "checked module invariant violated: exposed item {s} points at out-of-range node {d}",
                .{ module_env.getIdent(@bitCast(entry.ident_idx)), raw_node_idx },
            );
        }

        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        if (module_env.store.nodes.get(node_idx).tag != .def) continue;
        try appendExportDef(allocator, &defs, seen, @fromBackingInt(@intCast(raw_node_idx)));
    }

    return try defs.toOwnedSlice(allocator);
}

fn appendExportDef(
    allocator: Allocator,
    defs: *std.ArrayList(CIR.Def.Idx),
    seen: []bool,
    def_idx: CIR.Def.Idx,
) Allocator.Error!void {
    const raw = @backingInt(def_idx);
    if (raw >= seen.len) {
        base.invariant(
            "checked module invariant violated: export def {d} is outside the module node store",
            .{raw},
        );
    }
    if (seen[raw]) return;
    seen[raw] = true;
    try defs.append(allocator, def_idx);
}

/// The binder patterns of names bound by top-level destructures that the
/// module exposes. An importer reaches such a name through its binder node
/// (see `Can.populateExports`), so the export tables key its row by that node.
fn collectExportBinders(
    allocator: Allocator,
    module_env: *const ModuleEnv,
) Allocator.Error![]CIR.Pattern.Idx {
    var binders = std.ArrayList(CIR.Pattern.Idx).empty;
    errdefer binders.deinit(allocator);

    const node_count = module_env.store.nodes.len();
    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= node_count) continue;
        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        const tag = module_env.store.nodes.get(node_idx).tag;
        if (tag != .pattern_identifier and tag != .pattern_var_identifier and tag != .pattern_as) continue;
        const binder: CIR.Pattern.Idx = @fromBackingInt(@intCast(raw_node_idx));
        for (binders.items) |seen| {
            if (seen == binder) break;
        } else {
            try binders.append(allocator, binder);
        }
    }

    return try binders.toOwnedSlice(allocator);
}

fn checkedImportForModule(imports: []const CheckedImport, module_idx: u32) ?CheckedImport {
    for (imports) |import_module| {
        if (import_module.module_idx == module_idx) return import_module;
    }
    return null;
}

fn categorizeRequiredValueRef(
    requires_idx: u32,
    platform_required_declarations: PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
) ResolvedValueRef {
    const binding = platformBindingForRequiredIndex(platform_required_bindings, requires_idx) orelse {
        if (platform_required_bindings.isCheckedError(requires_idx)) {
            return .platform_required_checked_error;
        }
        const declaration = platform_required_declarations.lookupByRequiredIndex(requires_idx) orelse {
            base.invariant(
                "checked module invariant violated: required lookup {d} has no platform declaration",
                .{requires_idx},
            );
        };
        return .{ .platform_required_declaration = declaration.id };
    };

    return switch (binding.value_use) {
        .const_value => |const_use| .{ .platform_required_const = .{
            .binding = binding.id,
            .const_use = const_use.const_use,
        } },
        .procedure_value => |procedure_use| .{ .platform_required_proc = .{
            .binding = binding.id,
            .procedure = procedure_use.procedure,
            .root_evidence = procedure_use.root_evidence,
        } },
    };
}

/// The procedure template of `def_idx` when the hosted transform rewrote it
/// to a hosted lambda.
fn hostedProcedureTemplate(module: TypedCIR.Module, templates: *const CheckedProcedureTemplateTable, def_idx: CIR.Def.Idx) ?canonical.ProcedureTemplateRef {
    if (module.def(def_idx).expr.data != .e_hosted_lambda) return null;
    return templates.lookupByDef(def_idx) orelse checkedModuleInvariant("hosted procedure def has no checked template", .{});
}

fn platformBindingForRequiredIndex(table: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
    return table.lookupByRequiredIndex(requires_idx);
}

/// Whether a pattern introduces a name: an assign, var-assign, or as pattern.
fn patternBindsName(env: *const ModuleEnv, pattern: CIR.Pattern.Idx) bool {
    return switch (env.store.getPattern(pattern)) {
        .assign, .var_assign, .as => true,
        .applied_tag, .nominal, .nominal_external, .record_destructure, .list, .tuple, .num_literal, .num_from_numeral_literal, .small_dec_literal, .dec_literal, .frac_f32_literal, .frac_f64_literal, .str_literal, .str_interpolation, .underscore, .runtime_error, .deferred_import_ref => false,
    };
}

/// A generalized local function scope collected while walking template
/// bodies: `constraint(depth, k)` resolutions index the innermost enclosing
/// scope's canonical evidence params at depth 0, walking outward to the
/// template's own params.
pub const DispatchRefScope = struct {
    /// Enclosing generalized-local scope, or `null` for the template itself.
    parent: ?DispatchScopeId,
    /// The local function's scheme root var (its decl pattern var).
    scheme_var: Var,
    /// Published checked root of `scheme_var`; specialization evidence paths
    /// are authored relative to this exact callable shape.
    scheme_root: CheckedTypeId,
    /// Checked local-function expression that owns this scope.
    checked_expr: CIR.Expr.Idx,
};

/// Stable identity of a generalized-local dispatch scope within a checked
/// module.
pub const DispatchScopeId = checked_ids.DispatchScopeId;

/// Scope owning a checked dispatch reference. The template root is a real
/// variant, never an integer value that can be mistaken for a local scope id.
pub const DispatchScope = union(enum) {
    root,
    generalized: DispatchScopeId,
};

/// Checked relation shape Monotype must instantiate before specializing the
/// scope that owns a dispatch reference.
pub const DispatchRelationKind = enum(u8) {
    callable_result,
    conversion,
};

/// A checker-authored type relation needed to close a procedure interface
/// before Monotype chooses a specialization identity. These records contain
/// no executable-body semantics: they preserve checked equalities, procedure
/// results, ordinary call edges, and generalized local-procedure
/// instantiations.
pub const SpecializationInterfaceRelation = struct {
    scope: DispatchScope,
    data: Data,

    pub const Data = union(enum) {
        type_equality: struct {
            left: CheckedTypeId,
            right: CheckedTypeId,
        },
        procedure: struct {
            fn_ty: CheckedTypeId,
            /// The type the body delivers at the function's return: the
            /// body's own type, or the composed `Try` when a `?` return
            /// composes the result and the body's value crosses the explicit
            /// return boundary into it (design.md "Inferred Try Return-Row
            /// Composition").
            body_ret_ty: CheckedTypeId,
            owns_scope: bool,
        },
        call: struct {
            callable_ty: CheckedTypeId,
            callee_ty: CheckedTypeId,
            ret_ty: CheckedTypeId,
            args: store_serialize.Span,
            direct_target: ?ResolvedValueRefId,
        },
        local_proc_use: ResolvedValueRefId,
    };
};

const CollectedSchemeUseSite = struct {
    record_idx: u32,
    checked_expr: CIR.Expr.Idx,
};

const CollectedScopeConstructionSite = struct {
    scope: DispatchScopeId,
    checked_expr: CIR.Expr.Idx,
};

/// Nested functions that own a callable-derived dispatch scope, keyed by
/// checked expression, each mapped to its own type variable.
///
/// A function no construction edge generalized (a lambda that supplies a
/// conditional's, match's, or block's value inside a stored value) shares its
/// variables with the value holding it. When checking left such a variable
/// unquantified and constrained, nothing in this module pins it, yet every
/// importing use copies the value's type and requests the function at a
/// concrete one. The function's own callable type is then the path to that
/// receiver, exactly as a generalized nested function's scheme is, so its
/// scope publishes those requirements as callable-derived parameters instead
/// of letting the unpinned-dispatch rule commit them to `unreachable`. Only a
/// function whose type reaches the receiver of a dispatch plan checking left
/// unquantified owns one; a module with no such plan walks no types.
fn collectCallableDerivedSchemes(
    allocator: Allocator,
    module: TypedCIR.Module,
    module_index: *const ModuleIndex,
    plans: *const static_dispatch.StaticDispatchPlanTable,
    local_schemes: *const collections.DenseMap(u32, Var),
    out: *collections.DenseMap(u32, Var),
) Allocator.Error!void {
    const types_store = module.typeStoreConst();
    var unquantified = collections.DenseMap(Var, void).init(allocator);
    defer unquantified.deinit();
    for (plans.plan_sources) |source| {
        try noteUnquantifiedReceiver(types_store, source.dispatcher_var, &unquantified);
    }
    for (plans.iterator_plan_sources) |source| {
        try noteUnquantifiedReceiver(types_store, source.iter_dispatcher_var, &unquantified);
        try noteUnquantifiedReceiver(types_store, source.next_dispatcher_var, &unquantified);
    }
    if (unquantified.count() == 0) return;

    // A closure's scope belongs to the closure, never to the lambda it wraps.
    var closure_lambdas = collections.DenseMap(CIR.Expr.Idx, void).init(allocator);
    defer closure_lambdas.deinit();
    var raw_node: u32 = 0;
    while (raw_node < module.nodeCount()) : (raw_node += 1) {
        if (module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .expr_closure) continue;
        const closure_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw_node));
        try closure_lambdas.put(module.expr(closure_expr).data.e_closure.lambda_idx, {});
    }

    var scratch = dispatch_evidence.Scratch{};
    defer scratch.deinit(allocator);
    var params = std.ArrayListUnmanaged(dispatch_evidence.EvidenceParam).empty;
    defer params.deinit(allocator);
    raw_node = 0;
    while (raw_node < module.nodeCount()) : (raw_node += 1) {
        const tag = module.nodeTag(@fromBackingInt(@intCast(raw_node)));
        if (tag != .expr_lambda and tag != .expr_closure) continue;
        const source_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw_node));
        if (closure_lambdas.contains(source_expr)) continue;
        if (!module_index.reachesExpr(source_expr)) continue;
        const checked_expr = source_expr;
        if (local_schemes.contains(@backingInt(checked_expr))) continue;
        const fn_var = ModuleEnv.varFrom(source_expr);
        params.clearRetainingCapacity();
        try dispatch_evidence.enumerateEvidenceParams(allocator, types_store, fn_var, &scratch, &params);
        for (params.items) |param| {
            if (param.path_len == 0) continue;
            if (!unquantified.contains(types_store.resolveVar(param.dispatcher_var).var_)) continue;
            try out.put(@backingInt(checked_expr), fn_var);
            break;
        }
    }
}

fn noteUnquantifiedReceiver(
    types_store: *const types.Store,
    receiver: Var,
    out: *collections.DenseMap(Var, void),
) Allocator.Error!void {
    const resolved = types_store.resolveVar(receiver);
    if (resolved.desc.rank == .generalized) return;
    switch (resolved.desc.content) {
        .flex => try out.put(resolved.var_, {}),
        .rigid, .alias, .structure, .field_presence, .err => {},
    }
}

fn sealCheckedProcedureTemplateRefs(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedSourceTypes,
    bodies: CheckedBodies,
    diagnostics: *const body_analyses.NodeBits,
    default_exprs: []const CIR.Expr.Idx,
    compile_time_roots: *const CompileTimeRootTable,
    entry_wrappers: *const EntryWrapperTable,
    templates: *CheckedProcedureTemplateTable,
    static_dispatch_plans: *static_dispatch.StaticDispatchPlanTable,
    method_registry: *static_dispatch.MethodRegistry,
    resolved_value_refs: *ResolvedValueRefTable,
) Allocator.Error!void {
    // Local functions with dispatch obligations: entering one while collecting
    // pushes an evidence scope. Declarations map to their pattern scheme;
    // expression-position functions stored in a containing value map to the
    // pristine scheme instantiated at that construction edge.
    var local_schemes = collections.DenseMap(u32, Var).init(allocator);
    defer local_schemes.deinit();
    var nested_function_uses = collections.DenseMap(u32, u32).init(allocator);
    defer nested_function_uses.deinit();
    var callable_derived_schemes = collections.DenseMap(u32, Var).init(allocator);
    defer callable_derived_schemes.deinit();
    {
        const types_store = module.typeStoreConst();

        // Every reference that instantiated a scheme is a record checking
        // wrote, naming the exact scheme root it instantiated. A local
        // definition named that way owns an evidence scope: its uses carry the
        // evidence vector that scope schedules. Reading the records is what
        // decides this, because the pattern var's rank answers a different
        // question—whether let-generalization ran—and a definition whose body
        // defers a dispatch to its caller is instantiated at its uses while
        // that rank settles at `.outermost`.
        var instantiated_scheme_roots = collections.DenseMap(Var, void).init(allocator);
        defer instantiated_scheme_roots.deinit();
        for (module.moduleEnvConst().scheme_uses.items.items) |record| {
            switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
                .value_use, .shared_value_use => try instantiated_scheme_roots.put(
                    @fromBackingInt(@intCast(record.scheme_root)),
                    {},
                ),
                .nested_function_use, .dispatch_target, .recursive_dispatch_target, .recursive_reference, .recursive_value_reference, .where_method_use => {},
            }
        }

        // A promoted local function is the root of its own template, whose
        // scheme is the template's; it opens no generalized-local scope.
        var promoted_patterns = collections.DenseMap(CIR.Pattern.Idx, void).init(allocator);
        defer promoted_patterns.deinit();
        for (templates.promoted) |promoted| try promoted_patterns.put(promoted.pattern, {});

        var raw_node: u32 = 0;
        while (raw_node < module.nodeCount()) : (raw_node += 1) {
            if (module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .statement_decl) continue;
            const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node));
            const statement_data = module.getStatement(statement);
            if (statement_data != .s_decl) continue;
            const decl = statement_data.s_decl;
            if (promoted_patterns.contains(decl.pattern)) continue;
            const expr_data = module.expr(decl.expr).data;
            const is_alias = bodies.index().isSchemeAlias(decl.pattern);
            if (!is_alias and expr_data != .e_lambda and expr_data != .e_closure) continue;
            const pattern_var = ModuleEnv.varFrom(decl.pattern);
            const generalized = types_store.resolveVar(pattern_var).desc.rank == .generalized;
            if (!is_alias and !generalized and !instantiated_scheme_roots.contains(pattern_var)) continue;
            if (!bodies.index().reachesExpr(decl.expr)) continue;
            try local_schemes.put(@backingInt(decl.expr), pattern_var);
        }

        for (module.moduleEnvConst().scheme_uses.items.items, 0..) |record, record_idx| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) continue;
            if (bodies.index().nodeKind(record.node_idx) != .expr) continue;
            try local_schemes.put(record.node_idx, @fromBackingInt(@intCast(record.scheme_root)));
            try nested_function_uses.put(record.node_idx, @intCast(record_idx));
        }

        try collectCallableDerivedSchemes(allocator, module, bodies.index(), static_dispatch_plans, &local_schemes, &callable_derived_schemes);
    }

    var collector = CheckedTemplateRefCollector.init(
        allocator,
        module,
        checked_types,
        bodies,
        diagnostics,
        static_dispatch_plans,
        &local_schemes,
        &nested_function_uses,
        &callable_derived_schemes,
    );
    defer collector.deinit();

    // Flatten each template's collected refs into the two shared per-table pools,
    // recording each template's sub-range. Growing the pools as lists keeps the pass
    // amortized-O(1) per template; both tables then take ownership of the finished
    // pool as a single slice.
    var value_ref_pool = std.ArrayList(ResolvedValueRefId).empty;
    errdefer value_ref_pool.deinit(allocator);
    var dispatch_ref_pool = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    errdefer dispatch_ref_pool.deinit(allocator);
    var iterator_ref_pool = std.ArrayList(static_dispatch.IteratorForPlanId).empty;
    errdefer iterator_ref_pool.deinit(allocator);
    var value_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer value_ref_scope_pool.deinit(allocator);
    var dispatch_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer dispatch_ref_scope_pool.deinit(allocator);
    var dispatch_relation_kind_pool = std.ArrayList(DispatchRelationKind).empty;
    errdefer dispatch_relation_kind_pool.deinit(allocator);
    var iterator_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer iterator_scope_pool.deinit(allocator);
    var scheme_use_pool = std.ArrayList(CollectedSchemeUseSite).empty;
    errdefer scheme_use_pool.deinit(allocator);
    var scheme_use_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer scheme_use_scope_pool.deinit(allocator);
    var scope_site_pool = std.ArrayList(CollectedScopeConstructionSite).empty;
    errdefer scope_site_pool.deinit(allocator);
    var specialization_relation_pool = std.ArrayList(SpecializationInterfaceRelation).empty;
    errdefer specialization_relation_pool.deinit(allocator);
    var specialization_type_pool = std.ArrayList(CheckedTypeId).empty;
    errdefer specialization_type_pool.deinit(allocator);
    // One entry per template, then the defaulted-field expressions'.
    const iterator_spans = try allocator.alloc(store_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(iterator_spans);
    const scheme_use_spans = try allocator.alloc(store_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(scheme_use_spans);
    const scope_site_spans = try allocator.alloc(store_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(scope_site_spans);

    for (templates.templates.items, 0..) |*template, template_index| {
        collector.clear();

        switch (template.body) {
            .checked_body => |root_expr| {
                collector.template_root_expr = root_expr;
                try collector.collectExpr(root_expr);
            },
            .entry_wrapper => |wrapper_id| {
                const wrapper = entry_wrappers.get(wrapper_id);
                const root = compile_time_roots.root(wrapper.root);
                const parts = root.bodyParts();
                // A literal root's entry wrapper is no row of the table.
                if (parts.literal != null) checkedModuleInvariant("a literal conversion root's wrapper is a row of the template table", .{});
                if (parts.expr) |expr| try collector.collectExpr(expr);
                if (parts.pattern) |pattern| try collector.collectPattern(pattern);
                if (!rootBodyContainsDiagnosticError(diagnostics, root)) try collector.specialization_relations.append(allocator, .{
                    .scope = collector.currentScope(),
                    .data = .{ .procedure = .{
                        .fn_ty = template.checked_fn_root,
                        .body_ret_ty = if (root.evaluatedExpr()) |evaluated| try bodies.exprType(evaluated) else root.checked_type,
                        .owns_scope = true,
                    } },
                });
            },
            .literal_root => checkedModuleInvariant("a literal root's entry wrapper is a row of the template table", .{}),
            // Neither an intrinsic wrapper nor an unimplemented declaration
            // has a checked body to collect plans from.
            .intrinsic_wrapper, .unimplemented => {},
        }

        var seen_local_uses = collections.DenseMap(ResolvedValueRefId, void).init(allocator);
        defer seen_local_uses.deinit();
        for (collector.value_refs.items, collector.value_ref_scopes.items) |ref_id, use_scope| {
            const seen = try seen_local_uses.getOrPut(ref_id);
            if (seen.found_existing) continue;
            const record = resolved_value_refs.records[@backingInt(ref_id)];
            if (diagnostics.isSet(@backingInt(record.expr))) continue;
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .type_equality = .{
                    .left = record.checked_ty,
                    .right = try bodies.exprType(record.expr),
                } },
            });
            const local = switch (record.ref) {
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                => |binding| {
                    try collector.specialization_relations.append(allocator, .{
                        .scope = use_scope,
                        .data = .{ .type_equality = .{
                            .left = record.checked_ty,
                            .right = try bodies.patternType(binding.binder),
                        } },
                    });
                    continue;
                },
                .local_proc => |local| local,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                .platform_required_proc,
                .promoted_top_level_proc,
                => continue,
            };
            if (collector.scope_by_checked_expr.get(local.expr) == null) {
                try collector.specialization_relations.append(allocator, .{
                    .scope = use_scope,
                    .data = .{ .type_equality = .{
                        .left = record.checked_ty,
                        .right = try bodies.exprType(local.expr),
                    } },
                });
                continue;
            }
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .local_proc_use = ref_id },
            });
        }

        template.resolved_value_refs = try store_serialize.appendSpan(ResolvedValueRefTableRef, ResolvedValueRefId, &value_ref_pool, allocator, collector.value_refs.items);
        template.static_dispatch_plans = try store_serialize.appendSpan(@TypeOf(template.static_dispatch_plans), static_dispatch.StaticDispatchPlanId, &dispatch_ref_pool, allocator, collector.dispatch_refs.items);
        const specialization_type_base: u32 = @intCast(specialization_type_pool.items.len);
        try specialization_type_pool.appendSlice(allocator, collector.specialization_types.items);
        const specialization_relation_start: u32 = @intCast(specialization_relation_pool.items.len);
        try specialization_relation_pool.ensureUnusedCapacity(allocator, collector.specialization_relations.items.len);
        for (collector.specialization_relations.items) |raw_relation| {
            var relation = raw_relation;
            switch (relation.data) {
                .call => |*call| call.args.start += specialization_type_base,
                .type_equality, .procedure, .local_proc_use => {},
            }
            specialization_relation_pool.appendAssumeCapacity(relation);
        }
        template.specialization_interface_relations = .{
            .start = specialization_relation_start,
            .len = @intCast(collector.specialization_relations.items.len),
        };
        for (collector.dispatch_refs.items) |plan_id| {
            const plan = static_dispatch_plans.plans[@backingInt(plan_id)];
            var kind: DispatchRelationKind = .callable_result;
            for (plan.argsSlice(static_dispatch_plans)) |operand| switch (operand) {
                .generated_numeral, .generated_quote => kind = .conversion,
                .checked_expr, .generated_interpolation_segments, .literal_pattern_value, .literal_pattern_conversion => {},
            };
            try dispatch_relation_kind_pool.append(allocator, kind);
        }
        iterator_spans[template_index] = try store_serialize.appendSpan(store_serialize.Span, static_dispatch.IteratorForPlanId, &iterator_ref_pool, allocator, collector.iterator_refs.items);
        scheme_use_spans[template_index] = try store_serialize.appendSpan(store_serialize.Span, CollectedSchemeUseSite, &scheme_use_pool, allocator, collector.scheme_use_sites.items);
        scope_site_spans[template_index] = try store_serialize.appendSpan(store_serialize.Span, CollectedScopeConstructionSite, &scope_site_pool, allocator, collector.scope_sites.items);
        try value_ref_scope_pool.appendSlice(allocator, collector.value_ref_scopes.items);
        try dispatch_ref_scope_pool.appendSlice(allocator, collector.dispatch_ref_scopes.items);
        try iterator_scope_pool.appendSlice(allocator, collector.iterator_ref_scopes.items);
        try scheme_use_scope_pool.appendSlice(allocator, collector.scheme_use_scopes.items);
    }

    // Defaulted-field expressions (design.md "Defaulted Fields") are value
    // expressions no template body reaches: each is lowered standalone at
    // every construction site that omits its field. Collect their refs
    // exactly like a template body so the evidence pass publishes site
    // evidence for the calls and scheme instantiations inside them—
    // without this, a default calling a generic procedure reaches lowering
    // with no checked evidence vector for the callee's requirements.
    const default_ref_spans = try allocator.alloc(store_serialize.Span, 2);
    errdefer allocator.free(default_ref_spans);
    const defaults = templates.templates.items.len;
    {
        collector.clear();
        for (default_exprs) |default| {
            try collector.collectExpr(default);
        }
        default_ref_spans[TemplateDispatchSites.default_plan_refs] = try store_serialize.appendSpan(store_serialize.Span, static_dispatch.StaticDispatchPlanId, &dispatch_ref_pool, allocator, collector.dispatch_refs.items);
        default_ref_spans[TemplateDispatchSites.default_value_refs] = try store_serialize.appendSpan(store_serialize.Span, ResolvedValueRefId, &value_ref_pool, allocator, collector.value_refs.items);
        iterator_spans[defaults] = try store_serialize.appendSpan(store_serialize.Span, static_dispatch.IteratorForPlanId, &iterator_ref_pool, allocator, collector.iterator_refs.items);
        scheme_use_spans[defaults] = try store_serialize.appendSpan(store_serialize.Span, CollectedSchemeUseSite, &scheme_use_pool, allocator, collector.scheme_use_sites.items);
        scope_site_spans[defaults] = try store_serialize.appendSpan(store_serialize.Span, CollectedScopeConstructionSite, &scope_site_pool, allocator, collector.scope_sites.items);
        // `dispatch_relation_kind_pool` stays parallel to the plan-ref pool.
        for (collector.dispatch_refs.items) |plan_id| {
            const plan = static_dispatch_plans.plans[@backingInt(plan_id)];
            var kind: DispatchRelationKind = .callable_result;
            for (plan.argsSlice(static_dispatch_plans)) |operand| switch (operand) {
                .generated_numeral, .generated_quote => kind = .conversion,
                .checked_expr, .generated_interpolation_segments, .literal_pattern_value, .literal_pattern_conversion => {},
            };
            try dispatch_relation_kind_pool.append(allocator, kind);
        }
        try value_ref_scope_pool.appendSlice(allocator, collector.value_ref_scopes.items);
        try dispatch_ref_scope_pool.appendSlice(allocator, collector.dispatch_ref_scopes.items);
        try iterator_scope_pool.appendSlice(allocator, collector.iterator_ref_scopes.items);
        try scheme_use_scope_pool.appendSlice(allocator, collector.scheme_use_scopes.items);
    }

    resolved_value_refs.template_refs = try value_ref_pool.toOwnedSlice(allocator);
    templates.dispatch_plan_refs = try dispatch_ref_pool.toOwnedSlice(allocator);
    templates.dispatch_ref_scopes = try dispatch_ref_scope_pool.toOwnedSlice(allocator);
    templates.dispatch_relation_kinds = try dispatch_relation_kind_pool.toOwnedSlice(allocator);
    templates.dispatch_scopes = try allocator.dupe(DispatchRefScope, collector.scopes.items);
    templates.specialization_interface_relations = try specialization_relation_pool.toOwnedSlice(allocator);
    templates.specialization_interface_types = try specialization_type_pool.toOwnedSlice(allocator);
    recordLocalProcedureDispatchScopes(resolved_value_refs, &collector.scope_by_checked_expr);
    recordLocalMethodDispatchScopes(method_registry, &collector.scope_by_checked_expr);
    templates.dispatch_sites = .{
        .iterator_spans = iterator_spans,
        .iterator_refs = try iterator_ref_pool.toOwnedSlice(allocator),
        .iterator_scopes = try iterator_scope_pool.toOwnedSlice(allocator),
        .value_ref_scopes = try value_ref_scope_pool.toOwnedSlice(allocator),
        .scheme_use_spans = scheme_use_spans,
        .scheme_use_sites = try scheme_use_pool.toOwnedSlice(allocator),
        .scheme_use_scopes = try scheme_use_scope_pool.toOwnedSlice(allocator),
        .scope_site_spans = scope_site_spans,
        .scope_sites = try scope_site_pool.toOwnedSlice(allocator),
        .default_ref_spans = default_ref_spans,
    };
}

/// Attach the producer-owned dispatch scope identity to every use of a local
/// procedure. A generalized local procedure may own a scope even when its
/// checker-ordered evidence list is empty, so presence is determined by the checked
/// scope table rather than by evidence count.
fn recordLocalProcedureDispatchScopes(
    resolved_value_refs: *ResolvedValueRefTable,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
) void {
    for (resolved_value_refs.records) |*record| {
        if (record.ref != .local_proc) continue;
        const local = &record.ref.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

fn recordLocalMethodDispatchScopes(
    method_registry: *static_dispatch.MethodRegistry,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
) void {
    for (method_registry.entries) |*entry| {
        const target = if (entry.target) |*target| target else continue;
        if (target.alias) |*alias| switch (alias.binding) {
            .local => |*local| local.dispatch_scope = scope_by_checked_expr.get(local.lookup),
            .top_level => {},
        };
        if (target.kind != .local_proc) continue;
        const local = &target.kind.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

/// The sites each procedure template's body reaches, collected by
/// `sealCheckedProcedureTemplateRefs` from the template's checked body: its
/// iterator plans, the scope of each collected value reference and iterator
/// plan, its expression-position scheme instantiation sites, and its
/// generalized nested-procedure construction sites. Each per-template span
/// array has one entry per template the collection walked, then one for the
/// module's defaulted-field expressions (`defaults`). Dispatch resolution
/// reads these sites; they are a pure function of each body.
pub const TemplateDispatchSites = struct {
    /// Per template, a range of `iterator_refs`.
    iterator_spans: []store_serialize.Span = &.{},
    iterator_refs: []static_dispatch.IteratorForPlanId = &.{},
    /// Scope of each `iterator_refs` entry.
    iterator_scopes: []DispatchScope = &.{},
    /// Scope of each `ResolvedValueRefTable.template_refs` entry.
    value_ref_scopes: []DispatchScope = &.{},
    /// Per template, a range of `scheme_use_sites`.
    scheme_use_spans: []store_serialize.Span = &.{},
    scheme_use_sites: []CollectedSchemeUseSite = &.{},
    /// Scope of each `scheme_use_sites` entry.
    scheme_use_scopes: []DispatchScope = &.{},
    /// Per template, a range of `scope_sites`.
    scope_site_spans: []store_serialize.Span = &.{},
    scope_sites: []CollectedScopeConstructionSite = &.{},
    /// The defaulted-field expressions' ranges of the plan-ref pool
    /// (`CheckedProcedureTemplateTable.dispatch_plan_refs`) and of the
    /// value-ref pool (`ResolvedValueRefTable.template_refs`).
    default_ref_spans: []store_serialize.Span = &.{},

    pub const default_plan_refs = 0;
    pub const default_value_refs = 1;

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;

    /// The number of templates the collection walked; templates appended
    /// after it reach no sites.
    pub fn walkedTemplateCount(self: *const TemplateDispatchSites) usize {
        return if (self.iterator_spans.len == 0) 0 else self.iterator_spans.len - 1;
    }

    /// The index of the defaulted-field expressions' entries.
    pub fn defaultsIndex(self: *const TemplateDispatchSites) usize {
        return self.walkedTemplateCount();
    }

    pub fn iteratorSpan(self: *const TemplateDispatchSites, index: usize) store_serialize.Span {
        return if (index < self.iterator_spans.len) self.iterator_spans[index] else .{};
    }

    pub fn schemeUseSpan(self: *const TemplateDispatchSites, index: usize) store_serialize.Span {
        return if (index < self.scheme_use_spans.len) self.scheme_use_spans[index] else .{};
    }

    pub fn scopeSiteSpan(self: *const TemplateDispatchSites, index: usize) store_serialize.Span {
        return if (index < self.scope_site_spans.len) self.scope_site_spans[index] else .{};
    }

    pub fn defaultRefs(self: *const TemplateDispatchSites, which: usize) store_serialize.Span {
        return if (self.default_ref_spans.len == 0) .{} else self.default_ref_spans[which];
    }
};

/// The checked types a dispatch analysis reads source variables at: the
/// module's own types.
const DispatchTypes = struct {
    store: *CheckedTypeStore,

    fn rootForSourceVar(self: DispatchTypes, module: TypedCIR.Module, var_: Var) ?CheckedTypeId {
        const resolved = module.typeStoreConst().resolveVar(var_).var_;
        if (!self.store.sealed_var_facts.items[@backingInt(resolved)].reached) return null;
        return type_ids.fromVar(resolved);
    }
};

/// What a consumer reads of one scheme's dispatch requirements: its
/// quantified variables in canonical identity order, its evidence
/// parameters in canonical order, the path nodes the parameters' paths name
/// and their independent callable types.
pub const SchemaView = struct {
    /// The scheme's owning solver variable, which `SchemeParamRef.scheme`
    /// names; null for a template without an evidence scheme.
    scheme: ?u32 = null,
    vars: []const CheckedTypeId = &.{},
    params: []const static_dispatch.EvidenceParamRecord = &.{},
    path_nodes: []const static_dispatch.EvidencePathNode = &.{},
    param_callables: []const CheckedTypeId = &.{},
    /// See `TemplateSchema.callable_determines_scheme`.
    callable_determines_scheme: bool = true,

    pub fn paramCallables(self: SchemaView, param: static_dispatch.EvidenceParamRecord) []const CheckedTypeId {
        return self.param_callables[param.callable_contracts.start..][0..param.callable_contracts.len];
    }

    /// Replace `out`'s contents with the param's dispatcher path over the
    /// scheme callable, root first (empty = pathless).
    pub fn paramPath(
        self: SchemaView,
        allocator: Allocator,
        param: static_dispatch.EvidenceParamRecord,
        out: *std.ArrayListUnmanaged(static_dispatch.EvidencePathStep),
    ) Allocator.Error![]const static_dispatch.EvidencePathStep {
        out.clearRetainingCapacity();
        try dispatch_evidence.appendPathSteps(allocator, self.path_nodes, param.path.last, param.path.len, out);
        return out.items;
    }
};

/// One scheme's requirements as dispatch resolution matches obligations
/// against them: the enumerated parameters, indexed by dispatcher root, and
/// their published records.
const ChainScheme = struct {
    owner: u32,
    params: []const dispatch_evidence.EvidenceParam,
    by_dispatcher: EvidencePass.DispatcherParams,
    published: []const static_dispatch.EvidenceParamRecord,
};

/// The schema of one template or one generalized local scope
/// (`ModuleAnalyses` template and scope schema slots). Allocated in its own
/// arena.
pub const SchemeAnalysis = struct {
    arena: std.heap.ArenaAllocator.State = .{},
    view: SchemaView,
    /// The scheme whose parameters bind the template's or scope's
    /// obligations; null when the template binds none.
    chain: ?ChainScheme,

    pub fn destroy(self: *SchemeAnalysis, allocator: Allocator) void {
        var arena = self.arena.promote(allocator);
        arena.deinit();
        allocator.destroy(self);
    }
};

/// A template's or the module's evidence for one instantiation site.
const DeferredUseSite = struct { record_idx: u32, site_key: u32 };

/// The dispatch resolution of one procedure template
/// (`ModuleAnalyses.templateDispatch`): the plans, iterator plans and sites
/// its body reaches that its scheme chain binds, its root evidence, and the
/// evidence pool all of them name.
pub const TemplateDispatch = struct {
    pool: static_dispatch.EvidencePool,
    /// Sorted by key.
    site_evidence: []static_dispatch.SiteEvidenceEntry,
    /// Sorted by plan.
    plans: []PlanResolutionEntry,
    /// Sorted by plan.
    iterator_plans: []IteratorPlanResolutionEntry,
    /// The template's chain-free root evidence; null for a scheme-only
    /// procedure that requires instantiation evidence.
    root_evidence: ?static_dispatch.EvidenceSpan,
    /// Use sites the template's chain did not bind; the module resolves them
    /// chain-free when no template binds them.
    deferred_sites: []DeferredUseSite,

    pub fn destroy(self: *TemplateDispatch, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.site_evidence);
        allocator.free(self.plans);
        allocator.free(self.iterator_plans);
        allocator.free(self.deferred_sites);
        allocator.destroy(self);
    }

    pub fn plan(self: *const TemplateDispatch, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
        return lookupPlanResolution(self.plans, id);
    }

    pub fn iteratorPlan(self: *const TemplateDispatch, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
        return lookupIteratorPlanResolution(self.iterator_plans, id);
    }

    pub fn site(self: *const TemplateDispatch, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
        return lookupSiteEvidence(self.site_evidence, key);
    }

    /// Whether the template's chain deferred use site `key` to the module.
    pub fn defersSite(self: *const TemplateDispatch, key: u32) bool {
        for (self.deferred_sites) |deferred| {
            if (deferred.site_key == key) return true;
        }
        return false;
    }
};

fn lookupPlanResolution(entries: []const PlanResolutionEntry, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
    const found = store_serialize.binarySearchByKey(PlanResolutionEntry, u32, entries, @backingInt(id), PlanResolutionEntry.order) orelse return null;
    return found.resolution;
}

fn lookupIteratorPlanResolution(entries: []const IteratorPlanResolutionEntry, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
    const found = store_serialize.binarySearchByKey(IteratorPlanResolutionEntry, u32, entries, @backingInt(id), IteratorPlanResolutionEntry.order) orelse return null;
    return found.resolution;
}

fn lookupSiteEvidence(entries: []const static_dispatch.SiteEvidenceEntry, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
    return store_serialize.binarySearchByKey(static_dispatch.SiteEvidenceEntry, u32, entries, key, static_dispatch.siteEvidenceOrder);
}

/// The evidence of one use site and the analysis whose pool holds it.
pub const SiteEvidenceLookup = struct {
    entry: static_dispatch.SiteEvidenceEntry,
    owner: static_dispatch.EvidenceOwner,
};

/// One plan's resolution within an analysis's result, keyed by plan.
pub const PlanResolutionEntry = struct {
    plan: u32,
    resolution: static_dispatch.PlanResolution,

    fn order(entry: PlanResolutionEntry, key: u32) std.math.Order {
        return std.math.order(entry.plan, key);
    }

    fn lessThan(_: void, a: PlanResolutionEntry, b: PlanResolutionEntry) bool {
        return a.plan < b.plan;
    }
};

/// One iterator plan's resolution within an analysis's result, keyed by plan.
pub const IteratorPlanResolutionEntry = struct {
    plan: u32,
    resolution: static_dispatch.IteratorPlanResolution,

    fn order(entry: IteratorPlanResolutionEntry, key: u32) std.math.Order {
        return std.math.order(entry.plan, key);
    }

    fn lessThan(_: void, a: IteratorPlanResolutionEntry, b: IteratorPlanResolutionEntry) bool {
        return a.plan < b.plan;
    }
};

/// How a template's dispatch plans relate to its specialization
/// (`ModuleAnalyses.templateDispatchRelations`): the plans whose resolution
/// is a direct call, and the plans that need a relation (evidence-dependent
/// or representation-sensitive), each with its scope and relation kind.
pub const TemplateDispatchRelations = struct {
    direct: []static_dispatch.StaticDispatchPlanId,
    relations: []static_dispatch.StaticDispatchPlanId,
    relation_scopes: []DispatchScope,
    relation_kinds: []DispatchRelationKind,

    pub fn destroy(self: *TemplateDispatchRelations, allocator: Allocator) void {
        allocator.free(self.direct);
        allocator.free(self.relations);
        allocator.free(self.relation_scopes);
        allocator.free(self.relation_kinds);
        allocator.destroy(self);
    }
};

/// The module's dispatch resolution of what no template resolves
/// (`ModuleAnalyses.moduleDispatch`): the defaulted-field expressions' plans
/// and sites, plans and sites no template's chain binds (resolved
/// chain-free), and the generated-codec
/// contracts with their calls linked.
pub const ModuleDispatch = struct {
    pool: static_dispatch.EvidencePool,
    /// Sorted by key.
    site_evidence: []static_dispatch.SiteEvidenceEntry,
    /// Sorted by plan.
    plans: []PlanResolutionEntry,
    /// Sorted by plan.
    iterator_plans: []IteratorPlanResolutionEntry,
    codec_derivations: []static_dispatch.GeneratedCodecDerivation,
    codec_calls: []static_dispatch.GeneratedCodecCall,

    pub fn destroy(self: *ModuleDispatch, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.site_evidence);
        allocator.free(self.plans);
        allocator.free(self.iterator_plans);
        allocator.free(self.codec_derivations);
        allocator.free(self.codec_calls);
        allocator.destroy(self);
    }

    pub fn plan(self: *const ModuleDispatch, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
        return lookupPlanResolution(self.plans, id);
    }

    pub fn iteratorPlan(self: *const ModuleDispatch, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
        return lookupIteratorPlanResolution(self.iterator_plans, id);
    }

    pub fn site(self: *const ModuleDispatch, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
        return lookupSiteEvidence(self.site_evidence, key);
    }

    pub fn codecTable(self: *const ModuleDispatch) static_dispatch.GeneratedCodecTable {
        return .{
            .generated_codec_derivations = self.codec_derivations,
            .generated_codec_calls = self.codec_calls,
            .evidence_nodes = self.pool.nodes,
            .evidence_refs = self.pool.refs,
            .site_substitutions = self.pool.substitutions,
        };
    }
};

/// An app's root evidence for each of its platform requirement solutions
/// (`ModuleAnalyses.platformRequirementRootEvidence`), parallel to the
/// module's solutions: the chain-free evidence of the app procedure each
/// function requirement invokes. The platform's pairing reads it.
pub const PlatformRequirementRootEvidence = struct {
    pool: static_dispatch.EvidencePool,
    spans: []static_dispatch.EvidenceSpan,

    pub fn destroy(self: *PlatformRequirementRootEvidence, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.spans);
        allocator.destroy(self);
    }
};

/// The module-wide indexes dispatch resolution reads
/// (`ModuleAnalyses.dispatchIndex`): checker records by source identity,
/// and which templates reach each plan, iterator plan and use site, in
/// template order.
pub const DispatchIndex = struct {
    allocator: Allocator,
    /// Each source-defined template's scheme root: its definition's type or
    /// its promoted binding pattern's.
    template_scheme_vars: collections.DenseMap(u32, Var),
    value_use_by_node: collections.DenseMap(u32, u32),
    target_by_fn_var: collections.DenseMap(u32, u32),
    generated_codec_by_source: collections.DenseMap(Var, EvidencePass.GeneratedCodecsByKind),
    where_method_use_by_fn_var: collections.DenseMap(u32, u32),
    where_method_use_by_fn_root: collections.DenseMap(Var, u32),
    local_value_scheme_by_var: collections.DenseMap(u32, u32),
    value_use_record_by_pattern: collections.DenseMap(u32, u32),
    codec_instance_by_template: collections.DenseMap(Var, Var),
    fresh_by_pair_root: std.AutoHashMapUnmanaged(EvidencePass.PairRootKey, Var) = .empty,
    /// Per plan, a range of `plan_sites`.
    plan_reach: []store_serialize.Span = &.{},
    /// Per iterator plan, a range of `iterator_sites`.
    iterator_reach: []store_serialize.Span = &.{},
    /// Every reference to a plan from a template's body or a defaulted-field
    /// expression, grouped by plan, in template order with the defaults
    /// last.
    plan_sites: []PlanReach = &.{},
    iterator_sites: []PlanReach = &.{},
    /// Use sites, sorted by key then template order.
    site_reach: []SiteReach = &.{},
    /// The use sites of the defaulted-field expressions, sorted.
    default_sites: []u32 = &.{},

    /// One reference to a plan: the template whose body reaches it (null for
    /// a defaulted-field expression) and the scope it occurs in.
    pub const PlanReach = struct {
        template: ?u32,
        scope: DispatchScope,
    };

    pub const SiteReach = struct {
        site: u32,
        template: u32,

        fn lessThan(_: void, a: SiteReach, b: SiteReach) bool {
            if (a.site != b.site) return a.site < b.site;
            return a.template < b.template;
        }
    };

    pub fn destroy(self: *DispatchIndex) void {
        const allocator = self.allocator;
        self.template_scheme_vars.deinit();
        self.value_use_by_node.deinit();
        self.target_by_fn_var.deinit();
        self.generated_codec_by_source.deinit();
        self.where_method_use_by_fn_var.deinit();
        self.where_method_use_by_fn_root.deinit();
        self.local_value_scheme_by_var.deinit();
        self.value_use_record_by_pattern.deinit();
        self.codec_instance_by_template.deinit();
        self.fresh_by_pair_root.deinit(allocator);
        allocator.free(self.plan_reach);
        allocator.free(self.iterator_reach);
        allocator.free(self.plan_sites);
        allocator.free(self.iterator_sites);
        allocator.free(self.site_reach);
        allocator.free(self.default_sites);
        allocator.destroy(self);
    }

    /// Whether `site` is a use site of a defaulted-field expression.
    pub fn isDefaultSite(self: *const DispatchIndex, site: u32) bool {
        return std.sort.binarySearch(u32, self.default_sites, site, struct {
            fn order(key: u32, item: u32) std.math.Order {
                return std.math.order(key, item);
            }
        }.order) != null;
    }

    pub fn planSites(self: *const DispatchIndex, plan: static_dispatch.StaticDispatchPlanId) []const PlanReach {
        const span = self.plan_reach[@backingInt(plan)];
        return self.plan_sites[span.start..][0..span.len];
    }

    pub fn iteratorSites(self: *const DispatchIndex, plan: static_dispatch.IteratorForPlanId) []const PlanReach {
        const span = self.iterator_reach[@backingInt(plan)];
        return self.iterator_sites[span.start..][0..span.len];
    }

    pub fn siteTemplates(self: *const DispatchIndex, site: u32) []const SiteReach {
        var low: usize = 0;
        var high: usize = self.site_reach.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            if (self.site_reach[mid].site < site) low = mid + 1 else high = mid;
        }
        var end = low;
        while (end < self.site_reach.len and self.site_reach[end].site == site) end += 1;
        return self.site_reach[low..end];
    }
};

/// The checked data of one module its dispatch analyses read.
pub const DispatchSource = struct {
    env: *const ModuleEnv,
    module_idx: u32,
    key: CheckedModuleKey,
    /// The module's names, which dispatch resolution interns the method
    /// names of the obligations it resolves into.
    names: *canonical.CanonicalNameStore,
    types: DispatchTypes,
    module_index: *const ModuleIndex,
    /// The module's body analyses, whose index `module_index` is.
    body_analyses: *BodyAnalyses,
    method_registry: *const static_dispatch.MethodRegistry,
    templates: *const CheckedProcedureTemplateTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    plans: *const static_dispatch.StaticDispatchPlanTable,
    refs: *const ResolvedValueRefTable,
    entry_wrappers: *const EntryWrapperTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    compile_time_roots: *const CompileTimeRootTable,
    analyses: *ModuleAnalyses,
    /// The modules the module imports directly.
    direct_imports: []const CheckedModuleKey,
};

/// The reader over a module's dispatch resolution and dispatch schemas,
/// each computed on first demand into the module's slots.
pub const CheckedDispatch = struct {
    source: DispatchSource,

    pub const Error = Allocator.Error;

    fn analyses(self: CheckedDispatch) *ModuleAnalyses {
        return self.source.analyses;
    }

    /// The schema of procedure template `template`.
    pub fn templateSchema(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!SchemaView {
        return (try self.analyses().templateSchema(self, template)).view;
    }

    /// The schema of generalized local scope `scope`.
    pub fn scopeSchema(self: CheckedDispatch, scope: DispatchScopeId) Error!SchemaView {
        return (try self.analyses().scopeSchema(self, scope)).view;
    }

    /// The template's quantified variables (`SchemaView.vars`).
    pub fn templateSchemeVars(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const CheckedTypeId {
        return (try self.templateSchema(template)).vars;
    }

    /// The template's evidence parameters (`SchemaView.params`).
    pub fn evidenceParams(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const static_dispatch.EvidenceParamRecord {
        return (try self.templateSchema(template)).params;
    }

    /// The evidence pool of `owner`.
    pub fn pool(self: CheckedDispatch, owner: static_dispatch.EvidenceOwner) Error!*const static_dispatch.EvidencePool {
        return switch (owner) {
            .module => &(try self.analyses().moduleDispatch(self)).pool,
            .platform_requirements => &(try self.analyses().platformRequirementRootEvidence(self)).pool,
            _ => &(try self.analyses().templateDispatch(self, owner.template().?)).pool,
        };
    }

    pub fn evidenceNode(self: CheckedDispatch, id: static_dispatch.EvidenceNodeId) Error!static_dispatch.EvidenceNode {
        return (try self.pool(id.owner)).node(id);
    }

    pub fn evidenceEntries(self: CheckedDispatch, span: static_dispatch.EvidenceSpan) Error![]const static_dispatch.CheckedEvidence {
        if (span.len == 0) return &.{};
        return (try self.pool(span.owner)).entries(span);
    }

    pub fn substitution(self: CheckedDispatch, span: static_dispatch.EvidenceSpan) Error![]const CheckedTypeId {
        if (span.len == 0) return &.{};
        return (try self.pool(span.owner)).types(span);
    }

    /// The evidence node's nested evidence, in the target scheme's
    /// canonical evidence-param order.
    pub fn nestedEvidence(self: CheckedDispatch, node: static_dispatch.EvidenceNode) Error![]const static_dispatch.CheckedEvidence {
        return switch (node.nested) {
            .resolved => |span| self.evidenceEntries(span),
            .from_callable => checkedModuleInvariant("callable-derived target evidence has no resolved checked-evidence span", .{}),
            .through_alias => checkedModuleInvariant("alias-scope evidence was read as its target's own evidence", .{}),
        };
    }

    /// The evidence an edge that instantiated a procedure alias's scheme
    /// resolved for that alias's own obligations.
    pub fn aliasScopeEvidence(self: CheckedDispatch, node: static_dispatch.EvidenceNode) Error![]const static_dispatch.CheckedEvidence {
        return switch (node.nested) {
            .through_alias => |span| self.evidenceEntries(span),
            .resolved, .from_callable => checkedModuleInvariant("target evidence was read as an alias scope's evidence", .{}),
        };
    }

    /// Plan `id` with its total resolution.
    pub fn plan(self: CheckedDispatch, id: static_dispatch.StaticDispatchPlanId) Error!static_dispatch.StaticDispatchCallPlan {
        const recorded = self.source.plans.plans[@backingInt(id)];
        return static_dispatch.StaticDispatchCallPlan.fromRecorded(recorded, try self.analyses().planResolution(self, id));
    }

    /// Iterator plan `id` with its calls' total resolutions.
    pub fn iteratorPlan(self: CheckedDispatch, id: static_dispatch.IteratorForPlanId) Error!static_dispatch.ResolvedIteratorForPlan {
        const recorded = self.source.plans.iterator_for_plans[@backingInt(id)];
        return static_dispatch.ResolvedIteratorForPlan.fromRecorded(recorded, try self.analyses().iteratorPlanResolution(self, id));
    }

    fn siteEntry(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?SiteEvidenceLookup {
        return self.analyses().siteEvidence(self, @backingInt(expr));
    }

    /// Evidence for the scheme instantiated at `expr` (a constrained
    /// definition reference or an expression-position function construction
    /// edge), in the scheme's canonical evidence-param order; null when no
    /// checked instantiation edge was recorded for the expression.
    pub fn siteEvidence(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?[]const static_dispatch.CheckedEvidence {
        const found = (try self.siteEntry(expr)) orelse return null;
        return try self.evidenceEntries(.{ .owner = found.owner, .start = found.entry.start, .len = found.entry.len });
    }

    /// The range `siteEvidence` reads.
    pub fn siteEvidenceSpan(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?static_dispatch.EvidenceSpan {
        const found = (try self.siteEntry(expr)) orelse return null;
        return .{ .owner = found.owner, .start = found.entry.start, .len = found.entry.len };
    }

    /// The substitution recorded for the scheme used at `expr`: one checked
    /// type per quantified variable of that scheme, in the scheme's
    /// `scheme_vars` order. Null when the expression has no site entry at
    /// all; empty when its entry recorded no instantiation.
    pub fn siteSubstitution(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?[]const CheckedTypeId {
        const found = (try self.siteEntry(expr)) orelse return null;
        return try self.substitution(.{ .owner = found.owner, .start = found.entry.subst_start, .len = found.entry.subst_len });
    }

    /// The checked type of the instance a stored nested-function use at
    /// `expr` places into its containing value.
    pub fn siteInstanceType(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?CheckedTypeId {
        const found = (try self.siteEntry(expr)) orelse return null;
        if (found.entry.instance_ty == static_dispatch.SiteEvidenceEntry.no_site_instance) return null;
        return @fromBackingInt(@intCast(found.entry.instance_ty));
    }

    /// The chain-free root evidence of a procedure template: its own
    /// requirements resolved without a caller. Null explicitly marks a
    /// scheme-only procedure that requires instantiation evidence and
    /// cannot be invoked as a bare root.
    pub fn templateRootEvidenceSpan(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!?static_dispatch.EvidenceSpan {
        return (try self.analyses().templateDispatch(self, template)).root_evidence;
    }

    /// The entries of `templateRootEvidenceSpan`.
    pub fn templateRootEvidence(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const static_dispatch.CheckedEvidence {
        const span = (try self.templateRootEvidenceSpan(template)) orelse
            checkedModuleInvariant("a scheme-only procedure's root evidence was read", .{});
        return self.evidenceEntries(span);
    }

    /// How the template's plans relate to its specialization.
    pub fn templateRelations(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!*const TemplateDispatchRelations {
        return self.analyses().templateDispatchRelations(self, template);
    }

    /// The module's generated-codec contracts with every call linked.
    pub fn generatedCodecs(self: CheckedDispatch) Error!static_dispatch.GeneratedCodecTable {
        return (try self.analyses().moduleDispatch(self)).codecTable();
    }

    /// The app's root evidence for its platform requirement solution
    /// `solution` (an index into the module's solutions).
    pub fn platformRequirementRootEvidence(self: CheckedDispatch, solution: usize) Error!static_dispatch.EvidenceSpan {
        return (try self.analyses().platformRequirementRootEvidence(self)).spans[solution];
    }

    /// The module `key` names among the modules dispatch resolution reads.
    pub fn importedView(self: CheckedDispatch, key: ModuleId) Error!?ImportedModuleView {
        const imports = CheckedImportViews{ .current_owner = self.source.key.digest(), .direct = &.{}, .available = try self.analyses().dispatchImports(self) };
        return imports.viewForKey(key);
    }

    /// The module's literal call graph.
    pub fn literalGraph(self: CheckedDispatch) Error!*LiteralGraph {
        return self.analyses().literalGraph(self);
    }

    /// The literal requirements of procedure template `template`'s scheme. A
    /// literal root's entry wrapper converts closed literals only and has
    /// none.
    pub fn templateLiteralRequirements(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const LiteralRequirement {
        const row = template.rowIndex() orelse return &.{};
        const graph = try self.literalGraph();
        const component = try self.analyses().literalComponent(self, graph, row);
        return component.requirementsOf(.{ .template = row, .scope = null });
    }

    /// The literal requirements of generalized local scope `scope`'s scheme.
    pub fn scopeLiteralRequirements(self: CheckedDispatch, scope: DispatchScopeId) Error![]const LiteralRequirement {
        const graph = try self.literalGraph();
        const key: LiteralScopeKey = .{ .template = graph.scope_owners[@backingInt(scope)], .scope = @backingInt(scope) };
        const component = try self.analyses().literalComponent(self, graph, graph.nodeOfScope(key));
        return component.requirementsOf(key);
    }

    /// The literal arguments of `edge`, one per literal requirement of the
    /// scheme it instantiates, in requirement order; empty when the scheme
    /// has none.
    pub fn literalEdgeArgs(self: CheckedDispatch, edge: LiteralEdge) Error![]const LiteralArgSource {
        const graph = try self.literalGraph();
        const holder = (try self.analyses().literalEdgeHolder(self, graph, edge)) orelse return &.{};
        // A dispatch edge whose alias chain leaves the module is no edge of
        // the graph, though its holder's walk reaches it.
        const index = (try self.analyses().literalNode(self, graph, holder)).edgeIndex(edge) orelse return &.{};
        const component = try self.analyses().literalComponent(self, graph, holder);
        return component.edgeArgs(literalEdgeRef(holder, index));
    }

    /// Append the literal argument roots template `template`'s edges read to
    /// `out`, ascending: a row's, or a literal conversion root's entry
    /// wrapper's, whose edges are its conversion's.
    pub fn appendLiteralArgumentDemand(self: CheckedDispatch, allocator: Allocator, template: canonical.CheckedProcedureTemplateId, out: *std.ArrayList(ComptimeRootKey)) Error!void {
        if (template.rowIndex()) |row| {
            try out.appendSlice(allocator, try self.analyses().templateLiteralArgumentDemand(self, row));
            return;
        }
        const record = try self.literalRoot(templateLiteralRoot(template).?);
        const plan_id = record.plan orelse return;
        var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = self };
        defer walker.deinit();
        var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
        defer found.deinit(allocator);
        try walker.plan(try self.plan(plan_id), &found);
        const first = out.items.len;
        for (found.items) |item| {
            for (try self.literalEdgeArgs(.{ .node = item.id })) |arg| switch (arg) {
                .root => |id| try out.append(allocator, id),
                .forwarded, .unbound => {},
            };
        }
        const added = out.items[first..];
        std.mem.sort(ComptimeRootKey, added, {}, comptimeRootIdLessThan);
        var kept: usize = 0;
        for (added, 0..) |id, index| {
            if (index != 0 and added[index - 1] == id) continue;
            added[kept] = id;
            kept += 1;
        }
        out.shrinkRetainingCapacity(first + kept);
    }

    /// Append every literal root of the module to `out`: each top-level
    /// unit's literal conversion roots in unit order, then each literal
    /// component's argument roots in component order.
    pub fn appendLiteralRoots(self: CheckedDispatch, allocator: Allocator, out: *std.ArrayList(ComptimeRootKey)) Error!void {
        for (0..self.source.module_index.units.len) |unit| {
            const conversions = try self.analyses().unitLiteralConversions(self, @fromBackingInt(@intCast(unit)));
            for (conversions.records) |record| try out.append(allocator, record.root.id);
        }
        const graph = try self.literalGraph();
        for ((try self.analyses().literalComponentOrder(self, graph)).leaders) |leader| {
            const done = try self.analyses().literalComponent(self, graph, leader);
            for (done.roots) |record| try out.append(allocator, record.root.id);
        }
    }

    /// The conversion root of the literal at `raw_node`, or null.
    pub fn literalConversionRoot(self: CheckedDispatch, raw_node: u32) Error!?ComptimeRootKey {
        const candidate = (try literalConversionCandidate(dispatchSourceBodies(self.source), self, raw_node)) orelse return null;
        return literalConversionRootId(candidate.literal);
    }

    /// Literal root `id` with its entry wrapper.
    pub fn literalRoot(self: CheckedDispatch, id: ComptimeRootKey) Error!*const LiteralRootRecord {
        const name = literalRootName(id) orelse checkedModuleInvariant("a root of the root table was read as a literal root", .{});
        switch (name) {
            .conversion => |literal| {
                const unit = self.source.module_index.unitOf(literal.node());
                const conversions = try self.analyses().unitLiteralConversions(self, unit);
                return conversions.record(literal.node()) orelse checkedModuleInvariant("a literal conversion root names a literal without one", .{});
            },
            .argument => |argument| {
                const graph = try self.literalGraph();
                const holder = (try self.analyses().literalEdgeHolder(self, graph, argument.edge)) orelse checkedModuleInvariant("a literal argument root names an edge no body holds", .{});
                const component = try self.analyses().literalComponent(self, graph, holder);
                return component.root(id) orelse checkedModuleInvariant("a literal argument root names an argument its edge does not root", .{});
            },
        }
    }

    /// Procedure template `template`: a row of the template table, or a
    /// literal root's entry wrapper, whose body converts its root's literal.
    pub fn procedureTemplate(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!CheckedProcedureTemplate {
        const root = templateLiteralRoot(template) orelse return self.source.templates.get(template);
        const record = try self.literalRoot(root);
        return .{
            .proc_base = canonical.ProcBase.entry_wrapper,
            .template_id = template,
            .body = .{ .literal_root = root },
            .checked_fn_scheme = record.checked_fn_scheme,
            .checked_fn_root = record.checked_fn_root,
            .static_dispatch_plans = .{},
            .resolved_value_refs = .{},
            .top_level_value_uses = .{},
            .target = .comptime_only,
        };
    }

    /// The relations of template `template`'s interface to its
    /// specialization.
    pub fn specializationRelations(self: CheckedDispatch, template: *const CheckedProcedureTemplate) Error![]const SpecializationInterfaceRelation {
        if (templateLiteralRoot(template.template_id)) |root| return &(try self.literalRoot(root)).relation;
        return self.source.templates.specializationRelations(template);
    }

    /// Compile-time root `id`: a row of the root table, or a literal root.
    /// A literal root's payload is the evaluation output's
    /// (`CheckedModule.compileTimeRoot`).
    pub fn compileTimeRoot(self: CheckedDispatch, id: ComptimeRootKey) Error!CompileTimeRoot {
        if (!id.isLiteral()) return self.source.compile_time_roots.root(id);
        return (try self.literalRoot(id)).root;
    }

    /// How much of each of template `template`'s quantified variables
    /// (`SchemaView.vars`) its body demands, in slot order. Monotype
    /// specializes the template over only this much of each variable's
    /// substitution (design.md "Specialization By Demand").
    pub fn templateDemands(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const SchemeVarDemand {
        return self.analyses().templateDemands(self, template);
    }
};

/// The traversal scratch of an evidence pass: the visited sets and work
/// lists its walks over the module's solver store keep between walks. A
/// visited set's storage spans the range of solver variables its walks
/// reach, which can be most of the store, and a module runs an evidence pass
/// per template schema and per template resolution, so the module's passes
/// share their traversals instead of each growing its own: a pass borrows
/// one from its module for its lifetime
/// (`ModuleAnalyses.borrowEvidenceTraversal`) and returns it, and a pass
/// that starts while another is running borrows another. Every walk clears
/// what it reads before it starts, so no result depends on which traversal
/// a pass borrowed.
pub const EvidenceTraversal = struct {
    enum_scratch: dispatch_evidence.Scratch = .{},
    /// Reuse traversal capacity while giving each schema fresh identity slots.
    identity_writer: canonical_type_keys.TypeWriter,
    /// Traversal scratch for `schemeExtendsLabeledTagRow`.
    labeled_row_visited: collections.DenseMapUnmanaged(Var, void) = .empty,
    labeled_row_pending: std.ArrayList(Var) = .empty,

    /// A traversal over the solver store of `env`.
    pub fn create(allocator: Allocator, env: *const ModuleEnv) Allocator.Error!*EvidenceTraversal {
        const traversal = try allocator.create(EvidenceTraversal);
        traversal.* = .{ .identity_writer = canonical_type_keys.TypeWriter.init(allocator, &env.types, env) };
        return traversal;
    }

    pub fn destroy(self: *EvidenceTraversal, allocator: Allocator) void {
        self.enum_scratch.deinit(allocator);
        self.identity_writer.deinit();
        self.labeled_row_visited.deinit(allocator);
        self.labeled_row_pending.deinit(allocator);
        allocator.destroy(self);
    }
};

/// Resolve every static-dispatch plan and instantiation-site obligation to an
/// explicit `direct` / `constraint(k)` / `structural` / `checked_error`
/// resolution, and publish each template's evidence params.
///
/// Runs after `sealCheckedProcedureTemplateRefs` so plans and value refs are
/// grouped per template: `constraint(k)` indexes the enclosing template's
/// canonical evidence-param list. Concrete dispatchers resolve through the
/// checked registry; where-var dispatchers resolve to their param index;
/// evidence for call edges comes from the checker's persisted
/// `SchemeUseRecord`s, whose fresh vars are resolved against the
/// settled type store.
const EvidencePass = struct {
    pub const PairRootKey = struct {
        pairs_start: u32,
        pairs_len: u32,
        old_root: Var,
    };
    const PublishedScheme = struct {
        vars: store_serialize.Span,
        params: store_serialize.Span,
    };
    /// Each dispatcher root's params within one schema, in param order.
    /// Composite scheme requirements are matched by their exact relation
    /// instead, so they are not indexed.
    pub const DispatcherParams = struct {
        /// Sorted by dispatcher root, then by param index.
        rows: []const Row = &.{},

        const Row = struct {
            root: Var,
            param: u32,

            fn lessThan(_: void, left: Row, right: Row) bool {
                if (left.root != right.root) return @backingInt(left.root) < @backingInt(right.root);
                return left.param < right.param;
            }

            fn orderRoot(root: Var, row: Row) std.math.Order {
                return std.math.order(@backingInt(root), @backingInt(row.root));
            }
        };

        /// The rows of `root`'s params, in param order.
        fn forRoot(self: DispatcherParams, root: Var) []const Row {
            const start, const end = std.sort.equalRange(Row, self.rows, root, Row.orderRoot);
            return self.rows[start..end];
        }
    };
    /// One level of an evidence chain: a schema's params, their index, and
    /// the published scheme whose parameters they are.
    const ChainLevel = struct {
        params: []const EvidenceParam,
        by_dispatcher: DispatcherParams,
        scheme: ?u32,
        published: []const static_dispatch.EvidenceParamRecord,

        const empty: ChainLevel = .{ .params = &.{}, .by_dispatcher = .{}, .scheme = null, .published = &.{} };

        fn fromScheme(chain: ?ChainScheme) ChainLevel {
            const scheme = chain orelse return .empty;
            return .{ .params = scheme.params, .by_dispatcher = scheme.by_dispatcher, .scheme = scheme.owner, .published = scheme.published };
        }
    };
    const SchemeSchema = struct {
        params: []EvidenceParam,
        by_dispatcher: DispatcherParams,
        /// The nodes `params` name their paths by.
        path_nodes: []const static_dispatch.EvidencePathNode,
        identity_vars: []const Var,
        published: ?PublishedScheme = null,
    };

    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_types: DispatchTypes,
    module_index: *const ModuleIndex,
    local_method_registry: *const static_dispatch.MethodRegistry,
    import_views: CheckedImportViews,
    /// The import views method-target lookup searches after the local
    /// registry, in search order.
    method_lookup_views: []const *const ImportedModuleView = &.{},
    plan_table: *const static_dispatch.StaticDispatchPlanTable,
    templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    sites: *const TemplateDispatchSites,
    entry_wrappers: *const EntryWrapperTable,
    compile_time_roots: *const CompileTimeRootTable,
    /// The module's dispatch reader, through which the pass reads the
    /// schemas of templates and scopes and other modules' dispatch.
    dispatch: CheckedDispatch,
    /// The analysis whose pool this pass fills.
    owner: static_dispatch.EvidenceOwner,
    /// The module's checker-record indexes; the index under construction
    /// while `buildIndexes` runs.
    index: *const DispatchIndex,

    types: *const types.Store,

    /// Schemas enumerated by this pass, by scheme owner.
    schemas_by_root: collections.DenseMap(Var, SchemeSchema),
    /// The traversal scratch this pass borrows from its module for its
    /// lifetime.
    traversal: *EvidenceTraversal,
    /// Memoized evidence node per dispatch_target record.
    node_by_record: collections.DenseMap(u32, static_dispatch.EvidenceNodeId),
    /// Hash buckets and collision chains for structurally interned evidence
    /// nodes. Every `EvidenceNodeId` of the pool is therefore an exact
    /// evidence identity, independent of which checker record requested it.
    evidence_node_buckets: std.AutoHashMap(u64, u32),
    evidence_node_next: std.ArrayList(?u32),
    record_in_progress: collections.DenseMap(u32, void),
    /// Site-evidence dedupe (a checked expr can be reachable from two scopes
    /// of the walk).
    site_seen: collections.DenseMap(u32, void),

    evidence_nodes: std.ArrayList(static_dispatch.EvidenceNode),
    evidence_refs: std.ArrayList(static_dispatch.CheckedEvidence),
    /// Hash buckets and collision chains for interned callable contract
    /// vectors: each bucket names its newest row in `callable_contracts`.
    callable_contract_buckets: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    callable_contracts: std.ArrayListUnmanaged(CallableContractRow) = .empty,
    site_evidence: std.ArrayList(static_dispatch.SiteEvidenceEntry),
    evidence_params_pool: std.ArrayList(static_dispatch.EvidenceParamRecord),
    evidence_path_nodes: std.ArrayList(static_dispatch.EvidencePathNode),
    /// Scheme path node -> published path node, for the scheme being published.
    published_path_nodes: std.ArrayList(u32),
    published_path_chain: std.ArrayList(u32),
    evidence_param_callables: std.ArrayList(CheckedTypeId),
    scheme_vars_pool: std.ArrayList(CheckedTypeId),
    site_substitutions: std.ArrayList(CheckedTypeId),
    /// Solver variables of the scheme whose params are being appended, in
    /// slot order, so each param resolves to its slot.
    scheme_var_scratch: std.ArrayListUnmanaged(Var) = .empty,
    /// Stable copies of enumerated semantic paths. Evidence resolution may
    /// recursively enumerate another scheme before finishing the current
    /// vector, so consumers cannot retain aliases into the traversal's
    /// `enum_scratch`.
    enumerated_path_arena: base.SingleThreadArena,
    /// Scratch backing for the chain currently being resolved against.
    chain_scratch: std.ArrayList(ChainLevel),
    /// The plans and iterator plans this pass resolved: a plan reachable from
    /// two scopes of one walk resolves once.
    plan_results: std.ArrayListUnmanaged(PlanResolutionEntry) = .empty,
    iterator_results: std.ArrayListUnmanaged(IteratorPlanResolutionEntry) = .empty,
    plan_resolved: collections.DenseMapUnmanaged(u32, void) = .empty,
    iterator_plan_resolved: collections.DenseMapUnmanaged(u32, void) = .empty,
    /// Explicit shared-var use records deferred during template walks because
    /// the current chain did not bind every obligation.
    deferred_use_sites: std.ArrayListUnmanaged(DeferredUseSite) = .empty,
    /// Evidence already resolved for a scheme-use substitution: records
    /// naming the same substitution range of the same scheme (uses replayed
    /// from one source) resolve it once.
    record_spans_by_substitution: std.AutoHashMapUnmanaged(RecordSubstitutionKey, RecordSiteSpans) = .empty,
    /// The param chain in scope while resolving a site's evidence entries, so
    /// a fresh var that settled onto an enclosing where-var forwards as
    /// `constraint(depth, k)`. Index 0 is the innermost generalized callable.
    current_chain: []const ChainLevel = &.{},

    const EvidenceParam = dispatch_evidence.EvidenceParam;
    /// The generated-codec derivation each kind selected for one
    /// checker-authored source constraint.
    pub const GeneratedCodecsByKind = std.EnumArray(static_dispatch.GeneratedCodecDerivationKind, ?static_dispatch.GeneratedCodecDerivationId);
    const CallableContractRow = struct {
        span: static_dispatch.EvidenceSpan,
        /// The next older row in the same bucket.
        next: u32,

        const none = std.math.maxInt(u32);
    };

    /// A pass over `dispatch`'s module that fills `owner`'s pool.
    fn init(
        allocator: Allocator,
        dispatch: CheckedDispatch,
        module_data: *TypedCIR.ModuleData,
        owner: static_dispatch.EvidenceOwner,
        index: *const DispatchIndex,
    ) Allocator.Error!EvidencePass {
        const source = dispatch.source;
        const module = TypedCIR.Module.readOnly(allocator, source.module_idx, module_data);
        const import_views = CheckedImportViews{
            .current_owner = source.key.digest(),
            .direct = &.{},
            .available = try source.analyses.dispatchImports(dispatch),
        };
        const method_lookup_views = try methodLookupViews(allocator, import_views.available);
        errdefer allocator.free(method_lookup_views);
        return .{
            .allocator = allocator,
            .module = module,
            .names = source.names,
            .checked_types = source.types,
            .module_index = source.module_index,
            .local_method_registry = source.method_registry,
            .import_views = import_views,
            .method_lookup_views = method_lookup_views,
            .plan_table = source.plans,
            .templates = source.templates,
            .resolved_value_refs = source.refs,
            .sites = &source.templates.dispatch_sites,
            .entry_wrappers = source.entry_wrappers,
            .compile_time_roots = source.compile_time_roots,
            .dispatch = dispatch,
            .owner = owner,
            .index = index,
            .types = module.typeStoreConst(),
            .schemas_by_root = collections.DenseMap(Var, SchemeSchema).init(allocator),
            .traversal = try source.analyses.borrowEvidenceTraversal(source.env),
            .node_by_record = collections.DenseMap(u32, static_dispatch.EvidenceNodeId).init(allocator),
            .evidence_node_buckets = std.AutoHashMap(u64, u32).init(allocator),
            .evidence_node_next = .empty,
            .record_in_progress = collections.DenseMap(u32, void).init(allocator),
            .site_seen = collections.DenseMap(u32, void).init(allocator),
            .evidence_nodes = .empty,
            .evidence_refs = .empty,
            .site_evidence = .empty,
            .evidence_params_pool = .empty,
            .evidence_path_nodes = .empty,
            .published_path_nodes = .empty,
            .published_path_chain = .empty,
            .evidence_param_callables = .empty,
            .scheme_vars_pool = .empty,
            .site_substitutions = .empty,
            .enumerated_path_arena = base.SingleThreadArena.init(allocator),
            .chain_scratch = .empty,
        };
    }

    fn deinit(self: *EvidencePass) void {
        self.allocator.free(self.method_lookup_views);
        self.plan_results.deinit(self.allocator);
        self.iterator_results.deinit(self.allocator);
        self.plan_resolved.deinit(self.allocator);
        self.iterator_plan_resolved.deinit(self.allocator);
        self.deferred_use_sites.deinit(self.allocator);
        var schemas = self.schemas_by_root.valueIterator();
        while (schemas.next()) |schema| self.allocator.free(schema.identity_vars);
        self.schemas_by_root.deinit();
        self.dispatch.source.analyses.returnEvidenceTraversal(self.traversal);
        self.node_by_record.deinit();
        self.evidence_node_buckets.deinit();
        self.evidence_node_next.deinit(self.allocator);
        self.record_in_progress.deinit();
        self.site_seen.deinit();
        self.evidence_nodes.deinit(self.allocator);
        self.evidence_refs.deinit(self.allocator);
        self.callable_contract_buckets.deinit(self.allocator);
        self.callable_contracts.deinit(self.allocator);
        self.site_evidence.deinit(self.allocator);
        self.record_spans_by_substitution.deinit(self.allocator);
        self.evidence_params_pool.deinit(self.allocator);
        self.evidence_path_nodes.deinit(self.allocator);
        self.published_path_nodes.deinit(self.allocator);
        self.published_path_chain.deinit(self.allocator);
        self.evidence_param_callables.deinit(self.allocator);
        self.scheme_vars_pool.deinit(self.allocator);
        self.site_substitutions.deinit(self.allocator);
        self.scheme_var_scratch.deinit(self.allocator);
        self.enumerated_path_arena.deinit();
        self.chain_scratch.deinit(self.allocator);
    }

    /// The pool this pass filled, handed to its owner's result.
    fn takePool(self: *EvidencePass) Allocator.Error!static_dispatch.EvidencePool {
        const nodes = try self.evidence_nodes.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(nodes);
        const refs = try self.evidence_refs.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(refs);
        return .{
            .owner = self.owner,
            .nodes = nodes,
            .refs = refs,
            .substitutions = try self.site_substitutions.toOwnedSlice(self.allocator),
        };
    }

    fn takeSiteEvidence(self: *EvidencePass) Allocator.Error![]static_dispatch.SiteEvidenceEntry {
        std.mem.sort(static_dispatch.SiteEvidenceEntry, self.site_evidence.items, {}, siteEvidenceLessThan);
        return self.site_evidence.toOwnedSlice(self.allocator);
    }

    fn takePlanResults(self: *EvidencePass) Allocator.Error![]PlanResolutionEntry {
        std.mem.sort(PlanResolutionEntry, self.plan_results.items, {}, PlanResolutionEntry.lessThan);
        return self.plan_results.toOwnedSlice(self.allocator);
    }

    fn takeIteratorResults(self: *EvidencePass) Allocator.Error![]IteratorPlanResolutionEntry {
        std.mem.sort(IteratorPlanResolutionEntry, self.iterator_results.items, {}, IteratorPlanResolutionEntry.lessThan);
        return self.iterator_results.toOwnedSlice(self.allocator);
    }

    /// The template-or-scope schema of `scheme_var`, published into this
    /// pass's pools: its quantified variables, and, unless it has none, its
    /// evidence parameters.
    fn publishTemplateSchema(self: *EvidencePass, template: CheckedProcedureTemplate) Allocator.Error!struct { vars: store_serialize.Span, params: store_serialize.Span, callable_determines_scheme: bool, chain_root: ?Var } {
        if (self.templateEvidenceSchemeVar(template)) |scheme_var| {
            const schema = try self.publishScheme(scheme_var);
            const params = if (self.isCallableBindingWrapper(template))
                try self.appendReturnedCallableEvidenceParams(schema.params)
            else
                schema.params;
            const template_params = self.evidence_params_pool.items[params.start..][0..params.len];
            var callable_determines_scheme = true;
            if (try self.schemeExtendsLabeledTagRow(scheme_var)) {
                callable_determines_scheme = false;
            } else if (static_dispatch.procedureEvidenceSchema(template_params) == .from_callable) {
                // Only a callable-derived schema consults whether its
                // signature reaches every variable; every other schema
                // already requires checked per-use evidence.
                const signature_vars = try self.traversal.identity_writer.identityVarsFromVarIgnoringConstraints(scheme_var);
                defer self.allocator.free(signature_vars);
                callable_determines_scheme = signature_vars.len == schema.vars.len;
            }
            return .{ .vars = schema.vars, .params = params, .callable_determines_scheme = callable_determines_scheme, .chain_root = scheme_var };
        }
        // Constant-evaluation wrappers retain the value's type variables,
        // but have no caller-supplied dispatch parameters of their own.
        return .{ .vars = try self.appendSchemeVars(self.templateSchemeVar(template)), .params = .{}, .callable_determines_scheme = true, .chain_root = null };
    }

    /// Resolve one template's plans, iterator plans, value-reference sites,
    /// scheme-use sites and scope construction sites against its scheme
    /// chain, then its chain-free root evidence.
    fn resolveTemplate(self: *EvidencePass, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!?static_dispatch.EvidenceSpan {
        const template_index: usize = template_id.index();
        const template = self.templates.templates.items[template_index];
        const template_level = ChainLevel.fromScheme((try self.dispatch.analyses().templateSchema(self.dispatch, template_id)).chain);

        const plan_start = template.static_dispatch_plans.start;
        const plan_refs = self.templates.dispatch_plan_refs[plan_start .. plan_start + template.static_dispatch_plans.len];
        for (plan_refs, 0..) |plan_id, i| {
            const chain = try self.chainFor(self.templates.dispatch_ref_scopes[plan_start + i], template_level);
            try self.resolvePlan(plan_id, chain, .defer_resolution);
        }

        const iter_span = self.sites.iteratorSpan(template_index);
        for (self.sites.iterator_refs[iter_span.start .. iter_span.start + iter_span.len], 0..) |iter_plan_id, i| {
            const chain = try self.chainFor(self.sites.iterator_scopes[iter_span.start + i], template_level);
            try self.resolveIteratorPlan(iter_plan_id, chain, .defer_resolution);
        }

        if (template_index < self.sites.walkedTemplateCount()) {
            const value_ref_start = template.resolved_value_refs.start;
            const value_refs = self.resolved_value_refs.template_refs[value_ref_start .. value_ref_start + template.resolved_value_refs.len];
            for (value_refs, 0..) |ref_id, i| {
                const chain = try self.chainFor(self.sites.value_ref_scopes[value_ref_start + i], template_level);
                try self.emitSiteEvidence(ref_id, chain);
            }
        }

        const scheme_use_span = self.sites.schemeUseSpan(template_index);
        const scheme_use_sites = self.sites.scheme_use_sites[scheme_use_span.start .. scheme_use_span.start + scheme_use_span.len];
        for (scheme_use_sites, 0..) |site, i| {
            const chain = try self.chainFor(self.sites.scheme_use_scopes[scheme_use_span.start + i], template_level);
            try self.emitSchemeUseSiteEvidence(site.record_idx, @backingInt(site.checked_expr), chain);
        }

        const scope_site_span = self.sites.scopeSiteSpan(template_index);
        for (self.sites.scope_sites[scope_site_span.start .. scope_site_span.start + scope_site_span.len]) |site| {
            try self.emitScopeConstructionEvidence(site, template_level);
        }

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try self.enumerateTemplateParams(template, &params);
        for (params.items) |param| {
            if (param.requires_instantiation) return null;
        }
        return try self.rootEvidence(params.items);
    }

    /// The chain-free evidence of a root edge whose scheme requires `params`:
    /// a procedure template running as a root, or the app procedure a
    /// platform requirement invokes. A root has no caller to pin its scheme's
    /// variables, so every obligation resolves under `root_default`.
    fn rootEvidence(self: *EvidencePass, params: []const EvidenceParam) Allocator.Error!static_dispatch.EvidenceSpan {
        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, params.len);
        self.current_chain = &.{};
        for (params) |param| {
            const evidence = (try self.evidenceForVar(
                param,
                param.dispatcher_var,
                param.constraint.fn_var,
                .root_default,
            )) orelse checkedModuleInvariant(
                "root evidence remained unresolved after checking",
                .{},
            );
            entries.appendAssumeCapacity(evidence);
        }
        return try self.appendEvidenceRefs(entries.items);
    }

    /// The evidence of each platform requirement the app's checking solved:
    /// a platform requirement invokes an app procedure without a source
    /// expression use site in the platform module, so its root edge
    /// resolves against the app's solved requirement variable and exact
    /// target records.
    fn resolvePlatformRequirementRoots(self: *EvidencePass) Allocator.Error![]static_dispatch.EvidenceSpan {
        const module_env = self.module.moduleEnvConst();
        const solutions = module_env.platform_requirement_solutions.items.items;
        const spans = try self.allocator.alloc(static_dispatch.EvidenceSpan, solutions.len);
        errdefer self.allocator.free(spans);
        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        for (solutions, spans) |solution, *out| {
            out.* = .{ .owner = self.owner };
            switch (solution.outcome) {
                .checked_error => continue,
                .success => {},
            }
            if (!solution.is_function) continue;
            params.clearRetainingCapacity();
            // The app definition owns the complete scheme, including captured
            // codec requirements absent from the platform's copied type root.
            try self.enumerateParams(ModuleEnv.varFrom(solution.def), &params);
            out.* = try self.rootEvidence(params.items);
        }
        return spans;
    }

    /// Resolve what no template resolves: the defaulted-field expressions'
    /// plans and sites (`defaults`), use
    /// sites no template's chain bound (`deferred`), plans and iterator
    /// plans no template's chain bound, and the generated-codec calls.
    fn resolveModule(
        self: *EvidencePass,
        bound_by_template: *const ModuleBoundSet,
        deferred: []const DeferredUseSite,
        codec_calls: []static_dispatch.GeneratedCodecCall,
    ) Allocator.Error!void {
        try self.linkGeneratedCodecCalls(codec_calls);

        // Defaulted-field expression roots (design.md "Defaulted Fields"),
        // collected outside every template: resolve their plans and publish
        // their use-site evidence with no enclosing template params. A
        // default may constrain no declaration type parameter, so every
        // obligation resolves concretely; a generalized local function
        // inside the default still contributes its own scope chain segments.
        const defaults = self.sites.defaultsIndex();
        {
            const plan_span = self.sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
            for (self.templates.dispatch_plan_refs[plan_span.start .. plan_span.start + plan_span.len], 0..) |plan_id, i| {
                if (bound_by_template.plans.contains(@backingInt(plan_id))) continue;
                const chain = try self.chainFor(self.templates.dispatch_ref_scopes[plan_span.start + i], .empty);
                try self.resolvePlan(plan_id, chain, .defer_resolution);
            }

            const iter_span = self.sites.iteratorSpan(defaults);
            for (self.sites.iterator_refs[iter_span.start .. iter_span.start + iter_span.len], 0..) |iter_plan_id, i| {
                if (bound_by_template.iterator_plans.contains(@backingInt(iter_plan_id))) continue;
                const chain = try self.chainFor(self.sites.iterator_scopes[iter_span.start + i], .empty);
                try self.resolveIteratorPlan(iter_plan_id, chain, .defer_resolution);
            }

            const value_span = self.sites.defaultRefs(TemplateDispatchSites.default_value_refs);
            for (self.resolved_value_refs.template_refs[value_span.start .. value_span.start + value_span.len], 0..) |ref_id, i| {
                const site_key = @backingInt(self.resolved_value_refs.records[@backingInt(ref_id)].expr);
                if (bound_by_template.sites.contains(site_key)) continue;
                const chain = try self.chainFor(self.sites.value_ref_scopes[value_span.start + i], .empty);
                try self.emitSiteEvidence(ref_id, chain);
            }

            const scheme_span = self.sites.schemeUseSpan(defaults);
            for (self.sites.scheme_use_sites[scheme_span.start .. scheme_span.start + scheme_span.len], 0..) |site, i| {
                if (bound_by_template.sites.contains(@backingInt(site.checked_expr))) continue;
                const chain = try self.chainFor(self.sites.scheme_use_scopes[scheme_span.start + i], .empty);
                try self.emitSchemeUseSiteEvidence(site.record_idx, @backingInt(site.checked_expr), chain);
            }

            const scope_span = self.sites.scopeSiteSpan(defaults);
            for (self.sites.scope_sites[scope_span.start .. scope_span.start + scope_span.len]) |site| {
                if (bound_by_template.sites.contains(@backingInt(site.checked_expr))) continue;
                try self.emitScopeConstructionEvidence(site, .empty);
            }
        }

        // Explicit shared-var use sites no chain fully bound resolve
        // chain-free here. A site a template or a default already emitted is
        // skipped.
        for (deferred) |site| {
            if (bound_by_template.sites.contains(site.site_key)) continue;
            try self.deferUseSite(site);
        }
        {
            var i: usize = 0;
            while (i < self.deferred_use_sites.items.len) : (i += 1) {
                const site = self.deferred_use_sites.items[i];
                if (self.site_seen.contains(site.site_key)) continue;
                self.current_chain = &.{};
                const spans = (try self.evidenceRefsForRecord(site.record_idx, .commit)).?;
                if (spans.refs.len == 0 and spans.subst.len == 0) continue;
                try self.site_seen.put(site.site_key, {});
                try self.site_evidence.append(self.allocator, .{
                    .key = site.site_key,
                    .start = spans.refs.start,
                    .len = spans.refs.len,
                    .subst_start = spans.subst.start,
                    .subst_len = spans.subst.len,
                    .instance_ty = self.siteInstanceType(site.record_idx),
                });
            }
        }

        // Plans no template's chain bound (dead code, expressions outside
        // any template, obligations no enclosing scheme binds) still have a
        // definitive resolution: resolve them chain-free, exactly like root
        // edges.
        for (0..self.plan_table.plans.len) |raw| {
            if (bound_by_template.plans.contains(@intCast(raw))) continue;
            try self.resolvePlan(@fromBackingInt(@intCast(raw)), &.{}, .commit);
        }
        for (0..self.plan_table.iterator_for_plans.len) |raw| {
            if (bound_by_template.iterator_plans.contains(@intCast(raw))) continue;
            try self.resolveIteratorPlan(@fromBackingInt(@intCast(raw)), &.{}, .commit);
        }
    }

    fn deferUseSite(self: *EvidencePass, site: DeferredUseSite) Allocator.Error!void {
        try self.deferred_use_sites.append(self.allocator, site);
    }
    /// A generated body records one checked edge per source occurrence.
    /// Repeated fields whose subjects denote one type share a role, and so one
    /// prepared target, which is sound only when every edge in the role agrees
    /// on its complete callable relation and proof. Runs once the evidence
    /// graph is complete, since that proof spans the module's pool.
    fn debugVerifyGeneratedCodecRoleAgreement(self: *EvidencePass, table: *const static_dispatch.GeneratedCodecTable) Allocator.Error!void {
        if (builtin.mode != .debug) return;
        const type_view = self.checked_types.store.view();
        for (table.generated_codec_derivations) |derivation| {
            const calls = derivation.callsSlice(table);
            for (calls, 0..) |call, index| {
                for (calls[0..index]) |previous| {
                    if (previous.method != call.method or previous.method_role != call.method_role) continue;
                    if (!try @import("codec_identity.zig").callsEquivalent(self.allocator, type_view, table, previous, call)) {
                        checkedModuleInvariant(
                            "checked generated codec method role contained ambiguous calls",
                            .{},
                        );
                    }
                    // Every call in a role agrees with its first, so the rest
                    // of the role needs no further comparison.
                    break;
                }
            }
        }
    }

    /// The solver root of the scheme a compile-time root evaluates: the
    /// hoisted root's source pattern or the constant's definition. Expression
    /// roots, expect bodies and platform-required bindings have no scheme.
    fn rootSchemeVar(root: CompileTimeRoot) ?Var {
        if (root.source_pattern) |source_pattern| return ModuleEnv.varFrom(source_pattern);
        return switch (root.source) {
            .def => |def_idx| ModuleEnv.varFrom(def_idx),
            .expr, .statement, .required_binding, .hoisted, .literal => null,
        };
    }

    /// The solver root of a template's scheme: its definition's type, or the
    /// scheme of the compile-time root an entry wrapper evaluates. Intrinsic
    /// and hosted wrappers and expression roots have no scheme.
    fn templateSchemeVar(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
    ) ?Var {
        if (self.index.template_scheme_vars.get(template.template_id.index())) |scheme_var| return scheme_var;
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| rootSchemeVar(self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root)),
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => null,
        };
    }

    /// Append a scheme's quantified variables in identity order and retain
    /// their solver roots in `scheme_var_scratch` for slot lookup by the
    /// params appended next.
    fn appendSchemeVars(self: *EvidencePass, scheme_var: ?Var) Allocator.Error!store_serialize.Span {
        self.scheme_var_scratch.clearRetainingCapacity();
        const start: u32 = @intCast(self.scheme_vars_pool.items.len);
        const root = scheme_var orelse return .{ .start = start, .len = 0 };
        const identity_vars = try self.identityVarsForSchemeRoot(root);
        try self.scheme_var_scratch.ensureTotalCapacity(self.allocator, identity_vars.len);
        try self.scheme_vars_pool.ensureUnusedCapacity(self.allocator, identity_vars.len);
        for (identity_vars) |identity_var| {
            const resolved = self.types.resolveVar(identity_var).var_;
            self.scheme_var_scratch.appendAssumeCapacity(resolved);
            self.scheme_vars_pool.appendAssumeCapacity(self.checked_types.rootForSourceVar(self.module, resolved) orelse
                checkedModuleInvariant("scheme quantified variable type was not published", .{}));
        }
        return .{ .start = start, .len = @intCast(identity_vars.len) };
    }

    /// The identity variables of `scheme_root`, enumerated once per resolved
    /// root and shared by every scheme-var and substitution append.
    fn identityVarsForSchemeRoot(self: *EvidencePass, scheme_root: Var) Allocator.Error![]const Var {
        return (try self.schemeSchema(scheme_root)).identity_vars;
    }

    fn publishScheme(self: *EvidencePass, root: ?Var) Allocator.Error!PublishedScheme {
        const scheme_root = root orelse return .{ .vars = .{}, .params = .{} };
        const schema = try self.schemeSchema(scheme_root);
        if (schema.published) |published| return published;
        const published = PublishedScheme{
            .vars = try self.appendSchemeVars(scheme_root),
            .params = try self.appendEvidenceParams(schema.params, schema.path_nodes),
        };
        for (schema.params, 0..) |*param, index| param.published_index = @intCast(index);
        self.schemas_by_root.getPtr(self.schemeOwner(scheme_root)).?.published = published;
        return published;
    }

    fn schemeOwner(self: *EvidencePass, root: Var) Var {
        const requirements = self.module.moduleEnvConst().bindingSchemeCodecRequirementsForNode(@fromBackingInt(@intCast(@backingInt(root))));
        return if (requirements.len > 0) @fromBackingInt(@intCast(requirements[0].scheme_root)) else self.types.resolveVar(root).var_;
    }

    /// The slot of `dispatcher_var` in the scheme whose variables
    /// `appendSchemeVars` retained last.
    fn schemeVarSlot(self: *EvidencePass, dispatcher_var: Var) u32 {
        const root = self.types.resolveVar(dispatcher_var).var_;
        for (self.scheme_var_scratch.items, 0..) |scheme_var, slot| {
            if (scheme_var == root) return @intCast(slot);
        }
        checkedModuleInvariant("evidence parameter dispatcher was not a quantified variable of its scheme", .{});
    }

    /// The substitution one instantiation record applied to a scheme: for
    /// each quantified variable of `scheme_root` (in slot order) the checked
    /// type of its copy at that edge, or of the variable itself when the edge
    /// shared it. A type `renamings` renames is replaced by its copy.
    fn appendSiteSubstitution(
        self: *EvidencePass,
        scheme_root: Var,
        pairs: []const ModuleEnv.SchemeUsePair,
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
    ) Allocator.Error!static_dispatch.EvidenceSpan {
        const identity_vars = try self.identityVarsForSchemeRoot(scheme_root);
        const start: u32 = @intCast(self.site_substitutions.items.len);
        try self.site_substitutions.ensureUnusedCapacity(self.allocator, identity_vars.len);
        for (identity_vars) |identity_var| {
            const root = self.types.resolveVar(identity_var).var_;
            const edge_var = self.renamedVar(renamings, self.pairForResolved(pairs, root) orelse root);
            self.site_substitutions.appendAssumeCapacity(self.checked_types.rootForSourceVar(self.module, edge_var) orelse
                checkedModuleInvariant("instantiated scheme variable type was not published", .{}));
        }
        return .{ .owner = self.owner, .start = start, .len = @intCast(identity_vars.len) };
    }

    /// The copy `renamings` makes of `var_`'s type, or `var_` itself when it
    /// renames none.
    fn renamedVar(self: *EvidencePass, renamings: []const ModuleEnv.GeneratedCodecRenaming, var_: Var) Var {
        if (renamings.len == 0) return var_;
        const root = self.types.resolveVar(var_).var_;
        for (renamings) |renaming| {
            if (self.types.resolveVar(@fromBackingInt(@intCast(renaming.source_var))).var_ == root) {
                return @fromBackingInt(@intCast(renaming.copy_var));
            }
        }
        return var_;
    }

    /// Whether a variable of the scheme at `scheme_var` extends a tag row that
    /// has labels of its own (`[Closed, ..errs]`). Such a row normalizes to
    /// the same row whether the variable holds those labels or not, so a
    /// dispatch's normalized callable does not determine the variable's
    /// instantiation.
    fn schemeExtendsLabeledTagRow(self: *EvidencePass, scheme_var: Var) Allocator.Error!bool {
        const visited = &self.traversal.labeled_row_visited;
        visited.clearRetainingCapacity();
        const pending = &self.traversal.labeled_row_pending;
        pending.clearRetainingCapacity();
        try pending.append(self.allocator, scheme_var);
        while (pending.pop()) |raw| {
            const resolved = self.types.resolveVar(raw);
            if ((try visited.getOrPut(self.allocator, resolved.var_)).found_existing) continue;
            switch (resolved.desc.content) {
                .flex, .rigid, .field_presence, .err => {},
                .alias => |alias| {
                    try pending.append(self.allocator, self.types.getAliasBackingVar(alias));
                    var args = self.types.iterAliasArgs(alias);
                    while (args.next()) |arg| try pending.append(self.allocator, arg);
                },
                .structure => |flat| switch (flat) {
                    .tag_union => |row| {
                        const tags = self.types.getTagsSlice(row.tags);
                        if (tags.len != 0 and self.tagRowTailIsVariable(row.ext)) return true;
                        for (tags.items(.args)) |args| try pending.appendSlice(self.allocator, self.types.sliceVars(args));
                        try pending.append(self.allocator, row.ext);
                    },
                    .record => |record| {
                        try pending.append(self.allocator, record.ext);
                        const fields = self.types.getRecordFieldsSlice(record.fields);
                        for (fields.items(.presence)) |presence| try pending.append(self.allocator, presence.typeVar());
                    },
                    .tuple => |tuple| try pending.appendSlice(self.allocator, self.types.sliceVars(tuple.elems)),
                    .nominal_type => |nominal| {
                        var args = self.types.iterNominalArgs(nominal);
                        while (args.next()) |arg| try pending.append(self.allocator, arg);
                    },
                    .fn_pure, .fn_effectful, .fn_unbound => |func| {
                        try pending.appendSlice(self.allocator, self.types.sliceVars(func.args));
                        try pending.append(self.allocator, func.ret);
                    },
                    .empty_record, .empty_tag_union => {},
                },
            }
        }
        return false;
    }

    /// Whether a tag row's extension chain ends in a variable.
    fn tagRowTailIsVariable(self: *EvidencePass, ext: Var) bool {
        var tail = ext;
        while (true) {
            const content = self.types.resolveVar(tail).desc.content;
            switch (content) {
                .flex, .rigid => return true,
                .alias => |alias| tail = self.types.getAliasBackingVar(alias),
                .structure => |flat| switch (flat) {
                    .tag_union => |row| tail = row.ext,
                    .empty_tag_union => return false,
                    .record, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record => checkedModuleInvariant("tag row extension was not a row", .{}),
                },
                .field_presence, .err => return false,
            }
        }
    }

    fn isCallableBindingWrapper(self: *EvidencePass, template: CheckedProcedureTemplate) bool {
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| blk: {
                const root = self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root);
                break :blk root.kind == .callable_binding and root.source_pattern == null;
            },
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => false,
        };
    }

    /// A callable binding's wrapper takes no arguments and returns the
    /// binding's callable, so a dispatcher at a path over that callable is at
    /// the same path below the wrapper's return. The parameters keep the
    /// binding's scheme order, which a use's evidence follows.
    fn appendReturnedCallableEvidenceParams(self: *EvidencePass, params: store_serialize.Span) Allocator.Error!store_serialize.Span {
        const start: u32 = @intCast(self.evidence_params_pool.items.len);
        for (params.start..params.start + params.len) |index| {
            var param = self.evidence_params_pool.items[index];
            switch (param.source) {
                .scheme_callable => if (param.path.len != 0) {
                    var chain: std.ArrayList(static_dispatch.EvidencePathStep) = .empty;
                    defer chain.deinit(self.allocator);
                    var node = param.path.last;
                    while (node != static_dispatch.no_evidence_path_node) {
                        const path_node = self.evidence_path_nodes.items[node];
                        try chain.append(self.allocator, path_node.step);
                        node = path_node.parent;
                    }
                    var parent: u32 = @intCast(self.evidence_path_nodes.items.len);
                    try self.evidence_path_nodes.append(self.allocator, .{ .parent = static_dispatch.no_evidence_path_node, .step = .{ .kind = @backingInt(static_dispatch.EvidencePathStep.Kind.fn_ret), .data = 0 } });
                    var step_index = chain.items.len;
                    while (step_index > 0) {
                        step_index -= 1;
                        const next_node: u32 = @intCast(self.evidence_path_nodes.items.len);
                        try self.evidence_path_nodes.append(self.allocator, .{ .parent = parent, .step = chain.items[step_index] });
                        parent = next_node;
                    }
                    param.path = .{ .last = parent, .len = param.path.len + 1 };
                },
                .scheme_requirement, .constraint_callable, .use_site_only, .explicit_default, .erased_row_remainder => {},
            }
            try self.evidence_params_pool.append(self.allocator, param);
        }
        return .{ .start = start, .len = params.len };
    }

    /// Only procedure definitions, hoisted source-pattern roots, and callable
    /// bindings bind an evidence chain. A callable binding's wrapper produces
    /// the binding's callable for a use, which supplies the binding's
    /// dispatch parameters exactly as a use of a procedure does. Constant and
    /// expression entry wrappers evaluate their values without receiving the
    /// value's dispatch parameters as arguments.
    fn templateEvidenceSchemeVar(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
    ) ?Var {
        if (self.index.template_scheme_vars.get(template.template_id.index())) |scheme_var| return scheme_var;
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| blk: {
                const root = self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root);
                if (root.source_pattern) |pattern| break :blk ModuleEnv.varFrom(pattern);
                break :blk if (root.kind == .callable_binding) rootSchemeVar(root) else null;
            },
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => null,
        };
    }

    fn enumerateTemplateParams(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
        params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        params.clearRetainingCapacity();
        if (self.templateEvidenceSchemeVar(template)) |scheme_var| {
            try self.enumerateParams(scheme_var, params);
        }
    }

    /// Fill `out`, the index this pass reads as `index`, from the module's
    /// checker records.
    fn buildIndexes(self: *EvidencePass, out: *DispatchIndex) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        // Each source-defined procedure template publishes its source
        // binding's scheme: a top-level def's, or a promoted local function
        // binding pattern's.
        for (self.templates.by_def) |entry| {
            try out.template_scheme_vars.put(entry.template.template.index(), ModuleEnv.varFrom(entry.def));
        }
        for (self.templates.promoted) |entry| {
            try out.template_scheme_vars.put(entry.template.template.index(), ModuleEnv.varFrom(entry.pattern));
        }
        for (module_env.generated_codec_derivations.items.items, 0..) |derivation, index| {
            const kind: static_dispatch.GeneratedCodecDerivationKind = switch (@as(ModuleEnv.GeneratedCodecDerivation.Kind, @fromBackingInt(@intCast(derivation.kind)))) {
                .parser => .parser,
                .encoder => .encoder,
            };
            const source: Var = @fromBackingInt(@intCast(derivation.source_constraint_fn_var));
            const entry = try out.generated_codec_by_source.getOrPutValue(source, .initFill(null));
            const slot = entry.value_ptr.getPtr(kind);
            if (slot.* != null) {
                checkedModuleInvariant("duplicate generated codec source constraint identity", .{});
            }
            slot.* = @fromBackingInt(@intCast(@as(u32, @intCast(index))));
            if (derivation.template_constraint_fn_var != derivation.source_constraint_fn_var) {
                const template: Var = @fromBackingInt(@intCast(derivation.template_constraint_fn_var));
                try out.codec_instance_by_template.put(self.types.resolveVar(template).var_, source);
            }
        }
        // Records replayed from one source name the same substitution range,
        // whose pairs are indexed once.
        var indexed_ranges = std.AutoHashMap(struct { start: u32, len: u32 }, void).init(self.allocator);
        defer indexed_ranges.deinit();
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
            const range_seen = (try indexed_ranges.getOrPut(.{ .start = record.pairs_start, .len = record.pairs_len })).found_existing;
            if (!range_seen) for (pairs) |pair| {
                const entry = try out.fresh_by_pair_root.getOrPut(self.allocator, .{
                    .pairs_start = record.pairs_start,
                    .pairs_len = record.pairs_len,
                    .old_root = self.types.resolveVar(@fromBackingInt(@intCast(pair.old_var))).var_,
                });
                if (!entry.found_existing) entry.value_ptr.* = @fromBackingInt(@intCast(pair.fresh_var));
            };
            switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
                .value_use, .shared_value_use => {
                    // Re-checks can record the same binding use twice. A
                    // different scheme at this site is a producer bug, not
                    // another candidate from which the checked tables may choose.
                    const entry = try out.value_use_by_node.getOrPut(record.node_idx);
                    if (entry.found_existing) {
                        const previous = module_env.scheme_uses.items.items[entry.value_ptr.*];
                        std.debug.assert(self.types.resolveVar(@fromBackingInt(@intCast(previous.scheme_root))).var_ ==
                            self.types.resolveVar(@fromBackingInt(@intCast(record.scheme_root))).var_);
                    } else {
                        entry.value_ptr.* = @intCast(i);
                    }
                },
                .dispatch_target, .recursive_dispatch_target => {
                    // `slot_data` is the raw constraint-function var: checking
                    // guarantees exactly one selected-target instantiation per
                    // logical edge. Resolving it through union-find would
                    // collapse distinct evidence records whose callable
                    // signatures later unify.
                    const entry = try out.target_by_fn_var.getOrPut(record.slot_data);
                    if (entry.found_existing) {
                        checkedModuleInvariant("duplicate raw dispatch-target evidence identity", .{});
                    }
                    entry.value_ptr.* = @intCast(i);
                },
                .where_method_use => {
                    // `slot_data` is the raw body constraint callable. It is
                    // deliberately not resolved through union-find: two body
                    // uses may settle to the same callable shape while still
                    // owning distinct per-use signature copies.
                    const entry = try out.where_method_use_by_fn_var.getOrPut(record.slot_data);
                    if (entry.found_existing) {
                        checkedModuleInvariant("duplicate raw where-method-use callable identity", .{});
                    }
                    entry.value_ptr.* = @intCast(i);
                    const root = self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.slot_data)))).var_;
                    const root_entry = try out.where_method_use_by_fn_root.getOrPut(root);
                    if (!root_entry.found_existing) root_entry.value_ptr.* = @intCast(i);
                },
                .nested_function_use, .recursive_reference, .recursive_value_reference => {},
            }
        }
        // A relation checking folded into a retained same-name relation
        // dispatches through that relation's target instantiation.
        for (module_env.dispatch_relation_merges.items.items) |merge| {
            const record_idx = out.target_by_fn_var.get(merge.retained_fn_var) orelse continue;
            const entry = try out.target_by_fn_var.getOrPut(merge.dropped_fn_var);
            if (entry.found_existing) {
                checkedModuleInvariant("folded static-dispatch relation had its own dispatch-target evidence", .{});
            }
            entry.value_ptr.* = record_idx;
        }

        const global_value_defs = module_env.store.sliceDefs(module_env.global_value_defs);

        // Generalized local VALUE decls and one representative use record per
        // looked-up pattern (see `local_value_scheme_by_var`).
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.value_use)) continue;
            if (self.module.nodeTag(@fromBackingInt(@intCast(record.node_idx))) != .expr_var) continue;
            const lookup = self.module.expr(@fromBackingInt(@intCast(record.node_idx))).data.e_lookup_local;
            const entry = try out.value_use_record_by_pattern.getOrPut(@backingInt(lookup.pattern_idx));
            if (!entry.found_existing) entry.value_ptr.* = @intCast(i);
        }
        {
            var scheme_params = std.ArrayListUnmanaged(EvidenceParam).empty;
            defer scheme_params.deinit(self.allocator);
            var raw_node: u32 = 0;
            while (raw_node < self.module.nodeCount()) : (raw_node += 1) {
                if (self.module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .statement_decl) continue;
                const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node));
                const statement_data = self.module.getStatement(statement);
                if (statement_data != .s_decl) continue;
                try self.mapValueSchemeParams(out, statement_data.s_decl.pattern, statement_data.s_decl.expr, &scheme_params);
            }
            // Top-level generalized VALUE defs (e.g. an `if` choosing between
            // closures) lower inline at their single use type exactly like
            // local value decls; their body plans resolve through use records
            // the same way.
            for (global_value_defs) |def_idx| {
                const def = module_env.store.getDef(def_idx);
                try self.mapValueSchemeParams(out, def.pattern, def.expr, &scheme_params);
            }
        }
    }

    fn linkGeneratedCodecCalls(self: *EvidencePass, calls: []static_dispatch.GeneratedCodecCall) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        const source_derivations = module_env.generated_codec_derivations.items.items;
        if (source_derivations.len != self.plan_table.recorded_codec_derivations.len) {
            checkedModuleInvariant("generated codec source and checked derivation counts differed", .{});
        }
        for (source_derivations, self.plan_table.recorded_codec_derivations) |source_derivation, derivation| {
            const source_calls = module_env.generated_codec_calls.items.items[source_derivation.calls_start..][0..source_derivation.calls_len];
            const module_calls = calls[derivation.calls.start..][0..derivation.calls.len];
            if (source_calls.len != module_calls.len) {
                checkedModuleInvariant("generated codec source and checked derivation call counts differed", .{});
            }
            for (module_calls, source_calls) |*call, source_call| {
                const owner = (try self.methodOwnerForSourceContent(@fromBackingInt(@intCast(source_call.dispatcher_var)))) orelse {
                    call.resolution = .checked_error;
                    continue;
                };
                const target = switch (try self.lookupMethodTargetAcrossViews(owner, call.method) orelse {
                    call.resolution = .checked_error;
                    continue;
                }) {
                    // The declaration this codec contract names was rejected;
                    // its diagnostic is reported and nothing lowers it.
                    .rejected => {
                        call.resolution = .checked_error;
                        continue;
                    },
                    .target => |target| target,
                };
                const evidence_var: Var = @fromBackingInt(@intCast(source_call.evidence_var));
                switch (target.kind) {
                    .procedure, .local_proc => {
                        const node_id = try self.evidenceNodeForTarget(
                            target,
                            call.dispatcher_ty,
                            evidence_var,
                            .{
                                .callable_ty = call.callable_ty,
                                .renamings = module_env.generated_codec_renamings.items.items[source_derivation.renamings_start..][0..source_derivation.renamings_len],
                            },
                            .derivation,
                            .commit,
                        );
                        switch (self.evidence_nodes.items[node_id.index].nested) {
                            .resolved => {},
                            .from_callable, .through_alias => checkedModuleInvariant(
                                "generated codec method evidence was not resolved at its checked call edge",
                                .{},
                            ),
                        }
                        call.resolution = .{ .callable = node_id };
                    },
                    .structural => |kind| {
                        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                            .parser => .parser,
                            .encoder => .encoder,
                            .equality, .hash, .map, .map_effectful => checkedModuleInvariant("non-codec structural method reached a generated codec contract", .{}),
                        };
                        call.resolution = .{ .structural = self.generatedCodecDerivationForSourceConstraint(
                            @fromBackingInt(@intCast(source_call.evidence_var)),
                            expected_kind,
                        ) orelse
                            checkedModuleInvariant("structural generated codec call had no checked nested derivation", .{}) };
                    },
                }
            }
        }
        if (builtin.mode == .debug) try self.debugVerifyGeneratedCodecContracts(calls);
    }

    fn debugVerifyGeneratedCodecContracts(self: *EvidencePass, all_calls: []const static_dispatch.GeneratedCodecCall) Allocator.Error!void {
        if (builtin.mode != .debug) return;
        const type_view = self.checked_types.store.view();
        var scratch = CheckedTypeStoreView.EqualityScratch.init(self.allocator);
        defer scratch.deinit();
        for (self.plan_table.recorded_codec_derivations) |derivation| {
            const calls = all_calls[derivation.calls.start..][0..derivation.calls.len];
            for (calls, 0..) |call, index| {
                switch (call.resolution) {
                    .pending => checkedModuleInvariant(
                        "checked generated codec contract retained an unlinked call",
                        .{},
                    ),
                    .checked_error => {},
                    .callable => |node_id| {
                        // Generated codec calls are linked before the evidence
                        // builder transfers its nodes into the published plan
                        // table, so audit the builder-owned node directly.
                        const raw_node = node_id.index;
                        if (raw_node >= self.evidence_nodes.items.len) {
                            checkedModuleInvariant(
                                "checked generated codec contract referenced a missing callable evidence node",
                                .{},
                            );
                        }
                        const node = self.evidence_nodes.items[raw_node];
                        switch (node.target.kind) {
                            .procedure, .local_proc => {},
                            .structural => checkedModuleInvariant(
                                "checked generated codec callable resolution named a structural target",
                                .{},
                            ),
                        }
                        switch (node.nested) {
                            .resolved => {},
                            .from_callable, .through_alias => checkedModuleInvariant(
                                "checked generated codec callable retained unresolved nested evidence",
                                .{},
                            ),
                        }
                        if (node.dispatcher_ty == null or
                            !try type_view.rootExactEql(&scratch, node.dispatcher_ty.?, call.dispatcher_ty))
                        {
                            checkedModuleInvariant(
                                "checked generated codec callable evidence had a different dispatcher type",
                                .{},
                            );
                        }
                        const instantiated_callable = switch (node.instantiation) {
                            .callable, .alias, .derived_from_callable => |callable| callable,
                            .monomorphic => checkedModuleInvariant(
                                "checked generated codec callable evidence had no exact instantiation",
                                .{},
                            ),
                        };
                        if (!try type_view.rootExactEql(&scratch, instantiated_callable, call.callable_ty)) {
                            checkedModuleInvariant(
                                "checked generated codec callable evidence had a different callable type",
                                .{},
                            );
                        }
                    },
                    .structural => |nested_id| {
                        const raw_nested = @backingInt(nested_id);
                        if (raw_nested >= self.plan_table.recorded_codec_derivations.len) {
                            checkedModuleInvariant(
                                "checked generated codec contract referenced a missing nested derivation",
                                .{},
                            );
                        }
                        if (self.plan_table.recorded_codec_derivations[raw_nested].kind != derivation.kind) {
                            checkedModuleInvariant(
                                "checked generated codec contract referenced a nested derivation of the wrong kind",
                                .{},
                            );
                        }
                        const nested = self.plan_table.recorded_codec_derivations[raw_nested];
                        // The nested and parent contracts snapshot the same
                        // checked edge independently. Their open identities
                        // are therefore renamed copies, while every sharing
                        // relation and constraint must remain exact.
                        if (!try type_view.rootsAlphaExactEql(
                            &scratch,
                            &.{ nested.constructor_ty, nested.shape_ty },
                            &.{ call.callable_ty, call.dispatcher_ty },
                        )) {
                            checkedModuleInvariant(
                                "checked generated codec structural call disagreed with its nested derivation types",
                                .{},
                            );
                        }
                    },
                }

                if (call.subject_ty == null and call.method_role != 0) {
                    checkedModuleInvariant(
                        "checked generated codec shape-independent call had a nonzero method role",
                        .{},
                    );
                }
                var has_previous_role = call.method_role == 0;
                for (calls[0..index]) |previous| {
                    if (previous.method != call.method) continue;
                    if (call.method_role > 0 and previous.method_role == call.method_role - 1) has_previous_role = true;
                    if (previous.method_role != call.method_role) continue;
                    if ((previous.subject_ty == null) != (call.subject_ty == null)) {
                        checkedModuleInvariant(
                            "checked generated codec method role mixed subject-bearing and shape-independent calls",
                            .{},
                        );
                    }
                    if (call.subject_ty) |subject_ty| {
                        if (!try type_view.rootAliasTransparentEql(&scratch, previous.subject_ty.?, subject_ty)) {
                            checkedModuleInvariant(
                                "checked generated codec method role named different subject types",
                                .{},
                            );
                        }
                    }
                }
                if (!has_previous_role) {
                    checkedModuleInvariant(
                        "checked generated codec method roles were not dense in producer order",
                        .{},
                    );
                }
            }
        }
    }

    fn schemeSchema(self: *EvidencePass, root: Var) Allocator.Error!SchemeSchema {
        const owner = self.schemeOwner(root);
        if (self.schemas_by_root.get(owner)) |schema| return schema;
        const env = self.module.moduleEnvConst();
        const requirements = env.bindingSchemeCodecRequirementsForNode(@fromBackingInt(@intCast(@backingInt(root))));
        var explicit = std.ArrayListUnmanaged(dispatch_evidence.SchemeRequirement).empty;
        defer explicit.deinit(self.allocator);
        var relation_roots = std.ArrayListUnmanaged(Var).empty;
        defer relation_roots.deinit(self.allocator);
        try explicit.ensureTotalCapacity(self.allocator, requirements.len);
        try relation_roots.ensureTotalCapacity(self.allocator, requirements.len * 2);
        for (requirements) |requirement| {
            const receiver: Var = @fromBackingInt(@intCast(requirement.receiver_var));
            const constraint = self.types.getStaticDispatchConstraintAt(requirement.constraint_index);
            explicit.appendAssumeCapacity(.{
                .receiver = receiver,
                .constraint = constraint,
                .requires_instantiation = requirement.requires_instantiation != 0,
            });
            relation_roots.appendAssumeCapacity(receiver);
            relation_roots.appendAssumeCapacity(constraint.fn_var);
        }
        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try dispatch_evidence.enumerateEvidenceParamsWithRequirements(self.allocator, self.types, root, explicit.items, &self.traversal.enum_scratch, &params);
        const arena = self.enumerated_path_arena.allocator();
        for (params.items) |*param| {
            param.callable_contracts = try arena.dupe(types.StaticDispatchConstraint, param.callable_contracts);
        }
        const identity_vars = try self.traversal.identity_writer.identityVarsFromScheme(root, relation_roots.items);
        errdefer self.allocator.free(identity_vars);
        var dispatcher_row_count: usize = 0;
        for (params.items) |param| {
            if (param.source != .scheme_requirement) dispatcher_row_count += 1;
        }
        const dispatcher_rows = try arena.alloc(DispatcherParams.Row, dispatcher_row_count);
        var dispatcher_row_len: usize = 0;
        for (params.items, 0..) |param, index| {
            if (param.source == .scheme_requirement) continue;
            dispatcher_rows[dispatcher_row_len] = .{
                .root = self.types.resolveVar(param.dispatcher_var).var_,
                .param = std.math.cast(u32, index) orelse return error.OutOfMemory,
            };
            dispatcher_row_len += 1;
        }
        std.sort.pdq(DispatcherParams.Row, dispatcher_rows, {}, DispatcherParams.Row.lessThan);
        const schema = SchemeSchema{
            .params = try arena.dupe(EvidenceParam, params.items),
            .by_dispatcher = .{ .rows = dispatcher_rows },
            .path_nodes = try arena.dupe(static_dispatch.EvidencePathNode, self.traversal.enum_scratch.paramPathNodes()),
            .identity_vars = identity_vars,
        };
        try self.schemas_by_root.put(owner, schema);
        return schema;
    }

    fn enumerateParams(self: *EvidencePass, root: Var, out: *std.ArrayListUnmanaged(EvidenceParam)) Allocator.Error!void {
        try out.appendSlice(self.allocator, (try self.schemeSchema(root)).params);
    }

    /// The param chain at `scope_id`: the scope's own params first (depth 0),
    /// each enclosing local scope outward, then the template's params. The
    /// returned slice aliases `chain_scratch` and is valid until the next call.
    fn chainFor(self: *EvidencePass, scope_ref: DispatchScope, template_level: ChainLevel) Allocator.Error![]const ChainLevel {
        self.chain_scratch.clearRetainingCapacity();
        var current: ?DispatchScopeId = switch (scope_ref) {
            .root => null,
            .generalized => |id| id,
        };
        while (current) |id| {
            const scope = self.templates.dispatch_scopes[@backingInt(id)];
            const schema = try self.dispatch.analyses().scopeSchema(self.dispatch, id);
            try self.chain_scratch.append(self.allocator, ChainLevel.fromScheme(schema.chain));
            current = scope.parent;
        }
        try self.chain_scratch.append(self.allocator, template_level);
        return self.chain_scratch.items;
    }

    fn paramsForScope(self: *EvidencePass, _: DispatchScopeId, scheme_var: Var) Allocator.Error![]const EvidenceParam {
        return (try self.schemeSchema(scheme_var)).params;
    }

    fn appendEvidenceParams(
        self: *EvidencePass,
        params: []const EvidenceParam,
        path_nodes: []const static_dispatch.EvidencePathNode,
    ) Allocator.Error!store_serialize.Span {
        const idents = self.module.identStoreConst();
        const pool_start: u32 = @intCast(self.evidence_params_pool.items.len);
        self.published_path_nodes.clearRetainingCapacity();
        try self.published_path_nodes.appendNTimes(self.allocator, static_dispatch.no_evidence_path_node, path_nodes.len);
        for (params) |param| {
            const source: static_dispatch.EvidenceParamSource = switch (param.source) {
                .scheme_callable => if (param.path_len == 0) explicit: {
                    if (self.pathlessDefaultPhaseForParam(param)) |phase| break :explicit .{ .explicit_default = phase };
                    break :explicit .scheme_callable;
                } else .scheme_callable,
                .constraint_callable => |constraint_callable| constraint: {
                    if (!self.constraintCallableHasSpecializationDefault(param)) break :constraint .use_site_only;
                    // A default-field root always instantiates its local
                    // procedures with checked use-site evidence, so such a
                    // literal dispatcher is read from that evidence rather
                    // than from a runtime dictionary.
                    if (constraint_callable.intro_expr) |intro_expr| {
                        if (self.plan_table.lookupByExpr(@fromBackingInt(@intCast(intro_expr)))) |plan| {
                            if (self.planIsDefaultRoot(plan)) break :constraint .use_site_only;
                        }
                    }
                    break :constraint .{ .constraint_callable = .{
                        .callable_ty = self.checked_types.rootForSourceVar(self.module, constraint_callable.callable_var) orelse
                            checkedModuleInvariant("constraint-callable evidence source type was not published", .{}),
                    } };
                },
                .erased_row_remainder => .erased_row_remainder,
                .scheme_requirement => .scheme_requirement,
            };
            const published_path: static_dispatch.EvidencePath = switch (source) {
                .scheme_callable, .constraint_callable => .{
                    .last = try self.publishPathNode(path_nodes, param.path_node),
                    .len = param.path_len,
                },
                .scheme_requirement, .use_site_only, .explicit_default, .erased_row_remainder => .{},
            };
            const contract_start: u32 = @intCast(self.evidence_param_callables.items.len);
            for (param.callable_contracts) |contract| {
                try self.evidence_param_callables.append(self.allocator, self.checked_types.rootForSourceVar(self.module, contract.fn_var) orelse
                    checkedModuleInvariant("callable contract type was not published", .{}));
            }
            try self.evidence_params_pool.append(self.allocator, .{
                .callable_contracts = .{ .start = contract_start, .len = @intCast(param.callable_contracts.len) },
                .method = try self.names.internMethodIdent(idents, param.constraint.fn_name),
                .dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedModuleInvariant("checked evidence parameter dispatcher type was not published", .{}),
                .callable_ty = self.checked_types.rootForSourceVar(self.module, param.constraint.fn_var) orelse
                    checkedModuleInvariant("checked evidence parameter callable type was not published", .{}),
                .slot = if (source == .scheme_requirement) null else self.schemeVarSlot(param.dispatcher_var),
                .structural = self.structuralKindForMethodIdent(param.constraint.fn_name),
                .source = source,
                .path = published_path,
            });
        }
        return .{ .start = pool_start, .len = @intCast(params.len) };
    }

    /// Publish the scheme path ending at `scheme_node` in canonical names,
    /// sharing the prefixes this scheme already published, and return its
    /// published last node.
    fn publishPathNode(
        self: *EvidencePass,
        path_nodes: []const static_dispatch.EvidencePathNode,
        scheme_node: u32,
    ) Allocator.Error!u32 {
        const no_node = static_dispatch.no_evidence_path_node;
        if (scheme_node == no_node) return no_node;
        const idents = self.module.identStoreConst();
        const published = self.published_path_nodes.items;
        self.published_path_chain.clearRetainingCapacity();
        var node = scheme_node;
        while (node != no_node and published[node] == no_node) {
            try self.published_path_chain.append(self.allocator, node);
            node = path_nodes[node].parent;
        }
        var parent = if (node == no_node) no_node else published[node];
        var i = self.published_path_chain.items.len;
        while (i > 0) {
            i -= 1;
            const next = self.published_path_chain.items[i];
            var converted = path_nodes[next].step;
            switch (converted.stepKind()) {
                .record_field => converted.data = @backingInt(self.names.lookupRecordFieldIdent(idents, @bitCast(converted.data)) orelse
                    checkedModuleInvariant("an evidence path's field name was not interned with the module's names", .{})),
                .tag_payload_tag => converted.data = @backingInt(self.names.lookupTagIdent(idents, @bitCast(converted.data)) orelse
                    checkedModuleInvariant("an evidence path's tag name was not interned with the module's names", .{})),
                .fn_arg,
                .fn_ret,
                .alias_arg,
                .alias_backing,
                .nominal_arg,
                .nominal_backing,
                .tuple_elem,
                .tag_payload_index,
                => {},
            }
            const published_node: u32 = @intCast(self.evidence_path_nodes.items.len);
            try self.evidence_path_nodes.append(self.allocator, .{ .parent = parent, .step = converted });
            published[next] = published_node;
            parent = published_node;
        }
        return published[scheme_node];
    }

    fn pathlessDefaultPhaseForParam(self: *EvidencePass, param: EvidenceParam) ?NumericDefaultPhase {
        const resolved = self.types.resolveVar(param.dispatcher_var);
        const constraints = switch (resolved.desc.content) {
            .flex => |flex| flex.constraints,
            .rigid => |rigid| rigid.constraints,
            .alias, .field_presence, .structure, .err => return null,
        };
        return numericDefaultPhaseForConstraints(self.module.moduleEnvConst(), constraints);
    }

    fn planIsDefaultRoot(self: *const EvidencePass, plan_id: static_dispatch.StaticDispatchPlanId) bool {
        const span = self.sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (self.templates.dispatch_plan_refs[span.start .. span.start + span.len]) |default_plan_id| {
            if (default_plan_id == plan_id) return true;
        }
        return false;
    }

    /// Whether a dispatcher reachable only through a constraint callable has a
    /// checked specialization default. Only such parameters can be synthesized
    /// at compiler-generated edges, where no checked instantiation pins them.
    fn constraintCallableHasSpecializationDefault(self: *EvidencePass, param: EvidenceParam) bool {
        if (self.pathlessDefaultPhaseForParam(param) == null) return false;
        const method = param.constraint.fn_name;
        const idents = self.module.commonIdents();
        return method == idents.plus or
            method == idents.minus or
            method == idents.times or
            method == idents.div_by or
            method == idents.div_trunc_by or
            method == idents.rem_by or
            method == idents.negate or
            method == idents.from_numeral or
            method == idents.from_quote or
            method == idents.from_interpolation;
    }

    /// How a checked plan's callable relates to the evidence slot it resolves
    /// through. Only `exact` shares the slot's callable identity; the other two
    /// own an independent callable instantiation and differ in where their
    /// nested evidence comes from.
    const CallableRelation = enum {
        exact,
        independent_per_use,
        independent_reuse_slot_nested,
    };

    /// The canonical `(depth, index)` of one method target in the chain,
    /// searching innermost-out. Independent same-name callable relations share
    /// the target slot, while their checked plans retain the per-call shape.
    fn chainParamIndex(
        self: *EvidencePass,
        chain: []const ChainLevel,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?struct {
        index: static_dispatch.EvidenceChainIndex,
        callable_relation: CallableRelation,
        callable_contract: ?u32 = null,
    } {
        for (chain, 0..) |level, depth| {
            if (try self.paramIndexFor(level, dispatcher_root, method, constraint_fn_var)) |match| {
                return .{
                    .index = .{ .depth = @intCast(depth), .index = @intCast(match.index) },
                    .callable_relation = match.callable_relation,
                    .callable_contract = match.callable_contract,
                };
            }
        }
        return null;
    }

    /// Exact method-target lookup across every registry this computation can
    /// see: the local registry, then `method_lookup_views`.
    fn lookupMethodTargetAcrossViews(self: *EvidencePass, owner: static_dispatch.MethodOwner, method: canonical.MethodNameId) Allocator.Error!?static_dispatch.CheckedMethodLookup {
        return try static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, self.method_lookup_views, owner, method);
    }

    /// Map a generalized VALUE decl's scheme param roots to its pattern for
    /// use-record obligation resolution (lambda-form decls are evidence
    /// scopes instead).
    fn mapValueSchemeParams(
        self: *EvidencePass,
        out: *DispatchIndex,
        pattern: CIR.Pattern.Idx,
        expr: CIR.Expr.Idx,
        scheme_params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        const expr_data = self.module.expr(expr).data;
        if (expr_data == .e_lambda or expr_data == .e_closure) return;
        // A procedure alias owns an exact evidence scope. Its right-hand
        // side's requirements belong to that scope, not to a representative
        // use.
        if (bindsProcedureAlias(self.module, pattern, expr)) return;
        // Resolution reaches a pattern only through one of its value-use
        // records. A decl nobody instantiated (for example a local inside a
        // generalized definition, whose variables are generalized only as
        // part of that definition's scheme) has none, so it owns nothing here.
        if (!out.value_use_record_by_pattern.contains(@backingInt(pattern))) return;
        const pattern_var = ModuleEnv.varFrom(pattern);
        if (self.types.resolveVar(pattern_var).desc.rank != .generalized) return;
        scheme_params.clearRetainingCapacity();
        try self.enumerateParams(pattern_var, scheme_params);
        for (scheme_params.items) |param| {
            const root = self.types.resolveVar(param.dispatcher_var).var_;
            const entry = try out.local_value_scheme_by_var.getOrPut(@backingInt(root));
            if (!entry.found_existing) entry.value_ptr.* = @backingInt(pattern);
        }
    }

    /// The canonical param index of one dispatch obligation.
    fn paramIndexFor(
        self: *EvidencePass,
        level: ChainLevel,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?struct {
        index: u32,
        callable_relation: CallableRelation,
        callable_contract: ?u32 = null,
    } {
        const idents = self.module.identStoreConst();
        const constraint_fn_root = if (constraint_fn_var) |fn_var|
            self.types.resolveVar(fn_var).var_
        else
            null;
        const params = level.params;
        // Composite requirements are matched by their exact scheme relation
        // before structural dispatch, so the index omits them. A shared
        // receiver/method is insufficient.
        var same_method_fallback: ?u32 = null;
        for (level.by_dispatcher.forRoot(dispatcher_root)) |candidate| {
            const k = candidate.param;
            const param = params[k];
            if (try self.names.internMethodIdent(idents, param.constraint.fn_name) != method) continue;
            if (same_method_fallback == null) same_method_fallback = @intCast(k);
            if (constraint_fn_root) |fn_root| {
                if (self.types.resolveVar(param.constraint.fn_var).var_ != fn_root) {
                    for (param.callable_contracts, 0..) |contract, contract_index| {
                        if (self.types.resolveVar(contract.fn_var).var_ == fn_root) return .{
                            .index = @intCast(k),
                            .callable_relation = .independent_per_use,
                            .callable_contract = @intCast(contract_index),
                        };
                    }
                    continue;
                }
            }
            return .{ .index = @intCast(k), .callable_relation = .exact };
        }
        return if (same_method_fallback) |index|
            .{ .index = index, .callable_relation = self.fallbackCallableRelation(params[index], constraint_fn_var) }
        else
            null;
    }

    /// A same-name candidate names an independent callable. When that callable
    /// is (in one settled class with) a per-use where-method signature copy
    /// (`SchemeUseRecord.where_method_use`) whose pristine signature is the
    /// slot's own callable, the plan may reuse the slot's checked
    /// nested-evidence vector: every non-marker leaf of the copy is the
    /// signature's own variable (`Instantiator.share_leaves`). Otherwise the
    /// plan synthesizes nested evidence from its own callable.
    fn fallbackCallableRelation(self: *EvidencePass, candidate: EvidenceParam, constraint_fn_var: ?Var) CallableRelation {
        const fn_var = constraint_fn_var orelse return .independent_per_use;
        const fn_root = self.types.resolveVar(fn_var).var_;
        const record_idx = self.index.where_method_use_by_fn_var.get(@backingInt(fn_var)) orelse
            self.index.where_method_use_by_fn_root.get(fn_root) orelse
            return .independent_per_use;
        const module_env = self.module.moduleEnvConst();
        const record = module_env.scheme_uses.items.items[record_idx];
        if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use) or
            self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.slot_data)))).var_ != fn_root)
        {
            checkedModuleInvariant("where-method-use index named the wrong scheme-use record", .{});
        }
        const signature_root = self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.scheme_root)))).var_;
        const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
        const copied_callable = self.pairForResolved(pairs, signature_root) orelse
            checkedModuleInvariant("where-method-use record omitted its signature callable copy", .{});
        // Either callable may be written through a transparent alias, whose
        // backing, not the alias view, is what the use relation unified.
        if (self.types.resolveThroughAliases(copied_callable).var_ != self.types.resolveThroughAliases(fn_var).var_) {
            checkedModuleInvariant("where-method-use callable copy did not resolve to its body constraint", .{});
        }
        if (self.types.resolveVar(candidate.constraint.fn_var).var_ == signature_root) return .independent_reuse_slot_nested;
        return .independent_per_use;
    }

    fn resolvePlan(self: *EvidencePass, plan_id: static_dispatch.StaticDispatchPlanId, chain: []const ChainLevel, policy: UnpinnedPolicy) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        const plan = &self.plan_table.plans[raw];
        if (self.plan_resolved.contains(raw)) return;

        const src = self.plan_table.plan_sources[raw];
        const structural_kind: ?static_dispatch.StructuralKind = switch (plan.result_mode) {
            .value => null,
            .equality => |eq| if (eq.structural_allowed) .equality else null,
            .hash => |hash| if (hash.structural_allowed) .hash else null,
            .parser_for => |parser_for| if (parser_for.structural_allowed) .parser else null,
            .encoder_for => |encoder_for| if (encoder_for.structural_allowed) .encoder else null,
            .map => |map| if (map.structural_allowed) .map else null,
            .map_effectful => |map| if (map.structural_allowed) .map_effectful else null,
        };
        // Nested evidence built for this plan's target forwards enclosing
        // where-vars against the same chain.
        self.current_chain = chain;
        defer self.current_chain = &.{};
        const resolution: static_dispatch.CheckedCallResolution = switch (try self.resolveObligationStep(
            src.dispatcher_var,
            plan.dispatcher_ty,
            plan.method,
            structural_kind,
            src.constraint_fn_var,
            src.literal_kind,
            chain,
            policy,
        )) {
            .resolved => |resolution| resolution orelse return,
            .node => |request| .{ .direct_pending = try self.evidenceNodeForTarget(
                request.target,
                request.dispatcher_ty,
                request.constraint_fn_var,
                null,
                if (src.target_selected_by_checking) request.selection else .after_checking,
                policy,
            ) },
        };
        const generated_codec_derivation: ?static_dispatch.GeneratedCodecDerivationId = switch (resolution) {
            .structural => |derivation| switch (derivation.kind()) {
                .parser => self.generatedCodecDerivationForSourceConstraint(
                    src.constraint_fn_var orelse
                        checkedModuleInvariant("structural parser plan had no source constraint", .{}),
                    .parser,
                ) orelse
                    checkedModuleInvariant("structural parser plan had no checked generated-codec contract", .{}),
                .encoder => self.generatedCodecDerivationForSourceConstraint(
                    src.constraint_fn_var orelse
                        checkedModuleInvariant("structural encoder plan had no source constraint", .{}),
                    .encoder,
                ) orelse
                    checkedModuleInvariant("structural encoder plan had no checked generated-codec contract", .{}),
                .equality, .hash, .map, .map_effectful => null,
            },
            .direct_pending, .direct_closed, .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => null,
        };
        if (builtin.mode == .debug) switch (resolution) {
            .direct_pending => |node_id| try self.verifyDirectPlanSubstitution(node_id),
            .structural, .direct_closed, .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => {},
        };
        try self.plan_resolved.put(self.allocator, raw, {});
        try self.plan_results.append(self.allocator, .{ .plan = raw, .resolution = .{
            .resolution = resolution,
            .callable_ty = plan.callable_ty,
            .generated_codec_derivation = generated_codec_derivation,
        } });
    }

    /// A direct dispatch specializes its target under the evidence node's
    /// substitution, so that substitution must cover every quantified
    /// variable of the target's scheme, unless the node says the
    /// substitution derives from its callable.
    fn verifyDirectPlanSubstitution(self: *EvidencePass, node_id: static_dispatch.EvidenceNodeId) Allocator.Error!void {
        const node = self.evidence_nodes.items[node_id.index];
        if (node.target.kind != .procedure) return;
        const expected_len = switch (node.instantiation) {
            .derived_from_callable => 0,
            // The substitution covers the alias scope's variables, whose
            // count Monotype checks against that scope when it composes.
            .alias => return,
            .monomorphic, .callable => (try self.procedureEvidenceView(node.target)).vars.len,
        };
        if (node.subst.len != expected_len) {
            checkedModuleInvariant("direct dispatch plan's checked substitution did not match its target's scheme", .{});
        }
    }

    fn resolveIteratorPlan(self: *EvidencePass, plan_id: static_dispatch.IteratorForPlanId, chain: []const ChainLevel, policy: UnpinnedPolicy) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        const plan = &self.plan_table.iterator_for_plans[raw];
        if (self.iterator_plan_resolved.contains(raw)) return;

        const src = self.plan_table.iterator_plan_sources[raw];
        self.current_chain = chain;
        defer self.current_chain = &.{};
        const iter = (try self.resolveObligation(
            src.iter_dispatcher_var,
            plan.iter.dispatcher_ty,
            plan.iter.method,
            null,
            src.iter_fn_var,
            null,
            chain,
            policy,
        )) orelse return;
        const next = (try self.resolveObligation(
            src.next_dispatcher_var,
            plan.next.dispatcher_ty,
            plan.next.method,
            null,
            src.next_fn_var,
            null,
            chain,
            policy,
        )) orelse return;
        try self.iterator_plan_resolved.put(self.allocator, raw, {});
        try self.iterator_results.append(self.allocator, .{ .plan = raw, .resolution = .{
            .iter = iter,
            .iter_callable_ty = plan.iter.callable_ty,
            .next = next,
            .next_callable_ty = plan.next.callable_ty,
        } });
    }

    /// How an obligation that the given chain does not bind resolves.
    const UnpinnedPolicy = enum {
        /// Return null, so a template whose scheme does bind it (template
        /// plan-ref spans can overlap) or the final chain-free sweep resolves
        /// it instead. Template walks use this.
        defer_resolution,
        /// Commit it by the unpinned-dispatch rule; the result is total.
        commit,
        /// The obligation belongs to a root edge, which has no caller to pin
        /// it: a dispatcher its literals constrain takes those literals'
        /// default owner (`rootDefaultObligation`), and any other commits by
        /// the unpinned-dispatch rule. The result is total.
        root_default,

        /// The policy for an obligation whose resolution must be total, such
        /// as the nested obligations of a target's evidence node or a use
        /// instantiation's type: `root_default` stays, otherwise `commit`.
        fn committed(self: UnpinnedPolicy) UnpinnedPolicy {
            return switch (self) {
                .defer_resolution, .commit => .commit,
                .root_default => .root_default,
            };
        }
    };

    /// Resolve one dispatch obligation: `method` dispatched on
    /// `dispatcher_var`, with `constraint_fn_var` keying the discharge record
    /// that carries the chosen target's own nested obligations. `policy`
    /// decides an obligation `chain` does not bind.
    fn resolveObligation(
        self: *EvidencePass,
        dispatcher_var: Var,
        dispatcher_ty: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        literal_kind: ?LiteralKind,
        chain: []const ChainLevel,
        policy: UnpinnedPolicy,
    ) Allocator.Error!?static_dispatch.CheckedCallResolution {
        return switch (try self.resolveObligationStep(dispatcher_var, dispatcher_ty, method, structural_kind, constraint_fn_var, literal_kind, chain, policy)) {
            .resolved => |resolution| resolution,
            .node => |request| .{ .direct_pending = try self.evidenceNodeForTarget(request.target, request.dispatcher_ty, request.constraint_fn_var, null, request.selection, policy) },
        };
    }

    /// A procedure target whose evidence node the obligation resolves to.
    const EvidenceNodeRequest = struct {
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        selection: MethodTargetSelection,
    };

    /// An obligation's resolution, or the procedure target whose evidence
    /// node is its direct resolution. The node is built by the caller, so a
    /// target's nested evidence never nests native calls.
    const ObligationStep = union(enum) {
        resolved: ?static_dispatch.CheckedCallResolution,
        node: EvidenceNodeRequest,
    };

    fn resolveObligationStep(
        self: *EvidencePass,
        dispatcher_var_in: Var,
        dispatcher_ty_in: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var_in: ?Var,
        literal_kind: ?LiteralKind,
        chain: []const ChainLevel,
        policy_in: UnpinnedPolicy,
    ) Allocator.Error!ObligationStep {
        var dispatcher_var = dispatcher_var_in;
        var dispatcher_ty = dispatcher_ty_in;
        var constraint_fn_var = constraint_fn_var_in;
        var policy = policy_in;
        // A generalized value's use redirects resolution to the type that use
        // instantiated, which can itself redirect.
        redirect: while (true) {
            if (constraint_fn_var) |fn_var| {
                if (self.types.varStaticDispatchRejected(fn_var)) return .{ .resolved = .checked_error };
            }

            const resolved = self.types.resolveVar(dispatcher_var);
            // A structural receiver may still own a generic codec requirement.
            // Its exact scheme relation takes precedence over its current shape.
            if (structural_kind == .parser or structural_kind == .encoder) if (constraint_fn_var) |fn_var| {
                for (chain, 0..) |level, depth| {
                    for (level.params, 0..) |param, index| {
                        if (param.source != .scheme_requirement) continue;
                        if (self.types.resolveVar(param.constraint.fn_var).var_ != self.types.resolveVar(fn_var).var_) continue;
                        if (try self.names.internMethodIdent(self.module.identStoreConst(), param.constraint.fn_name) != method) continue;
                        return .{ .resolved = .{ .evidence_dependent = .{
                            .scheme_param = .{
                                .scheme = level.scheme orelse checkedModuleInvariant("forwarded scheme requirement was not published", .{}),
                                .index = param.published_index orelse checkedModuleInvariant("forwarded scheme requirement was not published", .{}),
                            },
                            .index = .{ .depth = @intCast(depth), .index = @intCast(index) },
                            .independent_callable = false,
                        } } };
                    }
                }
            };

            // Builtin containers have ordinary registry methods for parser_for and
            // encoder_for, but checking can deliberately discharge an obligation
            // through the generated structural codec path instead. Preserve that
            // exact producer decision: the derivation records the original
            // constraint-function variable that selected it.
            if (structural_kind) |kind| {
                const derivation_kind: ?static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                    .parser => .parser,
                    .encoder => .encoder,
                    .equality, .hash, .map, .map_effectful => null,
                };
                if (derivation_kind) |expected_kind| {
                    if (constraint_fn_var) |fn_var| {
                        if (self.generatedCodecDerivationForSourceConstraint(fn_var, expected_kind) != null) {
                            return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                        }
                    }
                }
            }

            // A generalized VALUE decl's scheme param may LOOK concrete here:
            // compile-time finalization defaults the pristine var (e.g. to Dec)
            // after uses were instantiated. The uses are the truth—they carry
            // the type each inline lowering actually runs at—so resolve through
            // a representative use record before trusting the var's content.
            if (self.index.local_value_scheme_by_var.get(@backingInt(resolved.var_))) |pattern_raw| {
                if (self.index.value_use_record_by_pattern.get(pattern_raw)) |record_idx| {
                    const module_env = self.module.moduleEnvConst();
                    const record = module_env.scheme_uses.items.items[record_idx];
                    const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
                    if (self.pairForResolved(pairs, resolved.var_)) |fresh| {
                        if (self.types.resolveVar(fresh).var_ != resolved.var_) {
                            const fresh_fn: ?Var = if (constraint_fn_var) |fn_var| self.pairForResolved(pairs, self.types.resolveVar(fn_var).var_) else null;
                            const fresh_dispatcher_ty = self.checked_types.rootForSourceVar(self.module, fresh) orelse
                                checkedModuleInvariant("checked dispatch use instantiation type was not published", .{});
                            dispatcher_var = fresh;
                            dispatcher_ty = fresh_dispatcher_ty;
                            constraint_fn_var = fresh_fn orelse constraint_fn_var;
                            policy = policy.committed();
                            continue :redirect;
                        }
                    }
                }
            }

            switch (resolved.desc.content) {
                // A different checker diagnostic can poison the value that owns
                // this receiver after the dispatch itself checked successfully.
                // The explicit rejection map above remains the sole authority for
                // dispatch-specific failures; `.err` is the separate value-error
                // fence and must never be inferred from the callable or its return.
                // A presence variable is not a dispatch target and carries no
                // obligations—treat it as inert like `.err`.
                .err, .field_presence => return .{ .resolved = .checked_error },
                .flex => |flex| {
                    switch (policy) {
                        .root_default => if (try self.rootDefaultObligation(flex.constraints, dispatcher_ty, method, structural_kind, constraint_fn_var)) |step| return step,
                        .defer_resolution, .commit => {},
                    }
                    return self.resolveVarObligation(resolved.var_, method, structural_kind, constraint_fn_var, chain, policy);
                },
                .rigid => return self.resolveVarObligation(resolved.var_, method, structural_kind, constraint_fn_var, chain, policy),
                // A transparent alias dispatches exactly as its backing does
                // (design.md "Type Alias Invariant"), including a backing that
                // is a where-constrained variable. `dispatcher_ty` stays the
                // alias root, which is a transparent view of that backing.
                .alias => |alias| {
                    dispatcher_var = self.types.getAliasBackingVar(alias);
                    continue :redirect;
                },
                .structure => {
                    if (try self.methodOwnerForSourceContent(resolved.var_)) |owner| {
                        if (try self.lookupMethodTargetAcrossViews(owner, method)) |found| {
                            return switch (found) {
                                // The method is declared, but canonicalization or
                                // checking rejected its declaration and already
                                // reported why. The dispatch itself needs no second
                                // diagnostic; it just must never lower.
                                .rejected => .{ .resolved = .checked_error },
                                .target => |target| try self.resolutionForMethodTarget(
                                    target,
                                    structural_kind,
                                    dispatcher_ty,
                                    constraint_fn_var,
                                    if (literal_kind != null and isBuiltinLiteralConversion(literal_kind.?, owner)) .builtin_literal else .dispatch_edge,
                                ),
                            };
                        }
                        // The dispatcher has an owner, checking passed, and no
                        // registry-visible view declares the method: the checker
                        // discharged the obligation with the derived structural
                        // implementation. Value dispatches cannot discharge
                        // structurally, so a miss there is a compiler bug
                        // (every view the checker resolved against is searched
                        // above).
                        if (structural_kind) |kind| return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                        base.invariant("the checked tables could not resolve a checked dispatch target for an owned method", .{});
                    }
                    // No owner head: a genuinely structural shape.
                    if (structural_kind) |kind| return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                    checkedModuleInvariant("ownerless non-structural dispatch reached the checked tables without an explicit rejection", .{});
                },
            }
        }
    }

    /// The callable a generated codec relation's derivation was validated at.
    fn codecRelationCallable(self: *EvidencePass, constraint_fn_var: Var) Var {
        return self.index.codec_instance_by_template.get(self.types.resolveVar(constraint_fn_var).var_) orelse constraint_fn_var;
    }

    fn generatedCodecDerivationForSourceConstraint(
        self: *EvidencePass,
        constraint_fn_var: Var,
        expected_kind: static_dispatch.GeneratedCodecDerivationKind,
    ) ?static_dispatch.GeneratedCodecDerivationId {
        const by_kind = self.index.generated_codec_by_source.getPtrConst(self.codecRelationCallable(constraint_fn_var)) orelse return null;
        return by_kind.get(expected_kind);
    }

    /// A root edge (a template running as a root, or the app procedure a
    /// platform requirement invokes) has no caller to pin the variables of its
    /// scheme, so a dispatcher its literals constrain takes those literals'
    /// default owner: Dec for numerals and defaultable arithmetic, Str for
    /// quotes and interpolations.
    fn rootDefaultObligation(
        self: *EvidencePass,
        constraints: types.StaticDispatchConstraint.SafeList.Range,
        dispatcher_ty: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?ObligationStep {
        const owner: static_dispatch.MethodOwner = switch (numericDefaultPhaseForConstraints(self.module.moduleEnvConst(), constraints) orelse return null) {
            .mono_specialization => .{ .builtin = .dec },
            .mono_specialization_str => .{ .builtin = .str },
            // `checking_finalized` is stamped only on vars checking already
            // resolved; an unresolved one cannot carry it.
            .checking_finalized => return .{ .resolved = .checked_error },
        };
        return switch (try self.lookupMethodTargetAcrossViews(owner, method) orelse return null) {
            .rejected => .{ .resolved = .checked_error },
            .target => |target| try self.resolutionForMethodTarget(target, structural_kind, dispatcher_ty, constraint_fn_var, .after_checking),
        };
    }

    fn resolveVarObligation(
        self: *EvidencePass,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        chain: []const ChainLevel,
        policy: UnpinnedPolicy,
    ) Allocator.Error!ObligationStep {
        if (try self.chainParamIndex(chain, dispatcher_root, method, constraint_fn_var)) |match| {
            const independent_callable = match.callable_relation != .exact;
            const level = chain[match.index.depth];
            const owner = level.params[match.index.index].published_index orelse
                checkedModuleInvariant("forwarded evidence owner was not published", .{});
            const schema = level.published[owner];
            return .{ .resolved = .{ .evidence_dependent = .{
                .scheme_param = if (match.callable_contract != null or
                    schema.source != .scheme_callable) .{
                    .scheme = level.scheme orelse checkedModuleInvariant("forwarded evidence owner was not published", .{}),
                    .index = owner,
                } else null,
                .index = match.index,
                .independent_callable = independent_callable,
                .reuse_slot_nested_evidence = match.callable_relation == .independent_reuse_slot_nested,
                .callable_contract = match.callable_contract,
            } } };
        }

        // Not bound by this chain. During template walks another template's
        // scheme may bind it (plan-ref spans can overlap); only the final
        // sweep commits unpinned classifications.
        switch (policy) {
            .defer_resolution => return .{ .resolved = null },
            .commit, .root_default => {},
        }

        // Not an evidence param of any enclosing callable, so no edge pins
        // it, and checking resolved no default for it: a dispatcher checking
        // defaults is unified with its default owner before the checked tables
        // (`flexConstraintCompatibility`), after validating the owner's
        // method against the dispatch's callable. A still-flex dispatcher
        // here is one no value ever reaches (a parameter of a function value
        // nothing calls), so its dispatch is unreachable rather than a call
        // of a default owner's method, whose signature nothing validated
        // against the callable: such a call would lower with operands the
        // method does not take.
        // Generated codecs require the explicit checker snapshot handled
        // above; without one, the unpinned-dispatch rule decides.
        return .{ .resolved = switch (static_dispatch.unpinnedDispatchResolution(structural_kind)) {
            .structural => .{ .structural = try self.structuralDerivation(structural_kind.?, constraint_fn_var) },
            .unreachable_value => .@"unreachable",
        } };
    }

    fn structuralDerivation(
        self: *EvidencePass,
        kind: static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
    ) Allocator.Error!static_dispatch.StructuralDerivation {
        return switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser => .parser,
            .encoder => .encoder,
            .map, .map_effectful => blk: {
                const fn_var = constraint_fn_var orelse checkedModuleInvariant("derived map evidence had no constraint function", .{});
                const plan = self.types.derivedMapPlan(fn_var) orelse checkedModuleInvariant("derived map evidence had no checked payload selection", .{});
                const canonical_plan = static_dispatch.DerivedMapPlan{
                    .tag = self.names.lookupTagIdent(self.module.identStoreConst(), plan.tag_name) orelse checkedModuleInvariant("a structural tag name was not interned with the module names", .{}),
                    .payload_index = plan.payload_index,
                };
                break :blk if (kind == .map)
                    .{ .map = canonical_plan }
                else
                    .{ .map_effectful = canonical_plan };
            },
        };
    }

    /// The method owner of a settled source var, walking alias content
    /// transparently (the source-var analog of monotype lowering's
    /// dispatch-head read of published type identity).
    fn methodOwnerForSourceContent(self: *EvidencePass, var_: Var) Allocator.Error!?static_dispatch.MethodOwner {
        var current = var_;
        var remaining: u64 = self.types.len();
        while (true) {
            const resolved = self.types.resolveVar(current);
            switch (resolved.desc.content) {
                .alias => |alias| {
                    if (remaining == 0) {
                        checkedModuleInvariant("checked evidence source alias chain was cyclic", .{});
                    }
                    remaining -= 1;
                    current = self.types.getAliasBackingVar(alias);
                },
                .structure => |flat_type| switch (flat_type) {
                    .nominal_type => |nominal| {
                        if (categorizeBuiltinNominal(self.module, self.import_views, nominal)) |builtin_nominal| {
                            if (builtin_nominal == .try_) {
                                const module_identity_id = self.names.lookupModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module)) orelse checkedModuleInvariant("a dispatcher origin module was not interned with the module names", .{});
                                return .{ .nominal = .{
                                    .module = module_identity_id,
                                    .source_decl = nominal.statement(),
                                } };
                            }
                            return .{ .builtin = static_dispatch.builtinOwnerForCheckedBuiltin(builtin_nominal) };
                        }
                        const module_identity_id = self.names.lookupModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module)) orelse checkedModuleInvariant("a dispatcher origin module was not interned with the module names", .{});
                        return .{ .nominal = .{
                            .module = module_identity_id,
                            .source_decl = nominal.statement(),
                        } };
                    },
                    .record,
                    .tuple,
                    .fn_pure,
                    .fn_effectful,
                    .fn_unbound,
                    .empty_record,
                    .tag_union,
                    .empty_tag_union,
                    => return null,
                },
                .flex, .rigid, .field_presence, .err => return null,
            }
        }
    }

    /// Inspection's use of each override is a dispatch-target edge whose
    /// instantiation checking recorded (design.md "Inspect Overrides"). The
    /// edge's evidence supplies the method's requirements at `T -> Str`.
    /// Preserve the checked registry's semantic resolution. Compiler-derived
    /// structural declarations are evidence themselves and must never enter a
    /// callable target's evidence-node graph.
    fn resolutionForMethodTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        structural_kind: ?static_dispatch.StructuralKind,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        selection: MethodTargetSelection,
    ) Allocator.Error!ObligationStep {
        return switch (target.kind) {
            .structural => |kind| blk: {
                if (structural_kind == null or structural_kind.? != kind) {
                    checkedModuleInvariant("structural method registry result did not match the checked dispatch result mode", .{});
                }
                break :blk .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
            },
            .procedure, .local_proc => .{ .node = .{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .constraint_fn_var = constraint_fn_var,
                .selection = selection,
            } },
        };
    }

    const ProcedureEvidenceSchema = static_dispatch.ProcedureEvidenceSchema;

    /// The schema of a procedure target's template, in the module that
    /// declares it.
    fn procedureEvidenceView(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!SchemaView {
        const procedure = switch (target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => checkedModuleInvariant("procedure evidence view requested for a non-procedure target", .{}),
        };
        const target_key = procedure.template.module;
        if (target_key.eql(self.import_views.current_owner)) {
            return try self.dispatch.templateSchema(procedure.template.template);
        }
        const view = self.import_views.viewForKey(target_key) orelse
            checkedModuleInvariant("procedure evidence target module was not among the modules dispatch resolution reads", .{});
        return try (try view.dispatch()).templateSchema(procedure.template.template);
    }

    /// Whether every evidence parameter of a procedure target is fixed by its
    /// concrete callable relation: either projected from the callable or
    /// reached through the callable of another requirement, which Monotype's
    /// substitution-derived fixpoint binds once that requirement's target is
    /// selected.
    fn procedureEvidenceDerivesFromCallable(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!bool {
        for ((try self.procedureEvidenceView(target)).params) |param| {
            switch (param.source) {
                .scheme_callable => if (param.path.len == 0) return false,
                .constraint_callable, .use_site_only => {},
                .scheme_requirement, .explicit_default, .erased_row_remainder => return false,
            }
        }
        return true;
    }

    fn procedureEvidenceSchema(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!ProcedureEvidenceSchema {
        return static_dispatch.procedureEvidenceSchema((try self.procedureEvidenceView(target)).params);
    }

    /// Build the evidence node for `target`. A checker-recorded dispatch-target
    /// record is the exact evidence selected at the discharge edge; compiler-
    /// generated edges that have no record derive evidence from the target
    /// schema and concrete callable relation. The generated codec derivation
    /// supplies the frozen contract callable identity explicitly; its source
    /// variable remains only the durable key for any recorded nested evidence.
    /// How a method target was selected, which decides whether a checked
    /// instantiation record must exist for it. A `dispatch_edge` target was
    /// chosen by resolving a static-dispatch constraint, and that resolution
    /// records the instantiation it performed. A `derivation` target was
    /// chosen by a generated codec deriving over a type's fields: there is no
    /// dispatch edge behind it, so no such record was ever written. A
    /// `after_checking` target was chosen by the checked module's analyses rather than by checking:
    /// the numeric default owner of a dispatcher no edge pins, or the target
    /// of a literal conversion checking left to each specialization.
    /// A `builtin_literal` target converts a source literal on a builtin
    /// number or `Str`, which checking discharges as a primitive with no
    /// callable instantiation.
    const MethodTargetSelection = enum { dispatch_edge, derivation, after_checking, builtin_literal };

    const LiteralKind = types.StaticDispatchConstraint.LiteralKind;

    /// Checking's primitive literal rule: a numeral converts natively to a
    /// builtin number, and a quote or interpolation to `Str`.
    fn isBuiltinLiteralConversion(kind: LiteralKind, owner: static_dispatch.MethodOwner) bool {
        const builtin_owner = switch (owner) {
            .builtin => |builtin_owner| builtin_owner,
            .nominal => return false,
        };
        return switch (kind) {
            .numeral => switch (builtin_owner) {
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => true,
                .list,
                .box,
                .dict,
                .set,
                .fields,
                .field,
                .bool,
                .str,
                .u8x16,
                .i8x16,
                .u16x8,
                .i16x8,
                .u32x4,
                .i32x4,
                .u64x2,
                .i64x2,
                .parse_tag_union_spec,
                .crypto_sha256_digest,
                .crypto_sha256_hasher,
                .crypto_blake3_digest,
                .crypto_blake3_hasher,
                .iter,
                .stream,
                => false,
            },
            .quote, .interpolation => builtin_owner == .str,
        };
    }

    fn evidenceNodeForTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        contract: ?ContractCallable,
        selection: MethodTargetSelection,
        policy: UnpinnedPolicy,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        // Every nested obligation of a node is resolved totally.
        const nested_policy = policy.committed();
        var frames = std.ArrayList(EvidenceRecordFrame).empty;
        defer {
            for (frames.items) |*frame| {
                _ = self.record_in_progress.remove(frame.record_idx);
                frame.deinit(self.allocator);
            }
            frames.deinit(self.allocator);
        }
        switch (try self.beginEvidenceNode(target, dispatcher_ty, constraint_fn_var, contract, selection)) {
            .done => |node_id| return node_id,
            .record => |frame| try frames.append(self.allocator, frame),
        }
        // The node of a nested target that just finished, for the pending
        // parameter of the frame below it.
        var delivered: ?static_dispatch.EvidenceNodeId = null;
        while (true) {
            const top = frames.items.len - 1;
            const frame = &frames.items[top];
            if (delivered) |node_id| {
                frame.entries.appendAssumeCapacity(self.evidenceFromResolution(frame.pending, .{ .direct_pending = node_id }));
                delivered = null;
            }
            if (frame.next < frame.params.items.len) {
                const param = frame.params.items[frame.next];
                frame.next += 1;
                const context = try self.evidenceContextForRecordParam(frame.pairs, param);
                switch (try self.resolveObligationStep(context.var_, context.dispatcher_ty, context.method, context.structural_kind, context.fresh_fn_var, context.literal_kind, self.current_chain, nested_policy)) {
                    .resolved => |resolution| frame.entries.appendAssumeCapacity(self.evidenceFromResolution(context, resolution orelse
                        checkedModuleInvariant("committed evidence resolution was not total", .{}))),
                    .node => |request| switch (try self.beginEvidenceNode(request.target, request.dispatcher_ty, request.constraint_fn_var, null, request.selection)) {
                        .done => |node_id| frame.entries.appendAssumeCapacity(self.evidenceFromResolution(context, .{ .direct_pending = node_id })),
                        .record => |nested| {
                            frame.pending = context;
                            try frames.append(self.allocator, nested);
                        },
                    },
                }
                continue;
            }
            var finished = frames.pop().?;
            defer finished.deinit(self.allocator);
            const node_id = self.finishEvidenceNode(&finished) catch |err| {
                _ = self.record_in_progress.remove(finished.record_idx);
                return err;
            };
            if (frames.items.len == 0) return node_id;
            delivered = node_id;
        }
    }

    /// A target's evidence node whose recorded nested evidence is still being
    /// resolved, one parameter of the scheme-use record at a time. The record
    /// stays in progress until the node is interned.
    const EvidenceRecordFrame = struct {
        record_idx: u32,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        callable_ty: CheckedTypeId,
        procedure_schema: ?ProcedureEvidenceSchema,
        scheme_root: Var,
        pairs: []const ModuleEnv.SchemeUsePair,
        /// The renaming a generated codec contract's callable carries.
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
        params: std.ArrayListUnmanaged(EvidenceParam) = .empty,
        entries: std.ArrayListUnmanaged(static_dispatch.CheckedEvidence) = .empty,
        next: usize = 0,
        /// The parameter whose target node the frame above is building.
        pending: EvidenceContext = undefined,

        fn deinit(frame: *EvidenceRecordFrame, allocator: Allocator) void {
            frame.params.deinit(allocator);
            frame.entries.deinit(allocator);
        }
    };

    /// The callable a generated codec contract names for one of its calls,
    /// with the renaming the contract's snapshot applied. The call's recorded
    /// substitution names the originals of the types the snapshot renamed.
    const ContractCallable = struct {
        callable_ty: CheckedTypeId,
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
    };

    const EvidenceNodeStart = union(enum) {
        done: static_dispatch.EvidenceNodeId,
        /// The target's recorded nested evidence must be resolved first.
        record: EvidenceRecordFrame,
    };

    fn finishEvidenceNode(self: *EvidencePass, frame: *const EvidenceRecordFrame) Allocator.Error!static_dispatch.EvidenceNodeId {
        const nested: RecordSiteSpans = .{
            .refs = try self.appendEvidenceRefs(frame.entries.items),
            .subst = try self.appendSiteSubstitution(frame.scheme_root, frame.pairs, frame.renamings),
        };
        const through_alias = frame.target.alias != null;
        if (!through_alias and (frame.procedure_schema == .requires_record or frame.procedure_schema == .from_target)) {
            if (nested.refs.len != (try self.procedureEvidenceView(frame.target)).params.len) {
                checkedModuleInvariant("recorded procedure target evidence length differed from its declared params", .{});
            }
        }
        const node_id = try self.internEvidenceNode(.{
            .target = frame.target,
            .dispatcher_ty = frame.dispatcher_ty,
            .generated_codec_derivation = null,
            .instantiation = if (through_alias) .{ .alias = frame.callable_ty } else .{ .callable = frame.callable_ty },
            .nested = if (through_alias) .{ .through_alias = nested.refs } else .{ .resolved = nested.refs },
            .subst = nested.subst,
        });
        try self.node_by_record.put(frame.record_idx, node_id);
        _ = self.record_in_progress.remove(frame.record_idx);
        return node_id;
    }

    fn beginEvidenceNode(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        contract: ?ContractCallable,
        selection: MethodTargetSelection,
    ) Allocator.Error!EvidenceNodeStart {
        if (target.kind == .structural) {
            checkedModuleInvariant("structural method registry result reached the callable evidence-node graph", .{});
        }
        const renamings: []const ModuleEnv.GeneratedCodecRenaming = if (contract) |named| named.renamings else &.{};
        const callable_ty = if (contract) |named| named.callable_ty else if (constraint_fn_var) |fn_var|
            self.checked_types.rootForSourceVar(self.module, fn_var) orelse
                checkedModuleInvariant("checked direct evidence callable type was not published", .{})
        else
            null;
        const record_idx: ?u32 = if (constraint_fn_var) |fn_var|
            self.index.target_by_fn_var.get(@backingInt(fn_var))
        else
            null;
        const generated_codec_derivation: ?static_dispatch.GeneratedCodecDerivationId = null;

        const procedure_schema: ?ProcedureEvidenceSchema = switch (target.kind) {
            .procedure => try self.procedureEvidenceSchema(target),
            .local_proc, .structural => null,
        };
        if (target.alias != null) {
            // The dispatch edge instantiated the alias's scheme, whose
            // requirements are not the target's. Its record substitutes the
            // alias scope's variables and resolves the alias's obligations;
            // the target's substitution and evidence compose through the
            // alias's forwarded lookup. An edge with no record instantiated
            // an alias scheme with no variables, and so no obligations.
            const callable = callable_ty orelse
                checkedModuleInvariant("method target reached through an alias had no checked callable", .{});
            if (record_idx == null) {
                return .{ .done = try self.internEvidenceNode(.{
                    .target = target,
                    .dispatcher_ty = dispatcher_ty,
                    .generated_codec_derivation = generated_codec_derivation,
                    .instantiation = .{ .alias = callable },
                    .nested = .{ .through_alias = .{} },
                }) };
            }
        }
        if (record_idx) |idx| {
            const record = self.module.moduleEnvConst().scheme_uses.items.items[idx];
            if (target.alias == null and record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.recursive_dispatch_target)) {
                // The checker closed an exact concrete backedge and proved
                // every requirement is determined by the target's callable,
                // directly or through the callables of determined
                // requirements. Publish its finite recipe instead of
                // expanding it again.
                if (target.kind == .procedure and !try self.procedureEvidenceDerivesFromCallable(target)) {
                    checkedModuleInvariant("recursive dispatch target did not have callable-derived evidence", .{});
                }
                return .{ .done = try self.internEvidenceNode(.{
                    .target = target,
                    .dispatcher_ty = dispatcher_ty,
                    .generated_codec_derivation = generated_codec_derivation,
                    .instantiation = .{ .callable = callable_ty.? },
                    .nested = if (procedure_schema == .none) .{ .resolved = .{} } else .from_callable,
                }) };
            }
            if (self.node_by_record.get(idx)) |memoized| {
                const existing = self.evidence_nodes.items[memoized.index];
                const checked_view = self.checked_types.store.view();
                const callable_matches = switch (existing.instantiation) {
                    .monomorphic, .derived_from_callable => false,
                    .callable => |existing_callable| target.alias == null and try checked_view.sameType(existing_callable, callable_ty.?),
                    .alias => |existing_callable| target.alias != null and try checked_view.sameType(existing_callable, callable_ty.?),
                };
                const dispatcher_matches = if (existing.dispatcher_ty) |existing_dispatcher|
                    if (dispatcher_ty) |requested| try checked_view.sameType(existing_dispatcher, requested) else false
                else
                    dispatcher_ty == null;
                if (!dispatcher_matches or
                    existing.generated_codec_derivation != generated_codec_derivation or
                    !callable_matches)
                {
                    checkedModuleInvariant("one checked dispatch evidence record resolved at two checked call identities", .{});
                }
                return .{ .done = memoized };
            }
            if ((try self.record_in_progress.getOrPut(idx)).found_existing) {
                checkedModuleInvariant("checked dispatch evidence chain was cyclic", .{});
            }
            errdefer _ = self.record_in_progress.remove(idx);

            const module_env = self.module.moduleEnvConst();
            if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
                checkedModuleInvariant("where-method callable relation reached scheme-use evidence emission", .{});
            }
            var frame: EvidenceRecordFrame = .{
                .record_idx = idx,
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .callable_ty = callable_ty.?,
                .procedure_schema = procedure_schema,
                .scheme_root = @fromBackingInt(@intCast(record.scheme_root)),
                .pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len],
                .renamings = renamings,
            };
            errdefer frame.deinit(self.allocator);
            try self.enumerateParams(frame.scheme_root, &frame.params);
            try frame.entries.ensureTotalCapacity(self.allocator, frame.params.items.len);
            return .{ .record = frame };
        }

        // Without a record this node carries no substitution. A dispatch edge
        // the checker discharged records one whenever the target's scheme has
        // variables; a target the checked module's analyses selected was never instantiated by
        // checking, so its node says the substitution derives from the
        // callable.
        if (target.kind == .procedure and constraint_fn_var != null and selection == .dispatch_edge and
            (try self.procedureEvidenceView(target)).vars.len != 0)
        {
            checkedModuleInvariant("polymorphic procedure target evidence had no checked instantiation record", .{});
        }
        const instantiation: static_dispatch.EvidenceTargetInstantiation = switch (selection) {
            .after_checking, .builtin_literal => .{ .derived_from_callable = callable_ty orelse
                checkedModuleInvariant("target evidence checking never instantiated had no checked callable", .{}) },
            .dispatch_edge, .derivation => if (callable_ty) |callable| .{ .callable = callable } else .monomorphic,
        };

        if (procedure_schema == .from_callable) {
            if (constraint_fn_var == null) {
                checkedModuleInvariant("callable-derived procedure evidence had no checked callable relation", .{});
            }
            return .{ .done = try self.internEvidenceNode(.{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .generated_codec_derivation = generated_codec_derivation,
                .instantiation = instantiation,
                .nested = .from_callable,
            }) };
        }

        if (procedure_schema == .requires_record or procedure_schema == .from_target) {
            checkedModuleInvariant("pathless procedure target evidence had no checked instantiation record", .{});
        }
        if (target.kind == .local_proc and constraint_fn_var != null and selection == .dispatch_edge) {
            checkedModuleInvariant("constrained local-procedure target evidence had no checked instantiation record", .{});
        }

        return .{ .done = try self.internEvidenceNode(.{
            .target = target,
            .dispatcher_ty = dispatcher_ty,
            .generated_codec_derivation = generated_codec_derivation,
            .instantiation = instantiation,
            .nested = .{ .resolved = .{} },
        }) };
    }

    fn internEvidenceNode(
        self: *EvidencePass,
        candidate: static_dispatch.EvidenceNode,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        // Bucket selector only; `evidenceNodesEql` decides identity, so a
        // collision costs one extra chain step. A checked type is hashed by
        // its identity as a type (`hashCheckedTypeIdentity`), which equal
        // types share whichever ids name them.
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, candidate.target);
        std.hash.autoHash(&hasher, candidate.dispatcher_ty != null);
        if (candidate.dispatcher_ty) |ty| try self.hashCheckedTypeIdentity(&hasher, ty);
        std.hash.autoHash(&hasher, candidate.generated_codec_derivation);
        std.hash.autoHash(&hasher, std.meta.activeTag(candidate.instantiation));
        switch (candidate.instantiation) {
            .monomorphic => {},
            .callable, .alias, .derived_from_callable => |ty| try self.hashCheckedTypeIdentity(&hasher, ty),
        }
        for (self.site_substitutions.items[candidate.subst.start .. candidate.subst.start + candidate.subst.len]) |ty| {
            try self.hashCheckedTypeIdentity(&hasher, ty);
        }
        switch (candidate.nested) {
            .from_callable => std.hash.autoHash(&hasher, @as(u8, 0)),
            .resolved, .through_alias => |span| {
                std.hash.autoHash(&hasher, @as(u8, if (candidate.nested == .resolved) 1 else 2));
                const refs = self.evidence_refs.items[span.start .. span.start + span.len];
                std.hash.autoHash(&hasher, refs.len);
                for (refs) |ref| {
                    try self.hashCheckedTypeIdentity(&hasher, ref.dispatcher_ty);
                    std.hash.autoHash(&hasher, ref.resolution);
                    std.hash.autoHash(&hasher, ref.callable_contracts);
                }
            },
        }
        const hash = hasher.final();
        var existing = self.evidence_node_buckets.get(hash);
        while (existing) |index| {
            if (try self.evidenceNodesEql(self.evidence_nodes.items[index], candidate)) {
                return .{ .index = index, .owner = self.owner };
            }
            existing = self.evidence_node_next.items[index];
        }

        const index: u32 = @intCast(self.evidence_nodes.items.len);
        const node_id: static_dispatch.EvidenceNodeId = .{ .index = index, .owner = self.owner };
        try self.evidence_nodes.append(self.allocator, candidate);
        try self.evidence_node_next.append(self.allocator, self.evidence_node_buckets.get(hash));
        try self.evidence_node_buckets.put(hash, index);
        return node_id;
    }

    /// Hash `ty` as the type it is: a type that reaches no identity variable
    /// is one type wherever it occurs, so it hashes by its canonical key, and
    /// any other type is identified by its id alone (design.md "Synthesized
    /// Types").
    fn hashCheckedTypeIdentity(self: *const EvidencePass, hasher: *std.hash.Wyhash, ty: CheckedTypeId) Allocator.Error!void {
        const type_view = self.checked_types.store.view();
        if (try type_view.rootHasIdentityVariables(ty)) {
            std.hash.autoHash(hasher, @as(u8, 0));
            std.hash.autoHash(hasher, ty);
        } else {
            std.hash.autoHash(hasher, @as(u8, 1));
            hasher.update(&(try type_view.rootKey(ty)).bytes);
        }
    }

    fn evidenceNodesEql(
        self: *const EvidencePass,
        left: static_dispatch.EvidenceNode,
        right: static_dispatch.EvidenceNode,
    ) Allocator.Error!bool {
        const type_view = self.checked_types.store.view();
        if (!std.meta.eql(left.target, right.target) or
            left.generated_codec_derivation != right.generated_codec_derivation or
            std.meta.activeTag(left.instantiation) != std.meta.activeTag(right.instantiation)) return false;
        if ((left.dispatcher_ty == null) != (right.dispatcher_ty == null)) return false;
        if (left.dispatcher_ty) |left_ty| {
            if (!try type_view.sameType(left_ty, right.dispatcher_ty.?)) return false;
        }
        switch (left.instantiation) {
            .monomorphic => {},
            inline .callable, .alias, .derived_from_callable => |left_ty, tag| {
                if (!try type_view.sameType(left_ty, @field(right.instantiation, @tagName(tag)))) return false;
            },
        }
        const left_subst = self.site_substitutions.items[left.subst.start .. left.subst.start + left.subst.len];
        const right_subst = self.site_substitutions.items[right.subst.start .. right.subst.start + right.subst.len];
        if (left_subst.len != right_subst.len) return false;
        for (left_subst, right_subst) |left_ty, right_ty| {
            if (!try type_view.sameType(left_ty, right_ty)) return false;
        }
        if (std.meta.activeTag(left.nested) != std.meta.activeTag(right.nested)) return false;
        return switch (left.nested) {
            .from_callable => true,
            .resolved, .through_alias => |left_span| blk: {
                const right_span = switch (right.nested) {
                    .resolved, .through_alias => |span| span,
                    .from_callable => unreachable, // the tags were compared equal above
                };
                const left_refs = self.evidence_refs.items[left_span.start .. left_span.start + left_span.len];
                const right_refs = self.evidence_refs.items[right_span.start .. right_span.start + right_span.len];
                if (left_refs.len != right_refs.len) break :blk false;
                for (left_refs, right_refs) |left_ref, right_ref| {
                    if (!std.meta.eql(left_ref.resolution, right_ref.resolution) or
                        !std.meta.eql(left_ref.callable_contracts, right_ref.callable_contracts) or
                        !try type_view.sameType(left_ref.dispatcher_ty, right_ref.dispatcher_ty)) break :blk false;
                }
                break :blk true;
            },
        };
    }

    const RecordSiteSpans = struct {
        refs: static_dispatch.EvidenceSpan,
        subst: static_dispatch.EvidenceSpan,
    };

    /// Whether an evidence chain has no parameters in any of its frames, so
    /// no resolution against it can depend on it.
    fn evidenceChainIsEmpty(chain: []const ChainLevel) bool {
        for (chain) |level| {
            if (level.params.len != 0) return false;
        }
        return true;
    }

    const RecordSubstitutionKey = struct {
        scheme_root: u32,
        pairs_start: u32,
        pairs_len: u32,
        unpinned: UnpinnedRecordEvidence,
    };

    /// How a scheme-use record publishes an obligation that neither the
    /// record's substitution nor the current chain pins.
    const UnpinnedRecordEvidence = enum {
        /// Publish nothing yet: a later walk may bind it.
        defer_resolution,
        /// Commit it by the unpinned-dispatch rule.
        commit,
        /// The record places a function into a value as data. A containing
        /// record, tuple, list, tag, or nominal can cross a module boundary
        /// before that function is requested at a concrete type, so an
        /// obligation reachable through the function's own callable type
        /// resolves from that eventual request instead of committing to
        /// `unreachable`.
        from_callable,
    };

    /// Resolve one scheme-use record's obligations (in the scheme's canonical
    /// order) into a contiguous `evidence_refs` range, and record the
    /// substitution the instantiation applied to the scheme.
    fn evidenceRefsForRecord(self: *EvidencePass, record_idx: u32, unpinned: UnpinnedRecordEvidence) Allocator.Error!?RecordSiteSpans {
        const module_env = self.module.moduleEnvConst();
        const record = module_env.scheme_uses.items.items[record_idx];
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
            checkedModuleInvariant("where-method callable relation reached scheme-use evidence emission", .{});
        }
        const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
        // Resolution against an enclosing evidence chain depends on that
        // chain, so only chain-free resolutions are shared.
        const key: ?RecordSubstitutionKey = if (evidenceChainIsEmpty(self.current_chain)) .{
            .scheme_root = record.scheme_root,
            .pairs_start = record.pairs_start,
            .pairs_len = record.pairs_len,
            .unpinned = unpinned,
        } else null;
        if (key) |shared| if (self.record_spans_by_substitution.get(shared)) |spans| return spans;

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try self.enumerateParams(@fromBackingInt(@intCast(record.scheme_root)), &params);

        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, params.items.len);

        for (params.items) |param| {
            const evidence = switch (unpinned) {
                .defer_resolution => (try self.evidenceForRecordParam(pairs, param, .defer_resolution)) orelse return null,
                .commit => (try self.evidenceForRecordParam(pairs, param, .commit)).?,
                .from_callable => try self.storedFunctionEvidenceForRecordParam(pairs, param),
            };
            entries.appendAssumeCapacity(evidence);
        }

        // A value use instantiates the referenced scheme; a nested-function use
        // instantiates the stored expression's own scheme for the value that
        // stores it. Either way the pairs name each quantified variable's copy.
        const spans: RecordSiteSpans = .{
            .refs = try self.appendEvidenceRefs(entries.items),
            .subst = try self.appendSiteSubstitution(@fromBackingInt(@intCast(record.scheme_root)), pairs, &.{}),
        };
        if (key) |shared| try self.record_spans_by_substitution.put(self.allocator, shared, spans);
        return spans;
    }

    fn evidenceForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
        policy: UnpinnedPolicy,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const context = try self.evidenceContextForRecordParam(pairs, param);
        const resolution = (try self.resolveObligation(context.var_, context.dispatcher_ty, context.method, context.structural_kind, context.fresh_fn_var, context.literal_kind, self.current_chain, policy)) orelse return null;
        var evidence = self.evidenceFromResolution(context, resolution);
        if (param.callable_contracts.len != 0) {
            // A non-structural method on one settled receiver has one target.
            // Its schema proves when every independent callable can derive its
            // own nested evidence. Preserve any exact per-call rejection even
            // on that path, using the same rejection authority as resolveObligation.
            if (!try self.evidenceNeedsCallableContract(evidence) and self.structuralKindForMethodIdent(param.constraint.fn_name) == null) {
                var rejected = false;
                for (param.callable_contracts) |constraint| {
                    const root = self.types.resolveVar(constraint.fn_var).var_;
                    const fresh = self.pairForResolved(pairs, root) orelse root;
                    if (self.types.varStaticDispatchRejected(fresh)) {
                        rejected = true;
                        break;
                    }
                }
                if (!rejected) return evidence;
            }
            // A contract parameter carries no contracts of its own, so this
            // descends one level.
            var contracts = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer contracts.deinit(self.allocator);
            for (param.callable_contracts) |constraint| {
                var contract_param = param;
                contract_param.constraint = constraint;
                contract_param.callable_contracts = &.{};
                const contract = (try self.evidenceForRecordParam(pairs, contract_param, policy)) orelse return null;
                try contracts.append(self.allocator, contract);
            }
            var needs_contract = try self.evidenceNeedsCallableContract(evidence);
            for (contracts.items) |contract| needs_contract = needs_contract or try self.evidenceNeedsCallableContract(contract);
            if (needs_contract) evidence.callable_contracts = try self.internCallableContracts(contracts.items);
        }
        return evidence;
    }

    fn evidenceContextForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
    ) Allocator.Error!EvidenceContext {
        const dispatcher_root = self.types.resolveVar(param.dispatcher_var).var_;
        const fresh_dispatcher = self.pairForResolved(pairs, dispatcher_root) orelse param.dispatcher_var;
        const fn_root = self.types.resolveVar(param.constraint.fn_var).var_;
        // A monomorphic receiver can share its root while the callable's
        // encoding or result parameters are copied. Consume both recorded
        // sides of the relation independently. The instantiator pairs every
        // callable it copies, so an unpaired callable is shared with the use,
        // exactly like an unpaired receiver.
        const fresh_fn = self.pairForResolved(pairs, fn_root) orelse param.constraint.fn_var;
        return try self.evidenceContext(param, fresh_dispatcher, fresh_fn);
    }

    /// One obligation of an instantiated scheme, ready to resolve.
    const EvidenceContext = struct {
        param: EvidenceParam,
        var_: Var,
        fresh_fn_var: ?Var,
        /// The kind of source literal the obligation converts, if any.
        literal_kind: ?LiteralKind,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        dispatcher_ty: CheckedTypeId,
    };

    fn evidenceContext(self: *EvidencePass, param: EvidenceParam, var_: Var, fresh_fn_var: ?Var) Allocator.Error!EvidenceContext {
        const idents = self.module.identStoreConst();
        return .{
            .param = param,
            .var_ = var_,
            .fresh_fn_var = fresh_fn_var,
            .literal_kind = param.constraint.origin.literalKind(),
            .method = try self.names.internMethodIdent(idents, param.constraint.fn_name),
            .structural_kind = self.structuralKindForMethodIdent(param.constraint.fn_name),
            .dispatcher_ty = self.checked_types.rootForSourceVar(self.module, var_) orelse
                checkedModuleInvariant("checked scheme evidence dispatcher type was not published", .{}),
        };
    }

    /// Callable-only target schemas need no per-use payload. Forwarded,
    /// structural, rejected and unreachable entries retain their exact proof.
    fn evidenceNeedsCallableContract(self: *EvidencePass, evidence: static_dispatch.CheckedEvidence) Allocator.Error!bool {
        return switch (evidence.resolution) {
            .direct => |id| switch (self.evidence_nodes.items[id.index].target.kind) {
                .procedure => blk: {
                    const target = self.evidence_nodes.items[id.index].target;
                    const schema = try self.procedureEvidenceView(target);
                    break :blk switch (static_dispatch.procedureEvidenceSchema(schema.params)) {
                        .none => !schema.callable_determines_scheme,
                        .from_callable => procedureHasCodecEvidenceParam(schema) or !schema.callable_determines_scheme,
                        .from_target, .requires_record => true,
                    };
                },
                .local_proc, .structural => true,
            },
            .constraint, .structural, .from_callable, .from_scheme, .checked_error, .unreachable_value => true,
        };
    }

    /// A callable-derived codec requirement resolves to a structural parser or
    /// encoder only through a checked generated-codec derivation, which a
    /// per-use callable cannot derive after checking.
    fn procedureHasCodecEvidenceParam(schema: SchemaView) bool {
        for (schema.params) |param| {
            const structural = param.structural orelse continue;
            switch (structural) {
                .parser, .encoder => return true,
                .equality, .hash, .map, .map_effectful => {},
            }
        }
        return false;
    }

    /// Intern only sparse side vectors. Children have already been interned,
    /// so their spans are canonical and equality needs no recursive traversal.
    fn internCallableContracts(self: *EvidencePass, entries: []const static_dispatch.CheckedEvidence) Allocator.Error!static_dispatch.EvidenceSpan {
        var hasher = std.hash.Wyhash.init(0);
        for (entries) |entry| std.hash.autoHash(&hasher, entry);
        const bucket_key = hasher.final();
        const row_index = std.math.cast(u32, self.callable_contracts.items.len) orelse return error.OutOfMemory;
        if (row_index == CallableContractRow.none) return error.OutOfMemory;
        try self.callable_contracts.ensureUnusedCapacity(self.allocator, 1);
        const bucket = try self.callable_contract_buckets.getOrPut(self.allocator, bucket_key);
        const newest = if (bucket.found_existing) bucket.value_ptr.* else CallableContractRow.none;
        var cursor = newest;
        while (cursor != CallableContractRow.none) {
            const row = self.callable_contracts.items[cursor];
            cursor = row.next;
            if (row.span.len != entries.len) continue;
            const existing = self.evidence_refs.items[row.span.start..][0..row.span.len];
            var equal = true;
            for (existing, entries) |left, right| {
                if (!std.meta.eql(left, right)) {
                    equal = false;
                    break;
                }
            }
            if (equal) return row.span;
        }
        const span = self.appendEvidenceRefs(entries) catch |err| {
            if (!bucket.found_existing) _ = self.callable_contract_buckets.remove(bucket_key);
            return err;
        };
        self.callable_contracts.appendAssumeCapacity(.{ .span = span, .next = newest });
        bucket.value_ptr.* = row_index;
        return span;
    }

    /// Resolve one obligation of an instantiated scheme: the fresh dispatcher
    /// var either settled to a concrete type (direct or structural evidence),
    /// or is one of the *enclosing* callable's params (forwarded). The
    /// enclosing params here are the ones of the template whose body contains
    /// the instantiation site; the caller of `siteEvidence`/nested-node
    /// construction passes them contextually via `current_site_params`.
    fn evidenceForVar(
        self: *EvidencePass,
        param: EvidenceParam,
        var_: Var,
        fresh_fn_var: ?Var,
        policy: UnpinnedPolicy,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const context = try self.evidenceContext(param, var_, fresh_fn_var);
        const resolution = (try self.resolveObligation(var_, context.dispatcher_ty, context.method, context.structural_kind, fresh_fn_var, context.literal_kind, self.current_chain, policy)) orelse return null;
        return self.evidenceFromResolution(context, resolution);
    }

    fn evidenceFromResolution(
        self: *EvidencePass,
        context: EvidenceContext,
        resolution: static_dispatch.CheckedCallResolution,
    ) static_dispatch.CheckedEvidence {
        const param = context.param;
        const var_ = context.var_;
        const fresh_fn_var = context.fresh_fn_var;
        const dispatcher_ty = context.dispatcher_ty;
        return .{
            .dispatcher_ty = dispatcher_ty,
            .resolution = switch (resolution) {
                .direct_pending => |node| .{ .direct = node },
                .direct_closed, .direct_parametric => checkedModuleInvariant("call resolution was finalized before evidence publication completed", .{}),
                .evidence_dependent => |dependent| .{ .constraint = .{
                    .scheme_param = dependent.scheme_param,
                    .index = dependent.index,
                    .independent_callable = dependent.independent_callable,
                    .reuse_slot_nested_evidence = dependent.reuse_slot_nested_evidence,
                    .callable_contract = dependent.callable_contract,
                } },
                .structural => |kind| blk: {
                    const callable_var = self.codecRelationCallable(fresh_fn_var orelse param.constraint.fn_var);
                    const callable_ty = self.checked_types.rootForSourceVar(self.module, callable_var) orelse
                        checkedModuleInvariant("checked structural evidence callable type was not published", .{});
                    break :blk .{ .structural = .{
                        .derivation = kind,
                        .dispatcher_ty = dispatcher_ty,
                        .callable_ty = callable_ty,
                        .generated_codec_derivation = switch (kind) {
                            .parser => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .parser,
                            ) orelse checkedModuleInvariant(
                                "structural parser evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .encoder => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .encoder,
                            ) orelse checkedModuleInvariant(
                                "structural encoder evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .equality, .hash, .map, .map_effectful => null,
                        },
                    } };
                },
                .checked_error => blk: {
                    if (@import("builtin").mode == .debug) {
                        std.log.scoped(.checked_evidence).debug("evidence entry checked_error: method={s} content={s}", .{
                            self.module.identStoreConst().getText(param.constraint.fn_name),
                            @tagName(self.types.resolveVar(var_).desc.content),
                        });
                    }
                    break :blk .checked_error;
                },
                .@"unreachable" => .unreachable_value,
            },
        };
    }

    /// The derived-structural kind a constraint method admits, if any.
    /// Ident-keyed view of `static_dispatch.structural_method_kinds`: each
    /// table entry's name doubles as the matching `CommonIdents` field.
    fn structuralKindForMethodIdent(self: *EvidencePass, fn_name: anytype) ?static_dispatch.StructuralKind {
        const common = self.module.commonIdents();
        inline for (static_dispatch.structural_method_kinds) |entry| {
            if (fn_name.eql(@field(common, entry.common_ident))) return entry.kind;
        }
        return null;
    }

    fn appendEvidenceRefs(self: *EvidencePass, entries: []const static_dispatch.CheckedEvidence) Allocator.Error!static_dispatch.EvidenceSpan {
        const start: u32 = @intCast(self.evidence_refs.items.len);
        try self.evidence_refs.appendSlice(self.allocator, entries);
        return .{ .owner = self.owner, .start = start, .len = @intCast(entries.len) };
    }

    /// Publish site evidence for one value reference within the current
    /// template: how each of the referenced scheme's obligations was
    /// satisfied at that use.
    fn emitSiteEvidence(self: *EvidencePass, ref_id: ResolvedValueRefId, chain: []const ChainLevel) Allocator.Error!void {
        const rec = self.resolved_value_refs.records[@backingInt(ref_id)];
        const site_key = @backingInt(rec.expr);
        if (self.site_seen.contains(site_key)) return;

        if (self.module_index.nodeKind(site_key) != .expr) return;
        const source_node = site_key;

        if (self.index.value_use_by_node.get(source_node)) |record_idx| {
            const procedure_value = switch (rec.ref) {
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .promoted_top_level_proc,
                .platform_required_proc,
                => true,
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                .local_proc,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                => false,
            };
            if (procedure_value) {
                try self.emitProcedureValueSiteEvidence(record_idx, site_key, chain);
                return;
            }
            try self.emitSchemeUseSiteEvidence(record_idx, site_key, chain);
            return;
        }

        // A monomorphic local procedure use does not instantiate a scheme, so
        // checking has no SchemeUseRecord for it. Its declaration scope still
        // owns an explicit evidence schema; publish that schema's finished
        // vector from the settled source variables now.
        if (rec.ref == .local_proc) {
            const local = rec.ref.local_proc;
            const scope_id = local.dispatch_scope orelse return;
            const raw_scope = @backingInt(scope_id);
            if (raw_scope >= self.templates.dispatch_scopes.len) {
                checkedModuleInvariant("local procedure use named an evidence scope outside the checked template table", .{});
            }
            const scope = self.templates.dispatch_scopes[raw_scope];
            if (scope.checked_expr != local.expr) {
                checkedModuleInvariant("local procedure use evidence scope belonged to a different checked expression", .{});
            }
            const params = try self.paramsForScope(scope_id, scope.scheme_var);
            if (params.len == 0) return;

            self.current_chain = chain;
            defer self.current_chain = &.{};
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.len);
            for (params) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    .commit,
                )) orelse checkedModuleInvariant(
                    "monomorphic local procedure evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            const span = try self.appendEvidenceRefs(entries.items);
            const subst = try self.appendSiteSubstitution(scope.scheme_var, &.{}, &.{});
            try self.site_seen.put(site_key, {});
            try self.site_evidence.append(self.allocator, .{
                .key = site_key,
                .start = span.start,
                .len = span.len,
                .subst_start = subst.start,
                .subst_len = subst.len,
            });
        }

        // References that do not become specialization edges intentionally
        // have no site evidence. Shared recursive uses are explicit records
        // and therefore returned through the branch above.
        return;
    }

    /// One obligation of a function stored as data (`UnpinnedRecordEvidence.from_callable`).
    fn storedFunctionEvidenceForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
    ) Allocator.Error!static_dispatch.CheckedEvidence {
        if (try self.evidenceForRecordParam(pairs, param, .defer_resolution)) |evidence| return evidence;
        if (param.path_len == 0 or param.source == .constraint_callable or param.source == .erased_row_remainder) {
            return (try self.evidenceForRecordParam(pairs, param, .commit)).?;
        }
        const dispatcher_root = self.types.resolveVar(param.dispatcher_var).var_;
        const dispatcher_var = self.pairForResolved(pairs, dispatcher_root) orelse param.dispatcher_var;
        const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, dispatcher_var) orelse
            checkedModuleInvariant("checked stored-function dispatcher type was not published", .{});
        return .{
            .dispatcher_ty = dispatcher_ty,
            .resolution = .from_callable,
        };
    }

    /// Publish a procedure value's evidence. The value is a function used as
    /// data, so its unpinned callable components resolve from its eventual
    /// request.
    fn emitProcedureValueSiteEvidence(
        self: *EvidencePass,
        record_idx: u32,
        site_key: u32,
        chain: []const ChainLevel,
    ) Allocator.Error!void {
        if (self.site_seen.contains(site_key)) return;

        self.current_chain = chain;
        defer self.current_chain = &.{};
        const spans = (try self.evidenceRefsForRecord(record_idx, .from_callable)).?;
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{
            .key = site_key,
            .start = spans.refs.start,
            .len = spans.refs.len,
            .subst_start = spans.subst.start,
            .subst_len = spans.subst.len,
        });
    }

    fn emitSchemeUseSiteEvidence(
        self: *EvidencePass,
        record_idx: u32,
        site_key: u32,
        chain: []const ChainLevel,
    ) Allocator.Error!void {
        if (self.site_seen.contains(site_key)) return;

        const record = self.module.moduleEnvConst().scheme_uses.items.items[record_idx];
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
            checkedModuleInvariant("where-method callable relation reached a scheme-use evidence site", .{});
        }
        // A value use and a nested-function use can share one node (a
        // referenced value stored in expression position); the value use
        // owns the site's evidence regardless of which record checking
        // appended first.
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) {
            if (self.module_index.nodeKind(site_key) == .expr and self.index.value_use_by_node.contains(site_key)) return;
        }

        self.current_chain = chain;
        defer self.current_chain = &.{};
        // A nested-function use stores the function it constructs into its
        // containing value as data.
        const unpinned: UnpinnedRecordEvidence = switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
            .shared_value_use => .defer_resolution,
            .nested_function_use => .from_callable,
            .value_use, .dispatch_target, .recursive_dispatch_target, .recursive_reference, .recursive_value_reference => .commit,
            .where_method_use => unreachable, // rejected above
        };
        const spans = (try self.evidenceRefsForRecord(record_idx, unpinned)) orelse {
            try self.deferred_use_sites.append(self.allocator, .{ .record_idx = record_idx, .site_key = site_key });
            return;
        };
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{
            .key = site_key,
            .start = spans.refs.start,
            .len = spans.refs.len,
            .subst_start = spans.subst.start,
            .subst_len = spans.subst.len,
            .instance_ty = self.siteInstanceType(record_idx),
        });
    }

    /// The instance a stored nested-function use places into its containing
    /// value, as a `SiteEvidenceEntry.instance_ty`.
    fn siteInstanceType(self: *EvidencePass, record_idx: u32) u32 {
        const record = self.module.moduleEnvConst().scheme_uses.items.items[record_idx];
        if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) {
            return static_dispatch.SiteEvidenceEntry.no_site_instance;
        }
        const instance = self.checked_types.rootForSourceVar(self.module, @fromBackingInt(@intCast(record.slot_data))) orelse
            checkedModuleInvariant("stored nested function instance type was not published", .{});
        return @backingInt(instance);
    }

    /// Publish the complete construction recipe for a generalized nested
    /// procedure that checking did not instantiate through a SchemeUseRecord.
    /// Path-bearing parameters explicitly project from the eventual callable;
    /// pathless parameters are resolved now against the enclosing checked
    /// evidence chain.
    fn emitScopeConstructionEvidence(
        self: *EvidencePass,
        site: CollectedScopeConstructionSite,
        template_level: ChainLevel,
    ) Allocator.Error!void {
        const site_key = @backingInt(site.checked_expr);
        if (self.site_seen.contains(site_key)) return;

        const raw_scope = @backingInt(site.scope);
        if (raw_scope >= self.templates.dispatch_scopes.len) {
            checkedModuleInvariant("nested procedure construction named an unknown checked scope", .{});
        }
        const scope = self.templates.dispatch_scopes[raw_scope];
        if (scope.checked_expr != site.checked_expr) {
            checkedModuleInvariant("nested procedure construction scope belonged to a different checked expression", .{});
        }

        const parent_scope: DispatchScope = if (scope.parent) |parent|
            .{ .generalized = parent }
        else
            .root;
        self.current_chain = try self.chainFor(parent_scope, template_level);
        defer self.current_chain = &.{};

        const scope_params = try self.paramsForScope(site.scope, scope.scheme_var);
        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, scope_params.len);
        for (scope_params) |param| {
            if ((param.path_len > 0 and param.source != .constraint_callable) or param.source == .scheme_requirement) {
                // A callable-derived scope's type can also reach a receiver
                // an enclosing scope binds, which forwards to that scope.
                if (param.source != .scheme_requirement) {
                    if (try self.evidenceForVar(param, param.dispatcher_var, param.constraint.fn_var, .defer_resolution)) |evidence| {
                        entries.appendAssumeCapacity(evidence);
                        continue;
                    }
                }
                const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedModuleInvariant("checked nested-procedure evidence dispatcher type was not published", .{});
                entries.appendAssumeCapacity(.{
                    .dispatcher_ty = dispatcher_ty,
                    .resolution = if (param.source == .scheme_requirement) .from_scheme else .from_callable,
                });
                continue;
            }
            const evidence = (try self.evidenceForVar(
                param,
                param.dispatcher_var,
                param.constraint.fn_var,
                .commit,
            )) orelse checkedModuleInvariant(
                "pathless nested procedure evidence remained unresolved after checking",
                .{},
            );
            entries.appendAssumeCapacity(evidence);
        }

        const span = try self.appendEvidenceRefs(entries.items);
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
    }

    /// The fresh var one scheme-use record's substitution pairs with
    /// `old_root`, comparing RESOLVED roots on both sides: finalization after
    /// record time can move the pristine var's root. `pairs` is that record's
    /// range of `scheme_use_pairs`.
    fn pairForResolved(self: *EvidencePass, pairs: []const ModuleEnv.SchemeUsePair, old_root: Var) ?Var {
        if (pairs.len == 0) return null;
        const all_pairs = self.module.moduleEnvConst().scheme_use_pairs.items.items;
        const offset = @intFromPtr(pairs.ptr) - @intFromPtr(all_pairs.ptr);
        std.debug.assert(offset % @sizeOf(ModuleEnv.SchemeUsePair) == 0);
        const pairs_start: u32 = @intCast(offset / @sizeOf(ModuleEnv.SchemeUsePair));
        std.debug.assert(pairs_start + pairs.len <= all_pairs.len);
        return self.index.fresh_by_pair_root.get(.{
            .pairs_start = pairs_start,
            .pairs_len = @intCast(pairs.len),
            .old_root = old_root,
        });
    }
};

test "procedure evidence schema positively classifies callable paths and pathless requirements" {
    var params = [_]static_dispatch.EvidenceParamRecord{
        .{ .method = @fromBackingInt(@intCast(1)), .dispatcher_ty = @fromBackingInt(@intCast(1)), .callable_ty = @fromBackingInt(@intCast(3)), .slot = 0, .structural = .encoder, .path = .{ .last = 0, .len = 1 } },
        .{ .method = @fromBackingInt(@intCast(2)), .dispatcher_ty = @fromBackingInt(@intCast(2)), .callable_ty = @fromBackingInt(@intCast(4)), .slot = 1, .path = .{ .last = 1, .len = 1 } },
    };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        static_dispatch.procedureEvidenceSchema(&params),
    );

    var pathless_params = params;
    pathless_params[1].path = .{};
    pathless_params[1].source = .erased_row_remainder;
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&pathless_params),
    );

    var target_params = [_]static_dispatch.EvidenceParamRecord{params[0]};
    target_params[0].source = .scheme_requirement;
    target_params[0].path = .{};
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_target,
        static_dispatch.procedureEvidenceSchema(&target_params),
    );

    target_params[0].path = .{ .last = 0, .len = 1 };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&target_params),
    );

    var mixed_params = [_]static_dispatch.EvidenceParamRecord{ params[0], params[1] };
    mixed_params[1].source = .scheme_requirement;
    mixed_params[1].path = .{};
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&mixed_params),
    );

    var defaulted_pathless_params = pathless_params;
    defaulted_pathless_params[1].source = .{ .explicit_default = .mono_specialization };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        static_dispatch.procedureEvidenceSchema(&defaulted_pathless_params),
    );

    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.none,
        static_dispatch.procedureEvidenceSchema(&.{}),
    );
}

fn siteEvidenceLessThan(_: void, a: static_dispatch.SiteEvidenceEntry, b: static_dispatch.SiteEvidenceEntry) bool {
    return a.key < b.key;
}

/// A template schema with no scheme: the schema of a template appended
/// after the module's dispatch sites were collected.
pub const empty_scheme_analysis: SchemeAnalysis = .{
    .view = .{},
    .chain = null,
};

/// The dispatch resolution of a template whose body reaches no dispatch
/// site: one appended after the module's dispatch sites were collected.
pub const empty_template_dispatch: TemplateDispatch = .{
    .pool = .{ .owner = .module },
    .site_evidence = &.{},
    .plans = &.{},
    .iterator_plans = &.{},
    .root_evidence = .{},
    .deferred_sites = &.{},
};

/// The relations of a template whose body reaches no dispatch plan.
pub const empty_template_relations: TemplateDispatchRelations = .{
    .direct = &.{},
    .relations = &.{},
    .relation_scopes = &.{},
    .relation_kinds = &.{},
};

/// The module-wide indexes dispatch resolution reads.
pub fn computeDispatchIndex(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*DispatchIndex {
    const source = dispatch.source;
    const index = try allocator.create(DispatchIndex);
    index.* = .{
        .allocator = allocator,
        .template_scheme_vars = collections.DenseMap(u32, Var).init(allocator),
        .value_use_by_node = collections.DenseMap(u32, u32).init(allocator),
        .target_by_fn_var = collections.DenseMap(u32, u32).init(allocator),
        .generated_codec_by_source = collections.DenseMap(Var, EvidencePass.GeneratedCodecsByKind).init(allocator),
        .where_method_use_by_fn_var = collections.DenseMap(u32, u32).init(allocator),
        .where_method_use_by_fn_root = collections.DenseMap(Var, u32).init(allocator),
        .local_value_scheme_by_var = collections.DenseMap(u32, u32).init(allocator),
        .value_use_record_by_pattern = collections.DenseMap(u32, u32).init(allocator),
        .codec_instance_by_template = collections.DenseMap(Var, Var).init(allocator),
    };
    errdefer index.destroy();
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    {
        var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
        defer pass.deinit();
        try pass.buildIndexes(index);
    }
    try fillDispatchReach(allocator, source, index);
    return index;
}

/// Record which templates reach each plan, iterator plan and use site.
fn fillDispatchReach(allocator: Allocator, source: DispatchSource, index: *DispatchIndex) Allocator.Error!void {
    const templates = source.templates;
    const sites = &templates.dispatch_sites;
    const walked = sites.walkedTemplateCount();

    const plan_reach = try allocator.alloc(store_serialize.Span, source.plans.plans.len);
    index.plan_reach = plan_reach;
    @memset(plan_reach, .{});
    const iterator_reach = try allocator.alloc(store_serialize.Span, source.plans.iterator_for_plans.len);
    index.iterator_reach = iterator_reach;
    @memset(iterator_reach, .{});

    // Count each plan's references, then place them in template order with
    // the defaulted-field expressions last.
    for (0..walked + 1) |t| {
        const plan_span = if (t < walked) dispatchPlanSpan(templates, t) else sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[plan_span.start..][0..plan_span.len]) |plan| plan_reach[@backingInt(plan)].len += 1;
        const iterator_span = sites.iteratorSpan(t);
        for (sites.iterator_refs[iterator_span.start..][0..iterator_span.len]) |plan| iterator_reach[@backingInt(plan)].len += 1;
    }
    index.plan_sites = try allocator.alloc(DispatchIndex.PlanReach, assignReachStarts(plan_reach));
    index.iterator_sites = try allocator.alloc(DispatchIndex.PlanReach, assignReachStarts(iterator_reach));
    for (plan_reach) |*span| span.len = 0;
    for (iterator_reach) |*span| span.len = 0;
    for (0..walked + 1) |t| {
        const template: ?u32 = if (t < walked) @intCast(t) else null;
        const plan_span = if (t < walked) dispatchPlanSpan(templates, t) else sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[plan_span.start..][0..plan_span.len], templates.dispatch_ref_scopes[plan_span.start..][0..plan_span.len]) |plan, scope| {
            const span = &plan_reach[@backingInt(plan)];
            index.plan_sites[span.start + span.len] = .{ .template = template, .scope = scope };
            span.len += 1;
        }
        const iterator_span = sites.iteratorSpan(t);
        for (sites.iterator_refs[iterator_span.start..][0..iterator_span.len], sites.iterator_scopes[iterator_span.start..][0..iterator_span.len]) |plan, scope| {
            const span = &iterator_reach[@backingInt(plan)];
            index.iterator_sites[span.start + span.len] = .{ .template = template, .scope = scope };
            span.len += 1;
        }
    }

    var site_reach = std.ArrayList(DispatchIndex.SiteReach).empty;
    defer site_reach.deinit(allocator);
    for (0..walked) |t| {
        const template = templates.templates.items[t];
        const template_raw: u32 = @intCast(t);
        const value_refs = source.refs.template_refs[template.resolved_value_refs.start..][0..template.resolved_value_refs.len];
        for (value_refs) |ref_id| {
            try site_reach.append(allocator, .{ .site = @backingInt(source.refs.records[@backingInt(ref_id)].expr), .template = template_raw });
        }
        const scheme_span = sites.schemeUseSpan(t);
        for (sites.scheme_use_sites[scheme_span.start..][0..scheme_span.len]) |site| {
            try site_reach.append(allocator, .{ .site = @backingInt(site.checked_expr), .template = template_raw });
        }
        const scope_span = sites.scopeSiteSpan(t);
        for (sites.scope_sites[scope_span.start..][0..scope_span.len]) |site| {
            try site_reach.append(allocator, .{ .site = @backingInt(site.checked_expr), .template = template_raw });
        }
    }
    std.mem.sort(DispatchIndex.SiteReach, site_reach.items, {}, DispatchIndex.SiteReach.lessThan);
    var len: usize = 0;
    for (site_reach.items) |entry| {
        if (len > 0 and std.meta.eql(site_reach.items[len - 1], entry)) continue;
        site_reach.items[len] = entry;
        len += 1;
    }
    site_reach.shrinkRetainingCapacity(len);
    index.site_reach = try site_reach.toOwnedSlice(allocator);

    var default_sites = std.ArrayList(u32).empty;
    defer default_sites.deinit(allocator);
    const defaults = sites.defaultsIndex();
    const default_value_refs = sites.defaultRefs(TemplateDispatchSites.default_value_refs);
    for (source.refs.template_refs[default_value_refs.start..][0..default_value_refs.len]) |ref_id| {
        try default_sites.append(allocator, @backingInt(source.refs.records[@backingInt(ref_id)].expr));
    }
    const default_scheme_uses = sites.schemeUseSpan(defaults);
    for (sites.scheme_use_sites[default_scheme_uses.start..][0..default_scheme_uses.len]) |site| {
        try default_sites.append(allocator, @backingInt(site.checked_expr));
    }
    const default_scope_sites = sites.scopeSiteSpan(defaults);
    for (sites.scope_sites[default_scope_sites.start..][0..default_scope_sites.len]) |site| {
        try default_sites.append(allocator, @backingInt(site.checked_expr));
    }
    std.mem.sort(u32, default_sites.items, {}, std.sort.asc(u32));
    index.default_sites = try default_sites.toOwnedSlice(allocator);
}

fn dispatchPlanSpan(templates: *const CheckedProcedureTemplateTable, template: usize) store_serialize.Span {
    const span = templates.templates.items[template].static_dispatch_plans;
    return .{ .start = span.start, .len = span.len };
}

/// Turn per-item counts into consecutive ranges; returns the total.
fn assignReachStarts(spans: []store_serialize.Span) usize {
    var next: u32 = 0;
    for (spans) |*span| {
        span.start = next;
        next += span.len;
    }
    return next;
}

/// The schema of procedure template `template`.
pub fn computeTemplateSchema(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*SchemeAnalysis {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    const published = try pass.publishTemplateSchema(source.templates.templates.items[template_id.index()]);
    return try schemeAnalysisFromPass(allocator, &pass, published.vars, published.params, published.callable_determines_scheme, published.chain_root);
}

/// The schema of generalized local scope `scope`.
pub fn computeScopeSchema(allocator: Allocator, dispatch: CheckedDispatch, scope: DispatchScopeId) Allocator.Error!*SchemeAnalysis {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    const scheme_var = source.templates.dispatch_scopes[@backingInt(scope)].scheme_var;
    const published = try pass.publishScheme(scheme_var);
    return try schemeAnalysisFromPass(allocator, &pass, published.vars, published.params, true, scheme_var);
}

/// Copy what `pass` published for one schema into a self-contained result.
fn schemeAnalysisFromPass(
    allocator: Allocator,
    pass: *EvidencePass,
    vars: store_serialize.Span,
    params: store_serialize.Span,
    callable_determines_scheme: bool,
    chain_root: ?Var,
) Allocator.Error!*SchemeAnalysis {
    const result = try allocator.create(SchemeAnalysis);
    errdefer allocator.destroy(result);
    var arena_allocator = std.heap.ArenaAllocator.init(allocator);
    errdefer arena_allocator.deinit();
    const arena = arena_allocator.allocator();
    result.* = .{ .view = .{}, .chain = null };
    result.view = .{
        .vars = try arena.dupe(CheckedTypeId, pass.scheme_vars_pool.items[vars.start..][0..vars.len]),
        .params = try arena.dupe(static_dispatch.EvidenceParamRecord, pass.evidence_params_pool.items[params.start..][0..params.len]),
        .path_nodes = try arena.dupe(static_dispatch.EvidencePathNode, pass.evidence_path_nodes.items),
        .param_callables = try arena.dupe(CheckedTypeId, pass.evidence_param_callables.items),
        .callable_determines_scheme = callable_determines_scheme,
    };
    if (chain_root) |root| {
        const owner = pass.schemeOwner(root);
        result.view.scheme = @backingInt(owner);
        const schema = try pass.schemeSchema(root);
        const enumerated = try arena.alloc(dispatch_evidence.EvidenceParam, schema.params.len);
        for (enumerated, schema.params) |*copy, param| {
            copy.* = param;
            copy.callable_contracts = try arena.dupe(types.StaticDispatchConstraint, param.callable_contracts);
        }
        const published = schema.published orelse checkedModuleInvariant("a chain scheme was enumerated without being published", .{});
        result.chain = .{
            .owner = @backingInt(owner),
            .params = enumerated,
            .by_dispatcher = .{ .rows = try arena.dupe(EvidencePass.DispatcherParams.Row, schema.by_dispatcher.rows) },
            .published = try arena.dupe(static_dispatch.EvidenceParamRecord, pass.evidence_params_pool.items[published.params.start..][0..published.params.len]),
        };
    }
    result.arena = arena_allocator.state;
    return result;
}

/// The dispatch resolution of procedure template `template`.
pub fn computeTemplateDispatch(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*TemplateDispatch {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, static_dispatch.EvidenceOwner.forTemplate(template_id), index);
    defer pass.deinit();
    const root_evidence = try pass.resolveTemplate(template_id);
    try specializeResolvedPlans(allocator, &pass, index);

    const result = try allocator.create(TemplateDispatch);
    errdefer allocator.destroy(result);
    var pool = try pass.takePool();
    errdefer pool.deinit(allocator);
    const site_evidence = try pass.takeSiteEvidence();
    errdefer allocator.free(site_evidence);
    const plans = try pass.takePlanResults();
    errdefer allocator.free(plans);
    const iterator_plans = try pass.takeIteratorResults();
    errdefer allocator.free(iterator_plans);
    var deferred = std.ArrayList(DeferredUseSite).empty;
    defer deferred.deinit(allocator);
    for (pass.deferred_use_sites.items) |site| {
        if (pass.site_seen.contains(site.site_key)) continue;
        try deferred.append(allocator, site);
    }
    result.* = .{
        .pool = pool,
        .site_evidence = site_evidence,
        .plans = plans,
        .iterator_plans = iterator_plans,
        .root_evidence = root_evidence,
        .deferred_sites = try deferred.toOwnedSlice(allocator),
    };
    return result;
}

/// The plans, iterator plans and use sites some template resolved.
const ModuleBoundSet = struct {
    plans: collections.DenseMap(u32, void),
    iterator_plans: collections.DenseMap(u32, void),
    sites: collections.DenseMap(u32, void),

    fn deinit(self: *ModuleBoundSet) void {
        self.plans.deinit();
        self.iterator_plans.deinit();
        self.sites.deinit();
    }
};

/// The module's dispatch resolution of what no template resolves.
pub fn computeModuleDispatch(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*ModuleDispatch {
    const source = dispatch.source;
    const analyses = source.analyses;
    const index = try analyses.dispatchIndex(dispatch);

    var bound = ModuleBoundSet{
        .plans = collections.DenseMap(u32, void).init(allocator),
        .iterator_plans = collections.DenseMap(u32, void).init(allocator),
        .sites = collections.DenseMap(u32, void).init(allocator),
    };
    defer bound.deinit();
    var deferred = std.ArrayList(DeferredUseSite).empty;
    defer deferred.deinit(allocator);
    for (0..source.templates.dispatch_sites.walkedTemplateCount()) |raw| {
        const resolved = try analyses.templateDispatch(dispatch, @fromBackingInt(@intCast(raw)));
        for (resolved.plans) |entry| try bound.plans.put(entry.plan, {});
        for (resolved.iterator_plans) |entry| try bound.iterator_plans.put(entry.plan, {});
        for (resolved.site_evidence) |entry| try bound.sites.put(entry.key, {});
        try deferred.appendSlice(allocator, resolved.deferred_sites);
    }

    const codec_derivations = try allocator.dupe(static_dispatch.GeneratedCodecDerivation, source.plans.recorded_codec_derivations);
    errdefer allocator.free(codec_derivations);
    const codec_calls = try allocator.dupe(static_dispatch.GeneratedCodecCall, source.plans.recorded_codec_calls);
    errdefer allocator.free(codec_calls);

    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    try pass.resolveModule(&bound, deferred.items, codec_calls);
    try specializeResolvedPlans(allocator, &pass, index);

    const result = try allocator.create(ModuleDispatch);
    errdefer allocator.destroy(result);
    var pool = try pass.takePool();
    errdefer pool.deinit(allocator);
    const site_evidence = try pass.takeSiteEvidence();
    errdefer allocator.free(site_evidence);
    const plans = try pass.takePlanResults();
    errdefer allocator.free(plans);
    const iterator_plans = try pass.takeIteratorResults();
    errdefer allocator.free(iterator_plans);
    result.* = .{
        .pool = pool,
        .site_evidence = site_evidence,
        .plans = plans,
        .iterator_plans = iterator_plans,
        .codec_derivations = codec_derivations,
        .codec_calls = codec_calls,
    };
    var table = result.codecTable();
    try @import("codec_identity.zig").intern(allocator, source.types.store.view(), &table);
    try @import("codec_identity.zig").digestContents(allocator, source.key.digest(), source.types.store, source.names, &table);
    if (builtin.mode == .debug) try pass.debugVerifyGeneratedCodecRoleAgreement(&table);
    return result;
}

/// An app's root evidence for each of its platform requirement solutions.
pub fn computePlatformRequirementRootEvidence(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*PlatformRequirementRootEvidence {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .platform_requirements, index);
    defer pass.deinit();
    const spans = try pass.resolvePlatformRequirementRoots();
    errdefer allocator.free(spans);
    const result = try allocator.create(PlatformRequirementRootEvidence);
    errdefer allocator.destroy(result);
    result.* = .{ .pool = try pass.takePool(), .spans = spans };
    return result;
}

/// How a template's plans relate to its specialization: a plan whose
/// resolution needs a relation (`checkedDispatchPlanNeedsRelation`) keeps
/// its scope and relation kind; every other plan is a direct call.
pub fn computeTemplateDispatchRelations(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*TemplateDispatchRelations {
    const templates = dispatch.source.templates;
    const span = dispatchPlanSpan(templates, template_id.index());
    var direct = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    defer direct.deinit(allocator);
    var relations = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    defer relations.deinit(allocator);
    var relation_scopes = std.ArrayList(DispatchScope).empty;
    defer relation_scopes.deinit(allocator);
    var relation_kinds = std.ArrayList(DispatchRelationKind).empty;
    defer relation_kinds.deinit(allocator);
    const refs = templates.dispatch_plan_refs[span.start..][0..span.len];
    const scopes = templates.dispatch_ref_scopes[span.start..][0..span.len];
    const kinds = templates.dispatch_relation_kinds[span.start..][0..span.len];
    for (refs, scopes, kinds) |plan_id, scope, kind| {
        const plan = try dispatch.plan(plan_id);
        if (try checkedDispatchPlanNeedsRelation(dispatch, plan)) {
            try relations.append(allocator, plan_id);
            try relation_scopes.append(allocator, scope);
            try relation_kinds.append(allocator, kind);
        } else {
            try direct.append(allocator, plan_id);
        }
    }
    const result = try allocator.create(TemplateDispatchRelations);
    errdefer allocator.destroy(result);
    const direct_slice = try direct.toOwnedSlice(allocator);
    errdefer allocator.free(direct_slice);
    const relations_slice = try relations.toOwnedSlice(allocator);
    errdefer allocator.free(relations_slice);
    const scopes_slice = try relation_scopes.toOwnedSlice(allocator);
    errdefer allocator.free(scopes_slice);
    result.* = .{
        .direct = direct_slice,
        .relations = relations_slice,
        .relation_scopes = scopes_slice,
        .relation_kinds = try relation_kinds.toOwnedSlice(allocator),
    };
    return result;
}

/// Specialize each direct call the pass resolved against its target and
/// classify it `direct_closed` or `direct_parametric`, against every
/// scheme context that references the plan.
///
/// Specialization creates types in the module's store, which other threads
/// read once the module is opened, so it runs under the store's creation
/// lock (`CheckedTypeStore.beginCreation`). It reads the nominal
/// representations of the module's own types and of the types it projects
/// from each target's module, so their interface capabilities are demanded
/// before the lock is taken; classification reads only complete types and
/// runs after the lock is released.
fn specializeResolvedPlans(allocator: Allocator, pass: *EvidencePass, index: *const DispatchIndex) Allocator.Error!void {
    const source = pass.dispatch.source;
    const store = source.types.store;
    // A store gets its capability source when its module is opened;
    // before that, nothing has the module's capabilities to read.
    if (store.capability_source != null) _ = try store.view().interfaceCapabilities();
    const owner = source.key.digest();
    for (pass.plan_results.items) |entry| switch (entry.resolution.resolution) {
        .direct_pending => |node_id| try demandTargetCapabilities(pass, owner, node_id),
        .direct_closed, .direct_parametric => checkedModuleInvariant("static dispatch plan was finalized more than once", .{}),
        .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
    };
    for (pass.iterator_results.items) |entry| {
        inline for (.{ entry.resolution.iter, entry.resolution.next }) |call| switch (call) {
            .direct_pending => |node_id| try demandTargetCapabilities(pass, owner, node_id),
            .direct_closed, .direct_parametric => checkedModuleInvariant("iterator dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        };
    }

    const evidence_closure = try allocator.alloc(DirectEvidenceClosure, pass.evidence_nodes.items.len);
    defer allocator.free(evidence_closure);
    @memset(evidence_closure, .unknown);
    var specializer = ResolvedDispatchCallableSpecializer{
        .allocator = allocator,
        .names = source.names,
        .store = source.types.store,
        .owner = source.key.digest(),
        .imports = pass.import_views,
        .evidence_nodes = pass.evidence_nodes.items,
        .evidence_refs = pass.evidence_refs.items,
        .evidence_closure = evidence_closure,
        .identity_index = EnclosingIdentityIndex.init(allocator, source.names, source.types.store),
    };
    defer specializer.deinit();
    {
        store.beginCreation(source.analyses.io);
        errdefer store.endCreation(source.analyses.io);
        for (pass.plan_results.items) |*entry| try specializer.specializePlan(&entry.resolution);
        for (pass.iterator_results.items) |*entry| try specializer.specializeIteratorPlan(&entry.resolution);
        try store.finishCreation(allocator, source.analyses.io);
    }
    var sites = std.ArrayList(EnclosingDispatchSite).empty;
    defer sites.deinit(allocator);
    for (pass.plan_results.items) |*entry| {
        try enclosingSitesFor(allocator, source.templates, index.planSites(@fromBackingInt(entry.plan)), &sites);
        try specializer.classifyPlan(&entry.resolution, .{
            .index = &specializer.identity_index,
            .sites = sites.items,
            .scopes = source.templates.dispatch_scopes,
        });
    }
    for (pass.iterator_results.items) |*entry| {
        try enclosingSitesFor(allocator, source.templates, index.iteratorSites(@fromBackingInt(entry.plan)), &sites);
        try specializer.classifyIteratorPlan(&entry.resolution, .{
            .index = &specializer.identity_index,
            .sites = sites.items,
            .scopes = source.templates.dispatch_scopes,
        });
    }
}

/// Demand the interface capabilities of the module whose callable the
/// resolved target `node_id` names, when that module is not `owner`.
fn demandTargetCapabilities(pass: *EvidencePass, owner: ModuleId, node_id: static_dispatch.EvidenceNodeId) Allocator.Error!void {
    const target = pass.evidence_nodes.items[node_id.index].target;
    const target_key = switch (target.kind) {
        .local_proc => return,
        .structural => checkedModuleInvariant("structural method registry result was published as a direct callable target", .{}),
        .procedure => |procedure| procedure.template.module,
    };
    if (target_key.eql(owner)) return;
    const imported = pass.import_views.viewForKey(target_key) orelse
        checkedModuleInvariant("resolved dispatch target module was not among the modules dispatch resolution reads", .{});
    _ = try imported.checked_types.interfaceCapabilities();
}

fn enclosingSitesFor(
    allocator: Allocator,
    templates: *const CheckedProcedureTemplateTable,
    reach: []const DispatchIndex.PlanReach,
    out: *std.ArrayList(EnclosingDispatchSite),
) Allocator.Error!void {
    out.clearRetainingCapacity();
    for (reach) |entry| {
        try out.append(allocator, .{
            .template_root = if (entry.template) |template| templates.templates.items[template].checked_fn_root else null,
            .scope = entry.scope,
        });
    }
}
fn sealConstEvalTemplatesForRoots(
    const_templates: *ConstTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    entry_wrappers: *const EntryWrapperTable,
    checked_procedure_templates: *const CheckedProcedureTemplateTable,
    top_level_values: *const TopLevelValueTable,
    hoisted_constants: *const HoistedConstTable,
) void {
    for (compile_time_roots.roots) |root| {
        if (!compileTimeRootHasConstBody(root.kind)) continue;
        const const_ref = switch (root.kind) {
            .constant => blk: {
                const def_idx = switch (root.source) {
                    .def => |def| def,
                    .expr, .statement, .required_binding, .hoisted, .literal => checkedModuleInvariant("constant root source is not a top-level definition", .{}),
                };
                const top_level = top_level_values.lookupByDef(def_idx) orelse {
                    checkedModuleInvariant("constant root has no top-level value entry", .{});
                };
                break :blk switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedModuleInvariant("constant root top-level value is not a ConstRef", .{}),
                };
            },
            .hoisted_constant => blk: {
                const hoisted = hoisted_constants.lookupByRoot(root.id) orelse {
                    checkedModuleInvariant("hoisted constant root has no hoisted const entry", .{});
                };
                break :blk hoisted.const_ref;
            },
            .hoisted_validation,
            .callable_binding,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .repl_expr,
            .literal_argument,
            => checkedModuleInvariant("non-constant root reached const eval template sealing", .{}),
        };
        const wrapper = entryWrapperForRoot(entry_wrappers, root.id);
        const template = checked_procedure_templates.get(wrapper.template.template);
        const_templates.fillEval(const_ref, .{
            .root = root.id,
            .entry_template = wrapper.template,
            .source_scheme = const_ref.source_scheme,
            .resolved_value_refs = template.resolved_value_refs,
            .static_dispatch_plans = template.static_dispatch_plans,
        });
    }
}

const CheckedTemplateRefCollector = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedSourceTypes,
    bodies: CheckedBodies,
    /// Diagnostic errors as the checked tables know them before total dispatch
    /// resolution (`body_analyses.DiagnosticMode.ordinary`).
    diagnostics: *const body_analyses.NodeBits,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    /// Generalized-with-obligations local function decls (checked lambda expr
    /// id -> decl pattern var), prebuilt by the seal pass; entering one pushes
    /// an evidence scope.
    local_schemes: *const collections.DenseMap(u32, Var),
    /// Checked nested function expr -> `SchemeUseRecord` index for the
    /// construction edge that instantiated it.
    nested_function_uses: *const collections.DenseMap(u32, u32),
    /// Checked nested function expr -> its own type variable, for each
    /// function that owns a callable-derived scope
    /// (`collectCallableDerivedSchemes`). A template's root function is never
    /// one: its template's own parameters already answer for its callable.
    callable_derived_schemes: *const collections.DenseMap(u32, Var),
    value_refs: std.ArrayList(ResolvedValueRefId),
    dispatch_refs: std.ArrayList(static_dispatch.StaticDispatchPlanId),
    iterator_refs: std.ArrayList(static_dispatch.IteratorForPlanId),
    /// Scope of each collected ref, parallel to the three ref lists.
    value_ref_scopes: std.ArrayList(DispatchScope),
    dispatch_ref_scopes: std.ArrayList(DispatchScope),
    iterator_ref_scopes: std.ArrayList(DispatchScope),
    scheme_use_sites: std.ArrayList(CollectedSchemeUseSite),
    scheme_use_scopes: std.ArrayList(DispatchScope),
    scope_sites: std.ArrayList(CollectedScopeConstructionSite),
    specialization_relations: std.ArrayList(SpecializationInterfaceRelation),
    specialization_types: std.ArrayList(CheckedTypeId),
    template_root_expr: ?CIR.Expr.Idx = null,
    /// Pooled across templates (ids are global); the stack resets per template.
    scopes: std.ArrayList(DispatchRefScope),
    scope_by_checked_expr: collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    scope_stack: std.ArrayList(DispatchScopeId),
    visited_exprs: collections.DenseMap(CIR.Expr.Idx, void),
    visited_patterns: collections.DenseMap(CIR.Pattern.Idx, void),
    visited_statements: collections.DenseMap(CIR.Statement.Idx, void),
    work: std.ArrayList(Work) = .empty,

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedSourceTypes,
        bodies: CheckedBodies,
        diagnostics: *const body_analyses.NodeBits,
        static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
        local_schemes: *const collections.DenseMap(u32, Var),
        nested_function_uses: *const collections.DenseMap(u32, u32),
        callable_derived_schemes: *const collections.DenseMap(u32, Var),
    ) CheckedTemplateRefCollector {
        return .{
            .allocator = allocator,
            .module = module,
            .checked_types = checked_types,
            .bodies = bodies,
            .diagnostics = diagnostics,
            .static_dispatch_plans = static_dispatch_plans,
            .local_schemes = local_schemes,
            .nested_function_uses = nested_function_uses,
            .callable_derived_schemes = callable_derived_schemes,
            .value_refs = .empty,
            .dispatch_refs = .empty,
            .iterator_refs = .empty,
            .value_ref_scopes = .empty,
            .dispatch_ref_scopes = .empty,
            .iterator_ref_scopes = .empty,
            .scheme_use_sites = .empty,
            .scheme_use_scopes = .empty,
            .scope_sites = .empty,
            .specialization_relations = .empty,
            .specialization_types = .empty,
            .scopes = .empty,
            .scope_by_checked_expr = collections.DenseMap(CIR.Expr.Idx, DispatchScopeId).init(allocator),
            .scope_stack = .empty,
            .visited_exprs = collections.DenseMap(CIR.Expr.Idx, void).init(allocator),
            .visited_patterns = collections.DenseMap(CIR.Pattern.Idx, void).init(allocator),
            .visited_statements = collections.DenseMap(CIR.Statement.Idx, void).init(allocator),
        };
    }

    fn deinit(self: *CheckedTemplateRefCollector) void {
        self.work.deinit(self.allocator);
        self.visited_statements.deinit();
        self.visited_patterns.deinit();
        self.visited_exprs.deinit();
        self.dispatch_refs.deinit(self.allocator);
        self.iterator_refs.deinit(self.allocator);
        self.value_refs.deinit(self.allocator);
        self.value_ref_scopes.deinit(self.allocator);
        self.dispatch_ref_scopes.deinit(self.allocator);
        self.iterator_ref_scopes.deinit(self.allocator);
        self.scheme_use_sites.deinit(self.allocator);
        self.scheme_use_scopes.deinit(self.allocator);
        self.scope_sites.deinit(self.allocator);
        self.specialization_relations.deinit(self.allocator);
        self.specialization_types.deinit(self.allocator);
        self.scopes.deinit(self.allocator);
        self.scope_by_checked_expr.deinit();
        self.scope_stack.deinit(self.allocator);
    }

    fn clear(self: *CheckedTemplateRefCollector) void {
        self.value_refs.clearRetainingCapacity();
        self.dispatch_refs.clearRetainingCapacity();
        self.iterator_refs.clearRetainingCapacity();
        self.value_ref_scopes.clearRetainingCapacity();
        self.dispatch_ref_scopes.clearRetainingCapacity();
        self.iterator_ref_scopes.clearRetainingCapacity();
        self.scheme_use_sites.clearRetainingCapacity();
        self.scheme_use_scopes.clearRetainingCapacity();
        self.scope_sites.clearRetainingCapacity();
        self.specialization_relations.clearRetainingCapacity();
        self.specialization_types.clearRetainingCapacity();
        self.template_root_expr = null;
        // `scopes` pools across templates; only the stack resets.
        self.scope_stack.clearRetainingCapacity();
        self.visited_exprs.clearRetainingCapacity();
        self.visited_patterns.clearRetainingCapacity();
        self.visited_statements.clearRetainingCapacity();
    }

    fn currentScopeId(self: *const CheckedTemplateRefCollector) ?DispatchScopeId {
        if (self.scope_stack.items.len == 0) return null;
        return self.scope_stack.items[self.scope_stack.items.len - 1];
    }

    fn currentScope(self: *const CheckedTemplateRefCollector) DispatchScope {
        return if (self.currentScopeId()) |id| .{ .generalized = id } else .root;
    }

    fn appendValueRef(self: *CheckedTemplateRefCollector, ref_id: ResolvedValueRefId) Allocator.Error!void {
        try self.value_refs.append(self.allocator, ref_id);
        try self.value_ref_scopes.append(self.allocator, self.currentScope());
    }

    fn appendDispatchRef(self: *CheckedTemplateRefCollector, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        try self.dispatch_refs.append(self.allocator, plan_id);
        try self.dispatch_ref_scopes.append(self.allocator, self.currentScope());
    }

    /// The type a lambda's body delivers at its function's return: the
    /// function's result. A body whose type differs is a composed `?`
    /// result whose value crosses the explicit return boundary into the
    /// function's `Try`, so what reaches the return is that `Try`.
    fn lambdaDeliveredReturnType(self: *const CheckedTemplateRefCollector, fn_ty: CheckedTypeId) CheckedTypeId {
        return checkedFunctionPayload(self.checked_types.store, fn_ty, "checked lambda specialization relation").ret;
    }

    fn appendProcedureRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CIR.Expr.Idx,
        fn_ty: CheckedTypeId,
        body_ret_ty: CheckedTypeId,
        owns_scope: bool,
    ) Allocator.Error!void {
        if (self.diagnostics.isSet(@backingInt(expr_id))) return;
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .procedure = .{
                .fn_ty = fn_ty,
                .body_ret_ty = body_ret_ty,
                .owns_scope = owns_scope,
            } },
        });
    }

    fn appendCallRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CIR.Expr.Idx,
    ) Allocator.Error!void {
        if (self.diagnostics.isSet(@backingInt(expr_id))) return;
        const call = self.bodies.exprData(expr_id).call;
        const start: u32 = @intCast(self.specialization_types.items.len);
        try self.specialization_types.ensureUnusedCapacity(self.allocator, call.args.len);
        for (call.args) |arg| {
            self.specialization_types.appendAssumeCapacity(try self.bodies.valueType(arg));
        }
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .call = .{
                .callable_ty = try self.bodies.callFnType(expr_id),
                .callee_ty = try self.bodies.valueType(call.func),
                .ret_ty = try self.bodies.exprType(expr_id),
                .args = .{ .start = start, .len = @intCast(call.args.len) },
                .direct_target = self.bodies.callDirectTarget(expr_id),
            } },
        });
    }

    /// Collect the references reachable from a checked expression. The walk
    /// keeps its own work stack, so body nesting depth never becomes native
    /// call depth; children are pushed in reverse so they are collected in
    /// source order, and post-actions are pushed before them so they run once
    /// every child is collected.
    fn collectExpr(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const base_len = self.work.items.len;
        try self.work.append(self.allocator, .{ .expr = expr_id });
        while (self.work.items.len > base_len) {
            switch (self.work.pop().?) {
                .expr => |id| try self.visitExpr(id),
                .pattern => |id| try self.visitPattern(id),
                .statement => |id| try self.visitStatement(id),
                .generated_interpolation_segments => |id| try self.visitInterpolationChildren(id),
                .literal_pattern => |id| try self.visitLiteralPattern(id),
                .call_relation => |id| try self.appendCallRelation(id),
                .pop_scope => _ = self.scope_stack.pop(),
            }
        }
    }

    const Work = union(enum) {
        expr: CIR.Expr.Idx,
        pattern: CIR.Pattern.Idx,
        statement: CIR.Statement.Idx,
        generated_interpolation_segments: CIR.Expr.Idx,
        /// A custom literal pattern's equality and conversion plans.
        literal_pattern: CIR.Pattern.Idx,
        /// Append a call's relation once its callee and arguments are collected.
        call_relation: CIR.Expr.Idx,
        /// Leave a generalized local function's evidence scope.
        pop_scope,
    };

    /// Children are pushed in source order between `beginChildren` and
    /// `endChildren`, which reverses them on the work stack.
    fn beginChildren(self: *const CheckedTemplateRefCollector) usize {
        return self.work.items.len;
    }

    fn endChildren(self: *CheckedTemplateRefCollector, start: usize) void {
        std.mem.reverse(Work, self.work.items[start..]);
    }

    fn pushChild(self: *CheckedTemplateRefCollector, work: Work) Allocator.Error!void {
        try self.work.append(self.allocator, work);
    }

    fn visitExpr(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const entry = try self.visited_exprs.getOrPut(expr_id);
        if (entry.found_existing) return;

        const raw_expr = @backingInt(expr_id);
        if (self.nested_function_uses.get(raw_expr)) |record_idx| {
            try self.scheme_use_sites.append(self.allocator, .{
                .record_idx = record_idx,
                .checked_expr = expr_id,
            });
            // The construction edge lives in the enclosing scope; the nested
            // function's own evidence scope begins below.
            try self.scheme_use_scopes.append(self.allocator, self.currentScope());
        }

        const local_scheme = self.local_schemes.get(raw_expr) orelse
            if (self.template_root_expr != expr_id) self.callable_derived_schemes.get(raw_expr) else null;
        if (local_scheme) |scheme_var| {
            const parent = self.currentScopeId();
            const scheme_root = self.checked_types.rootForSourceVar(self.module, scheme_var) orelse
                checkedModuleInvariant("generalized local dispatch scope had no checked scheme root", .{});
            const scope_entry = try self.scope_by_checked_expr.getOrPut(expr_id);
            const scope_id = if (scope_entry.found_existing) blk: {
                const existing = self.scopes.items[@backingInt(scope_entry.value_ptr.*)];
                if (existing.parent != parent or existing.scheme_var != scheme_var or existing.scheme_root != scheme_root) {
                    checkedModuleInvariant("generalized local dispatch scope has inconsistent checked ownership", .{});
                }
                break :blk scope_entry.value_ptr.*;
            } else blk: {
                const id: DispatchScopeId = @fromBackingInt(@intCast(@as(u32, @intCast(self.scopes.items.len))));
                scope_entry.value_ptr.* = id;
                try self.scopes.append(self.allocator, .{
                    .parent = parent,
                    .scheme_var = scheme_var,
                    .scheme_root = scheme_root,
                    .checked_expr = expr_id,
                });
                break :blk id;
            };
            try self.scope_sites.append(self.allocator, .{
                .scope = scope_id,
                .checked_expr = expr_id,
            });
            try self.scope_stack.append(self.allocator, scope_id);
        }
        // The scope stays pushed until every child has been collected.
        if (local_scheme != null) try self.work.append(self.allocator, .pop_scope);

        const bodies = self.bodies;
        const data = bodies.exprData(expr_id);
        const expr_ty = try bodies.exprType(expr_id);
        // An erroneous callable publishes no procedure relation, and its type
        // need not be a function.
        const publishes_procedure = !self.diagnostics.isSet(@backingInt(expr_id));
        if (data == .lambda) {
            if (publishes_procedure) try self.appendProcedureRelation(
                expr_id,
                expr_ty,
                self.lambdaDeliveredReturnType(expr_ty),
                self.template_root_expr == expr_id or local_scheme != null,
            );
        } else if (data == .closure) {
            const closure = data.closure;
            const lambda_data = bodies.exprData(closure.lambda);
            if (lambda_data != .lambda) {
                checkedModuleInvariant("checked closure specialization relation did not reference a lambda", .{});
            }
            if (publishes_procedure) try self.appendProcedureRelation(
                expr_id,
                expr_ty,
                self.lambdaDeliveredReturnType(expr_ty),
                self.template_root_expr == expr_id or local_scheme != null,
            );
        }
        const raw = @backingInt(expr_id);
        switch (data) {
            .lookup_local, .lookup_external, .lookup_required => {
                if (bodies.resolvedRef(expr_id)) |ref_id| try self.appendValueRef(ref_id);
            },
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => {
                const id = bodies.dispatchPlan(raw) orelse checkedModuleInvariant("checked dispatch expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
            },
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(expr_id)) {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = interpolation.first });
                for (interpolation.parts) |part| try self.pushChild(.{ .expr = part });
                self.endChildren(children);
            } else {
                const id = bodies.dispatchPlan(raw) orelse checkedModuleInvariant("checked interpolation expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
                const iter_plan = bodies.iteratorForPlan(raw) orelse checkedModuleInvariant("checked interpolation expression reached template closure collection without an iterator plan", .{});
                try self.pushIteratorForPlan(iter_plan);
            },
            .numeral => {
                // Builtin-targeted literals carry no plan (their bits are
                // produced at monotype lowering); only custom conversions do.
                if (bodies.numeralPlan(raw)) |id| {
                    try self.appendDispatchRef(id);
                    try self.pushStaticDispatchPlanArgs(id);
                }
            },
            .str => |segments| if (bodies.quoteIsCustom(raw)) {
                const id = bodies.quotePlan(raw) orelse checkedModuleInvariant("checked from_quote expression reached template closure collection without a dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
            } else {
                const children = self.beginChildren();
                for (segments) |segment| try self.pushChild(.{ .expr = segment });
                self.endChildren(children);
            },
            .list,
            .tuple,
            => |items| {
                const children = self.beginChildren();
                for (items) |item| try self.pushChild(.{ .expr = item });
                self.endChildren(children);
            },
            .match_ => |match| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = match.cond });
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushChild(.{ .pattern = bodies.matchBranchPattern(branch_pattern).pattern });
                    if (branch.guard) |guard| try self.pushChild(.{ .expr = guard });
                    try self.pushChild(.{ .expr = branch.value });
                }
                self.endChildren(children);
            },
            .if_ => |if_| {
                const children = self.beginChildren();
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushChild(.{ .expr = branch.cond });
                    try self.pushChild(.{ .expr = branch.body });
                }
                try self.pushChild(.{ .expr = if_.final_else });
                self.endChildren(children);
            },
            .call => |call| {
                if (bodies.callDirectTarget(expr_id)) |target| try self.appendValueRef(target);
                try self.work.append(self.allocator, .{ .call_relation = expr_id });
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = call.func });
                for (call.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .record => |record| {
                const children = self.beginChildren();
                if (record.ext) |ext| try self.pushChild(.{ .expr = ext });
                for (record.fields) |field| try self.pushChild(.{ .expr = bodies.recordFieldValue(field) });
                self.endChildren(children);
            },
            .block => |block| {
                const children = self.beginChildren();
                for (block.statements) |statement| try self.pushChild(.{ .statement = statement });
                try self.pushChild(.{ .expr = block.final_expr });
                self.endChildren(children);
            },
            .tag => |tag| {
                const children = self.beginChildren();
                for (tag.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .nominal => |nominal| try self.pushChild(.{ .expr = nominal.backing_expr }),
            .closure => |closure| try self.pushChild(.{ .expr = closure.lambda }),
            .lambda => |lambda| {
                const children = self.beginChildren();
                for (lambda.args) |arg| try self.pushChild(.{ .pattern = arg });
                try self.pushChild(.{ .expr = lambda.body });
                self.endChildren(children);
            },
            .binop => |binop| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = binop.lhs });
                try self.pushChild(.{ .expr = binop.rhs });
                self.endChildren(children);
            },
            .unary_minus => |child| try self.pushChild(.{ .expr = child }),
            .field_access => |field| try self.pushChild(.{ .expr = field.receiver }),
            .structural_eq => |eq| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = eq.lhs });
                try self.pushChild(.{ .expr = eq.rhs });
                self.endChildren(children);
            },
            .structural_hash => |h| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = h.value });
                try self.pushChild(.{ .expr = h.hasher });
                self.endChildren(children);
            },
            .tuple_access => |access| try self.pushChild(.{ .expr = access.tuple }),
            .dbg => |child| try self.pushChild(.{ .expr = child }),
            .expect_err => |expect_err| try self.pushChild(.{ .expr = expect_err.expr }),
            .expect => |child| try self.pushChild(.{ .expr = child }),
            .break_ => {},
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushChild(.{ .expr = ret.expr });
            },
            .for_ => |for_| {
                const plan_id = bodies.iteratorForPlan(raw) orelse checkedModuleInvariant("checked for expression reached template closure collection without an iterator-for plan", .{});
                const children = self.beginChildren();
                try self.pushIteratorForPlan(plan_id);
                try self.pushChild(.{ .pattern = for_.pattern });
                try self.pushChild(.{ .expr = for_.expr });
                try self.pushChild(.{ .expr = for_.body });
                self.endChildren(children);
            },
            .hosted_lambda => |hosted| {
                const children = self.beginChildren();
                for (hosted.args) |arg| try self.pushChild(.{ .pattern = arg });
                self.endChildren(children);
            },
            .run_low_level => |run| {
                const children = self.beginChildren();
                for (run.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            => {},
        }
    }

    fn pushStaticDispatchPlanArgs(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedModuleInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        const children = self.beginChildren();
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushChild(.{ .expr = expr }),
            .generated_interpolation_segments => |expr| try self.pushChild(.{ .generated_interpolation_segments = expr }),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
        self.endChildren(children);
    }

    fn visitInterpolationChildren(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const data = self.bodies.exprData(expr_id);
        if (data != .interpolation) {
            checkedModuleInvariant("generated interpolation segments operand pointed at non-interpolation expression", .{});
        }
        const interpolation = data.interpolation;
        const children = self.beginChildren();
        try self.pushChild(.{ .expr = interpolation.first });
        for (interpolation.parts) |part| try self.pushChild(.{ .expr = part });
        self.endChildren(children);
    }

    /// A custom literal pattern compares the matched value with its literal
    /// converted at the pattern's type: its equality plan, then the
    /// conversion's plan.
    fn visitLiteralPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const guard = try self.bodies.literalPatternGuard(pattern_id) orelse
            checkedModuleInvariant("a literal pattern guard was collected for a pattern compared directly", .{});
        const equality = guard.equality_plan orelse checkedModuleInvariant("a custom literal pattern reached template closure collection without an equality plan", .{});
        try self.appendDispatchRef(equality);
        if (guard.conversion.plan) |conversion| try self.appendDispatchRef(conversion);
    }

    /// Record an iterator-for plan and push its dispatch-call operands, in
    /// source order, among the children currently being pushed.
    fn pushIteratorForPlan(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.IteratorForPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.iterator_for_plans.len) {
            checkedModuleInvariant("checked template iterator-for plan id was outside the plan table", .{});
        }
        try self.iterator_refs.append(self.allocator, plan_id);
        try self.iterator_ref_scopes.append(self.allocator, self.currentScope());
        const plan = self.static_dispatch_plans.iterator_for_plans[raw];
        try self.pushIteratorDispatchCall(plan.iter);
        try self.pushIteratorDispatchCall(plan.next);
    }

    fn pushIteratorDispatchCall(
        self: *CheckedTemplateRefCollector,
        call: static_dispatch.IteratorDispatchCall,
    ) Allocator.Error!void {
        for (call.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushChild(.{ .expr = expr }),
            .loop_iterator_state, .interpolation_seed, .interpolation_iterator, .interpolation_value => {},
        };
    }

    /// Collect the references reachable from a checked pattern.
    fn collectPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const base_len = self.work.items.len;
        try self.work.append(self.allocator, .{ .pattern = pattern_id });
        while (self.work.items.len > base_len) {
            switch (self.work.pop().?) {
                .expr => |id| try self.visitExpr(id),
                .pattern => |id| try self.visitPattern(id),
                .statement => |id| try self.visitStatement(id),
                .generated_interpolation_segments => |id| try self.visitInterpolationChildren(id),
                .literal_pattern => |id| try self.visitLiteralPattern(id),
                .call_relation => |id| try self.appendCallRelation(id),
                .pop_scope => _ = self.scope_stack.pop(),
            }
        }
    }

    fn visitPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const entry = try self.visited_patterns.getOrPut(pattern_id);
        if (entry.found_existing) return;

        const bodies = self.bodies;
        const children = self.beginChildren();
        switch (bodies.patternData(pattern_id)) {
            .as => |as| try self.pushChild(.{ .pattern = as.pattern }),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.pushChild(.{ .pattern = arg });
            },
            .nominal => |nominal| try self.pushChild(.{ .pattern = nominal.backing_pattern }),
            .record_destructure => |destructs| {
                for (destructs) |destruct| try self.pushChild(.{ .pattern = bodies.recordDestructPattern(destruct) });
            },
            .list => |list| {
                for (list.patterns) |child| try self.pushChild(.{ .pattern = child });
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.pushChild(.{ .pattern = child });
                }
            },
            .tuple => |items| {
                for (items) |child| try self.pushChild(.{ .pattern = child });
            },
            .str_interpolation => |str| {
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushChild(.{ .pattern = capture });
                }
            },
            .numeral_literal, .str_literal => if (bodies.literalPatternIsCustom(pattern_id)) try self.pushChild(.{ .literal_pattern = pattern_id }),
            .assign,
            .underscore,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    fn visitStatement(self: *CheckedTemplateRefCollector, statement_id: CIR.Statement.Idx) Allocator.Error!void {
        const entry = try self.visited_statements.getOrPut(statement_id);
        if (entry.found_existing) return;

        const children = self.beginChildren();
        switch (self.bodies.statementData(statement_id)) {
            .decl => |decl| {
                try self.pushChild(.{ .pattern = decl.pattern });
                try self.pushChild(.{ .expr = decl.expr });
            },
            // The promoted procedure is collected as its own template.
            .promoted_proc => {},
            .var_ => |var_| {
                try self.pushChild(.{ .pattern = var_.pattern });
                try self.pushChild(.{ .expr = var_.expr });
            },
            .var_uninitialized => |var_| {
                try self.pushChild(.{ .pattern = var_.pattern });
            },
            .reassign => |reassign| {
                try self.pushChild(.{ .pattern = reassign.pattern });
                try self.pushChild(.{ .expr = reassign.expr });
            },
            inline .dbg, .expr, .expect => |child| try self.pushChild(.{ .expr = child }),
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushChild(.{ .expr = ret.expr });
            },
            .for_ => |for_| {
                const plan_id = self.bodies.iteratorForPlan(@backingInt(statement_id)) orelse checkedModuleInvariant("checked for statement reached template closure collection without an iterator-for plan", .{});
                try self.pushIteratorForPlan(plan_id);
                try self.pushChild(.{ .pattern = for_.pattern });
                try self.pushChild(.{ .expr = for_.expr });
                try self.pushChild(.{ .expr = for_.body });
            },
            inline .while_, .infinite_loop, .breakable_loop => |while_| {
                try self.pushChild(.{ .expr = while_.cond });
                try self.pushChild(.{ .expr = while_.body });
            },
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }
};

/// Public `TopLevelUseSummaryRef` declaration.
pub const TopLevelUseSummaryRef = struct {
    start: u32 = 0,
    len: u32 = 0,
};

/// Public `NestedProcKind` declaration.
pub const NestedProcKind = enum {
    local_function,
    closure,
    desugared_closure,
};

/// Producer-authored source of a nested procedure's evidence vector.
pub const NestedProcEvidenceSource = enum {
    /// The site does not introduce a dispatch scope and inherits its lexical
    /// evidence unchanged.
    inherited,
    /// Checking recorded an exact scheme-instantiation edge for the site.
    checked_site,
};

/// Root that lexically owns a nested procedure site. Almost every site sits
/// inside a checked procedure template's body (or an entry wrapper's generated
/// body, which borrows its template's identity). Defaulted-field expressions
/// (design.md "Defaulted Fields") are the exception: they belong to no
/// template—each is lowered standalone at every construction site that omits
/// its field—so each default expression owns the sites inside it.
pub const NestedProcSiteOwner = union(enum) {
    template: canonical.ProcedureTemplateRef,
    /// The defaulted-field expression that owns the site.
    default_root: CIR.Expr.Idx,
};

/// The id of a nested procedure site within its owner: the node id of the
/// lambda, closure or hosted lambda expression it constructs a procedure at.
pub fn nestedProcSiteId(expr: CIR.Expr.Idx) canonical.NestedProcSiteId {
    return @fromBackingInt(@backingInt(expr));
}

/// The expression a nested procedure site constructs its procedure at.
pub fn nestedProcSiteExpr(site: canonical.NestedProcSiteId) CIR.Expr.Idx {
    return @fromBackingInt(@backingInt(site));
}

/// One lambda, closure or hosted lambda an owner's body constructs a
/// procedure at. Its id is its expression's (`nestedProcSiteId`).
pub const NestedProcSite = struct {
    /// Exact generalized-local scope lexically owning this site, or the
    /// template root when the site is outside every generalized local.
    lexical_scope: DispatchScope,
    evidence_source: NestedProcEvidenceSource,
    /// The construction site's checked evidence when
    /// `evidence_source == .checked_site`; empty otherwise.
    evidence: static_dispatch.EvidenceSpan,
    kind: NestedProcKind,
    checked_expr: CIR.Expr.Idx,

    pub fn id(self: NestedProcSite) canonical.NestedProcSiteId {
        return nestedProcSiteId(self.checked_expr);
    }
};

/// The nested procedure sites of one owner's body, in scan order, and the
/// lexical facts of the same scan that the module's runtime captures read
/// (`ModuleNestedProcSites`). Computed on first demand per owner
/// (`ModuleAnalyses.nestedProcSites`).
pub const OwnerNestedProcSites = struct {
    sites: []const NestedProcSite = &.{},
    /// Positions in `sites`, ordered by expression.
    by_expr: []const u32 = &.{},
    /// Per site: the position of the site whose body lexically encloses it.
    parents: []const ?u32 = &.{},
    /// Every binder the owner's body binds, with the position of the
    /// innermost site whose body binds it; null for the owner's own body.
    binders: []const BinderSite = &.{},
    /// Each local procedure a site's own body selects.
    selections: []const SiteSelection = &.{},

    pub const BinderSite = struct {
        binder: CIR.Pattern.Idx,
        site: ?u32,
    };

    pub const SiteSelection = struct {
        site: u32,
        proc_expr: CIR.Expr.Idx,
    };

    /// The position of the site at `expr`.
    pub fn position(self: *const OwnerNestedProcSites, expr: CIR.Expr.Idx) ?u32 {
        var low: usize = 0;
        var high: usize = self.by_expr.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const candidate = self.sites[self.by_expr[mid]].checked_expr;
            if (@backingInt(candidate) == @backingInt(expr)) return self.by_expr[mid];
            if (@backingInt(candidate) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }

    /// The site `site`, when this owner constructs one there.
    pub fn find(self: *const OwnerNestedProcSites, site: canonical.NestedProcSiteId) ?NestedProcSite {
        const found = self.position(nestedProcSiteExpr(site)) orelse return null;
        return self.sites[found];
    }

    pub fn destroy(self: *OwnerNestedProcSites, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.free(self.by_expr);
        allocator.free(self.parents);
        allocator.free(self.binders);
        allocator.free(self.selections);
        allocator.destroy(self);
    }
};

/// The nested procedure sites of a module's owners, keyed by expression:
/// which owners construct a procedure at each site expression and the
/// binders of enclosing frames whose values that procedure needs at runtime
/// (its runtime captures). A closure's own captures come first, in their
/// checked order; after them come the binders that constructing the local
/// procedures this procedure (or a procedure nested in it) selects requires,
/// ordered by binder id. Computed on first demand per module
/// (`ModuleAnalyses.moduleNestedProcSites`).
pub const ModuleNestedProcSites = struct {
    /// Every site expression of every owner, ascending.
    exprs: []const CIR.Expr.Idx = &.{},
    /// Per expression: the first template, in template order, whose body
    /// constructs a procedure there; null when only defaults do.
    first_templates: []const ?canonical.CheckedProcedureTemplateId = &.{},
    /// Per expression: how many owners construct a procedure there.
    owner_counts: []const u32 = &.{},
    /// Per expression: its runtime captures, a range of `captures`.
    capture_spans: []const store_serialize.Span = &.{},
    captures: []const CheckedCapture = &.{},
    /// Each closure site's lambda with its closure's expression, ordered by
    /// lambda: a closure's lambda names the closure's site.
    closure_lambdas: []const ClosureLambda = &.{},

    pub const ClosureLambda = struct {
        lambda: CIR.Expr.Idx,
        closure: CIR.Expr.Idx,
    };

    /// The position of site expression `expr`, or of the closure whose
    /// lambda `expr` is.
    pub fn position(self: *const ModuleNestedProcSites, expr: CIR.Expr.Idx) ?usize {
        if (exprPosition(self.exprs, expr)) |found| return found;
        var low: usize = 0;
        var high: usize = self.closure_lambdas.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const candidate = self.closure_lambdas[mid].lambda;
            if (@backingInt(candidate) == @backingInt(expr)) return exprPosition(self.exprs, self.closure_lambdas[mid].closure);
            if (@backingInt(candidate) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }

    /// The runtime captures of the procedure constructed at `expr` (a site
    /// expression or a closure site's lambda).
    pub fn runtimeCaptures(self: *const ModuleNestedProcSites, expr: CIR.Expr.Idx) ?[]const CheckedCapture {
        const found = self.position(expr) orelse return null;
        const span = self.capture_spans[found];
        return self.captures[span.start..][0..span.len];
    }

    pub fn destroy(self: *ModuleNestedProcSites, allocator: Allocator) void {
        allocator.free(self.exprs);
        allocator.free(self.first_templates);
        allocator.free(self.owner_counts);
        allocator.free(self.capture_spans);
        allocator.free(self.captures);
        allocator.free(self.closure_lambdas);
        allocator.destroy(self);
    }

    fn exprPosition(exprs: []const CIR.Expr.Idx, expr: CIR.Expr.Idx) ?usize {
        var low: usize = 0;
        var high: usize = exprs.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            if (@backingInt(exprs[mid]) == @backingInt(expr)) return mid;
            if (@backingInt(exprs[mid]) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }
};

/// Public `ProcTarget` declaration.
pub const ProcTarget = union(enum) {
    roc,
    hosted,
    intrinsic,
    entry,
    comptime_only,
};

/// Public `CheckedProcedureTemplate` declaration.
pub const CheckedProcedureTemplate = struct {
    proc_base: canonical.ProcBase,
    template_id: canonical.CheckedProcedureTemplateId,
    body: CheckedProcedureBody,
    checked_fn_scheme: CheckedTypeSchemeId,
    checked_fn_root: CheckedTypeId,
    /// Every call plan the template's body reaches: a range of
    /// `CheckedProcedureTemplateTable.dispatch_plan_refs`. Dispatch
    /// resolution classifies them (`CheckedDispatch.templateRelations`).
    static_dispatch_plans: StaticDispatchPlanTableRef,
    /// Range into
    /// `CheckedProcedureTemplateTable.specialization_interface_relations`.
    specialization_interface_relations: store_serialize.Span = .{},
    resolved_value_refs: ResolvedValueRefTableRef,
    top_level_value_uses: TopLevelUseSummaryRef,
    target: ProcTarget,
    /// The low-level operation this template's body runs over its parameters,
    /// for a Builtin definition the Builtin low-level transform produced.
    /// Post-check stages read the operation from here; they never recognize a
    /// low-level wrapper from its body.
    provided_low_level: ?base.LowLevel = null,
};

fn checkedTypeIsClosedTagRow(
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) bool {
    var remaining = checked_types.typeCount();
    var current = root;
    while (true) {
        switch (checked_types.payload(current)) {
            .alias => |alias| current = alias.backing,
            .tag_union => |tag_union| current = tag_union.ext,
            .empty_tag_union => return true,
            .flex, .rigid => |variable| return variable.row_default == .empty_tag_union,
            .pending,
            .field_kind,
            .err,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => return false,
        }
        if (remaining == 0) {
            checkedModuleInvariant("hosted Try error row chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

test "hosted Try adapter capability recognizes only closed structural error rows" {
    const allocator = std.testing.allocator;

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();

    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &store, &names);

    const empty_row = try store.appendSyntheticPayloadRoot(allocator, .empty_tag_union);
    const non_row = try store.appendSyntheticPayloadRoot(allocator, .empty_record);
    const open_tail = try store.reserveSyntheticTypeRoot(allocator);
    try testFillSyntheticVariableRoot(allocator, &store, open_tail, .{ .flex = .{} });
    const defaulted_tail = try store.reserveSyntheticTypeRoot(allocator);
    try testFillSyntheticVariableRoot(allocator, &store, defaulted_tail, .{ .flex = .{ .row_default = .empty_tag_union } });

    const error_tag = try names.internTagLabel("HostErr");
    const closed_tags = try allocator.alloc(CheckedTag, 1);
    closed_tags[0] = .{ .name = error_tag };
    const closed_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = closed_tags,
        .ext = empty_row,
    } });

    const open_tags = try allocator.alloc(CheckedTag, 1);
    open_tags[0] = .{ .name = error_tag };
    const open_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = open_tags,
        .ext = open_tail,
    } });

    const defaulted_tags = try allocator.alloc(CheckedTag, 1);
    defaulted_tags[0] = .{ .name = error_tag };
    const defaulted_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = defaulted_tags,
        .ext = defaulted_tail,
    } });

    const alias_name = try names.internTypeName("HostErrors");
    const module_identity = try names.internModuleIdentity(&(@as([32]u8, @splat(0x69))));
    const aliased_row = try store.appendSyntheticPayloadRoot(allocator, .{ .alias = .{
        .name = alias_name,
        .origin_module = module_identity,
        .owner_module = testCheckedModuleKey(105).digest(),
        .backing = closed_row,
    } });

    try std.testing.expect(checkedTypeIsClosedTagRow(&store, empty_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, closed_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, defaulted_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, aliased_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, open_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, non_row));
}

/// Public `CheckedProcedureTemplateTable` declaration.
pub const CheckedProcedureTemplateTable = struct {
    templates: std.ArrayList(CheckedProcedureTemplate) = .empty,
    by_def: []static_dispatch.ProcedureTemplateLookupEntry = &.{},
    /// The templates of local functions checking promoted to procedures of
    /// their own, in promotion order, with each one's binding pattern.
    promoted: []PromotedProcedureTemplateEntry = &.{},
    /// Every template's call plans (`CheckedProcedureTemplate.static_dispatch_plans`),
    /// then the defaulted-field expressions' (`TemplateDispatchSites`).
    dispatch_plan_refs: []static_dispatch.StaticDispatchPlanId = &.{},
    /// Scope of each `dispatch_plan_refs` entry.
    dispatch_ref_scopes: []DispatchScope = &.{},
    /// The other sites each template's body reaches.
    dispatch_sites: TemplateDispatchSites = .{},
    /// Relation semantics of each `dispatch_plan_refs` entry.
    dispatch_relation_kinds: []DispatchRelationKind = &.{},
    /// Generalized-local scopes referenced by `dispatch_ref_scopes`.
    dispatch_scopes: []DispatchRefScope = &.{},
    /// Flat pool of checker-authored relations that complete callable
    /// interfaces before specialization keys are sealed.
    specialization_interface_relations: []SpecializationInterfaceRelation = &.{},
    /// Checked argument types backing call-relation spans.
    specialization_interface_types: []CheckedTypeId = &.{},

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        owner_module: canonical.CheckedModuleRef,
        checked_source_types: *const CheckedSourceTypes,
        module_index: *const ModuleIndex,
    ) Allocator.Error!CheckedProcedureTemplateTable {
        var templates = std.ArrayList(CheckedProcedureTemplate).empty;
        errdefer templates.deinit(allocator);
        var by_def = std.ArrayList(static_dispatch.ProcedureTemplateLookupEntry).empty;
        errdefer by_def.deinit(allocator);

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedModuleInvariant("generated method marker reached procedure-template publication", .{});
            }
            const template_kind = static_dispatch.procedureTemplateKindForValueBindingDef(module, def_idx) orelse continue;

            const intrinsic = intrinsicForProcedureDef(module, def_idx);
            const proc_base = canonical.ProcBase.of(
                if (intrinsic != null) .intrinsic_wrapper else if (isHostedProcedureExpr(def.expr.data)) .hosted_wrapper else .checked_source,
                @backingInt(def_idx),
            );
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .module = owner_module,
                .proc_base = proc_base,
                .template = template_id,
            };
            try by_def.append(allocator, .{
                .def = def_idx,
                .template = template_ref,
                .kind = template_kind,
            });
            const checked_fn_root = checked_source_types.rootForSourceVar(module, module.defType(def_idx)) orelse {
                base.invariant("checked module invariant violated: checked procedure function root was not published", .{});
            };
            const checked_fn_scheme = checked_source_types.schemeForSourceVar(module, module.defType(def_idx));
            const body: CheckedProcedureBody = if (intrinsic) |intrinsic_id| blk: {
                break :blk .{ .intrinsic_wrapper = intrinsic_id };
            } else if (def.expr.data == .e_anno_only) .{ .unimplemented = .{
                .region = module.regionAt(ModuleEnv.nodeIdxFrom(def.expr.idx)),
            } } else blk: {
                if (!module_index.reachesExpr(def.expr.idx)) {
                    base.invariant("checked module invariant violated: checked procedure body root expression was not published", .{});
                }
                break :blk .{ .checked_body = def.expr.idx };
            };

            try templates.append(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = body,
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = if (intrinsic != null)
                    .intrinsic
                else if (isHostedProcedureExpr(def.expr.data))
                    .hosted
                else
                    .roc,
                .provided_low_level = module.moduleEnvConst().providedLowLevelForDef(def_idx),
            });
        }

        std.mem.sort(static_dispatch.ProcedureTemplateLookupEntry, by_def.items, {}, static_dispatch.ProcedureTemplateLookupEntry.lessThan);
        const by_def_slice = try by_def.toOwnedSlice(allocator);
        errdefer allocator.free(by_def_slice);
        return .{
            .templates = templates,
            .by_def = by_def_slice,
        };
    }

    /// Give each promoted local function its own procedure template, rooted at
    /// its lambda and published under its binding's generalized scheme. A
    /// promoted closure's captures name other promoted procedures, so its
    /// template root is the closure's lambda.
    pub fn appendPromotedLocalProcedures(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        module: TypedCIR.Module,
        owner_module: canonical.CheckedModuleRef,
        checked_source_types: *const CheckedSourceTypes,
        module_index: *const ModuleIndex,
        promoted_local_procedures: []const hoist_roots.PromotedLocalProcedure,
    ) Allocator.Error!void {
        if (promoted_local_procedures.len == 0) return;
        const entries = try allocator.alloc(PromotedProcedureTemplateEntry, promoted_local_procedures.len);
        errdefer allocator.free(entries);
        try self.templates.ensureUnusedCapacity(allocator, promoted_local_procedures.len);
        for (promoted_local_procedures, entries) |promoted, *entry| {
            const source_data = module.expr(promoted.expr).data;
            const lambda_source = if (source_data == .e_lambda)
                promoted.expr
            else if (source_data == .e_closure)
                source_data.e_closure.lambda_idx
            else
                checkedModuleInvariant("promoted local procedure was not a lambda or closure", .{});
            if (!module_index.reachesExpr(lambda_source)) checkedModuleInvariant("promoted local procedure lambda was not published", .{});
            const root_expr = lambda_source;
            const proc_base = canonical.ProcBase.of(.promoted_local, @backingInt(lambda_source));
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .module = owner_module,
                .proc_base = proc_base,
                .template = template_id,
            };
            const checked_fn_root = checked_source_types.rootForSourceVar(module, module.exprType(root_expr)) orelse
                checkedModuleInvariant("promoted local procedure lambda type was not published", .{});
            self.templates.appendAssumeCapacity(.{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = .{ .checked_body = root_expr },
                .checked_fn_scheme = checked_source_types.schemeForSourceVar(module, ModuleEnv.varFrom(promoted.pattern)),
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = .roc,
            });
            entry.* = .{ .pattern = promoted.pattern, .template = template_ref };
        }
        allocator.free(self.promoted);
        self.promoted = entries;
    }

    pub fn lookupByDef(self: *const CheckedProcedureTemplateTable, def_idx: CIR.Def.Idx) ?canonical.ProcedureTemplateRef {
        return (self.lookupEntryByDef(def_idx) orelse return null).template;
    }

    /// The template of a source definition and its semantic lowering kind.
    pub fn lookupEntryByDef(self: *const CheckedProcedureTemplateTable, def_idx: CIR.Def.Idx) ?static_dispatch.ProcedureTemplateLookupEntry {
        var lo: usize = 0;
        var hi: usize = self.by_def.len;
        const target = @backingInt(def_idx);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_def[mid].def);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_def.len or self.by_def[lo].def != def_idx) return null;
        return self.by_def[lo];
    }

    pub fn appendEntryWrappersForRoots(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        owner_module: canonical.CheckedModuleRef,
        checked_types: *CheckedTypeStore,
        entry_wrappers: *EntryWrapperTable,
        roots: []const CompileTimeRoot,
    ) Allocator.Error!void {
        // Every selected root produces exactly one entry wrapper and template.
        try self.templates.ensureTotalCapacityPrecise(allocator, self.templates.items.len + roots.len);
        try entry_wrappers.wrappers.ensureTotalCapacityPrecise(allocator, entry_wrappers.wrappers.items.len + roots.len);

        for (roots) |root| {
            const checked_fn_root = try checked_types.appendSyntheticFunctionRoot(
                allocator,
                .pure,
                &.{},
                root.checked_type,
            );
            const checked_fn_scheme = try checked_types.ensureSchemeForRoot(allocator, checked_fn_root);
            const proc_base = canonical.ProcBase.entry_wrapper;
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .module = owner_module,
                .proc_base = proc_base,
                .template = template_id,
            };
            const wrapper_id = try entry_wrappers.append(allocator, root.id, template_ref, checked_fn_root);
            try self.appendTemplate(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = .{ .entry_wrapper = wrapper_id },
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = switch (root.kind) {
                    .expect => .entry,
                    .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => .comptime_only,
                },
            });
        }
    }

    fn appendTemplate(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        template: CheckedProcedureTemplate,
    ) Allocator.Error!void {
        try self.templates.append(allocator, template);
    }

    /// Template `id` of the table. A literal root's entry wrapper is no row
    /// (`CheckedDispatch.procedureTemplate`).
    pub fn get(self: *const CheckedProcedureTemplateTable, id: canonical.CheckedProcedureTemplateId) CheckedProcedureTemplate {
        return self.templates.items[id.index()];
    }

    pub fn view(self: *const CheckedProcedureTemplateTable) CheckedProcedureTemplateTableView {
        return .{ .templates = self.templates.items };
    }

    pub fn asLookup(self: *const CheckedProcedureTemplateTable, module_idx: u32) static_dispatch.ProcedureTemplateLookup {
        return .{
            .module_idx = module_idx,
            .by_def = self.by_def,
            .promoted = self.promoted,
        };
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;

    pub fn specializationRelations(self: *const CheckedProcedureTemplateTable, template: *const CheckedProcedureTemplate) []const SpecializationInterfaceRelation {
        const span = template.specialization_interface_relations;
        return self.specialization_interface_relations[span.start .. span.start + span.len];
    }

    pub fn specializationRelationTypes(self: *const CheckedProcedureTemplateTable, span: store_serialize.Span) []const CheckedTypeId {
        return self.specialization_interface_types[span.start .. span.start + span.len];
    }
};

/// A promoted local procedure's template and the binding pattern whose
/// generalized scheme it publishes.
pub const PromotedProcedureTemplateEntry = static_dispatch.PromotedProcedureTemplateEntry;

/// Public `CheckedProcedureTemplateTableView` declaration.
pub const CheckedProcedureTemplateTableView = struct {
    templates: []const CheckedProcedureTemplate = &.{},
};

test "issue 11128 procedure template extension stays amortized" {
    const count: usize = 4096;
    var bytes = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    const gpa = bytes.allocator();
    var table = CheckedProcedureTemplateTable{};
    defer table.deinit(gpa);
    for (0..count) |i| {
        try table.appendTemplate(gpa, .{
            .proc_base = @fromBackingInt(@intCast(i)),
            .template_id = @fromBackingInt(@intCast(i)),
            .body = .{ .entry_wrapper = @fromBackingInt(@intCast(i)) },
            .checked_fn_scheme = @fromBackingInt(@intCast(i)),
            .checked_fn_root = @fromBackingInt(@intCast(i)),
            .static_dispatch_plans = .{},
            .resolved_value_refs = .{},
            .top_level_value_uses = .{},
            .target = .comptime_only,
        });
    }
    for (0..count) |i| {
        const row = table.get(@fromBackingInt(@intCast(i)));
        try std.testing.expectEqual(i, @backingInt(row.template_id));
        try std.testing.expectEqual(i, @backingInt(row.body.entry_wrapper));
    }
    try std.testing.expect(bytes.allocated_bytes <= 8 * count * @sizeOf(CheckedProcedureTemplate));
}

/// Each generalized local scope of `scopes` by the expression it is checked
/// at.
pub fn nestedProcScopeMap(
    allocator: Allocator,
    scopes: []const DispatchRefScope,
) Allocator.Error!collections.DenseMap(CIR.Expr.Idx, DispatchScopeId) {
    var by_checked_expr = collections.DenseMap(CIR.Expr.Idx, DispatchScopeId).init(allocator);
    errdefer by_checked_expr.deinit();
    try by_checked_expr.ensureTotalCapacity(@intCast(scopes.len));
    for (scopes, 0..) |scope, raw_scope| {
        const entry = by_checked_expr.getOrPutAssumeCapacity(scope.checked_expr);
        if (entry.found_existing) {
            checkedModuleInvariant("checked expression owned more than one generalized dispatch scope", .{});
        }
        entry.value_ptr.* = @fromBackingInt(@intCast(@as(u32, @intCast(raw_scope))));
    }
    return by_checked_expr;
}

fn nestedProcLexicalScope(
    current: DispatchScope,
    expr: CIR.Expr.Idx,
    by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    scopes: []const DispatchRefScope,
) DispatchScope {
    const scope_id = by_checked_expr.get(expr) orelse return current;
    const raw_scope = @backingInt(scope_id);
    if (raw_scope >= scopes.len or scopes[raw_scope].checked_expr != expr) {
        checkedModuleInvariant("nested procedure lexical scope map disagreed with the checked scope table", .{});
    }
    const expected_parent: DispatchScope = if (scopes[raw_scope].parent) |parent|
        .{ .generalized = parent }
    else
        .root;
    if (!std.meta.eql(current, expected_parent)) {
        checkedModuleInvariant("generalized nested procedure site had the wrong lexical parent scope", .{});
    }
    return .{ .generalized = scope_id };
}

/// The scan of one owner's body for its nested procedure sites
/// (`computeOwnerNestedProcSites`).
const NestedProcSiteScan = struct {
    allocator: Allocator,
    bodies: CheckedBodies,
    dispatch: CheckedDispatch,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    dispatch_scopes: []const DispatchRefScope,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    current_scope: DispatchScope = .root,
    sites: std.ArrayList(NestedProcSite) = .empty,
    /// Per site, by position: the site lexically enclosing it, if any.
    parents: std.ArrayList(?u32) = .empty,
    binders: std.ArrayList(OwnerNestedProcSites.BinderSite) = .empty,
    selections: std.ArrayList(OwnerNestedProcSites.SiteSelection) = .empty,
    work: std.ArrayList(ScanWork) = .empty,
    /// The positions of the sites whose bodies the walk is inside, innermost
    /// last.
    open_sites: std.ArrayList(u32) = .empty,

    fn deinit(self: *NestedProcSiteScan) void {
        self.sites.deinit(self.allocator);
        self.parents.deinit(self.allocator);
        self.binders.deinit(self.allocator);
        self.selections.deinit(self.allocator);
        self.work.deinit(self.allocator);
        self.open_sites.deinit(self.allocator);
    }

    fn scanEntryWrapper(self: *NestedProcSiteScan, root: CompileTimeRoot) Allocator.Error!void {
        const parts = root.bodyParts();
        if (parts.expr) |expr| try self.scanExpr(expr, false);
        if (parts.pattern) |pattern| try self.scanPattern(pattern);
        // A literal conversion root converts its literal's value as data and
        // owns no nested procedure site.
    }

    fn addSite(self: *NestedProcSiteScan, kind: NestedProcKind, checked_expr: CIR.Expr.Idx) Allocator.Error!void {
        const evidence_source, const evidence = switch (self.current_scope) {
            .root => .{ NestedProcEvidenceSource.inherited, static_dispatch.EvidenceSpan{} },
            .generalized => |scope_id| blk: {
                const raw_scope = @backingInt(scope_id);
                if (raw_scope >= self.dispatch_scopes.len) {
                    checkedModuleInvariant("nested procedure site owned an unknown checked dispatch scope", .{});
                }
                if (self.dispatch_scopes[raw_scope].checked_expr != checked_expr) {
                    break :blk .{ NestedProcEvidenceSource.inherited, static_dispatch.EvidenceSpan{} };
                }
                const span = (try self.dispatch.siteEvidenceSpan(checked_expr)) orelse
                    checkedModuleInvariant("nested procedure scope had no producer-authored construction evidence", .{});
                break :blk .{ NestedProcEvidenceSource.checked_site, span };
            },
        };

        try self.parents.append(self.allocator, self.innermostOpenSite());
        try self.sites.append(self.allocator, .{
            .lexical_scope = self.current_scope,
            .evidence_source = evidence_source,
            .evidence = evidence,
            .kind = kind,
            .checked_expr = checked_expr,
        });
    }

    /// Scan a checked expression for nested procedure sites. The scan keeps
    /// its own work stack, so body nesting depth never becomes native call
    /// depth. Children are pushed in reverse so they are scanned in source
    /// order, and each expression's exit is pushed before its children so it
    /// restores the lexical state they saw once they are all scanned.
    fn scanExpr(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx, suppress_current_site: bool) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .expr = .{ .id = expr_id, .suppress_current_site = suppress_current_site } });
        try self.drain();
    }

    fn scanPattern(self: *NestedProcSiteScan, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        try self.pushPattern(pattern_id);
        try self.drain();
    }

    fn drain(self: *NestedProcSiteScan) Allocator.Error!void {
        while (self.work.pop()) |work| switch (work) {
            .expr => |item| try self.enterExpr(item.id, item.suppress_current_site),
            .exit_expr => |exit| self.exitExpr(exit),
            .pattern => |item| try self.enterPattern(item.id),
            .statement => |item| try self.enterStatement(item.id),
            .generated_interpolation_segments => |item| try self.pushInterpolationChildren(item.id),
        };
    }

    const ScanWork = union(enum) {
        expr: struct { id: CIR.Expr.Idx, suppress_current_site: bool },
        exit_expr: ExprExit,
        pattern: struct { id: CIR.Pattern.Idx },
        statement: struct { id: CIR.Statement.Idx },
        generated_interpolation_segments: struct { id: CIR.Expr.Idx },
    };

    /// The lexical state an expression restores once its children are scanned.
    const ExprExit = struct {
        previous_scope: DispatchScope,
        open_site_mark: usize,
    };

    /// Children are pushed in source order between `beginChildren` and
    /// `endChildren`, which reverses them on the work stack.
    fn beginChildren(self: *const NestedProcSiteScan) usize {
        return self.work.items.len;
    }

    fn endChildren(self: *NestedProcSiteScan, start: usize) void {
        std.mem.reverse(ScanWork, self.work.items[start..]);
    }

    fn pushWork(self: *NestedProcSiteScan, work: ScanWork) Allocator.Error!void {
        try self.work.append(self.allocator, work);
    }

    fn pushExpr(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        try self.pushWork(.{ .expr = .{ .id = expr_id, .suppress_current_site = false } });
    }

    fn pushPattern(self: *NestedProcSiteScan, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        try self.pushWork(.{ .pattern = .{ .id = pattern_id } });
    }

    fn enterExpr(
        self: *NestedProcSiteScan,
        expr_id: CIR.Expr.Idx,
        suppress_current_site: bool,
    ) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.exprData(expr_id);
        const previous_scope = self.current_scope;
        self.current_scope = nestedProcLexicalScope(
            previous_scope,
            expr_id,
            self.scope_by_checked_expr,
            self.dispatch_scopes,
        );
        try self.pushWork(.{ .exit_expr = .{ .previous_scope = previous_scope, .open_site_mark = self.open_sites.items.len } });
        const children = self.beginChildren();
        switch (data) {
            .closure => |closure| {
                if (!suppress_current_site) {
                    try self.addSite(.closure, expr_id);
                    try self.openSite();
                }
                try self.pushWork(.{ .expr = .{ .id = closure.lambda, .suppress_current_site = true } });
            },
            .lambda => |lambda| {
                if (!suppress_current_site) {
                    try self.addSite(.local_function, expr_id);
                    try self.openSite();
                }
                for (lambda.args) |arg| try self.pushPattern(arg);
                try self.pushExpr(lambda.body);
            },
            .str => |segments| if (bodies.quoteIsCustom(@backingInt(expr_id))) {
                try self.pushStaticDispatchPlanArgs(bodies.quotePlan(@backingInt(expr_id)) orelse checkedModuleInvariant("checked from_quote expression reached nested procedure site collection without a dispatch plan", .{}));
            } else {
                for (segments) |segment| try self.pushExpr(segment);
            },
            .list,
            .tuple,
            => |items| {
                for (items) |item| try self.pushExpr(item);
            },
            .match_ => |match| {
                try self.pushExpr(match.cond);
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushPattern(bodies.matchBranchPattern(branch_pattern).pattern);
                    if (branch.guard) |guard| try self.pushExpr(guard);
                    try self.pushExpr(branch.value);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushExpr(branch.cond);
                    try self.pushExpr(branch.body);
                }
                try self.pushExpr(if_.final_else);
            },
            .call => |call| {
                try self.pushExpr(call.func);
                for (call.args) |arg| try self.pushExpr(arg);
            },
            .record => |record| {
                if (record.ext) |ext| try self.pushExpr(ext);
                for (record.fields) |field| try self.pushExpr(bodies.recordFieldValue(field));
            },
            .block => |block| {
                for (block.statements) |statement| try self.pushWork(.{ .statement = .{ .id = statement } });
                try self.pushExpr(block.final_expr);
            },
            .tag => |tag| {
                for (tag.args) |arg| try self.pushExpr(arg);
            },
            .nominal => |nominal| try self.pushExpr(nominal.backing_expr),
            .binop => |binop| {
                try self.pushExpr(binop.lhs);
                try self.pushExpr(binop.rhs);
            },
            inline .unary_minus, .dbg => |child| try self.pushExpr(child),
            .expect_err => |expect_err| try self.pushExpr(expect_err.expr),
            .expect => |child| try self.pushExpr(child),
            .break_ => {},
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushExpr(ret.expr);
            },
            .field_access => |field| try self.pushExpr(field.receiver),
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => try self.pushStaticDispatchPlanArgs(bodies.dispatchPlan(@backingInt(expr_id)) orelse checkedModuleInvariant("checked dispatch expression reached nested procedure site collection without a static-dispatch plan", .{})),
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(expr_id)) {
                try self.pushExpr(interpolation.first);
                for (interpolation.parts) |part| try self.pushExpr(part);
            } else {
                try self.pushStaticDispatchPlanArgs(bodies.dispatchPlan(@backingInt(expr_id)) orelse checkedModuleInvariant("checked interpolation expression reached nested procedure site collection without a static-dispatch plan", .{}));
            },
            .numeral => if (bodies.numeralPlan(@backingInt(expr_id))) |plan_id| try self.pushStaticDispatchPlanArgs(plan_id),
            .structural_eq => |eq| {
                try self.pushExpr(eq.lhs);
                try self.pushExpr(eq.rhs);
            },
            .structural_hash => |h| {
                try self.pushExpr(h.value);
                try self.pushExpr(h.hasher);
            },
            .tuple_access => |access| try self.pushExpr(access.tuple),
            .for_ => |for_| {
                try self.pushPattern(for_.pattern);
                try self.pushExpr(for_.expr);
                try self.pushExpr(for_.body);
            },
            .hosted_lambda => |hosted| {
                if (!suppress_current_site) {
                    try self.addSite(.local_function, expr_id);
                    try self.openSite();
                }
                for (hosted.args) |arg| try self.pushPattern(arg);
            },
            .run_low_level => |run| {
                for (run.args) |arg| try self.pushExpr(arg);
            },
            .lookup_local, .lookup_external, .lookup_required => {
                if (data == .lookup_local) try self.selectLookupTarget(expr_id);
            },
            .runtime_error => |runtime_error| {
                for (runtime_error.evaluated) |operand| try self.pushExpr(operand);
            },
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .crash,
            .ellipsis,
            .anno_only,
            => {},
        }
        self.endChildren(children);
    }

    fn exitExpr(self: *NestedProcSiteScan, exit: ExprExit) void {
        self.open_sites.items.len = exit.open_site_mark;
        self.current_scope = exit.previous_scope;
    }

    /// Push a static-dispatch plan's checked operands among the children
    /// currently being pushed.
    fn pushStaticDispatchPlanArgs(
        self: *NestedProcSiteScan,
        plan_id: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedModuleInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushExpr(expr),
            .generated_interpolation_segments => |expr| try self.pushWork(.{ .generated_interpolation_segments = .{ .id = expr } }),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
    }

    fn pushInterpolationChildren(
        self: *NestedProcSiteScan,
        expr_id: CIR.Expr.Idx,
    ) Allocator.Error!void {
        const data = self.bodies.exprData(expr_id);
        if (data != .interpolation) {
            checkedModuleInvariant("generated interpolation segments operand pointed at non-interpolation expression", .{});
        }
        const interpolation = data.interpolation;
        const children = self.beginChildren();
        try self.pushExpr(interpolation.first);
        for (interpolation.parts) |part| try self.pushExpr(part);
        self.endChildren(children);
    }

    fn enterPattern(
        self: *NestedProcSiteScan,
        pattern_id: CIR.Pattern.Idx,
    ) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.patternData(pattern_id);
        switch (data) {
            .assign, .as => try self.recordBinderSite(pattern_id),
            .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => {},
        }
        const children = self.beginChildren();
        switch (data) {
            .as => |as| try self.pushPattern(as.pattern),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.pushPattern(arg);
            },
            .nominal => |nominal| try self.pushPattern(nominal.backing_pattern),
            .record_destructure => |destructs| {
                for (destructs) |destruct| try self.pushPattern(bodies.recordDestructPattern(destruct));
            },
            .list => |list| {
                for (list.patterns) |child| try self.pushPattern(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.pushPattern(child);
                }
            },
            .tuple => |items| {
                for (items) |child| try self.pushPattern(child);
            },
            .str_interpolation => |str| {
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushPattern(capture);
                }
            },
            .numeral_literal,
            .str_literal,
            .assign,
            .underscore,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    fn enterStatement(
        self: *NestedProcSiteScan,
        statement_id: CIR.Statement.Idx,
    ) Allocator.Error!void {
        const children = self.beginChildren();
        switch (self.bodies.statementData(statement_id)) {
            .decl => |decl| {
                try self.pushPattern(decl.pattern);
                try self.pushExpr(decl.expr);
            },
            // The promoted procedure's sites belong to its own template.
            .promoted_proc => {},
            .var_ => |var_| {
                try self.pushPattern(var_.pattern);
                try self.pushExpr(var_.expr);
            },
            .var_uninitialized => |var_| {
                try self.pushPattern(var_.pattern);
            },
            .reassign => |reassign| {
                try self.pushPattern(reassign.pattern);
                try self.pushExpr(reassign.expr);
            },
            inline .dbg, .expr, .expect => |child| try self.pushExpr(child),
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushExpr(ret.expr);
            },
            .for_ => |for_| {
                try self.pushPattern(for_.pattern);
                try self.pushExpr(for_.expr);
                try self.pushExpr(for_.body);
            },
            inline .while_, .infinite_loop, .breakable_loop => |while_| {
                try self.pushExpr(while_.cond);
                try self.pushExpr(while_.body);
            },
            // A local type's associated values are declarations of the
            // enclosing block in their own right (canonicalization adds each
            // one as a block statement), so the walk reaches their procedures
            // there.
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .crash,
            .rejected_method_decl,
            .break_,
            .import_,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    /// Enter the body of the site `addSite` just recorded.
    fn openSite(self: *NestedProcSiteScan) Allocator.Error!void {
        try self.open_sites.append(self.allocator, @intCast(self.sites.items.len - 1));
    }

    fn innermostOpenSite(self: *const NestedProcSiteScan) ?u32 {
        return self.open_sites.getLastOrNull();
    }

    fn recordBinderSite(self: *NestedProcSiteScan, binder: CIR.Pattern.Idx) Allocator.Error!void {
        try self.binders.append(self.allocator, .{ .binder = binder, .site = self.innermostOpenSite() });
    }

    /// Record that the innermost open site's own body selects the local
    /// procedure whose lambda or closure is `proc_expr`. The owner's body
    /// holds every binder a procedure it selects needs, so a selection
    /// outside every site records nothing.
    fn selectLocalProc(self: *NestedProcSiteScan, proc_expr: CIR.Expr.Idx) Allocator.Error!void {
        const site = self.innermostOpenSite() orelse return;
        try self.selections.append(self.allocator, .{ .site = site, .proc_expr = proc_expr });
    }

    fn selectLookupTarget(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const refs = self.resolved_value_refs;
        const id = refs.lookupIdByExpr(expr_id) orelse return;
        switch (refs.callableTarget(id).ref) {
            .local_proc => |local| try self.selectLocalProc(local.expr),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
    }

    fn finish(self: *NestedProcSiteScan) Allocator.Error!*OwnerNestedProcSites {
        const allocator = self.allocator;
        const by_expr = try allocator.alloc(u32, self.sites.items.len);
        errdefer allocator.free(by_expr);
        for (by_expr, 0..) |*position, index| position.* = @intCast(index);
        const sites = self.sites.items;
        std.mem.sort(u32, by_expr, sites, struct {
            fn lessThan(all: []const NestedProcSite, left: u32, right: u32) bool {
                return @backingInt(all[left].checked_expr) < @backingInt(all[right].checked_expr);
            }
        }.lessThan);
        for (by_expr[0..by_expr.len -| 1], by_expr[@min(1, by_expr.len)..]) |left, right| {
            if (sites[left].checked_expr == sites[right].checked_expr) {
                checkedModuleInvariant("an owner's body constructed two nested procedures at one expression", .{});
            }
        }
        const result = try allocator.create(OwnerNestedProcSites);
        errdefer allocator.destroy(result);
        const owned_sites = try self.sites.toOwnedSlice(allocator);
        errdefer allocator.free(owned_sites);
        const parents = try self.parents.toOwnedSlice(allocator);
        errdefer allocator.free(parents);
        const binders = try self.binders.toOwnedSlice(allocator);
        errdefer allocator.free(binders);
        result.* = .{
            .sites = owned_sites,
            .by_expr = by_expr,
            .parents = parents,
            .binders = binders,
            .selections = try self.selections.toOwnedSlice(allocator),
        };
        return result;
    }
};

/// The nested procedure sites `owner`'s body constructs, scanned from
/// `bodies` (design.md "On-Demand Analyses And Write-Once Slots").
pub fn computeOwnerNestedProcSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    owner: NestedProcSiteOwner,
) Allocator.Error!*OwnerNestedProcSites {
    const dispatch = bodies.tables.dispatch orelse checkedModuleInvariant("nested procedure sites were scanned from bodies without dispatch", .{});
    const source = dispatch.source;
    var scan = NestedProcSiteScan{
        .allocator = allocator,
        .bodies = bodies,
        .dispatch = dispatch,
        .static_dispatch_plans = source.plans,
        .resolved_value_refs = source.refs,
        .dispatch_scopes = source.templates.dispatch_scopes,
        .scope_by_checked_expr = scope_by_checked_expr,
    };
    defer scan.deinit();
    switch (owner) {
        .template => |template_ref| switch (source.templates.get(template_ref.template).body) {
            .checked_body => |root_expr| try scan.scanExpr(root_expr, true),
            .entry_wrapper => |wrapper_id| {
                const wrapper = source.entry_wrappers.get(wrapper_id);
                try scan.scanEntryWrapper(source.compile_time_roots.root(wrapper.root));
            },
            .literal_root => checkedModuleInvariant("a literal root's entry wrapper is a row of the template table", .{}),
            .intrinsic_wrapper, .unimplemented => {},
        },
        // Unlike a template body, whose root lambda is the procedure
        // itself, a default's root lambda is an ordinary nested function
        // value, so the default's root is a site.
        .default_root => |default| try scan.scanExpr(default, false),
    }
    return scan.finish();
}

/// The module's nested procedure sites by expression with their runtime
/// captures, from every owner's sites: each template's in template order,
/// then each defaulted-field default's. A procedure's runtime captures are
/// its own captures, then every binder of an enclosing frame that
/// constructing a local procedure it selects requires, directly or through
/// a site nested in it. A selected procedure needs its own runtime
/// captures, so this is the least fixpoint of that relation, with each site
/// keeping only the binders its own body does not bind. The relation is a
/// function of the site expressions alone, and it crosses owners: a
/// promoted local procedure's body selects local procedures its enclosing
/// template's body declares.
pub fn computeModuleNestedProcSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    analyses: *ModuleAnalyses,
) Allocator.Error!*ModuleNestedProcSites {
    const templates = bodies.tables.templates orelse checkedModuleInvariant("nested procedure sites were computed without the module's templates", .{});
    const defaults = bodies.index().defaults;
    const owners = try allocator.alloc(*const OwnerNestedProcSites, templates.templates.items.len + defaults.len);
    defer allocator.free(owners);
    for (templates.templates.items, owners[0..templates.templates.items.len]) |template, *owner| {
        owner.* = try analyses.nestedProcSites(bodies, .{ .template = .{ .proc_base = template.proc_base, .template = template.template_id } });
    }
    for (defaults, owners[templates.templates.items.len..]) |default, *owner| {
        owner.* = try analyses.nestedProcSites(bodies, .{ .default_root = @fromBackingInt(default) });
    }

    // Every owner's site expressions, grouped by expression in owner order.
    const Occurrence = struct {
        expr: CIR.Expr.Idx,
        template: ?canonical.CheckedProcedureTemplateId,

        fn lessThan(_: void, left: @This(), right: @This()) bool {
            return @backingInt(left.expr) < @backingInt(right.expr);
        }
    };
    var occurrences = std.ArrayList(Occurrence).empty;
    defer occurrences.deinit(allocator);
    for (owners, 0..) |owner, owner_index| {
        const template: ?canonical.CheckedProcedureTemplateId = if (owner_index < templates.templates.items.len) @fromBackingInt(@intCast(owner_index)) else null;
        for (owner.sites) |site| try occurrences.append(allocator, .{ .expr = site.checked_expr, .template = template });
    }
    std.mem.sortUnstable(Occurrence, occurrences.items, {}, Occurrence.lessThan);
    var exprs = std.ArrayList(CIR.Expr.Idx).empty;
    defer exprs.deinit(allocator);
    var first_templates = std.ArrayList(?canonical.CheckedProcedureTemplateId).empty;
    defer first_templates.deinit(allocator);
    var owner_counts = std.ArrayList(u32).empty;
    defer owner_counts.deinit(allocator);
    for (occurrences.items) |occurrence| {
        const last = exprs.items.len;
        if (last != 0 and exprs.items[last - 1] == occurrence.expr) {
            owner_counts.items[last - 1] += 1;
            if (occurrence.template) |template| {
                const first = &first_templates.items[last - 1];
                if (first.* == null or @backingInt(template) < @backingInt(first.*.?)) first.* = template;
            }
            continue;
        }
        try exprs.append(allocator, occurrence.expr);
        try first_templates.append(allocator, occurrence.template);
        try owner_counts.append(allocator, 1);
    }
    const count = exprs.items.len;
    const lookup = ModuleNestedProcSites{ .exprs = exprs.items };

    // The lexical facts of the site expressions, merged over owners: an
    // owner's scan starts below its own root, so where one owner's site has
    // no enclosing site another owner's may.
    const parents = try allocator.alloc(?u32, count);
    defer allocator.free(parents);
    @memset(parents, null);
    var binder_sites = collections.DenseMap(CIR.Pattern.Idx, ?u32).init(allocator);
    defer binder_sites.deinit();
    const Selection = struct { site: u32, proc_expr: CIR.Expr.Idx };
    var selections = std.ArrayList(Selection).empty;
    defer selections.deinit(allocator);
    for (owners) |owner| {
        for (owner.sites, owner.parents) |site, maybe_parent| {
            const parent = maybe_parent orelse continue;
            const child_position = lookup.position(site.checked_expr).?;
            const parent_position: u32 = @intCast(lookup.position(owner.sites[parent].checked_expr).?);
            if (parents[child_position]) |existing| {
                if (existing != parent_position) checkedModuleInvariant("two owners disagreed on a nested procedure site's enclosing site", .{});
            }
            parents[child_position] = parent_position;
        }
        for (owner.binders) |bound| {
            const position: ?u32 = if (bound.site) |site| @intCast(lookup.position(owner.sites[site].checked_expr).?) else null;
            const entry = try binder_sites.getOrPut(bound.binder);
            if (!entry.found_existing or entry.value_ptr.* == null) {
                entry.value_ptr.* = position;
            } else if (position) |found| {
                if (entry.value_ptr.*.? != found) checkedModuleInvariant("two owners disagreed on the site binding a binder", .{});
            }
        }
        for (owner.selections) |selection| {
            try selections.append(allocator, .{ .site = @intCast(lookup.position(owner.sites[selection.site].checked_expr).?), .proc_expr = selection.proc_expr });
        }
    }

    // Each closure site's lambda, through which a selection names the
    // closure's site.
    var closure_lambdas = std.ArrayList(ModuleNestedProcSites.ClosureLambda).empty;
    defer closure_lambdas.deinit(allocator);
    for (exprs.items) |expr| {
        const data = bodies.exprData(expr);
        if (data == .closure) try closure_lambdas.append(allocator, .{ .lambda = data.closure.lambda, .closure = expr });
    }
    std.mem.sortUnstable(ModuleNestedProcSites.ClosureLambda, closure_lambdas.items, {}, struct {
        fn lessThan(_: void, left: ModuleNestedProcSites.ClosureLambda, right: ModuleNestedProcSites.ClosureLambda) bool {
            return @backingInt(left.lambda) < @backingInt(right.lambda);
        }
    }.lessThan);
    const with_lambdas = ModuleNestedProcSites{ .exprs = exprs.items, .closure_lambdas = closure_lambdas.items };

    const needs = try allocator.alloc(std.ArrayList(CIR.Pattern.Idx), count);
    defer allocator.free(needs);
    for (needs) |*need| need.* = .empty;
    defer for (needs) |*need| need.deinit(allocator);
    for (exprs.items, needs) |expr, *need| {
        for (ownSiteCaptures(bodies, expr)) |capture| _ = try insertSortedBinder(allocator, need, checkedSiteCapture(bodies, capture).pattern);
    }

    const Fixpoint = struct {
        parents: []const ?u32,
        binder_sites: *const collections.DenseMap(CIR.Pattern.Idx, ?u32),

        /// Whether the body of `site`, or of a site nested in it, binds `binder`.
        fn boundWithin(self: @This(), site: u32, binder: CIR.Pattern.Idx) bool {
            var current = self.binder_sites.get(binder) orelse
                checkedModuleInvariant("nested procedure runtime capture named a binder no scanned pattern binds", .{});
            while (current) |candidate| {
                if (candidate == site) return true;
                current = self.parents[candidate];
            }
            return false;
        }
    };
    const fixpoint = Fixpoint{ .parents = parents, .binder_sites = &binder_sites };
    var changed = true;
    while (changed) {
        changed = false;
        for (selections.items) |selection| {
            const proc_site = with_lambdas.position(selection.proc_expr) orelse continue;
            var index: usize = 0;
            while (index < needs[proc_site].items.len) : (index += 1) {
                const binder = needs[proc_site].items[index];
                if (fixpoint.boundWithin(selection.site, binder)) continue;
                if (try insertSortedBinder(allocator, &needs[selection.site], binder)) changed = true;
            }
        }
        for (parents, 0..) |maybe_parent, child| {
            const parent = maybe_parent orelse continue;
            var index: usize = 0;
            while (index < needs[child].items.len) : (index += 1) {
                const binder = needs[child].items[index];
                if (fixpoint.boundWithin(parent, binder)) continue;
                if (try insertSortedBinder(allocator, &needs[parent], binder)) changed = true;
            }
        }
    }

    var pool = std.ArrayList(CheckedCapture).empty;
    defer pool.deinit(allocator);
    const capture_spans = try allocator.alloc(store_serialize.Span, count);
    errdefer allocator.free(capture_spans);
    for (exprs.items, needs, capture_spans) |expr, need, *span| {
        const start: u32 = @intCast(pool.items.len);
        const own = ownSiteCaptures(bodies, expr);
        for (own) |capture| try pool.append(allocator, checkedSiteCapture(bodies, capture));
        for (need.items) |binder| {
            const already_own = for (own) |capture| {
                if (checkedSiteCapture(bodies, capture).pattern == binder) break true;
            } else false;
            if (already_own) continue;
            try pool.append(allocator, .{
                .pattern = binder,
                .scope_depth = 0,
                .capture_id = CaptureId.fromBinder(binder),
            });
        }
        span.* = .{ .start = start, .len = @as(u32, @intCast(pool.items.len)) - start };
    }

    const result = try allocator.create(ModuleNestedProcSites);
    errdefer allocator.destroy(result);
    const owned_exprs = try exprs.toOwnedSlice(allocator);
    errdefer allocator.free(owned_exprs);
    const owned_first_templates = try first_templates.toOwnedSlice(allocator);
    errdefer allocator.free(owned_first_templates);
    const owned_owner_counts = try owner_counts.toOwnedSlice(allocator);
    errdefer allocator.free(owned_owner_counts);
    const owned_captures = try pool.toOwnedSlice(allocator);
    errdefer allocator.free(owned_captures);
    result.* = .{
        .exprs = owned_exprs,
        .first_templates = owned_first_templates,
        .owner_counts = owned_owner_counts,
        .capture_spans = capture_spans,
        .captures = owned_captures,
        .closure_lambdas = try closure_lambdas.toOwnedSlice(allocator),
    };
    return result;
}

fn ownSiteCaptures(bodies: CheckedBodies, expr: CIR.Expr.Idx) []const CIR.Expr.Capture.Idx {
    const data = bodies.exprData(expr);
    return if (data == .closure) data.closure.captures else &.{};
}

fn checkedSiteCapture(bodies: CheckedBodies, capture_idx: CIR.Expr.Capture.Idx) CheckedCapture {
    const capture = bodies.capture(capture_idx);
    if (!patternBindsName(bodies.env, capture.pattern)) {
        checkedModuleInvariant("nested procedure capture referenced a non-binding pattern", .{});
    }
    return .{ .pattern = capture.pattern, .scope_depth = capture.scope_depth, .capture_id = capture.capture_id };
}

/// Add `binder` to the sorted set `set`; whether it was absent.
fn insertSortedBinder(allocator: Allocator, set: *std.ArrayList(CIR.Pattern.Idx), binder: CIR.Pattern.Idx) Allocator.Error!bool {
    const index = std.sort.lowerBound(CIR.Pattern.Idx, set.items, binder, struct {
        fn order(key: CIR.Pattern.Idx, item: CIR.Pattern.Idx) std.math.Order {
            return std.math.order(@backingInt(key), @backingInt(item));
        }
    }.order);
    if (index < set.items.len and set.items[index] == binder) return false;
    try set.insert(allocator, index, binder);
    return true;
}

/// Public `HostedProc` declaration.
pub const HostedProc = struct {
    module_idx: u32,
    def_idx: CIR.Def.Idx,
    expr_idx: CIR.Expr.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
    deterministic_index: u32,
    /// Range into `HostedProcTable.order_key_bytes`.
    order_key_start: u32,
    order_key_len: u32,
    proc: canonical.ProcedureValueRef,
    template: canonical.ProcedureTemplateRef,

    /// The proc's deterministic ordering key bytes within its table's pool.
    pub fn orderKey(self: HostedProc, table: *const HostedProcTable) []const u8 {
        return table.order_key_bytes[self.order_key_start .. self.order_key_start + self.order_key_len];
    }
};

/// A module's hosted procedures (`ModuleAnalyses.hostedProcs`).
pub const HostedProcTable = struct {
    procs: []HostedProc = &.{},
    /// Flat pool of every proc's order-key bytes.
    order_key_bytes: []const u8 = &.{},

    pub fn deinit(self: *HostedProcTable, allocator: Allocator) void {
        allocator.free(self.procs);
        allocator.free(self.order_key_bytes);
        self.* = .{};
    }

    /// The hosted procedure of definition `def_idx`, if it is one.
    pub fn forDef(self: *const HostedProcTable, def_idx: CIR.Def.Idx) ?HostedProc {
        for (self.procs) |proc| {
            if (proc.def_idx == def_idx) return proc;
        }
        return null;
    }
};

/// Whether `env` declares a hosted procedure: a definition the hosted
/// transform rewrote to a hosted lambda.
pub fn declaresHostedProceduresIn(env: *const ModuleEnv) bool {
    for (env.store.sliceDefs(env.hosted_defs)) |def_idx| {
        if (env.store.getExpr(env.store.getDef(def_idx).expr) == .e_hosted_lambda) return true;
    }
    return false;
}

/// The external symbol names a module's hosted procedures and hosted section
/// entries name, interned into its name store before any slot reads them.
fn internHostedSymbolNames(env: *const ModuleEnv, names: *canonical.CanonicalNameStore) Allocator.Error!void {
    for (env.store.sliceDefs(env.hosted_defs)) |def_idx| {
        const expr = env.store.getExpr(env.store.getDef(def_idx).expr);
        if (expr != .e_hosted_lambda) continue;
        _ = try names.internExternalSymbolIdent(env.getIdentStoreConst(), expr.e_hosted_lambda.symbol_name);
    }
    if (env.module_kind != .platform) return;
    for (env.hosted_entries.items.items) |entry| {
        if (entry.target_status != .resolved or entry.target_def == null) continue;
        _ = try names.internExternalSymbolName(env.getString(entry.symbol));
    }
}

/// The hosted procedures of `owner` (`ModuleAnalyses.hostedProcs`): each
/// definition the hosted transform rewrote to a hosted lambda, ordered by its
/// qualified symbol name without a trailing `!`, then by definition.
pub fn computeHostedProcs(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!*HostedProcTable {
    const env = owner.module_env;
    const Candidate = struct {
        def_idx: CIR.Def.Idx,
        expr_idx: CIR.Expr.Idx,
        external_symbol_name: canonical.ExternalSymbolNameId,
        template: canonical.ProcedureTemplateRef,
        sort_key: []const u8,
    };
    var candidates = std.ArrayList(Candidate).empty;
    defer {
        for (candidates.items) |candidate| allocator.free(candidate.sort_key);
        candidates.deinit(allocator);
    }

    for (env.store.sliceDefs(env.hosted_defs)) |def_idx| {
        const def = env.store.getDef(def_idx);
        const expr = env.store.getExpr(def.expr);
        if (expr != .e_hosted_lambda) continue;
        const symbol_name = expr.e_hosted_lambda.symbol_name;
        const template_ref = (try owner.checkedTables()).checked_procedure_templates.lookupByDef(def_idx) orelse
            checkedModuleInvariant("hosted procedure def has no checked template", .{});
        const sort_key = try hostedProcSortKey(allocator, env, symbol_name);
        errdefer allocator.free(sort_key);
        try candidates.append(allocator, .{
            .def_idx = def_idx,
            .expr_idx = def.expr,
            .external_symbol_name = owner.canonical_names.lookupExternalSymbolIdent(env.getIdentStoreConst(), symbol_name) orelse
                checkedModuleInvariant("a hosted procedure's symbol name was not interned into its module's names", .{}),
            .template = template_ref,
            .sort_key = sort_key,
        });
    }

    std.mem.sort(Candidate, candidates.items, {}, struct {
        fn lessThan(_: void, a: Candidate, b: Candidate) bool {
            return switch (std.mem.order(u8, a.sort_key, b.sort_key)) {
                .lt => true,
                .gt => false,
                .eq => @backingInt(a.def_idx) < @backingInt(b.def_idx),
            };
        }
    }.lessThan);

    const procs = try allocator.alloc(HostedProc, candidates.items.len);
    errdefer allocator.free(procs);
    var order_key_len: usize = 0;
    for (candidates.items) |candidate| order_key_len += candidate.sort_key.len;
    const order_key_bytes = try allocator.alloc(u8, order_key_len);
    errdefer allocator.free(order_key_bytes);
    var order_key_start: usize = 0;
    for (candidates.items, procs, 0..) |candidate, *proc, index| {
        @memcpy(order_key_bytes[order_key_start..][0..candidate.sort_key.len], candidate.sort_key);
        proc.* = .{
            .module_idx = owner.module_identity.module_idx,
            .def_idx = candidate.def_idx,
            .expr_idx = candidate.expr_idx,
            .external_symbol_name = candidate.external_symbol_name,
            .deterministic_index = @intCast(index),
            .order_key_start = @intCast(order_key_start),
            .order_key_len = @intCast(candidate.sort_key.len),
            .proc = .{ .module = candidate.template.module, .proc_base = candidate.template.proc_base },
            .template = candidate.template,
        };
        order_key_start += candidate.sort_key.len;
    }
    const result = try allocator.create(HostedProcTable);
    result.* = .{ .procs = procs, .order_key_bytes = order_key_bytes };
    return result;
}

fn hostedProcSortKey(allocator: Allocator, env: *const ModuleEnv, symbol_name: Ident.Idx) Allocator.Error![]const u8 {
    var module_name = env.module_name;
    if (Ident.textEndsWith(module_name, ".roc")) {
        module_name = module_name[0 .. module_name.len - 4];
    }
    const local_name = env.getIdent(symbol_name);
    const trimmed = if (Ident.textEndsWith(local_name, "!")) local_name[0 .. local_name.len - 1] else local_name;
    return std.fmt.allocPrint(allocator, "{s}.{s}", .{ module_name, trimmed });
}

/// One platform-header hosted binding. Slice order is the host dispatch index.
pub const HostedBinding = struct {
    target_checked_module: CheckedModuleDigest,
    target_def: CIR.Def.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
};

/// Exact platform-header bindings from external symbols to checked hosted
/// defs (`ModuleAnalyses.hostedBindings`).
pub const HostedBindingTable = struct {
    bindings: []HostedBinding = &.{},

    pub fn deinit(self: *HostedBindingTable, allocator: Allocator) void {
        allocator.free(self.bindings);
        self.* = .{};
    }
};

/// The hosted bindings of `owner` (`ModuleAnalyses.hostedBindings`): for a
/// platform, each resolved entry of its hosted section in header order whose
/// target is a hosted procedure, of the module the entry's import names or,
/// for an entry naming no import, of the platform itself. Any other module
/// binds nothing. `resolver` resolves the platform's direct imports.
pub fn computeHostedBindings(allocator: Allocator, owner: ImportedModuleView, resolver: ?ModuleResolver) Allocator.Error!*HostedBindingTable {
    const env = owner.module_env;
    var bindings = std.ArrayList(HostedBinding).empty;
    errdefer bindings.deinit(allocator);
    if (env.module_kind == .platform) {
        for (env.hosted_entries.items.items) |entry| {
            if (entry.target_status != .resolved) continue;
            const target_def = entry.target_def orelse continue;
            const target_module = if (entry.target_import) |import_idx| blk: {
                const key = owner.importKey(import_idx) orelse continue;
                const imported = (resolver orelse checkedModuleInvariant("a platform's hosted bindings were read without a resolver for its imports", .{})).require(key.digest());
                if ((try imported.hostedProcs()).forDef(target_def) == null) continue;
                break :blk key.digest();
            } else blk: {
                // No import means the entry named this module's own
                // declaration, which is a hosted procedure only if the hosted
                // transform rewrote it.
                if ((try owner.hostedProcs()).forDef(target_def) == null) continue;
                break :blk owner.key.digest();
            };
            try bindings.append(allocator, .{
                .target_checked_module = target_module,
                .target_def = target_def,
                .external_symbol_name = owner.canonical_names.lookupExternalSymbolName(env.getString(entry.symbol)) orelse
                    checkedModuleInvariant("a hosted section entry's symbol name was not interned into its module's names", .{}),
            });
        }
    }
    const owned = try bindings.toOwnedSlice(allocator);
    errdefer allocator.free(owned);
    const result = try allocator.create(HostedBindingTable);
    result.* = .{ .bindings = owned };
    return result;
}

/// Public `PlatformAppRelationKey` declaration.
pub const PlatformAppRelationKey = struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    pub fn compute(
        app_module: ModuleId,
        requirement_context: PlatformRequirementContextKey,
    ) PlatformAppRelationKey {
        var hasher = base.Sha256.init(.{});
        hasher.update(&app_module.bytes);
        hasher.update(&requirement_context.bytes);
        return .{ .bytes = hasher.finalResult() };
    }
};

/// Public `PlatformRequiredDeclarationId` declaration.
pub const PlatformRequiredDeclarationId = enum(u32) { _ };
/// Public `PlatformRequiredBindingId` declaration.
pub const PlatformRequiredBindingId = enum(u32) { _ };
/// Public `PlatformRequirementRelationId` declaration.
pub const PlatformRequirementRelationId = enum(u32) { _ };

/// Public `PlatformRequiredValueKind` declaration.
pub const PlatformRequiredValueKind = enum {
    const_value,
    procedure_value,
};

/// Public `PlatformRequiredDeclaration` declaration.
pub const PlatformRequiredDeclaration = struct {
    id: PlatformRequiredDeclarationId,
    module_idx: u32,
    requires_idx: u32,
    /// The declared type's annotation; its scheme key is computed when an
    /// identity needs it (`PlatformRequiredDeclarationTable.identityHash`).
    type_anno: CIR.TypeAnno.Idx,
};

/// The requirement declarations of a platform module, read from its
/// `requires` clause: declaration `i` is requirement `i`. Empty for every
/// other module.
pub const PlatformRequiredDeclarationTable = struct {
    env: ?*const ModuleEnv = null,
    module_idx: u32 = 0,

    pub fn count(self: PlatformRequiredDeclarationTable) usize {
        const env = self.env orelse return 0;
        return env.requires_types.items.items.len;
    }

    pub fn get(self: PlatformRequiredDeclarationTable, requires_idx: usize) PlatformRequiredDeclaration {
        const env = self.env orelse checkedModuleInvariant("a platform requirement declaration was read from a module with none", .{});
        return .{
            .id = @fromBackingInt(@intCast(requires_idx)),
            .module_idx = self.module_idx,
            .requires_idx = @intCast(requires_idx),
            .type_anno = env.requires_types.items.items[requires_idx].type_anno,
        };
    }

    pub fn lookupByRequiredIndex(self: PlatformRequiredDeclarationTable, requires_idx: u32) ?PlatformRequiredDeclaration {
        if (requires_idx >= self.count()) return null;
        return self.get(requires_idx);
    }

    pub fn lookupByDeclarationId(self: PlatformRequiredDeclarationTable, declaration_id: PlatformRequiredDeclarationId) ?PlatformRequiredDeclaration {
        return self.lookupByRequiredIndex(@backingInt(declaration_id));
    }

    /// The declarations' identity: each one's name, the scheme key of its
    /// declared type in `types` (the platform's checked types), and its
    /// for-clause aliases.
    pub fn identityHash(self: PlatformRequiredDeclarationTable, type_view: CheckedTypeStoreView) Allocator.Error![32]u8 {
        var hasher = base.Sha256.init(.{});
        hashByteSlice(&hasher, "platform_required_declarations");
        hashU32(&hasher, @intCast(self.count()));
        const env = self.env orelse return hasher.finalResult();
        for (env.requires_types.items.items, 0..) |required_type, requires_idx| {
            hashU32(&hasher, @intCast(requires_idx));
            hashByteSlice(&hasher, env.getIdent(required_type.ident));
            const declared = type_view.sourceTypeRoot(ModuleEnv.varFrom(required_type.type_anno)) orelse
                checkedModuleInvariant("a platform requirement's declared type was not published", .{});
            hasher.update(&canonical_type_keys.schemeKeyForType(try type_view.rootKey(declared)).bytes);
            hasher.update(&hashRequiredTypeForClauseAliases(env, required_type));
        }
        return hasher.finalResult();
    }
};

fn hashRequiredTypeForClauseAliases(
    module_env: *const ModuleEnv,
    required_type: ModuleEnv.RequiredType,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashByteSlice(&hasher, "platform_required_for_clause_aliases");
    const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
    hashU32(&hasher, @intCast(aliases.len));
    for (aliases) |alias| {
        hashByteSlice(&hasher, module_env.getIdent(alias.alias_name));
        hashByteSlice(&hasher, module_env.getIdent(alias.rigid_name));
    }
    return hasher.finalResult();
}

/// Public `PlatformRequiredProcedureUse` declaration.
pub const PlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredConstUse` declaration.
pub const PlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredValueUse` declaration.
pub const PlatformRequiredValueUse = union(enum) {
    const_value: PlatformRequiredConstUse,
    procedure_value: PlatformRequiredProcedureUse,

    pub fn tag(self: PlatformRequiredValueUse) PlatformRequiredValueUseKind {
        return switch (self) {
            .const_value => .const_value,
            .procedure_value => .procedure_value,
        };
    }
};

/// Discriminant of `PlatformRequiredValueUse` / `StoredPlatformRequiredValueUse`.
pub const PlatformRequiredValueUseKind = enum { const_value, procedure_value };

/// Relocation-invariant (POD) mirror of `PlatformRequiredProcedureUse`.
pub const StoredPlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// Relocation-invariant (POD) mirror of `PlatformRequiredConstUse`.
pub const StoredPlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// POD mirror of `PlatformRequiredValueUse`: closures live as ranges into the
/// owning `PlatformRequiredBindingTable`'s `ClosurePool`. Stored by value in each
/// `PlatformRequiredBinding` row. A real tagged union (not a discriminant + two fixed
/// fields), so only the active variant's bytes exist—there is no inactive field to
/// leave `undefined`, and the serializer's union-padding zeroing keeps the blob
/// byte-deterministic.
pub const StoredPlatformRequiredValueUse = union(PlatformRequiredValueUseKind) {
    const_value: StoredPlatformRequiredConstUse,
    procedure_value: StoredPlatformRequiredProcedureUse,
};

/// Public `PlatformRequirementRelationInput` declaration.
pub const PlatformRequirementRelationInput = struct {
    id: PlatformRequirementRelationId,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    value_kind: PlatformRequiredValueKind,
    /// The app-store checked root the checker solved this requirement's type to.
    solved_root_app: CheckedTypeId,
    /// Root-call dispatch evidence in the app module's platform requirement
    /// root evidence.
    root_evidence: static_dispatch.EvidenceSpan = .{},
    /// Range into the owning `PlatformAppRelation.identity_solutions_app`: the
    /// app-store solved roots of this requirement's identity variables, in
    /// canonical identity-slot order.
    identity_start: u32,
    identity_len: u32,
};

/// Public `PlatformRequiredBindingInput` declaration.
pub const PlatformRequiredBindingInput = struct {
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    checked_relation: PlatformRequirementRelationId,
    value_use: PlatformRequiredValueUse,
};

/// Public `PlatformAppRelation` declaration.
pub const PlatformAppRelation = struct {
    key: PlatformAppRelationKey,
    requirement_context: PlatformRequirementContextKey,
    platform_module_idx: u32,
    app_module: CheckedModuleDigest,
    relations: []const PlatformRequirementRelationInput,
    bindings: []const PlatformRequiredBindingInput,
    /// Requires-clause indices whose app-side requirement check failed. These
    /// are explicit checked-error facts: platform required lookups at these
    /// indices lower to a runtime crash, while successful sibling bindings
    /// remain fully linked.
    checked_error_requires: []const u32,
    /// Borrowed app-store roots in the checker's canonical identity-slot order.
    /// The app module owns these roots and each binding's template closure;
    /// it must outlive the relation and pairing that consume them.
    identity_solutions_app: []const CheckedTypeId,

    pub fn deinit(self: *PlatformAppRelation, allocator: Allocator) void {
        allocator.free(self.relations);
        allocator.free(self.bindings);
        allocator.free(self.checked_error_requires);
        self.* = .{
            .key = .{},
            .requirement_context = .{},
            .platform_module_idx = 0,
            .app_module = .{},
            .relations = &.{},
            .bindings = &.{},
            .checked_error_requires = &.{},
            .identity_solutions_app = &.{},
        };
    }
};

/// Checked identities used to instantiate a platform against an app. These
/// rows are produced while source-to-checked mappings are alive; pairing never
/// walks source annotations or rediscovers identity-variable order.
pub const PlatformTypeInputs = struct {
    pub const Requirement = struct {
        declaration: PlatformRequiredDeclarationId,
        root: CheckedTypeId,
        identities: store_serialize.Span,
        aliases: store_serialize.Span,
    };
    pub const Alias = struct {
        root: CheckedTypeId,
        backing: CheckedTypeId,
        identity: CheckedTypeId,
    };
    requirements: []Requirement = &.{},
    identities: []CheckedTypeId = &.{},
    aliases: []Alias = &.{},

    pub fn deinit(self: *PlatformTypeInputs, allocator: Allocator) void {
        allocator.free(self.requirements);
        allocator.free(self.identities);
        allocator.free(self.aliases);
        self.* = .{};
    }
};

/// The requirement identity variables of `owner`, a platform: for each
/// requirement in `requires` order, its checked type root, the identity
/// variables that root reaches in key order, and its for-clause aliases.
pub fn computePlatformTypeInputs(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!*PlatformTypeInputs {
    const env = owner.module_env;
    const required_types = env.requires_types.items.items;
    const rows = try allocator.alloc(PlatformTypeInputs.Requirement, required_types.len);
    errdefer allocator.free(rows);
    var identities = std.ArrayList(CheckedTypeId).empty;
    errdefer identities.deinit(allocator);
    var aliases = std.ArrayList(PlatformTypeInputs.Alias).empty;
    errdefer aliases.deinit(allocator);
    const store = owner.checked_types.store orelse checkedModuleInvariant("a platform's type inputs were read from a view without a type store", .{});
    var orderer = CheckedIdentityOrderer.init(allocator, owner.canonical_names, store);
    defer orderer.deinit();
    for (required_types, rows, 0..) |required_type, *row, requires_idx| {
        const root = try reachedSourceRoot(owner, ModuleEnv.varFrom(required_type.type_anno)) orelse
            checkedModuleInvariant("a platform requirement has no checked type", .{});
        const formals = try orderer.identityRoots(root);
        const identity_start: u32 = @intCast(identities.items.len);
        try identities.appendSlice(allocator, formals);
        const alias_start: u32 = @intCast(aliases.items.len);
        for (env.for_clause_aliases.sliceRange(required_type.type_aliases)) |alias| {
            const anno = env.store.getStatement(alias.alias_stmt_idx).s_alias_decl.anno;
            const identity = try reachedSourceRoot(owner, ModuleEnv.varFrom(anno)) orelse
                checkedModuleInvariant("platform alias identity has no checked root", .{});
            const alias_root = try reachedSourceRoot(owner, ModuleEnv.varFrom(alias.alias_stmt_idx)) orelse
                checkedModuleInvariant("platform alias has no checked root", .{});
            const payload = store.payload(alias_root);
            try aliases.append(allocator, .{
                .root = alias_root,
                .backing = if (payload == .alias) payload.alias.backing else alias_root,
                .identity = identity,
            });
        }
        row.* = .{
            .declaration = @fromBackingInt(@intCast(requires_idx)),
            .root = root,
            .identities = .{ .start = identity_start, .len = @intCast(formals.len) },
            .aliases = .{ .start = alias_start, .len = @intCast(aliases.items.len - alias_start) },
        };
    }
    const owned_identities = try identities.toOwnedSlice(allocator);
    errdefer allocator.free(owned_identities);
    const owned_aliases = try aliases.toOwnedSlice(allocator);
    errdefer allocator.free(owned_aliases);
    const result = try allocator.create(PlatformTypeInputs);
    result.* = .{ .requirements = rows, .identities = owned_identities, .aliases = owned_aliases };
    return result;
}

/// The types of a platform read under one platform/app pairing (design.md
/// "Platform/App Composition"). Each requirement identity formal of the
/// platform, including each for-clause alias statement's roots, stands for
/// the app's solved actual. A read of a platform type under the pairing
/// resolves through that map on first demand: a type that reaches no formal
/// is its own image, and every other type's image is a synthesized type of
/// the platform's store, created once under the store's creation lock and
/// memoized here. The platform's store and names are never copied.
pub const PairingOverlay = struct {
    allocator: Allocator,
    io: std.Io,
    /// The platform's store, which holds every image.
    store: *CheckedTypeStore,
    formals: []CheckedTypeId = &.{},
    actuals: []CheckedTypeId = &.{},
    /// The number of source types the lock-free image column covers;
    /// synthesized types follow them.
    source_count: usize = 0,
    /// The published image of each type that existed when the pairing was
    /// created, by dense position (a source id, then a synthesized index
    /// after `source_count`); `unknown_image` until first demanded. Read
    /// without a lock; written after the creation that made the image ends.
    images: []std.atomic.Value(u32) = &.{},
    /// Read and written only under the store's creation lock: whether each
    /// type demanded so far reaches a formal, and the substitution's memo of
    /// each image created so far.
    reaching: collections.DenseMap(CheckedTypeId, bool),
    substitution: CheckedTypeSubstitution,

    const unknown_image = std.math.maxInt(u32);

    /// Map each identity formal of the platform's requirements to the app
    /// actual its solution records. The actuals are projected into the
    /// platform's store under its creation lock.
    fn init(
        self: *PairingOverlay,
        allocator: Allocator,
        io: std.Io,
        platform: *const CheckedModule,
        app: *const CheckedModule,
        relation: PlatformAppRelation,
    ) Allocator.Error!void {
        const store: *CheckedTypeStore = @constCast(&platform.checked_types);
        const names: *canonical.CanonicalNameStore = @constCast(&platform.canonical_names);
        try validatePlatformAppRelationForModule(platform.module_identity, platform.typesView(), platform.platformRequiredDeclarations(), relation);
        const type_inputs = try platform.platformTypeInputs();
        var identity_formals = std.ArrayList(CheckedTypeId).empty;
        defer identity_formals.deinit(allocator);
        var identity_actuals = std.ArrayList(CheckedTypeId).empty;
        defer identity_actuals.deinit(allocator);
        {
            store.beginCreation(io);
            errdefer store.endCreation(io);
            var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(allocator, store, names, importedView(app));
            defer projector.deinit();
            for (relation.relations) |input| {
                const required = type_inputs.requirements[@backingInt(input.declaration)];
                std.debug.assert(required.declaration == input.declaration);
                const formals = type_inputs.identities[required.identities.start..][0..required.identities.len];
                if (formals.len != input.identity_len) {
                    checkedModuleInvariant("platform/app relation identity slot count disagrees with the recorded solution", .{});
                }
                const app_roots = relation.identity_solutions_app[input.identity_start .. input.identity_start + input.identity_len];
                for (formals, app_roots) |formal, app_root| {
                    if (builtin.mode == .debug) std.debug.assert(checkedTypePayloadIsIdentity(store.payload(formal)));
                    try identity_formals.append(allocator, formal);
                    try identity_actuals.append(allocator, try projector.project(app_root));
                }
            }
            try store.finishCreation(allocator, io);
        }
        var formals = std.ArrayList(CheckedTypeId).empty;
        errdefer formals.deinit(allocator);
        var actuals = std.ArrayList(CheckedTypeId).empty;
        errdefer actuals.deinit(allocator);
        var next_identity: usize = 0;
        for (relation.relations) |input| {
            const required = type_inputs.requirements[@backingInt(input.declaration)];
            for (identity_formals.items[next_identity..][0..input.identity_len], identity_actuals.items[next_identity..][0..input.identity_len]) |formal, actual| {
                try recordRelationSubstitution(allocator, store, &formals, &actuals, formal, actual);
            }
            next_identity += input.identity_len;
            for (type_inputs.aliases[required.aliases.start..][0..required.aliases.len]) |alias| {
                const actual = relationSubstitutionActual(formals.items, actuals.items, alias.identity) orelse continue;
                try recordRelationSubstitution(allocator, store, &formals, &actuals, alias.root, actual);
                try recordRelationSubstitution(allocator, store, &formals, &actuals, alias.backing, actual);
                try recordRelationSubstitution(allocator, store, &formals, &actuals, alias.identity, actual);
            }
        }
        const owned_formals = try formals.toOwnedSlice(allocator);
        errdefer allocator.free(owned_formals);
        const owned_actuals = try actuals.toOwnedSlice(allocator);
        errdefer allocator.free(owned_actuals);
        self.* = .{
            .allocator = allocator,
            .io = io,
            .store = store,
            .formals = owned_formals,
            .actuals = owned_actuals,
            .reaching = collections.DenseMap(CheckedTypeId, bool).init(allocator),
            .substitution = CheckedTypeSubstitution.init(allocator, owned_formals, owned_actuals),
        };
        self.substitution.reaching = &self.reaching;
        errdefer {
            self.substitution.deinit();
            self.reaching.deinit();
        }
        if (owned_formals.len != 0) {
            self.source_count = store.sealed_var_facts.items.len;
            self.images = try allocator.alloc(std.atomic.Value(u32), self.source_count + store.payloads.items().len);
            @memset(self.images, .init(unknown_image));
        }
    }

    fn deinit(self: *PairingOverlay) void {
        self.substitution.deinit();
        self.reaching.deinit();
        self.allocator.free(self.images);
        self.allocator.free(self.actuals);
        self.allocator.free(self.formals);
    }

    fn position(self: *const PairingOverlay, own: CheckedTypeId) ?usize {
        const at = if (type_ids.isSynthesized(own)) self.source_count + type_ids.synthesizedIndex(own) else @backingInt(own);
        return if (at < self.images.len) at else null;
    }

    /// The type `own`, a type of the platform's store, reads as under the
    /// pairing.
    pub fn image(self: *PairingOverlay, own: CheckedTypeId) Allocator.Error!CheckedTypeId {
        if (self.formals.len == 0) return own;
        const at = self.position(own);
        if (at) |index| {
            const known = self.images[index].load(.acquire);
            if (known != unknown_image) {
                if (std.debug.runtime_safety) try self.assertImageFresh(own, @fromBackingInt(known));
                return @fromBackingInt(known);
            }
        }
        const result = blk: {
            self.store.beginCreation(self.io);
            errdefer self.store.endCreation(self.io);
            const created = try self.imageLocked(own);
            try self.store.finishCreation(self.allocator, self.io);
            break :blk created;
        };
        if (at) |index| self.images[index].store(@backingInt(result), .release);
        return result;
    }

    /// Debug check that the lock-free column, which covers the types that
    /// existed when the pairing was created, answers `own` with the image
    /// the locked memo computes for it now.
    fn assertImageFresh(self: *PairingOverlay, own: CheckedTypeId, known: CheckedTypeId) Allocator.Error!void {
        const fresh = if (self.store.createdOnThisThread()) try self.imageLocked(own) else fresh: {
            self.store.beginCreation(self.io);
            errdefer self.store.endCreation(self.io);
            const fresh = try self.imageLocked(own);
            try self.store.finishCreation(self.allocator, self.io);
            break :fresh fresh;
        };
        if (fresh != known) checkedModuleInvariant("a pairing's image column disagrees with the image its memo computes", .{});
    }

    /// The scheme `own`, a scheme of the platform's store, reads as under
    /// the pairing: the scheme of its root's image.
    pub fn schemeImage(self: *PairingOverlay, own: CheckedTypeSchemeId) Allocator.Error!CheckedTypeSchemeId {
        const root = self.store.scheme(own).root;
        const root_image = try self.image(root);
        if (root_image == root) return own;
        self.store.beginCreation(self.io);
        errdefer self.store.endCreation(self.io);
        const scheme = try self.store.ensureSchemeForRoot(self.allocator, root_image);
        try self.store.finishCreation(self.allocator, self.io);
        return scheme;
    }

    fn imageLocked(self: *PairingOverlay, own: CheckedTypeId) Allocator.Error!CheckedTypeId {
        try self.classifyReachLocked(own);
        if (!self.reaching.get(own).?) return own;
        return try self.store.cloneCheckedTypeRootSubstituting(self.allocator, own, &self.substitution);
    }

    /// Record whether `root` and every type it reaches reach a formal. The
    /// types not yet classified are collected with their child edges; a
    /// formal, and every collected type with a child that reaches one,
    /// reaches one.
    fn classifyReachLocked(self: *PairingOverlay, root: CheckedTypeId) Allocator.Error!void {
        if (self.reaching.contains(root)) return;
        const allocator = self.allocator;
        var collected = collections.DenseMap(CheckedTypeId, u32).init(allocator);
        defer collected.deinit();
        var nodes = std.ArrayList(CheckedTypeId).empty;
        defer nodes.deinit(allocator);
        var edge_starts = std.ArrayList(u32).empty;
        defer edge_starts.deinit(allocator);
        var children = std.ArrayList(CheckedTypeId).empty;
        defer children.deinit(allocator);
        try collected.put(root, 0);
        try nodes.append(allocator, root);
        var next: usize = 0;
        while (next < nodes.items.len) : (next += 1) {
            try edge_starts.append(allocator, @intCast(children.items.len));
            const before = children.items.len;
            try self.store.appendSubstitutionChildren(allocator, nodes.items[next], &children);
            for (children.items[before..]) |child| {
                if (self.reaching.contains(child) or collected.contains(child)) continue;
                try collected.put(child, @intCast(nodes.items.len));
                try nodes.append(allocator, child);
            }
        }
        try edge_starts.append(allocator, @intCast(children.items.len));

        var reaches = try std.DynamicBitSetUnmanaged.initEmpty(allocator, nodes.items.len);
        defer reaches.deinit(allocator);
        var parents = std.ArrayList(std.ArrayList(u32)).empty;
        defer {
            for (parents.items) |*list| list.deinit(allocator);
            parents.deinit(allocator);
        }
        try parents.appendNTimes(allocator, .empty, nodes.items.len);
        var pending = std.ArrayList(u32).empty;
        defer pending.deinit(allocator);
        for (nodes.items, 0..) |node, index| {
            var reached = self.isFormal(node);
            for (children.items[edge_starts.items[index]..edge_starts.items[index + 1]]) |child| {
                if (collected.get(child)) |child_index| {
                    try parents.items[child_index].append(allocator, @intCast(index));
                } else if (self.reaching.get(child).?) {
                    reached = true;
                }
            }
            if (reached) {
                reaches.set(index);
                try pending.append(allocator, @intCast(index));
            }
        }
        while (pending.pop()) |child| {
            for (parents.items[child].items) |parent| {
                if (reaches.isSet(parent)) continue;
                reaches.set(parent);
                try pending.append(allocator, parent);
            }
        }
        try self.reaching.ensureUnusedCapacity(@intCast(nodes.items.len));
        for (nodes.items, 0..) |node, index| self.reaching.putAssumeCapacity(node, reaches.isSet(index));
    }

    fn isFormal(self: *const PairingOverlay, id: CheckedTypeId) bool {
        for (self.formals) |formal| if (formal == id) return true;
        return false;
    }
};

/// Append a `formal -> actual` substitution. Repeated equivalent bindings keep
/// the first root; conflicting bindings violate the checked relation invariant.
fn recordRelationSubstitution(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (formal == actual) return;
    try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, store, formal, actual);
}

/// The recorded actual paired with `formal`, or null if `formal` is unbound.
fn relationSubstitutionActual(
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
    formal: CheckedTypeId,
) ?CheckedTypeId {
    for (formals, actuals) |existing, actual| {
        if (existing == formal) return actual;
    }
    return null;
}

/// Public `PlatformRequirementRelation` declaration.
pub const PlatformRequirementRelation = struct {
    id: PlatformRequirementRelationId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty_payload: CheckedTypeId,
    /// Root-call dispatch evidence in `app_value.module`.
    root_evidence: static_dispatch.EvidenceSpan = .{},
    value_kind: PlatformRequiredValueKind,
};

/// Public `PlatformRequirementRelationTable` declaration.
pub const PlatformRequirementRelationTable = struct {
    relations: []PlatformRequirementRelation = &.{},

    pub const Serialized = extern struct {
        relations: SerializedSlice(PlatformRequirementRelation) = .{},
        const Serde = store_serialize.SliceStoreSerde(PlatformRequirementRelationTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    /// Each requirement's solved app type is projected into the platform's
    /// `checked_types`, a store other threads read, under its creation
    /// lock.
    pub fn fromRelation(
        allocator: Allocator,
        io: std.Io,
        module_identity: ModuleIdentity,
        names: *canonical.CanonicalNameStore,
        checked_types: *CheckedTypeStore,
        declarations: PlatformRequiredDeclarationTable,
        relation_modules: []const ImportedModuleView,
        active_relation: PlatformAppRelation,
    ) Allocator.Error!PlatformRequirementRelationTable {
        try validatePlatformAppRelationForModule(
            module_identity,
            checked_types.view(),
            declarations,
            active_relation,
        );
        if (active_relation.relations.len != active_relation.bindings.len) {
            base.invariant(
                "checked module invariant violated: platform/app relation has {d} checked relation rows for {d} bindings",
                .{ active_relation.relations.len, active_relation.bindings.len },
            );
        }

        var seen_declarations: []bool = &.{};
        if (builtin.mode == .debug) {
            seen_declarations = try allocator.alloc(bool, declarations.count());
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .debug) allocator.free(seen_declarations);
        }

        const app_view = dependencyViewByKey(active_relation.app_module, &.{}, relation_modules, &.{}) orelse {
            checkedModuleInvariant("platform/app relation missing app relation module", .{});
        };

        const rows = try allocator.alloc(PlatformRequirementRelation, active_relation.relations.len);
        errdefer allocator.free(rows);

        checked_types.beginCreation(io);
        errdefer checked_types.endCreation(io);
        var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(allocator, checked_types, names, app_view.*);
        defer projector.deinit();
        for (active_relation.relations, 0..) |input, i| {
            const declaration = declarations.lookupByDeclarationId(input.declaration) orelse {
                base.invariant(
                    "checked module invariant violated: platform/app checked relation {d} references unknown requirement declaration",
                    .{i},
                );
            };
            const declaration_index: usize = @intCast(@backingInt(input.declaration));
            if (builtin.mode == .debug) {
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked module invariant violated: platform/app checked relation binds declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (input.requires_idx != declaration.requires_idx) {
                base.invariant(
                    "checked module invariant violated: platform/app checked relation {d} maps declaration {d} to required index {d}, expected {d}",
                    .{ i, declaration_index, input.requires_idx, declaration.requires_idx },
                );
            }
            if (!std.meta.eql(input.app_value.module.bytes, active_relation.app_module.bytes)) {
                base.invariant(
                    "checked module invariant violated: platform/app checked relation {d} points at a value outside the app module",
                    .{i},
                );
            }
            // The requirement type as the checker solved it, recorded on the
            // app's module and projected into the platform's store.
            const payload = try projector.project(input.solved_root_app);

            rows[i] = .{
                .id = input.id,
                .relation = active_relation.key,
                .module_idx = module_identity.module_idx,
                .declaration = input.declaration,
                .requires_idx = input.requires_idx,
                .app_value = input.app_value,
                .requested_source_ty_payload = payload,
                .root_evidence = input.root_evidence,
                .value_kind = input.value_kind,
            };
        }

        try checked_types.finishCreation(allocator, io);
        return .{ .relations = rows };
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;

    pub fn lookupByRelationId(self: *const PlatformRequirementRelationTable, relation_id: PlatformRequirementRelationId) ?PlatformRequirementRelation {
        const raw = @backingInt(relation_id);
        if (raw >= self.relations.len) return null;
        return self.relations[raw];
    }
};

/// Public `PlatformRequirementSolution` declaration.
///
/// One row of the check-time platform/app correspondence carried on the APP's
/// checked module: the exported app value a platform requirement resolved to
/// during checking, the requirement type as solved in the app's env, and the
/// solved types of the requirement's identity variables.
pub const PlatformRequirementSolution = struct {
    /// requires-clause index; equals the platform-side
    /// `PlatformRequiredDeclarationId` by construction (both are assigned
    /// positionally over the platform's `requires_types`).
    requires_idx: u32,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    /// The requirement type as solved in the app env, in the app's store.
    solved_root: CheckedTypeId,
    /// The solution's index among the module's checker-recorded solutions,
    /// which `CheckedDispatch.platformRequirementRootEvidence` reads by.
    source_solution: u32,
    value_kind: PlatformRequiredValueKind,
    /// Range into the table's `identity_solutions`; the offset within the
    /// range is the canonical identity slot of the platform requirement
    /// payload (the first-encounter order the canonical key digest assigns).
    identity_start: u32,
    identity_len: u32,
};

/// Public `PlatformRequirementSolutionTable` declaration.
///
/// The relation is recorded here, where it is proven: when an app checks
/// against a platform's requirement surface, each successful unification's
/// output travels as these rows. Finalization builds the platform/app
/// relation by reading them—it never re-resolves app exports by name and
/// never re-derives identity substitutions structurally. Empty for every
/// module that is not an app root checked against a platform.
pub const PlatformRequirementSolutionTable = struct {
    solutions: []PlatformRequirementSolution = &.{},
    /// Solved app types for requirement identity variables, slot-ordered per
    /// solution row (`identity_start`/`identity_len` ranges).
    identity_solutions: []CheckedTypeId = &.{},

    pub fn lookupByRequiredIndex(
        self: *const PlatformRequirementSolutionTable,
        requires_idx: u32,
    ) ?PlatformRequirementSolution {
        for (self.solutions) |solution| {
            if (solution.requires_idx == requires_idx) return solution;
        }
        return null;
    }

    pub fn identitySlice(
        self: *const PlatformRequirementSolutionTable,
        solution: PlatformRequirementSolution,
    ) []const CheckedTypeId {
        return self.identity_solutions[solution.identity_start .. solution.identity_start + solution.identity_len];
    }

    pub fn deinit(self: *PlatformRequirementSolutionTable, allocator: Allocator) void {
        allocator.free(self.solutions);
        allocator.free(self.identity_solutions);
        self.* = .{};
    }
};

/// The checker-recorded successful requirement solutions of `owner`, an app,
/// at their checked types. A row whose types contain an error is omitted;
/// platform/app relation construction converts that exact absent requires
/// index into an explicit checked-error requirement outcome.
pub fn computePlatformRequirementSolutions(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!*PlatformRequirementSolutionTable {
    const env = owner.module_env;
    var solutions = std.ArrayList(PlatformRequirementSolution).empty;
    errdefer solutions.deinit(allocator);
    var identity_solutions = std.ArrayList(CheckedTypeId).empty;
    errdefer identity_solutions.deinit(allocator);

    for (env.platform_requirement_solutions.items.items, 0..) |input, source_solution| {
        switch (input.outcome) {
            .checked_error => continue,
            .success => {},
        }

        const top_level = (try owner.checkedTables()).top_level_values.lookupByDef(input.def) orelse {
            checkedModuleInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        const value_kind: PlatformRequiredValueKind = if (input.is_function) .procedure_value else .const_value;
        const kind_matches = switch (top_level.value) {
            .procedure_binding => value_kind == .procedure_value,
            .const_ref => value_kind == .const_value,
        };
        if (!kind_matches) {
            checkedModuleInvariant("platform requirement solution value kind disagrees with the published app value", .{});
        }
        if (builtin.mode == .debug) {
            const rows = try owner.exportRows();
            const is_exported = switch (top_level.value) {
                .procedure_binding => rows.procedureBinding(top_level.def, top_level.pattern) != null,
                .const_ref => blk: {
                    for (rows.const_templates) |template| {
                        if (template.def == top_level.def and template.pattern == top_level.pattern) break :blk true;
                    }
                    break :blk false;
                },
            };
            if (!is_exported) checkedModuleInvariant("platform requirement solution references an unexported app value", .{});
        }

        const identity_start: u32 = @intCast(identity_solutions.items.len);
        const identity_vars = env.platformRequirementIdentityVars(input);
        for (identity_vars) |identity_var| {
            try identity_solutions.append(allocator, try reachedSourceRoot(owner, identity_var) orelse
                checkedModuleInvariant("a requirement identity solution has no checked type", .{}));
        }
        try solutions.append(allocator, .{
            .requires_idx = input.requires_idx,
            .def = input.def,
            .pattern = top_level.pattern,
            .solved_root = try reachedSourceRoot(owner, input.solved_var) orelse
                checkedModuleInvariant("a requirement solution has no checked type", .{}),
            .source_solution = @intCast(source_solution),
            .value_kind = value_kind,
            .identity_start = identity_start,
            .identity_len = @intCast(identity_vars.len),
        });
    }

    const owned_solutions = try solutions.toOwnedSlice(allocator);
    errdefer allocator.free(owned_solutions);
    const owned_identities = try identity_solutions.toOwnedSlice(allocator);
    errdefer allocator.free(owned_identities);
    const result = try allocator.create(PlatformRequirementSolutionTable);
    result.* = .{ .solutions = owned_solutions, .identity_solutions = owned_identities };
    return result;
}

/// Public `PlatformRequiredBinding` declaration.
pub const PlatformRequiredBinding = struct {
    id: PlatformRequiredBindingId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    checked_relation: PlatformRequirementRelationId,
    value_use: StoredPlatformRequiredValueUse,
};

/// Public `PlatformRequiredBindingTable` declaration.
pub const PlatformRequiredBindingTable = struct {
    bindings: []PlatformRequiredBinding = &.{},
    checked_error_requires: []u32 = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromRelation(
        allocator: Allocator,
        module_identity: ModuleIdentity,
        type_view: CheckedTypeStoreView,
        declarations: PlatformRequiredDeclarationTable,
        relations: *const PlatformRequirementRelationTable,
        active_relation: PlatformAppRelation,
    ) Allocator.Error!PlatformRequiredBindingTable {
        try validatePlatformAppRelationForModule(
            module_identity,
            type_view,
            declarations,
            active_relation,
        );
        if (active_relation.bindings.len + active_relation.checked_error_requires.len != declarations.count()) {
            base.invariant(
                "checked module invariant violated: platform/app relation has {d} bindings and {d} checked errors for {d} platform requirements",
                .{ active_relation.bindings.len, active_relation.checked_error_requires.len, declarations.count() },
            );
        }
        var seen_declarations: []bool = &.{};
        if (builtin.mode == .debug) {
            seen_declarations = try allocator.alloc(bool, declarations.count());
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .debug) allocator.free(seen_declarations);
        }

        const bindings = try allocator.alloc(PlatformRequiredBinding, active_relation.bindings.len);
        const checked_error_requires = try allocator.dupe(u32, active_relation.checked_error_requires);
        var closure_pool = ClosurePool.empty;
        errdefer {
            allocator.free(bindings);
            allocator.free(checked_error_requires);
            closure_pool.deinit(allocator);
        }

        if (builtin.mode == .debug) {
            for (checked_error_requires) |requires_idx| {
                const declaration = declarations.lookupByRequiredIndex(requires_idx) orelse {
                    base.invariant(
                        "checked module invariant violated: platform checked-error requirement {d} has no declaration",
                        .{requires_idx},
                    );
                };
                const declaration_index: usize = @intCast(@backingInt(declaration.id));
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked module invariant violated: platform requirement declaration {d} has multiple outcomes",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
        }

        for (active_relation.bindings, 0..) |binding, i| {
            const declaration = declarations.lookupByDeclarationId(binding.declaration) orelse {
                base.invariant(
                    "checked module invariant violated: platform/app binding {d} references unknown requirement declaration",
                    .{i},
                );
            };
            const declaration_index: usize = @intCast(@backingInt(binding.declaration));
            if (builtin.mode == .debug) {
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked module invariant violated: platform/app relation binds platform requirement declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (declaration.requires_idx != binding.requires_idx) {
                base.invariant(
                    "checked module invariant violated: platform/app binding {d} maps declaration {d} to required index {d}, expected {d}",
                    .{ i, declaration_index, binding.requires_idx, declaration.requires_idx },
                );
            }
            if (!std.meta.eql(binding.app_value.module.bytes, active_relation.app_module.bytes)) {
                base.invariant(
                    "checked module invariant violated: platform/app binding {d} points at a value outside the app module",
                    .{i},
                );
            }
            const checked_relation = relations.lookupByRelationId(binding.checked_relation) orelse {
                base.invariant(
                    "checked module invariant violated: platform/app binding {d} references missing checked relation",
                    .{i},
                );
            };
            validatePlatformBindingRelation(binding.declaration, binding.requires_idx, binding.app_value, binding.value_use.tag(), checked_relation, i);
            const value_use = platformRequiredValueUseWithRelation(binding.value_use, checked_relation);
            const stored_value_use = try copyPlatformRequiredValueUse(&closure_pool, allocator, value_use);
            bindings[i] = .{
                .id = @fromBackingInt(@intCast(@as(u32, @intCast(i)))),
                .relation = active_relation.key,
                .module_idx = module_identity.module_idx,
                .declaration = binding.declaration,
                .requires_idx = binding.requires_idx,
                .app_value = binding.app_value,
                .checked_relation = binding.checked_relation,
                .value_use = stored_value_use,
            };
        }

        return .{
            .bindings = bindings,
            .checked_error_requires = checked_error_requires,
            .closure_pool = closure_pool,
        };
    }

    pub fn deinit(self: *PlatformRequiredBindingTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) {
            allocator.free(self.bindings);
            allocator.free(self.checked_error_requires);
        }
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Materialize a binding's relation template closure from this table's pool.
    pub fn relationClosure(self: *const PlatformRequiredBindingTable, binding: PlatformRequiredBinding) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(switch (binding.value_use) {
            .const_value => |const_use| const_use.relation_template_closure,
            .procedure_value => |procedure_use| procedure_use.relation_template_closure,
        });
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        bindings: SerializedSlice(PlatformRequiredBinding) = .{},
        checked_error_requires: SerializedSlice(u32) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(store_serialize.relocatablePointerCount(Serialized) == 13);
        }

        const Serde = store_serialize.SliceStoreSerde(PlatformRequiredBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn lookupByRequiredIndex(self: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
        for (self.bindings) |binding| {
            if (binding.requires_idx == requires_idx) return binding;
        }
        return null;
    }

    pub fn isCheckedError(self: *const PlatformRequiredBindingTable, requires_idx: u32) bool {
        for (self.checked_error_requires) |checked_error_requires_idx| {
            if (checked_error_requires_idx == requires_idx) return true;
        }
        return false;
    }

    pub fn lookupByBindingId(self: *const PlatformRequiredBindingTable, binding_id: u32) ?PlatformRequiredBinding {
        if (binding_id >= self.bindings.len) return null;
        return self.bindings[binding_id];
    }
};

fn validatePlatformAppRelationForModule(
    module_identity: ModuleIdentity,
    type_view: CheckedTypeStoreView,
    declarations: PlatformRequiredDeclarationTable,
    active_relation: PlatformAppRelation,
) Allocator.Error!void {
    if (active_relation.platform_module_idx != module_identity.module_idx) {
        base.invariant(
            "checked module invariant violated: platform/app relation belongs to module {d}, not platform module {d}",
            .{ active_relation.platform_module_idx, module_identity.module_idx },
        );
    }
    // Debug builds check the relation was built against these declarations.
    if (builtin.mode == .debug) {
        const expected_requirement_context = PlatformRequirementContextKey.compute(
            module_identity,
            try declarations.identityHash(type_view),
        );
        if (!std.meta.eql(active_relation.requirement_context.bytes, expected_requirement_context.bytes)) {
            base.invariant(
                "checked module invariant violated: platform/app relation requirement context does not match the current platform requirement declarations",
                .{},
            );
        }
    }
    const expected_key = PlatformAppRelationKey.compute(
        active_relation.app_module,
        active_relation.requirement_context,
    );
    if (!std.meta.eql(active_relation.key.bytes, expected_key.bytes)) {
        base.invariant(
            "checked module invariant violated: platform/app relation key does not match the current platform requirement declarations",
            .{},
        );
    }
}

/// Per-scheme identity origins for `EnclosingDispatchIdentity`, computed on
/// first use and pooled. Each set is the key builder's own identity
/// enumeration of the scheme root (`CheckedIdentityOrderer`),
/// which reaches a where-clause signature through the constrained variable's
/// callable, normalized through `CheckedTypeStore.identityOrigin` so a
/// relation-substituted template root names a variable the way a specialized
/// plan callable does.
const EnclosingIdentityIndex = struct {
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    /// Identity origins per scheme root; each span indexes `pool`.
    spans_by_root: collections.DenseMap(CheckedTypeId, store_serialize.Span),
    pool: std.ArrayList(CheckedTypeId),
    orderer: CheckedIdentityOrderer,

    fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        store: *const CheckedTypeStore,
    ) EnclosingIdentityIndex {
        return .{
            .allocator = allocator,
            .names = names,
            .store = store,
            .spans_by_root = collections.DenseMap(CheckedTypeId, store_serialize.Span).init(allocator),
            .pool = .empty,
            .orderer = CheckedIdentityOrderer.init(allocator, names, store),
        };
    }

    fn deinit(self: *EnclosingIdentityIndex) void {
        self.pool.deinit(self.allocator);
        self.spans_by_root.deinit();
        self.orderer.deinit();
    }

    /// Whether the scheme published at `scheme_root` quantifies the identity
    /// origin `origin`.
    fn schemeQuantifies(
        self: *EnclosingIdentityIndex,
        scheme_root: CheckedTypeId,
        origin: CheckedTypeId,
    ) Allocator.Error!bool {
        const span = try self.identityOriginsOf(scheme_root);
        for (self.pool.items[span.start .. span.start + span.len]) |quantified| {
            if (quantified == origin) return true;
        }
        return false;
    }

    fn identityOriginsOf(
        self: *EnclosingIdentityIndex,
        scheme_root: CheckedTypeId,
    ) Allocator.Error!store_serialize.Span {
        if (self.spans_by_root.get(scheme_root)) |span| return span;
        const start: u32 = @intCast(self.pool.items.len);
        if (try self.store.rootContainsIdentityVariables(scheme_root)) {
            const roots = try self.orderer.identityRoots(scheme_root);
            try self.pool.ensureUnusedCapacity(self.allocator, roots.len);
            for (roots) |root| self.pool.appendAssumeCapacity(self.store.identityOrigin(root));
        }
        const span: store_serialize.Span = .{
            .start = start,
            .len = @intCast(self.pool.items.len - start),
        };
        try self.spans_by_root.put(scheme_root, span);
        return span;
    }
};

/// One scheme context a collected span attributes to a dispatch site: the
/// enclosing template's checked function root (null for a defaulted-field
/// expression, which no template quantifies) and the generalized-local scope
/// that owns the reference.
const EnclosingDispatchSite = struct {
    template_root: ?CheckedTypeId,
    scope: DispatchScope,
};

/// The schemes enclosing one dispatch site, asked which variables they
/// quantify: for every span that references the site, the enclosing
/// template's checked function root (with the where-clause signatures its
/// variables carry) and every generalized-local scope between the template
/// and the site. A variable any referencing context quantifies is a
/// specialization input. A site no span reaches (dead code) has no enclosing
/// scheme and is classified like a root edge.
const EnclosingDispatchIdentity = struct {
    index: *EnclosingIdentityIndex,
    sites: []const EnclosingDispatchSite,
    scopes: []const DispatchRefScope,

    /// Whether any referencing context—its template, that template's
    /// where-clause signatures, or an enclosing generalized-local scope—
    /// quantifies the variable at `root`.
    fn quantifies(self: EnclosingDispatchIdentity, root: CheckedTypeId) Allocator.Error!bool {
        const origin = self.index.store.identityOrigin(root);
        for (self.sites) |site| {
            if (site.template_root) |template_root| {
                if (try self.index.schemeQuantifies(template_root, origin)) return true;
            }
            var current: ?DispatchScopeId = switch (site.scope) {
                .root => null,
                .generalized => |id| id,
            };
            while (current) |id| {
                const raw_scope = @backingInt(id);
                if (raw_scope >= self.scopes.len) {
                    checkedModuleInvariant("dispatch site referenced a missing generalized-local scope", .{});
                }
                const scope = self.scopes[raw_scope];
                if (try self.index.schemeQuantifies(scope.scheme_root, origin)) return true;
                current = scope.parent;
            }
        }
        return false;
    }
};

/// Whether a resolved direct-dispatch callable specializes without any input
/// from the enclosing specialization (design.md "Static Dispatch In Monotype",
/// `direct_closed`). A rigid, a flex with no row default, a numeric-defaulting
/// flex, and a constrained flex each stand for a specialization input, as does
/// a defaultable row tail the enclosing schemes quantify; a defaultable,
/// unconstrained row tail nothing enclosing quantifies has exactly one
/// instantiation—its row default, which the closed path seals it to—and does
/// not. `rootContainsIdentityVariables` keeps answering the digest-identity
/// question (is any variable reachable at all); this answers the
/// specialization question.
fn callableIdentityIsSpecializationIndependent(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    callable: CheckedTypeId,
    enclosing: EnclosingDispatchIdentity,
) Allocator.Error!bool {
    if (!try store.rootContainsIdentityVariables(callable)) return true;
    var visited = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer visited.deinit();
    // The answer is the conjunction of every reachable type's own verdict;
    // types are visited once, in source order, from an explicit work list.
    var pending: std.ArrayListUnmanaged(CheckedTypeId) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, callable);
    while (pending.pop()) |root| {
        if ((try visited.getOrPut(root)).found_existing) continue;
        const start = pending.items.len;
        const payload = store.payload(root);
        switch (payload) {
            .pending => checkedModuleInvariant("direct dispatch classification reached a pending checked type", .{}),
            .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => if (!payload.variableSealsToRowDefault() or try enclosing.quantifies(root)) return false,
            .alias => |alias| {
                try pending.appendSlice(allocator, alias.args);
                try pending.append(allocator, alias.backing);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try pending.append(allocator, field.ty);
                    if (field.kind.undeterminedVariable()) |variable| try pending.append(allocator, variable);
                }
                try pending.append(allocator, record.ext);
            },
            .tuple => |elems| try pending.appendSlice(allocator, elems),
            .nominal => |nominal| {
                try pending.appendSlice(allocator, nominal.args);
                try pending.appendSlice(allocator, nominal.padding_field_types);
            },
            .function => |function| {
                try pending.appendSlice(allocator, function.args);
                try pending.append(allocator, function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try pending.appendSlice(allocator, tag.args);
                }
                try pending.append(allocator, tag_union.ext);
            },
        }
        std.mem.reverse(CheckedTypeId, pending.items[start..]);
    }
    return true;
}

/// One dispatch resolution's specializer: its callable projection and
/// instantiation memo, its evidence-closure memo over the resolution's own
/// pool, and the enclosing-identity index.
const ResolvedDispatchCallableSpecializer = struct {
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    owner: ModuleId,
    imports: CheckedImportViews,
    evidence_nodes: []const static_dispatch.EvidenceNode,
    evidence_refs: []const static_dispatch.CheckedEvidence,
    instantiated_pairs: std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId) = .empty,
    evidence_closure: []DirectEvidenceClosure,
    identity_index: EnclosingIdentityIndex,

    fn deinit(self: *ResolvedDispatchCallableSpecializer) void {
        self.identity_index.deinit();
        self.instantiated_pairs.deinit(self.allocator);
    }

    /// Specialize a pending direct plan's callable. The caller holds the
    /// store's creation lock.
    fn specializePlan(self: *ResolvedDispatchCallableSpecializer, plan: *static_dispatch.PlanResolution) Allocator.Error!void {
        switch (plan.resolution) {
            .direct_pending => |node_id| plan.callable_ty = try self.specializeCallable(node_id, plan.callable_ty),
            .direct_closed, .direct_parametric => checkedModuleInvariant("static dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        }
    }

    /// Classify a pending direct plan over its specialized callable.
    fn classifyPlan(
        self: *ResolvedDispatchCallableSpecializer,
        plan: *static_dispatch.PlanResolution,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!void {
        switch (plan.resolution) {
            .direct_pending => |node_id| plan.resolution = try self.classify(node_id, plan.callable_ty, enclosing),
            .direct_closed, .direct_parametric => checkedModuleInvariant("static dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        }
    }

    /// Specialize the callables of an iterator plan's pending direct calls.
    /// The caller holds the store's creation lock.
    fn specializeIteratorPlan(self: *ResolvedDispatchCallableSpecializer, iterator_plan: *static_dispatch.IteratorPlanResolution) Allocator.Error!void {
        inline for (.{ .{ &iterator_plan.iter, &iterator_plan.iter_callable_ty }, .{ &iterator_plan.next, &iterator_plan.next_callable_ty } }) |call| {
            switch (call[0].*) {
                .direct_pending => |node_id| call[1].* = try self.specializeCallable(node_id, call[1].*),
                .direct_closed, .direct_parametric => checkedModuleInvariant("iterator dispatch plan was finalized more than once", .{}),
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
    }

    /// Classify an iterator plan's pending direct calls over their
    /// specialized callables.
    fn classifyIteratorPlan(
        self: *ResolvedDispatchCallableSpecializer,
        iterator_plan: *static_dispatch.IteratorPlanResolution,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!void {
        inline for (.{ .{ &iterator_plan.iter, &iterator_plan.iter_callable_ty }, .{ &iterator_plan.next, &iterator_plan.next_callable_ty } }) |call| {
            switch (call[0].*) {
                .direct_pending => |node_id| call[0].* = try self.classify(node_id, call[1].*, enclosing),
                .direct_closed, .direct_parametric => checkedModuleInvariant("iterator dispatch plan was finalized more than once", .{}),
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
    }

    /// Project the resolved target's callable into this store and specialize
    /// the call's recorded callable against it.
    fn specializeCallable(
        self: *ResolvedDispatchCallableSpecializer,
        node_id: static_dispatch.EvidenceNodeId,
        plan_callable: CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const target = self.evidence_nodes[node_id.index].target;
        const target_callable = try projectResolvedDispatchTargetCallable(
            self.allocator,
            self.names,
            self.store,
            self.owner,
            self.imports,
            target,
        );
        return try instantiateResolvedDispatchTargetCallableMemoized(
            self.allocator,
            .{ .store = self.store, .names = self.names, .module = self.owner, .resolver = self.imports.resolver() },
            target_callable,
            plan_callable,
            &self.instantiated_pairs,
        );
    }

    fn classify(
        self: *ResolvedDispatchCallableSpecializer,
        node_id: static_dispatch.EvidenceNodeId,
        callable_ty: CheckedTypeId,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!static_dispatch.CheckedCallResolution {
        const direct: static_dispatch.DirectCall = .{ .evidence = node_id };
        const closed = (try callableIdentityIsSpecializationIndependent(self.allocator, self.store, callable_ty, enclosing)) and
            try directEvidenceIsClosed(self.allocator, self.evidence_nodes, self.evidence_refs, node_id, self.evidence_closure);
        return if (closed) .{ .direct_closed = direct } else .{ .direct_parametric = direct };
    }
};

const DirectEvidenceClosure = enum(u8) {
    unknown,
    visiting,
    closed,
    parametric,
};

/// Whether a concrete target's entire nested evidence tree is independent of
/// the enclosing specialization. This is the evidence half of
/// `direct_closed`: a structurally closed callable whose nested evidence still
/// forwards a constraint is parametric, not closed. Nested evidence lies in
/// the same pool as the node that names it.
fn directEvidenceIsClosed(
    allocator: Allocator,
    nodes: []const static_dispatch.EvidenceNode,
    refs: []const static_dispatch.CheckedEvidence,
    root: static_dispatch.EvidenceNodeId,
    states: []DirectEvidenceClosure,
) Allocator.Error!bool {
    // Each node being decided is a frame over its nested evidence, and each
    // entry's callable contracts are a frame of their own, so nested
    // requirement depth never becomes native call depth.
    const Frame = struct {
        /// The node this frame decides; null for a callable-contract vector,
        /// which decides only its enclosing node.
        node: ?usize,
        refs: []const static_dispatch.CheckedEvidence,
        next: usize = 0,
    };
    var frames: std.ArrayListUnmanaged(Frame) = .empty;
    defer frames.deinit(allocator);

    var result = switch (directEvidenceEnter(nodes, refs, root, states)) {
        .decided => |closed| return closed,
        .nested => |nested| blk: {
            try frames.append(allocator, .{ .node = root.index, .refs = nested });
            break :blk true;
        },
    };
    while (frames.items.len > 0) {
        const frame = &frames.items[frames.items.len - 1];
        if (!result) {
            if (frame.node) |node| states[node] = .parametric;
            _ = frames.pop();
            continue;
        }
        if (frame.next == frame.refs.len) {
            if (frame.node) |node| states[node] = .closed;
            _ = frames.pop();
            continue;
        }
        const evidence = frame.refs[frame.next];
        frame.next += 1;
        const contracts = refs[evidence.callable_contracts.start..][0..evidence.callable_contracts.len];
        if (contracts.len != 0) try frames.append(allocator, .{ .node = null, .refs = contracts });
        switch (evidence.resolution) {
            .direct => |child| switch (directEvidenceEnter(nodes, refs, child, states)) {
                .decided => |closed| result = closed,
                .nested => |nested| try frames.append(allocator, .{ .node = child.index, .refs = nested }),
            },
            .constraint, .from_callable, .from_scheme => result = false,
            .structural, .checked_error, .unreachable_value => {},
        }
    }
    return result;
}

/// A node's answer when it is already decided or decided by itself; otherwise
/// mark it visiting and return the nested evidence that decides it.
fn directEvidenceEnter(
    nodes: []const static_dispatch.EvidenceNode,
    refs: []const static_dispatch.CheckedEvidence,
    node_id: static_dispatch.EvidenceNodeId,
    states: []DirectEvidenceClosure,
) union(enum) { decided: bool, nested: []const static_dispatch.CheckedEvidence } {
    const raw_node = node_id.index;
    if (raw_node >= states.len) checkedModuleInvariant("direct evidence closure referenced a missing node", .{});
    switch (states[raw_node]) {
        .closed => return .{ .decided = true },
        .parametric => return .{ .decided = false },
        .visiting => checkedModuleInvariant("direct evidence closure contained a cycle", .{}),
        .unknown => states[raw_node] = .visiting,
    }
    const node = nodes[raw_node];
    switch (node.target.kind) {
        .local_proc => {
            // The declaration identity is checked data, but its capture/context
            // identity belongs to the enclosing Monotype specialization.
            states[raw_node] = .parametric;
            return .{ .decided = false };
        },
        .procedure => {},
        .structural => checkedModuleInvariant("direct evidence closure contained a structural target", .{}),
    }
    switch (node.nested) {
        // A target reached through an alias takes its evidence from the
        // alias's forwarded lookup, which belongs to the specialization.
        .from_callable, .through_alias => {
            states[raw_node] = .parametric;
            return .{ .decided = false };
        },
        .resolved => |span| return .{ .nested = refs[span.start .. span.start + span.len] },
    }
}

/// The identity of the conversion root of `literal`: the literal itself.
pub fn literalConversionRootId(literal: LiteralNode) ComptimeRootKey {
    const kind: u128 = @backingInt(ComptimeRootKey.Kind.literal_conversion);
    const pattern: u128 = switch (literal) {
        .expr => 0,
        .pattern => 1,
    };
    return @fromBackingInt((kind << ComptimeRootKey.kind_shift) | (pattern << 32) | literal.node());
}

/// The identity of the literal argument root converting literal requirement
/// `requirement` of the scheme `edge` instantiates at the type the edge
/// fixes.
pub fn literalArgumentRootId(edge: LiteralEdge, requirement: u32) ComptimeRootKey {
    const kind: u128 = @backingInt(ComptimeRootKey.Kind.literal_argument);
    const edge_bits: u128 = switch (edge) {
        .node => |id| @as(u64, @bitCast(id)),
        .use => |expr| (@as(u128, 1) << 64) | @backingInt(expr),
        .literal => checkedModuleInvariant("a literal argument root was named by a literal requirement's own literal", .{}),
    };
    return @fromBackingInt((kind << ComptimeRootKey.kind_shift) | (edge_bits << 32) | requirement);
}

/// What a literal root's identity names (`literalConversionRootId`,
/// `literalArgumentRootId`).
pub const LiteralRootName = union(enum) {
    conversion: LiteralNode,
    argument: struct { edge: LiteralEdge, requirement: u32 },
};

/// What literal root `id` names, or null for a root of the module's root
/// table.
pub fn literalRootName(id: ComptimeRootKey) ?LiteralRootName {
    const raw = @backingInt(id);
    switch (id.kind()) {
        .repl_expr, .def, .hoisted, .expect => return null,
        .literal_conversion => {
            const node: u32 = @truncate(raw);
            return .{ .conversion = if ((raw >> 32) & 1 == 0) .{ .expr = @fromBackingInt(node) } else .{ .pattern = @fromBackingInt(node) } };
        },
        .literal_argument => {
            const edge_bits = raw >> 32;
            const edge: LiteralEdge = if ((edge_bits >> 64) & 1 == 0)
                .{ .node = @bitCast(@as(u64, @truncate(edge_bits))) }
            else
                .{ .use = @fromBackingInt(@as(u32, @truncate(edge_bits))) };
            return .{ .argument = .{ .edge = edge, .requirement = @truncate(raw) } };
        },
    }
}

/// The name the definition procedure base `base` comes from binds, or null
/// for a base that names no definition or a definition whose pattern binds no
/// single name.
pub fn procBaseDefName(env: *const ModuleEnv, base_: canonical.ProcBase) ?[]const u8 {
    const def_idx = base_.sourceDef() orelse return null;
    const pattern = env.store.getPattern(env.store.getDef(@fromBackingInt(def_idx)).pattern);
    if (pattern == .assign) return env.getIdent(pattern.assign.ident);
    return null;
}

/// The entry wrapper of literal root `root`: a template named by the root's
/// identity, which no row of the template table holds.
pub fn literalRootWrapperTemplate(root: ComptimeRootKey) canonical.CheckedProcedureTemplateId {
    std.debug.assert(root.isLiteral());
    return @fromBackingInt(@backingInt(root));
}

/// The literal root whose entry wrapper `template` is, or null for a template
/// of the template table.
pub fn templateLiteralRoot(template: canonical.CheckedProcedureTemplateId) ?ComptimeRootKey {
    if (template.rowIndex() != null) return null;
    return @fromBackingInt(@backingInt(template));
}

/// A literal whose conversion is a literal conversion root: its custom
/// conversion's dispatch resolution is closed.
pub const LiteralConversionCandidate = struct {
    literal: LiteralNode,
    kind: CompileTimeLiteralConversionKind,
    plan: static_dispatch.StaticDispatchPlanId,
    ty: CheckedTypeId,
    evidence: static_dispatch.EvidenceNodeId,
};

/// The conversion root the literal at `raw_node` has, or null. Literal roots
/// have no lexical evidence parameters, so a literal has one only where its
/// module's dispatch resolution proved the complete conversion closed. A
/// concrete receiver alone does not prove this: nested codec requirements can
/// still belong to the enclosing scheme. Those literals stay in that scheme
/// and are hoisted by its specialization.
pub fn literalConversionCandidate(bodies: CheckedBodies, dispatch: CheckedDispatch, raw_node: u32) Allocator.Error!?LiteralConversionCandidate {
    const literal = bodies.env.store.literalDispatchPlanForNode(@fromBackingInt(raw_node)) orelse return null;
    switch (literal.dispatchResolution()) {
        .builtin_direct, .specialization_dispatch, .checked_error => return null,
        .custom_dispatch => {},
        .unresolved => checkedModuleInvariant("an unresolved literal reached literal root selection", .{}),
    }
    const literal_node: LiteralNode = switch (bodies.index().nodeKind(raw_node)) {
        .expr => switch (bodies.exprData(@fromBackingInt(raw_node))) {
            .numeral => .{ .expr = @fromBackingInt(raw_node) },
            .str => if (bodies.quoteIsCustom(raw_node)) .{ .expr = @fromBackingInt(raw_node) } else return null,
            // Diagnostic recovery retired the conversion.
            .runtime_error => return null,
            .str_segment, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        },
        .pattern => if (try bodies.literalPatternGuard(@fromBackingInt(raw_node)) == null) return null else .{ .pattern = @fromBackingInt(raw_node) },
        .statement, .unreached => return null,
    };
    const conversion = try bodies.literalConversion(raw_node);
    const plan_id = conversion.plan orelse checkedModuleInvariant("a custom literal had no conversion plan", .{});
    const plan = try dispatch.plan(plan_id);
    const evidence = switch (plan.resolution) {
        .direct_closed => |direct| direct.evidence,
        .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => return null,
        .direct_pending, .structural => checkedModuleInvariant("a literal conversion had no finalized callable dispatch", .{}),
    };
    return .{
        .literal = literal_node,
        .kind = if (literal.dispatchKind() == .numeral) .numeral else .quote,
        .plan = plan_id,
        .ty = conversion.ty,
        .evidence = evidence,
    };
}

/// A literal root of a module with its entry wrapper: the wrapper's function
/// type and scheme, created by the slot that holds the root, and the relation
/// of the wrapper's body to its specialization.
pub const LiteralRootRecord = struct {
    root: CompileTimeRoot,
    checked_fn_root: CheckedTypeId,
    checked_fn_scheme: CheckedTypeSchemeId,
    /// The conversion plan a literal conversion root's wrapper runs; null for
    /// a literal argument root.
    plan: ?static_dispatch.StaticDispatchPlanId,
    relation: [1]SpecializationInterfaceRelation,
};

/// The literal conversion roots of one top-level unit's literals, by node
/// (`ModuleAnalyses.unitLiteralConversions`).
pub const UnitLiteralConversions = struct {
    nodes: []const u32,
    records: []const LiteralRootRecord,

    pub fn record(self: *const UnitLiteralConversions, raw_node: u32) ?*const LiteralRootRecord {
        const index = std.sort.binarySearch(u32, self.nodes, raw_node, struct {
            fn order(key: u32, item: u32) std.math.Order {
                return std.math.order(key, item);
            }
        }.order) orelse return null;
        return &self.records[index];
    }

    pub fn destroy(self: *UnitLiteralConversions, allocator: Allocator) void {
        allocator.free(self.nodes);
        allocator.free(self.records);
        allocator.destroy(self);
    }
};

/// The import views a module's dispatch resolution reads.
fn dispatchImportViews(dispatch: CheckedDispatch) Allocator.Error!CheckedImportViews {
    return .{ .current_owner = dispatch.source.key.digest(), .direct = &.{}, .available = try dispatch.source.analyses.dispatchImports(dispatch) };
}

/// Demand, holding no claim, the interface capabilities of the module `dispatch`
/// reads and of `modules`, whose types a creation in the module's store or a
/// dispatch analysis reads, so every analysis reads their nominal types at
/// the representation the capabilities give them.
pub fn demandDispatchCapabilities(dispatch: CheckedDispatch, modules: []const ModuleId) Allocator.Error!void {
    const import_views = try dispatchImportViews(dispatch);
    const store = dispatch.source.types.store;
    if (store.capability_source != null) _ = try store.view().interfaceCapabilities();
    for (modules) |module| {
        if (module.eql(dispatch.source.key.digest())) continue;
        const view = import_views.viewForKey(module) orelse checkedModuleInvariant("a literal analysis read a module its dispatch resolution does not read", .{});
        _ = try view.checked_types.interfaceCapabilities();
    }
}

/// The relation of a literal root's entry wrapper to its specialization: the
/// wrapper's body delivers the root's type.
fn literalRootWrapperRelation(checked_fn_root: CheckedTypeId, root_ty: CheckedTypeId) [1]SpecializationInterfaceRelation {
    return .{.{
        .scope = .root,
        .data = .{ .procedure = .{
            .fn_ty = checked_fn_root,
            .body_ret_ty = root_ty,
            .owns_scope = true,
        } },
    }};
}

/// The literal conversion roots of unit `unit`'s literals: each root, its
/// request eligibility, and its entry wrapper's function type and scheme,
/// created here under the store's creation lock after every slot it reads.
pub fn computeUnitLiteralConversions(allocator: Allocator, dispatch: CheckedDispatch, unit: body_analyses.UnitId) Allocator.Error!*UnitLiteralConversions {
    const source = dispatch.source;
    const bodies = dispatchSourceBodies(source);
    var candidates: std.ArrayList(LiteralConversionCandidate) = .empty;
    defer candidates.deinit(allocator);
    for (bodies.index().unitNodeSlice(unit)) |raw_node| {
        if (try literalConversionCandidate(bodies, dispatch, raw_node)) |candidate| try candidates.append(allocator, candidate);
    }
    std.mem.sort(LiteralConversionCandidate, candidates.items, {}, struct {
        fn lessThan(_: void, a: LiteralConversionCandidate, b: LiteralConversionCandidate) bool {
            return a.literal.node() < b.literal.node();
        }
    }.lessThan);
    const nodes = try allocator.alloc(u32, candidates.items.len);
    errdefer allocator.free(nodes);
    const records = try allocator.alloc(LiteralRootRecord, candidates.items.len);
    errdefer allocator.free(records);
    const import_views = try dispatchImportViews(dispatch);
    const store = source.types.store;
    try demandDispatchCapabilities(dispatch, &.{});
    var proofs = try ConcreteRootProofs.init(allocator, source.key.digest(), store.view(), import_views.resolver());
    defer proofs.deinit();
    for (candidates.items, nodes, records) |candidate, *node, *record| {
        node.* = candidate.literal.node();
        const eligible = try proofs.isContextFree(false, candidate.ty);
        record.* = .{
            .root = .{
                .id = literalConversionRootId(candidate.literal),
                .module_idx = source.module_idx,
                .kind = switch (candidate.kind) {
                    .numeral => .numeral_conversion,
                    .quote => .quote_conversion,
                },
                .source = .{ .literal = candidate.literal },
                .pattern = null,
                .expr = null,
                .checked_type = candidate.ty,
                .request_eligibility = if (eligible) .eligible else .ineligible,
            },
            .checked_fn_root = undefined, // Created below, under the creation lock.
            .checked_fn_scheme = undefined, // Created below, under the creation lock.
            .plan = candidate.plan,
            .relation = undefined, // Set below from the created function type.
        };
    }
    {
        store.beginCreation(source.analyses.io);
        errdefer store.endCreation(source.analyses.io);
        for (records) |*record| {
            record.checked_fn_root = try store.appendSyntheticFunctionRoot(allocator, .pure, &.{}, record.root.checked_type);
            record.checked_fn_scheme = try store.ensureSchemeForRoot(allocator, record.checked_fn_root);
        }
        try store.finishCreation(allocator, source.analyses.io);
    }
    for (records) |*record| record.relation = literalRootWrapperRelation(record.checked_fn_root, record.root.checked_type);
    const result = try allocator.create(UnitLiteralConversions);
    result.* = .{ .nodes = nodes, .records = records };
    return result;
}

/// A scheme of a module: a template's own (`scope == null`) or a generalized
/// local scope's. A scope inside a defaulted field expression has no
/// template.
pub const LiteralScopeKey = struct { template: ?u32, scope: ?u32 };

fn literalScopeKeyOf(template: ?u32, scope: DispatchScope) LiteralScopeKey {
    return switch (scope) {
        .root => .{ .template = template, .scope = null },
        .generalized => |id| .{ .template = template, .scope = @backingInt(id) },
    };
}

/// The scheme an edge instantiates: a procedure template's, or a generalized
/// local function's.
pub const LiteralCallee = union(enum) {
    template: canonical.ProcedureTemplateRef,
    scope: DispatchScopeId,
};

/// Where an edge's substitution comes from.
pub const LiteralEdgeSubst = union(enum) {
    /// A dispatch edge's own instantiation of its target's scheme.
    evidence: static_dispatch.EvidenceSpan,
    /// A use's instantiation of the scheme it reads.
    site: CIR.Expr.Idx,
    /// A dispatch edge to a method bound to an exact procedure alias: the
    /// instantiation of the alias's scheme, composed through the alias
    /// chain's forwarded lookups.
    alias_chain: static_dispatch.EvidenceNodeId,
};

/// One instantiation edge of the module's bodies (`LiteralGraph`).
pub const LiteralGraphEdge = struct {
    key: LiteralEdge,
    /// The graph node whose body holds the edge first, in node order, which
    /// computes the edge's literal arguments.
    holder: u32,
    callee: LiteralCallee,
    /// The scope the edge is in; null inside a defaulted field expression.
    scope: ?LiteralScopeKey,
    owner_expr: CIR.Expr.Idx,
    subst: LiteralEdgeSubst,
};

/// A literal of a scheme's own body whose conversion plan is open: a literal
/// requirement of the innermost scheme around it.
pub const LiteralOwnSite = struct {
    scope: LiteralScopeKey,
    site: LiteralSite,
    ty: CheckedTypeId,
};

/// An edge of a module's literal graph, by its key.
pub const LiteralEdgeIndex = struct {
    key: u64,
    edge: u32,

    fn lessThan(_: void, a: LiteralEdgeIndex, b: LiteralEdgeIndex) bool {
        return a.key < b.key;
    }

    fn order(key: u64, item: LiteralEdgeIndex) std.math.Order {
        return std.math.order(key, item.key);
    }
};

/// The strongly connected components of a call graph over dense nodes,
/// numbered as they complete (callees first).
pub const CallGraphComponents = struct {
    component_of: []const u32,
    member_index: []const u32,
    /// Component `c`'s nodes, ascending: `members[member_starts[c]..member_starts[c + 1]]`.
    member_starts: []const u32,
    members: []const u32,
    /// Component `c`'s callee components other than itself, each once.
    callee_starts: []const u32,
    callees: []const u32,

    pub fn count(self: *const CallGraphComponents) usize {
        return self.member_starts.len - 1;
    }

    pub fn componentMembers(self: *const CallGraphComponents, component: u32) []const u32 {
        return self.members[self.member_starts[component]..self.member_starts[component + 1]];
    }

    pub fn componentCallees(self: *const CallGraphComponents, component: u32) []const u32 {
        return self.callees[self.callee_starts[component]..self.callee_starts[component + 1]];
    }

    pub fn deinit(self: *CallGraphComponents, allocator: Allocator) void {
        allocator.free(self.component_of);
        allocator.free(self.member_index);
        allocator.free(self.member_starts);
        allocator.free(self.members);
        allocator.free(self.callee_starts);
        allocator.free(self.callees);
    }
};

/// The strongly connected components of the graph whose node `n`'s callees
/// are `successors[successor_starts[n]..successor_starts[n + 1]]` (Tarjan's
/// algorithm, iteratively), numbered as they complete, so every component's
/// callee components precede it.
pub fn callGraphComponents(allocator: Allocator, successor_starts: []const u32, successors: []const u32) Allocator.Error!CallGraphComponents {
    const count = successor_starts.len - 1;
    const unvisited = std.math.maxInt(u32);
    const order = try allocator.alloc(u32, count);
    defer allocator.free(order);
    @memset(order, unvisited);
    const low = try allocator.alloc(u32, count);
    defer allocator.free(low);
    var on_stack = try std.DynamicBitSetUnmanaged.initEmpty(allocator, count);
    defer on_stack.deinit(allocator);
    var stack: std.ArrayList(u32) = .empty;
    defer stack.deinit(allocator);
    const Frame = struct { node: u32, next: u32 };
    var frames: std.ArrayList(Frame) = .empty;
    defer frames.deinit(allocator);

    const component_of = try allocator.alloc(u32, count);
    errdefer allocator.free(component_of);
    var members: std.ArrayList(u32) = .empty;
    defer members.deinit(allocator);
    var member_starts: std.ArrayList(u32) = .empty;
    defer member_starts.deinit(allocator);
    try member_starts.append(allocator, 0);
    var next_order: u32 = 0;

    for (0..count) |start| {
        if (order[start] != unvisited) continue;
        order[start] = next_order;
        low[start] = next_order;
        next_order += 1;
        try stack.append(allocator, @intCast(start));
        on_stack.set(start);
        try frames.append(allocator, .{ .node = @intCast(start), .next = successor_starts[start] });
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            const node = frame.node;
            if (frame.next < successor_starts[node + 1]) {
                const callee = successors[frame.next];
                frame.next += 1;
                if (order[callee] == unvisited) {
                    order[callee] = next_order;
                    low[callee] = next_order;
                    next_order += 1;
                    try stack.append(allocator, callee);
                    on_stack.set(callee);
                    try frames.append(allocator, .{ .node = callee, .next = successor_starts[callee] });
                } else if (on_stack.isSet(callee)) {
                    low[node] = @min(low[node], order[callee]);
                }
                continue;
            }
            _ = frames.pop();
            if (frames.items.len != 0) {
                const parent = frames.items[frames.items.len - 1].node;
                low[parent] = @min(low[parent], low[node]);
            }
            if (low[node] != order[node]) continue;
            const component: u32 = @intCast(member_starts.items.len - 1);
            const first = members.items.len;
            while (stack.pop()) |member| {
                on_stack.unset(member);
                component_of[member] = component;
                try members.append(allocator, member);
                if (member == node) break;
            }
            std.mem.sort(u32, members.items[first..], {}, std.sort.asc(u32));
            try member_starts.append(allocator, @intCast(members.items.len));
        }
    }

    const component_count = member_starts.items.len - 1;
    const member_index = try allocator.alloc(u32, count);
    errdefer allocator.free(member_index);
    for (0..component_count) |component| {
        for (members.items[member_starts.items[component]..member_starts.items[component + 1]], 0..) |member, index| member_index[member] = @intCast(index);
    }
    var callees: std.ArrayList(u32) = .empty;
    defer callees.deinit(allocator);
    var callee_starts: std.ArrayList(u32) = .empty;
    defer callee_starts.deinit(allocator);
    try callee_starts.append(allocator, 0);
    for (0..component_count) |component| {
        const first = callees.items.len;
        for (members.items[member_starts.items[component]..member_starts.items[component + 1]]) |member| {
            for (successors[successor_starts[member]..successor_starts[member + 1]]) |callee| {
                if (component_of[callee] != component) try callees.append(allocator, component_of[callee]);
            }
        }
        const added = callees.items[first..];
        std.mem.sort(u32, added, {}, std.sort.asc(u32));
        var kept: usize = 0;
        for (added, 0..) |callee, index| {
            if (index != 0 and added[index - 1] == callee) continue;
            added[kept] = callee;
            kept += 1;
        }
        callees.shrinkRetainingCapacity(first + kept);
        try callee_starts.append(allocator, @intCast(callees.items.len));
    }

    const owned_members = try members.toOwnedSlice(allocator);
    errdefer allocator.free(owned_members);
    const owned_member_starts = try member_starts.toOwnedSlice(allocator);
    errdefer allocator.free(owned_member_starts);
    const owned_callees = try callees.toOwnedSlice(allocator);
    errdefer allocator.free(owned_callees);
    return .{
        .component_of = component_of,
        .member_index = member_index,
        .member_starts = owned_member_starts,
        .members = owned_members,
        .callee_starts = try callee_starts.toOwnedSlice(allocator),
        .callees = owned_callees,
    };
}

test "lazy components assign only what a node reaches, callees first" {
    const gpa = std.testing.allocator;
    // 0 -> 1 -> 2 -> 1 (1 and 2 form a cycle), 3 -> 0, 4 alone.
    const Graph = struct {
        callees: []const []const u32,

        pub fn calleesOf(self: *const @This(), node: u32) []const u32 {
            return self.callees[node];
        }
    };
    const graph: Graph = .{ .callees = &.{ &.{1}, &.{2}, &.{1}, &.{0}, &.{} } };
    var components = try LazyComponents.init(gpa, 5);
    defer components.deinit(gpa);

    try components.assign(gpa, 0, &graph);
    try std.testing.expectEqual(@as(?u32, 0), components.leaderOf(0));
    try std.testing.expectEqual(@as(?u32, 1), components.leaderOf(1));
    try std.testing.expectEqual(@as(?u32, 1), components.leaderOf(2));
    try std.testing.expectEqual(@as(?u32, null), components.leaderOf(3));
    try std.testing.expectEqual(@as(?u32, null), components.leaderOf(4));
    try std.testing.expectEqualSlices(u32, &.{ 1, 2 }, components.info(1).members);
    try std.testing.expectEqualSlices(u32, &.{1}, components.info(0).callees);
    try std.testing.expectEqual(@as(u32, 1), components.info(1).memberIndex(2));

    try components.assign(gpa, 3, &graph);
    try std.testing.expectEqual(@as(?u32, 3), components.leaderOf(3));
    try std.testing.expectEqualSlices(u32, &.{0}, components.info(3).callees);
    try std.testing.expectEqual(@as(?u32, null), components.leaderOf(4));
}

/// The slot holding one literal component's results.
pub const LiteralComponentSlot = collections.OnceSlot(*LiteralComponent, .module_literal_component);
/// The slot holding the literal argument roots one template's edges read.
pub const LiteralDemandSlot = collections.OnceSlot(*LiteralArgumentDemand, .module_literal_demand);
/// The slot holding one node's part of a module's literal graph.
pub const LiteralNodeSlot = collections.OnceSlot(*LiteralNodeEdges, .module_literal_node);
/// The slot holding the holders of the evidence nodes one resolution's
/// pool gives the literal walks.
pub const LiteralPoolSlot = collections.OnceSlot(*LiteralPoolHolders, .module_literal_pool);
/// The slot holding the holders of the evidence nodes of the module's own
/// resolution that the literal walks reach.
pub const LiteralModulePoolSlot = collections.OnceSlot(*LiteralPoolHolders, .module_literal_module_pool);
/// The slot holding the order of every component of a module's literal
/// graph.
pub const LiteralOrderSlot = collections.OnceSlot(*LiteralComponentOrder, .module_literal_component_order);

/// A module's literal call graph (`ModuleAnalyses.literalGraph`). Nodes are
/// the module's templates in template order, then the defaulted-field
/// expressions as one node. An edge is held by the first node, in node
/// order, whose body reaches it, and that node's component computes its
/// literal arguments. The graph itself holds only what needs no dispatch
/// resolution: which node first reaches each value reference and each
/// generalized local function's construction. Each node's edges and own open
/// literals (`LiteralNodeEdges`), the first node reaching each evidence node
/// of a resolution's pool (`LiteralPoolHolders`), each strongly connected
/// component of the edges between nodes, and each component's literal
/// requirements, edge arguments and literal argument roots
/// (`LiteralComponent`) are slots of their own, so a consumer of one
/// template's requirements resolves only the templates that template reaches.
pub const LiteralGraph = struct {
    template_count: u32,
    /// The template whose body owns each generalized local scope.
    scope_owners: []const ?u32,
    /// The first node holding a value reference at each expression, with
    /// that reference.
    value_ref_firsts: std.AutoHashMapUnmanaged(u32, LiteralValueRefFirst),
    /// The first node holding a generalized local function's construction
    /// at each expression.
    scope_site_firsts: std.AutoHashMapUnmanaged(u32, u32),
    /// One per node.
    node_slots: []LiteralNodeSlot,
    /// One per template, for the evidence pool of the template's
    /// resolution.
    pool_slots: []LiteralPoolSlot,
    module_pool_slot: LiteralModulePoolSlot = .empty,
    order_slot: LiteralOrderSlot = .empty,
    /// The strongly connected components of the edges between nodes.
    components: LazyComponents,
    /// Each component's results, by its leader.
    component_slots: []LiteralComponentSlot,
    demand_slots: []LiteralDemandSlot,

    pub fn defaultsNode(self: *const LiteralGraph) u32 {
        return self.template_count;
    }

    /// The graph node a scope key's scheme belongs to.
    pub fn nodeOfScope(self: *const LiteralGraph, key: LiteralScopeKey) u32 {
        return key.template orelse self.defaultsNode();
    }

    /// The graph node an edge's callee scheme belongs to, or null for a
    /// scheme of another module.
    pub fn calleeNode(self: *const LiteralGraph, owner: canonical.CheckedModuleRef, callee: LiteralCallee) ?u32 {
        return switch (callee) {
            .template => |template| if (template.module.eql(owner)) template.template.index() else null,
            .scope => |scope| self.scope_owners[@backingInt(scope)] orelse self.defaultsNode(),
        };
    }

    /// Node `node`'s edges and own literals, which its component's
    /// assignment computed.
    pub fn finishedNode(self: *const LiteralGraph, node: u32) *const LiteralNodeEdges {
        return self.node_slots[node].peek() orelse
            checkedModuleInvariant("a literal graph node was read before its edges were computed", .{});
    }

    /// The leader of node `node`'s component, or null before an assignment
    /// reaches the node.
    pub fn leaderOf(self: *const LiteralGraph, node: u32) ?u32 {
        return self.components.leaderOf(node);
    }

    /// Component `leader`'s members and callee components.
    pub fn componentInfo(self: *const LiteralGraph, leader: u32) *const CallGraphComponentInfo {
        return self.components.info(leader);
    }

    /// The local schemes node `node`'s edges instantiate, which its
    /// component's assignment computed.
    pub fn calleesOf(self: *const LiteralGraph, node: u32) []const u32 {
        return self.finishedNode(node).callees;
    }

    /// The first node whose body reaches a value reference or a local
    /// function construction at `expr`, whichever comes first; null when no
    /// literal walk reads the expression's evidence.
    pub fn firstSiteWalker(self: *const LiteralGraph, expr: u32) ?u32 {
        const by_ref: ?u32 = if (self.value_ref_firsts.get(expr)) |first| first.node else null;
        const by_scope = self.scope_site_firsts.get(expr);
        if (by_ref) |ref_node| return if (by_scope) |scope_node| @min(ref_node, scope_node) else ref_node;
        return by_scope;
    }

    pub fn destroy(self: *LiteralGraph, allocator: Allocator) void {
        for (self.component_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        for (self.demand_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        for (self.node_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        for (self.pool_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        if (self.module_pool_slot.peek()) |result| result.destroy(allocator);
        if (self.order_slot.peek()) |result| result.destroy(allocator);
        self.components.deinit(allocator);
        allocator.free(self.component_slots);
        allocator.free(self.demand_slots);
        allocator.free(self.node_slots);
        allocator.free(self.pool_slots);
        allocator.free(self.scope_owners);
        self.value_ref_firsts.deinit(allocator);
        self.scope_site_firsts.deinit(allocator);
        allocator.destroy(self);
    }
};

/// The first node holding a value reference at an expression, and the
/// reference.
pub const LiteralValueRefFirst = struct {
    node: u32,
    ref: ResolvedValueRefId,
};

fn orderU32(key: u32, item: u32) std.math.Order {
    return std.math.order(key, item);
}

/// One strongly connected component of a module's call graph
/// (`LazyComponents`): its members, ascending (the first is its leader), and
/// the leaders of the other components its members' edges reach, ascending.
pub const CallGraphComponentInfo = struct {
    members: []const u32,
    callees: []const u32,

    /// Node `node`'s index among the members.
    pub fn memberIndex(self: *const CallGraphComponentInfo, node: u32) u32 {
        const index = std.sort.binarySearch(u32, self.members, node, orderU32) orelse checkedModuleInvariant("a node was looked up in a component it is no member of", .{});
        return @intCast(index);
    }

    pub fn destroy(self: *CallGraphComponentInfo, allocator: Allocator) void {
        allocator.free(self.members);
        allocator.free(self.callees);
        allocator.destroy(self);
    }
};

/// The strongly connected components of a module's call graph over dense
/// nodes, assigned as consumers reach them rather than for the whole module.
/// A component is named by its least member, its leader. An assignment from
/// a node reads the finished edges of every unassigned node it reaches, so
/// a consumer computes those before taking `mutex`, which is held around one
/// assignment only.
pub const LazyComponents = struct {
    mutex: std.Io.Mutex = .init,
    /// Each node's leader; `unassigned` until an assignment reaches the node.
    /// A node is assigned only after every node it reaches is.
    node_leaders: []std.atomic.Value(u32),
    /// Each component's record, by its leader.
    infos: []std.atomic.Value(?*CallGraphComponentInfo),

    pub const unassigned = std.math.maxInt(u32);

    pub fn init(allocator: Allocator, node_count: usize) Allocator.Error!LazyComponents {
        const node_leaders = try allocator.alloc(std.atomic.Value(u32), node_count);
        errdefer allocator.free(node_leaders);
        @memset(node_leaders, .init(unassigned));
        const infos = try allocator.alloc(std.atomic.Value(?*CallGraphComponentInfo), node_count);
        @memset(infos, .init(null));
        return .{ .node_leaders = node_leaders, .infos = infos };
    }

    pub fn deinit(self: *LazyComponents, allocator: Allocator) void {
        for (self.infos) |*slot| if (slot.load(.acquire)) |record| record.destroy(allocator);
        allocator.free(self.node_leaders);
        allocator.free(self.infos);
    }

    /// The leader of node `node`'s component, or null before an assignment
    /// reaches the node.
    pub fn leaderOf(self: *const LazyComponents, node: u32) ?u32 {
        const leader = self.node_leaders[node].load(.acquire);
        return if (leader == unassigned) null else leader;
    }

    /// Component `leader`'s record.
    pub fn info(self: *const LazyComponents, leader: u32) *const CallGraphComponentInfo {
        return self.infos[leader].load(.acquire) orelse
            checkedModuleInvariant("a call graph component was read before its assignment", .{});
    }

    /// Assign every node `start` reaches and no assignment has reached yet to
    /// its strongly connected component (Tarjan's algorithm, iteratively),
    /// creating each new component's record. `graph.calleesOf(node)` gives
    /// each such node's finished callees. The caller holds `mutex`.
    pub fn assign(self: *LazyComponents, allocator: Allocator, start: u32, graph: anytype) Allocator.Error!void {
        if (self.leaderOf(start) != null) return;
        var order = std.AutoHashMapUnmanaged(u32, u32).empty;
        defer order.deinit(allocator);
        var low = std.AutoHashMapUnmanaged(u32, u32).empty;
        defer low.deinit(allocator);
        var on_stack = std.AutoHashMapUnmanaged(u32, void).empty;
        defer on_stack.deinit(allocator);
        var stack: std.ArrayList(u32) = .empty;
        defer stack.deinit(allocator);
        const Frame = struct { node: u32, next: u32 };
        var frames: std.ArrayList(Frame) = .empty;
        defer frames.deinit(allocator);
        var members: std.ArrayList(u32) = .empty;
        defer members.deinit(allocator);
        var callees: std.ArrayList(u32) = .empty;
        defer callees.deinit(allocator);
        var next_order: u32 = 0;

        try order.put(allocator, start, next_order);
        try low.put(allocator, start, next_order);
        next_order += 1;
        try stack.append(allocator, start);
        try on_stack.put(allocator, start, {});
        try frames.append(allocator, .{ .node = start, .next = 0 });
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            const node = frame.node;
            const successors = graph.calleesOf(node);
            if (frame.next < successors.len) {
                const callee = successors[frame.next];
                frame.next += 1;
                if (self.leaderOf(callee) != null) continue;
                if (order.get(callee)) |callee_order| {
                    if (on_stack.contains(callee)) {
                        const node_low = low.getPtr(node).?;
                        node_low.* = @min(node_low.*, callee_order);
                    }
                    continue;
                }
                try order.put(allocator, callee, next_order);
                try low.put(allocator, callee, next_order);
                next_order += 1;
                try stack.append(allocator, callee);
                try on_stack.put(allocator, callee, {});
                try frames.append(allocator, .{ .node = callee, .next = 0 });
                continue;
            }
            _ = frames.pop();
            const node_low = low.get(node).?;
            if (frames.items.len != 0) {
                const parent_low = low.getPtr(frames.items[frames.items.len - 1].node).?;
                parent_low.* = @min(parent_low.*, node_low);
            }
            if (node_low != order.get(node).?) continue;

            members.clearRetainingCapacity();
            while (stack.pop()) |member| {
                _ = on_stack.remove(member);
                try members.append(allocator, member);
                if (member == node) break;
            }
            std.mem.sort(u32, members.items, {}, std.sort.asc(u32));
            const leader = members.items[0];
            // Every callee outside the component is assigned already: Tarjan
            // completes a component's callee components before it.
            callees.clearRetainingCapacity();
            for (members.items) |member| for (graph.calleesOf(member)) |callee| {
                if (std.sort.binarySearch(u32, members.items, callee, orderU32) != null) continue;
                try callees.append(allocator, self.leaderOf(callee) orelse
                    checkedModuleInvariant("a call graph component was assigned before its callee component", .{}));
            };
            std.mem.sort(u32, callees.items, {}, std.sort.asc(u32));
            var kept: usize = 0;
            for (callees.items, 0..) |callee, index| {
                if (index != 0 and callees.items[index - 1] == callee) continue;
                callees.items[kept] = callee;
                kept += 1;
            }
            const record = try allocator.create(CallGraphComponentInfo);
            errdefer allocator.destroy(record);
            const owned_members = try allocator.dupe(u32, members.items);
            errdefer allocator.free(owned_members);
            record.* = .{ .members = owned_members, .callees = try allocator.dupe(u32, callees.items[0..kept]) };
            self.infos[leader].store(record, .release);
            for (members.items) |member| self.node_leaders[member].store(leader, .release);
        }
    }
};

/// Every component of a module's literal graph, by leader, numbered as
/// Tarjan's algorithm over the nodes in node order completes them (callees
/// first).
pub const LiteralComponentOrder = struct {
    leaders: []const u32,

    pub fn destroy(self: *LiteralComponentOrder, allocator: Allocator) void {
        allocator.free(self.leaders);
        allocator.destroy(self);
    }
};

/// An edge a node's body reaches, with the node holding it.
pub const LiteralReachedEdge = struct {
    key: LiteralEdge,
    holder: u32,
};

/// One node's part of a module's literal graph (`ModuleAnalyses.literalNode`).
pub const LiteralNodeEdges = struct {
    /// The node's own open literals.
    own_sites: []const LiteralOwnSite,
    /// The edges the node holds, in the order its body first reaches them.
    edges: []const LiteralGraphEdge,
    /// `edges` by key, sorted: evidence node edges and use edges apart.
    node_keys: []const LiteralEdgeIndex,
    use_keys: []const LiteralEdgeIndex,
    /// Every edge a template's body reaches, each once, in the order it
    /// first reaches them; empty for the defaulted-field node.
    reached: []const LiteralReachedEdge,
    /// The nodes of the local schemes `edges` instantiate, each once.
    callees: []const u32,

    /// The index in `edges` of the edge keyed `edge`, or null when the node
    /// does not hold it.
    pub fn edgeIndex(self: *const LiteralNodeEdges, edge: LiteralEdge) ?u32 {
        const entries: []const LiteralEdgeIndex, const key: u64 = switch (edge) {
            .node => |id| .{ self.node_keys, @bitCast(id) },
            .use => |expr| .{ self.use_keys, @backingInt(expr) },
            .literal => return null,
        };
        const found = std.sort.binarySearch(LiteralEdgeIndex, entries, key, LiteralEdgeIndex.order) orelse return null;
        return entries[found].edge;
    }

    pub fn destroy(self: *LiteralNodeEdges, allocator: Allocator) void {
        allocator.free(self.own_sites);
        allocator.free(self.edges);
        allocator.free(self.node_keys);
        allocator.free(self.use_keys);
        allocator.free(self.reached);
        allocator.free(self.callees);
        allocator.destroy(self);
    }
};

/// The first node, in node order, whose literal walk reaches each evidence
/// node of one evidence pool, sorted by evidence node.
pub const LiteralPoolHolders = struct {
    holders: []const LiteralEdgeIndex,

    pub fn holder(self: *const LiteralPoolHolders, id: static_dispatch.EvidenceNodeId) ?u32 {
        const found = std.sort.binarySearch(LiteralEdgeIndex, self.holders, @as(u64, @bitCast(id)), LiteralEdgeIndex.order) orelse return null;
        return self.holders[found].edge;
    }

    pub fn destroy(self: *LiteralPoolHolders, allocator: Allocator) void {
        allocator.free(self.holders);
        allocator.destroy(self);
    }
};

/// The identity of an edge a component's literal arguments are listed by:
/// its holding node and its index among that node's edges.
pub fn literalEdgeRef(node: u32, index: u32) u64 {
    return (@as(u64, node) << 32) | index;
}

/// The literal kind of a plan with a generated literal operand.
fn literalKindOfPlan(table: *const static_dispatch.StaticDispatchPlanTable, plan: static_dispatch.RecordedDispatchPlan) ?LiteralArgumentKind {
    for (plan.argsSlice(table)) |operand| switch (operand) {
        .generated_numeral => return .numeral,
        .generated_quote => return .quote,
        .generated_interpolation_segments => return .interpolation,
        .checked_expr, .literal_pattern_value, .literal_pattern_conversion => {},
    };
    return null;
}

/// Walks the evidence a body's dispatch reaches and reports every edge it
/// holds: each procedure target the evidence names, through nested
/// evidence, alias scopes and generated codecs.
const LiteralEdgeWalker = struct {
    allocator: Allocator,
    dispatch: CheckedDispatch,
    /// Whether the walk follows generated codecs' calls, whose evidence
    /// is the module resolution's own.
    follow_derivations: bool = true,
    stack: std.ArrayListUnmanaged(static_dispatch.EvidenceNodeId) = .empty,
    visited_derivations: collections.DenseMapUnmanaged(static_dispatch.GeneratedCodecDerivationId, void) = .empty,

    const Found = struct {
        id: static_dispatch.EvidenceNodeId,
        template: canonical.ProcedureTemplateRef,
        alias: bool,
    };

    fn deinit(self: *LiteralEdgeWalker) void {
        self.stack.deinit(self.allocator);
        self.visited_derivations.deinit(self.allocator);
    }

    /// Every edge of `node_id` and of the nodes its evidence reaches, and of
    /// the nodes already queued.
    fn nodes(self: *LiteralEdgeWalker, node_id: static_dispatch.EvidenceNodeId, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        try self.stack.append(self.allocator, node_id);
        try self.drain(out);
    }

    fn drain(self: *LiteralEdgeWalker, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        while (self.stack.pop()) |id| {
            const node = try self.dispatch.evidenceNode(id);
            switch (node.target.kind) {
                .procedure => |procedure| try out.append(self.allocator, .{ .id = id, .template = procedure.template, .alias = node.instantiation == .alias }),
                // A method declared in a function body is called through
                // its function value, whose scheme its construction or use
                // instantiates.
                .local_proc, .structural => {},
            }
            switch (node.nested) {
                .resolved => try self.entries(try self.dispatch.nestedEvidence(node)),
                .through_alias => try self.entries(try self.dispatch.aliasScopeEvidence(node)),
                .from_callable => {},
            }
        }
    }

    fn entries(self: *LiteralEdgeWalker, evidence: []const static_dispatch.CheckedEvidence) Allocator.Error!void {
        for (evidence) |entry| {
            switch (entry.resolution) {
                .direct => |nested| try self.stack.append(self.allocator, nested),
                .structural => |structural| if (structural.generated_codec_derivation) |id| try self.derivationNodes(id),
                .constraint, .from_callable, .from_scheme, .checked_error, .unreachable_value => {},
            }
            for (try self.dispatch.evidenceEntries(entry.callable_contracts)) |contract| switch (contract.resolution) {
                .direct => |nested| try self.stack.append(self.allocator, nested),
                .structural => |structural| if (structural.generated_codec_derivation) |id| try self.derivationNodes(id),
                .constraint, .from_callable, .from_scheme, .checked_error, .unreachable_value => {},
            };
        }
    }

    /// Queue the method calls a generated codec's body makes, through the
    /// codecs it nests.
    fn derivationNodes(self: *LiteralEdgeWalker, first: static_dispatch.GeneratedCodecDerivationId) Allocator.Error!void {
        if (!self.follow_derivations) return;
        var pending: std.ArrayListUnmanaged(static_dispatch.GeneratedCodecDerivationId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, first);
        while (pending.pop()) |id| {
            if ((try self.visited_derivations.getOrPut(self.allocator, id)).found_existing) continue;
            const codecs = try self.dispatch.generatedCodecs();
            const derivation = codecs.generated_codec_derivations[@backingInt(id)];
            for (derivation.callsSlice(&codecs)) |call| switch (call.resolution) {
                .callable => |node| try self.stack.append(self.allocator, node),
                .structural => |nested| try pending.append(self.allocator, nested),
                .pending, .checked_error => {},
            };
        }
    }

    /// Every edge the evidence recorded at use site `expr` reaches.
    fn site(self: *LiteralEdgeWalker, expr: CIR.Expr.Idx, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        const evidence = (try self.dispatch.siteEvidence(expr)) orelse return;
        try self.entries(evidence);
        try self.drain(out);
    }

    /// Every edge a plan's resolution reaches.
    fn plan(self: *LiteralEdgeWalker, plan_value: static_dispatch.StaticDispatchCallPlan, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        switch (plan_value.resolution) {
            .direct_closed, .direct_parametric => |direct| try self.nodes(direct.evidence, out),
            // A generated codec's calls are edges of the scope that reaches
            // the codec.
            .structural => if (plan_value.generated_codec_derivation) |id| {
                try self.derivationNodes(id);
                try self.drain(out);
            },
            .evidence_dependent, .checked_error, .@"unreachable", .direct_pending => {},
        }
    }
};

/// The template a procedure value reference instantiates the scheme of: the
/// procedure's, or an exact procedure alias's entry wrapper, whose scheme is
/// the alias's. A use of a computed callable instantiates nothing.
fn literalTemplateOfValueRef(dispatch: CheckedDispatch, ref: ResolvedValueRef) Allocator.Error!?canonical.ProcedureTemplateRef {
    const source = dispatch.source;
    const owner = source.key.digest();
    const import_views = try dispatchImportViews(dispatch);
    const use: ProcedureUseTemplate = switch (ref) {
        .top_level_proc, .imported_proc, .promoted_top_level_proc => |use| use,
        .platform_required_proc => |required| required.procedure,
        .hosted_proc, .top_level_const, .imported_const, .selected_hoisted_const, .platform_required_const, .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .platform_required_declaration, .platform_required_checked_error => return null,
    };
    var alias_view: ?ImportedModuleView = null;
    const body: ProcedureBindingBody = switch (use.binding) {
        .top_level => |top_level| blk: {
            if (!top_level.module.eql(owner)) return null;
            break :blk source.top_level_procedure_bindings.get(top_level.binding).body;
        },
        .imported => |imported| blk: {
            const view = import_views.viewForKey(imported.module) orelse return null;
            alias_view = view;
            const binding = try importedProcedureBindingForDef(view, imported.def) orelse return null;
            break :blk binding.body;
        },
        .hosted, .platform_required => return null,
    };
    return switch (body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template| template,
            .lifted, .synthetic => null,
        },
        .callable_eval_template => |template_id| blk: {
            const eval_templates: CallableEvalTemplateTableView = if (alias_view) |view| (try view.checkedTables()).callable_eval_templates.view() else source.callable_eval_templates;
            const template = eval_templates.templates[@backingInt(template_id)];
            if (template.forwarded_lookup == null) break :blk null;
            const wrapper_table: *const EntryWrapperTable = if (alias_view) |view| &(try view.checkedTables()).entry_wrappers else source.entry_wrappers;
            const wrapper = wrapper_table.lookupByRoot(template.root) orelse
                checkedModuleInvariant("a callable-eval template's root has no entry wrapper", .{});
            break :blk wrapper.template;
        },
        .checked_error => null,
    };
}

/// The scheme a value reference's use instantiates, which its use edge
/// names; null when the use instantiates none.
fn literalValueRefCallee(dispatch: CheckedDispatch, record: ResolvedValueRefRecord) Allocator.Error!?LiteralCallee {
    return switch (record.ref) {
        .local_proc => |local| if (local.dispatch_scope) |scope| .{ .scope = scope } else null,
        .top_level_proc, .imported_proc, .promoted_top_level_proc, .platform_required_proc, .hosted_proc, .top_level_const, .imported_const, .selected_hoisted_const, .platform_required_const, .local_param, .local_value, .local_mutable_version, .pattern_binder, .platform_required_declaration, .platform_required_checked_error => if (try literalTemplateOfValueRef(dispatch, record.ref)) |template| .{ .template = template } else null,
    };
}

/// Walk node `node`'s body in the order the literal graph reads it: its
/// plans, its value references, then the constructions of its generalized
/// local functions (the defaulted-field node reads only its plans that
/// resolved to a direct call). `sink` receives each read's evidence edges
/// (`evidence`) and each use edge (`use`).
fn walkLiteralNode(
    dispatch: CheckedDispatch,
    graph: *const LiteralGraph,
    node: u32,
    walker: *LiteralEdgeWalker,
    found: *std.ArrayListUnmanaged(LiteralEdgeWalker.Found),
    sink: anytype,
) Allocator.Error!void {
    const source = dispatch.source;
    const templates = source.templates;
    const refs = source.refs;
    const sites = &templates.dispatch_sites;
    const scopes = templates.dispatch_scopes;
    if (node < graph.template_count) {
        const template = templates.templates.items[node];
        const plan_start = template.static_dispatch_plans.start;
        for (templates.dispatch_plan_refs[plan_start..][0..template.static_dispatch_plans.len], 0..) |plan_id, i| {
            const plan = try dispatch.plan(plan_id);
            found.clearRetainingCapacity();
            try walker.plan(plan, found);
            try sink.evidence(found.items, literalScopeKeyOf(node, templates.dispatch_ref_scopes[plan_start + i]), @fromBackingInt(@intCast(plan.node)));
        }
        const ref_start = template.resolved_value_refs.start;
        for (refs.template_refs[ref_start..][0..template.resolved_value_refs.len], 0..) |ref_id, i| {
            try walkLiteralValueRef(dispatch, walker, found, refs.records[@backingInt(ref_id)], literalScopeKeyOf(node, sites.value_ref_scopes[ref_start + i]), sink);
        }
        const site_span = sites.scopeSiteSpan(node);
        for (sites.scope_sites[site_span.start..][0..site_span.len]) |scope_site| {
            const parent = scopes[@backingInt(scope_site.scope)].parent;
            try walkLiteralScopeSite(walker, found, scope_site, .{ .template = node, .scope = if (parent) |p| @backingInt(p) else null }, sink);
        }
        return;
    }
    const span = sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
    for (templates.dispatch_plan_refs[span.start..][0..span.len]) |plan_id| {
        const plan = try dispatch.plan(plan_id);
        switch (plan.resolution) {
            .direct_closed, .direct_parametric => {
                found.clearRetainingCapacity();
                try walker.plan(plan, found);
                try sink.evidence(found.items, null, @fromBackingInt(@intCast(plan.node)));
            },
            .evidence_dependent, .checked_error, .@"unreachable", .structural, .direct_pending => {},
        }
    }
    const value_refs = sites.defaultRefs(TemplateDispatchSites.default_value_refs);
    for (refs.template_refs[value_refs.start..][0..value_refs.len]) |ref_id| {
        try walkLiteralValueRef(dispatch, walker, found, refs.records[@backingInt(ref_id)], null, sink);
    }
    const default_sites = sites.scopeSiteSpan(sites.defaultsIndex());
    for (sites.scope_sites[default_sites.start..][0..default_sites.len]) |scope_site| {
        const parent = scopes[@backingInt(scope_site.scope)].parent;
        try walkLiteralScopeSite(walker, found, scope_site, if (parent) |p| .{ .template = null, .scope = @backingInt(p) } else null, sink);
    }
}

fn walkLiteralValueRef(
    dispatch: CheckedDispatch,
    walker: *LiteralEdgeWalker,
    found: *std.ArrayListUnmanaged(LiteralEdgeWalker.Found),
    record: ResolvedValueRefRecord,
    scope: ?LiteralScopeKey,
    sink: anytype,
) Allocator.Error!void {
    found.clearRetainingCapacity();
    try walker.site(record.expr, found);
    try sink.evidence(found.items, scope, record.expr);
    const callee = (try literalValueRefCallee(dispatch, record)) orelse return;
    try sink.use(.{
        .key = .{ .use = record.expr },
        .holder = undefined, // Set by the sink to the node holding the edge.
        .callee = callee,
        .scope = scope,
        .owner_expr = record.expr,
        .subst = .{ .site = record.expr },
    });
}

fn walkLiteralScopeSite(
    walker: *LiteralEdgeWalker,
    found: *std.ArrayListUnmanaged(LiteralEdgeWalker.Found),
    scope_site: CollectedScopeConstructionSite,
    scope: ?LiteralScopeKey,
    sink: anytype,
) Allocator.Error!void {
    found.clearRetainingCapacity();
    try walker.site(scope_site.checked_expr, found);
    try sink.evidence(found.items, scope, scope_site.checked_expr);
    try sink.use(.{
        .key = .{ .use = scope_site.checked_expr },
        .holder = undefined, // Set by the sink to the node holding the edge.
        .callee = .{ .scope = scope_site.scope },
        .scope = scope,
        .owner_expr = scope_site.checked_expr,
        .subst = .{ .site = scope_site.checked_expr },
    });
}

/// The module's literal call graph: the owner of each generalized local
/// scope and the first node reaching each value reference and each local
/// function construction. Everything that needs dispatch resolution is a
/// slot of its own.
pub fn computeLiteralGraph(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*LiteralGraph {
    const source = dispatch.source;
    const templates = source.templates;
    const refs = source.refs;
    const sites = &templates.dispatch_sites;
    const scopes = templates.dispatch_scopes;
    const template_count: u32 = @intCast(templates.templates.items.len);
    const node_count = template_count + 1;

    const scope_owners = try allocator.alloc(?u32, scopes.len);
    errdefer allocator.free(scope_owners);
    @memset(scope_owners, null);
    for (sites.scope_site_spans[0..sites.walkedTemplateCount()], 0..) |span, template_index| {
        for (sites.scope_sites[span.start..][0..span.len]) |scope_site| {
            var current: ?DispatchScopeId = scope_site.scope;
            while (current) |id| {
                scope_owners[@backingInt(id)] = @intCast(template_index);
                current = scopes[@backingInt(id)].parent;
            }
        }
    }

    var value_ref_firsts = std.AutoHashMapUnmanaged(u32, LiteralValueRefFirst).empty;
    errdefer value_ref_firsts.deinit(allocator);
    var scope_site_firsts = std.AutoHashMapUnmanaged(u32, u32).empty;
    errdefer scope_site_firsts.deinit(allocator);
    for (0..node_count) |raw_node| {
        const node: u32 = @intCast(raw_node);
        const value_refs = if (node < template_count) blk: {
            const span = templates.templates.items[node].resolved_value_refs;
            break :blk refs.template_refs[span.start..][0..span.len];
        } else blk: {
            const span = sites.defaultRefs(TemplateDispatchSites.default_value_refs);
            break :blk refs.template_refs[span.start..][0..span.len];
        };
        for (value_refs) |ref_id| {
            const entry = try value_ref_firsts.getOrPut(allocator, @backingInt(refs.records[@backingInt(ref_id)].expr));
            if (!entry.found_existing) entry.value_ptr.* = .{ .node = node, .ref = ref_id };
        }
        const site_span = sites.scopeSiteSpan(if (node < template_count) node else sites.defaultsIndex());
        for (sites.scope_sites[site_span.start..][0..site_span.len]) |scope_site| {
            const entry = try scope_site_firsts.getOrPut(allocator, @backingInt(scope_site.checked_expr));
            if (!entry.found_existing) entry.value_ptr.* = node;
        }
    }

    const node_slots = try allocator.alloc(LiteralNodeSlot, node_count);
    errdefer allocator.free(node_slots);
    @memset(node_slots, .empty);
    const pool_slots = try allocator.alloc(LiteralPoolSlot, template_count);
    errdefer allocator.free(pool_slots);
    @memset(pool_slots, .empty);
    var components = try LazyComponents.init(allocator, node_count);
    errdefer components.deinit(allocator);
    const component_slots = try allocator.alloc(LiteralComponentSlot, node_count);
    errdefer allocator.free(component_slots);
    @memset(component_slots, .empty);
    const demand_slots = try allocator.alloc(LiteralDemandSlot, template_count);
    errdefer allocator.free(demand_slots);
    @memset(demand_slots, .empty);

    const result = try allocator.create(LiteralGraph);
    result.* = .{
        .template_count = template_count,
        .scope_owners = scope_owners,
        .value_ref_firsts = value_ref_firsts,
        .scope_site_firsts = scope_site_firsts,
        .node_slots = node_slots,
        .pool_slots = pool_slots,
        .components = components,
        .component_slots = component_slots,
        .demand_slots = demand_slots,
    };
    return result;
}

/// The first node, in node order, whose body holds the use edge keyed by
/// `expr`; null when no body does.
pub fn literalUseHolder(dispatch: CheckedDispatch, graph: *const LiteralGraph, expr: CIR.Expr.Idx) Allocator.Error!?u32 {
    const key = @backingInt(expr);
    var holder: ?u32 = graph.scope_site_firsts.get(key);
    if (graph.value_ref_firsts.get(key)) |first| {
        if (try literalValueRefCallee(dispatch, dispatch.source.refs.records[@backingInt(first.ref)]) != null) {
            holder = if (holder) |scope_node| @min(scope_node, first.node) else first.node;
        }
    }
    return holder;
}

/// Node `node`'s part of the literal graph: its own open literals, the
/// edges it holds (those no earlier node's body reaches), every edge a
/// template's body reaches, and the nodes of the local schemes its edges
/// instantiate.
pub fn computeLiteralNodeEdges(allocator: Allocator, dispatch: CheckedDispatch, graph: *LiteralGraph, node: u32) Allocator.Error!*LiteralNodeEdges {
    const source = dispatch.source;
    const owner = source.key.digest();
    const templates = source.templates;
    const plans = source.plans;
    const sites = &templates.dispatch_sites;
    const bodies = dispatchSourceBodies(source);

    // Own sites: each open literal conversion plan is a literal requirement
    // of the innermost scheme around it.
    var own_sites: std.ArrayList(LiteralOwnSite) = .empty;
    defer own_sites.deinit(allocator);
    if (node < graph.template_count) {
        const template = templates.templates.items[node];
        const start = template.static_dispatch_plans.start;
        for (templates.dispatch_plan_refs[start..][0..template.static_dispatch_plans.len], 0..) |plan_id, i| {
            const kind = literalKindOfPlan(plans, plans.plans[@backingInt(plan_id)]) orelse continue;
            const plan = try dispatch.plan(plan_id);
            switch (plan.resolution) {
                .evidence_dependent, .direct_parametric => {},
                .direct_closed, .checked_error, .@"unreachable", .structural => continue,
                .direct_pending => checkedModuleInvariant("a literal conversion plan was left pending at literal argument analysis", .{}),
            }
            // The literal requirement's type is the converted value's: the
            // literal's own for a numeral or a quote, the assembler's for an
            // interpolation.
            const ty = switch (kind) {
                .interpolation => blk: {
                    const expr: CIR.Expr.Idx = @fromBackingInt(@intCast(plan.node));
                    if (bodies.exprData(expr) != .interpolation) checkedModuleInvariant("a literal conversion plan's expression is not a literal", .{});
                    break :blk try bodies.interpolationAssemblerType(expr);
                },
                .numeral, .quote => (try bodies.literalConversion(plan.node)).ty,
            };
            try own_sites.append(allocator, .{
                .scope = literalScopeKeyOf(node, templates.dispatch_ref_scopes[start + i]),
                .site = .{ .module = owner, .node = plan.node, .kind = kind },
                .ty = ty,
            });
        }
    } else {
        const span = sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[span.start..][0..span.len]) |plan_id| {
            if (literalKindOfPlan(plans, plans.plans[@backingInt(plan_id)]) == null) continue;
            const plan = try dispatch.plan(plan_id);
            switch (plan.resolution) {
                .evidence_dependent, .direct_parametric => checkedModuleInvariant("a defaulted field expression's literal has no scheme to carry its obligation", .{}),
                .direct_closed, .checked_error, .@"unreachable", .structural => {},
                .direct_pending => checkedModuleInvariant("a literal conversion plan was left pending at literal argument analysis", .{}),
            }
        }
    }

    const Sink = struct {
        allocator: Allocator,
        dispatch: CheckedDispatch,
        graph: *LiteralGraph,
        owner: canonical.CheckedModuleRef,
        node: u32,
        holds: bool,
        edges: std.ArrayList(LiteralGraphEdge) = .empty,
        added: std.AutoHashMapUnmanaged(LiteralEdge, void) = .empty,
        reached: std.ArrayList(LiteralReachedEdge) = .empty,
        reached_keys: std.AutoHashMapUnmanaged(LiteralEdge, void) = .empty,

        fn deinit(self: *@This()) void {
            self.edges.deinit(self.allocator);
            self.added.deinit(self.allocator);
            self.reached.deinit(self.allocator);
            self.reached_keys.deinit(self.allocator);
        }

        fn place(self: *@This(), key: LiteralEdge, holder: u32) Allocator.Error!bool {
            // The node reaches the edge, so the first node reaching it comes
            // no later.
            if (holder > self.node) checkedModuleInvariant("a literal edge's holder comes after a node whose body reaches it", .{});
            if (self.holds and !(try self.reached_keys.getOrPut(self.allocator, key)).found_existing) {
                try self.reached.append(self.allocator, .{ .key = key, .holder = holder });
            }
            if (holder != self.node) return false;
            return !(try self.added.getOrPut(self.allocator, key)).found_existing;
        }

        pub fn evidence(self: *@This(), items: []const LiteralEdgeWalker.Found, scope: ?LiteralScopeKey, owner_expr: CIR.Expr.Idx) Allocator.Error!void {
            for (items) |item| {
                // An alias chain that leaves this module is instantiated
                // where the chain's procedure lives.
                if (item.alias and !item.template.module.eql(self.owner)) continue;
                const holder = (try self.dispatch.source.analyses.literalEvidenceHolder(self.dispatch, self.graph, item.id)) orelse
                    checkedModuleInvariant("a literal edge reached from a body has no holder", .{});
                if (!try self.place(.{ .node = item.id }, holder)) continue;
                try self.edges.append(self.allocator, .{
                    .key = .{ .node = item.id },
                    .holder = self.node,
                    .callee = .{ .template = item.template },
                    .scope = scope,
                    .owner_expr = owner_expr,
                    .subst = if (item.alias) .{ .alias_chain = item.id } else .{ .evidence = (try self.dispatch.evidenceNode(item.id)).subst },
                });
            }
        }

        pub fn use(self: *@This(), edge: LiteralGraphEdge) Allocator.Error!void {
            const holder = (try literalUseHolder(self.dispatch, self.graph, edge.key.use)) orelse
                checkedModuleInvariant("a use edge reached from a body has no holder", .{});
            if (!try self.place(edge.key, holder)) return;
            var placed = edge;
            placed.holder = self.node;
            try self.edges.append(self.allocator, placed);
        }
    };
    var sink: Sink = .{
        .allocator = allocator,
        .dispatch = dispatch,
        .graph = graph,
        .owner = owner,
        .node = node,
        .holds = node < graph.template_count,
    };
    defer sink.deinit();
    var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = dispatch };
    defer walker.deinit();
    var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
    defer found.deinit(allocator);
    try walkLiteralNode(dispatch, graph, node, &walker, &found, &sink);

    var node_keys: std.ArrayList(LiteralEdgeIndex) = .empty;
    defer node_keys.deinit(allocator);
    var use_keys: std.ArrayList(LiteralEdgeIndex) = .empty;
    defer use_keys.deinit(allocator);
    var callees: std.ArrayList(u32) = .empty;
    defer callees.deinit(allocator);
    var seen_callees = std.AutoHashMapUnmanaged(u32, void).empty;
    defer seen_callees.deinit(allocator);
    for (sink.edges.items, 0..) |edge, index| {
        switch (edge.key) {
            .node => |id| try node_keys.append(allocator, .{ .key = @bitCast(id), .edge = @intCast(index) }),
            .use => |expr| try use_keys.append(allocator, .{ .key = @backingInt(expr), .edge = @intCast(index) }),
            .literal => checkedModuleInvariant("a literal requirement's own literal was collected as an edge", .{}),
        }
        if (graph.calleeNode(owner, edge.callee)) |callee| {
            if (!(try seen_callees.getOrPut(allocator, callee)).found_existing) try callees.append(allocator, callee);
        }
    }
    std.mem.sort(LiteralEdgeIndex, node_keys.items, {}, LiteralEdgeIndex.lessThan);
    std.mem.sort(LiteralEdgeIndex, use_keys.items, {}, LiteralEdgeIndex.lessThan);

    const owned_own_sites = try own_sites.toOwnedSlice(allocator);
    errdefer allocator.free(owned_own_sites);
    const owned_edges = try sink.edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_edges);
    const owned_node_keys = try node_keys.toOwnedSlice(allocator);
    errdefer allocator.free(owned_node_keys);
    const owned_use_keys = try use_keys.toOwnedSlice(allocator);
    errdefer allocator.free(owned_use_keys);
    const owned_reached = try sink.reached.toOwnedSlice(allocator);
    errdefer allocator.free(owned_reached);
    const owned_callees = try callees.toOwnedSlice(allocator);
    errdefer allocator.free(owned_callees);
    const result = try allocator.create(LiteralNodeEdges);
    result.* = .{
        .own_sites = owned_own_sites,
        .edges = owned_edges,
        .node_keys = owned_node_keys,
        .use_keys = owned_use_keys,
        .reached = owned_reached,
        .callees = owned_callees,
    };
    return result;
}

/// Collects, for each evidence node a walk reaches, the least node said to
/// reach it.
const LiteralHolderCollector = struct {
    allocator: Allocator,
    holders: std.AutoHashMapUnmanaged(u64, u32) = .empty,

    fn deinit(self: *LiteralHolderCollector) void {
        self.holders.deinit(self.allocator);
    }

    fn note(self: *LiteralHolderCollector, id: static_dispatch.EvidenceNodeId, node: u32) Allocator.Error!void {
        const entry = try self.holders.getOrPut(self.allocator, @bitCast(id));
        if (!entry.found_existing or node < entry.value_ptr.*) entry.value_ptr.* = node;
    }

    fn finish(self: *LiteralHolderCollector) Allocator.Error!*LiteralPoolHolders {
        const holders = try self.allocator.alloc(LiteralEdgeIndex, self.holders.count());
        errdefer self.allocator.free(holders);
        var it = self.holders.iterator();
        var index: usize = 0;
        while (it.next()) |entry| : (index += 1) holders[index] = .{ .key = entry.key_ptr.*, .edge = entry.value_ptr.* };
        std.mem.sort(LiteralEdgeIndex, holders, {}, LiteralEdgeIndex.lessThan);
        const result = try self.allocator.create(LiteralPoolHolders);
        result.* = .{ .holders = holders };
        return result;
    }
};

/// The first node, in node order, whose body reaches each evidence node of
/// template `template`'s resolution. A literal walk enters a resolution's
/// pool only through a plan or a use site that resolution resolves, and every
/// node holding that plan or site walks it, so the first such node of the
/// plans and sites reaching an evidence node is its holder. Generated codecs'
/// calls are the module resolution's evidence, so these walks leave them.
pub fn computeLiteralPoolHolders(allocator: Allocator, dispatch: CheckedDispatch, graph: *const LiteralGraph, template: u32) Allocator.Error!*LiteralPoolHolders {
    const analyses = dispatch.source.analyses;
    const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(template);
    const owner = static_dispatch.EvidenceOwner.forTemplate(template_id);
    const resolution = try analyses.templateDispatch(dispatch, template_id);
    const index = try analyses.dispatchIndex(dispatch);
    var collector: LiteralHolderCollector = .{ .allocator = allocator };
    defer collector.deinit();
    var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = dispatch, .follow_derivations = false };
    defer walker.deinit();
    var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
    defer found.deinit(allocator);

    for (resolution.plans) |entry| {
        const plan_id: static_dispatch.StaticDispatchPlanId = @fromBackingInt(entry.plan);
        if (try analyses.planResolver(dispatch, plan_id) != template) continue;
        const first = index.planSites(plan_id)[0].template orelse graph.defaultsNode();
        found.clearRetainingCapacity();
        try walker.plan(try dispatch.plan(plan_id), &found);
        for (found.items) |item| try noteLiteralPoolHolder(&collector, owner, item.id, first);
    }
    for (resolution.site_evidence) |entry| {
        const first = graph.firstSiteWalker(entry.key) orelse continue;
        if (try analyses.siteResolver(dispatch, entry.key) != template) continue;
        found.clearRetainingCapacity();
        try walker.site(@fromBackingInt(entry.key), &found);
        for (found.items) |item| try noteLiteralPoolHolder(&collector, owner, item.id, first);
    }
    return collector.finish();
}

fn noteLiteralPoolHolder(collector: *LiteralHolderCollector, owner: static_dispatch.EvidenceOwner, id: static_dispatch.EvidenceNodeId, node: u32) Allocator.Error!void {
    if (id.owner == owner) return collector.note(id, node);
    if (id.owner.template() != null) checkedModuleInvariant("a template resolution's evidence named another template's pool", .{});
}

/// The first node, in node order, whose body reaches each evidence node of
/// the module's own resolution: generated codecs' calls and what no
/// template's chain binds, which any node's walk can reach.
pub fn computeLiteralModulePoolHolders(allocator: Allocator, dispatch: CheckedDispatch, graph: *const LiteralGraph) Allocator.Error!*LiteralPoolHolders {
    var collector: LiteralHolderCollector = .{ .allocator = allocator };
    defer collector.deinit();
    var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
    defer found.deinit(allocator);
    const Sink = struct {
        collector: *LiteralHolderCollector,
        node: u32,

        pub fn evidence(self: *@This(), items: []const LiteralEdgeWalker.Found, _: ?LiteralScopeKey, _: CIR.Expr.Idx) Allocator.Error!void {
            for (items) |item| if (item.id.owner.template() == null) try self.collector.note(item.id, self.node);
        }

        pub fn use(_: *@This(), _: LiteralGraphEdge) Allocator.Error!void {}
    };
    for (0..graph.template_count + 1) |raw_node| {
        const node: u32 = @intCast(raw_node);
        var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = dispatch };
        defer walker.deinit();
        var sink: Sink = .{ .collector = &collector, .node = node };
        try walkLiteralNode(dispatch, graph, node, &walker, &found, &sink);
    }
    return collector.finish();
}

/// Every component of the module's literal graph, by leader, in the order
/// Tarjan's algorithm over every node, in node order, completes them.
pub fn computeLiteralComponentOrder(allocator: Allocator, dispatch: CheckedDispatch, graph: *LiteralGraph) Allocator.Error!*LiteralComponentOrder {
    const node_count = graph.template_count + 1;
    const successor_starts = try allocator.alloc(u32, node_count + 1);
    defer allocator.free(successor_starts);
    var successors: std.ArrayList(u32) = .empty;
    defer successors.deinit(allocator);
    for (0..node_count) |node| {
        successor_starts[node] = @intCast(successors.items.len);
        try successors.appendSlice(allocator, (try dispatch.source.analyses.literalNode(dispatch, graph, @intCast(node))).callees);
    }
    successor_starts[node_count] = @intCast(successors.items.len);
    var components = try callGraphComponents(allocator, successor_starts, successors.items);
    defer components.deinit(allocator);
    const leaders = try allocator.alloc(u32, components.count());
    errdefer allocator.free(leaders);
    for (leaders, 0..) |*leader, component| leader.* = components.componentMembers(@intCast(component))[0];
    const result = try allocator.create(LiteralComponentOrder);
    result.* = .{ .leaders = leaders };
    return result;
}

/// What makes two literal requirements of one literal the same: the type's
/// key, which names its variables only up to renaming, and the variables
/// themselves. Instantiating an open type gives a new root every time, even
/// around a recursive cycle that maps each variable back to itself.
fn literalRequirementTypeIdentity(
    store: *const CheckedTypeStore,
    names: *const canonical.CanonicalNameStore,
    orderer: *CheckedIdentityOrderer,
    ty: CheckedTypeId,
) Allocator.Error![32]u8 {
    var view = store.view();
    view.names = names;
    const key = try view.rootKey(ty);
    if (!try store.rootContainsIdentityVariables(ty)) return key.bytes;
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(&key.bytes);
    for (try orderer.identityRoots(ty)) |variable| {
        const origin: u32 = @backingInt(store.identityOrigin(variable));
        hasher.update(std.mem.asBytes(&origin));
    }
    return hasher.finalResult();
}

/// Whether every variable of `ty` is quantified by the scheme `key` names
/// (a template's own, or a generalized local scope's) or by one enclosing it.
fn literalRequirementTypeIsBound(
    store: *const CheckedTypeStore,
    orderer: *CheckedIdentityOrderer,
    templates: *const CheckedProcedureTemplateTable,
    dispatch: CheckedDispatch,
    key: LiteralScopeKey,
    ty: CheckedTypeId,
) Allocator.Error!bool {
    variables: for (try orderer.identityRoots(ty)) |variable| {
        const origin = store.identityOrigin(variable);
        var current: ?u32 = key.scope;
        while (current) |id| {
            const dispatch_scope = templates.dispatch_scopes[id];
            for ((try dispatch.scopeSchema(@fromBackingInt(id))).vars) |bound| {
                if (store.identityOrigin(bound) == origin) continue :variables;
            }
            current = if (dispatch_scope.parent) |parent| @backingInt(parent) else null;
        }
        if (key.template) |template_index| {
            for (try dispatch.templateSchemeVars(.row(template_index))) |bound| {
                if (store.identityOrigin(bound) == origin) continue :variables;
            }
        }
        return false;
    }
    return true;
}

fn literalScopeKeyLessThan(_: void, a: LiteralScopeKey, b: LiteralScopeKey) bool {
    const a_template = a.template orelse std.math.maxInt(u32);
    const b_template = b.template orelse std.math.maxInt(u32);
    if (a_template != b_template) return a_template < b_template;
    const a_scope = a.scope orelse std.math.maxInt(u32);
    const b_scope = b.scope orelse std.math.maxInt(u32);
    return a_scope < b_scope;
}

fn comptimeRootIdLessThan(_: void, a: ComptimeRootKey, b: ComptimeRootKey) bool {
    return @backingInt(a) < @backingInt(b);
}

/// The literal requirements, edge arguments and literal argument roots of
/// one component of a module's literal graph (`ModuleAnalyses.literalComponent`).
pub const LiteralComponent = struct {
    /// The schemes of the component's nodes with literal requirements,
    /// sorted; scheme `i`'s are `requirements[scope_spans[i]]`.
    scope_keys: []const LiteralScopeKey,
    scope_spans: []const store_serialize.Span,
    requirements: []const LiteralRequirement,
    /// The edges the component's nodes hold, by `literalEdgeRef`, ascending,
    /// with their literal arguments: edge `arg_edges[i]`'s are
    /// `args[arg_spans[i]]`.
    arg_edges: []const u64,
    arg_spans: []const store_serialize.Span,
    args: []const LiteralArgSource,
    /// The component's literal argument roots, by id.
    roots: []const LiteralRootRecord,

    pub fn requirementsOf(self: *const LiteralComponent, key: LiteralScopeKey) []const LiteralRequirement {
        for (self.scope_keys, self.scope_spans) |candidate, span| {
            if (std.meta.eql(candidate, key)) return self.requirements[span.start..][0..span.len];
        }
        return &.{};
    }

    /// The literal arguments of the edge `edge` names (`literalEdgeRef`).
    pub fn edgeArgs(self: *const LiteralComponent, edge: u64) []const LiteralArgSource {
        const index = std.sort.binarySearch(u64, self.arg_edges, edge, struct {
            fn order(key: u64, item: u64) std.math.Order {
                return std.math.order(key, item);
            }
        }.order) orelse return &.{};
        const span = self.arg_spans[index];
        return self.args[span.start..][0..span.len];
    }

    pub fn root(self: *const LiteralComponent, id: ComptimeRootKey) ?*const LiteralRootRecord {
        const index = std.sort.binarySearch(LiteralRootRecord, self.roots, id, struct {
            fn order(key: ComptimeRootKey, item: LiteralRootRecord) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.root.id));
            }
        }.order) orelse return null;
        return &self.roots[index];
    }

    pub fn destroy(self: *LiteralComponent, allocator: Allocator) void {
        allocator.free(self.scope_keys);
        allocator.free(self.scope_spans);
        allocator.free(self.requirements);
        allocator.free(self.arg_edges);
        allocator.free(self.arg_spans);
        allocator.free(self.args);
        allocator.free(self.roots);
        allocator.destroy(self);
    }
};

/// The literal argument roots one template's edges read
/// (`ModuleAnalyses.templateLiteralArgumentDemand`), ascending.
pub const LiteralArgumentDemand = struct {
    roots: []const ComptimeRootKey,

    pub fn destroy(self: *LiteralArgumentDemand, allocator: Allocator) void {
        allocator.free(self.roots);
        allocator.destroy(self);
    }
};

/// One step of an exact procedure alias chain: the module its lookup is in
/// (null for this module), the lookup's site substitution, and the
/// quantified variables of the scheme the lookup instantiates, which the
/// substitution is over.
const LiteralAliasStep = struct {
    module: ?ImportedModuleView,
    lookup_subst: []const CheckedTypeId,
    vars: []const CheckedTypeId,
};

/// The scheme of a top-level alias: its callable-eval template's root
/// wrapper template, whose body is the alias's forwarded lookup.
fn literalCallableEvalAliasStep(dispatch: CheckedDispatch, alias_view: ?ImportedModuleView, pattern: CIR.Pattern.Idx) Allocator.Error!struct { lookup: CIR.Expr.Idx, vars: []const CheckedTypeId } {
    const source = dispatch.source;
    const eval_templates: CallableEvalTemplateTableView = if (alias_view) |view| (try view.checkedTables()).callable_eval_templates.view() else source.callable_eval_templates;
    const template = for (eval_templates.templates) |candidate| {
        if (candidate.pattern == pattern) break candidate;
    } else checkedModuleInvariant("a method's alias binding has no callable-eval template", .{});
    const wrapper_table: *const EntryWrapperTable = if (alias_view) |view| &(try view.checkedTables()).entry_wrappers else source.entry_wrappers;
    const wrapper = wrapper_table.lookupByRoot(template.root) orelse checkedModuleInvariant("a callable-eval template's root has no entry wrapper", .{});
    const procedure_templates: *const CheckedProcedureTemplateTable = if (alias_view) |view| &(try view.checkedTables()).checked_procedure_templates else source.templates;
    const wrapper_template = procedure_templates.get(wrapper.template.template);
    return .{
        .lookup = template.forwarded_lookup orelse checkedModuleInvariant("a method's alias binding is not an exact procedure alias", .{}),
        .vars = try (if (alias_view) |view| try view.dispatch() else dispatch).templateSchemeVars(wrapper_template.template_id),
    };
}

/// The steps of the alias chain a dispatch edge to a method bound to an
/// exact procedure alias passes through, each step's lookup instantiating
/// the next scheme; null where the chain leaves this module, whose
/// instantiation the owning module computes. Reads only finished slots and
/// tables; the composition (`composeLiteralAliasChain`) creates the types.
fn literalAliasChainSteps(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    node: static_dispatch.EvidenceNode,
    steps: *std.ArrayListUnmanaged(LiteralAliasStep),
) Allocator.Error!bool {
    const source = dispatch.source;
    const owner = source.key.digest();
    const import_views = try dispatchImportViews(dispatch);
    const alias = node.target.alias orelse checkedModuleInvariant("an alias-instantiated target has no alias binding", .{});
    switch (node.target.kind) {
        .procedure => {},
        .local_proc, .structural => checkedModuleInvariant("an alias-instantiated target is not a procedure", .{}),
    }
    // The module that declares the alias binding composes the chain; the
    // procedure it reaches may be another module's.
    if (!alias.module.eql(owner)) return false;
    var module: ?ImportedModuleView = null;
    var lookup: CIR.Expr.Idx, var vars: []const CheckedTypeId = switch (alias.binding) {
        .top_level => |pattern| blk: {
            const step = try literalCallableEvalAliasStep(dispatch, null, pattern);
            break :blk .{ step.lookup, step.vars };
        },
        .local => |local| .{ local.lookup, if (local.dispatch_scope) |scope_id| (try dispatch.scopeSchema(scope_id)).vars else &.{} },
    };
    var actual_count = (try dispatch.substitution(node.subst)).len;
    while (true) {
        if (actual_count != vars.len) checkedModuleInvariant("an alias edge's substitution differs from its alias's scheme", .{});
        const step_dispatch: CheckedDispatch = if (module) |view| try view.dispatch() else dispatch;
        const refs: *const ResolvedValueRefTable = if (module) |view| (try view.valueRefs()) else source.refs;
        const lookup_subst = (try step_dispatch.siteSubstitution(lookup)) orelse &.{};
        try steps.append(allocator, .{ .module = module, .lookup_subst = lookup_subst, .vars = vars });
        actual_count = lookup_subst.len;
        const ref_id = refs.lookupIdByExpr(lookup) orelse checkedModuleInvariant("an alias's forwarded lookup has no resolved reference", .{});
        switch (refs.records[@backingInt(ref_id)].ref) {
            .local_proc => |local| {
                if (!local.is_alias) return true;
                lookup = local.expr;
                vars = if (local.dispatch_scope) |scope_id| (try step_dispatch.scopeSchema(scope_id)).vars else &.{};
            },
            inline .top_level_proc, .imported_proc, .hosted_proc, .promoted_top_level_proc, .platform_required_proc => |ref, tag| {
                const use = if (tag == .platform_required_proc) ref.procedure else ref;
                switch (use.binding) {
                    .top_level => |top_level| {
                        const owner_key = top_level.module;
                        const local_owner = owner_key.eql(owner);
                        const bindings: *const TopLevelProcedureBindingTable = if (local_owner) source.top_level_procedure_bindings else &(try (import_views.viewForKey(owner_key) orelse return false).checkedTables()).top_level_procedure_bindings;
                        switch (bindings.get(top_level.binding).body) {
                            .callable_eval_template => |template_id| {
                                const view = if (local_owner) null else import_views.viewForKey(owner_key);
                                const eval_templates: CallableEvalTemplateTableView = if (view) |v| (try v.checkedTables()).callable_eval_templates.view() else source.callable_eval_templates;
                                if (eval_templates.templates[@backingInt(template_id)].forwarded_lookup == null) return true;
                                const step = try literalCallableEvalAliasStep(dispatch, view, eval_templates.templates[@backingInt(template_id)].pattern);
                                module = view;
                                lookup = step.lookup;
                                vars = step.vars;
                            },
                            .direct_template, .checked_error => return true,
                        }
                    },
                    .imported => |imported| {
                        const view = import_views.viewForKey(imported.module) orelse return false;
                        const binding = (try view.exportRows()).procedureBinding(imported.def, imported.pattern) orelse
                            checkedModuleInvariant("an alias chain's imported procedure was not exported by its checked module", .{});
                        switch (binding.body) {
                            .callable_eval_template => |template_id| {
                                const template = (try view.checkedTables()).callable_eval_templates.view().templates[@backingInt(template_id)];
                                if (template.forwarded_lookup == null) return true;
                                const step = try literalCallableEvalAliasStep(dispatch, view, template.pattern);
                                module = view;
                                lookup = step.lookup;
                                vars = step.vars;
                            },
                            .direct_template, .checked_error => return true,
                        }
                    },
                    .hosted, .platform_required => return true,
                }
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => checkedModuleInvariant("a forwarded procedure alias lookup names no procedure", .{}),
        }
    }
}

/// The substitution of the procedure template an alias chain ends at, in
/// this module's store: the edge's instantiation of the first alias's scheme,
/// carried through each step's forwarded lookup. Runs under the store's
/// creation lock.
fn composeLiteralAliasChain(
    allocator: Allocator,
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    first_actuals: []const CheckedTypeId,
    steps: []const LiteralAliasStep,
) Allocator.Error![]CheckedTypeId {
    var actuals = try allocator.dupe(CheckedTypeId, first_actuals);
    errdefer allocator.free(actuals);
    for (steps) |step| {
        var projector: ?CheckedTypeStoreImportProjector = if (step.module) |view| CheckedTypeStoreImportProjector.init(allocator, store, names, view) else null;
        defer if (projector) |*p| p.deinit();
        const formals = try allocator.alloc(CheckedTypeId, step.vars.len);
        defer allocator.free(formals);
        for (step.vars, formals) |variable, *out| out.* = if (projector) |*p| try p.project(variable) else variable;
        // The next scheme's variables, as the lookup instantiates them over
        // this scheme's variables, at this edge's types.
        const composed = try allocator.alloc(CheckedTypeId, step.lookup_subst.len);
        errdefer allocator.free(composed);
        for (step.lookup_subst, composed) |checked_ty, *out| {
            const projected = if (projector) |*p| try p.project(checked_ty) else checked_ty;
            var substitution = CheckedTypeSubstitution.init(allocator, formals, actuals);
            defer substitution.deinit();
            out.* = try store.cloneCheckedTypeRootSubstituting(allocator, projected, &substitution);
        }
        allocator.free(actuals);
        actuals = composed;
    }
    return actuals;
}

/// The literal requirements, edge arguments and literal argument roots of
/// component `component` of `graph` (design.md "Literal Arguments"). An
/// edge that instantiates a scheme instantiates each of the callee's
/// literal requirements at the edge's substitution: a closed type gets a
/// literal argument root of this module converting the literal at that
/// type, named by the edge and the requirement; an open one becomes a
/// literal requirement of the scope the edge is in, forwarded in turn.
/// Requirements are computed to a fixpoint over the component's edges.
/// Every callee component and every imported callee's requirements are done
/// before the component is claimed (`ModuleAnalyses.literalComponent`).
/// Types are created under the store's creation lock, which is held around
/// each creation only, after every slot the creation reads.
pub fn computeLiteralComponent(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    graph: *const LiteralGraph,
    component: u32,
) Allocator.Error!*LiteralComponent {
    const source = dispatch.source;
    const owner = source.key.digest();
    const store = source.types.store;
    const names = source.names;
    const io = source.analyses.io;
    const templates = source.templates;
    const import_views = try dispatchImportViews(dispatch);
    const members = graph.componentInfo(component).members;

    var orderer = CheckedIdentityOrderer.init(allocator, names, store);
    defer orderer.deinit();

    const ObligationKey = LiteralObligationKey;
    var states: LiteralScopeStates = .empty;
    defer {
        var it = states.valueIterator();
        while (it.next()) |state| {
            state.list.deinit(allocator);
            state.index.deinit(allocator);
        }
        states.deinit(allocator);
    }

    // The component's own open literals.
    for (members) |node| {
        for (graph.finishedNode(node).own_sites) |own| {
            const entry = try states.getOrPut(allocator, own.scope);
            if (!entry.found_existing) entry.value_ptr.* = .{};
            const slot = try entry.value_ptr.index.getOrPut(allocator, .{ .site = own.site, .ty = try literalRequirementTypeIdentity(store, names, &orderer, own.ty) });
            if (slot.found_existing) continue;
            slot.value_ptr.* = @intCast(entry.value_ptr.list.items.len);
            try entry.value_ptr.list.append(allocator, .{ .site = own.site, .ty = own.ty, .edge = .literal, .callee_requirement = 0 });
        }
    }

    const ArgBuild = union(enum) { root: ComptimeRootKey, forwarded: u32, unbound };
    const EdgeState = struct {
        /// The edge's `literalEdgeRef`.
        index: u64,
        edge: LiteralGraphEdge,
        callee: LiteralCalleeScheme,
        alias_steps: std.ArrayListUnmanaged(LiteralAliasStep) = .empty,
        /// The edge's substitution; owned when an alias chain composed it.
        subst: []const CheckedTypeId = &.{},
        owned_subst: ?[]CheckedTypeId = null,
        formals: []CheckedTypeId = &.{},
        projector: ?*CheckedTypeStoreImportProjector = null,
        substitution: ?CheckedTypeSubstitution = null,
        args: std.ArrayListUnmanaged(ArgBuild) = .empty,
    };
    var edge_states: std.ArrayListUnmanaged(EdgeState) = .empty;
    defer {
        for (edge_states.items) |*state| {
            state.alias_steps.deinit(allocator);
            if (state.owned_subst) |slice| allocator.free(slice);
            allocator.free(state.formals);
            if (state.projector) |projector| {
                projector.deinit();
                allocator.destroy(projector);
            }
            if (state.substitution) |*substitution| substitution.deinit();
            state.args.deinit(allocator);
        }
        edge_states.deinit(allocator);
    }
    var modules: std.ArrayListUnmanaged(ModuleId) = .empty;
    defer modules.deinit(allocator);
    for (members) |node| {
        for (graph.finishedNode(node).edges, 0..) |edge, edge_index| {
            const callee: LiteralCalleeScheme = switch (edge.callee) {
                .template => |template| blk: {
                    if (template.module.eql(owner)) {
                        const key: LiteralScopeKey = .{ .template = template.template.index(), .scope = null };
                        break :blk literalLocalCallee(graph, component, key, try dispatch.templateSchemeVars(template.template));
                    }
                    const view = import_views.viewForKey(template.module) orelse continue;
                    try modules.append(allocator, template.module);
                    break :blk .{
                        .live = null,
                        .finished = try (try view.dispatch()).templateLiteralRequirements(template.template),
                        .vars = try (try view.dispatch()).templateSchemeVars(template.template),
                        .module = view,
                    };
                },
                .scope => |scope_id| literalLocalCallee(
                    graph,
                    component,
                    .{ .template = graph.scope_owners[@backingInt(scope_id)], .scope = @backingInt(scope_id) },
                    (try dispatch.scopeSchema(scope_id)).vars,
                ),
            };
            var state: EdgeState = .{ .index = literalEdgeRef(node, @intCast(edge_index)), .edge = edge, .callee = callee };
            switch (edge.subst) {
                .evidence => |span| state.subst = try dispatch.substitution(span),
                .site => |expr| state.subst = (try dispatch.siteSubstitution(expr)) orelse &.{},
                .alias_chain => |id| {
                    const evidence_node = try dispatch.evidenceNode(id);
                    if (!try literalAliasChainSteps(allocator, dispatch, evidence_node, &state.alias_steps)) {
                        state.alias_steps.deinit(allocator);
                        continue;
                    }
                    state.subst = try dispatch.substitution(evidence_node.subst);
                    for (state.alias_steps.items) |step| if (step.module) |view| try modules.append(allocator, view.key.digest());
                },
            }
            try edge_states.append(allocator, state);
        }
    }

    // Read the nominal representations of every module whose types the
    // creations below copy before taking the creation lock.
    try demandDispatchCapabilities(dispatch, modules.items);
    {
        store.beginCreation(io);
        errdefer store.endCreation(io);
        for (edge_states.items) |*state| {
            if (state.alias_steps.items.len != 0) {
                const composed = try composeLiteralAliasChain(allocator, store, names, state.subst, state.alias_steps.items);
                state.owned_subst = composed;
                state.subst = composed;
            }
            state.formals = try allocator.alloc(CheckedTypeId, state.callee.vars.len);
            if (state.callee.module) |view| {
                const projector = try allocator.create(CheckedTypeStoreImportProjector);
                projector.* = CheckedTypeStoreImportProjector.init(allocator, store, names, view);
                state.projector = projector;
                for (state.callee.vars, state.formals) |variable, *out| out.* = try projector.project(variable);
            } else @memcpy(state.formals, state.callee.vars);
            if (state.subst.len != 0) {
                if (state.subst.len != state.formals.len) checkedModuleInvariant("an edge's substitution differs from its callee's scheme", .{});
                state.substitution = CheckedTypeSubstitution.init(allocator, state.formals, state.subst);
            }
        }
        try store.finishCreation(allocator, io);
    }

    const NewRoot = struct { id: ComptimeRootKey, site: LiteralSite, ty: CheckedTypeId, edge: LiteralEdge, callee_requirement: u32, owner_expr: CIR.Expr.Idx };
    var new_roots: std.ArrayListUnmanaged(NewRoot) = .empty;
    defer new_roots.deinit(allocator);
    var root_index = std.AutoHashMapUnmanaged(ObligationKey, ComptimeRootKey).empty;
    defer root_index.deinit(allocator);
    while (true) {
        var changed = false;
        for (edge_states.items) |*state| {
            const callee = state.callee;
            // A use with no recorded instantiation of a scheme with
            // variables instantiates nothing.
            if (callee.vars.len != 0 and state.subst.len == 0) continue;
            var j: u32 = @intCast(state.args.items.len);
            // A self-recursive edge appends to the list it instantiates.
            while (j < literalCalleeRequirements(callee, &states).len) : (j += 1) {
                const obligation = literalCalleeRequirements(callee, &states)[j];
                const ty = created: {
                    store.beginCreation(io);
                    errdefer store.endCreation(io);
                    const projected = if (state.projector) |projector| try projector.project(obligation.ty) else obligation.ty;
                    const created = if (state.substitution) |*substitution| try store.cloneCheckedTypeRootSubstituting(allocator, projected, substitution) else projected;
                    try store.finishCreation(allocator, io);
                    break :created created;
                };
                const key: ObligationKey = .{ .site = obligation.site, .ty = try literalRequirementTypeIdentity(store, names, &orderer, ty) };
                if (!try store.rootContainsIdentityVariables(ty)) {
                    const slot = try root_index.getOrPut(allocator, key);
                    if (!slot.found_existing) {
                        const id = literalArgumentRootId(state.edge.key, j);
                        slot.value_ptr.* = id;
                        try new_roots.append(allocator, .{
                            .id = id,
                            .site = obligation.site,
                            .ty = ty,
                            .edge = state.edge.key,
                            .callee_requirement = j,
                            .owner_expr = state.edge.owner_expr,
                        });
                    }
                    try state.args.append(allocator, .{ .root = slot.value_ptr.* });
                } else if (state.edge.scope != null and !try literalRequirementTypeIsBound(store, &orderer, templates, dispatch, state.edge.scope.?, ty)) {
                    // No use fixes a variable no scheme around the edge
                    // quantifies, so nothing converts this literal.
                    try state.args.append(allocator, .unbound);
                } else {
                    const scope_key = state.edge.scope orelse checkedModuleInvariant("a defaulted field expression instantiates a literal obligation at an open type", .{});
                    const entry = try states.getOrPut(allocator, scope_key);
                    if (!entry.found_existing) entry.value_ptr.* = .{};
                    const slot = try entry.value_ptr.index.getOrPut(allocator, key);
                    if (!slot.found_existing) {
                        slot.value_ptr.* = @intCast(entry.value_ptr.list.items.len);
                        try entry.value_ptr.list.append(allocator, .{ .site = obligation.site, .ty = ty, .edge = state.edge.key, .callee_requirement = j });
                    }
                    try state.args.append(allocator, .{ .forwarded = slot.value_ptr.* });
                }
                changed = true;
            }
        }
        if (!changed) break;
    }

    // The requirement lists.
    var scope_keys: std.ArrayListUnmanaged(LiteralScopeKey) = .empty;
    defer scope_keys.deinit(allocator);
    {
        var it = states.keyIterator();
        while (it.next()) |key| try scope_keys.append(allocator, key.*);
    }
    std.mem.sort(LiteralScopeKey, scope_keys.items, {}, literalScopeKeyLessThan);
    const scope_spans = try allocator.alloc(store_serialize.Span, scope_keys.items.len);
    errdefer allocator.free(scope_spans);
    var requirements: std.ArrayListUnmanaged(LiteralRequirement) = .empty;
    defer requirements.deinit(allocator);
    for (scope_keys.items, scope_spans) |key, *span| {
        const list = states.getPtr(key).?.list.items;
        span.* = .{ .start = @intCast(requirements.items.len), .len = @intCast(list.len) };
        try requirements.appendSlice(allocator, list);
    }

    // The edges' literal arguments.
    var arg_edges: std.ArrayListUnmanaged(u64) = .empty;
    defer arg_edges.deinit(allocator);
    var arg_spans: std.ArrayListUnmanaged(store_serialize.Span) = .empty;
    defer arg_spans.deinit(allocator);
    var args: std.ArrayListUnmanaged(LiteralArgSource) = .empty;
    defer args.deinit(allocator);
    for (edge_states.items) |state| {
        if (state.args.items.len == 0) continue;
        try arg_edges.append(allocator, state.index);
        try arg_spans.append(allocator, .{ .start = @intCast(args.items.len), .len = @intCast(state.args.items.len) });
        for (state.args.items) |arg| try args.append(allocator, switch (arg) {
            .root => |id| .{ .root = id },
            .forwarded => |index| .{ .forwarded = index },
            .unbound => .unbound,
        });
    }

    // The roots, each with its entry wrapper.
    std.mem.sort(NewRoot, new_roots.items, {}, struct {
        fn lessThan(_: void, a: NewRoot, b: NewRoot) bool {
            return @backingInt(a.id) < @backingInt(b.id);
        }
    }.lessThan);
    const roots = try allocator.alloc(LiteralRootRecord, new_roots.items.len);
    errdefer allocator.free(roots);
    var proofs = try ConcreteRootProofs.init(allocator, owner, store.view(), import_views.resolver());
    defer proofs.deinit();
    for (new_roots.items, roots) |new_root, *record| {
        const validate_only = !new_root.site.carriesValue() or try checkedTypeHoldsFunction(allocator, store.view(), owner, import_views, new_root.ty);
        const eligible = try proofs.isContextFree(false, new_root.ty);
        record.* = .{
            .root = .{
                .id = new_root.id,
                .module_idx = source.module_idx,
                .kind = .literal_argument,
                .source = .{ .expr = new_root.owner_expr },
                .pattern = null,
                .expr = new_root.owner_expr,
                .checked_type = new_root.ty,
                .request_eligibility = if (eligible) .eligible else .ineligible,
                .literal_argument = .{
                    .site = new_root.site,
                    .ty = new_root.ty,
                    .edge = new_root.edge,
                    .callee_requirement = new_root.callee_requirement,
                    .validate_only = validate_only,
                },
            },
            .checked_fn_root = undefined, // Created below, under the creation lock.
            .checked_fn_scheme = undefined, // Created below, under the creation lock.
            .plan = null,
            .relation = undefined, // Set below from the created function type.
        };
    }
    {
        store.beginCreation(io);
        errdefer store.endCreation(io);
        for (roots) |*record| {
            record.checked_fn_root = try store.appendSyntheticFunctionRoot(allocator, .pure, &.{}, record.root.checked_type);
            record.checked_fn_scheme = try store.ensureSchemeForRoot(allocator, record.checked_fn_root);
        }
        try store.finishCreation(allocator, io);
    }
    for (roots) |*record| record.relation = literalRootWrapperRelation(record.checked_fn_root, record.root.checked_type);

    const owned_scope_keys = try scope_keys.toOwnedSlice(allocator);
    errdefer allocator.free(owned_scope_keys);
    const owned_requirements = try requirements.toOwnedSlice(allocator);
    errdefer allocator.free(owned_requirements);
    const owned_arg_edges = try arg_edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_arg_edges);
    const owned_arg_spans = try arg_spans.toOwnedSlice(allocator);
    errdefer allocator.free(owned_arg_spans);
    const owned_args = try args.toOwnedSlice(allocator);
    errdefer allocator.free(owned_args);
    const result = try allocator.create(LiteralComponent);
    result.* = .{
        .scope_keys = owned_scope_keys,
        .scope_spans = scope_spans,
        .requirements = owned_requirements,
        .arg_edges = owned_arg_edges,
        .arg_spans = owned_arg_spans,
        .args = owned_args,
        .roots = roots,
    };
    return result;
}

/// The literal argument roots template `template`'s edges read: every
/// evaluation of the template reads their values. Every component holding
/// one of the template's edges is done before the template's slot is
/// claimed (`ModuleAnalyses.templateLiteralArgumentDemand`).
pub fn computeLiteralArgumentDemand(allocator: Allocator, graph: *const LiteralGraph, template: u32) Allocator.Error!*LiteralArgumentDemand {
    var roots: std.ArrayList(ComptimeRootKey) = .empty;
    defer roots.deinit(allocator);
    for (graph.finishedNode(template).reached) |reached| {
        const leader = graph.leaderOf(reached.holder) orelse
            checkedModuleInvariant("a template's literal demand was computed before the component of an edge it reaches", .{});
        const component = graph.component_slots[leader].peek() orelse
            checkedModuleInvariant("a template's literal demand was computed before the component of an edge it reaches", .{});
        const index = graph.finishedNode(reached.holder).edgeIndex(reached.key) orelse
            checkedModuleInvariant("a literal edge's holder does not hold it", .{});
        for (component.edgeArgs(literalEdgeRef(reached.holder, index))) |arg| switch (arg) {
            .root => |id| try roots.append(allocator, id),
            .forwarded, .unbound => {},
        };
    }
    std.mem.sort(ComptimeRootKey, roots.items, {}, comptimeRootIdLessThan);
    var kept: usize = 0;
    for (roots.items, 0..) |id, index| {
        if (index != 0 and roots.items[index - 1] == id) continue;
        roots.items[kept] = id;
        kept += 1;
    }
    roots.shrinkRetainingCapacity(kept);
    const result = try allocator.create(LiteralArgumentDemand);
    errdefer allocator.destroy(result);
    result.* = .{ .roots = try roots.toOwnedSlice(allocator) };
    return result;
}

const LiteralObligationKey = struct { site: LiteralSite, ty: [32]u8 };

/// One scheme's literal requirements while its component is computed, with
/// the index that keeps each requirement once.
const LiteralScopeState = struct {
    list: std.ArrayListUnmanaged(LiteralRequirement) = .empty,
    index: std.AutoHashMapUnmanaged(LiteralObligationKey, u32) = .empty,
};

const LiteralScopeStates = std.AutoHashMapUnmanaged(LiteralScopeKey, LiteralScopeState);

/// An edge's callee scheme: its literal requirements (a live list for a
/// scheme of the component being computed) and its quantified variables, in
/// the scheme's module.
const LiteralCalleeScheme = struct {
    live: ?LiteralScopeKey,
    finished: []const LiteralRequirement,
    vars: []const CheckedTypeId,
    module: ?ImportedModuleView,
};

fn literalCalleeRequirements(callee: LiteralCalleeScheme, states: *const LiteralScopeStates) []const LiteralRequirement {
    const key = callee.live orelse return callee.finished;
    return if (states.getPtr(key)) |state| state.list.items else &.{};
}

/// A callee scheme of this module: live while its component is the one being
/// computed, otherwise the finished requirements of its component.
fn literalLocalCallee(graph: *const LiteralGraph, component: u32, key: LiteralScopeKey, vars: []const CheckedTypeId) LiteralCalleeScheme {
    const node = graph.nodeOfScope(key);
    const callee_component = graph.leaderOf(node) orelse
        checkedModuleInvariant("a literal component was computed before its callee component was assigned", .{});
    if (callee_component == component) return .{ .live = key, .finished = &.{}, .vars = vars, .module = null };
    const done = graph.component_slots[callee_component].peek() orelse
        checkedModuleInvariant("a literal component was computed before its callee component", .{});
    return .{ .live = null, .finished = done.requirementsOf(key), .vars = vars, .module = null };
}

/// Whether a value of the closed type `ty` holds a function: a function
/// type anywhere in it, through aliases, nominal backings, and the builtin
/// encodings that hold callables.
fn checkedTypeHoldsFunction(
    allocator: Allocator,
    own_types: CheckedTypeStoreView,
    own_key: CheckedModuleDigest,
    import_views: CheckedImportViews,
    ty: CheckedTypeId,
) Allocator.Error!bool {
    const Pending = struct { key: [32]u8, types: CheckedTypeStoreView, ty: CheckedTypeId };
    const Seen = struct { key: [32]u8, ty: CheckedTypeId };
    var seen = std.AutoHashMapUnmanaged(Seen, void).empty;
    defer seen.deinit(allocator);
    var pending = std.ArrayListUnmanaged(Pending).empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .key = own_key.bytes, .types = own_types, .ty = ty });
    while (pending.pop()) |item| {
        const seen_entry = try seen.getOrPut(allocator, .{ .key = item.key, .ty = item.ty });
        if (seen_entry.found_existing) continue;
        switch (item.types.payload(item.ty)) {
            .function => return true,
            .pending, .field_kind, .err, .flex, .rigid, .empty_record, .empty_tag_union => {},
            .alias => |alias| {
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = alias.backing });
                for (alias.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = field.ty });
                }
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = record.ext });
            },
            .tuple => |items| for (items) |elem| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = elem }),
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    for (tag.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
                }
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = tag_union.ext });
            },
            .nominal => |nominal| {
                for (nominal.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
                switch (nominal.representation) {
                    .builtin => |builtin_nominal| switch (builtinRuntimeEncoding(builtin_nominal)) {
                        .parse_tag_union_spec => return true,
                        .primitive, .bool_tag_union, .try_nominal, .list, .box, .dict, .set, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => {},
                        .iterator => {
                            const owner = nominal.owner_module.*;
                            const declaring: CheckedTypeStoreView = if (owner.eql(own_key))
                                own_types
                            else
                                (import_views.viewForKey(owner) orelse checkedModuleInvariant("a nominal type's declaring module is not available", .{})).checked_types;
                            const declaration = declaring.builtinNominalDeclaration(builtin_nominal) orelse
                                checkedModuleInvariant("the Builtin module has no declaration for the builtin iterator", .{});
                            try pending.append(allocator, .{ .key = owner.bytes, .types = declaring, .ty = declaration.backing });
                        },
                    },
                    .local_declaration => |declaration_id| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = item.types.nominalDeclarationById(declaration_id).backing }),
                    .imported_declaration => |imported| {
                        const declaring: CheckedTypeStoreView = if (imported.module.eql(own_key))
                            own_types
                        else
                            (import_views.viewForKey(imported.module) orelse checkedModuleInvariant("a nominal type's declaring module is not available", .{})).checked_types;
                        try pending.append(allocator, .{ .key = imported.module.bytes, .types = declaring, .ty = declaring.nominalDeclarationById(imported.declaration).backing });
                    },
                    // A nominal read with a box payload capability is
                    // declared in its module like any other.
                    .local_box_payload_capability => {
                        const declaration = item.types.nominalDeclarationForPayload(nominal) orelse
                            checkedModuleInvariant("a box payload capability names a nominal its module does not declare", .{});
                        try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = declaration.backing });
                    },
                    .opaque_without_backing => {},
                }
            },
        }
    }
    return false;
}

fn checkedDispatchPlanNeedsRelation(
    dispatch: CheckedDispatch,
    plan: static_dispatch.StaticDispatchCallPlan,
) Allocator.Error!bool {
    return switch (plan.resolution) {
        .direct_closed, .direct_parametric => |direct| switch ((try dispatch.evidenceNode(direct.evidence)).target.kind) {
            .procedure => |procedure| switch (procedure.runtime_target) {
                .graph_participating, .intrinsic => true,
                .procedure, .low_level => false,
            },
            .local_proc => false,
            .structural => checkedModuleInvariant("direct checked call targeted a structural derivation", .{}),
        },
        .direct_pending => checkedModuleInvariant("unfinalized direct call reached template classification", .{}),
        .evidence_dependent, .structural, .@"unreachable", .checked_error => true,
    };
}

const ResolvedDispatchCallablePair = struct {
    target: CheckedTypeId,
    plan: CheckedTypeId,
};

/// The store a dispatch specialization relates and creates types in: the
/// types of module `module`, whose nominal types' declarations of other
/// modules `resolver` resolves.
const DispatchSubstitutionTypes = struct {
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    module: ModuleId,
    resolver: ModuleResolver,
};

fn instantiateResolvedDispatchTargetCallableMemoized(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
    memo: *std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId),
) Allocator.Error!CheckedTypeId {
    const key = ResolvedDispatchCallablePair{
        .target = target_callable,
        .plan = plan_callable,
    };
    if (memo.get(key)) |existing| return existing;

    const instantiated = try instantiateResolvedDispatchTargetCallable(
        allocator,
        dispatch_types,
        target_callable,
        plan_callable,
    );
    try memo.put(allocator, key, instantiated);
    return instantiated;
}

fn projectResolvedDispatchTargetCallable(
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    owner: ModuleId,
    imports: CheckedImportViews,
    target: static_dispatch.MethodTarget,
) Allocator.Error!CheckedTypeId {
    const target_key = switch (target.kind) {
        .local_proc => return target.callable_ty,
        .structural => checkedModuleInvariant("structural method registry result was published as a direct callable target", .{}),
        .procedure => |procedure| procedure.template.module,
    };
    if (target_key.eql(owner)) return target.callable_ty;

    const imported = imports.viewForKey(target_key) orelse
        checkedModuleInvariant("resolved dispatch target module was not among the modules dispatch resolution reads", .{});
    var projector = CheckedTypeStoreImportProjector.init(allocator, store, names, imported);
    defer projector.deinit();
    return try projector.project(target.callable_ty);
}

fn instantiateResolvedDispatchTargetCallable(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const store = dispatch_types.store;
    const target_fn = checkedFunctionPayload(store, target_callable, "resolved dispatch target callable");
    const plan_fn = checkedFunctionPayload(store, plan_callable, "resolved dispatch plan callable");
    if (target_fn.args.len != plan_fn.args.len) {
        checkedModuleInvariant("resolved dispatch target arity differed from plan arity", .{});
    }
    const target_args = try allocator.dupe(CheckedTypeId, target_fn.args);
    defer allocator.free(target_args);
    const plan_args = try allocator.dupe(CheckedTypeId, plan_fn.args);
    defer allocator.free(plan_args);
    const plan_ret = plan_fn.ret;

    var target_formals = std.ArrayList(CheckedTypeId).empty;
    defer target_formals.deinit(allocator);
    var target_actuals = std.ArrayList(CheckedTypeId).empty;
    defer target_actuals.deinit(allocator);
    var active = std.AutoHashMap(PlatformRequirementTypePair, void).init(allocator);
    defer active.deinit();
    var target_conflicts = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer target_conflicts.deinit();

    for (target_args, plan_args) |target_arg, plan_arg| {
        try collectResolvedDispatchTargetSubstitutions(
            allocator,
            dispatch_types,
            target_arg,
            plan_arg,
            &target_formals,
            &target_actuals,
            &active,
            &target_conflicts,
        );
    }

    var target_substitution = CheckedTypeSubstitution.init(allocator, target_formals.items, target_actuals.items);
    defer target_substitution.deinit();
    const instantiated_target = try store.cloneCheckedTypeRootSubstituting(allocator, target_callable, &target_substitution);
    const target_instantiated_fn = checkedFunctionPayload(store, instantiated_target, "instantiated resolved dispatch target callable");
    const target_instantiated_args = try allocator.dupe(CheckedTypeId, target_instantiated_fn.args);
    defer allocator.free(target_instantiated_args);
    const target_instantiated_ret = target_instantiated_fn.ret;

    var plan_formals = std.ArrayList(CheckedTypeId).empty;
    defer plan_formals.deinit(allocator);
    var plan_actuals = std.ArrayList(CheckedTypeId).empty;
    defer plan_actuals.deinit(allocator);

    active.clearRetainingCapacity();
    for (target_instantiated_args, plan_args) |target_arg, plan_arg| {
        try collectDispatchPlanIdentitySubstitutions(
            allocator,
            dispatch_types,
            target_arg,
            plan_arg,
            &plan_formals,
            &plan_actuals,
            &active,
        );
    }
    active.clearRetainingCapacity();
    try collectDispatchPlanIdentitySubstitutions(
        allocator,
        dispatch_types,
        target_instantiated_ret,
        plan_ret,
        &plan_formals,
        &plan_actuals,
        &active,
    );

    var plan_substitution = CheckedTypeSubstitution.init(allocator, plan_formals.items, plan_actuals.items);
    defer plan_substitution.deinit();
    return try store.cloneCheckedTypeRootSubstituting(allocator, plan_callable, &plan_substitution);
}

/// The function payload a checked type resolves to through its alias chain.
/// Any other payload, or a cyclic chain, is an invariant violation naming
/// `context`.
pub fn checkedFunctionPayload(
    store: anytype,
    root: CheckedTypeId,
    comptime context: []const u8,
) CheckedFunctionType {
    var current = root;
    var remaining = store.typeCount();
    while (true) {
        const payload = store.payload(current);
        if (payload == .alias) {
            current = payload.alias.backing;
        } else if (payload == .function) {
            return payload.function;
        } else {
            checkedModuleInvariant(context ++ " was not a function", .{});
        }
        if (remaining == 0) {
            checkedModuleInvariant(context ++ " alias chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

fn collectResolvedDispatchTargetSubstitutions(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!void {
    try walkDispatchSubstitutions(.resolved_target, allocator, dispatch_types, target, plan, formals, actuals, active, conflicts);
}

fn collectDispatchPlanIdentitySubstitutions(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
) Allocator.Error!void {
    try walkDispatchSubstitutions(.plan_identity, allocator, dispatch_types, target, plan, formals, actuals, active, {});
}

/// `resolved_target` relates a resolved target's identities to the plan's
/// types, keeping only consistent ones; `plan_identity` relates the plan's
/// identities to the target's structure.
const DispatchSubstitutionMode = enum { resolved_target, plan_identity };

const DispatchSubstitutionItem = union(enum) {
    pair: struct { target: CheckedTypeId, plan: CheckedTypeId },
    /// Every pair below this one's has been related, so it leaves the
    /// active path.
    exit: PlatformRequirementTypePair,
};

/// Relate `target` to `plan` position by position. Pairs are related in
/// source order from an explicit work list; a pair already on the current
/// path is skipped, which is what closes cycles.
fn walkDispatchSubstitutions(
    comptime mode: DispatchSubstitutionMode,
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: switch (mode) {
        .resolved_target => *collections.DenseMap(CheckedTypeId, void),
        .plan_identity => void,
    },
) Allocator.Error!void {
    var pending: std.ArrayListUnmanaged(DispatchSubstitutionItem) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan } });
    while (pending.pop()) |item| switch (item) {
        .exit => |pair| _ = active.remove(pair),
        .pair => |pair| try dispatchSubstitutionStep(mode, allocator, dispatch_types, pair.target, pair.plan, formals, actuals, active, conflicts, &pending),
    };
}

/// Relate one pair: record a substitution, or queue the child pairs that
/// relate its structure.
fn dispatchSubstitutionStep(
    comptime mode: DispatchSubstitutionMode,
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: switch (mode) {
        .resolved_target => *collections.DenseMap(CheckedTypeId, void),
        .plan_identity => void,
    },
    pending: *std.ArrayListUnmanaged(DispatchSubstitutionItem),
) Allocator.Error!void {
    const names = dispatch_types.names;
    const store = dispatch_types.store;
    if (target == plan) return;

    const pair = PlatformRequirementTypePair{
        .expected = @backingInt(target),
        .actual = @backingInt(plan),
    };
    if (active.contains(pair)) return;
    try active.put(pair, {});
    try pending.append(allocator, .{ .exit = pair });
    const start = pending.items.len;
    defer std.mem.reverse(DispatchSubstitutionItem, pending.items[start..]);

    const target_payload = store.payload(target);
    const plan_payload = store.payload(plan);

    switch (mode) {
        .resolved_target => {
            if (checkedTypePayloadIsIdentity(target_payload)) {
                try appendConsistentDispatchTargetSubstitution(formals, actuals, conflicts, allocator, target, plan);
                return;
            }
            if (checkedTypePayloadIsIdentity(plan_payload)) return;
        },
        .plan_identity => {
            if (checkedTypePayloadIsIdentity(plan_payload)) {
                if (!checkedTypePayloadIsIdentity(target_payload)) {
                    try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, store, plan, target);
                }
                return;
            }
            if (checkedTypePayloadIsIdentity(target_payload)) return;
        },
    }

    if (target_payload == .alias) {
        return try pending.append(allocator, .{ .pair = .{ .target = target_payload.alias.backing, .plan = plan } });
    }
    if (plan_payload == .alias) {
        return try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan_payload.alias.backing } });
    }

    switch (target_payload) {
        .function => |target_fn| {
            const plan_fn = switch (plan_payload) {
                .function => |function| function,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .nominal,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_fn.args.len != plan_fn.args.len) return;
            try appendDispatchSubstitutionPairs(allocator, pending, target_fn.args, plan_fn.args);
            if (mode == .plan_identity) {
                try pending.append(allocator, .{ .pair = .{ .target = target_fn.ret, .plan = plan_fn.ret } });
            }
        },
        .nominal => |target_nominal| {
            const plan_nominal = switch (plan_payload) {
                .nominal => |nominal| nominal,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {
                    if (!target_nominal.is_opaque) {
                        const target_backing = (try store.ensureInstantiatedNominalBackingRootForPayload(
                            allocator,
                            dispatch_types.names,
                            dispatch_types.module,
                            dispatch_types.resolver,
                            target_nominal,
                        )) orelse return;
                        try pending.append(allocator, .{ .pair = .{ .target = target_backing, .plan = plan } });
                    }
                    return;
                },
            };
            if (target_nominal.name != plan_nominal.name or
                target_nominal.origin_module != plan_nominal.origin_module or
                !target_nominal.owner_module.*.eql(plan_nominal.owner_module.*) or
                target_nominal.source_decl != plan_nominal.source_decl or
                target_nominal.builtin != plan_nominal.builtin or
                target_nominal.args.len != plan_nominal.args.len)
            {
                return;
            }
            // Matching nominal applications are completely related by their
            // arguments. Their shared declaration backing is representation
            // data and is opened only for nominal-versus-structural relations.
            try appendDispatchSubstitutionPairs(allocator, pending, target_nominal.args, plan_nominal.args);
        },
        .tuple => |target_items| {
            const plan_items = switch (plan_payload) {
                .tuple => |items| items,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_items.len != plan_items.len) return;
            try appendDispatchSubstitutionPairs(allocator, pending, target_items, plan_items);
        },
        .empty_record,
        .record,
        => {
            const target_parts = recordParts(target_payload) orelse return;
            const plan_parts = recordParts(plan_payload) orelse return;
            const target_row = try flattenPlatformRequirementRecordRow(allocator, store, target_parts.fields, target_parts.ext);
            defer target_row.deinit(allocator);
            const plan_row = try flattenPlatformRequirementRecordRow(allocator, store, plan_parts.fields, plan_parts.ext);
            defer plan_row.deinit(allocator);

            for (target_row.fields) |target_field| {
                const plan_field = findRecordField(names, plan_row.fields, target_field.name) orelse continue;
                try pending.append(allocator, .{ .pair = .{ .target = target_field.ty, .plan = plan_field.ty } });
            }
            if (target_row.tail) |target_tail| {
                if (plan_row.tail) |plan_tail| {
                    try pending.append(allocator, .{ .pair = .{ .target = target_tail, .plan = plan_tail } });
                }
            }
        },
        .empty_tag_union,
        .tag_union,
        => {
            const target_union = tagUnionParts(target_payload) orelse return;
            const plan_union = tagUnionParts(plan_payload) orelse return;
            const target_row = try flattenPlatformRequirementTagRow(allocator, store, target_union.tags, target_union.ext);
            defer target_row.deinit(allocator);
            const plan_row = try flattenPlatformRequirementTagRow(allocator, store, plan_union.tags, plan_union.ext);
            defer plan_row.deinit(allocator);

            for (target_row.tags) |target_tag| {
                const plan_tag = findTag(names, plan_row.tags, target_tag.name) orelse continue;
                const target_args = target_tag.args;
                const plan_args = plan_tag.args;
                if (target_args.len != plan_args.len) continue;
                try appendDispatchSubstitutionPairs(allocator, pending, target_args, plan_args);
            }
            if (target_row.tail) |target_tail| {
                if (plan_row.tail) |plan_tail| {
                    try pending.append(allocator, .{ .pair = .{ .target = target_tail, .plan = plan_tail } });
                }
            }
        },
        .pending, .field_kind, .err, .flex, .rigid, .alias => {},
    }
}

fn appendDispatchSubstitutionPairs(
    allocator: Allocator,
    pending: *std.ArrayListUnmanaged(DispatchSubstitutionItem),
    targets: []const CheckedTypeId,
    plans: []const CheckedTypeId,
) Allocator.Error!void {
    for (targets, plans) |target, plan| {
        try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan } });
    }
}

fn appendConsistentDispatchTargetSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
    allocator: Allocator,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (conflicts.contains(formal)) return;

    for (formals.items, actuals.items, 0..) |existing_formal, existing_actual, i| {
        if (existing_formal != formal) continue;
        if (existing_actual == actual) return;

        try conflicts.put(formal, {});
        _ = formals.orderedRemove(i);
        _ = actuals.orderedRemove(i);
        return;
    }

    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn appendUniqueCheckedTypeSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    allocator: Allocator,
    store: *const CheckedTypeStore,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    for (formals.items, actuals.items) |existing_formal, existing_actual| {
        if (existing_formal != formal) continue;
        // A store can hold two roots for one type, so a partially rebuilt
        // instantiation can reference one root in one position and another
        // in another. Two ids for one type are one actual, not a conflict;
        // the first is kept. Debug builds check that the two are one type
        // by structure, which reads no key slot: the caller may hold the
        // store's creation lock.
        if (builtin.mode == .debug and existing_actual != actual) {
            var scratch = CheckedTypeStoreView.EqualityScratch.init(allocator);
            defer scratch.deinit();
            if (!try checkedTypeRootSliceEql(.alpha, .named, .stored, store.view(), &.{existing_actual}, &.{actual}, &scratch)) {
                checkedModuleInvariant("checked type substitution mapped one formal to multiple actuals", .{});
            }
        }
        return;
    }
    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn validatePlatformBindingRelation(
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    value_use_kind: PlatformRequiredValueUseKind,
    relation: PlatformRequirementRelation,
    binding_index: usize,
) void {
    if (relation.declaration != declaration or relation.requires_idx != requires_idx) {
        base.invariant(
            "checked module invariant violated: platform/app binding {d} points at a checked relation for a different requirement",
            .{binding_index},
        );
    }
    if (!std.meta.eql(relation.app_value.module.bytes, app_value.module.bytes) or
        relation.app_value.pattern != app_value.pattern)
    {
        base.invariant(
            "checked module invariant violated: platform/app binding {d} points at a checked relation for a different app value",
            .{binding_index},
        );
    }
    switch (value_use_kind) {
        .const_value => if (relation.value_kind != .const_value) {
            base.invariant(
                "checked module invariant violated: platform/app binding {d} has const value use but procedure checked relation",
                .{binding_index},
            );
        },
        .procedure_value => if (relation.value_kind != .procedure_value) {
            base.invariant(
                "checked module invariant violated: platform/app binding {d} has procedure value use but const checked relation",
                .{binding_index},
            );
        },
    }
}

fn platformRequiredValueUseWithRelation(
    value_use: PlatformRequiredValueUse,
    relation: PlatformRequirementRelation,
) PlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{ .const_value = .{
            .const_use = .{
                .const_ref = const_use.const_use.const_ref,
                .requested_source_ty_payload = relation.requested_source_ty_payload,
            },
            .relation_template_closure = const_use.relation_template_closure,
        } },
        .procedure_value => |proc_use| .{ .procedure_value = .{
            .procedure = .{
                .binding = proc_use.procedure.binding,
                .source_fn_ty_payload = relation.requested_source_ty_payload,
                .intrinsic = proc_use.procedure.intrinsic,
                .iterator_procedure = proc_use.procedure.iterator_procedure,
                .runtime_result_provenance = proc_use.procedure.runtime_result_provenance,
            },
            .root_evidence = .{
                .checked_module = relation.app_value.module,
                .span = relation.root_evidence,
            },
            .relation_template_closure = proc_use.relation_template_closure,
        } },
    };
}

/// Copy borrowed closure slices directly into the final the opening's pool.
fn copyPlatformRequiredValueUse(
    pool: *ClosurePool,
    allocator: Allocator,
    value_use: PlatformRequiredValueUse,
) Allocator.Error!StoredPlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{
            .const_value = .{
                .const_use = const_use.const_use,
                .relation_template_closure = try pool.appendBorrowed(allocator, const_use.relation_template_closure),
            },
        },
        .procedure_value => |proc_use| .{
            .procedure_value = .{
                .procedure = proc_use.procedure,
                .root_evidence = proc_use.root_evidence,
                .relation_template_closure = try pool.appendBorrowed(allocator, proc_use.relation_template_closure),
            },
        },
    };
}

/// Public `platformRequirementContextKey` function.
pub fn platformRequirementContextKey(checked: *const CheckedModule) Allocator.Error!PlatformRequirementContextKey {
    return PlatformRequirementContextKey.compute(
        checked.module_identity,
        try checked.platformRequiredDeclarations().identityHash(checked.typesView()),
    );
}

fn buildPlatformAppRelationFromDeclarations(
    allocator: Allocator,
    module_idx: u32,
    requirement_context: PlatformRequirementContextKey,
    declarations: PlatformRequiredDeclarationTable,
    app_module: *const CheckedModule,
    resolver: ModuleResolver,
) Allocator.Error!PlatformAppRelation {
    // The relation borrows the app's export closures, which live as long
    // as the app.
    const app_closures = try importedView(app_module).exportClosures(resolver);
    // The one read of an app's analyses from its platform: the root
    // evidence of each requirement the app solves.
    const app_root_evidence = try (try importedView(app_module).dispatch()).analyses().platformRequirementRootEvidence(try importedView(app_module).dispatch());
    var relations = std.ArrayList(PlatformRequirementRelationInput).empty;
    errdefer relations.deinit(allocator);
    var bindings = std.ArrayList(PlatformRequiredBindingInput).empty;
    errdefer bindings.deinit(allocator);
    var checked_error_requires = std.ArrayList(u32).empty;
    errdefer checked_error_requires.deinit(allocator);

    const relation_key = PlatformAppRelationKey.compute(app_module.key.digest(), requirement_context);

    for (0..declarations.count()) |requires_idx| {
        const declaration = declarations.get(requires_idx);
        // The checker records successful solutions as exact app value/type
        // facts. A missing row is recorded explicitly as a checked-error
        // requirement so the pairing stays total without inventing a binding.
        const solution = (try app_module.platformRequirementSolutions()).lookupByRequiredIndex(declaration.requires_idx) orelse {
            try checked_error_requires.append(allocator, declaration.requires_idx);
            continue;
        };

        const app_value_ref = TopLevelValueRef{
            .module = app_module.key.digest(),
            .pattern = solution.pattern,
        };

        const value_kind = solution.value_kind;

        const top_level = (try app_module.checkedTables()).top_level_values.lookupByDef(solution.def) orelse {
            checkedModuleInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        if (builtin.mode == .debug) {
            std.debug.assert(top_level.pattern == solution.pattern);
        }

        const relation_id: PlatformRequirementRelationId = @fromBackingInt(@intCast(@as(u32, @intCast(relations.items.len))));
        try relations.append(allocator, .{
            .id = relation_id,
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .value_kind = value_kind,
            .solved_root_app = solution.solved_root,
            .root_evidence = app_root_evidence.spans[solution.source_solution],
            .identity_start = solution.identity_start,
            .identity_len = solution.identity_len,
        });

        try bindings.append(allocator, .{
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .checked_relation = relation_id,
            .value_use = if (value_kind == .procedure_value) blk: {
                const procedure_binding = switch (top_level.value) {
                    .procedure_binding => |binding| binding,
                    .const_ref => checkedModuleInvariant("platform requirement solution needs a procedure but the app value is a const", .{}),
                };
                _ = (try app_module.checkedTables()).top_level_procedure_bindings.get(procedure_binding);
                const exported_index = exportedProcedureBindingForAppValue(
                    (try app_module.exportRows()).procedure_bindings,
                    top_level,
                );
                const exported_binding = (try app_module.exportRows()).procedure_bindings[exported_index];
                const template_closure = try exportedProcedureBindingClosureForAppValue(app_module, app_closures, exported_index);

                break :blk .{ .procedure_value = .{
                    .procedure = platformRequiredProcedureUse(
                        app_module.key,
                        app_value_ref,
                        procedure_binding,
                        exported_binding,
                    ),
                    .root_evidence = .{
                        .checked_module = app_module.key.digest(),
                        .span = app_root_evidence.spans[solution.source_solution],
                    },
                    .relation_template_closure = template_closure,
                } };
            } else blk: {
                const const_ref = switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedModuleInvariant("platform requirement solution needs a const but the app value is a procedure", .{}),
                };
                const template_closure = try exportedConstTemplateClosureForAppValue(app_module, app_closures, app_value_ref, const_ref);

                break :blk .{ .const_value = .{
                    .const_use = .{
                        .const_ref = const_ref,
                        .requested_source_ty_payload = null,
                    },
                    .relation_template_closure = template_closure,
                } };
            },
        });
    }

    const owned_relations = try relations.toOwnedSlice(allocator);
    errdefer allocator.free(owned_relations);
    const owned_bindings = try bindings.toOwnedSlice(allocator);
    errdefer allocator.free(owned_bindings);
    const owned_checked_errors = try checked_error_requires.toOwnedSlice(allocator);
    errdefer allocator.free(owned_checked_errors);

    return .{
        .key = relation_key,
        .requirement_context = requirement_context,
        .platform_module_idx = module_idx,
        .app_module = app_module.key.digest(),
        .relations = owned_relations,
        .bindings = owned_bindings,
        .checked_error_requires = owned_checked_errors,
        .identity_solutions_app = (try app_module.platformRequirementSolutions()).identity_solutions,
    };
}

/// Copy an evaluation column into storage `allocator`, an arena, owns: a
/// paired module's or a reopened module's own evaluation columns. The source
/// stays with the module it belongs to.
fn copyPairingColumns(comptime T: type, source: T, allocator: Allocator) Allocator.Error!T {
    if (comptime @typeInfo(T) == .pointer) {
        const pointer = @typeInfo(T).pointer;
        comptime std.debug.assert(pointer.size == .slice);
        store_serialize.assertRelocatablePod(pointer.child);
        const result = try allocator.alignedAlloc(pointer.child, .fromByteUnits(pointer.attrs.@"align" orelse @alignOf(pointer.child)), source.len);
        @memcpy(result, source);
        return result;
    } else if (comptime T == canonical.CanonicalNameStore) {
        return source.clone(allocator);
    } else if (comptime @typeInfo(T) == .@"struct") {
        if (comptime @hasField(T, "items") and @hasField(T, "capacity")) {
            var result = source;
            result.items = try copyPairingColumns(@TypeOf(source.items), source.items, allocator);
            result.capacity = result.items.len;
            return result;
        } else if (comptime @hasDecl(T, "Serialized")) {
            var result: T = source;
            inline for (@typeInfo(T).@"struct".field_names, @typeInfo(T).@"struct".field_types, @typeInfo(T).@"struct".field_attrs) |field_name, field_type, field_attrs| {
                const transient = comptime blk: {
                    if (@hasDecl(T, "serde_transient_fields")) for (T.serde_transient_fields) |name| {
                        if (pairingFieldNameEql(name, field_name)) break :blk true;
                    };
                    break :blk false;
                };
                if (comptime transient) {
                    @field(result, field_name) = if (field_attrs.defaultValue(field_type)) |value| value else field_type.init(allocator);
                } else if (comptime field_type == Allocator) {
                    @field(result, field_name) = allocator;
                } else if (comptime pairingFieldNameEql(field_name, "serialized")) {
                    @field(result, field_name) = false;
                } else if (comptime pairingFieldNameEql(field_name, "supports_inserts")) {
                    @field(result, field_name) = true;
                } else {
                    @field(result, field_name) = try copyPairingColumns(field_type, @field(source, field_name), allocator);
                }
            }
            return result;
        } else {
            store_serialize.assertRelocatablePod(T);
            return source;
        }
    } else {
        store_serialize.assertRelocatablePod(T);
        return source;
    }
}

fn pairingFieldNameEql(comptime a: []const u8, comptime b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| if (x != y) return false;
    return true;
}

/// A platform/app pairing over two sealed checked modules (design.md
/// "Platform/App Composition"): the platform's types read through the
/// pairing's overlay, and the facts that depend on those types computed per
/// pairing on first demand. The platform's bodies, templates, names, roots
/// and tables are read in place; the paired module a pairing heads owns
/// only its root requests and its evaluation output.
pub const PlatformPairing = struct {
    /// Thread-safe; owns the overlay and every slot result.
    allocator: Allocator,
    io: std.Io,
    platform: *const CheckedModule,
    app: *const CheckedModule,
    /// The modules a direct call target of the platform resolves against.
    available: []const ImportedModuleView,
    /// The app, as the relation's one relation module.
    app_views: [1]ImportedModuleView,
    relation: PlatformAppRelation,
    overlay: PairingOverlay,
    relation_tables: collections.OnceSlot(*PairingRelationTables, .pairing_relation_tables) = .empty,
    value_refs: collections.OnceSlot(*ResolvedValueRefTable, .pairing_value_refs) = .empty,
    provided_exports: collections.OnceSlot(*ProvidedExportTable, .pairing_provided_exports) = .empty,

    /// The relation's requirement relations and required bindings.
    pub const PairingRelationTables = struct {
        relations: PlatformRequirementRelationTable,
        bindings: PlatformRequiredBindingTable,
    };

    fn destroy(self: *PlatformPairing) void {
        const allocator = self.allocator;
        if (self.provided_exports.peek()) |table| {
            allocator.free(table.exports);
            allocator.destroy(table);
        }
        if (self.value_refs.peek()) |table| {
            allocator.free(table.records);
            allocator.free(table.retired_exprs);
            allocator.free(table.call_direct_targets);
            allocator.destroy(table);
        }
        if (self.relation_tables.peek()) |tables| {
            tables.relations.deinit(allocator);
            tables.bindings.deinit(allocator);
            allocator.destroy(tables);
        }
        self.overlay.deinit();
        allocator.destroy(self);
    }

    /// The platform's requirement relations and required bindings under
    /// this pairing. Projecting each requirement's solved app type into the
    /// platform's store creates types, under the store's creation lock.
    pub fn relationTables(self: *PlatformPairing) Allocator.Error!*const PairingRelationTables {
        return self.relation_tables.getOrCompute(self.io, Allocator.Error, self, computeRelationTables);
    }

    fn computeRelationTables(self: *PlatformPairing) Allocator.Error!*PairingRelationTables {
        const allocator = self.allocator;
        const platform = self.platform;
        const tables = try allocator.create(PairingRelationTables);
        errdefer allocator.destroy(tables);
        var relations = try PlatformRequirementRelationTable.fromRelation(
            allocator,
            self.io,
            platform.module_identity,
            @constCast(&platform.canonical_names),
            @constCast(&platform.checked_types),
            platform.platformRequiredDeclarations(),
            &self.app_views,
            self.relation,
        );
        errdefer relations.deinit(allocator);
        tables.* = .{
            .relations = relations,
            .bindings = try PlatformRequiredBindingTable.fromRelation(
                allocator,
                platform.module_identity,
                platform.typesView(),
                platform.platformRequiredDeclarations(),
                &relations,
                self.relation,
            ),
        };
        return tables;
    }

    /// The platform's resolved value references under this pairing: each
    /// requirement lookup classified by its binding, the lookups of
    /// requirements the app rejected retired, and each call of a
    /// requirement whose binding is a procedure given its direct target.
    pub fn valueRefs(self: *PlatformPairing) Allocator.Error!*const ResolvedValueRefTable {
        _ = try self.relationTables();
        return self.value_refs.getOrCompute(self.io, Allocator.Error, self, computeValueRefs);
    }

    fn computeValueRefs(self: *PlatformPairing) Allocator.Error!*ResolvedValueRefTable {
        const allocator = self.allocator;
        const platform = self.platform;
        const bindings = &self.relation_tables.peek().?.bindings;
        const table = try allocator.create(ResolvedValueRefTable);
        errdefer allocator.destroy(table);
        table.* = (try platform.valueRefs()).*;
        const records = try allocator.dupe(ResolvedValueRefRecord, (try platform.valueRefs()).records);
        errdefer allocator.free(records);
        for (records) |*record| {
            if (record.ref == .platform_required_declaration) {
                const required = platform.platformRequiredDeclarations().lookupByDeclarationId(record.ref.platform_required_declaration).?;
                record.ref = categorizeRequiredValueRef(required.requires_idx, platform.platformRequiredDeclarations(), bindings);
            }
        }
        table.records = records;
        const env = platform.moduleEnvConst();
        const retired = try allocator.dupe(u64, (try platform.valueRefs()).retired_exprs);
        errdefer allocator.free(retired);
        for (records) |record| {
            if (record.ref != .platform_required_checked_error) continue;
            if (env.store.getExpr(record.expr) != .e_lookup_required) continue;
            ResolvedValueRefTable.setRetired(retired, record.expr);
        }
        table.retired_exprs = retired;
        var direct_targets = std.ArrayList(CallDirectTarget).empty;
        defer direct_targets.deinit(allocator);
        try direct_targets.appendSlice(allocator, (try platform.valueRefs()).call_direct_targets);
        const platform_analyses = platform.body_analyses orelse checkedModuleInvariant("a platform was paired before its body analyses were attached", .{});
        for (platform_analyses.index.node_kinds, 0..) |kind, raw| {
            if (kind != .expr) continue;
            const call_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw));
            const data = env.store.getExpr(call_expr);
            if (data != .e_call) continue;
            const ref_id = (try platform.valueRefs()).lookupIdByExpr(data.e_call.func) orelse continue;
            if ((try platform.valueRefs()).records[@backingInt(ref_id)].ref != .platform_required_declaration) continue;
            // The binding supplies the procedure kind that an unpaired
            // requirement cannot classify; the call gets the same direct-call
            // decision a resolved module's call gets.
            const target = try directProcedureTargetForCall(
                table,
                data.e_call.func,
                platform.key,
                &(try platform.checkedTables()).top_level_procedure_bindings,
                &(try platform.checkedTables()).callable_eval_templates,
                &.{},
                self.available,
                &self.app_views,
            );
            const index = std.sort.lowerBound(CallDirectTarget, direct_targets.items, call_expr, struct {
                fn order(key: CIR.Expr.Idx, entry: CallDirectTarget) std.math.Order {
                    return std.math.order(@backingInt(key), @backingInt(entry.call));
                }
            }.order);
            const present = index < direct_targets.items.len and direct_targets.items[index].call == call_expr;
            if (target) |resolved| {
                if (present) {
                    direct_targets.items[index].target = resolved;
                } else {
                    try direct_targets.insert(allocator, index, .{ .call = call_expr, .target = resolved });
                }
            } else if (present) {
                _ = direct_targets.orderedRemove(index);
            }
        }
        table.call_direct_targets = try direct_targets.toOwnedSlice(allocator);
        return table;
    }

    /// The platform's provided exports, each read at its type under this
    /// pairing.
    pub fn providedExports(self: *PlatformPairing) Allocator.Error!*const ProvidedExportTable {
        return self.provided_exports.getOrCompute(self.io, Allocator.Error, self, computeProvidedExports);
    }

    fn computeProvidedExports(self: *PlatformPairing) Allocator.Error!*ProvidedExportTable {
        const allocator = self.allocator;
        const table = try allocator.create(ProvidedExportTable);
        errdefer allocator.destroy(table);
        const exports = try allocator.dupe(ProvidedExport, (try self.platform.providedExports()).exports);
        errdefer allocator.free(exports);
        for (exports) |*provided| switch (provided.*) {
            inline .procedure, .data => |*value| value.checked_type = try self.overlay.image(value.checked_type),
            .checked_error => {},
        };
        table.* = .{ .exports = exports };
        return table;
    }

    /// Comptime fingerprint of `Serialized`'s layout. The compiler's cache
    /// versioning folds it into the platform-pairing cache entry's admission hash.
    // Bump the version for semantics not visible in the serialized layout fingerprint.
    pub const SERIALIZED_VERSION_HASH: [32]u8 = store_serialize.rootLayoutVersionHash(Serialized, 8);

    /// A pairing's cache entry: its evaluation output alone, keyed by the
    /// platform's and the app's checked entries. A hit installs it over a
    /// pairing created from the two modules, whose every other fact is
    /// computed on demand as without a hit.
    pub const Serialized = extern struct {
        relation: [32]u8,
        evaluation: EvaluationOutput.Serialized,

        pub const root_contract: collections.serde_validation.RootContract = .{
            .Owner = CheckedModule,
            .owner_only_fields = &.{
                // The platform's own checked module, read in place.
                "key",
                "source_hash",
                "canonical_names",
                "module_identity",
                "direct_import_module_keys",
                "module_env",
                "checked_types",
                "inference",
                // Recorded as `relation`; the rest is the platform's.
                "checking_context_identity",
                // Runtime ownership, not checked data.
                "serialized_backing",
                "serialized_backing_borrowed",
                "pairing_arena",
                "pairing",
                "reopened_arena",
                "body_analyses",
                "module_analyses",
            },
            .serialized_only_fields = &.{
                "relation", // `checking_context_identity.platform_app_relation`.
            },
        };

        pub fn serialize(self: *Serialized, checked: *const CheckedModule, gpa: Allocator, writer: *CompactWriter) Allocator.Error!void {
            std.debug.assert(checked.pairing != null and checked.evaluation.state == .finalized);
            self.relation = checked.checking_context_identity.platform_app_relation.?.bytes;
            try self.evaluation.serialize(&checked.evaluation, gpa, writer);
        }

        pub fn validate(self: *const Serialized, len: usize) error{CorruptSerializedData}!void {
            if (len < @sizeOf(Serialized)) return error.CorruptSerializedData;
            try store_serialize.validateSerialized(Serialized, self, len);
            try self.evaluation.validateContents(@intFromPtr(self));
        }

        /// Whether the entry was stored for the relation `paired` has.
        pub fn matches(self: *const Serialized, paired: *const CheckedModule) bool {
            const relation = paired.checking_context_identity.platform_app_relation orelse return false;
            return std.meta.eql(self.relation, relation.bytes);
        }

        /// Install the entry's evaluation output over `paired`, a pairing
        /// awaiting evaluation. The pairing's arena owns the relocated
        /// buffer the output aliases.
        pub fn install(self: *const Serialized, paired: *CheckedModule) void {
            std.debug.assert(paired.pairing != null and paired.evaluation.state == .prepared);
            paired.evaluation = self.evaluation.deserialize(@intFromPtr(self), paired.pairing_arena.?.allocator());
            paired.evaluation.state = .finalized;
        }
    };
};

/// Pair a checked platform with a checked app. The paired module reads the
/// platform's checked module in place through the pairing; it owns the
/// evaluation output its app-dependent roots fill.
pub fn pairCheckedPlatform(
    allocator: Allocator,
    platform: *const CheckedModule,
    app: *const CheckedModule,
    available_modules: []const ImportedModuleView,
) Allocator.Error!CheckedModule {
    std.debug.assert(platform.evaluation.state == .finalized);
    std.debug.assert(platform.checking_context_identity.platform_app_relation == null);
    // The pairing reads the nominal representations of the platform's, the
    // app's and every available module's types, so their capabilities exist
    // before it creates any type.
    _ = try platform.typesView().interfaceCapabilities();
    _ = try app.typesView().interfaceCapabilities();
    for (available_modules) |available| _ = try available.checked_types.interfaceCapabilities();
    const platform_analyses = platform.body_analyses orelse checkedModuleInvariant("a platform was paired before its body analyses were attached", .{});
    const thread_safe = platform_analyses.allocator;
    const io = platform_analyses.io;

    const arena = try allocator.create(base.SingleThreadArena);
    arena.* = base.SingleThreadArena.init(allocator);
    errdefer {
        arena.deinit();
        allocator.destroy(arena);
    }
    const session = arena.allocator();
    const app_views = [_]ImportedModuleView{importedView(app)};
    const pairing_views = CheckedImportViews{ .current_owner = platform.key.digest(), .direct = &.{}, .available = available_modules, .relations = &app_views };
    const relation = try buildPlatformAppRelationFromDeclarations(session, platform.module_identity.module_idx, try platform.platformRequirementContextKey(), platform.platformRequiredDeclarations(), app, pairing_views.resolver());

    const pairing = try thread_safe.create(PlatformPairing);
    var pairing_initialized = false;
    errdefer if (!pairing_initialized) thread_safe.destroy(pairing);
    pairing.* = .{
        .allocator = thread_safe,
        .io = io,
        .platform = platform,
        .app = app,
        .available = try session.dupe(ImportedModuleView, available_modules),
        .app_views = app_views,
        .relation = relation,
        .overlay = undefined,
    };
    try pairing.overlay.init(thread_safe, io, platform, app, relation);
    pairing_initialized = true;
    errdefer pairing.destroy();

    var result = platform.*;
    result.serialized_backing = null;
    result.serialized_backing_borrowed = false;
    result.pairing_arena = arena;
    result.pairing = pairing;
    // Every read of the pairing's types and names goes to the platform's
    // stores (`typeStore`, `nameStore`).
    result.checked_types = .{};
    result.canonical_names = canonical.CanonicalNameStore.init(session);
    result.checking_context_identity.platform_app_relation = relation.key;
    // The pairing's bodies read the classified references and its views
    // the required bindings, so they are demanded here.
    _ = try pairing.relationTables();
    _ = try pairing.valueRefs();
    result.body_analyses = try BodyAnalyses.create(thread_safe, io, platform.moduleEnvConst(), platform.moduleEnvConst().promoted_local_procedures.items.items);
    errdefer result.body_analyses.?.destroy();
    result.module_analyses = try ModuleAnalyses.create(thread_safe, io, platform);
    errdefer result.module_analyses.?.destroy();
    result.module_analyses.?.pairing = pairing;
    // The pairing evaluates the compile-time roots its platform withheld
    // until the app binds its requirements, into an evaluation output of its
    // own that starts as its platform's. A pairing with nothing to evaluate
    // reads its platform's output. Either records its own debug
    // observations.
    const pairing_evaluates = for ((try platform.rootRequests()).requests) |request| {
        if (request.abi == .compile_time and request.requires_pairing) break true;
    } else false;
    if (pairing_evaluates) {
        result.evaluation = try copyPairingColumns(EvaluationOutput, platform.evaluation, session);
    }
    result.evaluation.debug = .{};
    result.evaluation.state = .prepared;
    result.openToAnalyses();
    return result;
}

const FlattenedPlatformRequirementRecordRow = struct {
    fields: []const CheckedRecordField,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.fields.len > 0) allocator.free(self.fields);
    }
};

fn flattenPlatformRequirementRecordRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: CheckedRecordFields,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementRecordRow {
    var fields = std.ArrayList(CheckedRecordField).empty;
    errdefer fields.deinit(allocator);
    try head.appendTo(allocator, &fields);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_record => {
                tail = null;
                break;
            },
            .record => |record| {
                try record.fields.appendTo(allocator, &fields);
                tail = record.ext;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .field_kind,
            .err,
            .flex,
            .rigid,
            .tuple,
            .nominal,
            .function,
            .tag_union,
            .empty_tag_union,
            => break,
        }
    }
    return .{ .fields = try fields.toOwnedSlice(allocator), .tail = tail };
}

const FlattenedPlatformRequirementTagRow = struct {
    tags: []const CheckedTag,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.tags.len > 0) allocator.free(self.tags);
    }
};

fn flattenPlatformRequirementTagRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: CheckedTags,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementTagRow {
    var tags = std.ArrayList(CheckedTag).empty;
    errdefer tags.deinit(allocator);
    try head.appendTo(allocator, &tags);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_tag_union => {
                tail = null;
                break;
            },
            .tag_union => |tag_union| {
                try tag_union.tags.appendTo(allocator, &tags);
                tail = tag_union.ext;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .field_kind,
            .err,
            .flex,
            .rigid,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => break,
        }
    }
    return .{ .tags = try tags.toOwnedSlice(allocator), .tail = tail };
}

fn platformRequirementPayload(store: *const CheckedTypeStore, root: CheckedTypeId) CheckedTypePayload {
    return store.payload(root);
}

const RelationTagUnionParts = struct {
    tags: CheckedTags,
    ext: ?CheckedTypeId,
};

fn tagUnionParts(payload: CheckedTypePayload) ?RelationTagUnionParts {
    return switch (payload) {
        .tag_union => |tag_union| .{ .tags = tag_union.tags, .ext = tag_union.ext },
        .empty_tag_union => .{ .tags = .empty, .ext = null },
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        => null,
    };
}

/// A visited pair of checked type roots, keyed by their raw ids. Used as the
/// cycle guard while walking two structurally-parallel checked types in
/// lock-step (resolved dispatch target substitution collection).
const PlatformRequirementTypePair = struct {
    expected: u32,
    actual: u32,
};

fn checkedTypePayloadIsIdentity(payload: CheckedTypePayload) bool {
    return payload == .flex or payload == .rigid;
}

const RelationRecordParts = struct {
    fields: CheckedRecordFields,
    ext: ?CheckedTypeId,
};

fn recordParts(payload: CheckedTypePayload) ?RelationRecordParts {
    return switch (payload) {
        .record => |record| .{ .fields = record.fields, .ext = record.ext },
        .empty_record => .{ .fields = .empty, .ext = null },
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .tuple,
        .nominal,
        .function,
        .tag_union,
        .empty_tag_union,
        => null,
    };
}

fn findRecordField(
    names: *const canonical.CanonicalNameStore,
    fields: []const CheckedRecordField,
    name: canonical.RecordFieldLabelId,
) ?CheckedRecordField {
    for (fields) |field| {
        if (names.recordFieldLabelTextEql(field.name, name)) return field;
    }
    return null;
}

fn findTag(
    names: *const canonical.CanonicalNameStore,
    tags: []const CheckedTag,
    name: canonical.TagLabelId,
) ?CheckedTag {
    for (tags) |tag| {
        if (names.tagLabelTextEql(tag.name, name)) return tag;
    }
    return null;
}

fn exportedProcedureBindingClosureForAppValue(
    app_module: *const CheckedModule,
    closures: *const ExportClosures,
    binding_index: usize,
) Allocator.Error!ImportedTemplateClosureView {
    switch ((try app_module.exportRows()).procedure_bindings[binding_index].body) {
        .direct_template => |direct| {
            if (checkedTemplateFromCallableTemplateForClosure(direct.template)) |template_ref| {
                return try exportedProcedureTemplateClosureForRef(app_module, closures, template_ref);
            }
        },
        .callable_eval_template, .checked_error => {},
    }
    return closures.procedureBinding(binding_index);
}

fn exportedProcedureBindingForAppValue(
    bindings: []const ImportedProcedureBindingView,
    app_value: TopLevelValueEntry,
) usize {
    for (bindings, 0..) |binding, index| {
        if (binding.binding.def == app_value.def and binding.binding.pattern == app_value.pattern) return index;
    }
    checkedModuleInvariant("platform-required app procedure was not exported by the app module", .{});
}

fn platformRequiredProcedureUse(
    app_module: CheckedModuleKey,
    app_value: TopLevelValueRef,
    procedure_binding: TopLevelProcedureBindingRef,
    exported_binding: ImportedProcedureBindingView,
) ProcedureUseTemplate {
    if (!exported_binding.binding.module.eql(app_module.digest()) or
        exported_binding.binding.pattern != app_value.pattern)
    {
        checkedModuleInvariant("platform-required app procedure use disagreed with its exported binding", .{});
    }
    return .{
        .binding = .{ .platform_required = .{
            .module = app_module.digest(),
            .app_value = app_value,
            .procedure_binding = procedure_binding,
        } },
        .source_fn_ty_payload = null,
        .intrinsic = null,
        .iterator_procedure = exported_binding.iterator_procedure,
        .runtime_result_provenance = exported_binding.runtime_result_provenance,
    };
}

fn exportedProcedureTemplateClosureForRef(
    app_module: *const CheckedModule,
    closures: *const ExportClosures,
    template_ref: canonical.ProcedureTemplateRef,
) Allocator.Error!ImportedTemplateClosureView {
    for ((try app_module.exportRows()).procedure_templates, 0..) |template, index| {
        if (canonical.procedureTemplateRefEql(template.template, template_ref)) return closures.procedureTemplate(index);
    }
    checkedModuleInvariant("platform-required app procedure template was not exported by the app module", .{});
}

fn exportedConstTemplateClosureForAppValue(
    app_module: *const CheckedModule,
    closures: *const ExportClosures,
    app_value: TopLevelValueRef,
    const_ref: ConstRef,
) Allocator.Error!ImportedTemplateClosureView {
    for ((try app_module.exportRows()).const_templates, 0..) |template, index| {
        if (template.pattern != app_value.pattern) continue;
        if (!constRefEql(template.const_ref, const_ref)) {
            checkedModuleInvariant("platform-required app const export disagreed with top-level const ref", .{});
        }
        return closures.constTemplate(index);
    }
    checkedModuleInvariant("platform-required app const was not exported by the app module", .{});
}

fn topLevelDefSourceName(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    def: TypedCIR.Def,
) Allocator.Error!?canonical.ExportNameId {
    const ident = topLevelDefSourceIdent(def) orelse return null;
    return try names.internExportIdent(module.identStoreConst(), ident);
}

fn topLevelDefSourceIdent(def: TypedCIR.Def) ?base.Ident.Idx {
    return if (def.pattern.data == .assign) def.pattern.data.assign.ident else null;
}

/// Public `BoxPayloadCapabilityId` declaration.
pub const BoxPayloadCapabilityId = enum(u32) { _ };

/// The box payload capability of one instance of a local nominal type: its
/// declaration at one list of argument types, with its backing and padding
/// types instantiated at them.
pub const BoxPayloadCapabilityEntry = struct {
    id: BoxPayloadCapabilityId,
    nominal: canonical.NominalTypeKey,
    declaration: CheckedNominalDeclarationId,
    /// The type the capability was created for; its arguments are the
    /// instance's.
    source_ty_payload: CheckedTypeId,
    backing_ty: CheckedTypeId,
    /// Range into `ModuleInterfaceCapabilities.padding_pool` for this instance's
    /// unnamed padding field types, instantiated with its type arguments (in
    /// declared order). Empty for nominals with no unnamed fields.
    padding_start: u32 = 0,
    padding_len: u32 = 0,
    is_opaque: bool,

    /// This entry's instantiated padding field types within `caps.padding_pool`.
    pub fn paddingFieldTys(self: BoxPayloadCapabilityEntry, caps: *const ModuleInterfaceCapabilities) []const CheckedTypeId {
        return caps.padding_pool.items()[self.padding_start..][0..self.padding_len];
    }
};

/// The box payload capability one local nominal source type reads with.
pub const CapabilityRepresentationRow = struct {
    ty: CheckedTypeId,
    capability: BoxPayloadCapabilityId,
};

/// The box payload capabilities of one module's local nominal types, one
/// per instance: a declaration of the module at one list of argument types,
/// where two argument lists are one when they are equal as types
/// (`CheckedNominalEquality.declaration_args`: variables by identity, every
/// other type by structure, a nominal by its declaration and arguments).
/// Every type entry naming an instance reads with the instance's
/// capability, whenever it was created. Computed on first demand into a
/// slot of the module's analyses (`ModuleAnalyses`) for every local nominal
/// type the store holds then, which is exactly what it held when it was
/// published; a creation that ends later settles the types it made before
/// any of them leaves it (`CheckedTypeStore.finishCreation`), creating the
/// capability of an instance first met then. A consumer that reads nominal
/// representations of a module's types demands them first
/// (`CheckedTypeStoreView.interfaceCapabilities`), and reads of those types
/// then carry them.
///
/// Capability ids follow the order instances are first met: the published
/// types in id order, then each later creation's types in the order the
/// creations end, which depends on demand order. An id is only a table
/// index and an identity for equality; nothing orders anything by it.
pub const ModuleInterfaceCapabilities = struct {
    current_module: canonical.ModuleIdentityId,
    /// Every capability, by id. Grows under the store's creation lock while
    /// other threads read it.
    boxed_payload_templates: collections.PublishedList(BoxPayloadCapabilityEntry) = .empty,
    /// Shared flat pool of instantiated padding field types referenced by box
    /// entries' `(padding_start, padding_len)` ranges.
    padding_pool: collections.PublishedList(CheckedTypeId) = .empty,
    /// Every local nominal source type the store's checking reached, sorted
    /// by type id.
    source_representations: []const CapabilityRepresentationRow = &.{},
    /// Per synthesized type below its count: the capability of a local
    /// nominal type, null for any other type. Synthesized types at or past
    /// its count belong to the creation under way and are settled before it
    /// ends.
    synthesized_representations: collections.PublishedList(?BoxPayloadCapabilityId) = .empty,
    /// Read and written only under the store's creation lock: the
    /// capabilities of each instance hash (`nominalInstanceHash`).
    instances: std.AutoHashMapUnmanaged(u64, std.ArrayListUnmanaged(BoxPayloadCapabilityId)) = .empty,

    /// Compute the capabilities of `store`'s local nominal types, creating
    /// the instantiated backing and padding types they name. The caller
    /// holds the store's creation (`CheckedTypeStore.beginCreation`).
    pub fn compute(
        allocator: Allocator,
        checked_types: *CheckedTypeStore,
        current_module: canonical.ModuleIdentityId,
    ) Allocator.Error!ModuleInterfaceCapabilities {
        var result = ModuleInterfaceCapabilities{ .current_module = current_module };
        errdefer result.deinit(allocator);

        // Every type the store holds now is a type it held when it was
        // published: every slot demands its module's capabilities before
        // it creates a type there, so the capabilities of a cold module and
        // of the same module loaded from its cache entry are one table.
        const published = checked_types.published_counts orelse
            checkedModuleInvariant("interface capabilities were computed for a store that was never published", .{});
        const synthesized_count = published[@backingInt(CheckedTypeStore.Column.payloads)];
        if (std.debug.runtime_safety and checked_types.payloads.count() != synthesized_count) {
            checkedModuleInvariant("a module's types were created before its interface capabilities were demanded", .{});
        }

        var scratch = CheckedTypeStoreView.EqualityScratch.init(allocator);
        defer scratch.deinit();

        // The published synthesized types, then the source types checking
        // reached, in variable order, then every type the capabilities
        // created.
        try result.settleSynthesized(allocator, checked_types, &scratch, synthesized_count);
        var source_rows = std.ArrayList(CapabilityRepresentationRow).empty;
        defer source_rows.deinit(allocator);
        for (checked_types.sealed_var_facts.items, 0..) |var_facts, raw| {
            if (!var_facts.reached) continue;
            const ty = type_ids.fromVar(@fromBackingInt(@intCast(raw)));
            if (try result.capabilityOfType(allocator, checked_types, &scratch, ty)) |capability| {
                if (std.debug.runtime_safety and source_rows.items.len != 0 and @backingInt(source_rows.items[source_rows.items.len - 1].ty) >= @backingInt(ty)) {
                    checkedModuleInvariant("local nominal source types were settled out of id order", .{});
                }
                try source_rows.append(allocator, .{ .ty = ty, .capability = capability });
            }
        }
        result.source_representations = try source_rows.toOwnedSlice(allocator);
        try result.settleSynthesized(allocator, checked_types, &scratch, null);
        return result;
    }

    pub fn deinit(self: *ModuleInterfaceCapabilities, allocator: Allocator) void {
        self.boxed_payload_templates.deinit(allocator);
        self.padding_pool.deinit(allocator);
        allocator.free(self.source_representations);
        self.synthesized_representations.deinit(allocator);
        var buckets = self.instances.valueIterator();
        while (buckets.next()) |bucket| bucket.deinit(allocator);
        self.instances.deinit(allocator);
        self.* = undefined;
    }

    /// Settle every synthesized type of `store` past the settled ones, up
    /// to `limit` (every type, including those settling creates, when
    /// null). The caller holds the store's creation.
    fn settleSynthesized(
        self: *ModuleInterfaceCapabilities,
        allocator: Allocator,
        store: *CheckedTypeStore,
        scratch: *CheckedTypeStoreView.EqualityScratch,
        limit: ?usize,
    ) Allocator.Error!void {
        while (true) {
            const index = self.synthesized_representations.count();
            if (index >= limit orelse store.payloads.count()) return;
            const capability = try self.capabilityOfType(allocator, store, scratch, type_ids.fromSynthesized(index));
            if (std.debug.runtime_safety and self.synthesized_representations.count() != index) {
                checkedModuleInvariant("a synthesized type was settled while settling another", .{});
            }
            try self.synthesized_representations.append(allocator, capability);
        }
    }

    /// The capability `ty` reads with when it is a local nominal type of
    /// the module, creating its instance's capability when no type naming
    /// the instance was settled before; null for any other type.
    fn capabilityOfType(
        self: *ModuleInterfaceCapabilities,
        allocator: Allocator,
        store: *CheckedTypeStore,
        scratch: *CheckedTypeStoreView.EqualityScratch,
        ty: CheckedTypeId,
    ) Allocator.Error!?BoxPayloadCapabilityId {
        const view = store.view();
        const nominal = switch (view.payload(ty)) {
            .nominal => |nominal| nominal,
            .pending => checkedModuleInvariant("a pending checked type was settled", .{}),
            .field_kind, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => return null,
        };
        if (nominal.builtin != null or nominal.origin_module != self.current_module) return null;
        const declaration_id = switch (nominal.representation) {
            .local_declaration => |declaration_id| declaration_id,
            .local_box_payload_capability => |capability| self.boxPayloadCapability(capability.capability).declaration,
            .builtin, .imported_declaration, .opaque_without_backing => checkedModuleInvariant("a nominal type its module declares is not represented by its declaration", .{}),
        };
        const nominal_key = checkedNominalTypeKey(nominal);
        // nominal.args aliases type_id_pool, which instantiation grows.
        const args = try allocator.dupe(CheckedTypeId, nominal.args);
        defer allocator.free(args);

        const hash = nominalInstanceHash(view, declaration_id, args);
        const bucket = try self.instances.getOrPut(allocator, hash);
        if (!bucket.found_existing) bucket.value_ptr.* = .empty;
        const found = found: for (bucket.value_ptr.items) |candidate| {
            if (try self.instanceIs(view, scratch, candidate, declaration_id, args)) break :found candidate;
        } else null;
        if (std.debug.runtime_safety) try self.assertInstanceFound(view, scratch, declaration_id, args, found);
        if (found) |capability| return capability;

        const declaration = view.nominalDeclarationById(declaration_id);
        const backing_ty = try store.ensureInstantiatedNominalBackingRoot(allocator, declaration, args);
        const padding_field_tys = try store.ensureInstantiatedPaddingFieldTypes(allocator, declaration, args);
        defer allocator.free(padding_field_tys);
        const padding_start: u32 = @intCast(self.padding_pool.count());
        const padding_len: u32 = @intCast(padding_field_tys.len);
        try self.padding_pool.appendSlice(allocator, padding_field_tys);

        const capability: BoxPayloadCapabilityId = @fromBackingInt(@intCast(self.boxed_payload_templates.count()));
        try self.boxed_payload_templates.append(allocator, .{
            .id = capability,
            .nominal = nominal_key,
            .declaration = declaration_id,
            .source_ty_payload = ty,
            .backing_ty = backing_ty,
            .padding_start = padding_start,
            .padding_len = padding_len,
            .is_opaque = nominal.is_opaque,
        });
        try bucket.value_ptr.append(allocator, capability);
        return capability;
    }

    /// Whether `capability` is the instance of `declaration` at `args`.
    fn instanceIs(
        self: *const ModuleInterfaceCapabilities,
        view: CheckedTypeStoreView,
        scratch: *CheckedTypeStoreView.EqualityScratch,
        capability: BoxPayloadCapabilityId,
        declaration: CheckedNominalDeclarationId,
        args: []const CheckedTypeId,
    ) Allocator.Error!bool {
        const entry = self.boxPayloadCapability(capability);
        if (entry.declaration != declaration) return false;
        const instance_args = switch (view.payload(entry.source_ty_payload)) {
            .nominal => |nominal| nominal.args,
            .pending, .field_kind, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => checkedModuleInvariant("a box payload capability was created for a type that is not nominal", .{}),
        };
        if (instance_args.len != args.len) checkedModuleInvariant("two instances of one nominal declaration have different arities", .{});
        scratch.clear();
        return try checkedTypeRootSliceEql(.exact, .named, .declaration_args, view, instance_args, args, scratch);
    }

    /// Debug check that the instance hash buckets every instance of a
    /// declaration with its equal argument lists: a scan of every
    /// capability finds the instance `found` names, or none when it is null.
    fn assertInstanceFound(
        self: *const ModuleInterfaceCapabilities,
        view: CheckedTypeStoreView,
        scratch: *CheckedTypeStoreView.EqualityScratch,
        declaration: CheckedNominalDeclarationId,
        args: []const CheckedTypeId,
        found: ?BoxPayloadCapabilityId,
    ) Allocator.Error!void {
        var scanned: ?BoxPayloadCapabilityId = null;
        for (self.boxed_payload_templates.items()) |entry| {
            if (!try self.instanceIs(view, scratch, entry.id, declaration, args)) continue;
            if (scanned != null) checkedModuleInvariant("one nominal instance was given two box payload capabilities", .{});
            scanned = entry.id;
        }
        if (scanned != found) checkedModuleInvariant("a nominal instance's hash did not find the capability its equal arguments were given", .{});
    }

    pub fn boxPayloadCapability(
        self: *const ModuleInterfaceCapabilities,
        id: BoxPayloadCapabilityId,
    ) BoxPayloadCapabilityEntry {
        const entries = self.boxed_payload_templates.items();
        const index: usize = @backingInt(id);
        if (index >= entries.len) {
            checkedModuleInvariant("interface capability lookup referenced missing boxed payload capability", .{});
        }
        return entries[index];
    }

    /// The representation `nominal`, the payload of the local nominal type
    /// `ty` of `store` as the store holds it, reads with: its instance's
    /// capability once `ty` is settled, and its declaration while the
    /// creation that made it, on this thread, is under way.
    fn representationOf(
        self: *const ModuleInterfaceCapabilities,
        store: *const CheckedTypeStore,
        ty: CheckedTypeId,
        nominal: CheckedNominalType,
    ) CheckedNominalRepresentationRef {
        const capability = if (type_ids.isSynthesized(ty)) synthesized: {
            const index = type_ids.synthesizedIndex(ty);
            const settled = self.synthesized_representations.items();
            if (index >= settled.len) {
                if (std.debug.runtime_safety and !store.createdOnThisThread()) {
                    checkedModuleInvariant("a local nominal type was read before the creation that made it settled its representation", .{});
                }
                return nominal.representation;
            }
            break :synthesized settled[index] orelse
                checkedModuleInvariant("a local nominal type was settled as no local nominal type", .{});
        } else source: {
            const raw: u32 = @backingInt(ty);
            const rows = self.source_representations;
            var low: usize = 0;
            var high: usize = rows.len;
            while (low < high) {
                const mid = low + (high - low) / 2;
                const row = rows[mid];
                if (@backingInt(row.ty) == raw) break :source row.capability;
                if (@backingInt(row.ty) < raw) low = mid + 1 else high = mid;
            }
            checkedModuleInvariant("a local nominal source type checking never reached was read", .{});
        };
        if (std.debug.runtime_safety) {
            const entry = self.boxPayloadCapability(capability);
            if (!canonicalNominalTypeKeyEql(entry.nominal, checkedNominalTypeKey(nominal)) or nominal.representation != .local_declaration or nominal.representation.local_declaration != entry.declaration) {
                checkedModuleInvariant("a local nominal type reads with the capability of another declaration", .{});
            }
        }
        return .{ .local_box_payload_capability = .{ .capability = capability } };
    }
};

/// A bucket selector for the instance of `declaration` at `args`: equal
/// argument lists (`CheckedNominalEquality.declaration_args`) hash alike,
/// and `ModuleInterfaceCapabilities.instanceIs` decides within a bucket.
/// It reads each argument's constructor and names two levels deep.
fn nominalInstanceHash(view: CheckedTypeStoreView, declaration: CheckedNominalDeclarationId, args: []const CheckedTypeId) u64 {
    var hasher = std.hash.Wyhash.init(0);
    std.hash.autoHash(&hasher, declaration);
    std.hash.autoHash(&hasher, args.len);
    for (args) |arg| hashInstanceArgument(&hasher, view, arg, 2);
    return hasher.final();
}

fn hashInstanceArgument(hasher: *std.hash.Wyhash, view: CheckedTypeStoreView, ty: CheckedTypeId, depth: u8) void {
    const payload = view.payload(ty);
    std.hash.autoHash(hasher, std.meta.activeTag(payload));
    const children_depth = if (depth == 0) return else depth - 1;
    switch (payload) {
        .pending => checkedModuleInvariant("a pending checked type was hashed as a nominal argument", .{}),
        .field_kind, .err, .empty_record, .empty_tag_union => {},
        .flex, .rigid => std.hash.autoHash(hasher, ty),
        .alias => |alias| {
            std.hash.autoHash(hasher, alias.name);
            std.hash.autoHash(hasher, alias.origin_module);
            for (alias.args) |arg| hashInstanceArgument(hasher, view, arg, children_depth);
        },
        .nominal => |nominal| {
            std.hash.autoHash(hasher, nominal.origin_module);
            std.hash.autoHash(hasher, nominal.source_decl);
            for (nominal.args) |arg| hashInstanceArgument(hasher, view, arg, children_depth);
        },
        .record => |record| {
            std.hash.autoHash(hasher, record.fields.len());
            for (0..record.fields.len()) |field_index| {
                const field = record.fields.get(field_index);
                std.hash.autoHash(hasher, field.name);
                hashInstanceArgument(hasher, view, field.ty, children_depth);
            }
        },
        .tuple => |items| for (items) |item| hashInstanceArgument(hasher, view, item, children_depth),
        .function => |function| {
            std.hash.autoHash(hasher, finalizedFunctionKind(function.kind));
            for (function.args) |arg| hashInstanceArgument(hasher, view, arg, children_depth);
            hashInstanceArgument(hasher, view, function.ret, children_depth);
        },
        .tag_union => |tag_union| {
            std.hash.autoHash(hasher, tag_union.tags.len());
            for (0..tag_union.tags.len()) |tag_index| {
                const tag = tag_union.tags.get(tag_index);
                std.hash.autoHash(hasher, tag.name);
                for (tag.args) |arg| hashInstanceArgument(hasher, view, arg, children_depth);
            }
        },
    }
}

fn canonicalNominalTypeKeyEql(a: canonical.NominalTypeKey, b: canonical.NominalTypeKey) bool {
    return a.module == b.module and a.source_decl == b.source_decl;
}

/// Fill a reserved synthetic root with a variable payload and declare it a
/// fresh identity instance, as every non-clone producer of a synthetic
/// variable root must (`reserveDistinctSyntheticTypeRoot`); a test variable
/// left undeclared would trip `identityOrigin` the first time a
/// classification reaches it.
fn testFillSyntheticVariableRoot(
    allocator: Allocator,
    store: *CheckedTypeStore,
    root: CheckedTypeId,
    payload: CheckedTypePayloadBuild,
) Allocator.Error!void {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    try store.fillSyntheticTypeRoot(allocator, root, payload);
    try store.declareIdentityInstance(allocator, root);
}

/// The types of a test store whose nominal types name no declaration of
/// another module.
fn testDispatchSubstitutionTypes(store: *CheckedTypeStore, names: *canonical.CanonicalNameStore) DispatchSubstitutionTypes {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this
    const Resolver = struct {
        fn resolveNone(_: *const anyopaque, _: ModuleId) ?ImportedModuleView {
            return null;
        }
    };
    return .{
        .store = store,
        .names = names,
        .module = testCheckedModuleKey(1).digest(),
        .resolver = .{ .context = store, .resolve_fn = Resolver.resolveNone },
    };
}

fn testCheckedModuleKey(byte: u8) CheckedModuleKey {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    var key = CheckedModuleKey{};
    key.bytes[0] = byte;
    return key;
}

/// Whether no type reachable from `root` holds a callable. The answer is the
/// conjunction of every reachable type's own verdict, so each is visited once
/// from an explicit work list.
/// A type of one module a walk over checked types has entered
/// (`WalkModules`).
const WalkItem = struct { module: u32, ty: CheckedTypeId };

/// Queues the children of one walked type, which are types of its module.
const WalkChildren = struct {
    allocator: Allocator,
    module: u32,
    pending: *std.ArrayListUnmanaged(WalkItem),

    fn add(self: *WalkChildren, ty: CheckedTypeId) Allocator.Error!void {
        try self.pending.append(self.allocator, .{ .module = self.module, .ty = ty });
    }

    fn addSlice(self: *WalkChildren, tys: []const CheckedTypeId) Allocator.Error!void {
        for (tys) |ty| try self.add(ty);
    }
};

fn checkedTypeHasNoReachableCallableSlots(
    allocator: Allocator,
    module: ModuleId,
    checked_types: CheckedTypeStoreView,
    resolver: ModuleResolver,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var modules = try WalkModules.init(allocator, module, checked_types, resolver);
    defer modules.deinit(allocator);
    var visited = std.AutoHashMap(u64, void).init(allocator);
    defer visited.deinit();
    var pending: std.ArrayListUnmanaged(WalkItem) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .module = 0, .ty = root });
    while (pending.pop()) |item| {
        if ((try visited.getOrPut(WalkModules.key(item.module, item.ty))).found_existing) continue;
        var children = WalkChildren{ .allocator = allocator, .module = item.module, .pending = &pending };

        switch (modules.typesOf(item.module).payload(item.ty)) {
            .pending => checkedModuleInvariant("callable-slot proof reached pending checked type", .{}),
            .field_kind, .err => {},
            .flex,
            .rigid,
            .function,
            => return false,
            .empty_record,
            .empty_tag_union,
            => {},
            .alias => |alias| try children.add(alias.backing),
            .nominal => |nominal| {
                if (nominal.builtin) |builtin_nominal| {
                    switch (builtin_nominal) {
                        .str,
                        .u8,
                        .i8,
                        .u16,
                        .i16,
                        .u32,
                        .i32,
                        .u64,
                        .i64,
                        .u128,
                        .i128,
                        .f32,
                        .f64,
                        .dec,
                        .u8x16,
                        .i8x16,
                        .u16x8,
                        .i16x8,
                        .u32x4,
                        .i32x4,
                        .u64x2,
                        .i64x2,
                        .bool,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                        .list,
                        .box,
                        => {
                            if (nominal.args.len != 1) checkedModuleInvariant("builtin container nominal had non-unary args", .{});
                            try children.add(nominal.args[0]);
                        },
                        .try_ => {
                            if (nominal.args.len != 2) checkedModuleInvariant("builtin Try nominal had non-binary args", .{});
                            try children.addSlice(nominal.args[0..2]);
                        },
                        .set => {
                            if (nominal.args.len != 1) checkedModuleInvariant("builtin Set nominal had non-unary args", .{});
                            try children.add(nominal.args[0]);
                        },
                        .dict => {
                            if (nominal.args.len != 2) checkedModuleInvariant("builtin Dict nominal had non-binary args", .{});
                            try children.addSlice(nominal.args[0..2]);
                        },
                        .iter, .stream => {
                            if (try modules.declaration(allocator, item.module, nominal)) |site| {
                                try pending.append(allocator, .{ .module = site.module, .ty = site.declaration.backing });
                            }
                        },
                    }
                    continue;
                }
                if (try modules.declaration(allocator, item.module, nominal)) |site| {
                    try pending.append(allocator, .{ .module = site.module, .ty = site.declaration.backing });
                }
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try children.add(field.ty);
                }
                try children.add(record.ext);
            },
            .tuple => |items| try children.addSlice(items),
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try children.addSlice(tag.args);
                }
                try children.add(tag_union.ext);
            },
        }
    }
    return true;
}

/// Public `ComptimeRootKey` declaration.
pub const ComptimeRootKey = checked_ids.ComptimeRootKey;

/// Public `CompileTimeRootKind` declaration.
pub const CompileTimeRootKind = enum {
    /// Ordinary top-level value constant.
    constant,
    /// A selected top-level-equivalent expression inside a runtime body.
    hoisted_constant,
    /// A compile-time-known refutable destructure whose successful unit result
    /// has no runtime value to archive.
    hoisted_validation,
    callable_binding,
    expect,
    /// A `from_numeral` conversion of a numeric literal whose target is a
    /// non-builtin nominal type. The root body evaluates the dispatch call's
    /// `Try` result and returns its validated `Ok` payload. `Err` becomes a
    /// literal rejection terminal, reported as a checking problem.
    numeral_conversion,
    /// A `from_quote` conversion of a string literal whose target is a
    /// non-builtin nominal type; works exactly like `numeral_conversion` with
    /// `Err(BadQuotedBytes(..))` reported as the checking problem.
    quote_conversion,
    /// One explicitly requested REPL expression body whose inspected `Str`
    /// result is evaluated during checking finalization but is not installed
    /// as a source-visible top-level constant.
    repl_expr,
    /// The conversion of a literal inside a generic function at the concrete
    /// type one of this module's instantiations fixes the literal's type to
    /// (design.md "Literal Arguments"): the first place the literal's type
    /// is concrete. The root's body is the conversion the instantiation's
    /// evidence selected, called on the literal, with its `Try` result's
    /// `Ok` payload the root's value and an `Err` the literal's rejection.
    /// `CompileTimeRoot.literal_argument` names the literal and the edge.
    literal_argument,
};

/// A literal in a generic body whose conversion depends on the body's
/// instantiation (design.md "Literal Arguments").
pub const LiteralSite = struct {
    /// The checked module holding the literal.
    module: CheckedModuleDigest,
    /// The literal's CIR node in that module: a literal expression, or a
    /// custom literal pattern whose literal converts at the pattern's type.
    node: u32,
    kind: LiteralArgumentKind,

    pub fn eql(a: LiteralSite, b: LiteralSite) bool {
        return a.module.eql(b.module) and a.node == b.node and a.kind == b.kind;
    }

    /// Whether the literal's converted value is passed at runtime: an
    /// interpolation's conversion is validated at compile time only, and the
    /// body converts it through its dictionary.
    pub fn carriesValue(self: LiteralSite) bool {
        return switch (self.kind) {
            .numeral, .quote => true,
            .interpolation => false,
        };
    }
};

/// The conversion a literal argument's literal dispatches.
pub const LiteralArgumentKind = enum(u8) {
    numeral,
    quote,
    interpolation,
};

/// One instantiation edge of a scheme inside a body: a dispatch edge (the
/// evidence node whose target the edge instantiates) or a use of a procedure
/// or of a generalized local function (the use expression; for a local
/// function whose scheme its construction fixes, the function expression).
/// `literal` marks an literal requirement's own literal: no edge, the literal is in
/// the scope's body.
pub const LiteralEdge = union(enum(u8)) {
    literal,
    node: static_dispatch.EvidenceNodeId,
    use: CIR.Expr.Idx,
};

/// One literal a scheme's instantiation must convert: a literal of the
/// scheme's own body (`edge == .literal`), or literal requirement `callee_requirement`
/// of the scheme the body's `edge` instantiates. A specialization of the
/// scheme receives each literal requirement whose literal carries a value
/// (`LiteralSite.carriesValue`) as a hidden argument, in literal requirement order
/// after its dictionaries: the address of the converted value, or null
/// where the value is not stored and the body converts through its
/// dictionary.
pub const LiteralRequirement = struct {
    site: LiteralSite,
    /// The literal's type in this scheme's module, over the scheme's
    /// variables and its enclosing scopes'.
    ty: CheckedTypeId,
    edge: LiteralEdge,
    callee_requirement: u32,
};

/// Where an edge's hidden literal argument comes from: a `literal_argument`
/// root of the edge's module (its converted value) or an literal requirement of the
/// scope the edge is in (that scope's own hidden argument).
pub const LiteralArgSource = union(enum(u8)) {
    root: ComptimeRootKey,
    forwarded: u32,
    /// The instantiated literal's type mentions a variable that no scheme
    /// around the edge quantifies: a use's copy of a variable nothing relates
    /// to the program, such as `_ = local` taking a generalized local function
    /// that nothing calls. No use fixes that variable, so nothing reads the
    /// argument.
    unbound,
};

/// What a `literal_argument` root converts: the literal requirement
/// `callee_requirement` of the scheme this module's `edge` instantiates, at
/// the closed type `ty`. A validate-only root (its value is an interpolation
/// assembler, or holds a function) is evaluated for its outcome and stores
/// no value; its wrapper, called at runtime, converts the literal.
pub const LiteralArgumentRoot = struct {
    site: LiteralSite,
    ty: CheckedTypeId,
    edge: LiteralEdge,
    callee_requirement: u32,
    validate_only: bool,
};

/// The two literal-conversion root kinds, as a payload-free classification
/// (design.md "Defaulted Fields": a defaulted field's conversion literal
/// gets an ordinary conversion root in its declaring module; there is no
/// separate field-default root kind).
pub const CompileTimeLiteralConversionKind = enum(u8) {
    numeral,
    quote,
};

/// Public `CompileTimeRootPayload` declaration.
pub const CompileTimeRootPayload = union(enum) {
    pending,
    /// A requested root that no compilation finalizing this module demanded
    /// (design.md "Demand-Driven Compile-Time Evaluation"). Its value was
    /// never computed; a later compilation that demands it evaluates it
    /// against this same checked module, through the same declared root
    /// function an uncached compilation uses.
    unevaluated,
    const_node: ConstNodeId,
    fn_value: ConstFnId,
    discarded,
    expect,
    /// A guarded hoisted root whose compile-time evaluation failed. Runtime
    /// lowering evaluates its original expression and declaration in place.
    runtime,
};

/// Whether a selected compile-time root may become a root request.
pub const CompileTimeRootRequestEligibility = enum(u8) {
    pending,
    eligible,
    ineligible,
};

/// Public `CompileTimeRoot` declaration.
pub const CompileTimeRoot = struct {
    id: ComptimeRootKey,
    module_idx: u32,
    kind: CompileTimeRootKind,
    source: RootSource,
    source_pattern: ?CIR.Pattern.Idx = null,
    /// A selected hoisted root's body. A pattern body is a construct
    /// lowering builds from this description: a crash for a rejected
    /// destructure binder, or a match of the base expression against the
    /// pattern that yields the bound value or unit.
    hoisted_body: ?hoist_roots.Body = null,
    pattern: ?CIR.Pattern.Idx,
    /// The root's expression: the evaluated expression or a hoisted pattern
    /// root's selected expression. A literal conversion root has none: it
    /// converts the literal its `source` names (`literalNode`).
    expr: ?CIR.Expr.Idx,
    checked_type: CheckedTypeId,
    request_eligibility: CompileTimeRootRequestEligibility,
    /// A hoisted root reached only through a branch, guard, loop body, or
    /// expect body. Its evaluation failure is not a diagnostic; finalization
    /// records the `runtime` payload instead.
    guarded: bool = false,
    /// For a `literal_argument` root: what it converts.
    literal_argument: ?LiteralArgumentRoot = null,

    /// The expression the root evaluates itself, or null when its entry
    /// evaluates a lowering-side construct instead: the one its
    /// `hoisted_body` describes for a hoisted pattern root (a crash for a
    /// rejected destructure binder, or a match of its base expression against
    /// its pattern), or a literal conversion root's conversion of its literal
    /// (`literalNode`).
    pub fn evaluatedExpr(self: CompileTimeRoot) ?CIR.Expr.Idx {
        if (self.literalNode() != null) return null;
        const body = self.hoisted_body orelse return self.rootExpr();
        return switch (body) {
            .expr, .valueless_binding => self.rootExpr(),
            .pattern_error, .pattern_extraction, .pattern_validation => null,
        };
    }

    /// The body nodes the root evaluates: its expression and, for a hoisted
    /// pattern root, the pattern it matches the base expression against; for
    /// a literal conversion root, the literal it converts.
    pub fn bodyParts(self: CompileTimeRoot) RootBodyParts {
        if (self.literalNode()) |literal| return .{ .literal = literal };
        const body = self.hoisted_body orelse return .{ .expr = self.rootExpr() };
        return switch (body) {
            .expr, .valueless_binding => .{ .expr = self.rootExpr() },
            .pattern_error => .{},
            .pattern_extraction => |extraction| .{ .expr = extraction.base_expr, .pattern = extraction.scrutinee_pattern },
            .pattern_validation => |validation| .{ .expr = validation.base_expr, .pattern = validation.scrutinee_pattern },
        };
    }

    /// The literal a literal conversion root converts, or null for every
    /// other root.
    pub fn literalNode(self: CompileTimeRoot) ?LiteralNode {
        return switch (self.source) {
            .literal => |literal| literal,
            .def, .expr, .statement, .required_binding, .hoisted => null,
        };
    }

    /// The expression a root other than a literal conversion root evaluates
    /// or selects.
    pub fn rootExpr(self: CompileTimeRoot) CIR.Expr.Idx {
        return self.expr orelse checkedModuleInvariant("a literal conversion root was read as an expression root", .{});
    }

    pub fn literalConversionKind(self: CompileTimeRoot) ?CompileTimeLiteralConversionKind {
        return switch (self.kind) {
            .numeral_conversion => .numeral,
            .quote_conversion => .quote,
            .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .expect, .repl_expr, .literal_argument => null,
        };
    }
};

/// The body nodes a compile-time root evaluates (`CompileTimeRoot.bodyParts`).
pub const RootBodyParts = struct {
    expr: ?CIR.Expr.Idx = null,
    pattern: ?CIR.Pattern.Idx = null,
    /// A literal conversion root's literal. The root converts the literal's
    /// value as data; it evaluates none of the literal's CIR.
    literal: ?LiteralNode = null,
};

/// Whether a compile-time root's body contains a diagnostic error.
fn rootBodyContainsDiagnosticError(diagnostics: *const body_analyses.NodeBits, root: CompileTimeRoot) bool {
    if (root.hoisted_body) |body| if (body == .pattern_error) return true;
    const parts = root.bodyParts();
    if (parts.expr) |expr| if (diagnostics.isSet(@backingInt(expr))) return true;
    if (parts.pattern) |pattern| if (diagnostics.isSet(@backingInt(pattern))) return true;
    if (parts.literal) |literal| if (diagnostics.isSet(literal.node())) return true;
    return false;
}

/// Public `CompileTimeRootTable` declaration.
///
/// This is the durable compile-time root schedule and payload table. It stores
/// root identities and selected root bodies only; it deliberately does not
/// store dependency edges, readiness state, request membership caches, or
/// per-expression/per-pattern hoistability facts. Ordinary top-level roots are
/// published first in canonical order, then sparse selected hoisted roots are
/// appended in checker-selected dependency-first order. Finalization consumes
/// the sorted request stream and validates this order with temporary scratch.
pub const CompileTimeRootTable = struct {
    roots: []CompileTimeRoot = &.{},

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        checked_types: *const CheckedSourceTypes,
        module_index: *const ModuleIndex,
        procedure_templates: *const CheckedProcedureTemplateTable,
        empty_record: ?CheckedTypeId,
    ) Allocator.Error!CompileTimeRootTable {
        var roots = std.ArrayList(CompileTimeRoot).empty;
        errdefer {
            deinitCompileTimeRootSlice(allocator, roots.items);
            roots.deinit(allocator);
        }

        // Field defaults get no root of their own (design.md "Defaulted
        // Fields"): every construction site that omits a defaulted field
        // lowers the declaring module's archived checked expression at the
        // site's monotype—per-specialization materialization. A default
        // whose literal needs a closed custom conversion gets its ordinary
        // conversion root after dispatch evidence is finalized.
        const module_env = module.moduleEnvConst();

        for (module_env.requested_compile_time_roots.items.items) |requested_root| {
            const expr_idx = requested_root.body;
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .repl_expr,
                .source = .{ .expr = expr_idx },
                .pattern = null,
                .expr = reachedRootExpr(module_index, expr_idx),
                .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, module.exprType(expr_idx)),
            });
        }

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedModuleInvariant("generated method marker reached compile-time-root publication", .{});
            }
            if (topLevelDefSourceIdent(def) == null) continue;
            if (procedure_templates.lookupByDef(def_idx) != null) continue;
            // An annotation-only declaration has no value to evaluate; its
            // const template already records that the value is missing.
            if (def.expr.data == .e_anno_only) continue;

            const source_ty = module.defType(def_idx);
            if (sourceTypeIsFunction(module, source_ty)) {
                if (def.expr.data == .e_runtime_error) continue;
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .callable_binding,
                    .source = .{ .def = def_idx },
                    .pattern = reachedRootPattern(module_index, def.pattern.idx),
                    .expr = reachedRootExpr(module_index, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                });
            } else {
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .constant,
                    .source = .{ .def = def_idx },
                    .pattern = reachedRootPattern(module_index, def.pattern.idx),
                    .expr = reachedRootExpr(module_index, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                });
            }
        }

        for (module_env.selected_hoisted_roots.items.items, 0..) |selected, selected_index| {
            const source_ty = if (selected.pattern) |pattern|
                ModuleEnv.varFrom(pattern)
            else
                module.exprType(selected.expr);
            const source_is_function = sourceTypeIsFunction(module, source_ty);
            const kind: CompileTimeRootKind = switch (selected.value_kind) {
                .data_constant => if (source_is_function)
                    checkedModuleInvariant("function-typed selected root was classified as a data constant", .{})
                else
                    .hoisted_constant,
                .callable_binding => if (!source_is_function)
                    checkedModuleInvariant("non-function selected root was classified as a callable binding", .{})
                else
                    .callable_binding,
                .discarded => .hoisted_validation,
            };
            const checked_root = try selectedHoistedRootBody(allocator, module, checked_types, module_index, selected, empty_record);
            const hoisted_body = try hoist_roots.cloneBody(allocator, selected.body);
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = kind,
                .source = .{ .hoisted = .{
                    .index = @intCast(selected_index),
                    .expr = selected.expr,
                } },
                .source_pattern = selected.pattern,
                .hoisted_body = hoisted_body,
                .pattern = checked_root.pattern,
                .expr = checked_root.expr,
                .checked_type = checked_root.checked_type,
                .guarded = selected.guarded,
            });
        }

        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            const stmt = module_env.store.getStatement(statement_idx);
            if (stmt != .s_expect) continue;
            try collectExpectRoot(
                &roots,
                allocator,
                module,
                checked_types,
                module_index,
                statement_idx,
                stmt.s_expect.body,
            );
        }

        try recordCompileTimeRootRequestEligibility(allocator, module, checked_types, roots.items);

        std.mem.sort(CompileTimeRoot, roots.items, {}, struct {
            fn lessThan(_: void, a: CompileTimeRoot, b: CompileTimeRoot) bool {
                return @backingInt(a.id) < @backingInt(b.id);
            }
        }.lessThan);
        return .{ .roots = try roots.toOwnedSlice(allocator) };
    }

    pub fn lookupIdByPattern(self: *const CompileTimeRootTable, pattern: CIR.Pattern.Idx) ?ComptimeRootKey {
        for (self.roots) |entry| {
            if (entry.kind == .hoisted_validation) continue;
            if (entry.pattern != null and entry.pattern.? == pattern) return entry.id;
        }
        return null;
    }

    /// Whether evaluation discarded the runtime-erasable validation root of
    /// `pattern`, given the module's evaluation output.
    pub fn validationResolvedByPattern(self: *const CompileTimeRootTable, evaluation: *const EvaluationOutput, pattern: CIR.Pattern.Idx) bool {
        for (self.roots) |entry| {
            if (entry.kind != .hoisted_validation or entry.pattern != pattern) continue;
            const body = entry.hoisted_body orelse checkedModuleInvariant("hoisted validation root had no selected body", .{});
            if (body != .pattern_validation) checkedModuleInvariant("hoisted validation root had a non-validation body", .{});
            if (!body.pattern_validation.erase_runtime) return false;
            return evaluation.rootPayload(entry.id) == .discarded;
        }
        return false;
    }

    /// Look up a selected hoisted constant root by its checked source expression.
    pub fn lookupHoistedRootByExpr(self: *const CompileTimeRootTable, expr: CIR.Expr.Idx) ?CompileTimeRoot {
        for (self.roots) |entry| {
            if (entry.kind == .hoisted_constant and entry.expr == expr) return entry;
        }
        return null;
    }

    /// Row `id` of the table. A literal root is no row
    /// (`CheckedModule.compileTimeRoot`).
    pub fn root(self: *const CompileTimeRootTable, id: ComptimeRootKey) CompileTimeRoot {
        const index = self.position(id) orelse checkedModuleInvariant("a compile-time root was read that its module's root table does not hold", .{});
        return self.roots[index];
    }

    /// The position of row `id` in the table, ascending by root identity.
    pub fn position(self: *const CompileTimeRootTable, id: ComptimeRootKey) ?u32 {
        const index = std.sort.binarySearch(CompileTimeRoot, self.roots, id, struct {
            fn order(key: ComptimeRootKey, item: CompileTimeRoot) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.id));
            }
        }.order) orelse return null;
        return @intCast(index);
    }

    pub fn deinit(self: *CompileTimeRootTable, allocator: Allocator) void {
        deinitCompileTimeRootSlice(allocator, self.roots);
        allocator.free(self.roots);
        self.* = .{};
    }

    const RootWithoutId = struct {
        module_idx: u32,
        kind: CompileTimeRootKind,
        source: RootSource,
        source_pattern: ?CIR.Pattern.Idx = null,
        hoisted_body: ?hoist_roots.Body = null,
        pattern: ?CIR.Pattern.Idx,
        expr: ?CIR.Expr.Idx,
        checked_type: CheckedTypeId,
        request_eligibility: CompileTimeRootRequestEligibility = .pending,
        guarded: bool = false,
        literal_argument: ?LiteralArgumentRoot = null,
    };

    /// Collect one top-level `expect` as a test root. Expects evaluated inside
    /// its body remain inline and are reported by the test observation table.
    fn collectExpectRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedSourceTypes,
        module_index: *const ModuleIndex,
        statement_idx: CIR.Statement.Idx,
        body_expr: CIR.Expr.Idx,
    ) Allocator.Error!void {
        try appendCompileTimeRoot(roots, allocator, .{
            .module_idx = module.moduleIndex(),
            .kind = .expect,
            .source = .{ .statement = statement_idx },
            .pattern = null,
            .expr = reachedRootExpr(module_index, body_expr),
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(body_expr)),
        });
    }

    /// The identity of the row root `source` names.
    fn rootIdForSource(source: RootSource) ComptimeRootKey {
        return switch (source) {
            .expr => |expr| ComptimeRootKey.ofSource(.repl_expr, @backingInt(expr)),
            .def => |def| ComptimeRootKey.ofSource(.def, @backingInt(def)),
            .hoisted => |hoisted| ComptimeRootKey.ofSource(.hoisted, hoisted.index),
            .statement => |statement| ComptimeRootKey.ofSource(.expect, @backingInt(statement)),
            .required_binding, .literal => checkedModuleInvariant("a root table row was named by a source no row root has", .{}),
        };
    }

    fn appendCompileTimeRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        entry: RootWithoutId,
    ) Allocator.Error!void {
        const id = rootIdForSource(entry.source);
        roots.append(allocator, .{
            .id = id,
            .module_idx = entry.module_idx,
            .kind = entry.kind,
            .source = entry.source,
            .source_pattern = entry.source_pattern,
            .hoisted_body = entry.hoisted_body,
            .pattern = entry.pattern,
            .expr = entry.expr,
            .checked_type = entry.checked_type,
            .request_eligibility = entry.request_eligibility,
            .guarded = entry.guarded,
            .literal_argument = entry.literal_argument,
        }) catch |err| {
            if (entry.hoisted_body) |body| hoist_roots.deinitBody(allocator, body);
            return err;
        };
    }
};

/// Request eligibility from each root's solved type. Diagnostic exclusion
/// follows once the body diagnostic facts are published.
fn recordCompileTimeRootRequestEligibility(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedSourceTypes,
    roots: []CompileTimeRoot,
) Allocator.Error!void {
    var proofs = try ConcreteRootProofs.init(allocator, checked_types.current_owner, checked_types.view, checked_types.resolver);
    defer proofs.deinit();
    for (roots) |*root| {
        const producer_callable_type_is_fixed = switch (root.kind) {
            .callable_binding => true,
            .constant => switch (root.source) {
                .def => |def_idx| module.def(def_idx).data.annotation != null,
                .expr, .statement, .hoisted, .required_binding, .literal => false,
            },
            .hoisted_constant,
            .hoisted_validation,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .repl_expr,
            .literal_argument,
            => false,
        };
        const context_free = try proofs.isContextFree(producer_callable_type_is_fixed, root.checked_type);
        root.request_eligibility = if (context_free) .eligible else .ineligible;
    }
}

/// How much of one quantified variable a procedure template's body demands
/// (design.md "Specialization By Demand"). The scale is the same one
/// `LowLevel.elementDemand` places on an operation's arguments.
pub const SchemeVarDemand = base.LowLevel.ElementDemand;

fn maxSchemeVarDemand(left: SchemeVarDemand, right: SchemeVarDemand) SchemeVarDemand {
    return if (@backingInt(left) >= @backingInt(right)) left else right;
}

/// How a checked type reaches one type variable it mentions. Each flag is
/// true when at least one path from the type to the variable has the
/// property, so the flags of several paths combine by `or`.
const TypeVarMentionFlags = packed struct(u8) {
    /// A path passes through a function's argument or result.
    under_function: bool = false,
    /// A path reaches the variable without passing through the element of a
    /// `List` or `Box`.
    outside_container: bool = false,
    /// The variable is the extension of a record or tag-union row.
    row_extension: bool = false,
    /// A path passes through an argument of a builtin nominal whose runtime
    /// representation that argument's structure decides, not just its layout:
    /// the field-name tables of `FieldNames`, `FieldName`, and
    /// `ParseTagUnionSpec`, and the iterator representation of `Iter` and
    /// `Stream`.
    decides_representation: bool = false,
    _padding: u4 = 0,

    fn merge(left: TypeVarMentionFlags, right: TypeVarMentionFlags) TypeVarMentionFlags {
        return @bitCast(@as(u8, @bitCast(left)) | @as(u8, @bitCast(right)));
    }

    /// The flags of a path that reaches a nominal's argument along `self` and
    /// then, inside the nominal's backing, reaches the argument's formal
    /// along `formal`.
    fn through(self: TypeVarMentionFlags, formal: TypeVarMentionFlags) TypeVarMentionFlags {
        return .{
            .under_function = self.under_function or formal.under_function,
            .outside_container = self.outside_container and formal.outside_container,
            .decides_representation = self.decides_representation or formal.decides_representation,
        };
    }
};

/// One type variable a checked type mentions, and how.
const TypeVarMention = struct {
    var_ty: CheckedTypeId,
    flags: TypeVarMentionFlags,
};

/// The type variables each checked type mentions, memoized by type.
const TypeVarMentions = struct {
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    memo: collections.DenseMap(CheckedTypeId, store_serialize.Span),
    pool: std.ArrayList(TypeVarMention) = .empty,
    /// Walk state of one query: each (type, flags) pair is visited once, so a
    /// cyclic type terminates.
    pending: std.ArrayList(Step) = .empty,
    visited: std.AutoHashMapUnmanaged(Step, void) = .empty,
    found: collections.DenseMap(CheckedTypeId, TypeVarMentionFlags),
    reach: NominalFormalReach,

    const Step = struct {
        ty: CheckedTypeId,
        flags: TypeVarMentionFlags,
    };

    fn deinit(self: *TypeVarMentions) void {
        self.reach.deinit();
        self.memo.deinit();
        self.pool.deinit(self.allocator);
        self.pending.deinit(self.allocator);
        self.visited.deinit(self.allocator);
        self.found.deinit();
    }

    /// The variables `root` mentions, in ascending type-id order.
    fn of(self: *TypeVarMentions, root: CheckedTypeId) Allocator.Error![]const TypeVarMention {
        if (self.memo.get(root)) |span| return self.pool.items[span.start .. span.start + span.len];
        self.pending.clearRetainingCapacity();
        self.visited.clearRetainingCapacity();
        self.found.clearRetainingCapacity();
        try self.push(root, .{ .outside_container = true });
        while (self.pending.pop()) |step| try expandStep(self.checked_types, step, self);
        const lessThan = struct {
            fn lessThan(_: void, left: TypeVarMention, right: TypeVarMention) bool {
                return @backingInt(left.var_ty) < @backingInt(right.var_ty);
            }
        }.lessThan;
        const start = self.pool.items.len;
        try self.pool.ensureUnusedCapacity(self.allocator, self.found.count());
        var it = self.found.iterator();
        while (it.next()) |entry| self.pool.appendAssumeCapacity(.{ .var_ty = entry.key_ptr.*, .flags = entry.value_ptr.* });
        const mentions = self.pool.items[start..];
        std.mem.sort(TypeVarMention, mentions, {}, lessThan);
        try self.memo.put(root, .{ .start = @intCast(start), .len = @intCast(mentions.len) });
        return mentions;
    }

    /// Visit one step of a walk from a type to the variables it mentions:
    /// note the variable it reaches, or push each component with the flags of
    /// the path through it. `sink` provides `push(ty, flags)`,
    /// `noteMention(var_ty, flags)` and `nominalReach(nominal)`.
    /// `type_source` (a store or a view) holds the types the walk names.
    fn expandStep(type_source: anytype, step: Step, sink: anytype) Allocator.Error!void {
        switch (type_source.payload(step.ty)) {
            .flex, .rigid => try sink.noteMention(step.ty, step.flags),
            .alias => |alias| try sink.push(alias.backing, step.flags),
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try sink.push(field.ty, step.flags);
                }
                try expandRowExtension(type_source, record.ext, step.flags, sink);
            },
            .tuple => |elems| for (elems) |elem| try sink.push(elem, step.flags),
            .nominal => |nominal| {
                if (try sink.nominalReach(nominal)) |reach| {
                    // A declared backing reaches each formal as its paths
                    // do: an argument stands where the backing places it.
                    for (nominal.args, reach) |arg, formal| {
                        try sink.push(arg, step.flags.through(formal.value orelse .{}));
                        if (formal.row) |row| try expandRowExtension(type_source, arg, step.flags.through(row), sink);
                    }
                } else {
                    var arg_flags = step.flags;
                    if (nominal.builtin) |builtin_nominal| switch (builtin_nominal) {
                        .list, .box => arg_flags.outside_container = false,
                        .fields, .field, .parse_tag_union_spec, .iter, .stream => arg_flags.decides_representation = true,
                        .bool, .try_, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .dict, .set, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => {},
                    };
                    for (nominal.args) |arg| try sink.push(arg, arg_flags);
                }
                for (nominal.padding_field_types) |padding| try sink.push(padding, step.flags);
            },
            .function => |function| {
                var inner = step.flags;
                inner.under_function = true;
                for (function.args) |arg| try sink.push(arg, inner);
                try sink.push(function.ret, inner);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    for (tag.args) |arg| try sink.push(arg, step.flags);
                }
                try expandRowExtension(type_source, tag_union.ext, step.flags, sink);
            },
            .empty_record, .empty_tag_union, .field_kind, .err, .pending => {},
        }
    }

    fn expandRowExtension(type_source: anytype, ext: CheckedTypeId, flags: TypeVarMentionFlags, sink: anytype) Allocator.Error!void {
        switch (type_source.payload(ext)) {
            .flex, .rigid => {
                var ext_flags = flags;
                ext_flags.row_extension = true;
                try sink.noteMention(ext, ext_flags);
            },
            .pending, .field_kind, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => try sink.push(ext, flags),
        }
    }

    fn push(self: *TypeVarMentions, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
        const step: Step = .{ .ty = ty, .flags = flags };
        const entry = try self.visited.getOrPut(self.allocator, step);
        if (entry.found_existing) return;
        try self.pending.append(self.allocator, step);
    }

    fn noteMention(self: *TypeVarMentions, var_ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
        const entry = try self.found.getOrPut(var_ty);
        entry.value_ptr.* = if (entry.found_existing) entry.value_ptr.merge(flags) else flags;
    }

    fn nominalReach(self: *TypeVarMentions, nominal: CheckedNominalType) Allocator.Error!?[]const FormalReach {
        return self.reach.get(0, nominal);
    }
};

/// How a nominal declaration's backing reaches one of its formal parameters:
/// the merged flags of the paths that reach it other than as a row
/// extension, and of the paths that reach it as one. Null when no such path
/// exists.
const FormalReach = struct {
    value: ?TypeVarMentionFlags = null,
    row: ?TypeVarMentionFlags = null,
};

/// How each user nominal declaration's backing reaches its formals, computed
/// once per declaration on first use. A declaration is read in the module
/// that declares it, through that module's types (`WalkModules`, whose index
/// 0 is the module whose types name the nominals asked about). A builtin
/// nominal's arguments follow `TypeVarMentions.expandStep`'s builtin table
/// instead, and an opaque nominal without a backing passes its arguments
/// through unchanged. The declarations whose backings name one another form a
/// group whose reaches are a least fixed point: every flag only rises, so
/// re-walking the group until nothing changes converges.
const NominalFormalReach = struct {
    allocator: Allocator,
    modules: WalkModules,
    /// Each declaration's position in `entries`.
    by_declaration: std.AutoHashMapUnmanaged(DeclarationKey, u32) = .empty,
    entries: std.ArrayList(Entry) = .empty,
    pool: std.ArrayList(FormalReach) = .empty,
    group: std.ArrayList(u32) = .empty,
    pending: std.ArrayList(TypeVarMentions.Step) = .empty,
    visited: std.AutoHashMapUnmanaged(TypeVarMentions.Step, void) = .empty,

    /// A declaration, by the walk index of its declaring module.
    const DeclarationKey = struct {
        module: u32,
        declaration: CheckedNominalDeclarationId,
    };

    const Entry = struct {
        module: u32,
        declaration: CheckedNominalDeclaration,
        state: enum { unknown, computing, done } = .unknown,
        start: u32 = 0,
        len: u32 = 0,
    };

    fn deinit(self: *NominalFormalReach) void {
        self.modules.deinit(self.allocator);
        self.by_declaration.deinit(self.allocator);
        self.entries.deinit(self.allocator);
        self.pool.deinit(self.allocator);
        self.group.deinit(self.allocator);
        self.pending.deinit(self.allocator);
        self.visited.deinit(self.allocator);
    }

    /// The reach of each formal of the declaration of `nominal`, a type of
    /// module `module` (a walk index), or null when its arguments are not
    /// read through a declared backing.
    fn get(self: *NominalFormalReach, module: u32, nominal: CheckedNominalType) Allocator.Error!?[]const FormalReach {
        const index = (try self.entryOf(module, nominal)) orelse return null;
        if (self.entries.items[index].state != .done) try self.computeGroup(index);
        return self.slice(index);
    }

    fn slice(self: *const NominalFormalReach, index: u32) []const FormalReach {
        const entry = self.entries.items[index];
        return self.pool.items[entry.start .. entry.start + entry.len];
    }

    fn entryTypes(self: *const NominalFormalReach, index: u32) CheckedTypeStoreView {
        return self.modules.typesOf(self.entries.items[index].module);
    }

    /// The entry of the declaration of `nominal`, a type of module `module`,
    /// created unknown on first sight; null for a builtin nominal and for a
    /// nominal with no declaration backing.
    fn entryOf(self: *NominalFormalReach, module: u32, nominal: CheckedNominalType) Allocator.Error!?u32 {
        if (nominal.builtin != null) return null;
        switch (nominal.representation) {
            .builtin, .opaque_without_backing => return null,
            .local_declaration, .imported_declaration, .local_box_payload_capability => {},
        }
        const site = (try self.modules.declaration(self.allocator, module, nominal)) orelse
            checkedModuleInvariant("a user nominal's declaration was missing from its declaring module", .{});
        const key: DeclarationKey = .{ .module = site.module, .declaration = site.declaration.id };
        const found = try self.by_declaration.getOrPut(self.allocator, key);
        if (!found.found_existing) {
            found.value_ptr.* = @intCast(self.entries.items.len);
            try self.entries.append(self.allocator, .{ .module = site.module, .declaration = site.declaration });
        }
        return found.value_ptr.*;
    }

    /// Compute the reaches of `root`'s declaration and of every declaration
    /// its backing reaches whose reaches are not yet known.
    fn computeGroup(self: *NominalFormalReach, root: u32) Allocator.Error!void {
        self.group.clearRetainingCapacity();
        try self.join(root);
        var collected: usize = 0;
        while (collected < self.group.items.len) : (collected += 1) {
            const index = self.group.items[collected];
            const module_types = self.entryTypes(index);
            self.pending.clearRetainingCapacity();
            self.visited.clearRetainingCapacity();
            try self.walk(self.entries.items[index].declaration.backing, .{ .outside_container = true });
            const sink: CollectSink = .{ .reach = self, .module = self.entries.items[index].module };
            while (self.pending.pop()) |step| try TypeVarMentions.expandStep(module_types, step, sink);
        }
        var changed = true;
        while (changed) {
            changed = false;
            for (self.group.items) |index| {
                const module_types = self.entryTypes(index);
                const entry = self.entries.items[index];
                self.pending.clearRetainingCapacity();
                self.visited.clearRetainingCapacity();
                try self.walk(entry.declaration.backing, .{ .outside_container = true });
                var sink: FormalSink = .{ .reach = self, .module = entry.module, .formals = entry.declaration.formalArgs(module_types), .index = index };
                while (self.pending.pop()) |step| try TypeVarMentions.expandStep(module_types, step, &sink);
                changed = changed or sink.changed;
            }
        }
        for (self.group.items) |index| self.entries.items[index].state = .done;
    }

    fn join(self: *NominalFormalReach, index: u32) Allocator.Error!void {
        const entry = &self.entries.items[index];
        if (entry.state != .unknown) return;
        const formals = entry.declaration.formalArgs(self.entryTypes(index));
        entry.state = .computing;
        entry.start = @intCast(self.pool.items.len);
        entry.len = @intCast(formals.len);
        try self.pool.appendNTimes(self.allocator, .{}, formals.len);
        try self.group.append(self.allocator, index);
    }

    fn walk(self: *NominalFormalReach, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
        const step: TypeVarMentions.Step = .{ .ty = ty, .flags = flags };
        const entry = try self.visited.getOrPut(self.allocator, step);
        if (entry.found_existing) return;
        try self.pending.append(self.allocator, step);
    }

    /// Finds the declarations a backing names, so the group holds them.
    const CollectSink = struct {
        reach: *NominalFormalReach,
        /// The walk index of the module whose types the backing names.
        module: u32,

        pub fn push(sink: CollectSink, ty: CheckedTypeId, _: TypeVarMentionFlags) Allocator.Error!void {
            try sink.reach.walk(ty, .{});
        }

        pub fn noteMention(_: CollectSink, _: CheckedTypeId, _: TypeVarMentionFlags) Allocator.Error!void {}

        pub fn nominalReach(sink: CollectSink, nominal: CheckedNominalType) Allocator.Error!?[]const FormalReach {
            if (try sink.reach.entryOf(sink.module, nominal)) |index| try sink.reach.join(index);
            return null;
        }
    };

    /// Records how one declaration's backing reaches its formals, reading the
    /// group's current reaches for the declarations the backing names.
    const FormalSink = struct {
        reach: *NominalFormalReach,
        /// The walk index of the module whose types the backing names.
        module: u32,
        formals: []const CheckedTypeId,
        index: u32,
        changed: bool = false,

        pub fn push(sink: *FormalSink, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            try sink.reach.walk(ty, flags);
        }

        pub fn noteMention(sink: *FormalSink, var_ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            const position = for (sink.formals, 0..) |formal_ty, index| {
                if (formal_ty == var_ty) break index;
            } else return;
            const entry = sink.reach.entries.items[sink.index];
            const formal = &sink.reach.pool.items[entry.start + position];
            var path = flags;
            path.row_extension = false;
            const slot = if (flags.row_extension) &formal.row else &formal.value;
            const merged = if (slot.*) |existing| existing.merge(path) else path;
            if (slot.* == null or @as(u8, @bitCast(slot.*.?)) != @as(u8, @bitCast(merged))) {
                slot.* = merged;
                sink.changed = true;
            }
        }

        pub fn nominalReach(sink: *FormalSink, nominal: CheckedNominalType) Allocator.Error!?[]const FormalReach {
            const index = (try sink.reach.entryOf(sink.module, nominal)) orelse return null;
            if (sink.reach.entries.items[index].state == .unknown) {
                checkedModuleInvariant("a nominal backing named a declaration outside its reach group", .{});
            }
            return sink.reach.slice(index);
        }
    };
};

/// The demand of a caller's `caller_slot` is at least that of `callee_slot`
/// of the template `callee` names.
pub const TemplateDemandEdge = struct {
    caller_slot: u32,
    callee: TemplateDemandCallee,
    callee_slot: u32,
};

/// The callee of a demand edge: a template of the module itself (its raw
/// template id), or a template of a module dispatch resolution reads.
pub const TemplateDemandCallee = union(enum) {
    local: u32,
    imported: canonical.ProcedureTemplateRef,
};

/// One strongly connected component's demand vectors, in the component's
/// member order (`TemplateDemandGraph.componentMembers`).
pub const TemplateDemandComponent = struct {
    starts: []const u32,
    demands: []const SchemeVarDemand,

    pub fn member(self: *const TemplateDemandComponent, index: u32) []const SchemeVarDemand {
        return self.demands[self.starts[index]..self.starts[index + 1]];
    }

    pub fn destroy(self: *TemplateDemandComponent, allocator: Allocator) void {
        allocator.free(self.starts);
        allocator.free(self.demands);
        allocator.destroy(self);
    }
};

/// The slot holding one component's demand vectors.
pub const TemplateDemandComponentSlot = collections.OnceSlot(*TemplateDemandComponent, .module_template_demand);

/// The slot holding one template's part of a module's demand call graph.
pub const TemplateDemandNodeSlot = collections.OnceSlot(*TemplateDemandNode, .module_template_demand_node);

/// One template's part of a module's demand call graph
/// (`ModuleAnalyses.templateDemandNode`): its demand vector as its own body
/// sets it, the edges along which its callees' demands raise it, and the
/// templates of the module those edges call, each once.
pub const TemplateDemandNode = struct {
    base: []const SchemeVarDemand,
    edges: []const TemplateDemandEdge,
    callees: []const u32,

    pub fn destroy(self: *TemplateDemandNode, allocator: Allocator) void {
        allocator.free(self.base);
        allocator.free(self.edges);
        allocator.free(self.callees);
        allocator.destroy(self);
    }
};

/// A module's demand call graph (`ModuleAnalyses.templateDemandGraph`),
/// built only as far as a consumer reaches it: each template's own vector
/// and edges (`TemplateDemandNode`) and each strongly connected component of
/// the local edges, with the component's vectors, are slots of their own.
pub const TemplateDemandGraph = struct {
    node_slots: []TemplateDemandNodeSlot,
    components: LazyComponents,
    /// Each component's vectors, by its leader.
    component_slots: []TemplateDemandComponentSlot,

    /// Template `template`'s part of the graph, which its component's
    /// assignment computed.
    pub fn finishedNode(self: *const TemplateDemandGraph, template: u32) *const TemplateDemandNode {
        return self.node_slots[template].peek() orelse
            checkedModuleInvariant("a demand graph node was read before it was computed", .{});
    }

    /// The templates template `template`'s edges call.
    pub fn calleesOf(self: *const TemplateDemandGraph, template: u32) []const u32 {
        return self.finishedNode(template).callees;
    }

    pub fn destroy(self: *TemplateDemandGraph, allocator: Allocator) void {
        for (self.component_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        for (self.node_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        allocator.free(self.component_slots);
        allocator.free(self.node_slots);
        self.components.deinit(allocator);
        allocator.destroy(self);
    }
};

/// The reader over a module's bodies that its dispatch source describes.
fn dispatchSourceBodies(source: DispatchSource) CheckedBodies {
    var types_view = source.types.store.view();
    types_view.names = source.names;
    return .{
        .env = source.env,
        .names = source.names,
        .types = types_view,
        .analyses = source.body_analyses,
        .tables = .{
            .module = source.key.digest(),
            .plans = source.plans,
            .refs = source.refs,
            .roots = source.compile_time_roots,
            .dispatch = .{ .source = source },
        },
    };
}

/// The module's demand call graph: the slots of its templates and their
/// components.
pub fn computeTemplateDemandGraph(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*TemplateDemandGraph {
    const count = dispatch.source.templates.templates.items.len;
    const node_slots = try allocator.alloc(TemplateDemandNodeSlot, count);
    errdefer allocator.free(node_slots);
    @memset(node_slots, .empty);
    const component_slots = try allocator.alloc(TemplateDemandComponentSlot, count);
    errdefer allocator.free(component_slots);
    @memset(component_slots, .empty);
    var components = try LazyComponents.init(allocator, count);
    errdefer components.deinit(allocator);
    const result = try allocator.create(TemplateDemandGraph);
    result.* = .{ .node_slots = node_slots, .components = components, .component_slots = component_slots };
    return result;
}

/// Template `template`'s body walked into its own demand vector and the
/// edges to the templates it calls.
pub fn computeTemplateDemandNode(allocator: Allocator, dispatch: CheckedDispatch, template: u32) Allocator.Error!*TemplateDemandNode {
    const source = dispatch.source;
    // The resolver the reach walk finds declaring modules through reads
    // `import_views`, which outlives the walk.
    const import_views = try dispatchImportViews(dispatch);
    var pass = TemplateDemandWalk{
        .allocator = allocator,
        .module_key = source.key,
        .checked_types = source.types.store,
        .bodies = dispatchSourceBodies(source),
        .templates = source.templates,
        .resolved_value_refs = source.refs,
        .top_level_procedure_bindings = source.top_level_procedure_bindings,
        .static_dispatch_plans = source.plans,
        .dispatch = dispatch,
        .current_slots = collections.DenseMap(CheckedTypeId, u32).init(allocator),
        .mentions = .{
            .allocator = allocator,
            .checked_types = source.types.store,
            .memo = collections.DenseMap(CheckedTypeId, store_serialize.Span).init(allocator),
            .found = collections.DenseMap(CheckedTypeId, TypeVarMentionFlags).init(allocator),
            .reach = .{
                .allocator = allocator,
                .modules = try WalkModules.init(allocator, source.key.digest(), source.types.store.view(), import_views.resolver()),
            },
        },
    };
    defer pass.deinit();
    return pass.walkTemplate(template);
}

/// The demand vectors of the templates of component `component` of
/// `graph`: their own vectors raised along their edges to a fixed point.
/// Every callee component and every imported callee's vector is done
/// before the component is claimed (`ModuleAnalyses.templateDemandComponent`).
pub fn computeTemplateDemandComponent(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    graph: *const TemplateDemandGraph,
    component: u32,
) Allocator.Error!*TemplateDemandComponent {
    const info = graph.components.info(component);
    const members = info.members;
    const starts = try allocator.alloc(u32, members.len + 1);
    errdefer allocator.free(starts);
    starts[0] = 0;
    for (members, 0..) |template, index| starts[index + 1] = starts[index] + @as(u32, @intCast(graph.finishedNode(template).base.len));
    const demands = try allocator.alloc(SchemeVarDemand, starts[members.len]);
    errdefer allocator.free(demands);
    for (members, 0..) |template, index| @memcpy(demands[starts[index]..starts[index + 1]], graph.finishedNode(template).base);

    // The edges between members, grouped by callee, so a changed member
    // revisits only its callers.
    const by_callee_starts = try allocator.alloc(u32, members.len + 1);
    defer allocator.free(by_callee_starts);
    @memset(by_callee_starts, 0);
    for (members) |template| for (graph.finishedNode(template).edges) |edge| switch (edge.callee) {
        .local => |callee| if (graph.components.leaderOf(callee) == component) {
            by_callee_starts[info.memberIndex(callee) + 1] += 1;
        },
        .imported => {},
    };
    for (1..by_callee_starts.len) |index| by_callee_starts[index] += by_callee_starts[index - 1];
    const InnerEdge = struct { caller: u32, edge: TemplateDemandEdge };
    const by_callee = try allocator.alloc(InnerEdge, by_callee_starts[members.len]);
    defer allocator.free(by_callee);
    const cursor = try allocator.dupe(u32, by_callee_starts[0..members.len]);
    defer allocator.free(cursor);

    // Edges to templates outside the component read final vectors; raise
    // along them once.
    for (members, 0..) |template, index| {
        const vector = demands[starts[index]..starts[index + 1]];
        for (graph.finishedNode(template).edges) |edge| {
            const callee_demand = switch (edge.callee) {
                .local => |callee| blk: {
                    const callee_component = graph.components.leaderOf(callee) orelse
                        checkedModuleInvariant("a demand component was computed before its callee was assigned", .{});
                    if (callee_component == component) {
                        const member = info.memberIndex(callee);
                        by_callee[cursor[member]] = .{ .caller = @intCast(index), .edge = edge };
                        cursor[member] += 1;
                        continue;
                    }
                    const done = graph.component_slots[callee_component].peek() orelse
                        checkedModuleInvariant("a demand component was computed before its callee component", .{});
                    break :blk done.member(graph.components.info(callee_component).memberIndex(callee))[edge.callee_slot];
                },
                .imported => |callee| (try importedTemplateDemands(dispatch, callee))[edge.callee_slot],
            };
            vector[edge.caller_slot] = maxSchemeVarDemand(vector[edge.caller_slot], callee_demand);
        }
    }

    // Edges between members, to a fixed point. Demands only rise and each
    // has three values, so every caller slot changes at most twice.
    var queued = try std.DynamicBitSetUnmanaged.initFull(allocator, members.len);
    defer queued.deinit(allocator);
    var pending: std.ArrayList(u32) = .empty;
    defer pending.deinit(allocator);
    try pending.ensureTotalCapacity(allocator, members.len);
    for (0..members.len) |index| pending.appendAssumeCapacity(@intCast(members.len - 1 - index));
    while (pending.pop()) |callee| {
        queued.unset(callee);
        for (by_callee[by_callee_starts[callee]..by_callee_starts[callee + 1]]) |inner| {
            const demand = demands[starts[callee] + inner.edge.callee_slot];
            const caller_demand = &demands[starts[inner.caller] + inner.edge.caller_slot];
            const raised = maxSchemeVarDemand(caller_demand.*, demand);
            if (raised == caller_demand.*) continue;
            caller_demand.* = raised;
            if (!queued.isSet(inner.caller)) {
                queued.set(inner.caller);
                try pending.append(allocator, inner.caller);
            }
        }
    }

    const result = try allocator.create(TemplateDemandComponent);
    result.* = .{ .starts = starts, .demands = demands };
    return result;
}

/// The demand vector of a template of a module dispatch resolution reads.
pub fn importedTemplateDemands(dispatch: CheckedDispatch, callee: canonical.ProcedureTemplateRef) Allocator.Error![]const SchemeVarDemand {
    const view = (try dispatch.importedView(callee.module)) orelse
        checkedModuleInvariant("a demand edge named a module dispatch resolution does not read", .{});
    return (try view.dispatch()).templateDemands(callee.template);
}

/// Walks every local procedure template's body into its own demand vector
/// (for each quantified variable of its scheme, the most its body asks of
/// the type a specialization substitutes for it; design.md "Specialization
/// By Demand") and the edges to the templates it calls
/// (`TemplateDemandGraph`).
const TemplateDemandWalk = struct {
    allocator: Allocator,
    module_key: CheckedModuleKey,
    checked_types: *const CheckedTypeStore,
    bodies: CheckedBodies,
    templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    dispatch: CheckedDispatch,

    mentions: TypeVarMentions,
    /// The walked template's own vector.
    demands: std.ArrayList(SchemeVarDemand) = .empty,
    edges: std.ArrayList(TemplateDemandEdge) = .empty,
    work: std.ArrayList(Work) = .empty,
    imported_templates: std.AutoHashMapUnmanaged(ImportedDefKey, ?canonical.ProcedureTemplateRef) = .empty,

    /// Every step a raise has walked in the current template, at the demand
    /// it raised. A raise's effect is a function of its step and demand, and
    /// demands only rise, so a step walked once at a demand never needs
    /// walking again at that demand within the template.
    raised: std.AutoHashMapUnmanaged(RaiseStep, void) = .empty,
    raise_pending: std.ArrayList(RaiseStep) = .empty,

    // The template being walked.
    current: canonical.CheckedProcedureTemplateId = undefined,
    current_vars: []const CheckedTypeId = &.{},
    /// Each quantified variable's slot in `current_vars`.
    current_slots: collections.DenseMap(CheckedTypeId, u32),
    current_demands: []SchemeVarDemand = &.{},

    const ImportedDefKey = struct {
        module: ModuleId,
        def: CIR.Def.Idx,
    };

    /// One step of a raise walk: a type reached along a path with `flags`,
    /// raising the variables it mentions to `demand` (and exact mentions to
    /// `full`).
    const RaiseStep = struct {
        step: TypeVarMentions.Step,
        demand: SchemeVarDemand,
    };

    /// The sink `TypeVarMentions.expandStep` drives during a raise walk.
    const RaiseSink = struct {
        pass: *TemplateDemandWalk,
        demand: SchemeVarDemand,

        pub fn push(sink: RaiseSink, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            try sink.pass.pushRaise(.{ .step = .{ .ty = ty, .flags = flags }, .demand = sink.demand });
        }

        pub fn noteMention(sink: RaiseSink, var_ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            const slot = sink.pass.slotOf(var_ty) orelse return;
            sink.pass.raiseSlot(slot, if (exactMention(flags)) .full else sink.demand);
        }

        pub fn nominalReach(sink: RaiseSink, nominal: CheckedNominalType) Allocator.Error!?[]const FormalReach {
            return sink.pass.mentions.reach.get(0, nominal);
        }
    };

    /// Where an expression stands relative to the operation that consumes it.
    const ExprRole = enum {
        /// Its value is materialized: held in a local, stored, returned, or
        /// matched on.
        value,
        /// A direct operand of a procedure call or a low-level operation. The
        /// callee's or operation's demand covers the operand, so reading a
        /// local into this position materializes nothing.
        operand,
        /// The callee of a direct template call. The call's edges cover it.
        direct_callee,
    };

    const PatternRole = enum {
        /// A parameter of the template's own lambda. The value already exists
        /// in the caller; binding it materializes nothing.
        parameter,
        binding,
    };

    const Work = union(enum) {
        expr: struct { id: CIR.Expr.Idx, role: ExprRole },
        pattern: struct { id: CIR.Pattern.Idx, role: PatternRole },
        statement: CIR.Statement.Idx,
    };

    fn deinit(self: *TemplateDemandWalk) void {
        self.mentions.deinit();
        self.current_slots.deinit();
        self.raised.deinit(self.allocator);
        self.raise_pending.deinit(self.allocator);
        self.demands.deinit(self.allocator);
        self.edges.deinit(self.allocator);
        self.work.deinit(self.allocator);
        self.imported_templates.deinit(self.allocator);
    }

    fn walkTemplate(self: *TemplateDemandWalk, raw: u32) Allocator.Error!*TemplateDemandNode {
        const allocator = self.allocator;
        self.current = @fromBackingInt(raw);
        self.current_vars = try self.dispatch.templateSchemeVars(self.current);
        for (self.current_vars, 0..) |var_ty, slot| try self.current_slots.put(var_ty, @intCast(slot));
        try self.demands.appendNTimes(allocator, .none, self.current_vars.len);
        self.current_demands = self.demands.items;
        try self.analyzeTemplate(&self.templates.templates.items[raw]);

        var callees: std.ArrayList(u32) = .empty;
        defer callees.deinit(allocator);
        var seen_callees = std.AutoHashMapUnmanaged(u32, void).empty;
        defer seen_callees.deinit(allocator);
        for (self.edges.items) |edge| switch (edge.callee) {
            .local => |callee| if (!(try seen_callees.getOrPut(allocator, callee)).found_existing) try callees.append(allocator, callee),
            .imported => {},
        };
        const own = try self.demands.toOwnedSlice(allocator);
        errdefer allocator.free(own);
        const edges = try self.edges.toOwnedSlice(allocator);
        errdefer allocator.free(edges);
        const owned_callees = try callees.toOwnedSlice(allocator);
        errdefer allocator.free(owned_callees);
        const result = try allocator.create(TemplateDemandNode);
        result.* = .{ .base = own, .edges = edges, .callees = owned_callees };
        return result;
    }

    fn analyzeTemplate(self: *TemplateDemandWalk, template: *const CheckedProcedureTemplate) Allocator.Error!void {
        if (self.current_vars.len == 0) return;
        const root_expr = switch (template.body) {
            .checked_body => |root| root,
            // An intrinsic inspects its operands, an entry wrapper marshals
            // them to the host, and an unimplemented declaration's crash
            // body still returns at its declared type.
            .intrinsic_wrapper, .entry_wrapper, .literal_root, .unimplemented => return self.raiseEverything(),
        };
        if (template.target != .roc) return self.raiseEverything();

        // A dispatch requirement inspects its dispatcher's type.
        for (try self.dispatch.evidenceParams(self.current)) |param| {
            try self.raiseMentions(param.dispatcher_ty, .full);
            try self.raiseMentions(param.callable_ty, .full);
        }
        for (self.current_vars, self.current_demands) |var_ty, *demand| {
            switch (self.checked_types.payload(var_ty)) {
                .flex, .rigid => |variable| {
                    if (variable.constraints.len() != 0 or variable.numeric_default_phase != null) demand.* = .full;
                },
                .pending, .field_kind, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => demand.* = .full,
            }
        }

        // A specialization substitutes each variable through the root type,
        // so a variable it never mentions is fixed only by evidence, and a row
        // extension's substitution is a row rather than a type of its own.
        // Function types carry program-specific lambda sets. A variable that
        // a parameter holds by value, rather than as a list or box element,
        // sizes the parameter itself.
        const root_fn = self.rootFunction(template.checked_fn_root) orelse return self.raiseEverything();
        const root_flags = try self.allocator.alloc(?TypeVarMentionFlags, self.current_vars.len);
        defer self.allocator.free(root_flags);
        @memset(root_flags, null);
        for (root_fn.args) |arg| try self.noteRootMentions(root_flags, arg);
        try self.noteRootMentions(root_flags, root_fn.ret);
        for (root_flags, self.current_demands) |maybe_flags, *demand| {
            const flags = maybe_flags orelse {
                demand.* = .full;
                continue;
            };
            if (flags.row_extension or flags.under_function or flags.decides_representation) {
                demand.* = .full;
            } else if (flags.outside_container) {
                demand.* = maxSchemeVarDemand(demand.*, .layout);
            }
        }

        // Walking the body only raises demands, and the edges it records only
        // raise this template's demands, so a template that already demands
        // all of every variable has nothing left to learn from its body.
        for (self.current_demands) |demand| {
            if (demand != .full) break;
        } else return;

        const root = self.bodies.exprData(root_expr);
        if (root != .lambda) return self.raiseEverything();
        const lambda = root.lambda;
        self.work.clearRetainingCapacity();
        try self.work.append(self.allocator, .{ .expr = .{ .id = lambda.body, .role = .value } });
        for (lambda.args) |arg| try self.work.append(self.allocator, .{ .pattern = .{ .id = arg, .role = .parameter } });
        while (self.work.pop()) |item| switch (item) {
            .expr => |expr| try self.visitExpr(expr.id, expr.role),
            .pattern => |pattern| try self.visitPattern(pattern.id, pattern.role),
            .statement => |statement| try self.visitStatement(statement),
        };
    }

    /// The function type a template's root names, through aliases.
    fn rootFunction(self: *const TemplateDemandWalk, root: CheckedTypeId) ?CheckedFunctionType {
        var current = root;
        var remaining = self.checked_types.typeCount();
        while (remaining != 0) : (remaining -= 1) {
            switch (self.checked_types.payload(current)) {
                .alias => |alias| current = alias.backing,
                .function => |function| return function,
                .pending, .field_kind, .err, .flex, .rigid, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
        checkedModuleInvariant("procedure template root alias chain was cyclic", .{});
    }

    fn noteRootMentions(self: *TemplateDemandWalk, flags: []?TypeVarMentionFlags, ty: CheckedTypeId) Allocator.Error!void {
        for (try self.mentions.of(ty)) |mention| {
            const slot = self.slotOf(mention.var_ty) orelse continue;
            flags[slot] = if (flags[slot]) |existing| existing.merge(mention.flags) else mention.flags;
        }
    }

    fn slotOf(self: *const TemplateDemandWalk, var_ty: CheckedTypeId) ?usize {
        return if (self.current_slots.get(var_ty)) |slot| slot else null;
    }

    fn raiseSlot(self: *TemplateDemandWalk, slot: usize, demand: SchemeVarDemand) void {
        self.current_demands[slot] = maxSchemeVarDemand(self.current_demands[slot], demand);
    }

    fn raiseEverything(self: *TemplateDemandWalk) void {
        @memset(self.current_demands, .full);
    }

    /// Raise every quantified variable `ty` mentions to `demand`, and every one
    /// whose exact type it needs (see `exactMention`) to `full`. The walk
    /// skips every step an earlier raise in this template already walked at
    /// this demand, so the raises of one template cost the size of the types
    /// they reach, however many of its expressions share those types.
    fn raiseMentions(self: *TemplateDemandWalk, ty: CheckedTypeId, demand: SchemeVarDemand) Allocator.Error!void {
        try self.pushRaise(.{ .step = .{ .ty = ty, .flags = .{ .outside_container = true } }, .demand = demand });
        const sink: RaiseSink = .{ .pass = self, .demand = demand };
        while (self.raise_pending.pop()) |raise| try TypeVarMentions.expandStep(self.checked_types, raise.step, sink);
    }

    fn pushRaise(self: *TemplateDemandWalk, raise: RaiseStep) Allocator.Error!void {
        const entry = try self.raised.getOrPut(self.allocator, raise);
        if (entry.found_existing) return;
        try self.raise_pending.append(self.allocator, raise);
    }

    /// Whether a type needs the exact type of a variable it mentions this
    /// way: lambda-set solving needs the exact type of every function, and a
    /// representation-deciding builtin argument decides more than a layout.
    fn exactMention(flags: TypeVarMentionFlags) bool {
        return flags.under_function or flags.decides_representation;
    }

    /// Raise every quantified variable whose exact type `ty` needs to `full`:
    /// a raise to `none` leaves every other mention as it is.
    fn raiseFunctionMentions(self: *TemplateDemandWalk, ty: CheckedTypeId) Allocator.Error!void {
        try self.raiseMentions(ty, .none);
    }

    fn pushExpr(self: *TemplateDemandWalk, id: CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .expr = .{ .id = id, .role = role } });
    }

    fn pushExprs(self: *TemplateDemandWalk, ids: []const CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        for (ids) |id| try self.pushExpr(id, role);
    }

    fn pushPattern(self: *TemplateDemandWalk, id: CIR.Pattern.Idx, role: PatternRole) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .pattern = .{ .id = id, .role = role } });
    }

    fn visitExpr(self: *TemplateDemandWalk, id: CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.exprData(id);
        const ty = try bodies.exprType(id);
        // A row-coerced value reaches its parent through its coercion: the
        // parent's role demands the widened type, and the coercion holds the
        // expression's own value.
        const own_role = if (try bodies.rowCoercion(id)) |wide| blk: {
            switch (role) {
                .direct_callee => {},
                .operand, .value => try self.raiseMentions(wide, .layout),
            }
            break :blk ExprRole.value;
        } else role;
        switch (own_role) {
            .direct_callee => {},
            .operand => if (data == .lookup_local)
                try self.raiseFunctionMentions(ty)
            else
                try self.raiseMentions(ty, .layout),
            .value => try self.raiseMentions(ty, .layout),
        }
        switch (data) {
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .crash,
            .break_,
            => {},
            .ellipsis, .anno_only, .hosted_lambda => self.raiseEverything(),
            .numeral => {
                try self.raiseMentions(ty, .full);
                if (bodies.numeralPlan(@backingInt(id))) |plan| try self.visitInspectingPlan(plan);
            },
            .str => |segments| if (bodies.quoteIsCustom(@backingInt(id))) {
                try self.raiseMentions(ty, .full);
                if (bodies.quotePlan(@backingInt(id))) |plan| try self.visitInspectingPlan(plan);
            } else {
                try self.pushExprs(segments, .value);
            },
            .list, .tuple => |items| try self.pushExprs(items, .value),
            .match_ => |match| {
                try self.pushExpr(match.cond, .value);
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushPattern(bodies.matchBranchPattern(branch_pattern).pattern, .binding);
                    if (branch.guard) |guard| try self.pushExpr(guard, .value);
                    try self.pushExpr(branch.value, .value);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushExpr(branch.cond, .value);
                    try self.pushExpr(branch.body, .value);
                }
                try self.pushExpr(if_.final_else, .value);
            },
            .call => |call| try self.visitCall(id, call),
            .record => |record| {
                if (record.ext) |ext| try self.pushExpr(ext, .value);
                for (record.fields) |field| try self.pushExpr(bodies.recordFieldValue(field), .value);
            },
            .block => |block| {
                for (block.statements) |statement| try self.work.append(self.allocator, .{ .statement = statement });
                try self.pushExpr(block.final_expr, .value);
            },
            .tag => |tag| try self.pushExprs(tag.args, .value),
            .nominal => |nominal| try self.pushExpr(nominal.backing_expr, .value),
            .closure => |closure| {
                // A closure's lambda set is program-specific, and so is the
                // layout of what it captures.
                try self.raiseMentions(ty, .full);
                for (closure.captures) |capture| {
                    try self.raiseMentions(try bodies.patternType(bodies.capture(capture).pattern), .full);
                }
                try self.pushExpr(closure.lambda, .value);
            },
            .lambda => |lambda| {
                try self.raiseMentions(ty, .full);
                for (lambda.args) |arg| try self.pushPattern(arg, .binding);
                try self.pushExpr(lambda.body, .value);
            },
            .binop => |binop| {
                try self.raiseMentions(try bodies.valueType(binop.lhs), .full);
                try self.raiseMentions(try bodies.valueType(binop.rhs), .full);
                try self.pushExpr(binop.lhs, .value);
                try self.pushExpr(binop.rhs, .value);
            },
            .unary_minus => |operand| {
                try self.raiseMentions(try bodies.valueType(operand), .full);
                try self.pushExpr(operand, .value);
            },
            .field_access => |field| try self.pushExpr(field.receiver, .value),
            .tuple_access => |access| try self.pushExpr(access.tuple, .value),
            .dispatch_call, .type_dispatch_call => {
                const plan = bodies.dispatchPlan(@backingInt(id)) orelse return self.raiseEverything();
                try self.visitDispatchPlan(plan);
            },
            .method_eq => {
                const plan = bodies.dispatchPlan(@backingInt(id)) orelse return self.raiseEverything();
                try self.visitInspectingPlan(plan);
            },
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(id)) {
                try self.pushExpr(interpolation.first, .value);
                try self.pushExprs(interpolation.parts, .value);
            } else {
                var value_index: usize = 0;
                while (value_index < interpolation.valueCount()) : (value_index += 1) {
                    try self.raiseMentions(try bodies.valueType(interpolation.value(value_index)), .full);
                }
                var segment_index: usize = 0;
                while (segment_index < interpolation.segmentCount()) : (segment_index += 1) {
                    try self.pushExpr(interpolation.segment(segment_index), .value);
                }
                value_index = 0;
                while (value_index < interpolation.valueCount()) : (value_index += 1) {
                    try self.pushExpr(interpolation.value(value_index), .value);
                }
            },
            .structural_eq => |eq| {
                try self.raiseMentions(try bodies.valueType(eq.lhs), .full);
                try self.raiseMentions(try bodies.valueType(eq.rhs), .full);
                try self.pushExpr(eq.lhs, .value);
                try self.pushExpr(eq.rhs, .value);
            },
            .structural_hash => |hash| {
                try self.raiseMentions(try bodies.valueType(hash.value), .full);
                try self.pushExpr(hash.value, .value);
                try self.pushExpr(hash.hasher, .value);
            },
            .runtime_error => |runtime_error| try self.pushExprs(runtime_error.evaluated, .value),
            .dbg => |payload| {
                try self.raiseMentions(try bodies.valueType(payload), .full);
                try self.pushExpr(payload, .value);
            },
            .expect_err => |expect_err| {
                try self.raiseMentions(try bodies.valueType(expect_err.expr), .full);
                try self.pushExpr(expect_err.expr, .value);
            },
            .expect => |condition| try self.pushExpr(condition, .value),
            .return_ => |ret| try self.pushExpr(ret.expr, .value),
            .for_ => |for_| try self.visitFor(for_.pattern, for_.expr, for_.body),
            .run_low_level => |run| {
                for (run.args, 0..) |arg, index| {
                    try self.raiseMentions(try bodies.valueType(arg), run.op.elementDemand(index));
                    try self.pushExpr(arg, .operand);
                }
            },
        }
    }

    fn visitFor(self: *TemplateDemandWalk, pattern: CIR.Pattern.Idx, iterable: CIR.Expr.Idx, body: CIR.Expr.Idx) Allocator.Error!void {
        // Iteration dispatches on the iterable's type.
        try self.raiseMentions(try self.bodies.valueType(iterable), .full);
        try self.raiseMentions(try self.bodies.patternType(pattern), .full);
        try self.pushPattern(pattern, .binding);
        try self.pushExpr(iterable, .value);
        try self.pushExpr(body, .value);
    }

    fn visitStatement(self: *TemplateDemandWalk, id: CIR.Statement.Idx) Allocator.Error!void {
        switch (self.bodies.statementData(id)) {
            .decl => |decl| {
                try self.pushPattern(decl.pattern, .binding);
                try self.pushExpr(decl.expr, .value);
            },
            .var_ => |var_| {
                try self.pushPattern(var_.pattern, .binding);
                try self.pushExpr(var_.expr, .value);
            },
            .reassign => |reassign| {
                try self.pushPattern(reassign.pattern, .binding);
                try self.pushExpr(reassign.expr, .value);
            },
            // The promoted procedure is a template of its own; its binding's
            // function type is all this body sees of it.
            .promoted_proc => |promoted| try self.pushPattern(promoted.pattern, .binding),
            .var_uninitialized => |var_| try self.pushPattern(var_.pattern, .binding),
            .dbg => |payload| {
                try self.raiseMentions(try self.bodies.valueType(payload), .full);
                try self.pushExpr(payload, .value);
            },
            .expr, .expect => |expr| try self.pushExpr(expr, .value),
            .for_ => |for_| try self.visitFor(for_.pattern, for_.expr, for_.body),
            .while_, .infinite_loop, .breakable_loop => |loop| {
                try self.pushExpr(loop.cond, .value);
                try self.pushExpr(loop.body, .value);
            },
            .return_ => |ret| try self.pushExpr(ret.expr, .value),
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }

    fn visitPattern(self: *TemplateDemandWalk, id: CIR.Pattern.Idx, role: PatternRole) Allocator.Error!void {
        const bodies = self.bodies;
        const pattern_ty = try bodies.patternType(id);
        switch (bodies.patternData(id)) {
            .assign, .underscore => switch (role) {
                .parameter => try self.raiseFunctionMentions(pattern_ty),
                .binding => try self.raiseMentions(pattern_ty, .layout),
            },
            .as => |as| {
                try self.raiseMentions(pattern_ty, .layout);
                try self.pushPattern(as.pattern, .binding);
            },
            .applied_tag => |tag| {
                try self.raiseMentions(pattern_ty, .layout);
                for (tag.args) |arg| try self.pushPattern(arg, .binding);
            },
            .nominal => |nominal| {
                try self.raiseMentions(pattern_ty, .layout);
                try self.pushPattern(nominal.backing_pattern, .binding);
            },
            .record_destructure => |destructs| {
                try self.raiseMentions(pattern_ty, .layout);
                for (destructs) |destruct| try self.pushPattern(bodies.recordDestructPattern(destruct), .binding);
            },
            .list => |list| {
                try self.raiseMentions(pattern_ty, .layout);
                for (list.patterns) |child| try self.pushPattern(child, .binding);
                if (list.rest) |rest| if (rest.pattern) |child| try self.pushPattern(child, .binding);
            },
            .tuple => |items| {
                try self.raiseMentions(pattern_ty, .layout);
                for (items) |child| try self.pushPattern(child, .binding);
            },
            .numeral_literal, .str_literal => {
                try self.raiseMentions(pattern_ty, .full);
                if (try bodies.literalPatternGuard(id)) |guard| try self.visitLiteralPatternGuard(guard);
            },
            .str_interpolation => |str| {
                try self.raiseMentions(pattern_ty, .full);
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushPattern(capture, .binding);
                }
            },
            .runtime_error => {},
        }
    }

    /// A custom literal pattern compares the matched value with its literal
    /// converted at the pattern's type: both inspect their dispatchers.
    fn visitLiteralPatternGuard(self: *TemplateDemandWalk, guard: checked_bodies_mod.LiteralPatternGuard) Allocator.Error!void {
        try self.raiseMentions(guard.equality_ty, .layout);
        try self.visitInspectingPlan(guard.equality_plan orelse return self.raiseEverything());
        if (guard.conversion.plan) |plan| try self.visitInspectingPlan(plan);
    }

    fn visitCall(self: *TemplateDemandWalk, call_expr: CIR.Expr.Idx, call: anytype) Allocator.Error!void {
        if (self.bodies.callDirectTarget(call_expr)) |target| {
            if (try self.directCallTemplate(target)) |callee| {
                if (try self.dispatch.siteSubstitution(call.func)) |subst| {
                    if (try self.relateCall(callee, subst)) {
                        try self.pushExpr(call.func, .direct_callee);
                        try self.pushExprs(call.args, .operand);
                        return;
                    }
                }
            }
        }
        // Any other callee is a function value whose lambda set the program
        // decides; its type mentions every variable its operands do.
        try self.raiseMentions(try self.bodies.valueType(call.func), .full);
        try self.pushExpr(call.func, .value);
        try self.pushExprs(call.args, .operand);
    }

    /// A dispatch whose checked resolution selected one procedure template
    /// behaves like a direct call to it; any other dispatch inspects its
    /// dispatcher.
    fn visitDispatchPlan(self: *TemplateDemandWalk, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        const plan = try self.dispatch.plan(plan_id);
        if (try self.dispatchTemplate(plan)) |selected| {
            if (try self.relateCall(selected.template, selected.subst)) {
                try self.pushPlanOperands(plan, .operand);
                return;
            }
        }
        try self.raiseMentions(plan.dispatcher_ty, .full);
        try self.raiseMentions(plan.callable_ty, .full);
        try self.pushPlanOperands(plan, .operand);
    }

    fn visitInspectingPlan(self: *TemplateDemandWalk, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        const plan = try self.dispatch.plan(plan_id);
        try self.raiseMentions(plan.dispatcher_ty, .full);
        try self.raiseMentions(plan.callable_ty, .full);
        try self.pushPlanOperands(plan, .value);
    }

    fn pushPlanOperands(self: *TemplateDemandWalk, plan: static_dispatch.StaticDispatchCallPlan, role: ExprRole) Allocator.Error!void {
        for (plan.argsSlice(self.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| try self.pushExpr(expr, role),
            .generated_interpolation_segments => |expr| try self.pushExpr(expr, .value),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
    }

    const SelectedTemplate = struct {
        template: canonical.ProcedureTemplateRef,
        subst: []const CheckedTypeId,
    };

    fn dispatchTemplate(self: *TemplateDemandWalk, plan: static_dispatch.StaticDispatchCallPlan) Allocator.Error!?SelectedTemplate {
        const direct = switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| direct,
            .direct_pending, .evidence_dependent, .structural, .checked_error, .@"unreachable" => return null,
        };
        const node = (try self.dispatch.evidenceNode(direct.evidence));
        if (node.target.alias != null) return null;
        const procedure = switch (node.target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => return null,
        };
        switch (procedure.runtime_target) {
            .procedure, .low_level => {},
            .intrinsic, .graph_participating => return null,
        }
        return .{
            .template = procedure.template,
            .subst = (try self.dispatch.substitution(node.subst)),
        };
    }

    /// The checked template a direct call's target names, when it names one.
    fn directCallTemplate(self: *TemplateDemandWalk, target: ResolvedValueRefId) Allocator.Error!?canonical.ProcedureTemplateRef {
        const procedure = switch (self.resolved_value_refs.records[@backingInt(target)].ref) {
            .top_level_proc, .imported_proc, .promoted_top_level_proc => |procedure| procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            => return null,
        };
        if (procedure.intrinsic != null) return null;
        const body = switch (procedure.binding) {
            .top_level => |binding| blk: {
                if (!binding.module.eql(self.module_key.digest())) return null;
                break :blk self.top_level_procedure_bindings.get(binding.binding).body;
            },
            .imported => |imported| return try self.importedTemplate(imported),
            .hosted, .platform_required => return null,
        };
        return directProcedureBindingTemplate(body);
    }

    fn importedTemplate(self: *TemplateDemandWalk, imported: ImportedProcedureBindingRef) Allocator.Error!?canonical.ProcedureTemplateRef {
        const key: ImportedDefKey = .{ .module = imported.module, .def = imported.def };
        if (self.imported_templates.get(key)) |cached| return cached;
        const view = (try self.dispatch.importedView(imported.module)) orelse return null;
        const template = if (try importedProcedureBindingForDef(view, imported.def)) |binding|
            directProcedureBindingTemplate(binding.body)
        else
            null;
        try self.imported_templates.put(self.allocator, key, template);
        return template;
    }

    fn directProcedureBindingTemplate(body: ProcedureBindingBody) ?canonical.ProcedureTemplateRef {
        return switch (body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| template,
                .lifted, .synthetic => null,
            },
            .callable_eval_template, .checked_error => null,
        };
    }

    /// Relate a call to `callee` under `subst` (one caller type per callee
    /// quantified variable): every caller variable a slot's type mentions is
    /// demanded at least as much as the callee demands that slot, and fully
    /// where the slot needs the variable's exact type. False when the callee
    /// is not a template this module reads.
    fn relateCall(self: *TemplateDemandWalk, callee: canonical.ProcedureTemplateRef, subst: []const CheckedTypeId) Allocator.Error!bool {
        const local = callee.module.eql(self.module_key.digest());
        const callee_vars = if (local)
            try self.dispatch.templateSchemeVars(callee.template)
        else blk: {
            const view = (try self.dispatch.importedView(callee.module)) orelse return false;
            break :blk try (try view.dispatch()).templateSchemeVars(callee.template);
        };
        if (subst.len != callee_vars.len) return false;
        for (subst, 0..) |slot_ty, callee_slot| {
            for (try self.mentions.of(slot_ty)) |mention| {
                const caller_slot = self.slotOf(mention.var_ty) orelse continue;
                if (exactMention(mention.flags)) {
                    self.raiseSlot(caller_slot, .full);
                    continue;
                }
                try self.edges.append(self.allocator, .{
                    .caller_slot = @intCast(caller_slot),
                    .callee = if (local) .{ .local = callee.template.index() } else .{ .imported = callee },
                    .callee_slot = @intCast(callee_slot),
                });
            }
        }
        return true;
    }
};

fn deinitCompileTimeRootSlice(allocator: Allocator, roots: []CompileTimeRoot) void {
    for (roots) |*root| {
        if (root.hoisted_body) |body| {
            hoist_roots.deinitBody(allocator, body);
            root.hoisted_body = null;
        }
    }
}

fn verifyCompileTimeRootPayloadMatchesKind(root: CompileTimeRoot, payload: CompileTimeRootPayload) void {
    const matches = switch (root.kind) {
        .constant, .hoisted_constant => switch (payload) {
            .const_node, .unevaluated => true,
            .runtime => root.guarded,
            .pending, .fn_value, .discarded, .expect => false,
        },
        // A REPL expression is the compilation's only demand.
        .repl_expr => switch (payload) {
            .const_node => true,
            .runtime => root.guarded,
            .pending, .unevaluated, .fn_value, .discarded, .expect => false,
        },
        .hoisted_validation => switch (payload) {
            .discarded, .unevaluated => true,
            .runtime => root.guarded,
            .pending, .const_node, .fn_value, .expect => false,
        },
        .callable_binding => switch (payload) {
            // A callable initializer that reaches an explicit checked error is
            // stored as a divergent ConstStore node. Monotype restores that
            // node at the callable's expected type, so execution crashes at
            // the exact invalid binding while independent roots remain usable.
            .fn_value, .const_node, .unevaluated => true,
            .pending, .discarded, .expect, .runtime => false,
        },
        .expect => switch (payload) {
            .expect => true,
            .pending, .unevaluated, .const_node, .fn_value, .discarded, .runtime => false,
        },
        .numeral_conversion, .quote_conversion => switch (payload) {
            .const_node, .unevaluated => true,
            .pending, .fn_value, .discarded, .expect, .runtime => false,
        },
        // A literal argument holding a function value (an interpolation's
        // assembler) is stored as one.
        .literal_argument => switch (payload) {
            .const_node, .fn_value, .unevaluated => true,
            .pending, .discarded, .expect, .runtime => false,
        },
    };
    if (matches) return;
    checkedModuleInvariant("compile-time root payload does not match root kind", .{});
}

fn compileTimeRootHasConstBody(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant, .hoisted_constant => true,
        .hoisted_validation, .callable_binding, .expect, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => false,
    };
}

/// The local procedure templates a module's root requests reach at runtime,
/// at compile time, and at compile time only through a further pairing.
const ExhaustivenessTemplateReachability = struct {
    allocator: Allocator,
    module_key: CheckedModuleKey,
    procedure_templates: *const CheckedProcedureTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    runtime_templates: []bool,
    compile_time_templates: []bool,
    pairing_templates: []bool,
    /// Templates marked reachable whose own refs are not yet marked.
    pending_templates: std.ArrayListUnmanaged(PendingTemplate) = .empty,

    const PendingTemplate = struct { kind: ReachabilityKind, idx: usize };

    fn init(
        allocator: Allocator,
        module_key: CheckedModuleKey,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        const runtime_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        errdefer allocator.free(runtime_templates);
        const compile_time_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        errdefer allocator.free(compile_time_templates);
        const pairing_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        @memset(pairing_templates, false);
        @memset(runtime_templates, false);
        @memset(compile_time_templates, false);
        return .{
            .allocator = allocator,
            .module_key = module_key,
            .procedure_templates = procedure_templates,
            .entry_wrappers = entry_wrappers,
            .callable_eval_templates = callable_eval_templates,
            .top_level_procedure_bindings = top_level_procedure_bindings,
            .platform_required_bindings = platform_required_bindings,
            .resolved_value_refs = resolved_value_refs,
            .runtime_templates = runtime_templates,
            .compile_time_templates = compile_time_templates,
            .pairing_templates = pairing_templates,
        };
    }

    fn deinit(self: *ExhaustivenessTemplateReachability) void {
        self.pending_templates.deinit(self.allocator);
        self.allocator.free(self.pairing_templates);
        self.allocator.free(self.compile_time_templates);
        self.allocator.free(self.runtime_templates);
        self.* = undefined;
    }

    fn build(
        allocator: Allocator,
        module_key: CheckedModuleKey,
        root_requests: *const RootRequestTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        var reachability = try ExhaustivenessTemplateReachability.init(
            allocator,
            module_key,
            procedure_templates,
            entry_wrappers,
            callable_eval_templates,
            top_level_procedure_bindings,
            platform_required_bindings,
            resolved_value_refs,
        );
        errdefer reachability.deinit();

        for (root_requests.requests) |request| {
            try reachability.markRootRequest(if (request.abi == .compile_time) .compile_time else .runtime, request);
            if (request.abi == .compile_time and request.requires_pairing) try reachability.markRootRequest(.pairing, request);
        }

        return reachability;
    }

    fn templateIsRuntimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.runtime_templates[idx];
    }

    fn templateIsCompileTimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.compile_time_templates[idx];
    }

    const ReachabilityKind = enum {
        runtime,
        compile_time,
        pairing,
    };

    fn markRootRequest(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        request: RootRequest,
    ) Allocator.Error!void {
        switch (request.source) {
            .required_binding => |binding_id| try self.markPlatformRequiredBindingClosure(kind, @fromBackingInt(@intCast(binding_id))),
            .def,
            .expr,
            .statement,
            .hoisted,
            .literal,
            => {},
        }
        if (request.procedure_template) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        if (request.procedure_use) |procedure| {
            try self.markProcedureUse(kind, procedure);
        }
        if (request.procedure_binding) |binding| {
            try self.markTopLevelProcedureBinding(kind, .{
                .module = self.module_key.digest(),
                .binding = binding,
            });
        }
        try self.drainPendingTemplates();
    }

    /// Mark the refs of every template marked reachable, until none is left.
    fn drainPendingTemplates(self: *ExhaustivenessTemplateReachability) Allocator.Error!void {
        while (self.pending_templates.pop()) |pending| {
            const template = self.procedure_templates.templates.items[pending.idx];
            const end = template.resolved_value_refs.start + template.resolved_value_refs.len;
            if (end > self.resolved_value_refs.template_refs.len) {
                checkedModuleInvariant("reachable procedure template resolved-ref span was outside table", .{});
            }
            for (self.resolved_value_refs.template_refs[template.resolved_value_refs.start..end]) |ref_id| {
                const raw = @backingInt(ref_id);
                if (raw >= self.resolved_value_refs.records.len) {
                    checkedModuleInvariant("reachable procedure template resolved-ref id was outside table", .{});
                }
                try self.markResolvedValueRef(pending.kind, self.resolved_value_refs.records[raw].ref);
            }
        }
    }

    fn markProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const idx = self.localTemplateIndex(template_ref) orelse return;
        const seen = switch (kind) {
            .runtime => &self.runtime_templates[idx],
            .compile_time => &self.compile_time_templates[idx],
            .pairing => &self.pairing_templates[idx],
        };
        if (seen.*) return;
        seen.* = true;

        const template = self.procedure_templates.templates.items[idx];
        if (template.proc_base != template_ref.proc_base) {
            checkedModuleInvariant("reachable procedure template ref disagreed with template row", .{});
        }
        // Its refs are marked by `drainPendingTemplates`, so a long call
        // chain never becomes native call depth.
        try self.pending_templates.append(self.allocator, .{ .kind = kind, .idx = idx });
    }

    fn markResolvedValueRef(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        ref: ResolvedValueRef,
    ) Allocator.Error!void {
        switch (ref) {
            .top_level_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| try self.markProcedureUse(kind, procedure),
            .platform_required_proc => |required| {
                try self.markProcedureUse(kind, required.procedure);
                try self.markPlatformRequiredBindingClosure(kind, required.binding);
            },
            .platform_required_const => |required| try self.markPlatformRequiredBindingClosure(kind, required.binding),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .local_proc,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            => {},
        }
    }

    fn markProcedureUse(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        switch (procedure.binding) {
            .top_level => |top_level| try self.markTopLevelProcedureBinding(kind, top_level),
            .hosted => |hosted| try self.markProcedureTemplate(kind, hosted.template),
            .platform_required => |required| try self.markTopLevelProcedureBinding(kind, .{
                .module = required.module,
                .binding = required.procedure_binding,
            }),
            .imported => {},
        }
    }

    fn markTopLevelProcedureBinding(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_ref: ModuleTopLevelProcedureBindingRef,
    ) Allocator.Error!void {
        if (!binding_ref.module.eql(self.module_key.digest())) return;
        const binding = self.top_level_procedure_bindings.get(binding_ref.binding);
        try self.markProcedureBindingBody(kind, binding.body);
    }

    fn markProcedureBindingBody(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        body: ProcedureBindingBody,
    ) Allocator.Error!void {
        switch (body) {
            .direct_template => |direct| try self.markCallableProcedureTemplate(kind, direct.template),
            .checked_error => {},
            .callable_eval_template => |template_id| try self.markCallableEvalTemplate(kind, template_id),
        }
    }

    fn markCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_id: CallableEvalTemplateId,
    ) Allocator.Error!void {
        const raw = @backingInt(template_id);
        if (raw >= self.callable_eval_templates.templates.len) {
            checkedModuleInvariant("reachable callable-eval template id was outside table", .{});
        }
        const template = self.callable_eval_templates.get(template_id);
        try self.markProcedureTemplate(kind, entryWrapperForRoot(self.entry_wrappers, template.root).template);
    }

    fn markPlatformRequiredBindingClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_id: PlatformRequiredBindingId,
    ) Allocator.Error!void {
        const binding = self.platform_required_bindings.lookupByBindingId(@backingInt(binding_id)) orelse {
            checkedModuleInvariant("reachable platform-required binding id was outside table", .{});
        };
        const closure = self.platform_required_bindings.relationClosure(binding);
        try self.markImportedTemplateClosure(kind, closure);
    }

    fn markImportedTemplateClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        for (closure.checked_procedure_templates) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        for (closure.callable_eval_templates) |template_ref| {
            try self.markModuleCallableEvalTemplate(kind, template_ref);
        }
    }

    fn markModuleCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: ModuleCallableEvalTemplateRef,
    ) Allocator.Error!void {
        if (!template_ref.module.eql(self.module_key.digest())) return;
        try self.markCallableEvalTemplate(kind, template_ref.template);
    }

    fn markCallableProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template: canonical.CallableProcedureTemplateRef,
    ) Allocator.Error!void {
        switch (template) {
            .checked => |checked| try self.markProcedureTemplate(kind, checked),
            .synthetic => |synthetic| try self.markProcedureTemplate(kind, synthetic.template),
            .lifted => checkedModuleInvariant("reachable procedure template reached lifted procedure before post-check lowering", .{}),
        }
    }

    fn localTemplateIndex(
        self: *const ExhaustivenessTemplateReachability,
        template_ref: canonical.ProcedureTemplateRef,
    ) ?usize {
        if (!template_ref.module.eql(self.module_key.digest())) return null;
        // A literal root's entry wrapper converts a literal and reaches no
        // exhaustiveness check.
        const idx = template_ref.template.rowIndex() orelse return null;
        if (idx >= self.procedure_templates.templates.items.len) {
            checkedModuleInvariant("reachable procedure template ref was outside table", .{});
        }
        return idx;
    }
};

/// The nested procedure sites of a literal root's entry wrapper, whose body
/// constructs no procedure.
pub const empty_owner_nested_proc_sites: OwnerNestedProcSites = .{};

/// The exhaustiveness sites of a literal root's entry wrapper, whose body
/// reaches none.
pub const empty_template_exhaustiveness_sites: TemplateExhaustivenessSites = .{};

/// The exhaustiveness checks a procedure template's body reaches
/// (`ModuleAnalyses.templateExhaustivenessSites`).
pub const TemplateExhaustivenessSites = struct {
    /// Ascending.
    sites: []const CheckedExhaustivenessSiteId = &.{},

    pub fn destroy(self: *TemplateExhaustivenessSites, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.destroy(self);
    }
};

/// The exhaustiveness checks the body of procedure template `template`
/// reaches.
pub fn computeTemplateExhaustivenessSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    template: canonical.CheckedProcedureTemplateId,
) Allocator.Error!*TemplateExhaustivenessSites {
    const templates = bodies.tables.templates orelse checkedModuleInvariant("exhaustiveness sites were collected from bodies without templates", .{});
    var found = std.ArrayList(CheckedExhaustivenessSiteId).empty;
    defer found.deinit(allocator);
    switch (templates.get(template).body) {
        .checked_body => |root| try collectExhaustivenessSites(allocator, bodies, root, &found),
        .intrinsic_wrapper, .entry_wrapper, .literal_root, .unimplemented => {},
    }
    const sites = try sortedUniqueSites(allocator, found.items);
    errdefer allocator.free(sites);
    const result = try allocator.create(TemplateExhaustivenessSites);
    result.* = .{ .sites = sites };
    return result;
}

fn sortedUniqueSites(allocator: Allocator, sites: []CheckedExhaustivenessSiteId) Allocator.Error![]CheckedExhaustivenessSiteId {
    std.mem.sortUnstable(CheckedExhaustivenessSiteId, sites, {}, struct {
        fn lessThan(_: void, left: CheckedExhaustivenessSiteId, right: CheckedExhaustivenessSiteId) bool {
            return @backingInt(left) < @backingInt(right);
        }
    }.lessThan);
    var len: usize = 0;
    for (sites) |site| {
        if (len > 0 and sites[len - 1] == site) continue;
        sites[len] = site;
        len += 1;
    }
    return allocator.dupe(CheckedExhaustivenessSiteId, sites[0..len]);
}

/// Every exhaustiveness check of `owner` (an index of
/// `ModuleEnv.exhaustiveness_obligations`) with the owner and policy that
/// decide it. A check whose source no body reaches is decided by its checking
/// mode. Otherwise the first compile-time root, in root order, whose
/// evaluation replaces the check's source owns it, else the first template,
/// in template order, whose body reaches it; a template-owned check is
/// runtime reachable or compile-time only by whether the module's root
/// requests reach its template at runtime or only at compile time, and by
/// its checking mode when they reach it at neither.
///
/// A platform/app pairing decides its platform's checks (`platform_sites`)
/// by its own root requests: a template-owned check its requests reach at
/// runtime is runtime reachable, one they reach only at compile time is
/// compile-time only, and none waits for a further pairing.
pub fn computeExhaustivenessSites(
    allocator: Allocator,
    analyses: *ModuleAnalyses,
    owner: ImportedModuleView,
    platform_sites: ?*const CheckedExhaustivenessSiteTable,
) Allocator.Error!*CheckedExhaustivenessSiteTable {
    const root_requests = try owner.rootRequests();
    var reachability = try ExhaustivenessTemplateReachability.build(
        allocator,
        owner.key,
        root_requests,
        &(try owner.checkedTables()).checked_procedure_templates,
        &(try owner.checkedTables()).entry_wrappers,
        (try owner.checkedTables()).callable_eval_templates.view(),
        &(try owner.checkedTables()).top_level_procedure_bindings,
        owner.platform_required_bindings,
        (try owner.valueRefs()),
    );
    defer reachability.deinit();

    const sites = if (platform_sites) |platform|
        try pairingExhaustivenessSites(allocator, platform, &reachability)
    else
        try moduleExhaustivenessSites(allocator, analyses, owner, root_requests, &reachability);
    errdefer allocator.free(sites);
    const result = try allocator.create(CheckedExhaustivenessSiteTable);
    result.* = .{ .sites = sites };
    return result;
}

fn pairingExhaustivenessSites(
    allocator: Allocator,
    platform: *const CheckedExhaustivenessSiteTable,
    reachability: *const ExhaustivenessTemplateReachability,
) Allocator.Error![]CheckedExhaustivenessSite {
    const sites = try allocator.dupe(CheckedExhaustivenessSite, platform.sites);
    for (sites) |*site| {
        site.requires_pairing = false;
        if (site.owner) |owner| switch (owner) {
            .procedure_template => |template| {
                if (reachability.templateIsRuntimeReachable(template)) site.policy = .runtime_reachable else if (reachability.templateIsCompileTimeReachable(template)) site.policy = .compile_time_only;
            },
            .root => {},
        };
    }
    return sites;
}

fn moduleExhaustivenessSites(
    allocator: Allocator,
    analyses: *ModuleAnalyses,
    owner: ImportedModuleView,
    root_requests: *const RootRequestTable,
    reachability: *const ExhaustivenessTemplateReachability,
) Allocator.Error![]CheckedExhaustivenessSite {
    const bodies = (try owner.bodies());
    const obligations = bodies.env.exhaustiveness_obligations.items.items;
    const sites = try allocator.alloc(CheckedExhaustivenessSite, obligations.len);
    errdefer allocator.free(sites);
    if (obligations.len == 0) return sites;

    // The first template, in template order, whose body reaches each check.
    const templates = (try owner.checkedTables()).checked_procedure_templates.templates.items;
    const owner_templates = try allocator.alloc(?canonical.CheckedProcedureTemplateId, obligations.len);
    defer allocator.free(owner_templates);
    @memset(owner_templates, null);
    for (0..templates.len) |raw_template| {
        const template: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(raw_template));
        for ((try analyses.templateExhaustivenessSites(bodies, template)).sites) |site| {
            const slot = &owner_templates[@backingInt(site)];
            if (slot.* == null) slot.* = template;
        }
    }

    // The request of each root of the table that has one. A root with no
    // request (its checked type is not context-free) is never evaluated on
    // its own: every reader evaluates its body in place, so it replaces no
    // check's source.
    const root_table = (try owner.checkedTables()).compile_time_roots.roots;
    const root_requests_by_position = try allocator.alloc(?RootRequest, root_table.len);
    defer allocator.free(root_requests_by_position);
    @memset(root_requests_by_position, null);
    for (root_requests.requests) |request| {
        if (request.abi != .compile_time) continue;
        const root_id = request.compile_time_root orelse continue;
        const position = (try owner.checkedTables()).compile_time_roots.position(root_id) orelse continue;
        root_requests_by_position[position] = request;
    }

    // The first requested compile-time root, in root order, whose evaluation
    // replaces each check's source.
    const replacing_roots = try allocator.alloc(?CompileTimeRoot, obligations.len);
    defer allocator.free(replacing_roots);
    @memset(replacing_roots, null);
    const replacing_requests = try allocator.alloc(RootRequest, obligations.len);
    defer allocator.free(replacing_requests);
    var found = std.ArrayList(CheckedExhaustivenessSiteId).empty;
    defer found.deinit(allocator);
    for (root_table, root_requests_by_position) |root, maybe_request| {
        const request = maybe_request orelse continue;
        if (!compileTimeRootReplacesSourceOccurrence(root.kind)) continue;
        // A literal conversion converts literal data and contains no site.
        if (root.literalConversionKind() != null) continue;
        found.clearRetainingCapacity();
        if (root.hoisted_body) |body| switch (body) {
            .pattern_extraction, .pattern_validation => {
                const base_expr, const exact_pattern = switch (body) {
                    .pattern_extraction => |extraction| .{ extraction.base_expr, extraction.scrutinee_pattern },
                    .pattern_validation => |validation| .{ validation.base_expr, validation.scrutinee_pattern },
                    .expr, .pattern_error, .valueless_binding => unreachable, // the enclosing prong matches only pattern_extraction and pattern_validation
                };
                // Pattern roots evaluate both their match of the base
                // expression against the pattern and the base expression
                // itself.
                try bodies.appendExhaustivenessSitesAt(@backingInt(exact_pattern), .destructure_pattern, allocator, &found);
                try collectExhaustivenessSites(allocator, bodies, base_expr, &found);
            },
            // A rejected destructure binder's root crashes and contains no site.
            .pattern_error => continue,
            .expr, .valueless_binding => try collectExhaustivenessSites(allocator, bodies, root.rootExpr(), &found),
        } else try collectExhaustivenessSites(allocator, bodies, root.rootExpr(), &found);
        for (found.items) |site| {
            const slot = &replacing_roots[@backingInt(site)];
            if (slot.* == null) {
                slot.* = root;
                replacing_requests[@backingInt(site)] = request;
            }
        }
    }

    const owner_module = owner.key.digest();
    for (obligations, sites, owner_templates, replacing_roots, replacing_requests, 0..) |obligation, *site, owner_template_id, replacing_root, replacing_request, index| {
        const id: CheckedExhaustivenessSiteId = @fromBackingInt(@intCast(index));
        const kind: CheckedComptimeSiteKind = switch (obligation.source) {
            .match_expr => .match,
            .destructure_pattern => .destructure,
        };
        const checked_expr: ?CIR.Expr.Idx = switch (obligation.source) {
            .match_expr => |source_expr| source_expr,
            .destructure_pattern => null,
        };
        const checked_pattern: ?CIR.Pattern.Idx = switch (obligation.source) {
            .match_expr => null,
            .destructure_pattern => |source_pattern| source_pattern,
        };
        const source_is_reached = switch (obligation.source) {
            .match_expr => |source_expr| bodies.index().reachesExpr(source_expr),
            .destructure_pattern => |source_pattern| bodies.index().reachesPattern(source_pattern),
        };
        if (!source_is_reached) {
            // Checking may replace an erroneous enclosing expression with a
            // runtime-error node. Its child source occurrences are then
            // intentionally absent from the checked body graph, so no
            // evaluation reaches the site and its checking mode decides it.
            site.* = .{
                .id = id,
                .kind = kind,
                .region = obligation.region,
                .checked_expr = checked_expr,
                .checked_pattern = checked_pattern,
                .policy = .not_pending,
            };
            continue;
        }

        const owner_template: ?canonical.ProcedureTemplateRef = if (owner_template_id) |template_id| .{
            .module = owner_module,
            .proc_base = templates[template_id.index()].proc_base,
            .template = template_id,
        } else null;
        const policy: ExhaustivenessResolutionPolicy = if (replacing_root) |root|
            .{ .compile_time_replaced_by_root = root.id }
        else if (owner_template) |template_ref|
            if (reachability.templateIsRuntimeReachable(template_ref))
                .runtime_reachable
            else if (reachability.templateIsCompileTimeReachable(template_ref))
                .compile_time_only
            else switch (obligation.mode) {
                .static => .runtime_reachable,
                .empirical => .compile_time_only,
            }
        else switch (obligation.mode) {
            .empirical => .compile_time_only,
            .static => .runtime_reachable,
        };
        const requires_pairing = if (replacing_root != null)
            replacing_request.requires_pairing
        else if (owner_template) |template| blk: {
            const template_index = reachability.localTemplateIndex(template).?;
            break :blk reachability.pairing_templates[template_index] and !reachability.runtime_templates[template_index];
        } else false;
        site.* = .{
            .id = id,
            .kind = kind,
            .region = obligation.region,
            .owner = if (replacing_root) |root|
                .{ .root = root.id }
            else if (owner_template) |template_ref|
                .{ .procedure_template = template_ref }
            else
                null,
            .checked_expr = checked_expr,
            .checked_pattern = checked_pattern,
            .policy = policy,
            .requires_pairing = requires_pairing,
        };
    }
    return sites;
}

/// Append the exhaustiveness checks within the checked expression tree
/// rooted at `root` to `found`. Nested lambdas' bodies are searched;
/// promoted procedures' bodies are their own templates'. Nodes wait on an
/// explicit stack, so body nesting never becomes native call depth.
fn collectExhaustivenessSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    root: CIR.Expr.Idx,
    found: *std.ArrayList(CheckedExhaustivenessSiteId),
) Allocator.Error!void {
    const Node = union(enum) {
        expr: CIR.Expr.Idx,
        statement: CIR.Statement.Idx,
        pattern: CIR.Pattern.Idx,
    };
    var pending: std.ArrayList(Node) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .expr = root });
    while (pending.pop()) |node| switch (node) {
        .expr => |expr_id| {
            try bodies.appendExhaustivenessSitesAt(@backingInt(expr_id), .match_expr, allocator, found);
            switch (bodies.exprData(expr_id)) {
                .str => |segments| if (!bodies.quoteIsCustom(@backingInt(expr_id))) for (segments) |segment| try pending.append(allocator, .{ .expr = segment }),
                .list, .tuple => |items| for (items) |item| try pending.append(allocator, .{ .expr = item }),
                .match_ => |match| {
                    try pending.append(allocator, .{ .expr = match.cond });
                    for (match.branches) |branch_idx| {
                        const branch = bodies.matchBranch(branch_idx);
                        for (branch.patterns) |branch_pattern| try pending.append(allocator, .{ .pattern = bodies.matchBranchPattern(branch_pattern).pattern });
                        if (branch.guard) |guard| try pending.append(allocator, .{ .expr = guard });
                        try pending.append(allocator, .{ .expr = branch.value });
                    }
                },
                .if_ => |if_| {
                    for (if_.branches) |branch_idx| {
                        const branch = bodies.ifBranch(branch_idx);
                        try pending.append(allocator, .{ .expr = branch.cond });
                        try pending.append(allocator, .{ .expr = branch.body });
                    }
                    try pending.append(allocator, .{ .expr = if_.final_else });
                },
                .call => |call| {
                    try pending.append(allocator, .{ .expr = call.func });
                    for (call.args) |arg| try pending.append(allocator, .{ .expr = arg });
                },
                .record => |record| {
                    if (record.ext) |ext| try pending.append(allocator, .{ .expr = ext });
                    for (record.fields) |field| try pending.append(allocator, .{ .expr = bodies.recordFieldValue(field) });
                },
                .block => |block| {
                    for (block.statements) |statement| try pending.append(allocator, .{ .statement = statement });
                    try pending.append(allocator, .{ .expr = block.final_expr });
                },
                .tag => |tag| for (tag.args) |arg| try pending.append(allocator, .{ .expr = arg }),
                .nominal => |nominal| try pending.append(allocator, .{ .expr = nominal.backing_expr }),
                .closure => |closure| try pending.append(allocator, .{ .expr = closure.lambda }),
                .lambda => |lambda| {
                    for (lambda.args) |arg| try pending.append(allocator, .{ .pattern = arg });
                    try pending.append(allocator, .{ .expr = lambda.body });
                },
                .binop => |binop| {
                    try pending.append(allocator, .{ .expr = binop.lhs });
                    try pending.append(allocator, .{ .expr = binop.rhs });
                },
                .unary_minus, .dbg, .expect => |child| try pending.append(allocator, .{ .expr = child }),
                .tuple_access => |access| try pending.append(allocator, .{ .expr = access.tuple }),
                .field_access => |field| try pending.append(allocator, .{ .expr = field.receiver }),
                .interpolation => |interpolation| {
                    try pending.append(allocator, .{ .expr = interpolation.first });
                    for (interpolation.parts) |part| try pending.append(allocator, .{ .expr = part });
                },
                .structural_eq => |eq| {
                    try pending.append(allocator, .{ .expr = eq.lhs });
                    try pending.append(allocator, .{ .expr = eq.rhs });
                },
                .structural_hash => |h| {
                    try pending.append(allocator, .{ .expr = h.value });
                    try pending.append(allocator, .{ .expr = h.hasher });
                },
                .expect_err => |expect_err| try pending.append(allocator, .{ .expr = expect_err.expr }),
                .return_ => |ret| try pending.append(allocator, .{ .expr = ret.expr }),
                .for_ => |for_| {
                    try pending.append(allocator, .{ .pattern = for_.pattern });
                    try pending.append(allocator, .{ .expr = for_.expr });
                    try pending.append(allocator, .{ .expr = for_.body });
                },
                .run_low_level => |run| for (run.args) |arg| try pending.append(allocator, .{ .expr = arg }),
                .hosted_lambda => |hosted| for (hosted.args) |arg| try pending.append(allocator, .{ .pattern = arg }),
                .numeral,
                .str_segment,
                .bytes_literal,
                .lookup_local,
                .lookup_external,
                .lookup_required,
                .empty_list,
                .empty_record,
                .zero_argument_tag,
                .dispatch_call,
                .method_eq,
                .type_dispatch_call,
                .runtime_error,
                .crash,
                .break_,
                .ellipsis,
                .anno_only,
                => {},
            }
        },
        .statement => |statement_id| switch (bodies.statementData(statement_id)) {
            .decl => |decl| {
                try pending.append(allocator, .{ .pattern = decl.pattern });
                try pending.append(allocator, .{ .expr = decl.expr });
            },
            // The promoted procedure's lambda is its own template's body.
            .promoted_proc => |promoted| try pending.append(allocator, .{ .pattern = promoted.pattern }),
            .var_ => |var_| {
                try pending.append(allocator, .{ .pattern = var_.pattern });
                try pending.append(allocator, .{ .expr = var_.expr });
            },
            .var_uninitialized => |var_| try pending.append(allocator, .{ .pattern = var_.pattern }),
            .reassign => |reassign| {
                try pending.append(allocator, .{ .pattern = reassign.pattern });
                try pending.append(allocator, .{ .expr = reassign.expr });
            },
            .dbg, .expr, .expect => |expr| try pending.append(allocator, .{ .expr = expr }),
            .for_ => |for_| {
                try pending.append(allocator, .{ .pattern = for_.pattern });
                try pending.append(allocator, .{ .expr = for_.expr });
                try pending.append(allocator, .{ .expr = for_.body });
            },
            .while_, .infinite_loop, .breakable_loop => |loop| {
                try pending.append(allocator, .{ .expr = loop.cond });
                try pending.append(allocator, .{ .expr = loop.body });
            },
            .return_ => |ret| try pending.append(allocator, .{ .expr = ret.expr }),
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        },
        .pattern => |pattern_id| {
            try bodies.appendExhaustivenessSitesAt(@backingInt(pattern_id), .destructure_pattern, allocator, found);
            switch (bodies.patternData(pattern_id)) {
                .as => |as| try pending.append(allocator, .{ .pattern = as.pattern }),
                .applied_tag => |tag| for (tag.args) |arg| try pending.append(allocator, .{ .pattern = arg }),
                .nominal => |nominal| try pending.append(allocator, .{ .pattern = nominal.backing_pattern }),
                .record_destructure => |destructs| for (destructs) |destruct| {
                    try pending.append(allocator, .{ .pattern = bodies.recordDestructPattern(destruct) });
                },
                .list => |list| {
                    for (list.patterns) |child| try pending.append(allocator, .{ .pattern = child });
                    if (list.rest) |rest| if (rest.pattern) |rest_pattern| try pending.append(allocator, .{ .pattern = rest_pattern });
                },
                .tuple => |items| for (items) |item| try pending.append(allocator, .{ .pattern = item }),
                .str_interpolation => |str| {
                    var offset: u32 = 0;
                    while (offset < str.steps.span.len) : (offset += 1) {
                        if (bodies.strPatternStep(str.steps, offset).capture) |capture| try pending.append(allocator, .{ .pattern = capture });
                    }
                },
                .assign,
                .numeral_literal,
                .str_literal,
                .underscore,
                .runtime_error,
                => {},
            }
        },
    };
}

fn compileTimeRootReplacesSourceOccurrence(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant,
        .hoisted_constant,
        .hoisted_validation,
        .numeral_conversion,
        .quote_conversion,
        .repl_expr,
        .literal_argument,
        => true,
        .callable_binding,
        .expect,
        => false,
    };
}

fn reachedRootExpr(module_index: *const ModuleIndex, expr: CIR.Expr.Idx) CIR.Expr.Idx {
    if (!module_index.reachesExpr(expr)) {
        checkedModuleInvariant("a compile-time root's expression {d} is not reached by the checked bodies", .{@backingInt(expr)});
    }
    return expr;
}

fn reachedRootPattern(module_index: *const ModuleIndex, pattern: CIR.Pattern.Idx) CIR.Pattern.Idx {
    if (!module_index.reachesPattern(pattern)) {
        checkedModuleInvariant("a compile-time root's pattern {d} is not reached by the checked bodies", .{@backingInt(pattern)});
    }
    return pattern;
}

const SelectedHoistedRootBody = struct {
    expr: CIR.Expr.Idx,
    pattern: ?CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
};

/// A selected hoisted root's expression, binding pattern, and value type. A
/// pattern root's body is the lowering-side construct its `hoisted_body`
/// describes; its expression is the selected expression it matches.
fn selectedHoistedRootBody(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedSourceTypes,
    module_index: *const ModuleIndex,
    selected: hoist_roots.SelectedHoistedRoot,
    empty_record: ?CheckedTypeId,
) Allocator.Error!SelectedHoistedRootBody {
    return switch (selected.body) {
        .expr => .{
            .expr = reachedRootExpr(module_index, selected.expr),
            .pattern = if (selected.pattern) |pattern| reachedRootPattern(module_index, pattern) else null,
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, if (selected.pattern) |pattern| ModuleEnv.varFrom(pattern) else module.exprType(selected.expr)),
        },
        .pattern_error => blk: {
            const pattern = selected.pattern orelse
                checkedModuleInvariant("pattern-error hoisted root has no binding pattern", .{});
            break :blk .{
                .expr = selected.expr,
                .pattern = reachedRootPattern(module_index, pattern),
                .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(pattern)),
            };
        },
        .pattern_extraction => |extraction| .{
            .expr = reachedRootExpr(module_index, extraction.base_expr),
            .pattern = reachedRootPattern(module_index, extraction.result_pattern),
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(extraction.result_pattern)),
        },
        .pattern_validation => |validation| .{
            .expr = reachedRootExpr(module_index, validation.base_expr),
            .pattern = reachedRootPattern(module_index, validation.scrutinee_pattern),
            .checked_type = empty_record orelse checkedModuleInvariant("a pattern-validation root's empty record type was not created", .{}),
        },
        // The right-hand side always crashes, so the root produces no value:
        // like a validation root, its discarded result is unit-valued.
        .valueless_binding => .{
            .expr = reachedRootExpr(module_index, selected.expr),
            .pattern = null,
            .checked_type = empty_record orelse checkedModuleInvariant("a valueless root's empty record type was not created", .{}),
        },
    };
}

/// Public `ConstRef` declaration.
pub const ConstRef = struct {
    module: CheckedModuleDigest,
    owner: ConstOwner,
    template: ConstTemplateId,
    source_scheme: CheckedTypeSchemeId,
};

/// Public checked constant locator declaration.
pub const ConstLocator = ConstRef;

/// Return the checked module id that owns a compile-time constant.
pub fn constModuleId(ref: ConstRef) ModuleId {
    return ref.module;
}

/// Public `ConstOwner` declaration.
pub const ConstOwner = union(enum(u8)) {
    top_level_binding: ConstTopLevelOwner,
    hoisted_root: ConstHoistedOwner,
};

/// Public `ConstTopLevelOwner` declaration.
pub const ConstTopLevelOwner = struct {
    module_idx: u32,
    pattern: CIR.Pattern.Idx,
};

/// Public `ConstHoistedOwner` declaration.
pub const ConstHoistedOwner = struct {
    module_idx: u32,
    /// The hoisted constant's compile-time root. Several roots can match one
    /// expression (one per binder of a destructure), so the root identifies
    /// the constant.
    root: ComptimeRootKey,
};

/// Public `TopLevelValueKind` declaration.
pub const TopLevelValueKind = union(enum) {
    const_ref: ConstRef,
    procedure_binding: TopLevelProcedureBindingRef,
};

/// Public `TopLevelValueEntry` declaration.
pub const TopLevelValueEntry = struct {
    module_idx: u32,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    source_name: canonical.ExportNameId,
    source_scheme: CheckedTypeSchemeId,
    value: TopLevelValueKind,
};

const TopLevelValueByDefEntry = struct {
    def: CIR.Def.Idx,
    entry: u32,

    fn lessThan(_: void, lhs: TopLevelValueByDefEntry, rhs: TopLevelValueByDefEntry) bool {
        return @backingInt(lhs.def) < @backingInt(rhs.def);
    }
};

const TopLevelValueByPatternEntry = struct {
    pattern: CIR.Pattern.Idx,
    entry: u32,

    fn order(item: TopLevelValueByPatternEntry, key: CIR.Pattern.Idx) std.math.Order {
        return std.math.order(@backingInt(item.pattern), @backingInt(key));
    }

    fn lessThan(_: void, a: TopLevelValueByPatternEntry, b: TopLevelValueByPatternEntry) bool {
        return @backingInt(a.pattern) < @backingInt(b.pattern);
    }
};

/// Public `TopLevelValueTable` declaration.
pub const TopLevelValueTable = struct {
    entries: []TopLevelValueEntry = &.{},
    /// Entries by pattern, ascending.
    by_pattern: []TopLevelValueByPatternEntry = &.{},
    by_def: []TopLevelValueByDefEntry = &.{},

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        module_index: *const ModuleIndex,
        templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *CallableEvalTemplateTable,
        procedure_bindings: *TopLevelProcedureBindingTable,
        const_templates: *ConstTemplateTable,
        module_key: CheckedModuleKey,
        compile_time_roots: *const CompileTimeRootTable,
        checked_source_types: *const CheckedSourceTypes,
    ) Allocator.Error!TopLevelValueTable {
        var entries = std.ArrayList(TopLevelValueEntry).empty;
        errdefer entries.deinit(allocator);

        var by_pattern = std.ArrayList(TopLevelValueByPatternEntry).empty;
        errdefer by_pattern.deinit(allocator);

        var by_def = std.ArrayList(TopLevelValueByDefEntry).empty;
        errdefer by_def.deinit(allocator);

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedModuleInvariant("generated method marker reached top-level-value publication", .{});
            }
            const checked_pattern = reachedRootPattern(module_index, def.pattern.idx);
            const source_name = try topLevelDefSourceName(module, names, def) orelse continue;
            const source_ty = module.defType(def_idx);
            const source_scheme = checked_source_types.schemeForSourceVar(module, source_ty);
            const value: TopLevelValueKind = if (templates.lookupByDef(def_idx)) |template| blk: {
                const binding = try procedure_bindings.appendDirect(
                    allocator,
                    source_scheme,
                    .{ .module = template.module, .proc_base = template.proc_base },
                    template,
                );
                break :blk .{ .procedure_binding = binding };
            } else if (sourceTypeIsFunction(module, source_ty)) blk: {
                if (def.expr.data == .e_runtime_error) {
                    break :blk .{ .procedure_binding = try procedure_bindings.appendCheckedError(
                        allocator,
                        source_scheme,
                        reachedRootExpr(module_index, def.expr.idx),
                    ) };
                }
                const root_id = compile_time_roots.lookupIdByPattern(checked_pattern) orelse {
                    base.invariant(
                        "checked module invariant violated: function-valued binding {d} has no compile-time callable root",
                        .{@backingInt(def.pattern.idx)},
                    );
                };
                const root = compile_time_roots.root(root_id);
                if (root.kind != .callable_binding) {
                    base.invariant(
                        "checked module invariant violated: function-valued binding {d} mapped to non-callable compile-time root",
                        .{@backingInt(def.pattern.idx)},
                    );
                }
                const checked_fn_root = root.checked_type;
                const callable_template = try callable_eval_templates.append(
                    allocator,
                    module.moduleIndex(),
                    checked_pattern,
                    root_id,
                    source_scheme,
                    checked_fn_root,
                );
                const binding = try procedure_bindings.appendCallableEval(
                    allocator,
                    source_scheme,
                    callable_template,
                );
                break :blk .{ .procedure_binding = binding };
            } else if (def.expr.data == .e_anno_only) .{ .const_ref = try const_templates.reserveUnimplementedTopLevel(
                allocator,
                module_key,
                module.moduleIndex(),
                checked_pattern,
                source_scheme,
                .{ .region = module.regionAt(ModuleEnv.nodeIdxFrom(def.expr.idx)) },
            ) } else .{ .const_ref = try const_templates.reserveTopLevel(
                allocator,
                module_key,
                module.moduleIndex(),
                checked_pattern,
                source_scheme,
            ) };

            const entry_idx: u32 = @intCast(entries.items.len);
            try entries.append(allocator, .{
                .module_idx = module.moduleIndex(),
                .def = def_idx,
                .pattern = checked_pattern,
                .source_name = source_name,
                .source_scheme = source_scheme,
                .value = value,
            });
            try by_pattern.append(allocator, .{ .pattern = checked_pattern, .entry = entry_idx });
            try by_def.append(allocator, .{
                .def = def_idx,
                .entry = entry_idx,
            });
        }

        std.mem.sort(TopLevelValueByDefEntry, by_def.items, {}, TopLevelValueByDefEntry.lessThan);
        std.mem.sort(TopLevelValueByPatternEntry, by_pattern.items, {}, TopLevelValueByPatternEntry.lessThan);
        const entry_slice = try entries.toOwnedSlice(allocator);
        errdefer allocator.free(entry_slice);
        const by_pattern_slice = try by_pattern.toOwnedSlice(allocator);
        errdefer allocator.free(by_pattern_slice);
        const by_def_slice = try by_def.toOwnedSlice(allocator);
        return .{
            .entries = entry_slice,
            .by_pattern = by_pattern_slice,
            .by_def = by_def_slice,
        };
    }

    pub fn lookupByPattern(self: *const TopLevelValueTable, pattern: CIR.Pattern.Idx) ?TopLevelValueEntry {
        const found = store_serialize.binarySearchByKey(TopLevelValueByPatternEntry, CIR.Pattern.Idx, self.by_pattern, pattern, TopLevelValueByPatternEntry.order) orelse return null;
        return self.entries[found.entry];
    }

    pub fn lookupByDef(self: *const TopLevelValueTable, def: CIR.Def.Idx) ?TopLevelValueEntry {
        var lo: usize = 0;
        var hi: usize = self.by_def.len;
        const target = @backingInt(def);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_def[mid].def);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_def.len or self.by_def[lo].def != def) return null;
        return self.entries[self.by_def[lo].entry];
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `HoistedConstId` declaration.
pub const HoistedConstId = enum(u32) { _ };

/// Public `HoistedConstEntry` declaration.
pub const HoistedConstEntry = struct {
    id: HoistedConstId,
    module_idx: u32,
    root: ComptimeRootKey,
    expr: CIR.Expr.Idx,
    pattern: ?CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
    source_scheme: CheckedTypeSchemeId,
    const_ref: ConstRef,
};

const HoistedConstByExprEntry = struct {
    expr: CIR.Expr.Idx,
    entry: HoistedConstId,

    fn lessThan(_: void, lhs: HoistedConstByExprEntry, rhs: HoistedConstByExprEntry) bool {
        return @backingInt(lhs.expr) < @backingInt(rhs.expr);
    }
};

const HoistedConstByPatternEntry = struct {
    pattern: CIR.Pattern.Idx,
    entry: HoistedConstId,

    fn lessThan(_: void, lhs: HoistedConstByPatternEntry, rhs: HoistedConstByPatternEntry) bool {
        return @backingInt(lhs.pattern) < @backingInt(rhs.pattern);
    }
};

/// Public `HoistedConstTable` declaration.
///
/// Sparse index for selected hoisted constants. Every entry corresponds to a
/// published `.hoisted_constant` root. The by-expr, by-pattern, and by-root
/// indexes are lookup accelerators for later stages; there is no data here for
/// unselected expressions or patterns, and no scheduling/dependency metadata.
pub const HoistedConstTable = struct {
    entries: []HoistedConstEntry = &.{},
    by_expr: []HoistedConstByExprEntry = &.{},
    by_pattern: []HoistedConstByPatternEntry = &.{},

    pub fn fromRoots(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_key: CheckedModuleKey,
        validation_scheme: ?CheckedTypeSchemeId,
        roots: *const CompileTimeRootTable,
        const_templates: *ConstTemplateTable,
        checked_source_types: *const CheckedSourceTypes,
    ) Allocator.Error!HoistedConstTable {
        var entries = std.ArrayList(HoistedConstEntry).empty;
        errdefer entries.deinit(allocator);

        var by_expr = std.ArrayList(HoistedConstByExprEntry).empty;
        errdefer by_expr.deinit(allocator);

        var by_pattern = std.ArrayList(HoistedConstByPatternEntry).empty;
        errdefer by_pattern.deinit(allocator);

        for (roots.roots) |root| {
            if (root.kind != .hoisted_constant) continue;
            const source_expr = switch (root.source) {
                .hoisted => |hoisted| hoisted.expr,
                .def,
                .expr,
                .statement,
                .required_binding,
                .literal,
                => checkedModuleInvariant("hoisted constant root had non-expression source", .{}),
            };
            const source_var = if (root.source_pattern) |pattern|
                ModuleEnv.varFrom(pattern)
            else
                ModuleEnv.varFrom(source_expr);
            const source_scheme = if (root.hoisted_body) |body| switch (body) {
                .pattern_validation => validation_scheme orelse checkedModuleInvariant("a pattern-validation constant's scheme was not created", .{}),
                .expr, .pattern_extraction, .pattern_error => checked_source_types.schemeForSourceVar(module, source_var),
                .valueless_binding => checkedModuleInvariant("valueless binding root was published as a hoisted constant", .{}),
            } else checked_source_types.schemeForSourceVar(module, source_var);
            const const_ref = try const_templates.reserveHoisted(
                allocator,
                module_key,
                module.moduleIndex(),
                root.id,
                source_scheme,
            );
            const id: HoistedConstId = @fromBackingInt(@intCast(@as(u32, @intCast(entries.items.len))));
            try entries.append(allocator, .{
                .id = id,
                .module_idx = module.moduleIndex(),
                .root = root.id,
                .expr = root.rootExpr(),
                .pattern = root.pattern,
                .checked_type = root.checked_type,
                .source_scheme = source_scheme,
                .const_ref = const_ref,
            });
            // Only a root that evaluates its expression stands for that
            // expression's occurrence.
            if (root.evaluatedExpr()) |evaluated| try by_expr.append(allocator, .{
                .expr = evaluated,
                .entry = id,
            });
            if (root.pattern) |pattern| {
                try by_pattern.append(allocator, .{
                    .pattern = pattern,
                    .entry = id,
                });
            }
        }

        std.mem.sort(HoistedConstByExprEntry, by_expr.items, {}, HoistedConstByExprEntry.lessThan);
        std.mem.sort(HoistedConstByPatternEntry, by_pattern.items, {}, HoistedConstByPatternEntry.lessThan);

        const entry_slice = try entries.toOwnedSlice(allocator);
        errdefer allocator.free(entry_slice);
        const by_expr_slice = try by_expr.toOwnedSlice(allocator);
        errdefer allocator.free(by_expr_slice);
        const by_pattern_slice = try by_pattern.toOwnedSlice(allocator);

        return .{
            .entries = entry_slice,
            .by_expr = by_expr_slice,
            .by_pattern = by_pattern_slice,
        };
    }

    pub fn lookupByExpr(self: *const HoistedConstTable, expr: CIR.Expr.Idx) ?HoistedConstEntry {
        var lo: usize = 0;
        var hi: usize = self.by_expr.len;
        const target = @backingInt(expr);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_expr[mid].expr);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_expr.len or self.by_expr[lo].expr != expr) return null;
        return self.entries[@backingInt(self.by_expr[lo].entry)];
    }

    pub fn lookupByPattern(self: *const HoistedConstTable, pattern: CIR.Pattern.Idx) ?HoistedConstEntry {
        var lo: usize = 0;
        var hi: usize = self.by_pattern.len;
        const target = @backingInt(pattern);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_pattern[mid].pattern);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_pattern.len or self.by_pattern[lo].pattern != pattern) return null;
        return self.entries[@backingInt(self.by_pattern[lo].entry)];
    }

    /// The entry of hoisted root `root`. Entries follow their roots'
    /// ascending identities.
    pub fn lookupByRoot(self: *const HoistedConstTable, root: ComptimeRootKey) ?HoistedConstEntry {
        const index = std.sort.binarySearch(HoistedConstEntry, self.entries, root, struct {
            fn order(key: ComptimeRootKey, item: HoistedConstEntry) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.root));
            }
        }.order) orelse return null;
        return self.entries[index];
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};

