/// Public `ImportedTemplateClosureView` declaration.
pub const ImportedTemplateClosureView = struct {
    checked_bodies: []const ModuleCheckedBodyRef = &.{},
    checked_type_roots: []const ModuleCheckedTypeRef = &.{},
    checked_type_schemes: []const ModuleCheckedTypeSchemeRef = &.{},
    checked_callable_bodies: []const ModuleCheckedCallableBodyRef = &.{},
    checked_procedure_templates: []const ModuleProcedureTemplateRef = &.{},
    callable_eval_templates: []const ModuleCallableEvalTemplateRef = &.{},
    const_templates: []const ConstRef = &.{},
    resolved_value_refs: []const ModuleResolvedValueRefTableRef = &.{},
    static_dispatch_plans: []const ModuleStaticDispatchPlanTableRef = &.{},
    method_registry_entries: []const MethodRegistryEntryRef = &.{},
    interface_capabilities: []const ModuleInterfaceCapabilitiesRef = &.{},
};

/// The closure slice names, shared by every table that stores one list per slice.
const closure_fields = @typeInfo(ImportedTemplateClosureView).@"struct".field_names;

/// `(start, len)` range into one of a `ClosurePool`'s flat side pools.
pub const ClosureRange = extern struct { start: u32 = 0, len: u32 = 0 };

/// Relocation-invariant (POD) mirror of `ImportedTemplateClosureView`: each of
/// the 11 closure slices is replaced by a `ClosureRange` into the owning
/// `ClosurePool`. Stored by value in closure-bearing table rows so each row
/// relocates with a constant number of base-pointer fixups. The public
/// `ImportedTemplateClosureView` (with slices) is reconstructed on demand.
pub const StoredImportedTemplateClosure = extern struct {
    checked_bodies: ClosureRange = .{},
    checked_type_roots: ClosureRange = .{},
    checked_type_schemes: ClosureRange = .{},
    checked_callable_bodies: ClosureRange = .{},
    checked_procedure_templates: ClosureRange = .{},
    callable_eval_templates: ClosureRange = .{},
    const_templates: ClosureRange = .{},
    resolved_value_refs: ClosureRange = .{},
    static_dispatch_plans: ClosureRange = .{},
    method_registry_entries: ClosureRange = .{},
    interface_capabilities: ClosureRange = .{},
};

/// Flat side pools backing every `StoredImportedTemplateClosure` of a single
/// closure-bearing table. Each public closure slice has its own pool of POD ref
/// elements; `commit` copies an owned `ImportedTemplateClosureView` into the
/// pools and `materialize` returns the public view aliasing them (zero-alloc).
pub const ClosurePool = struct {
    checked_bodies: std.ArrayList(ModuleCheckedBodyRef) = .empty,
    checked_type_roots: std.ArrayList(ModuleCheckedTypeRef) = .empty,
    checked_type_schemes: std.ArrayList(ModuleCheckedTypeSchemeRef) = .empty,
    checked_callable_bodies: std.ArrayList(ModuleCheckedCallableBodyRef) = .empty,
    checked_procedure_templates: std.ArrayList(ModuleProcedureTemplateRef) = .empty,
    callable_eval_templates: std.ArrayList(ModuleCallableEvalTemplateRef) = .empty,
    const_templates: std.ArrayList(ConstRef) = .empty,
    resolved_value_refs: std.ArrayList(ModuleResolvedValueRefTableRef) = .empty,
    static_dispatch_plans: std.ArrayList(ModuleStaticDispatchPlanTableRef) = .empty,
    method_registry_entries: std.ArrayList(MethodRegistryEntryRef) = .empty,
    interface_capabilities: std.ArrayList(ModuleInterfaceCapabilitiesRef) = .empty,
    /// True when the pools alias a serialized buffer and must not be freed.
    serialized: bool = false,

    pub const empty: ClosurePool = .{};

    /// Copy each closure slice into its pool, returning the POD ranges, then
    /// free the input view's owned slices. Mirrors `deinitImportedTemplateClosure`.
    pub fn commit(
        self: *ClosurePool,
        allocator: Allocator,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!StoredImportedTemplateClosure {
        var owned = closure;
        defer deinitImportedTemplateClosure(allocator, &owned);
        return self.appendBorrowed(allocator, closure);
    }

    /// Append borrowed closure refs without allocating temporary owned slices.
    pub fn appendBorrowed(
        self: *ClosurePool,
        allocator: Allocator,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!StoredImportedTemplateClosure {
        var stored: StoredImportedTemplateClosure = .{};
        inline for (closure_fields) |name| {
            const Elem = std.meta.Child(@FieldType(ImportedTemplateClosureView, name));
            @field(stored, name) = try store_serialize.appendSpan(ClosureRange, Elem, &@field(self, name), allocator, @field(closure, name));
        }
        return stored;
    }

    /// Materialize the public 11-slice view aliasing this pool's flat storage.
    pub fn reconstruct(self: *const ClosurePool, stored: StoredImportedTemplateClosure) ImportedTemplateClosureView {
        var closure: ImportedTemplateClosureView = .{};
        inline for (closure_fields) |name| {
            const range = @field(stored, name);
            @field(closure, name) = @field(self, name).items[range.start .. range.start + range.len];
        }
        return closure;
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;

    /// Relocatable serialized form: one `SerializedSlice` per flat pool (11
    /// base-pointer fixups, independent of stored data size).
    pub const Serialized = extern struct {
        checked_bodies: SerializedSlice(ModuleCheckedBodyRef) = .{},
        checked_type_roots: SerializedSlice(ModuleCheckedTypeRef) = .{},
        checked_type_schemes: SerializedSlice(ModuleCheckedTypeSchemeRef) = .{},
        checked_callable_bodies: SerializedSlice(ModuleCheckedCallableBodyRef) = .{},
        checked_procedure_templates: SerializedSlice(ModuleProcedureTemplateRef) = .{},
        callable_eval_templates: SerializedSlice(ModuleCallableEvalTemplateRef) = .{},
        const_templates: SerializedSlice(ConstRef) = .{},
        resolved_value_refs: SerializedSlice(ModuleResolvedValueRefTableRef) = .{},
        static_dispatch_plans: SerializedSlice(ModuleStaticDispatchPlanTableRef) = .{},
        method_registry_entries: SerializedSlice(MethodRegistryEntryRef) = .{},
        interface_capabilities: SerializedSlice(ModuleInterfaceCapabilitiesRef) = .{},

        comptime {
            std.debug.assert(store_serialize.relocatablePointerCount(Serialized) == 11);
        }

        const Serde = store_serialize.SliceStoreSerde(ClosurePool, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

test "ClosurePool: commit/reconstruct then serialize/relocate round-trip" {
    const gpa = std.testing.allocator;

    const key_a = CheckedModuleKey{ .bytes = @as([32]u8, @splat(1)) };
    const key_b = CheckedModuleKey{ .bytes = @as([32]u8, @splat(2)) };

    // An owned closure view (slices allocated by the caller, freed by commit).
    var closure = ImportedTemplateClosureView{};
    closure.checked_bodies = try gpa.dupe(ModuleCheckedBodyRef, &.{
        .{ .module = key_a.digest(), .body = @fromBackingInt(@intCast(7)) },
        .{ .module = key_b.digest(), .body = @fromBackingInt(@intCast(9)) },
    });
    closure.interface_capabilities = try gpa.dupe(ModuleInterfaceCapabilitiesRef, &.{
        .{ .module = key_a.digest() },
    });

    var pool = ClosurePool.empty;
    defer pool.deinit(gpa);
    const stored = try pool.commit(gpa, closure);

    // Reconstructed view aliases the pool.
    const reconstructed = pool.reconstruct(stored);
    try std.testing.expectEqual(@as(usize, 2), reconstructed.checked_bodies.len);
    try std.testing.expectEqual(@as(u32, 7), @backingInt(reconstructed.checked_bodies[0].body));
    try std.testing.expectEqual(@as(usize, 1), reconstructed.interface_capabilities.len);

    // Serialize → aligned buffer → deserialize, then materialize again.
    var rt = try store_serialize.roundTripForTest(gpa, ClosurePool, &pool);
    defer gpa.free(rt.buffer);
    defer rt.loaded.deinit(gpa);

    const loaded = rt.loaded.reconstruct(stored);
    try std.testing.expectEqual(@as(usize, 2), loaded.checked_bodies.len);
    try std.testing.expectEqual(@as(u32, 9), @backingInt(loaded.checked_bodies[1].body));
    try std.testing.expectEqualSlices(u8, &key_b.bytes, &loaded.checked_bodies[1].module.bytes);
    try std.testing.expectEqual(@as(usize, 1), loaded.interface_capabilities.len);
    try std.testing.expectEqualSlices(u8, &key_a.bytes, &loaded.interface_capabilities[0].module.bytes);
}

test "platform relation procedure use preserves exported runtime result provenance" {
    const gpa = std.testing.allocator;
    const app_key = CheckedModuleKey{ .bytes = @as([32]u8, @splat(0xA7)) };
    const app_pattern: CIR.Pattern.Idx = @fromBackingInt(@intCast(2));
    const procedure_binding: TopLevelProcedureBindingRef = @fromBackingInt(@intCast(3));
    const required_binding_id: PlatformRequiredBindingId = @fromBackingInt(@intCast(8));
    const required_declaration_id: PlatformRequiredDeclarationId = @fromBackingInt(@intCast(9));
    const required_relation_id: PlatformRequirementRelationId = @fromBackingInt(@intCast(10));
    const exported = ImportedProcedureBindingView{
        .binding = .{
            .module = app_key.digest(),
            .def = @fromBackingInt(@intCast(1)),
            .pattern = app_pattern,
        },
        .source_scheme = @fromBackingInt(@intCast(1)),
        .body = .{ .callable_eval_template = @fromBackingInt(@intCast(4)) },
        .runtime_result_provenance = .list_element_read,
    };
    const app_value = TopLevelValueEntry{
        .module_idx = 5,
        .def = exported.binding.def,
        .pattern = app_pattern,
        .source_name = @fromBackingInt(@intCast(6)),
        .source_scheme = @fromBackingInt(@intCast(1)),
        .value = .{ .procedure_binding = procedure_binding },
    };
    const app_value_ref = TopLevelValueRef{
        .module = app_key.digest(),
        .pattern = app_pattern,
    };
    const resolved_export = exported;
    try std.testing.expectEqual(@as(usize, 0), exportedProcedureBindingForAppValue(
        &.{exported},
        app_value,
    ));
    const procedure = platformRequiredProcedureUse(
        app_key,
        app_value_ref,
        procedure_binding,
        resolved_export,
    );

    var table = PlatformRequiredBindingTable{};
    defer table.deinit(gpa);
    const stored_use = try copyPlatformRequiredValueUse(&table.closure_pool, gpa, .{
        .procedure_value = .{ .procedure = procedure },
    });
    table.bindings = try gpa.dupe(PlatformRequiredBinding, &.{.{
        .id = required_binding_id,
        .relation = .{},
        .module_idx = 7,
        .declaration = required_declaration_id,
        .requires_idx = 0,
        .app_value = app_value_ref,
        .checked_relation = required_relation_id,
        .value_use = stored_use,
    }});

    var rt = try store_serialize.roundTripForTest(gpa, PlatformRequiredBindingTable, &table);
    defer gpa.free(rt.buffer);
    defer rt.loaded.deinit(gpa);
    try std.testing.expectEqual(required_binding_id, rt.loaded.bindings[0].id);
    try std.testing.expectEqual(required_declaration_id, rt.loaded.bindings[0].declaration);
    try std.testing.expectEqual(required_relation_id, rt.loaded.bindings[0].checked_relation);
    const loaded_procedure = switch (rt.loaded.bindings[0].value_use) {
        .procedure_value => |procedure_use| procedure_use.procedure,
        .const_value => return error.TestExpectedEqual,
    };
    try std.testing.expectEqual(
        RuntimeResultProvenance.list_element_read,
        loaded_procedure.runtime_result_provenance.?,
    );
}

/// Public `appendImportedTemplateClosureModuleKeys` function.
///
/// Appends every checked module explicitly referenced by an imported
/// template closure. This is used when an executable root needs to assemble the
/// complete set of read-only module views required by platform/app relation
/// closures without scanning source or rediscovering dependencies from syntax.
pub fn appendImportedTemplateClosureModuleKeys(
    allocator: Allocator,
    keys: *std.ArrayList(ModuleId),
    closure: ImportedTemplateClosureView,
) Allocator.Error!void {
    inline for (closure_fields) |name| {
        const Elem = std.meta.Child(@FieldType(ImportedTemplateClosureView, name));
        // Method registry entries are keyed by the owning table, not by module.
        if (comptime @hasField(Elem, "module")) {
            for (@field(closure, name)) |value| {
                try appendClosureModuleKey(allocator, keys, value.module);
            }
        }
    }
}

/// Public `appendPlatformRelationDependencyModuleKeysFromView` function.
///
/// Same dependency collection as `appendPlatformRelationDependencyModuleKeys`,
/// but consumes the read-only relation module view already passed across the
/// post-check lowering boundary.
pub fn appendPlatformRelationDependencyModuleKeysFromView(
    allocator: Allocator,
    keys: *std.ArrayList(ModuleId),
    relation_module: ImportedModuleView,
    resolver: ModuleResolver,
    binding: PlatformRequiredBinding,
    binding_relation_closure: ImportedTemplateClosureView,
) Allocator.Error!void {
    for (relation_module.direct_import_module_keys) |key| {
        try appendClosureModuleKey(allocator, keys, key.digest());
    }

    try appendImportedTemplateClosureModuleKeys(allocator, keys, binding_relation_closure);
    try appendRelationModuleExportedValueClosureKeysFromView(allocator, keys, relation_module, try relation_module.exportClosures(resolver), binding);
}

fn appendRelationModuleExportedValueClosureKeysFromView(
    allocator: Allocator,
    keys: *std.ArrayList(ModuleId),
    relation_module: ImportedModuleView,
    closures: *const ExportClosures,
    binding: PlatformRequiredBinding,
) Allocator.Error!void {
    switch (binding.value_use) {
        .procedure_value => {
            var found = false;
            for ((try relation_module.exportRows()).procedure_bindings, 0..) |exported, binding_index| {
                if (exported.binding.pattern != binding.app_value.pattern) continue;
                found = true;
                try appendImportedTemplateClosureModuleKeys(allocator, keys, closures.procedureBinding(binding_index));
                for ((try relation_module.exportRows()).procedure_templates, 0..) |template, template_index| {
                    if (template.def == exported.binding.def) {
                        try appendImportedTemplateClosureModuleKeys(allocator, keys, closures.procedureTemplate(template_index));
                    }
                }
            }
            if (!found) {
                checkedModuleInvariant("platform relation dependency collection could not find exported app procedure binding", .{});
            }
        },
        .const_value => |const_use| {
            var found = false;
            for ((try relation_module.exportRows()).const_templates, 0..) |template, template_index| {
                if (template.pattern != binding.app_value.pattern) continue;
                if (!constRefEql(template.const_ref, const_use.const_use.const_ref)) continue;
                found = true;
                try appendImportedTemplateClosureModuleKeys(allocator, keys, closures.constTemplate(template_index));
            }
            if (!found) {
                checkedModuleInvariant("platform relation dependency collection could not find exported app const template", .{});
            }
        },
    }
}

fn appendClosureModuleKey(
    allocator: Allocator,
    keys: *std.ArrayList(ModuleId),
    key: ModuleId,
) Allocator.Error!void {
    for (keys.items) |existing| {
        if (ModuleId.eql(existing, key)) return;
    }
    try keys.append(allocator, key);
}

const ModuleKeyAccumulator = UniqueList(ModuleId);

/// The checked type of `owner`'s source variable `var_` when its checked
/// output reaches the variable.
fn reachedSourceRoot(owner: ImportedModuleView, var_: Var) Allocator.Error!?CheckedTypeId {
    const resolved = owner.module_env.types.resolveVar(var_).var_;
    const sealed = owner.checked_types.sealed orelse checkedModuleInvariant("a source root was read from a store without sealed types", .{});
    if (!sealed.var_facts[@backingInt(resolved)].reached) return null;
    return try (try owner.bodies()).typeOf(resolved);
}

/// The checked modules a consumer of `owner`'s public API reads: the owners
/// of every type its exports, requirement signatures, exposed type
/// declarations and binding scheme codec requirements name, and the modules
/// its export closures reach.
pub fn computePublicApiDependencies(allocator: Allocator, owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!PublicApiDependencies {
    const module_key = owner.key.digest();
    const checked_types = owner.checked_types;
    const module_env = owner.module_env;
    var keys = ModuleKeyAccumulator.empty;
    defer keys.deinit(allocator);
    var type_owner_keys = ModuleKeyAccumulator.empty;
    defer type_owner_keys.deinit(allocator);

    var visited_types = std.AutoHashMap(ModuleTypeVisit, void).init(allocator);
    defer visited_types.deinit();

    // A type walk adds the owner of a type its walk names, and every name
    // the module's types use comes from a module of its sealed origins.
    if (typesNameDependencyModule(owner, resolver)) {
        for ((try owner.exportRows()).defs) |def_idx| {
            const root = try reachedSourceRoot(owner, ModuleEnv.varFrom(def_idx)) orelse {
                checkedModuleInvariant("exported def type root was not published", .{});
            };
            try appendPublicApiTypeDependencies(allocator, module_key, checked_types, root, &visited_types, resolver, &keys, &type_owner_keys);
        }

        // Platform requirement signatures are public API too: requirement
        // unification copies them into each app's store, so nominals they mention
        // (e.g. a hosted-interface type from a sibling module) must be reachable
        // through this module's type-owner dependencies (issue 9911).
        for (module_env.requires_types.items.items) |required_type| {
            const root = try reachedSourceRoot(owner, ModuleEnv.varFrom(required_type.type_anno)) orelse continue;
            try appendPublicApiTypeDependencies(allocator, module_key, checked_types, root, &visited_types, resolver, &keys, &type_owner_keys);
        }

        try appendExposedTypeDeclarationPublicApiDependencies(allocator, owner, resolver, &visited_types, &keys, &type_owner_keys);

        // Generated-codec requirements serialized on binding schemes are copied
        // into every importer that instantiates the binding (an exported def or a
        // method reached by static dispatch), and each copy is revalidated there.
        // A receiver can name a nominal the binding's type never mentions (issue
        // 11839), so its owner must be reachable through this module's
        // type-owner dependencies.
        for (module_env.binding_scheme_codec_requirements.items.items) |requirement| {
            const constraint = module_env.types.getStaticDispatchConstraintAt(requirement.constraint_index);
            for ([_]Var{ @fromBackingInt(@intCast(requirement.receiver_var)), constraint.fn_var }) |requirement_var| {
                const root = try reachedSourceRoot(owner, requirement_var) orelse {
                    checkedModuleInvariant("binding scheme codec requirement root was not published", .{});
                };
                try appendPublicApiTypeDependencies(allocator, module_key, checked_types, root, &visited_types, resolver, &keys, &type_owner_keys);
            }
        }

        const declarations = owner.platformRequiredDeclarations();
        for (0..declarations.count()) |requires_idx| {
            const declaration = declarations.get(requires_idx);
            if (declaration.requires_idx >= module_env.requires_types.items.items.len) {
                checkedModuleInvariant("platform requirement declaration has an out-of-range required index", .{});
            }
            const required_type = module_env.requires_types.items.items[declaration.requires_idx];
            const root = try reachedSourceRoot(owner, ModuleEnv.varFrom(required_type.type_anno)) orelse {
                checkedModuleInvariant("platform requirement declaration has no platform-owned checked payload", .{});
            };
            try appendPublicApiTypeDependencies(allocator, module_key, checked_types, root, &visited_types, resolver, &keys, &type_owner_keys);
        }
    }

    // A closure leaves the module only through a reference to another
    // module's value or template.
    if (try closuresNameDependencyModule(owner, resolver)) {
        var closure_dependencies = PublicApiClosureDependencyCollector.init(
            allocator,
            module_key,
            resolver,
            &(try owner.checkedTables()).checked_procedure_templates,
            (try owner.checkedTables()).callable_eval_templates.view(),
            &(try owner.checkedTables()).entry_wrappers,
            &(try owner.checkedTables()).const_templates,
            (try owner.valueRefs()),
            &(try owner.checkedTables()).top_level_procedure_bindings,
            owner.platform_required_bindings,
            &keys,
            &type_owner_keys,
        );
        defer closure_dependencies.deinit();
        try closure_dependencies.appendExportClosures(owner, try owner.exportClosures(resolver));
    }

    const checked_modules = try keys.toOwnedSlice(allocator);
    errdefer allocator.free(checked_modules);
    const type_owner_modules = try type_owner_keys.toOwnedSlice(allocator);

    return .{
        .modules = checked_modules,
        .type_owner_modules = type_owner_modules,
    };
}

/// Whether a name `owner`'s types use comes from a module that can be a
/// public API dependency: one other than `owner` and the builtin modules.
fn typesNameDependencyModule(owner: ImportedModuleView, resolver: ModuleResolver) bool {
    const sealed = owner.checked_types.sealed orelse checkedModuleInvariant("public API dependencies were demanded of a store without sealed types", .{});
    const own = owner.key.digest();
    for (sealed.origins) |origin| {
        if (origin.has_owner == 0) continue;
        if (ModuleId.eql(origin.owner, own)) continue;
        if (publicApiDependencyKeyIsKnownBuiltin(origin.owner, resolver)) continue;
        return true;
    }
    return false;
}

/// Whether one of `owner`'s exports or value references names a module that
/// can be a public API dependency: one other than `owner` and the builtin
/// modules. A platform requirement's relation reaches the app.
fn closuresNameDependencyModule(owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!bool {
    const own = owner.key.digest();
    const Names = struct {
        own: ModuleId,
        resolver: ModuleResolver,

        fn dependency(self: @This(), key: ModuleId) bool {
            return !ModuleId.eql(key, self.own) and !publicApiDependencyKeyIsKnownBuiltin(key, self.resolver);
        }

        fn binding(self: @This(), ref: ProcedureBindingRef) bool {
            return switch (ref) {
                .top_level => |top_level| self.dependency(top_level.module),
                .imported => |imported| self.dependency(imported.module),
                .hosted => |hosted| self.dependency(hosted.template.module),
                .platform_required => true,
            };
        }

        fn callable(self: @This(), template: canonical.CallableProcedureTemplateRef) bool {
            return switch (template) {
                .checked => |checked| self.dependency(checked.module),
                .synthetic => |synthetic| self.dependency(synthetic.template.module),
                .lifted => true,
            };
        }
    };
    const names: Names = .{ .own = own, .resolver = resolver };
    const rows = try owner.exportRows();
    for (rows.procedure_templates) |exported| {
        if (names.dependency(exported.template.module)) return true;
    }
    for (rows.procedure_bindings) |binding| switch (binding.body) {
        .direct_template => |direct| if (names.callable(direct.template)) return true,
        .callable_eval_template, .checked_error => {},
    };
    for (rows.const_templates) |exported| {
        if (names.dependency(exported.const_ref.module)) return true;
    }
    for ((try owner.valueRefs()).records) |record| switch (record.ref) {
        .top_level_const, .imported_const => |const_use| if (names.dependency(const_use.const_ref.module)) return true,
        .selected_hoisted_const => |selected| if (names.dependency(selected.const_use.const_ref.module)) return true,
        .top_level_proc, .imported_proc, .hosted_proc, .promoted_top_level_proc => |procedure| if (names.binding(procedure.binding)) return true,
        .platform_required_const, .platform_required_proc => return true,
        .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .platform_required_declaration, .platform_required_checked_error => {},
    };
    return false;
}

fn appendExposedTypeDeclarationPublicApiDependencies(
    allocator: Allocator,
    owner: ImportedModuleView,
    resolver: ModuleResolver,
    visited_types: *std.AutoHashMap(ModuleTypeVisit, void),
    keys: *ModuleKeyAccumulator,
    type_owner_keys: *ModuleKeyAccumulator,
) Allocator.Error!void {
    const module_env = owner.module_env;
    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.typeDeclNode() orelse continue;
        if (raw_node_idx >= module_env.store.nodes.len()) {
            checkedModuleInvariant("exposed type item points at out-of-range node", .{});
        }

        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        if (!isStatementNodeTag(module_env.store.nodes.get(node_idx).tag)) continue;

        const statement_idx: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node_idx));
        switch (module_env.store.getStatement(statement_idx)) {
            .s_alias_decl => {},
            .s_nominal_decl => if (!localNominalDeclarationIsValid(module_env, statement_idx)) continue,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => continue,
        }

        const root = try reachedSourceRoot(owner, ModuleEnv.varFrom(statement_idx)) orelse {
            checkedModuleInvariant("exposed type declaration root was not published", .{});
        };
        try appendPublicApiTypeDependencies(allocator, owner.key.digest(), owner.checked_types, root, visited_types, resolver, keys, type_owner_keys);
    }
}

/// Append the owner of every alias and nominal reachable from `root`, in
/// first-reached order. `visited` spans every root of one collection: a type
/// already walked contributes nothing new, since the key lists deduplicate.
fn appendPublicApiTypeDependencies(
    allocator: Allocator,
    module_key: ModuleId,
    checked_types: CheckedTypeStoreView,
    root: CheckedTypeId,
    visited: *std.AutoHashMap(ModuleTypeVisit, void),
    resolver: ModuleResolver,
    keys: *ModuleKeyAccumulator,
    type_owner_keys: *ModuleKeyAccumulator,
) Allocator.Error!void {
    var modules = try WalkModules.init(allocator, module_key, checked_types, resolver);
    defer modules.deinit(allocator);
    var pending: std.ArrayListUnmanaged(WalkItem) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .module = 0, .ty = root });
    while (pending.pop()) |item| {
        const module = modules.entries.items[item.module].module;
        if ((try visited.getOrPut(.{ .module = module.bytes, .ty = @backingInt(item.ty) })).found_existing) continue;

        const start = pending.items.len;
        var children = WalkChildren{ .allocator = allocator, .module = item.module, .pending = &pending };
        switch (modules.typesOf(item.module).payload(item.ty)) {
            .pending => checkedModuleInvariant("public API dependency scan reached pending checked type payload", .{}),
            .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => |variable| for (0..variable.constraints.len()) |constraint_index| {
                const constraint = variable.constraints.get(constraint_index);
                try children.add(constraint.fn_ty);
            },
            .alias => |alias| {
                try appendPublicApiOwnerDependency(
                    allocator,
                    module_key,
                    alias.owner_module.*,
                    resolver,
                    keys,
                    type_owner_keys,
                );
                try children.add(alias.backing);
                try children.addSlice(alias.args);
            },
            .nominal => |nominal| {
                try appendPublicApiOwnerDependency(
                    allocator,
                    module_key,
                    nominal.owner_module.*,
                    resolver,
                    keys,
                    type_owner_keys,
                );
                if (try modules.declaration(allocator, item.module, nominal)) |site| {
                    try pending.append(allocator, .{ .module = site.module, .ty = site.declaration.backing });
                }
                try children.addSlice(nominal.args);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try children.add(field.ty);
                }
                try children.add(record.ext);
            },
            .tuple => |items| try children.addSlice(items),
            .function => |function| {
                try children.addSlice(function.args);
                try children.add(function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try children.addSlice(tag.args);
                }
                try children.add(tag_union.ext);
            },
        }
        std.mem.reverse(WalkItem, pending.items[start..]);
    }
}

fn appendPublicApiOwnerDependency(
    allocator: Allocator,
    module_key: ModuleId,
    owner_key: ModuleId,
    resolver: ModuleResolver,
    keys: *ModuleKeyAccumulator,
    type_owner_keys: *ModuleKeyAccumulator,
) Allocator.Error!void {
    if (ModuleId.eql(owner_key, module_key)) return;
    if (keys.contains(owner_key) and type_owner_keys.contains(owner_key)) return;
    if (publicApiDependencyKeyIsKnownBuiltin(owner_key, resolver)) return;
    _ = try keys.append(allocator, owner_key);
    _ = try type_owner_keys.append(allocator, owner_key);
}

fn importedViewIdentityMatches(view: *const ImportedModuleView, origin_hash: *const [32]u8) bool {
    return base.ModuleIdentity.eql(&view.module_identity.stable_hash, origin_hash);
}

fn appendPublicApiClosureDependencyKey(
    allocator: Allocator,
    module_key: ModuleId,
    resolver: ModuleResolver,
    keys: *ModuleKeyAccumulator,
    key: ModuleId,
) Allocator.Error!void {
    if (ModuleId.eql(key, module_key)) return;
    if (keys.contains(key)) return;
    if (publicApiDependencyKeyIsKnownBuiltin(key, resolver)) return;
    _ = try keys.append(allocator, key);
}

fn publicApiDependencyKeyIsKnownBuiltin(
    key: ModuleId,
    resolver: ModuleResolver,
) bool {
    if (resolver.resolve(key)) |view| {
        return view.module_env.module_role == .builtin;
    }
    return false;
}

const PublicApiClosureDependencyCollector = struct {
    allocator: Allocator,
    module_key: ModuleId,
    resolver: ModuleResolver,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    keys: *ModuleKeyAccumulator,
    type_owner_keys: *ModuleKeyAccumulator,
    visited_templates: std.AutoHashMap(canonical.ProcedureTemplateRef, void),
    visited_consts: std.AutoHashMap(ConstRef, void),
    visited_callable_eval_templates: std.AutoHashMap(ModuleCallableEvalTemplateRef, void),

    fn init(
        allocator: Allocator,
        module_key: ModuleId,
        resolver: ModuleResolver,
        checked_templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        entry_wrappers: *const EntryWrapperTable,
        const_templates: *const ConstTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        keys: *ModuleKeyAccumulator,
        type_owner_keys: *ModuleKeyAccumulator,
    ) PublicApiClosureDependencyCollector {
        return .{
            .allocator = allocator,
            .module_key = module_key,
            .resolver = resolver,
            .checked_templates = checked_templates,
            .callable_eval_templates = callable_eval_templates,
            .entry_wrappers = entry_wrappers,
            .const_templates = const_templates,
            .resolved_value_refs = resolved_value_refs,
            .top_level_bindings = top_level_bindings,
            .platform_required_bindings = platform_required_bindings,
            .keys = keys,
            .type_owner_keys = type_owner_keys,
            .visited_templates = std.AutoHashMap(canonical.ProcedureTemplateRef, void).init(allocator),
            .visited_consts = std.AutoHashMap(ConstRef, void).init(allocator),
            .visited_callable_eval_templates = std.AutoHashMap(ModuleCallableEvalTemplateRef, void).init(allocator),
        };
    }

    fn deinit(self: *PublicApiClosureDependencyCollector) void {
        self.visited_callable_eval_templates.deinit();
        self.visited_consts.deinit();
        self.visited_templates.deinit();
    }

    /// Collect the dependency keys of every export closure of `owner`.
    fn appendExportClosures(
        self: *PublicApiClosureDependencyCollector,
        owner: ImportedModuleView,
        closures: *const ExportClosures,
    ) Allocator.Error!void {
        for (0..(try owner.exportRows()).procedure_templates.len) |index| try self.appendClosure(closures.procedureTemplate(index));
        for (0..(try owner.exportRows()).procedure_bindings.len) |index| try self.appendClosure(closures.procedureBinding(index));
        for (0..(try owner.exportRows()).const_templates.len) |index| try self.appendClosure(closures.constTemplate(index));
    }

    /// Collect every dependency key `closure` reaches. The walk is a
    /// continuation stack of pending steps, run in exactly the order a direct
    /// descent would take them, so a long call chain never becomes native call
    /// depth.
    fn appendClosure(
        self: *PublicApiClosureDependencyCollector,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        try self.runClosureSteps(.{ .closure = closure });
    }

    fn appendProcedureTemplateRef(
        self: *PublicApiClosureDependencyCollector,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        try self.runClosureSteps(.{ .procedure_template = template_ref });
    }

    fn appendTopLevelProcedureBinding(
        self: *PublicApiClosureDependencyCollector,
        binding_ref: ModuleTopLevelProcedureBindingRef,
    ) Allocator.Error!void {
        try self.runClosureSteps(.{ .top_level_binding = binding_ref });
    }

    fn appendProcedureUse(
        self: *PublicApiClosureDependencyCollector,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        try self.runClosureSteps(.{ .procedure_use = procedure });
    }

    fn runClosureSteps(
        self: *PublicApiClosureDependencyCollector,
        first: ClosureStep,
    ) Allocator.Error!void {
        var pending: std.ArrayListUnmanaged(ClosureStep) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, first);
        while (pending.pop()) |step| {
            const start = pending.items.len;
            try self.runClosureStep(step, &pending);
            std.mem.reverse(ClosureStep, pending.items[start..]);
        }
    }

    const ClosureStep = union(enum) {
        closure: ImportedTemplateClosureView,
        module_key: ModuleId,
        type_owner_key: ModuleId,
        procedure_template: canonical.ProcedureTemplateRef,
        callable_eval_template: ModuleCallableEvalTemplateRef,
        const_ref: ConstRef,
        resolved_value_refs: ResolvedValueRefTableRef,
        procedure_use: ProcedureUseTemplate,
        top_level_binding: ModuleTopLevelProcedureBindingRef,
        platform_required_binding: PlatformRequiredBindingId,
    };

    /// Run one step. Steps it leads to are appended to `pending` in the order
    /// they run.
    fn runClosureStep(
        self: *PublicApiClosureDependencyCollector,
        step: ClosureStep,
        pending: *std.ArrayListUnmanaged(ClosureStep),
    ) Allocator.Error!void {
        const gpa = self.allocator;
        switch (step) {
            .closure => |closure| {
                for (closure.checked_bodies) |value| try pending.append(gpa, .{ .module_key = value.module });
                for (closure.checked_type_roots) |value| {
                    try pending.append(gpa, .{ .module_key = value.module });
                    try pending.append(gpa, .{ .type_owner_key = value.module });
                }
                for (closure.checked_type_schemes) |value| {
                    try pending.append(gpa, .{ .module_key = value.module });
                    try pending.append(gpa, .{ .type_owner_key = value.module });
                }
                for (closure.checked_callable_bodies) |value| try pending.append(gpa, .{ .module_key = value.module });
                for (closure.checked_procedure_templates) |value| try pending.append(gpa, .{ .procedure_template = value });
                for (closure.callable_eval_templates) |value| try pending.append(gpa, .{ .callable_eval_template = value });
                for (closure.const_templates) |value| try pending.append(gpa, .{ .const_ref = value });
                for (closure.resolved_value_refs) |value| try pending.append(gpa, .{ .module_key = value.module });
                for (closure.static_dispatch_plans) |value| try pending.append(gpa, .{ .module_key = value.module });
                for (closure.interface_capabilities) |value| try pending.append(gpa, .{ .module_key = value.module });
            },
            .module_key => |key| try self.appendModuleKey(key),
            .type_owner_key => |key| try self.appendTypeOwnerModuleKey(key),
            .procedure_template => |template_ref| {
                const key = template_ref.module;
                try self.appendModuleKey(key);
                if (!ModuleId.eql(key, self.module_key)) return;

                const entry = try self.visited_templates.getOrPut(template_ref);
                if (entry.found_existing) return;
                entry.value_ptr.* = {};

                // A literal root's entry wrapper converts a closed literal of
                // this module and reads nothing beyond it.
                const index: usize = template_ref.template.rowIndex() orelse return;
                if (index >= self.checked_templates.templates.items.len) {
                    checkedModuleInvariant("public API closure dependency referenced missing local procedure template", .{});
                }
                const template = self.checked_templates.get(template_ref.template);
                if (template.proc_base != template_ref.proc_base) {
                    checkedModuleInvariant("public API closure dependency procedure template ref disagreed with template row", .{});
                }
                try pending.append(gpa, .{ .resolved_value_refs = template.resolved_value_refs });
            },
            .callable_eval_template => |template_ref| {
                try self.appendModuleKey(template_ref.module);
                if (!ModuleId.eql(template_ref.module, self.module_key)) return;

                const entry = try self.visited_callable_eval_templates.getOrPut(template_ref);
                if (entry.found_existing) return;
                entry.value_ptr.* = {};

                const index: usize = @backingInt(template_ref.template);
                if (index >= self.callable_eval_templates.templates.len) {
                    checkedModuleInvariant("public API closure dependency referenced missing callable-eval template", .{});
                }
                const template = self.callable_eval_templates.get(template_ref.template);
                const wrapper = entryWrapperForRoot(self.entry_wrappers, template.root);
                try pending.append(gpa, .{ .procedure_template = wrapper.template });
            },
            .const_ref => |const_ref| {
                try self.appendModuleKey(const_ref.module);
                if (!ModuleId.eql(const_ref.module, self.module_key)) return;

                const entry = try self.visited_consts.getOrPut(const_ref);
                if (entry.found_existing) return;
                entry.value_ptr.* = {};

                // An unimplemented declaration has no value and pulls in no
                // further dependencies.
                if (constEvalTemplate(self.const_templates, const_ref)) |eval| {
                    try pending.append(gpa, .{ .resolved_value_refs = eval.resolved_value_refs });
                    try pending.append(gpa, .{ .procedure_template = eval.entry_template });
                }
            },
            .resolved_value_refs => |table| {
                const end = table.start + table.len;
                if (end > self.resolved_value_refs.template_refs.len) {
                    checkedModuleInvariant("public API closure resolved-ref span was outside table", .{});
                }
                for (self.resolved_value_refs.template_refs[table.start..end]) |ref_id| {
                    const raw = @backingInt(ref_id);
                    if (raw >= self.resolved_value_refs.records.len) {
                        checkedModuleInvariant("public API closure resolved-ref id was outside table", .{});
                    }
                    switch (self.resolved_value_refs.records[raw].ref) {
                        .top_level_const,
                        .imported_const,
                        => |const_use| try pending.append(gpa, .{ .const_ref = const_use.const_ref }),
                        .selected_hoisted_const => |selected| try pending.append(gpa, .{ .const_ref = selected.const_use.const_ref }),
                        .top_level_proc,
                        .imported_proc,
                        .hosted_proc,
                        .promoted_top_level_proc,
                        => |procedure| try pending.append(gpa, .{ .procedure_use = procedure }),
                        .platform_required_const => |required| {
                            try pending.append(gpa, .{ .const_ref = required.const_use.const_ref });
                            try pending.append(gpa, .{ .platform_required_binding = required.binding });
                        },
                        .platform_required_proc => |required| {
                            try pending.append(gpa, .{ .procedure_use = required.procedure });
                            try pending.append(gpa, .{ .platform_required_binding = required.binding });
                        },
                        .local_param,
                        .local_value,
                        .local_mutable_version,
                        .pattern_binder,
                        .local_proc,
                        .platform_required_declaration,
                        .platform_required_checked_error,
                        => {},
                    }
                }
            },
            .procedure_use => |procedure| switch (procedure.binding) {
                .top_level => |binding_ref| try pending.append(gpa, .{ .top_level_binding = binding_ref }),
                .imported => |imported| try self.appendModuleKey(imported.module),
                .hosted => |hosted| try pending.append(gpa, .{ .procedure_template = hosted.template }),
                .platform_required => |required| try self.appendModuleKey(required.module),
            },
            .top_level_binding => |binding_ref| {
                try self.appendModuleKey(binding_ref.module);
                if (!ModuleId.eql(binding_ref.module, self.module_key)) return;

                switch (self.top_level_bindings.get(binding_ref.binding).body) {
                    .direct_template => |direct| switch (direct.template) {
                        .checked => |checked| try pending.append(gpa, .{ .procedure_template = checked }),
                        .synthetic => |synthetic| try pending.append(gpa, .{ .procedure_template = synthetic.template }),
                        .lifted => checkedModuleInvariant("public API closure reached lifted procedure template before mono", .{}),
                    },
                    .checked_error => {},
                    .callable_eval_template => |template| try pending.append(gpa, .{ .callable_eval_template = .{
                        .module = self.module_key,
                        .template = template,
                    } }),
                }
            },
            .platform_required_binding => |binding_id| {
                const binding = self.platform_required_bindings.lookupByBindingId(@backingInt(binding_id)) orelse {
                    checkedModuleInvariant("public API closure referenced missing platform-required binding", .{});
                };
                try pending.append(gpa, .{ .closure = self.platform_required_bindings.relationClosure(binding) });
            },
        }
    }

    fn appendModuleKey(
        self: *PublicApiClosureDependencyCollector,
        key: ModuleId,
    ) Allocator.Error!void {
        try appendPublicApiClosureDependencyKey(
            self.allocator,
            self.module_key,
            self.resolver,
            self.keys,
            key,
        );
    }

    fn appendTypeOwnerModuleKey(
        self: *PublicApiClosureDependencyCollector,
        key: ModuleId,
    ) Allocator.Error!void {
        try appendPublicApiClosureDependencyKey(
            self.allocator,
            self.module_key,
            self.resolver,
            self.type_owner_keys,
            key,
        );
    }
};

/// A type of one module, which a walk over several modules' types visits
/// once.
const ModuleTypeVisit = struct {
    module: [32]u8,
    ty: u32,
};

const LoweringVisibilityBuilder = struct {
    allocator: Allocator,
    module_key: ModuleId,
    checked_types: CheckedTypeStoreView,
    resolver: ModuleResolver,
    keys: ModuleKeyAccumulator = .empty,
    /// Every key `appendKey` has settled. The type walk names an owner at
    /// every alias and nominal it reaches, so each owner settles once
    /// rather than once per reference.
    settled_keys: std.AutoHashMapUnmanaged(CheckedModuleDigest, void) = .empty,
    visited_types: std.AutoHashMap(ModuleTypeVisit, void),
    visited_public_api: std.AutoHashMap(CheckedModuleDigest, void),

    fn init(
        allocator: Allocator,
        module_key: ModuleId,
        checked_types: CheckedTypeStoreView,
        resolver: ModuleResolver,
    ) LoweringVisibilityBuilder {
        return .{
            .allocator = allocator,
            .module_key = module_key,
            .checked_types = checked_types,
            .resolver = resolver,
            .visited_types = std.AutoHashMap(ModuleTypeVisit, void).init(allocator),
            .visited_public_api = std.AutoHashMap(CheckedModuleDigest, void).init(allocator),
        };
    }

    fn deinit(self: *LoweringVisibilityBuilder) void {
        self.settled_keys.deinit(self.allocator);
        self.visited_public_api.deinit();
        self.visited_types.deinit();
        self.keys.deinit(self.allocator);
    }

    fn finish(self: *LoweringVisibilityBuilder) Allocator.Error!LoweringVisibility {
        const module_ids = try self.keys.toOwnedSlice(self.allocator);
        std.mem.sort(ModuleId, module_ids, {}, checkedModuleKeyLessThan);
        return .{ .module_ids = module_ids };
    }

    /// Make `key` visible along with the public API dependencies of every
    /// module that becomes visible. The keys are sorted by `finish`, so
    /// the work list's order does not matter.
    fn appendKey(self: *LoweringVisibilityBuilder, key: ModuleId) Allocator.Error!void {
        var pending: std.ArrayListUnmanaged(ModuleId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, key);
        while (pending.pop()) |next| {
            if (ModuleId.eql(next, self.module_key)) continue;
            const settled = try self.settled_keys.getOrPut(self.allocator, next);
            if (settled.found_existing) continue;
            if (self.viewByKey(next)) |view| {
                if (view.module_env.module_role == .builtin) continue;
            }
            _ = try self.keys.append(self.allocator, next);
            try self.pushPublicApiDependencies(next, &pending);
        }
    }

    fn appendPublicApiDependenciesForKey(self: *LoweringVisibilityBuilder, key: ModuleId) Allocator.Error!void {
        var dependencies: std.ArrayListUnmanaged(ModuleId) = .empty;
        defer dependencies.deinit(self.allocator);
        try self.pushPublicApiDependencies(key, &dependencies);
        for (dependencies.items) |dependency| try self.appendKey(dependency);
    }

    /// Queue the public API dependencies of `key` the first time it is seen.
    fn pushPublicApiDependencies(
        self: *LoweringVisibilityBuilder,
        key: ModuleId,
        pending: *std.ArrayListUnmanaged(ModuleId),
    ) Allocator.Error!void {
        if (ModuleId.eql(key, self.module_key)) return;
        const entry = try self.visited_public_api.getOrPut(key);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};

        const view = self.viewByKey(key) orelse {
            checkedModuleInvariant("lowering visibility referenced a checked module its resolver does not resolve", .{});
        };
        const dependencies = try view.publicApiDependencies(self.resolver);
        try pending.appendSlice(self.allocator, dependencies.modules);
        try pending.appendSlice(self.allocator, dependencies.type_owner_modules);
    }

    fn appendRootRequest(self: *LoweringVisibilityBuilder, request: RootRequest) Allocator.Error!void {
        try self.appendTypeRoot(request.checked_type);
    }

    /// Make visible the owner of every type reachable from `root`, walking
    /// each type once from an explicit work list. A nominal's backing is
    /// walked in its declaring module.
    fn appendTypeRoot(self: *LoweringVisibilityBuilder, root: CheckedTypeId) Allocator.Error!void {
        var modules = try WalkModules.init(self.allocator, self.module_key, self.checked_types, self.resolver);
        defer modules.deinit(self.allocator);
        var pending: std.ArrayListUnmanaged(WalkItem) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .module = 0, .ty = root });
        while (pending.pop()) |item| {
            const module = modules.entries.items[item.module].module;
            const entry = try self.visited_types.getOrPut(.{ .module = module.bytes, .ty = @backingInt(item.ty) });
            if (entry.found_existing) continue;
            entry.value_ptr.* = {};

            if (item.module != 0) try self.appendKey(module);
            try self.appendTypePayload(&modules, item, &pending);
        }
    }

    fn appendTypePayload(
        self: *LoweringVisibilityBuilder,
        modules: *WalkModules,
        item: WalkItem,
        pending: *std.ArrayListUnmanaged(WalkItem),
    ) Allocator.Error!void {
        const gpa = self.allocator;
        var children = WalkChildren{ .allocator = gpa, .module = item.module, .pending = pending };
        switch (modules.typesOf(item.module).payload(item.ty)) {
            .pending => checkedModuleInvariant("lowering visibility type traversal reached pending payload", .{}),
            .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => |variable| for (0..variable.constraints.len()) |constraint_index| {
                const constraint = variable.constraints.get(constraint_index);
                try children.add(constraint.fn_ty);
            },
            .alias => |alias| {
                try self.appendKey(alias.owner_module.*);
                try children.add(alias.backing);
                try children.addSlice(alias.args);
            },
            .nominal => |nominal| {
                try self.appendKey(nominal.owner_module.*);
                if (try modules.declaration(gpa, item.module, nominal)) |site| {
                    try pending.append(gpa, .{ .module = site.module, .ty = site.declaration.backing });
                }
                try children.addSlice(nominal.args);
                try children.addSlice(nominal.padding_field_types);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    if (field.kind.undeterminedVariable()) |variable| try children.add(variable);
                    try children.add(field.ty);
                }
                try children.add(record.ext);
            },
            .tuple => |items| try children.addSlice(items),
            .function => |function| {
                try children.addSlice(function.args);
                try children.add(function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try children.addSlice(tag.args);
                }
                try children.add(tag_union.ext);
            },
        }
    }

    fn viewByKey(self: *LoweringVisibilityBuilder, key: ModuleId) ?ImportedModuleView {
        return self.resolver.resolve(key);
    }
};

/// The checked modules lowering `owner`'s roots reads: its direct imports,
/// its public API dependencies, the owners of its root types, the modules
/// its roots and exports reach, the app modules its platform requirement
/// bindings reach, and the public API dependencies of each of those.
pub fn computeLoweringVisibility(allocator: Allocator, owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!LoweringVisibility {
    const module_key = owner.key.digest();
    var builder = LoweringVisibilityBuilder.init(allocator, module_key, owner.checked_types, resolver);
    defer builder.deinit();

    const public_api_dependencies = try owner.publicApiDependencies(resolver);
    for (owner.direct_import_module_keys) |key| try builder.appendKey(key.digest());
    for (public_api_dependencies.modules) |key| try builder.appendKey(key);
    for (public_api_dependencies.type_owner_modules) |key| try builder.appendKey(key);
    for ((try owner.rootRequests()).requests) |request| try builder.appendRootRequest(request);

    var closure_dependencies = PublicApiClosureDependencyCollector.init(
        allocator,
        module_key,
        resolver,
        &(try owner.checkedTables()).checked_procedure_templates,
        (try owner.checkedTables()).callable_eval_templates.view(),
        &(try owner.checkedTables()).entry_wrappers,
        &(try owner.checkedTables()).const_templates,
        (try owner.valueRefs()),
        &(try owner.checkedTables()).top_level_procedure_bindings,
        owner.platform_required_bindings,
        &builder.keys,
        &builder.keys,
    );
    defer closure_dependencies.deinit();

    for ((try owner.rootRequests()).requests) |request| {
        if (request.procedure_template) |template| try closure_dependencies.appendProcedureTemplateRef(template);
        if (request.procedure_binding) |binding| try closure_dependencies.appendTopLevelProcedureBinding(.{
            .module = module_key,
            .binding = binding,
        });
        if (request.procedure_use) |procedure| try closure_dependencies.appendProcedureUse(procedure);
    }

    try closure_dependencies.appendExportClosures(owner, try owner.exportClosures(resolver));

    for (owner.platform_required_bindings.bindings) |binding| {
        const relation_view = resolver.resolve(binding.app_value.module) orelse {
            checkedModuleInvariant("lowering visibility relation binding referenced unavailable relation module", .{});
        };
        var relation_keys = std.ArrayList(ModuleId).empty;
        defer relation_keys.deinit(allocator);
        try appendPlatformRelationDependencyModuleKeysFromView(
            allocator,
            &relation_keys,
            relation_view,
            resolver,
            binding,
            owner.platform_required_bindings.relationClosure(binding),
        );
        for (relation_keys.items) |key| try builder.appendKey(key);
    }

    var visibility_index: usize = 0;
    while (visibility_index < builder.keys.set.count()) : (visibility_index += 1) {
        try builder.appendPublicApiDependenciesForKey(builder.keys.set.keys()[visibility_index]);
    }

    return try builder.finish();
}

fn dependencyViewByKey(
    key: ModuleId,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) ?*const ImportedModuleView {
    for (imports) |*import_module| {
        if (import_module.key.digest().eql(key)) return &import_module.view;
    }
    for (available_modules) |*view| {
        if (view.key.digest().eql(key)) return view;
    }
    for (relation_modules) |*view| {
        if (view.key.digest().eql(key)) return view;
    }
    return null;
}

/// Public `ExportedProcedureTemplate` declaration.
pub const ExportedProcedureTemplate = struct {
    def: CIR.Def.Idx,
    source_scheme: CheckedTypeSchemeId,
    template: canonical.ProcedureTemplateRef,
};

fn buildImportedTemplateClosure(
    context: ImportedTemplateClosureContext,
    template_ref: canonical.ProcedureTemplateRef,
    template: CheckedProcedureTemplate,
) Allocator.Error!ImportedTemplateClosureView {
    var builder = ImportedTemplateClosureBuilder.init(context);
    defer builder.deinit();

    try builder.appendInterfaceCapabilities(.{ .module = context.module_key.digest() });
    try builder.appendTemplate(template_ref, template);

    return try builder.finish();
}

/// Insertion-ordered set; `append` reports whether the value was new.
fn UniqueList(comptime T: type) type {
    return struct {
        set: std.AutoArrayHashMapUnmanaged(T, void) = .empty,

        const Self = @This();
        const empty: Self = .{};

        fn append(self: *Self, allocator: Allocator, value: T) Allocator.Error!bool {
            return !(try self.set.getOrPut(allocator, value)).found_existing;
        }

        fn contains(self: *const Self, value: T) bool {
            return self.set.contains(value);
        }

        fn toOwnedSlice(self: *Self, allocator: Allocator) Allocator.Error![]T {
            return try allocator.dupe(T, self.set.keys());
        }

        fn deinit(self: *Self, allocator: Allocator) void {
            self.set.deinit(allocator);
            self.* = .{};
        }
    };
}

/// The tables an exported closure is collected from, shared by every closure
/// built for one module.
const ImportedTemplateClosureContext = struct {
    allocator: Allocator,
    module_key: CheckedModuleKey,
    checked_types: CheckedTypeStoreView,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_template_table: CallableEvalTemplateTableView,
    entry_wrappers: *const EntryWrapperTable,
    const_templates_table: *const ConstTemplateTable,
    resolved_value_refs_table: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    resolver: ModuleResolver,

    fn fromView(allocator: Allocator, owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!ImportedTemplateClosureContext {
        return .{
            .allocator = allocator,
            .module_key = owner.key,
            .checked_types = owner.checked_types,
            .checked_templates = &(try owner.checkedTables()).checked_procedure_templates,
            .callable_eval_template_table = (try owner.checkedTables()).callable_eval_templates.view(),
            .entry_wrappers = &(try owner.checkedTables()).entry_wrappers,
            .const_templates_table = &(try owner.checkedTables()).const_templates,
            .resolved_value_refs_table = (try owner.valueRefs()),
            .top_level_bindings = &(try owner.checkedTables()).top_level_procedure_bindings,
            .platform_required_bindings = owner.platform_required_bindings,
            .resolver = resolver,
        };
    }
};

/// The template closure of every row of a module's export tables, parallel
/// to each table's rows. A per-module analysis
/// (`ModuleAnalyses.exportClosures`).
pub const ExportClosures = struct {
    pool: ClosurePool = .empty,
    procedure_templates: []StoredImportedTemplateClosure = &.{},
    procedure_bindings: []StoredImportedTemplateClosure = &.{},
    const_templates: []StoredImportedTemplateClosure = &.{},

    /// The closure of row `index` of the module's exported procedure templates.
    pub fn procedureTemplate(self: *const ExportClosures, index: usize) ImportedTemplateClosureView {
        return self.pool.reconstruct(self.procedure_templates[index]);
    }

    /// The closure of row `index` of the module's exported procedure bindings.
    pub fn procedureBinding(self: *const ExportClosures, index: usize) ImportedTemplateClosureView {
        return self.pool.reconstruct(self.procedure_bindings[index]);
    }

    /// The closure of row `index` of the module's exported const templates.
    pub fn constTemplate(self: *const ExportClosures, index: usize) ImportedTemplateClosureView {
        return self.pool.reconstruct(self.const_templates[index]);
    }

    pub fn destroy(self: *ExportClosures, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.procedure_templates);
        allocator.free(self.procedure_bindings);
        allocator.free(self.const_templates);
        allocator.destroy(self);
    }
};

/// The template closures of `owner`'s export rows.
pub fn computeExportClosures(allocator: Allocator, owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!ExportClosures {
    const context = try ImportedTemplateClosureContext.fromView(allocator, owner, resolver);
    var result = ExportClosures{};
    errdefer {
        result.pool.deinit(allocator);
        allocator.free(result.procedure_templates);
        allocator.free(result.procedure_bindings);
        allocator.free(result.const_templates);
    }
    const templates = (try owner.exportRows()).procedure_templates;
    result.procedure_templates = try allocator.alloc(StoredImportedTemplateClosure, templates.len);
    @memset(result.procedure_templates, .{});
    for (templates, result.procedure_templates) |exported, *out| {
        out.* = try result.pool.commit(allocator, try buildImportedTemplateClosure(context, exported.template, (try owner.checkedTables()).checked_procedure_templates.get(exported.template.template)));
    }
    const bindings = (try owner.exportRows()).procedure_bindings;
    result.procedure_bindings = try allocator.alloc(StoredImportedTemplateClosure, bindings.len);
    @memset(result.procedure_bindings, .{});
    for (bindings, result.procedure_bindings) |binding, *out| {
        out.* = try result.pool.commit(allocator, try buildProcedureBindingClosure(context, binding.body));
    }
    const consts = (try owner.exportRows()).const_templates;
    result.const_templates = try allocator.alloc(StoredImportedTemplateClosure, consts.len);
    @memset(result.const_templates, .{});
    for (consts, result.const_templates) |exported, *out| {
        out.* = try result.pool.commit(allocator, try buildImportedConstTemplateClosure(context, exported.const_ref));
    }
    return result;
}

/// The evaluation template of a constant `const_templates` holds, or null
/// for a constant that has no value.
fn constEvalTemplate(const_templates: *const ConstTemplateTable, const_ref: ConstRef) ?ConstEvalTemplate {
    return switch (const_templates.get(const_ref).state) {
        .eval_template => |eval| eval,
        .unimplemented => null,
        .reserved => checkedModuleInvariant("a closure reached an unsealed const template", .{}),
    };
}

const ImportedTemplateClosureBuilder = struct {
    context: ImportedTemplateClosureContext,
    checked_bodies: UniqueList(ModuleCheckedBodyRef) = .empty,
    checked_type_roots: UniqueList(ModuleCheckedTypeRef) = .empty,
    checked_type_schemes: UniqueList(ModuleCheckedTypeSchemeRef) = .empty,
    checked_callable_bodies: UniqueList(ModuleCheckedCallableBodyRef) = .empty,
    checked_procedure_templates: UniqueList(ModuleProcedureTemplateRef) = .empty,
    callable_eval_templates: UniqueList(ModuleCallableEvalTemplateRef) = .empty,
    const_templates: UniqueList(ConstRef) = .empty,
    resolved_value_refs: UniqueList(ModuleResolvedValueRefTableRef) = .empty,
    static_dispatch_plans: UniqueList(ModuleStaticDispatchPlanTableRef) = .empty,
    method_registry_entries: UniqueList(MethodRegistryEntryRef) = .empty,
    interface_capabilities: UniqueList(ModuleInterfaceCapabilitiesRef) = .empty,

    fn init(context: ImportedTemplateClosureContext) ImportedTemplateClosureBuilder {
        return .{ .context = context };
    }

    fn deinit(self: *ImportedTemplateClosureBuilder) void {
        inline for (closure_fields) |name| @field(self, name).deinit(self.context.allocator);
    }

    /// Move every collected list into an owned closure view.
    fn finish(self: *ImportedTemplateClosureBuilder) Allocator.Error!ImportedTemplateClosureView {
        var closure: ImportedTemplateClosureView = .{};
        errdefer deinitImportedTemplateClosure(self.context.allocator, &closure);
        inline for (closure_fields) |name| {
            @field(closure, name) = try @field(self, name).toOwnedSlice(self.context.allocator);
        }
        return closure;
    }

    fn appendTemplate(
        self: *ImportedTemplateClosureBuilder,
        template_ref: canonical.ProcedureTemplateRef,
        template: CheckedProcedureTemplate,
    ) Allocator.Error!void {
        try self.runClosureSteps(.{ .template = .{ .ref = template_ref, .template = template } });
    }

    /// One pending closure step. A callable-eval binding's closure reaches
    /// further templates, so steps run from an explicit continuation stack,
    /// in exactly the order a direct descent would run them.
    const ClosureStep = union(enum) {
        template: struct { ref: canonical.ProcedureTemplateRef, template: CheckedProcedureTemplate },
        direct_dependency: ResolvedValueRef,
        callable_eval_template: CallableEvalTemplateId,
        /// Record a callable-eval template once its entry template's closure
        /// is complete.
        callable_eval_template_done: CallableEvalTemplateId,
    };

    fn runClosureSteps(self: *ImportedTemplateClosureBuilder, first: ClosureStep) Allocator.Error!void {
        var pending: std.ArrayListUnmanaged(ClosureStep) = .empty;
        defer pending.deinit(self.context.allocator);
        try pending.append(self.context.allocator, first);
        while (pending.pop()) |step| {
            const start = pending.items.len;
            try self.runClosureStep(step, &pending);
            std.mem.reverse(ClosureStep, pending.items[start..]);
        }
    }

    /// Run one step; the steps it leads to are appended in the order they run.
    fn runClosureStep(
        self: *ImportedTemplateClosureBuilder,
        step: ClosureStep,
        pending: *std.ArrayListUnmanaged(ClosureStep),
    ) Allocator.Error!void {
        switch (step) {
            .template => |entry| {
                const template = entry.template;
                if (!try self.checked_procedure_templates.append(self.context.allocator, entry.ref)) return;

                switch (template.body) {
                    .checked_body => |body| try self.appendCheckedBody(body),
                    .intrinsic_wrapper,
                    .entry_wrapper,
                    .literal_root,
                    .unimplemented,
                    => {},
                }
                try self.appendCheckedTypeRoot(template.checked_fn_root);
                try self.appendCheckedTypeScheme(template.checked_fn_scheme);
                try self.appendResolvedValueRefs(template.resolved_value_refs);
                try self.appendStaticDispatchPlans(template.static_dispatch_plans);
                try self.appendDirectProcedureDependencies(template.resolved_value_refs, pending);
            },
            .direct_dependency => |resolved| {
                if (try self.appendImportedTemplateClosureForResolvedRef(resolved)) return;
                if (try self.appendPlatformRequiredRelationClosureForResolvedRef(resolved)) return;
                if (self.callableEvalBindingForResolvedRef(resolved)) |template_id| {
                    return try pending.append(self.context.allocator, .{ .callable_eval_template = template_id });
                }
                if (self.templateForResolvedValueRef(resolved)) |dependency_ref| {
                    _ = try self.checked_procedure_templates.append(self.context.allocator, dependency_ref);
                }
                if (self.constRefForResolvedValueRef(resolved)) |dependency_ref| {
                    _ = try self.const_templates.append(self.context.allocator, dependency_ref);
                }
            },
            .callable_eval_template => |template_id| {
                const template = self.context.callable_eval_template_table.get(template_id);
                const wrapper = entryWrapperForRoot(self.context.entry_wrappers, template.root);
                const entry_template = self.context.checked_templates.get(wrapper.template.template);

                try self.appendCheckedTypeRoot(template.checked_fn_root);
                try self.appendCheckedTypeScheme(template.source_scheme);
                try pending.append(self.context.allocator, .{ .template = .{ .ref = wrapper.template, .template = entry_template } });
                try pending.append(self.context.allocator, .{ .callable_eval_template_done = template_id });
            },
            .callable_eval_template_done => |template_id| {
                _ = try self.callable_eval_templates.append(self.context.allocator, .{
                    .module = self.context.module_key.digest(),
                    .template = template_id,
                });
            },
        }
    }

    fn appendCheckedBody(self: *ImportedTemplateClosureBuilder, body: CIR.Expr.Idx) Allocator.Error!void {
        const ref = ModuleCheckedBodyRef{ .module = self.context.module_key.digest(), .body = body };
        _ = try self.checked_bodies.append(self.context.allocator, ref);
    }

    fn appendCheckedTypeRoot(self: *ImportedTemplateClosureBuilder, ty: CheckedTypeId) Allocator.Error!void {
        const ref = ModuleCheckedTypeRef{ .module = self.context.module_key.digest(), .ty = ty };
        _ = try self.checked_type_roots.append(self.context.allocator, ref);
    }

    fn appendCheckedTypeScheme(
        self: *ImportedTemplateClosureBuilder,
        scheme: CheckedTypeSchemeId,
    ) Allocator.Error!void {
        std.debug.assert(self.context.checked_types.scheme(scheme).id == scheme);
        const ref = ModuleCheckedTypeSchemeRef{ .module = self.context.module_key.digest(), .scheme = scheme };
        _ = try self.checked_type_schemes.append(self.context.allocator, ref);
    }

    fn appendResolvedValueRefs(
        self: *ImportedTemplateClosureBuilder,
        table: ResolvedValueRefTableRef,
    ) Allocator.Error!void {
        if (table.len == 0) return;
        const ref = ModuleResolvedValueRefTableRef{ .module = self.context.module_key.digest(), .table = table };
        _ = try self.resolved_value_refs.append(self.context.allocator, ref);
    }

    fn appendStaticDispatchPlans(
        self: *ImportedTemplateClosureBuilder,
        table: StaticDispatchPlanTableRef,
    ) Allocator.Error!void {
        if (table.len == 0) return;
        const ref = ModuleStaticDispatchPlanTableRef{ .module = self.context.module_key.digest(), .table = table };
        _ = try self.static_dispatch_plans.append(self.context.allocator, ref);
    }

    fn appendInterfaceCapabilities(
        self: *ImportedTemplateClosureBuilder,
        ref: ModuleInterfaceCapabilitiesRef,
    ) Allocator.Error!void {
        _ = try self.interface_capabilities.append(self.context.allocator, ref);
    }

    fn appendImportedTemplateClosure(
        self: *ImportedTemplateClosureBuilder,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        inline for (closure_fields) |name| {
            for (@field(closure, name)) |value| _ = try @field(self, name).append(self.context.allocator, value);
        }
    }

    /// Queue a direct-dependency step for each resolved ref, in order.
    fn appendDirectProcedureDependencies(
        self: *ImportedTemplateClosureBuilder,
        table: ResolvedValueRefTableRef,
        pending: *std.ArrayListUnmanaged(ClosureStep),
    ) Allocator.Error!void {
        const end = table.start + table.len;
        if (end > self.context.resolved_value_refs_table.template_refs.len) checkedModuleInvariant("checked template resolved-ref span was outside table", .{});
        for (self.context.resolved_value_refs_table.template_refs[table.start..end]) |ref_id| {
            const raw = @backingInt(ref_id);
            if (raw >= self.context.resolved_value_refs_table.records.len) checkedModuleInvariant("checked template resolved-ref id was outside table", .{});
            try pending.append(self.context.allocator, .{ .direct_dependency = self.context.resolved_value_refs_table.records[raw].ref });
        }
    }

    fn appendImportedTemplateClosureForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) Allocator.Error!bool {
        return switch (ref) {
            .imported_const => |const_use| blk: {
                _ = try self.const_templates.append(self.context.allocator, const_use.const_ref);
                break :blk true;
            },
            .imported_proc => |proc_use| blk: {
                const imported = switch (proc_use.binding) {
                    .imported => |imported| imported,
                    .top_level,
                    .hosted,
                    .platform_required,
                    => checkedModuleInvariant("imported procedure ref did not carry imported binding", .{}),
                };
                const binding = try self.importedProcedureBinding(imported);
                try self.appendImportedProcedureBindingDependency(binding);
                break :blk true;
            },
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .top_level_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => false,
        };
    }

    fn appendImportedProcedureBindingDependency(
        self: *ImportedTemplateClosureBuilder,
        binding: ImportedProcedureBindingView,
    ) Allocator.Error!void {
        switch (binding.body) {
            .direct_template => |direct| {
                const template_ref = checkedTemplateFromCallableTemplateForClosure(direct.template) orelse {
                    checkedModuleInvariant("imported procedure binding referenced a post-check template before mono", .{});
                };
                _ = try self.checked_procedure_templates.append(self.context.allocator, template_ref);
            },
            .checked_error => {},
            .callable_eval_template => |template_id| {
                _ = try self.callable_eval_templates.append(self.context.allocator, .{
                    .module = binding.binding.module,
                    .template = template_id,
                });
            },
        }
    }

    fn importedProcedureBinding(
        self: *ImportedTemplateClosureBuilder,
        ref: ImportedProcedureBindingRef,
    ) Allocator.Error!ImportedProcedureBindingView {
        const view = self.context.resolver.require(ref.module);
        return (try view.exportRows()).procedureBinding(ref.def, ref.pattern) orelse
            checkedModuleInvariant("imported procedure dependency had no published imported closure", .{});
    }

    fn appendPlatformRequiredRelationClosureForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) Allocator.Error!bool {
        return switch (ref) {
            .platform_required_const => |required| blk: {
                const binding = self.platformRequiredBinding(required.binding);
                switch (binding.value_use) {
                    .const_value => {},
                    .procedure_value => checkedModuleInvariant("platform-required const ref pointed at procedure binding {d}", .{@backingInt(required.binding)}),
                }
                try self.appendImportedTemplateClosure(self.context.platform_required_bindings.relationClosure(binding));
                break :blk true;
            },
            .platform_required_proc => |required| blk: {
                const binding = self.platformRequiredBinding(required.binding);
                switch (binding.value_use) {
                    .procedure_value => {},
                    .const_value => checkedModuleInvariant("platform-required procedure ref pointed at const binding {d}", .{@backingInt(required.binding)}),
                }
                try self.appendImportedTemplateClosure(self.context.platform_required_bindings.relationClosure(binding));
                break :blk true;
            },
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .promoted_top_level_proc,
            => false,
        };
    }

    fn platformRequiredBinding(
        self: *ImportedTemplateClosureBuilder,
        binding_id: PlatformRequiredBindingId,
    ) PlatformRequiredBinding {
        return self.context.platform_required_bindings.lookupByBindingId(@backingInt(binding_id)) orelse {
            checkedModuleInvariant("resolved platform-required value referenced missing binding {d}", .{@backingInt(binding_id)});
        };
    }

    fn appendConstTemplate(
        self: *ImportedTemplateClosureBuilder,
        const_ref: ConstRef,
    ) Allocator.Error!void {
        if (!try self.const_templates.append(self.context.allocator, const_ref)) return;

        if (!std.meta.eql(const_ref.module.bytes, self.context.module_key.bytes)) return;

        const scheme = self.context.checked_types.scheme(const_ref.source_scheme);
        try self.appendCheckedTypeRoot(scheme.root);
        try self.appendCheckedTypeScheme(const_ref.source_scheme);

        const eval = constEvalTemplate(self.context.const_templates_table, const_ref) orelse return;
        try self.appendResolvedValueRefs(eval.resolved_value_refs);
        try self.appendStaticDispatchPlans(eval.static_dispatch_plans);
        var pending: std.ArrayListUnmanaged(ClosureStep) = .empty;
        defer pending.deinit(self.context.allocator);
        try self.appendDirectProcedureDependencies(eval.resolved_value_refs, &pending);
        const entry_template = self.context.checked_templates.get(eval.entry_template.template);
        try pending.append(self.context.allocator, .{ .template = .{ .ref = eval.entry_template, .template = entry_template } });
        std.mem.reverse(ClosureStep, pending.items);
        while (pending.pop()) |step| {
            const start = pending.items.len;
            try self.runClosureStep(step, &pending);
            std.mem.reverse(ClosureStep, pending.items[start..]);
        }
    }

    fn templateForResolvedValueRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) ?canonical.ProcedureTemplateRef {
        const use: ProcedureUseTemplate = switch (ref) {
            .top_level_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| procedure,
            .platform_required_proc => |required| required.procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => return null,
        };
        return switch (use.binding) {
            .top_level => |binding_ref| self.templateForTopLevelBinding(binding_ref),
            .hosted => |hosted| hosted.template,
            .platform_required => checkedModuleInvariant("platform-required procedure dependency must be provided by its relation template closure", .{}),
            .imported => null,
        };
    }

    /// The callable-eval template a ref's top-level binding evaluates, if any.
    fn callableEvalBindingForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) ?CallableEvalTemplateId {
        const use: ProcedureUseTemplate = switch (ref) {
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            => return null,
        };
        const top_level = switch (use.binding) {
            .top_level => |binding| binding,
            .imported, .hosted, .platform_required => return null,
        };
        if (!std.meta.eql(top_level.module.bytes, self.context.module_key.bytes)) {
            checkedModuleInvariant("top-level callable-eval closure dependency referenced a different module", .{});
        }
        const binding = self.context.top_level_bindings.get(top_level.binding);
        return switch (binding.body) {
            .direct_template, .checked_error => null,
            .callable_eval_template => |template| template,
        };
    }

    fn constRefForResolvedValueRef(
        _: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) ?ConstRef {
        return switch (ref) {
            .top_level_const => |const_use| const_use.const_ref,
            .selected_hoisted_const => |selected| selected.const_use.const_ref,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
        };
    }

    fn templateForTopLevelBinding(
        self: *ImportedTemplateClosureBuilder,
        binding_ref: ModuleTopLevelProcedureBindingRef,
    ) ?canonical.ProcedureTemplateRef {
        if (!std.meta.eql(binding_ref.module.bytes, self.context.module_key.bytes)) {
            checkedModuleInvariant("top-level procedure closure dependency referenced a different module", .{});
        }
        const binding = self.context.top_level_bindings.get(binding_ref.binding);
        return switch (binding.body) {
            .direct_template => |direct| checkedTemplateFromCallableTemplateForClosure(direct.template),
            .callable_eval_template, .checked_error => null,
        };
    }
};

fn checkedTemplateFromCallableTemplateForClosure(
    template: canonical.CallableProcedureTemplateRef,
) ?canonical.ProcedureTemplateRef {
    return switch (template) {
        .checked => |checked| checked,
        .synthetic => |synthetic| synthetic.template,
        .lifted => null,
    };
}

fn buildImportedConstTemplateClosure(
    context: ImportedTemplateClosureContext,
    const_ref: ConstRef,
) Allocator.Error!ImportedTemplateClosureView {
    var builder = ImportedTemplateClosureBuilder.init(context);
    defer builder.deinit();

    try builder.appendInterfaceCapabilities(.{ .module = context.module_key.digest() });
    try builder.appendConstTemplate(const_ref);

    return try builder.finish();
}

pub fn deinitImportedTemplateClosure(
    allocator: Allocator,
    closure: *ImportedTemplateClosureView,
) void {
    inline for (closure_fields) |name| allocator.free(@field(closure, name));
    closure.* = .{};
}

/// Public `ImportedProcedureBindingView` declaration.
pub const ImportedProcedureBindingView = struct {
    binding: ImportedProcedureBindingRef,
    source_scheme: CheckedTypeSchemeId,
    body: ProcedureBindingBody,
    intrinsic: ?IntrinsicId = null,
    iterator_procedure: ?IteratorProcedureId = null,
    runtime_result_provenance: ?RuntimeResultProvenance,
};

fn buildProcedureBindingClosure(
    context: ImportedTemplateClosureContext,
    body: ProcedureBindingBody,
) Allocator.Error!ImportedTemplateClosureView {
    return switch (body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template_ref| buildImportedTemplateClosure(
                context,
                template_ref,
                context.checked_templates.get(template_ref.template),
            ),
            .synthetic => |synthetic| buildImportedTemplateClosure(
                context,
                synthetic.template,
                context.checked_templates.get(synthetic.template.template),
            ),
            .lifted => {
                base.invariant("checked module invariant violated: exported checked binding cannot reference lifted templates before mono", .{});
            },
        },
        .checked_error => .{},
        .callable_eval_template => |template_id| blk: {
            const template = context.callable_eval_template_table.get(template_id);
            const wrapper = entryWrapperForRoot(context.entry_wrappers, template.root);
            const entry_template = context.checked_templates.get(wrapper.template.template);

            var builder = ImportedTemplateClosureBuilder.init(context);
            defer builder.deinit();

            try builder.appendInterfaceCapabilities(.{ .module = context.module_key.digest() });
            try builder.appendCheckedTypeRoot(template.checked_fn_root);
            try builder.appendCheckedTypeScheme(template.source_scheme);
            try builder.appendTemplate(wrapper.template, entry_template);

            _ = try builder.callable_eval_templates.append(context.allocator, .{
                .module = context.module_key.digest(),
                .template = template_id,
            });

            break :blk try builder.finish();
        },
    };
}

/// Public `ConstEvalTemplate` declaration.
pub const ConstEvalTemplate = struct {
    /// The compile-time root whose body evaluates the constant.
    root: ComptimeRootKey,
    entry_template: canonical.ProcedureTemplateRef,
    source_scheme: CheckedTypeSchemeId,
    resolved_value_refs: ResolvedValueRefTableRef = .{},
    static_dispatch_plans: StaticDispatchPlanTableRef = .{},
};

/// Public `StoredConstTemplate` declaration.
pub const StoredConstTemplate = struct {
    node: ConstNodeId,
    /// The compile-time root whose evaluation stored `node`. A compilation
    /// that restores this value demands that root (design.md "Demand-Driven
    /// Compile-Time Evaluation").
    root: ComptimeRootKey,
    /// Exact producer-owned Monotype representation used to evaluate `node`.
    /// This is explicit post-check evidence, stored in `ConstStore.type_store`.
    root_type: const_store.ConstTypeId,
};

/// Public `ConstTemplateState` declaration.
pub const ConstTemplateState = union(enum) {
    reserved,
    eval_template: ConstEvalTemplate,
    /// This constant was declared with a type annotation and never given a
    /// value. It lowers to a crash wherever the constant is used.
    unimplemented: UnimplementedDeclaration,
};

/// What a constant template holds for a reader: its checked state, or the
/// value evaluation stored for it (`EvaluationOutput.storedConst`).
pub const ConstTemplateValue = union(enum) {
    reserved,
    eval_template: ConstEvalTemplate,
    stored_const: StoredConstTemplate,
    unimplemented: UnimplementedDeclaration,

    /// The value of `template` given the evaluation output of its module.
    pub fn of(template: ConstTemplate, evaluation: *const EvaluationOutput) ConstTemplateValue {
        if (evaluation.storedConst(template.owner)) |stored| return .{ .stored_const = stored };
        return switch (template.state) {
            .reserved => .reserved,
            .eval_template => |eval| .{ .eval_template = eval },
            .unimplemented => |declaration| .{ .unimplemented = declaration },
        };
    }
};

/// Public `ConstTemplate` declaration.
pub const ConstTemplate = struct {
    id: ConstTemplateId,
    owner: ConstOwner,
    source_scheme: CheckedTypeSchemeId,
    state: ConstTemplateState,
};

/// Public `ConstTemplateTable` declaration.
pub const ConstTemplateTable = struct {
    templates: std.ArrayList(ConstTemplate) = .empty,

    pub fn reserveTopLevel(
        self: *ConstTemplateTable,
        allocator: Allocator,
        module_key: CheckedModuleKey,
        module_idx: u32,
        pattern: CIR.Pattern.Idx,
        source_scheme: CheckedTypeSchemeId,
    ) Allocator.Error!ConstRef {
        return self.appendTopLevel(allocator, module_key, module_idx, pattern, source_scheme, .reserved);
    }

    /// Record a top-level constant whose declaration never received a value.
    pub fn reserveUnimplementedTopLevel(
        self: *ConstTemplateTable,
        allocator: Allocator,
        module_key: CheckedModuleKey,
        module_idx: u32,
        pattern: CIR.Pattern.Idx,
        source_scheme: CheckedTypeSchemeId,
        declaration: UnimplementedDeclaration,
    ) Allocator.Error!ConstRef {
        return self.appendTopLevel(
            allocator,
            module_key,
            module_idx,
            pattern,
            source_scheme,
            .{ .unimplemented = declaration },
        );
    }

    fn appendTopLevel(
        self: *ConstTemplateTable,
        allocator: Allocator,
        module_key: CheckedModuleKey,
        module_idx: u32,
        pattern: CIR.Pattern.Idx,
        source_scheme: CheckedTypeSchemeId,
        state: ConstTemplateState,
    ) Allocator.Error!ConstRef {
        const id: ConstTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
        const owner: ConstOwner = .{ .top_level_binding = .{
            .module_idx = module_idx,
            .pattern = pattern,
        } };
        try self.templates.append(allocator, .{
            .id = id,
            .owner = owner,
            .source_scheme = source_scheme,
            .state = state,
        });
        return .{
            .module = module_key.digest(),
            .owner = owner,
            .template = id,
            .source_scheme = source_scheme,
        };
    }

    pub fn reserveHoisted(
        self: *ConstTemplateTable,
        allocator: Allocator,
        module_key: CheckedModuleKey,
        module_idx: u32,
        root: ComptimeRootKey,
        source_scheme: CheckedTypeSchemeId,
    ) Allocator.Error!ConstRef {
        const id: ConstTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
        const owner: ConstOwner = .{ .hoisted_root = .{
            .module_idx = module_idx,
            .root = root,
        } };
        try self.templates.append(allocator, .{
            .id = id,
            .owner = owner,
            .source_scheme = source_scheme,
            .state = .reserved,
        });
        return .{
            .module = module_key.digest(),
            .owner = owner,
            .template = id,
            .source_scheme = source_scheme,
        };
    }

    pub fn fillEval(
        self: *ConstTemplateTable,
        ref: ConstRef,
        template: ConstEvalTemplate,
    ) void {
        const record = self.recordForRef(ref);
        if (!(record.source_scheme == template.source_scheme)) {
            checkedModuleInvariant("constant eval template source scheme does not match reserved ConstRef", .{});
        }
        switch (record.state) {
            .reserved => record.state = .{ .eval_template = template },
            .eval_template => checkedModuleInvariant("constant template was filled twice", .{}),
            .unimplemented => checkedModuleInvariant("constant template without a declared value was given an eval body", .{}),
        }
    }

    /// The owners of every template with a body to evaluate: the entries of
    /// the module's evaluation output (`EvaluationOutput.addConsts`).
    pub fn evaluatedOwners(self: *const ConstTemplateTable, allocator: Allocator) Allocator.Error![]ConstOwner {
        var owners: std.ArrayList(ConstOwner) = .empty;
        errdefer owners.deinit(allocator);
        for (self.templates.items) |template| switch (template.state) {
            .eval_template => try owners.append(allocator, template.owner),
            .reserved, .unimplemented => {},
        };
        return owners.toOwnedSlice(allocator);
    }

    pub fn get(self: *const ConstTemplateTable, ref: ConstRef) ConstTemplate {
        const idx = @backingInt(ref.template);
        if (idx >= self.templates.items.len) {
            checkedModuleInvariant("ConstRef template id is out of range", .{});
        }
        const template = self.templates.items[idx];
        if (!std.meta.eql(template.owner, ref.owner) or
            !(template.source_scheme == ref.source_scheme))
        {
            checkedModuleInvariant("ConstRef does not match constant template row", .{});
        }
        return template;
    }

    pub fn verifySealed(self: *const ConstTemplateTable) void {
        if (builtin.mode != .debug) return;

        for (self.templates.items, 0..) |template, i| {
            std.debug.assert(@backingInt(template.id) == i);
            switch (template.state) {
                // A declaration with no implementation is sealed when its
                // module is opened; there is never a value to fill in later.
                .eval_template, .unimplemented => {},
                .reserved => base.invariant(
                    "checked module invariant violated: constant template {d} was not sealed before the module was opened",
                    .{i},
                ),
            }
        }
    }

    fn recordForRef(self: *ConstTemplateTable, ref: ConstRef) *ConstTemplate {
        const idx = @backingInt(ref.template);
        if (idx >= self.templates.items.len) {
            checkedModuleInvariant("ConstRef template id is out of range", .{});
        }
        const record = &self.templates.items[idx];
        if (!std.meta.eql(record.owner, ref.owner) or
            !(record.source_scheme == ref.source_scheme))
        {
            checkedModuleInvariant("ConstRef does not match constant template row", .{});
        }
        return record;
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `ImportedConstTemplateView` declaration.
pub const ImportedConstTemplateView = struct {
    module_idx: u32,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    const_ref: ConstRef,
    source_scheme: CheckedTypeSchemeId,
    template: ConstTemplate,
};

/// A compiler invariant of checked module construction: a debug-only
/// assertion, unreachable in release builds.
pub fn checkedModuleInvariant(comptime message: []const u8, args: anytype) noreturn {
    base.invariant("checked module invariant violated: " ++ message, args);
}

fn checkedModuleKeyLessThan(_: void, a: ModuleId, b: ModuleId) bool {
    for (a.bytes, b.bytes) |left, right| {
        if (left < right) return true;
        if (left > right) return false;
    }
    return false;
}

fn constRefEql(a: ConstRef, b: ConstRef) bool {
    return a.module.eql(b.module) and
        std.meta.eql(a.owner, b.owner) and
        a.template == b.template and
        (a.source_scheme == b.source_scheme);
}

fn constRefTopLevelOwner(ref: ConstRef) ?ConstTopLevelOwner {
    return switch (ref.owner) {
        .top_level_binding => |owner| owner,
        .hoisted_root => null,
    };
}

/// Ordered compile-time debug observations owned by the checked module and
/// replayed from cache without executing their roots again.
pub const CompileTimeDebugStore = struct {
    pub const Entry = extern struct { root: ComptimeRootKey, message_start: u32, message_len: u32, _reserved: u64 = 0 };
    pub const Input = struct { root: ComptimeRootKey, message: []const u8 };
    entries: []const Entry = &.{},
    bytes: []const u8 = &.{},

    pub const Serialized = extern struct {
        entries: SerializedSlice(Entry) = .{},
        bytes: SerializedSlice(u8) = .{},
        const Serde = store_serialize.SliceStoreSerde(CompileTimeDebugStore, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn init(allocator: Allocator, inputs: []const Input) Allocator.Error!CompileTimeDebugStore {
        var byte_count: usize = 0;
        for (inputs) |input| byte_count += input.message.len;
        const entries = try allocator.alloc(Entry, inputs.len);
        errdefer allocator.free(entries);
        const bytes = try allocator.alloc(u8, byte_count);
        var offset: usize = 0;
        for (inputs, entries) |input, *entry| {
            entry.* = .{ .root = input.root, .message_start = @intCast(offset), .message_len = @intCast(input.message.len) };
            @memcpy(bytes[offset..][0..input.message.len], input.message);
            offset += input.message.len;
        }
        return .{ .entries = entries, .bytes = bytes };
    }

    pub fn validate(self: CompileTimeDebugStore) error{CorruptSerializedData}!void {
        for (self.entries) |entry| {
            if (entry.message_start > self.bytes.len or
                entry.message_len > self.bytes.len - entry.message_start) return error.CorruptSerializedData;
        }
    }

    pub fn message(self: CompileTimeDebugStore, entry: Entry) []const u8 {
        return self.bytes[entry.message_start..][0..entry.message_len];
    }

    pub const deinit = store_serialize.SliceStoreDeinit(@This()).deinit;
};

/// The checked roots each evaluated compile-time root's body reads (design.md
/// "Demand-Driven Compile-Time Evaluation"). A compilation that demands a root
/// whose value it restores from this module also demands every root listed
/// here for it, exactly as if it had lowered the root's body itself, so the
/// demanded set never depends on which values a cache already held.
///
/// Rows are dense by root id. A root that was never evaluated has no row
/// content; its payload says so.
pub const CompileTimeRootReadTable = struct {
    /// A read root, named by its module's identity bytes.
    pub const Ref = extern struct { module: [32]u8, root: ComptimeRootKey };
    /// The reads of one evaluated root, by root id.
    pub const Row = extern struct { root: ComptimeRootKey, start: u32 = 0, len: u32 = 0, _reserved: u64 = 0 };
    pub const Input = struct { root: ComptimeRootKey, reads: []const Ref };
    /// Ascending by root.
    rows: []const Row = &.{},
    refs: []const Ref = &.{},

    pub const Serialized = extern struct {
        rows: SerializedSlice(Row) = .{},
        refs: SerializedSlice(Ref) = .{},
        const Serde = store_serialize.SliceStoreSerde(CompileTimeRootReadTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    /// Keep `previous`'s rows and replace those named by `inputs`, the roots
    /// this compilation evaluated.
    pub fn merge(
        allocator: Allocator,
        previous: CompileTimeRootReadTable,
        inputs: []const Input,
    ) Allocator.Error!CompileTimeRootReadTable {
        var replaced = std.AutoHashMapUnmanaged(ComptimeRootKey, []const Ref).empty;
        defer replaced.deinit(allocator);
        for (inputs) |input| {
            const slot = try replaced.getOrPut(allocator, input.root);
            if (slot.found_existing) checkedModuleInvariant("compile-time root reads were recorded twice for one root", .{});
            slot.value_ptr.* = input.reads;
        }
        var roots: std.ArrayList(ComptimeRootKey) = .empty;
        defer roots.deinit(allocator);
        for (previous.rows) |row| if (!replaced.contains(row.root)) try roots.append(allocator, row.root);
        for (inputs) |input| try roots.append(allocator, input.root);
        std.mem.sort(ComptimeRootKey, roots.items, {}, comptimeRootIdLessThan);
        var ref_count: usize = 0;
        for (roots.items) |root| ref_count += (replaced.get(root) orelse previous.readsOf(root)).len;
        const rows = try allocator.alloc(Row, roots.items.len);
        errdefer allocator.free(rows);
        const refs = try allocator.alloc(Ref, ref_count);
        var offset: usize = 0;
        for (roots.items, rows) |root, *row| {
            const reads = replaced.get(root) orelse previous.readsOf(root);
            row.* = .{ .root = root, .start = @intCast(offset), .len = @intCast(reads.len) };
            @memcpy(refs[offset..][0..reads.len], reads);
            offset += reads.len;
        }
        return .{ .rows = rows, .refs = refs };
    }

    pub fn readsOf(self: CompileTimeRootReadTable, root: ComptimeRootKey) []const Ref {
        const index = std.sort.binarySearch(Row, self.rows, root, struct {
            fn order(key: ComptimeRootKey, item: Row) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.root));
            }
        }.order) orelse return &.{};
        const row = self.rows[index];
        return self.refs[row.start..][0..row.len];
    }

    pub fn validate(self: CompileTimeRootReadTable) error{CorruptSerializedData}!void {
        for (self.rows, 0..) |row, index| {
            if (index != 0 and @backingInt(self.rows[index - 1].root) >= @backingInt(row.root)) return error.CorruptSerializedData;
            if (row.start > self.refs.len or row.len > self.refs.len - row.start) return error.CorruptSerializedData;
        }
    }

    pub fn deinit(self: *CompileTimeRootReadTable, allocator: Allocator) void {
        allocator.free(self.rows);
        allocator.free(self.refs);
        self.* = .{};
    }
};

/// The address spaces whose compilations an evaluation output serves
/// (design.md "Compile-Time Constants").
pub const EvaluatedAddressSpace = enum(u8) {
    /// Every allocation request the evaluation made fit a 32-bit
    /// `roc_alloc`, so the output is what any address space's evaluation
    /// produces.
    any = 0,
    /// A 64-bit evaluation asked for an allocation larger than a 32-bit
    /// `roc_alloc` can be asked for and was granted it; a 32-bit program's
    /// evaluation runs out of memory there instead.
    u64_only = 1,
    /// A 32-bit evaluation asked for an allocation larger than a 32-bit
    /// `roc_alloc` can be asked for and ran out of memory there; a 64-bit
    /// program's evaluation is granted it instead.
    u32_only = 2,

    /// The kind of output an evaluation in `address_space` produces when it
    /// asks for an allocation larger than a 32-bit `roc_alloc` can be asked
    /// for: only that address space's evaluation answers it that way.
    pub fn askedPastU32(address_space: base.target.TargetUsize) EvaluatedAddressSpace {
        return switch (address_space) {
            .u64 => .u64_only,
            .u32 => .u32_only,
        };
    }

    /// Whether a compilation whose compile-time evaluation runs in
    /// `address_space` reads an output of this kind as its own.
    pub fn serves(self: EvaluatedAddressSpace, address_space: base.target.TargetUsize) bool {
        return switch (self) {
            .any => true,
            .u64_only => switch (address_space) {
                .u64 => true,
                .u32 => false,
            },
            .u32_only => switch (address_space) {
                .u64 => false,
                .u32 => true,
            },
        };
    }
};

test "an evaluation output serves the address spaces whose evaluation answers its requests the way it did" {
    try std.testing.expect(EvaluatedAddressSpace.any.serves(.u32) and EvaluatedAddressSpace.any.serves(.u64));
    inline for (.{ base.target.TargetUsize.u32, base.target.TargetUsize.u64 }) |ran_in| {
        const output = EvaluatedAddressSpace.askedPastU32(ran_in);
        try std.testing.expect(output.serves(ran_in));
        try std.testing.expect(!output.serves(switch (ran_in) {
            .u32 => .u64,
            .u64 => .u32,
        }));
    }
}

/// Whether compile-time evaluation still has to finish a module's evaluation
/// output. Process-local: a cache entry holds a finished output.
pub const EvaluationState = enum { prepared, finalized };

/// One compile-time root's evaluation output.
pub const RootOutput = struct {
    id: ComptimeRootKey,
    payload: CompileTimeRootPayload = .pending,
    /// The value a `.boxy` evaluation stored for a root holding a function
    /// value (design.md "Stored Function Values"). Only `.boxy` programs read
    /// it: to a `.lss` compilation the root stays `unevaluated`.
    boxy_value: ?StoredConstTemplate = null,
};

/// The value evaluation stored for one constant template, named by the
/// template's owner.
pub const ConstOutput = struct {
    owner: ConstOwner,
    value: ?StoredConstTemplate = null,
};

/// Everything compile-time evaluation writes for one module, and nothing
/// else: the constant store, each root's payload and stored `.boxy` value,
/// each constant template's stored value, the recorded debug observations and
/// the roots each evaluated root read. Evaluation writes no checked table.
/// Every entry is named by an id that is a function of the module's sealed
/// data alone: a root by its root id, a constant by its owner.
pub const EvaluationOutput = struct {
    const_store: ConstStore,
    /// Ascending by root id: an entry for every row of the module's root
    /// table and for every literal root its root requests evaluate.
    roots: []RootOutput = &.{},
    /// Ascending by owner (`constOwnerOrder`): an entry for every constant
    /// template with a body to evaluate.
    consts: []ConstOutput = &.{},
    debug: CompileTimeDebugStore = .{},
    root_reads: CompileTimeRootReadTable = .{},
    /// Ascending: each exhaustiveness check that needs a platform/app pairing
    /// to decide whose empirical failure evaluation already reported. A
    /// pairing does not decide it again.
    reported_sites: []CheckedExhaustivenessSiteId = &.{},
    /// Which address spaces' compilations this output serves.
    address_space: EvaluatedAddressSpace = .any,
    state: EvaluationState = .finalized,

    pub const serde_transient_fields = [_][]const u8{"state"};

    pub const Serialized = extern struct {
        const_store: ConstStore.Serialized,
        roots: SerializedSlice(RootOutput) = .{},
        consts: SerializedSlice(ConstOutput) = .{},
        debug: CompileTimeDebugStore.Serialized = .{},
        root_reads: CompileTimeRootReadTable.Serialized = .{},
        reported_sites: SerializedSlice(CheckedExhaustivenessSiteId) = .{},
        address_space: store_serialize.SerializedScalar(EvaluatedAddressSpace, .any) = .{},

        pub const root_contract: collections.serde_validation.RootContract = .{
            .Owner = EvaluationOutput,
            .owner_only_fields = &.{
                "state", // Process-local; a serialized output is finished.
            },
        };

        const Serde = store_serialize.SliceStoreSerde(EvaluationOutput, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserializeWithAllocator;

        /// Check every range the output's tables hold against themselves,
        /// once the buffer at `base_addr` that holds them is validated.
        pub fn validateContents(self: *const Serialized, base_addr: usize) error{CorruptSerializedData}!void {
            const address_space: *const u8 = @ptrCast(&self.address_space.value);
            _ = std.enums.fromInt(EvaluatedAddressSpace, address_space.*) orelse return error.CorruptSerializedData;
            try self.debug.deserialize(base_addr).validate();
            try self.root_reads.deserialize(base_addr).validate();
            const roots = self.roots.deserialize(base_addr);
            for (roots, 0..) |root, index| {
                if (index != 0 and @backingInt(roots[index - 1].id) >= @backingInt(root.id)) return error.CorruptSerializedData;
            }
        }
    };

    pub fn init(allocator: Allocator) EvaluationOutput {
        return .{ .const_store = ConstStore.init(allocator) };
    }

    pub fn deinit(self: *EvaluationOutput, allocator: Allocator) void {
        self.const_store.deinit();
        allocator.free(self.roots);
        allocator.free(self.consts);
        self.debug.deinit(allocator);
        self.root_reads.deinit(allocator);
        allocator.free(self.reported_sites);
        self.* = undefined;
    }

    /// Whether evaluation reported the empirical failure of `site`, an
    /// exhaustiveness check a pairing decides.
    pub fn reportedSite(self: *const EvaluationOutput, site: CheckedExhaustivenessSiteId) bool {
        return std.sort.binarySearch(CheckedExhaustivenessSiteId, self.reported_sites, site, struct {
            fn order(key: CheckedExhaustivenessSiteId, item: CheckedExhaustivenessSiteId) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item));
            }
        }.order) != null;
    }

    /// Record that evaluation reported the empirical failure of `site`, an
    /// exhaustiveness check a pairing decides.
    pub fn recordReportedSite(self: *EvaluationOutput, allocator: Allocator, frees_replaced: bool, site: CheckedExhaustivenessSiteId) Allocator.Error!void {
        if (self.reportedSite(site)) return;
        const index = std.sort.lowerBound(CheckedExhaustivenessSiteId, self.reported_sites, site, struct {
            fn order(key: CheckedExhaustivenessSiteId, item: CheckedExhaustivenessSiteId) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item));
            }
        }.order);
        const sites = try allocator.alloc(CheckedExhaustivenessSiteId, self.reported_sites.len + 1);
        @memcpy(sites[0..index], self.reported_sites[0..index]);
        sites[index] = site;
        @memcpy(sites[index + 1 ..], self.reported_sites[index..]);
        if (frees_replaced) allocator.free(self.reported_sites);
        self.reported_sites = sites;
    }

    fn findRoot(self: *const EvaluationOutput, id: ComptimeRootKey) ?usize {
        return std.sort.binarySearch(RootOutput, self.roots, id, struct {
            fn order(key: ComptimeRootKey, item: RootOutput) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.id));
            }
        }.order);
    }

    fn findConst(self: *const EvaluationOutput, owner: ConstOwner) ?usize {
        return std.sort.binarySearch(ConstOutput, self.consts, owner, struct {
            fn order(key: ConstOwner, item: ConstOutput) std.math.Order {
                return constOwnerOrder(key, item.owner);
            }
        }.order);
    }

    /// Root `id`'s payload: `pending` for a root evaluation has no entry for
    /// yet.
    pub fn rootPayload(self: *const EvaluationOutput, id: ComptimeRootKey) CompileTimeRootPayload {
        const index = self.findRoot(id) orelse return .pending;
        return self.roots[index].payload;
    }

    /// The value a `.boxy` evaluation stored for root `id`.
    pub fn rootBoxyValue(self: *const EvaluationOutput, id: ComptimeRootKey) ?StoredConstTemplate {
        const index = self.findRoot(id) orelse return null;
        return self.roots[index].boxy_value;
    }

    /// The value evaluation stored for the constant template `owner` names.
    pub fn storedConst(self: *const EvaluationOutput, owner: ConstOwner) ?StoredConstTemplate {
        const index = self.findConst(owner) orelse return null;
        return self.consts[index].value;
    }

    fn rootEntry(self: *EvaluationOutput, id: ComptimeRootKey) *RootOutput {
        const index = self.findRoot(id) orelse checkedModuleInvariant("a compile-time root without an evaluation output entry received a payload", .{});
        return &self.roots[index];
    }

    /// Record root `id`'s payload.
    pub fn setRootPayload(self: *EvaluationOutput, id: ComptimeRootKey, payload: CompileTimeRootPayload) void {
        self.rootEntry(id).payload = payload;
    }

    /// Record the value a `.boxy` evaluation stored for root `id`.
    pub fn setRootBoxyValue(self: *EvaluationOutput, id: ComptimeRootKey, value: StoredConstTemplate) void {
        self.rootEntry(id).boxy_value = value;
    }

    /// Record the value evaluation stored for the constant template `owner`
    /// names.
    pub fn setStoredConst(self: *EvaluationOutput, owner: ConstOwner, value: StoredConstTemplate) void {
        const index = self.findConst(owner) orelse checkedModuleInvariant("a constant template without an evaluation output entry received a stored value", .{});
        const entry = &self.consts[index];
        if (entry.value != null) checkedModuleInvariant("constant template was given a stored value twice", .{});
        entry.value = value;
    }

    /// Give every root in `entries` an entry, keeping the entries already
    /// present. `entries` holds each root with the payload it starts with.
    pub fn addRoots(self: *EvaluationOutput, allocator: Allocator, frees_replaced: bool, entries: []const RootOutput) Allocator.Error!void {
        var merged: std.ArrayList(RootOutput) = .empty;
        errdefer merged.deinit(allocator);
        try merged.appendSlice(allocator, self.roots);
        for (entries) |entry| {
            if (self.findRoot(entry.id) == null) try merged.append(allocator, entry);
        }
        if (merged.items.len == self.roots.len) {
            merged.deinit(allocator);
            return;
        }
        std.mem.sort(RootOutput, merged.items, {}, struct {
            fn lessThan(_: void, a: RootOutput, b: RootOutput) bool {
                return @backingInt(a.id) < @backingInt(b.id);
            }
        }.lessThan);
        const roots = try merged.toOwnedSlice(allocator);
        if (frees_replaced) allocator.free(self.roots);
        self.roots = roots;
    }

    /// Give every constant template `owners` names an entry awaiting its
    /// value. The output holds no constant entries yet.
    pub fn addConsts(self: *EvaluationOutput, allocator: Allocator, owners: []const ConstOwner) Allocator.Error!void {
        std.debug.assert(self.consts.len == 0);
        const consts = try allocator.alloc(ConstOutput, owners.len);
        for (consts, owners) |*entry, owner| entry.* = .{ .owner = owner };
        std.mem.sort(ConstOutput, consts, {}, struct {
            fn lessThan(_: void, a: ConstOutput, b: ConstOutput) bool {
                return constOwnerOrder(a.owner, b.owner) == .lt;
            }
        }.lessThan);
        self.consts = consts;
    }

    /// Record that evaluating one of this output's roots in
    /// `address_space` asked for an allocation larger than a 32-bit
    /// `roc_alloc` can be asked for, which only that address space's
    /// evaluation answers the way it did.
    pub fn recordAskedPastU32(self: *EvaluationOutput, address_space: base.target.TargetUsize) void {
        self.address_space = EvaluatedAddressSpace.askedPastU32(address_space);
    }

    /// Make every root no compilation evaluated await evaluation again.
    pub fn reopen(self: *EvaluationOutput) void {
        for (self.roots) |*root| {
            if (root.payload == .unevaluated) root.payload = .pending;
        }
        self.state = .prepared;
    }
};

/// The order of constant template owners in an evaluation output: top-level
/// constants by binder pattern, then hoisted constants by root id.
fn constOwnerOrder(a: ConstOwner, b: ConstOwner) std.math.Order {
    const tag_order = std.math.order(@backingInt(std.meta.activeTag(a)), @backingInt(std.meta.activeTag(b)));
    if (tag_order != .eq) return tag_order;
    return switch (a) {
        .top_level_binding => |owner| std.math.order(@backingInt(owner.pattern), @backingInt(b.top_level_binding.pattern)),
        .hoisted_root => |owner| std.math.order(@backingInt(owner.root), @backingInt(b.hoisted_root.root)),
    };
}

/// The live checked module: its environment, types, names, inference and
/// evaluation outputs, and the analyses over them.
pub const CheckedModule = struct {
    key: CheckedModuleKey,
    /// Hash of the module's source inputs: the one `key` input not otherwise
    /// held by the module.
    source_hash: [32]u8,
    /// The names the module's checked data names. Never cached: opening the
    /// module creates it.
    canonical_names: canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    checking_context_identity: CheckingContextIdentity,
    direct_import_module_keys: []CheckedModuleKey = &.{},
    /// The module's canonical IR and sealed solver store.
    module_env: ModuleEnvStorage,
    /// The module's synthesized-type store, which also holds the columns
    /// that read its sealed solver store. Never cached: opening the module
    /// creates it. Empty in a paired module, which reads its platform's
    /// (`typeStore`).
    checked_types: CheckedTypeStore = .{},
    /// What inference output beside the solved source, its checking outcome
    /// included.
    inference: InferenceOutput = .{},
    /// What compile-time evaluation wrote for the module.
    evaluation: EvaluationOutput,
    /// Owns the evaluation output of a finalized module that a compilation
    /// reopened to evaluate roots no earlier compilation demanded (see
    /// `reopenForEvaluation`). Process-local, like `pairing_arena`.
    reopened_arena: ?*base.SingleThreadArena = null,
    /// 16-byte-aligned buffer holding the stored outputs (`Serialized`) a
    /// module loaded from the disk cache or the compiler's static builtin
    /// data was opened with: its `inference` and `evaluation` alias it.
    /// `null` for a module opened right after checking, which owns both.
    serialized_backing: ?[]align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8 = null,
    /// Whether something else owns `serialized_backing`: static data, or a
    /// cache entry the module's environment storage owns.
    serialized_backing_borrowed: bool = false,
    /// Owns a paired module's evaluation output.
    pairing_arena: ?*base.SingleThreadArena = null,
    /// The platform/app pairing a paired module reads its platform
    /// through. Process-local.
    pairing: ?*PlatformPairing = null,
    /// The module's body facts, computed on first demand. Never serialized:
    /// opening the module creates them.
    body_analyses: ?*BodyAnalyses = null,
    /// The module's analyses of its own tables and the modules it reaches,
    /// computed on first demand. Never serialized; created wherever
    /// `body_analyses` is.
    module_analyses: ?*ModuleAnalyses = null,

    pub fn owningAllocator(self: *const CheckedModule) Allocator {
        if (self.pairing_arena) |arena| return arena.child_allocator;
        if (self.reopened_arena) |arena| return arena.child_allocator;
        return self.canonical_names.allocator;
    }

    /// Semantic identity of executable code, including the session's exact
    /// app binding environment. Local checked IDs retain the module's key.
    pub fn codeGenerationKey(self: *const CheckedModule) CheckedModuleKey {
        if (self.pairing_arena == null) return self.key;
        return CheckedModuleKey.computeFromSourceHash(self.source_hash, self.module_identity, self.checking_context_identity, self.direct_import_module_keys);
    }

    /// A view of the module's checked types that computes keys against the
    /// module's own name store. A paired module's view reads its
    /// platform's types through the pairing.
    pub fn typesView(self: *const CheckedModule) CheckedTypeStoreView {
        if (self.pairing) |pairing| {
            var types_view = pairing.platform.typesView();
            types_view.pairing = &pairing.overlay;
            return types_view;
        }
        var types_view = self.checked_types.view();
        types_view.names = &self.canonical_names;
        return types_view;
    }

    /// The store holding the module's types: its own, or a paired
    /// module's platform's.
    pub fn typeStore(self: *const CheckedModule) *CheckedTypeStore {
        if (self.pairing) |pairing| return @constCast(&pairing.platform.checked_types);
        return @constCast(&self.checked_types);
    }

    /// The name store the module's checked data names: its own, or a
    /// paired module's platform's.
    pub fn nameStore(self: *const CheckedModule) *const canonical.CanonicalNameStore {
        if (self.pairing) |pairing| return &pairing.platform.canonical_names;
        return &self.canonical_names;
    }

    /// The requirement relations of a platform/app pairing, its pairing's
    /// slot (empty for any other module).
    pub fn platformRequirementRelations(self: *const CheckedModule) *const PlatformRequirementRelationTable {
        const pairing = self.pairing orelse return &empty_platform_requirement_relations;
        return &(pairing.relation_tables.peek() orelse checkedModuleInvariant("a pairing's relation tables were read before its creation computed them", .{})).relations;
    }

    /// The platform-required bindings of a platform/app pairing, its
    /// pairing's slot (empty for any other module).
    pub fn platformRequiredBindings(self: *const CheckedModule) *const PlatformRequiredBindingTable {
        const pairing = self.pairing orelse return &empty_platform_required_bindings;
        return &(pairing.relation_tables.peek() orelse checkedModuleInvariant("a pairing's relation tables were read before its creation computed them", .{})).bindings;
    }

    /// The module's platform requirement declarations.
    pub fn platformRequiredDeclarations(self: *const CheckedModule) PlatformRequiredDeclarationTable {
        return .{ .env = self.moduleEnvConst(), .module_idx = self.module_identity.module_idx };
    }

    /// Whether the module is a platform that declares requirements.
    pub fn hasPlatformRequirements(self: *const CheckedModule) bool {
        return self.moduleEnvConst().requires_types.items.items.len != 0;
    }

    /// A platform's requirement identity variables; a paired module's are
    /// its platform's.
    pub fn platformTypeInputs(self: *const CheckedModule) Allocator.Error!*const PlatformTypeInputs {
        return importedView(self).platformTypeInputs();
    }

    /// An app's solutions of its platform's requirement identity variables.
    pub fn platformRequirementSolutions(self: *const CheckedModule) Allocator.Error!*const PlatformRequirementSolutionTable {
        return importedView(self).platformRequirementSolutions();
    }

    /// The module's export rows; a paired module's are its platform's.
    pub fn exportRows(self: *const CheckedModule) Allocator.Error!*const ExportRows {
        return importedView(self).exportRows();
    }

    /// The module's hosted procedures; a paired module's are its platform's.
    pub fn hostedProcs(self: *const CheckedModule) Allocator.Error!*const HostedProcTable {
        return importedView(self).hostedProcs();
    }

    /// A platform's hosted bindings; a paired module's are its platform's.
    pub fn hostedBindings(self: *const CheckedModule) Allocator.Error!*const HostedBindingTable {
        return importedView(self).hostedBindings();
    }

    /// Whether the module declares a hosted procedure.
    pub fn declaresHostedProcedures(self: *const CheckedModule) bool {
        return declaresHostedProceduresIn(self.moduleEnvConst());
    }

    /// The module's provided exports at their types. A paired module's
    /// `provided_exports` are its platform's rows, which name the platform's
    /// own types; these are read under its pairing.
    pub fn providedExports(self: *const CheckedModule) Allocator.Error!*const ProvidedExportTable {
        if (self.pairing) |pairing| return try pairing.providedExports();
        return importedView(self).providedExports();
    }

    /// The module's checked tables, computed on first demand; a paired
    /// module's are its platform's.
    pub fn checkedTables(self: *const CheckedModule) Allocator.Error!*const CheckedTables {
        return importedView(self).checkedTables();
    }

    /// The module's resolved value references: its checked tables', or a
    /// paired module's own (`PlatformPairing.valueRefs`).
    pub fn valueRefs(self: *const CheckedModule) Allocator.Error!*const ResolvedValueRefTable {
        return importedView(self).valueRefs();
    }

    /// Point the module's types at its module analyses, which compute
    /// their interface capabilities.
    pub fn attachCapabilitySource(self: *CheckedModule) void {
        const analyses = self.module_analyses orelse checkedModuleInvariant("a module's capability source was attached before its module analyses", .{});
        const hash = self.moduleEnvConst().contentIdentityHash() orelse checkedModuleInvariant("a checked module has no content identity", .{});
        const current_module = self.canonical_names.lookupModuleIdentity(hash) orelse checkedModuleInvariant("a checked module's own identity was never interned", .{});
        self.checked_types.capability_source = .{ .analyses = analyses, .current_module = current_module, .module = self.key.digest() };
    }

    /// Let the module's slots run: its type store and name store are
    /// readable by other threads and its interface capabilities have their source, so no
    /// slot can see the module before every type and name its cache entry
    /// holds exists. A pairing's stores and capabilities are its platform's.
    pub fn openToAnalyses(self: *CheckedModule) void {
        if (std.debug.runtime_safety) {
            const type_store = self.typeStore();
            if (type_store.published_counts == null) checkedModuleInvariant("a module's analyses were let run before its type store was published", .{});
            if (self.nameStore().published == null) checkedModuleInvariant("a module's analyses were let run before its name store was published", .{});
            if (type_store.capability_source == null) checkedModuleInvariant("a module's analyses were let run before its interface capabilities had their source", .{});
        }
        if (self.module_analyses) |analyses| analyses.markOpened();
        if (self.body_analyses) |analyses| analyses.markOpened();
    }

    /// The checked modules lowering this module's roots reads.
    pub fn loweringVisibility(self: *const CheckedModule, resolver: ModuleResolver) Allocator.Error!*const LoweringVisibility {
        return importedView(self).loweringVisibility(resolver);
    }

    /// The checked modules a consumer of this module's public API reads.
    pub fn publicApiDependencies(self: *const CheckedModule, resolver: ModuleResolver) Allocator.Error!*const PublicApiDependencies {
        return importedView(self).publicApiDependencies(resolver);
    }

    /// The template closures of this module's export rows.
    pub fn exportClosures(self: *const CheckedModule, resolver: ModuleResolver) Allocator.Error!*const ExportClosures {
        return importedView(self).exportClosures(resolver);
    }

    /// The reader over the module's bodies.
    pub fn bodies(self: *const CheckedModule) Allocator.Error!CheckedBodies {
        return importedView(self).bodies();
    }

    /// What the module's dispatch analyses read. A platform/app pairing
    /// reads its platform's dispatch resolution.
    pub fn dispatchSource(self: *const CheckedModule) Allocator.Error!DispatchSource {
        return importedView(self).dispatchSource();
    }

    /// The reader over the module's dispatch resolution.
    pub fn dispatch(self: *const CheckedModule) Allocator.Error!CheckedDispatch {
        return .{ .source = try self.dispatchSource() };
    }

    /// Exhaustiveness check `id` with the owner and policy that decide it.
    pub fn exhaustivenessSite(self: *const CheckedModule, id: CheckedExhaustivenessSiteId) Allocator.Error!CheckedExhaustivenessSite {
        return (try importedView(self).exhaustivenessSites()).get(id);
    }

    pub fn moduleEnv(self: *CheckedModule) *ModuleEnv {
        return self.module_env.env();
    }

    pub fn moduleEnvConst(self: *const CheckedModule) *const ModuleEnv {
        return self.module_env.envConst();
    }

    pub fn platformRequirementContextKey(self: *const CheckedModule) Allocator.Error!PlatformRequirementContextKey {
        return PlatformRequirementContextKey.compute(
            self.module_identity,
            try self.platformRequiredDeclarations().identityHash(self.typesView()),
        );
    }

    /// The identity of the program this module roots when it is an
    /// executable root. A paired platform keeps its own module `key`, so the
    /// app it was paired with is named only by `platform_app_relation`; this
    /// identity covers both, and an unpaired root is named by its key alone.
    pub fn executableIdentity(self: *const CheckedModule) [32]u8 {
        var hasher = base.Sha256.init(.{});
        hasher.update("roc-executable-identity");
        hasher.update(&self.key.bytes);
        if (self.checking_context_identity.platform_app_relation) |relation| {
            hasher.update(&[_]u8{1});
            hasher.update(&relation.bytes);
        } else {
            hasher.update(&[_]u8{0});
        }
        return hasher.finalResult();
    }

    /// A platform with declared app requirements is runtime-lowerable only
    /// after pairing has supplied its exact app relation.
    pub fn hasUnboundPlatformRequirements(self: *const CheckedModule) bool {
        return self.module_identity.kind == .platform and
            self.platformRequiredDeclarations().count() > 0 and
            self.checking_context_identity.platform_app_relation == null;
    }

    /// Whether a compile-time request of this finalized module names a root
    /// no compilation that finalized it demanded.
    /// Whether a compilation under `strategy` has roots to evaluate here:
    /// a `.lss` compilation never evaluates a literal argument root
    /// (design.md "Literal Arguments").
    pub fn hasUnevaluatedRequests(self: *const CheckedModule, strategy: base.SpecializationStrategy) Allocator.Error!bool {
        for ((try self.rootRequests()).compile_time_requests) |request| {
            const id = request.compile_time_root orelse continue;
            const payload = self.evaluation.rootPayload(id);
            if (payload != .unevaluated and payload != .pending) continue;
            if (strategy == .lss and id.kind() == .literal_argument) continue;
            if (strategy == .boxy and self.evaluation.rootBoxyValue(id) != null) continue;
            return true;
        }
        return false;
    }

    /// The module's root requests.
    pub fn rootRequests(self: *const CheckedModule) Allocator.Error!*const RootRequestTable {
        return importedView(self).rootRequests();
    }

    /// The resolver the module's analyses find other modules through.
    pub fn analysesResolver(self: *const CheckedModule) ModuleResolver {
        const analyses = self.module_analyses orelse checkedModuleInvariant("a resolver was read from a module without analyses", .{});
        return analyses.resolver orelse checkedModuleInvariant("a module's analyses were read before their resolver was attached", .{});
    }

    /// The module's root requests when a consumer has demanded them.
    pub fn peekRootRequests(self: *const CheckedModule) ?*const RootRequestTable {
        const analyses = self.module_analyses orelse return null;
        return analyses.root_requests.peek();
    }

    /// Compile-time root `id` of this module: a row of the root table, or a
    /// literal root.
    pub fn compileTimeRoot(self: *const CheckedModule, id: ComptimeRootKey) Allocator.Error!CompileTimeRoot {
        return importedView(self).compileTimeRoot(id);
    }

    /// Record root `id`'s payload.
    pub fn fillRootPayload(self: *CheckedModule, id: ComptimeRootKey, payload: CompileTimeRootPayload) Allocator.Error!void {
        verifyCompileTimeRootPayloadMatchesKind(try self.compileTimeRoot(id), payload);
        self.evaluation.setRootPayload(id, payload);
    }

    /// Record the value a `.boxy` evaluation stored for root `id`.
    pub fn fillRootBoxyValue(self: *CheckedModule, id: ComptimeRootKey, value: StoredConstTemplate) void {
        self.evaluation.setRootBoxyValue(id, value);
    }

    /// Give every literal root the module's root requests evaluate its
    /// evaluation output entry, before evaluation fills any.
    pub fn prepareLiteralRootPayloads(self: *CheckedModule) Allocator.Error!void {
        const allocator = self.evaluationAllocator();
        var entries: std.ArrayList(RootOutput) = .empty;
        defer entries.deinit(allocator);
        for ((try self.rootRequests()).requests) |request| {
            const root = request.compile_time_root orelse continue;
            if (!root.isLiteral()) continue;
            try entries.append(allocator, .{ .id = root });
        }
        try self.evaluation.addRoots(allocator, self.freesReplacedEvaluationColumns(), entries.items);
    }

    /// Reopen a finalized module so this compilation can evaluate the roots
    /// earlier compilations did not demand (design.md "Demand-Driven
    /// Compile-Time Evaluation"). The evaluation output moves into storage
    /// this module owns, every unevaluated root awaits evaluation again,
    /// and the module awaits finalization. Roots this compilation does not
    /// demand either return to `unevaluated` when it seals the module.
    pub fn reopenForEvaluation(self: *CheckedModule) Allocator.Error!void {
        if (self.evaluation.state != .finalized) checkedModuleInvariant("only a finalized module can be reopened for evaluation", .{});
        if (self.reopened_arena != null) checkedModuleInvariant("checked module was reopened for evaluation twice", .{});
        // A relocated cache entry's output aliases its buffer and a paired
        // module's may alias its platform's, so it moves into owned storage; an
        // module this process opened already owns it. The arena belongs
        // to the allocator that owns the module, which `owningAllocator`
        // reads back through the arena.
        if (self.serialized_backing != null or self.pairing_arena != null) {
            const owner = if (self.pairing_arena) |arena| arena.allocator() else blk: {
                const allocator = self.owningAllocator();
                const arena = try allocator.create(base.SingleThreadArena);
                arena.* = base.SingleThreadArena.init(allocator);
                self.reopened_arena = arena;
                break :blk arena.allocator();
            };
            self.evaluation = try copyPairingColumns(EvaluationOutput, self.evaluation, owner);
        }
        self.evaluation.reopen();
    }

    /// The allocator that owns this module's evaluation output: the bytes
    /// finalization stores for the cache entry and replay.
    pub fn evaluationAllocator(self: *const CheckedModule) Allocator {
        if (self.reopened_arena) |arena| return arena.allocator();
        if (self.pairing_arena) |arena| return arena.allocator();
        return self.canonical_names.allocator;
    }

    /// Whether replacing a column of the evaluation output must free the one
    /// it replaces: an arena or a relocated buffer owns them otherwise.
    pub fn freesReplacedEvaluationColumns(self: *const CheckedModule) bool {
        return self.reopened_arena == null and self.pairing_arena == null and self.serialized_backing == null;
    }

    /// Root orders are dense indices in the complete checked request table.
    pub fn lookupRootRequestByOrder(self: *const CheckedModule, order: u32) Allocator.Error!?RootRequest {
        const requests = (try self.rootRequests()).requests;
        if (order >= requests.len) return null;
        const root = requests[order];
        std.debug.assert(root.order == order);
        return root;
    }

    /// Borrow a provided procedure root's exact published FFI symbol.
    pub fn providedEntrypointName(self: *const CheckedModule, root: RootRequest) Allocator.Error!?[]const u8 {
        if (root.kind != .provided_export) return null;
        const export_id = root.provided_export.get() orelse
            checkedModuleInvariant("provided root has no export declaration identity", .{});
        const provided = (try self.providedExports()).exports[@backingInt(export_id)];
        const procedure = switch (provided) {
            .procedure => |procedure| procedure,
            .data, .checked_error => checkedModuleInvariant("provided procedure root names an export that is not a procedure", .{}),
        };
        return self.nameStore().externalSymbolNameText(procedure.ffi_symbol);
    }

    /// Whether a `provides` entry declares a host boundary with no ABI
    /// (`ProvidedCheckedErrorExport`), in which case no program with this
    /// module's host boundary exists and a runtime command stops at the
    /// diagnostics already reported.
    pub fn hasProvidedExportWithoutAbi(self: *const CheckedModule) Allocator.Error!bool {
        for ((try self.providedExports()).exports) |provided| {
            if (provided == .checked_error) return true;
        }
        return false;
    }

    /// A checked module's stored outputs: the inference output and the
    /// evaluation output, which are what a cache entry and the baked Builtin
    /// blob hold beside the module's `ModuleEnv`. Every other part of the
    /// live module is a function of these, the `ModuleEnv` and the module's
    /// imports, and is recreated when the outputs are loaded
    /// (`openCheckedModule`).
    pub const Serialized = extern struct {
        // No field defaults: `Serialized` is only ever produced by `serialize`,
        // which sets every field.
        inference: InferenceOutput.Serialized,
        evaluation: EvaluationOutput.Serialized,

        pub const root_contract: collections.serde_validation.RootContract = .{
            .Owner = CheckedModule,
            .owner_only_fields = &.{
                // Recreated from the `ModuleEnv` and the imports on load.
                "key",
                "source_hash",
                "canonical_names",
                "module_identity",
                "checking_context_identity",
                "direct_import_module_keys",
                "checked_types",
                // Written as the entry's own `ModuleEnv` body.
                "module_env",
                // Runtime ownership, not checked data.
                "serialized_backing",
                "serialized_backing_borrowed",
                "pairing_arena",
                "pairing",
                "reopened_arena",
                "body_analyses",
                "module_analyses",
            },
        };

        comptime {
            // The inference output's and the evaluation output's slices;
            // fixed at compile time, independent of stored data size.
            std.debug.assert(store_serialize.relocatablePointerCount(Serialized) == 63);
            // A cache entry holds the `ModuleEnv`, the inference output and
            // the evaluation output, and nothing else.
            const fields = @typeInfo(Serialized).@"struct".field_names;
            std.debug.assert(fields.len == 2);
            std.debug.assert(store_serialize.comptimeStrEq(fields[0], "inference"));
            std.debug.assert(store_serialize.comptimeStrEq(fields[1], "evaluation"));
        }

        /// Append the module's inference and evaluation outputs to `writer`.
        pub fn serialize(
            self: *Serialized,
            checked: *const CheckedModule,
            gpa: Allocator,
            writer: *CompactWriter,
        ) Allocator.Error!void {
            if (checked.pairing != null) checkedModuleInvariant("a paired module cannot be cached as a module", .{});
            if (checked.evaluation.state != .finalized) checkedModuleInvariant("cannot serialize a module whose evaluation is unfinished", .{});
            try self.inference.serialize(&checked.inference, gpa, writer);
            try self.evaluation.serialize(&checked.evaluation, gpa, writer);
        }

        /// Bounds-check every relocatable marker's `(offset, len)` against
        /// the `backing`-buffer length before anything aliases it, so a
        /// truncated or corrupt blob (builtin trailer / disk cache) fails
        /// cleanly instead of producing dangling out-of-bounds slices.
        pub fn validate(self: *const Serialized, backing_len: usize) error{CorruptSerializedData}!void {
            if (backing_len < @sizeOf(Serialized)) return error.CorruptSerializedData;
            try store_serialize.validateSerialized(Serialized, self, backing_len);
            try self.evaluation.validateContents(@intFromPtr(self));
            try self.inference.deserialize(@intFromPtr(self)).validate();
        }
    };

    /// Manual discriminant for `SERIALIZED_VERSION_HASH`: bump to force a cache /
    /// baked-blob invalidation for a layout change the structural fingerprint below
    /// cannot observe (e.g. a semantic change to how a field is interpreted).
    const serialized_layout_version: u32 = 125;

    /// Comptime fingerprint of `Serialized`'s layout. It is appended to the baked
    /// builtin module blob and validated on load (`expectSerializedVersion`), and
    /// the compiler's cache versioning folds it into the admission hash of every
    /// cache entry holding a module body, so a module serialized by a compiler
    /// with a different `Serialized` layout is rejected rather than relocated into a
    /// mismatched struct (a real hazard during development, where
    /// a reported release version can remain unchanged between rebuilds).
    pub const SERIALIZED_VERSION_HASH: [32]u8 =
        store_serialize.rootLayoutVersionHash(Serialized, serialized_layout_version);

    // A-11: validate the entire serialized sub-store tree at compile time—every
    // field must be a relocatable marker or relocation-invariant POD (a raw pointer
    // embedded outside a marker would silently dangle after relocation).
    comptime {
        store_serialize.assertSerializedRelocatable(Serialized);
    }

    /// Validate a version hash read from a serialized module (builtin blob trailer
    /// or cache header) against the running compiler's `SERIALIZED_VERSION_HASH`.
    pub fn expectSerializedVersion(found: *const [32]u8) bool {
        // Manual byte compare: `std.mem.eql` is banned in src/check (raw byte
        // comparison is a type-checker-identity footgun); a fixed-length hash
        // compare here is unambiguous.
        for (found, &SERIALIZED_VERSION_HASH) |a, b| {
            if (a != b) return false;
        }
        return true;
    }

    /// Length of the version trailer the builtin baker appends to its blob.
    pub const VERSION_TRAILER_LEN = SERIALIZED_VERSION_HASH.len;

    /// The baked builtin blob is laid out `[serialized bytes][version trailer]`: the
    /// baker (`builtin_compiler`) writes the `Serialized` at offset 0 and appends
    /// `SERIALIZED_VERSION_HASH` as a trailer. This validates that trailer against the
    /// running compiler's layout hash and returns the serialized prefix to relocate,
    /// keeping the one place that knows the trailer's position. A stale or truncated
    /// blob is rejected rather than relocated into a mismatched struct.
    pub fn splitVersionTrailer(blob: []const u8) error{ CorruptBuiltinOutputs, BuiltinOutputsVersionMismatch }![]const u8 {
        if (blob.len < VERSION_TRAILER_LEN) return error.CorruptBuiltinOutputs;
        const serialized_len = blob.len - VERSION_TRAILER_LEN;
        // The serialized prefix must be at least a whole `Serialized` header—the loader
        // `@ptrCast`s it to `*const Serialized`. This mirrors the disk-cache loader's
        // `< @sizeOf(Serialized)` floor so a truncated builtin blob is a clean error, not
        // an out-of-bounds read.
        if (serialized_len < @sizeOf(Serialized)) return error.CorruptBuiltinOutputs;
        if (!expectSerializedVersion(blob[serialized_len..][0..VERSION_TRAILER_LEN])) {
            return error.BuiltinOutputsVersionMismatch;
        }
        return blob[0..serialized_len];
    }

    pub fn deinit(self: *CheckedModule, allocator: Allocator) void {
        self.deinitInternal(allocator, true);
    }

    pub fn deinitRetainingModuleEnv(self: *CheckedModule, allocator: Allocator) void {
        self.deinitInternal(allocator, false);
    }

    fn deinitInternal(self: *CheckedModule, allocator: Allocator, comptime deinit_module_env: bool) void {
        if (self.module_analyses) |analyses| {
            analyses.destroy();
            self.module_analyses = null;
        }
        if (self.body_analyses) |analyses| {
            analyses.destroy();
            self.body_analyses = null;
        }
        if (self.checked_types.synthesized_keys) |keys| {
            keys.destroy();
            self.checked_types.synthesized_keys = null;
        }
        if (self.checked_types.sealed_keys) |keys| keys.destroy();
        const owning = self.owningAllocator();
        if (self.reopened_arena) |arena| {
            const owner = arena.child_allocator;
            arena.deinit();
            owner.destroy(arena);
            self.reopened_arena = null;
        } else if (self.pairing_arena == null and self.serialized_backing == null) {
            self.evaluation.deinit(allocator);
        }
        if (self.pairing_arena) |arena| {
            const owner = arena.child_allocator;
            if (deinit_module_env) self.module_env.deinit();
            if (self.pairing) |pairing| pairing.destroy();
            arena.deinit();
            owner.destroy(arena);
            self.* = undefined;
            return;
        }
        if (self.serialized_backing) |backing| {
            // The inference and evaluation outputs alias the stored
            // outputs' buffer, which the module frees unless it borrows it.
            if (!self.serialized_backing_borrowed) {
                std.debug.assert(allocator.ptr == owning.ptr and allocator.vtable == owning.vtable);
                allocator.free(backing);
            }
        } else {
            self.inference.deinit(allocator);
        }
        self.checked_types.deinit(allocator);
        self.canonical_names.deinit();
        self.checking_context_identity.deinit(allocator);
        allocator.free(self.direct_import_module_keys);
        if (deinit_module_env) {
            self.module_env.deinit();
        } else {
            self.module_env = undefined;
        }
        self.* = undefined;
    }

    pub fn verifyReadyForCompileTimeLowering(self: *const CheckedModule) Allocator.Error!void {
        if (builtin.mode != .debug) return;

        std.debug.assert(self.module_identity.module_idx != std.math.maxInt(u32));
        // Another thread may be creating types in the store; the roots its
        // creation made are complete only once it ends.
        const complete_roots = self.typeStore().completeRootCount();
        std.debug.assert(self.typeStore().payloads.items().len >= complete_roots);
        const root_requests = self.peekRootRequests() orelse &empty_root_requests;
        verifyRootRequestSubsets(root_requests.*);

        for (self.typeStore().payloads.items()[0..complete_roots], 0..) |payload, i| {
            switch (payload) {
                .pending => base.invariant("checked module invariant violated: checked type payload {d} was not filled before compile-time lowering", .{i}),
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {},
            }
        }

        for (root_requests.requests, 0..) |request, i| {
            std.debug.assert(request.order == i);
            if (request.kind == .provided_export) {
                const export_id = request.provided_export.get() orelse
                    checkedModuleInvariant("provided root has no export declaration identity", .{});
                const provided = (try self.providedExports()).exports[@backingInt(export_id)];
                std.debug.assert(provided == .procedure);
                std.debug.assert(request.source == .def);
                std.debug.assert(request.source.def == provided.procedure.def);
                std.debug.assert(request.abi == .platform and request.exposure == .exported);
            } else {
                std.debug.assert(request.provided_export == .none);
            }
            std.debug.assert(request.module_idx == self.module_identity.module_idx);
            std.debug.assert(self.typesView().containsId(request.checked_type));
            if (request.abi == .compile_time) {
                const template_ref = request.procedure_template orelse {
                    base.invariant("checked module invariant violated: compile-time root has no private wrapper template", .{});
                };
                // A literal root's entry wrapper runs only at compile time.
                const row = template_ref.template.rowIndex() orelse continue;
                std.debug.assert(row < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
                const template = (try self.checkedTables()).checked_procedure_templates.get(template_ref.template);
                switch (template.target) {
                    .comptime_only => {},
                    .roc, .hosted, .intrinsic, .entry => base.invariant("checked module invariant violated: compile-time root wrapper was not marked comptime_only", .{}),
                }
            }
        }

        for ((try self.checkedTables()).compile_time_roots.roots, 0..) |root, i| {
            std.debug.assert(root.id == CompileTimeRootTable.rootIdForSource(root.source));
            if (i != 0) std.debug.assert(@backingInt((try self.checkedTables()).compile_time_roots.roots[i - 1].id) < @backingInt(root.id));
            std.debug.assert(root.module_idx == self.module_identity.module_idx);
            if (root.expr) |expr| std.debug.assert(@backingInt(expr) < self.moduleEnvConst().store.nodes.len());
            if (root.literalNode()) |literal| std.debug.assert(literal.node() < self.moduleEnvConst().store.nodes.len());
            std.debug.assert((root.expr == null) == (root.literalNode() != null));
            if (root.pattern) |pattern| std.debug.assert(@backingInt(pattern) < self.moduleEnvConst().store.nodes.len());
            const payload = self.evaluation.rootPayload(root.id);
            switch (root.kind) {
                .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => switch (payload) {
                    .pending => {},
                    .unevaluated,
                    .const_node,
                    .fn_value,
                    .discarded,
                    .expect,
                    .runtime,
                    => verifyCompileTimeRootPayloadMatchesKind(root, payload),
                },
                .expect => switch (payload) {
                    .expect => {},
                    .pending,
                    .unevaluated,
                    .const_node,
                    .fn_value,
                    .discarded,
                    .runtime,
                    => base.invariant("checked module invariant violated: expect root has non-expect payload before compile-time lowering", .{}),
                },
            }
        }
    }

    /// Verify the producer-authored runtime category for every method whose
    /// checked template is an annotation-only intrinsic wrapper. This runs only
    /// from the debug module verifier; release consumers trust the serialized
    /// category without repeating the classification work.
    fn verifyMethodIntrinsicRuntimeTargets(self: *const CheckedModule) Allocator.Error!void {
        for ((try self.checkedTables()).method_registry.entries, 0..) |entry, entry_index| {
            const entry_target = entry.target orelse continue;
            const procedure = switch (entry_target.kind) {
                .procedure => |procedure| procedure,
                .local_proc, .structural => continue,
            };
            // A method bound to another module's procedure
            // (`method = Other.function`) names that module's template, which
            // this module does not hold.
            if (!std.meta.eql(procedure.template.module.bytes, self.key.bytes)) continue;
            const template_index = procedure.template.template.rowIndex() orelse (try self.checkedTables()).checked_procedure_templates.templates.items.len;
            if (template_index >= (try self.checkedTables()).checked_procedure_templates.templates.items.len) {
                base.invariant(
                    "checked module invariant violated: method registry procedure {d} referenced a missing checked template",
                    .{entry_index},
                );
            }
            const template = (try self.checkedTables()).checked_procedure_templates.templates.items[template_index];
            const template_intrinsic: ?IntrinsicId = switch (template.body) {
                .intrinsic_wrapper => |intrinsic| intrinsic,
                .checked_body, .entry_wrapper, .literal_root, .unimplemented => null,
            };

            switch (procedure.runtime_target) {
                .intrinsic => |runtime_intrinsic| {
                    if (runtime_intrinsic.callsiteArity() == null or
                        template_intrinsic == null or
                        template_intrinsic.? != runtime_intrinsic)
                    {
                        base.invariant(
                            "checked module invariant violated: method registry procedure {d} had inconsistent call-site intrinsic metadata",
                            .{entry_index},
                        );
                    }
                },
                .procedure, .low_level, .graph_participating => {
                    if (template_intrinsic) |intrinsic| {
                        if (intrinsic.callsiteArity() != null) {
                            base.invariant(
                                "checked module invariant violated: method registry procedure {d} lost its call-site intrinsic runtime target",
                                .{entry_index},
                            );
                        }
                    }
                },
            }
        }
    }

    pub fn verifyComplete(self: *const CheckedModule) Allocator.Error!void {
        if (self.evaluation.state != .finalized) checkedModuleInvariant("complete checked module still awaits evaluation", .{});
        self.evaluation.debug.validate() catch checkedModuleInvariant("compile-time debug observation has an invalid message range", .{});
        if (builtin.mode != .debug) return;

        std.debug.assert(self.module_identity.module_idx != std.math.maxInt(u32));
        const root_requests = try self.rootRequests();
        verifyRootRequestSubsets(root_requests.*);
        try self.verifyMethodIntrinsicRuntimeTargets();

        if (self.hasUnboundPlatformRequirements()) {
            for (root_requests.runtime_requests) |request| {
                if (request.kind == .provided_export) {
                    base.invariant(
                        "checked module invariant violated: relationless required platform published a provided runtime root",
                        .{},
                    );
                }
            }
        }

        for (root_requests.requests, 0..) |request, i| {
            std.debug.assert(request.order == i);
            std.debug.assert(request.module_idx == self.module_identity.module_idx);
            std.debug.assert(self.typesView().containsId(request.checked_type));
            if (request.procedure_template) |template_ref| {
                std.debug.assert(template_ref.module.eql(self.key.digest()));
                if (template_ref.template.rowIndex()) |row| std.debug.assert(row < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
                const evidence = request.root_evidence orelse {
                    base.invariant("checked module invariant violated: procedure template root has no checked evidence vector", .{});
                };
                std.debug.assert(evidence.checked_module.eql(self.key.digest()));
            }
            if (request.kind == .test_expect or
                request.kind == .compile_time_constant or
                request.kind == .compile_time_callable)
            {
                const template_ref = request.procedure_template orelse {
                    base.invariant("checked module invariant violated: compile-time/test root has no entry wrapper template", .{});
                };
                if (template_ref.template.rowIndex()) |row| std.debug.assert(row < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
            }
            if (request.kind == .platform_required_binding and request.procedure_use != null) {
                _ = request.root_evidence orelse {
                    base.invariant("checked module invariant violated: platform procedure root has no checked evidence vector", .{});
                };
            }
        }

        for ((try self.checkedTables()).compile_time_roots.roots, 0..) |root, i| {
            std.debug.assert(root.id == CompileTimeRootTable.rootIdForSource(root.source));
            if (i != 0) std.debug.assert(@backingInt((try self.checkedTables()).compile_time_roots.roots[i - 1].id) < @backingInt(root.id));
            std.debug.assert(root.module_idx == self.module_identity.module_idx);
            if (root.expr) |expr| std.debug.assert(@backingInt(expr) < self.moduleEnvConst().store.nodes.len());
            if (root.literalNode()) |literal| std.debug.assert(literal.node() < self.moduleEnvConst().store.nodes.len());
            std.debug.assert((root.expr == null) == (root.literalNode() != null));
            if (root.pattern) |pattern| std.debug.assert(@backingInt(pattern) < self.moduleEnvConst().store.nodes.len());
            const payload = self.evaluation.rootPayload(root.id);
            if (root.kind == .expect) {
                switch (payload) {
                    .expect => {},
                    .pending, .unevaluated, .const_node, .fn_value, .discarded, .runtime => base.invariant("checked module invariant violated: expect root has non-expect payload", .{}),
                }
                continue;
            }
            const has_request = blk: {
                for (root_requests.requests) |request| {
                    if (!request.requires_pairing and compileTimeRootHasRootRequest(&.{request}, root)) break :blk true;
                }
                break :blk false;
            };
            switch (payload) {
                .pending => {
                    if (has_request) {
                        base.invariant("checked module invariant violated: requested compile-time root has pending payload", .{});
                    }
                },
                .unevaluated, .const_node, .fn_value, .discarded, .expect, .runtime => {
                    if (!has_request) {
                        base.invariant("checked module invariant violated: non-requested compile-time root has concrete payload", .{});
                    }
                    verifyCompileTimeRootPayloadMatchesKind(root, payload);
                },
            }
        }

        if (self.pairing_arena == null) {
            std.debug.assert(CheckedModuleKey.eql(self.key, CheckedModuleKey.computeFromSourceHash(
                self.source_hash,
                self.module_identity,
                self.checking_context_identity,
                self.direct_import_module_keys,
            )));
        }

        // Another thread may be creating types in the store; the roots its
        // creation made are complete only once it ends.
        const complete_roots = self.typeStore().completeRootCount();
        std.debug.assert(self.typeStore().payloads.items().len >= complete_roots);
        for (self.typeStore().roots.items()[0..complete_roots], 0..) |root, i| {
            std.debug.assert(root.id == type_ids.fromSynthesized(i));
            switch (self.typeStore().payloads.items()[i]) {
                .pending => base.invariant("checked module invariant violated: checked type payload {d} was not filled", .{i}),
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {},
            }
        }

        {
            const checked = try self.bodies();
            for (checked.index().node_kinds, 0..) |kind, raw| switch (kind) {
                .expr => std.debug.assert(self.typesView().containsId(try checked.exprType(@fromBackingInt(@intCast(raw))))),
                .pattern => std.debug.assert(self.typesView().containsId(try checked.patternType(@fromBackingInt(@intCast(raw))))),
                .statement, .unreached => {},
            };
        }

        for ((try self.checkedTables()).checked_procedure_templates.templates.items, 0..) |template, i| {
            std.debug.assert(template.template_id.index() == i);
            std.debug.assert(self.typesView().containsId(template.checked_fn_root));
            _ = self.typeStore().scheme(template.checked_fn_scheme);
            switch (template.body) {
                .checked_body => |root_expr| std.debug.assert((try self.bodies()).index().reachesExpr(root_expr)),
                .intrinsic_wrapper => std.debug.assert(template.proc_base.kind() == .intrinsic_wrapper),
                .entry_wrapper => |wrapper_id| {
                    const wrapper = (try self.checkedTables()).entry_wrappers.get(wrapper_id);
                    std.debug.assert(self.typesView().containsId(wrapper.checked_fn_root));
                    std.debug.assert(wrapper.checked_fn_root == template.checked_fn_root);
                    std.debug.assert(wrapper.template.template == template.template_id);
                    std.debug.assert(wrapper.template.proc_base == template.proc_base);
                    std.debug.assert(std.meta.eql(wrapper.template.module.bytes, self.key.bytes));
                },
                .literal_root => checkedModuleInvariant("a literal root's entry wrapper is a row of the template table", .{}),
                // An unimplemented declaration publishes no body to verify.
                .unimplemented => {},
            }
        }

        for ((try self.exportRows()).procedure_templates) |exported| {
            std.debug.assert(std.meta.eql(exported.template.module.bytes, self.key.bytes));
            std.debug.assert(@backingInt(exported.template.template) < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
        }

        for ((try self.exportRows()).procedure_bindings) |exported| {
            std.debug.assert(std.meta.eql(exported.binding.module.bytes, self.key.bytes));
            switch (exported.body) {
                .direct_template => {},
                .checked_error => |expr| std.debug.assert((try self.bodies()).exprData(expr) == .runtime_error),
                .callable_eval_template => |template_id| std.debug.assert(@backingInt(template_id) < (try self.checkedTables()).callable_eval_templates.templates.items.len),
            }
        }

        for ((try self.exportRows()).const_templates) |exported| {
            std.debug.assert(std.meta.eql(exported.const_ref.module.bytes, self.key.bytes));
            std.debug.assert(@backingInt(exported.const_ref.template) < (try self.checkedTables()).const_templates.templates.items.len);
            switch (exported.template.state) {
                .eval_template => |eval| {
                    std.debug.assert((try self.checkedTables()).compile_time_roots.position(eval.root) != null);
                    std.debug.assert(compileTimeRootHasConstBody((try self.checkedTables()).compile_time_roots.root(eval.root).kind));
                    std.debug.assert(std.meta.eql(eval.entry_template.module.bytes, self.key.bytes));
                    std.debug.assert(@backingInt(eval.entry_template.template) < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
                },
                .reserved => base.invariant(
                    "checked module invariant violated: exported const template was not sealed",
                    .{},
                ),
                // An unimplemented declaration publishes no body or stored
                // value, so there is nothing further to verify.
                .unimplemented => {},
            }
        }

        for (self.platformRequirementRelations().relations, 0..) |relation, i| {
            std.debug.assert(@backingInt(relation.id) == i);
            std.debug.assert(relation.module_idx == self.module_identity.module_idx);
            const declaration = self.platformRequiredDeclarations().lookupByDeclarationId(relation.declaration) orelse {
                base.invariant(
                    "checked module invariant violated: platform requirement relation {d} has no declaration",
                    .{i},
                );
            };
            std.debug.assert(declaration.requires_idx == relation.requires_idx);
            if (!self.typesView().containsId(relation.requested_source_ty_payload)) {
                base.invariant(
                    "checked module invariant violated: platform requirement relation {d} requested payload is out of range",
                    .{i},
                );
            }
            switch (relation.value_kind) {
                .const_value, .procedure_value => {},
            }
        }

        for (self.platformRequiredBindings().bindings, 0..) |binding, i| {
            std.debug.assert(@backingInt(binding.id) == i);
            std.debug.assert(binding.module_idx == self.module_identity.module_idx);
            _ = self.platformRequiredDeclarations().lookupByRequiredIndex(binding.requires_idx) orelse {
                base.invariant(
                    "checked module invariant violated: platform required binding {d} has no declaration",
                    .{i},
                );
            };
            const relation = self.platformRequirementRelations().lookupByRelationId(binding.checked_relation) orelse {
                base.invariant(
                    "checked module invariant violated: platform required binding {d} has no checked relation",
                    .{i},
                );
            };
            validatePlatformBindingRelation(binding.declaration, binding.requires_idx, binding.app_value, std.meta.activeTag(binding.value_use), relation, i);
            verifyPlatformRequiredValueUse(self, binding);
        }
        for (self.platformRequiredBindings().checked_error_requires) |requires_idx| {
            _ = self.platformRequiredDeclarations().lookupByRequiredIndex(requires_idx) orelse {
                base.invariant(
                    "checked module invariant violated: platform checked-error requirement {d} has no declaration",
                    .{requires_idx},
                );
            };
            if (self.platformRequiredBindings().lookupByRequiredIndex(requires_idx) != null) {
                base.invariant(
                    "checked module invariant violated: platform requirement {d} is both bound and a checked error",
                    .{requires_idx},
                );
            }
        }

        for ((try self.checkedTables()).callable_eval_templates.templates.items, 0..) |template, i| {
            std.debug.assert(@backingInt(template.id) == i);
            std.debug.assert(template.module_idx == self.module_identity.module_idx);
            std.debug.assert(@backingInt(template.pattern) < self.moduleEnvConst().store.nodes.len());
            std.debug.assert((try self.checkedTables()).compile_time_roots.position(template.root) != null);
            const root = (try self.checkedTables()).compile_time_roots.root(template.root);
            std.debug.assert(root.kind == .callable_binding);
            std.debug.assert(root.pattern != null and root.pattern.? == template.pattern);
            std.debug.assert(self.typesView().containsId(template.checked_fn_root));
            _ = self.typeStore().scheme(template.source_scheme);
        }

        for ((try self.checkedTables()).top_level_values.entries) |entry| {
            std.debug.assert(@backingInt(entry.pattern) < self.moduleEnvConst().store.nodes.len());
            _ = self.nameStore().exportNameText(entry.source_name);
            switch (entry.value) {
                .const_ref => |const_ref| {
                    const owner = constRefTopLevelOwner(const_ref) orelse {
                        base.invariant("checked module invariant violated: top-level value table referenced a non-top-level ConstRef", .{});
                    };
                    std.debug.assert(owner.module_idx == self.module_identity.module_idx);
                    std.debug.assert(owner.pattern == entry.pattern);
                    std.debug.assert((const_ref.source_scheme == entry.source_scheme));
                },
                .procedure_binding => |binding_ref| {
                    const binding = (try self.checkedTables()).top_level_procedure_bindings.get(binding_ref);
                    switch (binding.body) {
                        .direct_template => |direct| {
                            switch (direct.template) {
                                .checked => |template| {
                                    std.debug.assert(template.proc_base == direct.proc_value.proc_base);
                                    std.debug.assert(std.meta.eql(template.module.bytes, direct.proc_value.module.bytes));
                                },
                                .synthetic => |synthetic| {
                                    std.debug.assert(synthetic.template.proc_base == direct.proc_value.proc_base);
                                    std.debug.assert(std.meta.eql(synthetic.template.module.bytes, direct.proc_value.module.bytes));
                                    std.debug.assert(@backingInt(synthetic.template.template) < (try self.checkedTables()).checked_procedure_templates.templates.items.len);
                                },
                                .lifted => base.invariant(
                                    "checked module invariant violated: direct top-level binding cannot use lifted template before mono",
                                    .{},
                                ),
                            }
                        },
                        .checked_error => |expr| std.debug.assert((try self.bodies()).exprData(expr) == .runtime_error),
                        .callable_eval_template => |template| {
                            std.debug.assert(@backingInt(template) < (try self.checkedTables()).callable_eval_templates.templates.items.len);
                        },
                    }
                },
            }
        }

        for ((try self.providedExports()).exports) |provided| {
            switch (provided) {
                .checked_error => |export_| {
                    const top_level = (try self.checkedTables()).top_level_values.lookupByDef(export_.def) orelse {
                        base.invariant("checked module invariant violated: provided checked-error export references missing top-level value", .{});
                    };
                    std.debug.assert(top_level.pattern == export_.pattern);
                    std.debug.assert(top_level.source_name == export_.source_name);
                },
                .procedure => |procedure| {
                    std.debug.assert(self.typesView().containsId(procedure.checked_type));
                    const top_level = (try self.checkedTables()).top_level_values.lookupByDef(procedure.def) orelse {
                        base.invariant("checked module invariant violated: provided procedure export references missing top-level value", .{});
                    };
                    std.debug.assert(top_level.pattern == procedure.pattern);
                    std.debug.assert(top_level.source_name == procedure.source_name);
                    std.debug.assert((top_level.source_scheme == procedure.source_scheme));
                    switch (top_level.value) {
                        .procedure_binding => |binding| std.debug.assert(binding == procedure.binding),
                        .const_ref => base.invariant("checked module invariant violated: provided procedure export references const top-level value", .{}),
                    }
                },
                .data => |data| {
                    std.debug.assert(self.typesView().containsId(data.checked_type));
                    const top_level = (try self.checkedTables()).top_level_values.lookupByDef(data.def) orelse {
                        base.invariant("checked module invariant violated: provided data export references missing top-level value", .{});
                    };
                    std.debug.assert(top_level.pattern == data.pattern);
                    std.debug.assert(top_level.source_name == data.source_name);
                    std.debug.assert((top_level.source_scheme == data.source_scheme));
                    switch (top_level.value) {
                        .const_ref => |const_ref| std.debug.assert(constRefEql(const_ref, data.const_ref)),
                        .procedure_binding => base.invariant("checked module invariant violated: provided data export references procedure top-level value", .{}),
                    }
                },
            }
        }

        for (self.evaluation.consts) |entry| {
            const stored = entry.value orelse continue;
            std.debug.assert(@backingInt(stored.node) < self.evaluation.const_store.values.items.len);
            std.debug.assert(@backingInt(stored.root_type) < self.evaluation.const_store.type_store.typeCount());
        }
        (try self.checkedTables()).const_templates.verifySealed();
        try self.evaluation.const_store.verifyComplete();
        for ((try self.valueRefs()).records) |record| {
            std.debug.assert(@backingInt(record.expr) < self.moduleEnvConst().store.nodes.len());
            if (self.checking_context_identity.platform_app_relation != null) {
                switch (record.ref) {
                    .platform_required_declaration => base.invariant(
                        "checked module invariant violated: executable platform module kept a declaration-only required lookup",
                        .{},
                    ),
                    .local_param,
                    .local_value,
                    .local_mutable_version,
                    .pattern_binder,
                    .local_proc,
                    .selected_hoisted_const,
                    .top_level_const,
                    .imported_const,
                    .top_level_proc,
                    .imported_proc,
                    .hosted_proc,
                    .platform_required_checked_error,
                    .platform_required_const,
                    .platform_required_proc,
                    .promoted_top_level_proc,
                    => {},
                }
            }
        }

        verifyLoweringVisibleNamesInterned(self.moduleEnvConst(), self.nameStore());
    }
};
/// Short name for checked module data.
pub const Module = CheckedModule;

fn verifyPlatformRequiredValueUse(self: *const CheckedModule, binding: PlatformRequiredBinding) void {
    if (builtin.mode != .debug) return;

    switch (binding.value_use) {
        .const_value => |const_use| {
            std.debug.assert(std.meta.eql(const_use.const_use.const_ref.module.bytes, binding.app_value.module.bytes));
            const owner = constRefTopLevelOwner(const_use.const_use.const_ref) orelse {
                base.invariant("checked module invariant violated: platform-required const use referenced a non-top-level ConstRef", .{});
            };
            std.debug.assert(owner.pattern == binding.app_value.pattern);
        },
        .procedure_value => |procedure_use| switch (procedure_use.procedure.binding) {
            .platform_required => |required| {
                std.debug.assert(std.meta.eql(required.module.bytes, binding.app_value.module.bytes));
                std.debug.assert(required.app_value.pattern == binding.app_value.pattern);
                if (self.platformRequiredBindings().relationClosure(binding).interface_capabilities.len == 0) {
                    base.invariant(
                        "checked module invariant violated: platform-required procedure use has no relation template closure",
                        .{},
                    );
                }
                const evidence = procedure_use.root_evidence orelse {
                    base.invariant("checked module invariant violated: platform-required procedure use has no root evidence", .{});
                };
                std.debug.assert(std.meta.eql(evidence.checked_module.bytes, binding.app_value.module.bytes));
            },
            .top_level,
            .imported,
            .hosted,
            => base.invariant(
                "checked module invariant violated: platform-required procedure use must reference the app requirement binding explicitly",
                .{},
            ),
        },
    }
}

/// Public `ImportedModuleView` declaration.
pub const ImportedModuleView = struct {
    code_generation_key: ?CheckedModuleKey = null,
    key: CheckedModuleKey,
    module_env: *const ModuleEnv,
    canonical_names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    direct_import_module_keys: []const CheckedModuleKey = &.{},
    /// The module's analyses; null only for a view of no opened module.
    module_analyses: ?*ModuleAnalyses = null,
    checked_types: CheckedTypeStoreView,
    /// The module's body facts; null only for a view of no opened module.
    body_analyses: ?*BodyAnalyses = null,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    checking_context_identity: *const CheckingContextIdentity = &empty_checking_context_identity,
    /// What compile-time evaluation wrote for the module.
    evaluation: *const EvaluationOutput,
    /// The module's constant store (`evaluation.const_store`).
    const_store: *const ConstStore,

    /// The keys of the modules this module imports directly.
    pub fn directImportKeys(self: ImportedModuleView) []const CheckedModuleKey {
        return self.direct_import_module_keys;
    }

    fn analyses(self: ImportedModuleView) *ModuleAnalyses {
        return self.module_analyses orelse checkedModuleInvariant("a module analysis was demanded of a view without module analyses", .{});
    }

    /// The module's checked tables, computed on first demand. A platform/app
    /// pairing's are its platform's.
    pub fn checkedTables(self: ImportedModuleView) Allocator.Error!*const CheckedTables {
        return self.analyses().checkedTables(self);
    }

    /// The module's resolved value references: its checked tables', or a
    /// platform/app pairing's own.
    pub fn valueRefs(self: ImportedModuleView) Allocator.Error!*const ResolvedValueRefTable {
        return self.analyses().valueRefs(self);
    }

    /// What the module's dispatch analyses read. A platform/app pairing
    /// reads its platform's dispatch resolution.
    pub fn dispatchSource(self: ImportedModuleView) Allocator.Error!DispatchSource {
        const module_analyses = self.analyses();
        if (module_analyses.platform) |platform| return importedView(platform).dispatchSource();
        const module_body_analyses = self.body_analyses orelse checkedModuleInvariant("dispatch was read from a view without body analyses", .{});
        const tables = try self.checkedTables();
        return .{
            .env = self.module_env,
            .module_idx = self.module_identity.module_idx,
            .key = self.key,
            .names = @constCast(self.canonical_names),
            .types = .{ .store = self.checked_types.store orelse checkedModuleInvariant("dispatch was read from a view without a type store", .{}) },
            .module_index = &module_body_analyses.index,
            .body_analyses = module_body_analyses,
            .method_registry = &tables.method_registry,
            .templates = &tables.checked_procedure_templates,
            .top_level_procedure_bindings = &tables.top_level_procedure_bindings,
            .plans = &tables.static_dispatch_plans,
            .refs = &tables.resolved_value_refs,
            .entry_wrappers = &tables.entry_wrappers,
            .callable_eval_templates = tables.callable_eval_templates.view(),
            .compile_time_roots = &tables.compile_time_roots,
            .analyses = module_analyses,
            .direct_imports = self.direct_import_module_keys,
        };
    }

    /// The reader over the module's dispatch resolution. A platform/app pairing
    /// reads its platform's.
    pub fn dispatch(self: ImportedModuleView) Allocator.Error!CheckedDispatch {
        return .{ .source = try self.dispatchSource() };
    }

    /// The reader over the module's bodies.
    pub fn bodies(self: ImportedModuleView) Allocator.Error!CheckedBodies {
        const tables = try self.checkedTables();
        return .{
            .env = self.module_env,
            .names = self.canonical_names,
            .types = self.checked_types,
            .analyses = self.body_analyses orelse checkedModuleInvariant("a view's bodies were read without body analyses", .{}),
            .tables = .{
                .module = self.key.digest(),
                .plans = &tables.static_dispatch_plans,
                .refs = try self.valueRefs(),
                .roots = &tables.compile_time_roots,
                .const_templates = &tables.const_templates,
                .templates = &tables.checked_procedure_templates,
                .top_level_procedure_bindings = &tables.top_level_procedure_bindings,
                .module_analyses = self.module_analyses,
                .dispatch = try self.dispatch(),
            },
        };
    }

    /// The module's platform requirement declarations.
    pub fn platformRequiredDeclarations(self: ImportedModuleView) PlatformRequiredDeclarationTable {
        return .{ .env = self.module_env, .module_idx = self.module_identity.module_idx };
    }

    /// Whether the module is a platform that declares requirements.
    pub fn hasPlatformRequirements(self: ImportedModuleView) bool {
        return self.module_env.requires_types.items.items.len != 0;
    }

    /// A platform's requirement identity variables (empty for any other
    /// module).
    pub fn platformTypeInputs(self: ImportedModuleView) Allocator.Error!*const PlatformTypeInputs {
        return self.analyses().platformTypeInputs(self);
    }

    /// An app's solutions of its platform's requirement identity variables
    /// (empty for any other module).
    pub fn platformRequirementSolutions(self: ImportedModuleView) Allocator.Error!*const PlatformRequirementSolutionTable {
        return self.analyses().platformRequirementSolutions(self);
    }

    /// The module's provided exports. A platform/app pairing's are its
    /// pairing's (`CheckedModule.providedExports`).
    pub fn providedExports(self: ImportedModuleView) Allocator.Error!*const ProvidedExportTable {
        return self.analyses().providedExports(self);
    }

    /// The module's export rows.
    pub fn exportRows(self: ImportedModuleView) Allocator.Error!*const ExportRows {
        return self.analyses().exportRows(self);
    }

    /// The module's hosted procedures.
    pub fn hostedProcs(self: ImportedModuleView) Allocator.Error!*const HostedProcTable {
        return self.analyses().hostedProcs(self);
    }

    /// A platform's hosted bindings (empty for any other module).
    pub fn hostedBindings(self: ImportedModuleView) Allocator.Error!*const HostedBindingTable {
        return self.analyses().hostedBindings(self);
    }

    /// The key of the module import `import_idx` resolves to, or null when it
    /// resolved to none. The module's direct import keys are its resolved
    /// imports' keys in import order.
    pub fn importKey(self: ImportedModuleView, import_idx: CIR.Import.Idx) ?CheckedModuleKey {
        const imports = &self.module_env.imports;
        if (imports.getResolvedModule(import_idx) == null) return null;
        var position: usize = 0;
        for (0..@backingInt(import_idx)) |i| {
            if (imports.getResolvedModule(@fromBackingInt(@as(u32, @intCast(i)))) != null) position += 1;
        }
        if (position >= self.direct_import_module_keys.len) {
            checkedModuleInvariant("a resolved import has no direct import key", .{});
        }
        return self.direct_import_module_keys[position];
    }

    /// The template closures of the module's export rows.
    pub fn exportClosures(self: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!*const ExportClosures {
        return self.analyses().exportClosures(self, resolver);
    }

    /// The checked modules a consumer of the module's public API reads.
    pub fn publicApiDependencies(self: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!*const PublicApiDependencies {
        return self.analyses().publicApiDependencies(self, resolver);
    }

    /// The checked modules lowering the module's roots reads.
    pub fn loweringVisibility(self: ImportedModuleView, resolver: ModuleResolver) Allocator.Error!*const LoweringVisibility {
        return self.analyses().loweringVisibility(self, resolver);
    }

    /// Every exhaustiveness check of the module with the owner and policy
    /// that decide it.
    pub fn exhaustivenessSites(self: ImportedModuleView) Allocator.Error!*const CheckedExhaustivenessSiteTable {
        return self.analyses().exhaustivenessSites(self);
    }

    /// The module's root requests.
    pub fn rootRequests(self: ImportedModuleView) Allocator.Error!*const RootRequestTable {
        return self.analyses().rootRequests(self);
    }

    /// Compile-time root `id` of the module: a row of the root table, or a
    /// literal root.
    pub fn compileTimeRoot(self: ImportedModuleView, id: ComptimeRootKey) Allocator.Error!CompileTimeRoot {
        if (!id.isLiteral()) return (try self.checkedTables()).compile_time_roots.root(id);
        return (try (try self.dispatch()).literalRoot(id)).root;
    }

    /// What constant template `ref` names holds: its checked state, or the
    /// value evaluation stored for it.
    pub fn constValue(self: ImportedModuleView, ref: ConstRef) Allocator.Error!ConstTemplateValue {
        return ConstTemplateValue.of((try self.checkedTables()).const_templates.get(ref), self.evaluation);
    }

    /// The payload evaluation gave root `id`.
    pub fn rootPayload(self: ImportedModuleView, id: ComptimeRootKey) CompileTimeRootPayload {
        return self.evaluation.rootPayload(id);
    }

    /// The value a `.boxy` evaluation stored for root `id`.
    pub fn rootBoxyValue(self: ImportedModuleView, id: ComptimeRootKey) ?StoredConstTemplate {
        return self.evaluation.rootBoxyValue(id);
    }
};

const empty_root_requests: RootRequestTable = .{};
const empty_platform_requirement_relations: PlatformRequirementRelationTable = .{};
const empty_platform_required_bindings: PlatformRequiredBindingTable = .{};
const empty_checking_context_identity: CheckingContextIdentity = .{};

/// Public `LoweringModuleView` declaration.
pub const LoweringModuleView = struct {
    module: *const CheckedModule,
    roots: *const RootRequestTable,
    relation_modules: []const ImportedModuleView = &.{},
};

/// Public `importedView` function.
pub fn importedView(checked: *const CheckedModule) ImportedModuleView {
    return .{
        .code_generation_key = if (checked.pairing_arena != null) checked.codeGenerationKey() else null,
        .key = checked.key,
        .module_env = checked.moduleEnvConst(),
        .canonical_names = checked.nameStore(),
        .module_identity = checked.module_identity,
        .direct_import_module_keys = checked.direct_import_module_keys,
        .module_analyses = checked.module_analyses,
        .checked_types = checked.typesView(),
        .body_analyses = checked.body_analyses,
        .platform_required_bindings = checked.platformRequiredBindings(),
        .checking_context_identity = &checked.checking_context_identity,
        .evaluation = &checked.evaluation,
        .const_store = &checked.evaluation.const_store,
    };
}

/// Return checked boundary names for an imported module view.
pub fn importedNames(view: ImportedModuleView) *const canonical.NameStore {
    return view.canonical_names;
}

/// One step of projecting a checked type into another store: a child type to
/// project, or a name to remap into the target's name store.
const CheckedTypeProjectOp = union(enum) {
    child: CheckedTypeId,
    type_name: canonical.TypeNameId,
    module_identity: canonical.ModuleIdentityId,
    method_name: canonical.MethodNameId,
    record_field: canonical.RecordFieldLabelId,
    tag: canonical.TagLabelId,
};

/// A projected type's op results, read back in the order its ops ran.
const CheckedTypeProjectResults = struct {
    items: []const u32,
    next: usize = 0,

    fn take(self: *CheckedTypeProjectResults) u32 {
        const value = self.items[self.next];
        self.next += 1;
        return value;
    }

    fn typeId(self: *CheckedTypeProjectResults) CheckedTypeId {
        return @fromBackingInt(@intCast(self.take()));
    }

    fn typeIds(self: *CheckedTypeProjectResults, allocator: Allocator, len: usize) Allocator.Error![]const CheckedTypeId {
        if (len == 0) return &.{};
        const out = try allocator.alloc(CheckedTypeId, len);
        for (out) |*id| id.* = self.typeId();
        return out;
    }
};

const CheckedTypeStoreImportProjector = struct {
    allocator: Allocator,
    target_store: *CheckedTypeStore,
    target_names: *canonical.CanonicalNameStore,
    imported: ImportedModuleView,
    preserve_source_instance: bool,
    active: collections.DenseMap(CheckedTypeId, CheckedTypeId),
    projected: collections.DenseMap(CheckedTypeId, CheckedTypeId),

    fn init(
        allocator: Allocator,
        target_store: *CheckedTypeStore,
        target_names: *canonical.CanonicalNameStore,
        imported: ImportedModuleView,
    ) CheckedTypeStoreImportProjector {
        return .{
            .allocator = allocator,
            .target_store = target_store,
            .target_names = target_names,
            .imported = imported,
            .preserve_source_instance = false,
            .active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator),
            .projected = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator),
        };
    }

    /// Project one checked source instance without coalescing it with an
    /// equal-key target root. Platform requirement solutions use this path:
    /// their canonical key names the requirement shape, while their payload is
    /// the explicit solution produced by checking.
    fn initPreservingSourceInstance(
        allocator: Allocator,
        target_store: *CheckedTypeStore,
        target_names: *canonical.CanonicalNameStore,
        imported: ImportedModuleView,
    ) CheckedTypeStoreImportProjector {
        var projector = init(allocator, target_store, target_names, imported);
        projector.preserve_source_instance = true;
        return projector;
    }
    fn deinit(self: *CheckedTypeStoreImportProjector) void {
        self.projected.deinit();
        self.active.deinit();
    }

    /// A type whose payload is still being projected: its ops occupy
    /// `ops[ops_start..]` and their results `results[results_start..]`.
    const Frame = struct {
        ty: CheckedTypeId,
        reserved: CheckedTypeId,
        payload: CheckedTypePayload,
        ops_start: usize,
        next: usize,
        results_start: usize,
    };

    const Run = struct {
        frames: std.ArrayListUnmanaged(Frame) = .empty,
        ops: std.ArrayListUnmanaged(CheckedTypeProjectOp) = .empty,
        results: std.ArrayListUnmanaged(u32) = .empty,

        fn deinit(run: *Run, allocator: Allocator) void {
            run.results.deinit(allocator);
            run.ops.deinit(allocator);
            run.frames.deinit(allocator);
        }

        fn push(run: *Run, allocator: Allocator, ty: CheckedTypeId, reserved: CheckedTypeId, payload: CheckedTypePayload) Allocator.Error!void {
            try run.frames.append(allocator, .{
                .ty = ty,
                .reserved = reserved,
                .payload = payload,
                .ops_start = run.ops.items.len,
                .next = run.ops.items.len,
                .results_start = run.results.items.len,
            });
        }

        fn pop(run: *Run) Frame {
            const frame = run.frames.pop().?;
            run.ops.shrinkRetainingCapacity(frame.ops_start);
            run.results.shrinkRetainingCapacity(frame.results_start);
            return frame;
        }
    };

    /// Project `ty` and everything it reaches. Each reserved type is an
    /// explicit frame whose ops run in order, so the depth of the projected
    /// graph never becomes native call depth.
    fn project(self: *CheckedTypeStoreImportProjector, ty: CheckedTypeId) Allocator.Error!CheckedTypeId {
        var run: Run = .{};
        defer run.deinit(self.allocator);
        if (try self.enter(&run, ty)) |id| return id;

        while (true) {
            const index = run.frames.items.len - 1;
            const frame = run.frames.items[index];
            if (frame.next < run.ops.items.len) {
                const op = run.ops.items[frame.next];
                run.frames.items[index].next += 1;
                const result: u32 = switch (op) {
                    .child => |child| if (try self.enter(&run, child)) |id| @backingInt(id) else continue,
                    .type_name => |id| @backingInt(try self.remapTypeName(id)),
                    .module_identity => |id| @backingInt(try self.remapModuleIdentity(id)),
                    .method_name => |id| @backingInt(try self.remapMethodName(id)),
                    .record_field => |id| @backingInt(try self.remapRecordField(id)),
                    .tag => |id| @backingInt(try self.remapTag(id)),
                };
                try run.results.append(self.allocator, result);
                continue;
            }

            var results = CheckedTypeProjectResults{ .items = run.results.items[frame.results_start..] };
            try self.finishType(frame.ty, frame.reserved, frame.payload, &results);
            std.debug.assert(results.next == results.items.len);
            _ = run.pop();
            if (run.frames.items.len == 0) return frame.reserved;
            try run.results.append(self.allocator, @backingInt(frame.reserved));
        }
    }

    /// The projected id of `ty` when it needs no new root; otherwise reserve
    /// one and push its frame.
    fn enter(self: *CheckedTypeStoreImportProjector, run: *Run, ty: CheckedTypeId) Allocator.Error!?CheckedTypeId {
        if (self.projected.get(ty)) |projected| return projected;
        if (self.active.get(ty)) |reserved| return reserved;

        // An identity-free imported type projects to one root of the target
        // store however often it is projected.
        const memo_key: CheckedTypeStore.ProjectedImportKey = .{ .module = self.imported.key.bytes, .ty = ty };
        const shared = !self.preserve_source_instance and !try self.imported.checked_types.rootHasIdentityVariables(ty);
        if (shared) {
            if (self.target_store.projected_imports.get(memo_key)) |existing| {
                try self.projected.put(ty, existing);
                return existing;
            }
        }

        // A synthesized function keeps the key its source computes.
        const recipe: CheckedTypeKeyRecipe = if (type_ids.isSynthesized(ty))
            self.imported.checked_types.rootRows()[type_ids.synthesizedIndex(ty)].recipe
        else
            .payload;
        const reserved = try self.target_store.reserveSyntheticTypeRootWithRecipe(self.allocator, recipe);
        if (shared) try self.target_store.projected_imports.put(self.allocator, memo_key, reserved);
        try self.active.put(ty, reserved);

        const payload = self.imported.checked_types.payload(ty);
        try run.push(self.allocator, ty, reserved, payload);
        try self.appendPayloadOps(&run.ops, payload);
        return null;
    }

    /// The ops a payload's projection runs, in order.
    fn appendPayloadOps(
        self: *CheckedTypeStoreImportProjector,
        ops: *std.ArrayListUnmanaged(CheckedTypeProjectOp),
        payload: CheckedTypePayload,
    ) Allocator.Error!void {
        const gpa = self.allocator;
        switch (payload) {
            .pending => checkedModuleInvariant("platform for-clause projection reached pending app checked type payload", .{}),
            .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => |variable| for (0..variable.constraints.len()) |constraint_index| {
                const constraint = variable.constraints.get(constraint_index);
                try ops.append(gpa, .{ .method_name = constraint.fn_name });
                try ops.append(gpa, .{ .child = constraint.fn_ty });
            },
            .alias => |alias| {
                try ops.append(gpa, .{ .type_name = alias.name });
                try ops.append(gpa, .{ .module_identity = alias.origin_module });
                try ops.append(gpa, .{ .child = alias.backing });
                for (alias.args) |arg| try ops.append(gpa, .{ .child = arg });
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try ops.append(gpa, .{ .record_field = field.name });
                    try ops.append(gpa, .{ .child = field.ty });
                    // Default identities remap across name stores; an
                    // undetermined kind's checked variable is projected with the
                    // field payload.
                    if (field.kind.defaultIdentity()) |default| {
                        try ops.append(gpa, .{ .module_identity = default.origin() orelse
                            checkedModuleInvariant("checked defaulted field kind carried no default identity", .{}) });
                    } else if (field.kind.undeterminedVariable()) |variable| {
                        try ops.append(gpa, .{ .child = variable });
                    }
                }
                try ops.append(gpa, .{ .child = record.ext });
            },
            .tuple => |items| for (items) |item| try ops.append(gpa, .{ .child = item }),
            .nominal => |nominal| {
                try ops.append(gpa, .{ .type_name = nominal.name });
                try ops.append(gpa, .{ .module_identity = nominal.origin_module });
                for (nominal.args) |arg| try ops.append(gpa, .{ .child = arg });
                for (nominal.padding_field_types) |padding| try ops.append(gpa, .{ .child = padding });
                for (nominal.declared_fields) |field| switch (field) {
                    .named => |name| try ops.append(gpa, .{ .record_field = name }),
                    .padding => {},
                };
            },
            .function => |function| {
                for (function.args) |arg| try ops.append(gpa, .{ .child = arg });
                try ops.append(gpa, .{ .child = function.ret });
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try ops.append(gpa, .{ .tag = tag.name });
                    for (tag.args) |arg| try ops.append(gpa, .{ .child = arg });
                }
                try ops.append(gpa, .{ .child = tag_union.ext });
            },
        }
    }

    /// Build and fill the projected payload from its op results.
    fn finishType(
        self: *CheckedTypeStoreImportProjector,
        ty: CheckedTypeId,
        reserved: CheckedTypeId,
        source_payload: CheckedTypePayload,
        results: *CheckedTypeProjectResults,
    ) Allocator.Error!void {
        var payload = try self.buildPayload(source_payload, results);
        if (payload == .flex or payload == .rigid) {
            // The fill below owns the payload; until then this frame does.
            errdefer deinitCheckedTypePayloadBuild(self.allocator, &payload);
            try self.target_store.declareIdentityInstance(self.allocator, reserved);
        }
        try self.target_store.fillSyntheticTypeRoot(self.allocator, reserved, payload);
        _ = self.active.remove(ty);
        try self.projected.put(ty, reserved);
    }

    fn buildPayload(
        self: *CheckedTypeStoreImportProjector,
        payload: CheckedTypePayload,
        results: *CheckedTypeProjectResults,
    ) Allocator.Error!CheckedTypePayloadBuild {
        const gpa = self.allocator;
        return switch (payload) {
            .pending => unreachable, // appendPayloadOps rejects pending payloads before any frame finishes
            .err => .err,
            .field_kind => |kind| .{ .field_kind = kind },
            .empty_record => .empty_record,
            .empty_tag_union => .empty_tag_union,
            .flex => |flex| .{ .flex = try self.buildVariable(flex, results) },
            .rigid => |rigid| .{ .rigid = try self.buildVariable(rigid, results) },
            .alias => |alias| blk: {
                const name: canonical.TypeNameId = @fromBackingInt(@intCast(results.take()));
                const origin_module: canonical.ModuleIdentityId = @fromBackingInt(@intCast(results.take()));
                const backing = results.typeId();
                break :blk .{ .alias = .{
                    .name = name,
                    .origin_module = origin_module,
                    .owner_module = alias.owner_module.*,
                    .source_decl = alias.source_decl,
                    .builtin_origin = alias.builtin_origin,
                    .backing = backing,
                    .args = try results.typeIds(gpa, alias.args.len),
                } };
            },
            .record => |record| blk: {
                const fields = try self.buildRecordFields(record.fields, results);
                break :blk .{ .record = .{ .fields = fields, .ext = results.typeId() } };
            },
            .tuple => |items| .{ .tuple = try results.typeIds(gpa, items.len) },
            .nominal => |nominal| blk: {
                const name: canonical.TypeNameId = @fromBackingInt(@intCast(results.take()));
                const origin_module: canonical.ModuleIdentityId = @fromBackingInt(@intCast(results.take()));
                const representation: CheckedNominalRepresentationRef = switch (nominal.representation) {
                    .builtin => |builtin_id| .{ .builtin = builtin_id },
                    .local_declaration => |declaration| .{ .imported_declaration = .{
                        .module = self.imported.key.digest(),
                        .declaration = declaration,
                    } },
                    .imported_declaration => |imported_decl| .{ .imported_declaration = imported_decl },
                    // A nominal another module declares is represented by
                    // its declaration in every importer.
                    .local_box_payload_capability => |capability| .{ .imported_declaration = .{
                        .module = self.imported.key.digest(),
                        .declaration = self.imported.checked_types.demandedInterfaceCapabilities().boxPayloadCapability(capability.capability).declaration,
                    } },
                    .opaque_without_backing => .opaque_without_backing,
                };
                const args = try results.typeIds(gpa, nominal.args.len);
                errdefer if (args.len != 0) gpa.free(args);
                const padding_field_types = try results.typeIds(gpa, nominal.padding_field_types.len);
                errdefer if (padding_field_types.len != 0) gpa.free(padding_field_types);
                const declared_fields: []const CheckedDeclaredField = if (nominal.declared_fields.len == 0) &.{} else fields_blk: {
                    const out = try gpa.alloc(CheckedDeclaredField, nominal.declared_fields.len);
                    for (nominal.declared_fields, out) |field, *slot| {
                        slot.* = switch (field) {
                            .named => .{ .named = @fromBackingInt(@intCast(results.take())) },
                            .padding => |index| .{ .padding = index },
                        };
                    }
                    break :fields_blk out;
                };
                break :blk .{ .nominal = .{
                    .name = name,
                    .origin_module = origin_module,
                    .owner_module = nominal.owner_module.*,
                    .source_decl = nominal.source_decl,
                    .builtin = nominal.builtin,
                    .is_opaque = nominal.is_opaque,
                    .representation = representation,
                    .args = args,
                    .padding_field_types = padding_field_types,
                    .declared_fields = declared_fields,
                } };
            },
            .function => |function| blk: {
                const args = try results.typeIds(gpa, function.args.len);
                break :blk .{ .function = .{
                    .kind = finalizedFunctionKind(function.kind),
                    .args = args,
                    .ret = results.typeId(),
                } };
            },
            .tag_union => |tag_union| blk: {
                const tags: []const CheckedTag = if (tag_union.tags.len() == 0) &.{} else tags_blk: {
                    const out = try gpa.alloc(CheckedTag, tag_union.tags.len());
                    for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
                    errdefer freeOwned(gpa, out);
                    for (out, 0..) |*slot, tag_index| {
                        slot.name = @fromBackingInt(@intCast(results.take()));
                        slot.args = try results.typeIds(gpa, tag_union.tags.get(tag_index).args.len);
                    }
                    break :tags_blk out;
                };
                break :blk .{ .tag_union = .{ .tags = tags, .ext = results.typeId() } };
            },
        };
    }

    fn buildVariable(
        self: *CheckedTypeStoreImportProjector,
        variable: CheckedTypeVariable,
        results: *CheckedTypeProjectResults,
    ) Allocator.Error!CheckedTypeVariableBuild {
        const name = if (variable.name) |name_text|
            try self.allocator.dupe(u8, name_text)
        else
            null;
        errdefer if (name) |owned| self.allocator.free(owned);

        const constraints: []const CheckedStaticDispatchConstraint = if (variable.constraints.len() == 0) &.{} else blk: {
            const out = try self.allocator.alloc(CheckedStaticDispatchConstraint, variable.constraints.len());
            for (out, 0..) |*slot, constraint_index| {
                const constraint = variable.constraints.get(constraint_index);
                slot.* = .{
                    .fn_name = @fromBackingInt(@intCast(results.take())),
                    .fn_ty = results.typeId(),
                    .origin = constraint.origin,
                    .numeral = constraint.numeral,
                };
            }
            break :blk out;
        };

        return .{
            .name = name,
            .constraints = constraints,
            .numeric_default_phase = variable.numeric_default_phase,
            .row_default = variable.row_default,
            .row_default_discharges_constraints = variable.row_default_discharges_constraints,
            .bounded_row_ext = variable.bounded_row_ext,
        };
    }

    fn buildRecordFields(
        self: *CheckedTypeStoreImportProjector,
        fields: CheckedRecordFields,
        results: *CheckedTypeProjectResults,
    ) Allocator.Error![]const CheckedRecordField {
        if (fields.len() == 0) return &.{};
        const out = try self.allocator.alloc(CheckedRecordField, fields.len());
        for (out, 0..) |*slot, field_index| {
            const field = fields.get(field_index);
            const name: canonical.RecordFieldLabelId = @fromBackingInt(@intCast(results.take()));
            const ty = results.typeId();
            slot.* = .{
                .name = name,
                .ty = ty,
                .kind = if (field.kind.defaultIdentity()) |default|
                    .defaultedFromParts(@fromBackingInt(@intCast(results.take())), default.expr_node)
                else if (field.kind.undeterminedVariable() != null)
                    .undetermined(results.typeId())
                else
                    field.kind,
            };
        }
        return out;
    }

    fn remapModuleIdentity(
        self: *CheckedTypeStoreImportProjector,
        id: canonical.ModuleIdentityId,
    ) Allocator.Error!canonical.ModuleIdentityId {
        return try self.target_names.internModuleIdentity(self.imported.canonical_names.moduleIdentityBytes(id));
    }

    fn remapTypeName(
        self: *CheckedTypeStoreImportProjector,
        id: canonical.TypeNameId,
    ) Allocator.Error!canonical.TypeNameId {
        return try self.target_names.internTypeName(self.imported.canonical_names.typeNameText(id));
    }

    fn remapMethodName(
        self: *CheckedTypeStoreImportProjector,
        id: canonical.MethodNameId,
    ) Allocator.Error!canonical.MethodNameId {
        return try self.target_names.internMethodName(self.imported.canonical_names.methodNameText(id));
    }

    fn remapRecordField(
        self: *CheckedTypeStoreImportProjector,
        id: canonical.RecordFieldLabelId,
    ) Allocator.Error!canonical.RecordFieldLabelId {
        return try self.target_names.internRecordFieldLabel(self.imported.canonical_names.recordFieldLabelText(id));
    }

    fn remapTag(
        self: *CheckedTypeStoreImportProjector,
        id: canonical.TagLabelId,
    ) Allocator.Error!canonical.TagLabelId {
        return try self.target_names.internTagLabel(self.imported.canonical_names.tagLabelText(id));
    }
};

fn directImportModuleKeysFromModule(
    allocator: Allocator,
    module_env: *const ModuleEnv,
    imports: []const CheckedImport,
) Allocator.Error![]CheckedModuleKey {
    const imported_names = module_env.imports.imports.items.items;
    var keys = std.ArrayList(CheckedModuleKey).empty;
    errdefer keys.deinit(allocator);

    for (imported_names, 0..) |_, i| {
        const import_idx: CIR.Import.Idx = @fromBackingInt(@intCast(@as(u32, @intCast(i))));
        const resolved_module_idx = module_env.imports.getResolvedModule(import_idx) orelse continue;
        const key = checkedImportKeyForModule(imports, resolved_module_idx) orelse {
            base.invariant(
                "checked module invariant violated: import {d} resolved to module {d} without a checked module key",
                .{ i, resolved_module_idx },
            );
        };
        try keys.append(allocator, key);
    }

    return try keys.toOwnedSlice(allocator);
}

fn checkedImportKeyForModule(imports: []const CheckedImport, module_idx: u32) ?CheckedModuleKey {
    for (imports) |import_module| {
        if (import_module.module_idx == module_idx) return import_module.key;
    }
    return null;
}

const InternLoweringVisibleNameVisitor = struct {
    names: *canonical.CanonicalNameStore,
    idents: *const Ident.Store,

    fn recordField(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internRecordFieldIdent(self.idents, ident);
    }

    fn tag(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internTagIdent(self.idents, ident);
    }

    fn method(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internMethodIdent(self.idents, ident);
    }

    fn typeName(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internTypeIdent(self.idents, ident);
    }

    fn exportName(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internExportIdent(self.idents, ident);
    }

    fn externalSymbol(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        _ = try self.names.internExternalSymbolIdent(self.idents, ident);
    }
};

const VerifyLoweringVisibleNameVisitor = struct {
    names: *const canonical.CanonicalNameStore,
    idents: *const Ident.Store,

    fn recordField(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupRecordFieldIdent(self.idents, ident) != null);
    }

    fn tag(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupTagIdent(self.idents, ident) != null);
    }

    fn method(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupMethodIdent(self.idents, ident) != null);
    }

    fn typeName(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupTypeIdent(self.idents, ident) != null);
    }

    fn exportName(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupExportIdent(self.idents, ident) != null);
    }

    fn externalSymbol(self: *@This(), ident: Ident.Idx) Allocator.Error!void {
        std.debug.assert(self.names.lookupExternalSymbolIdent(self.idents, ident) != null);
    }
};

fn internLoweringVisibleNames(
    module_env: *const ModuleEnv,
    names: *canonical.CanonicalNameStore,
) Allocator.Error!void {
    var visitor = InternLoweringVisibleNameVisitor{
        .names = names,
        .idents = module_env.getIdentStoreConst(),
    };
    try scanLoweringVisibleNames(module_env, &visitor);
}

fn verifyLoweringVisibleNamesInterned(
    module_env: *const ModuleEnv,
    names: *const canonical.CanonicalNameStore,
) void {
    if (builtin.mode != .debug) return;
    var visitor = VerifyLoweringVisibleNameVisitor{
        .names = names,
        .idents = module_env.getIdentStoreConst(),
    };
    scanLoweringVisibleNames(module_env, &visitor) catch unreachable; // VerifyLoweringVisibleNameVisitor methods only assert, so the scan cannot fail
}

fn scanLoweringVisibleNames(module_env: *const ModuleEnv, visitor: anytype) Allocator.Error!void {
    const store = &module_env.store;
    var raw_node_idx: u32 = 0;
    while (raw_node_idx < store.nodes.len()) : (raw_node_idx += 1) {
        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        const tag = store.nodes.get(node_idx).tag;
        switch (tag) {
            .field_access_segment => {
                const segment = store.getFieldAccessSegment(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.recordField(segment.name);
            },
            .record_field => {
                const field = store.getRecordField(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.recordField(field.name);
            },
            .record_unset_field => {
                const unset = store.getUnsetField(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.recordField(unset.name);
            },
            .record_destruct => {
                const destruct = store.getRecordDestruct(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.recordField(destruct.label);
            },
            .expr_typed_int,
            .expr_typed_frac,
            .expr_typed_num_from_numeral,
            .expr_tag,
            .expr_zero_argument_tag,
            .expr_closure,
            .expr_field_access,
            .expr_method_call,
            .expr_dispatch_call,
            .expr_method_eq,
            .expr_type_method_call,
            .expr_type_dispatch_call,
            .expr_type_dispatch_call_dispatcher,
            .expr_hosted_lambda,
            => {
                const expr = store.getExpr(@fromBackingInt(@intCast(raw_node_idx)));
                switch (expr) {
                    inline .e_typed_int, .e_typed_frac, .e_typed_num_from_numeral => |typed| try visitor.typeName(typed.type_name),
                    .e_tag => |tag_expr| try visitor.tag(tag_expr.name),
                    .e_zero_argument_tag => |tag_expr| {
                        try visitor.tag(tag_expr.name);
                        try visitor.tag(tag_expr.closure_name);
                    },
                    .e_closure => |closure| try visitor.tag(closure.tag_name),
                    .e_field_access => {}, // no action needed, segments are added above directly
                    .e_method_call => |method_call| try visitor.method(method_call.method_name),
                    .e_dispatch_call => |dispatch_call| try visitor.method(dispatch_call.method_name),
                    .e_method_eq => try visitor.method(module_env.idents.is_eq),
                    .e_type_method_call => |type_method_call| try visitor.method(type_method_call.method_name),
                    .e_type_dispatch_call => |type_dispatch_call| try visitor.method(type_dispatch_call.method_name),
                    .e_hosted_lambda => |hosted| try visitor.externalSymbol(hosted.symbol_name),
                    .e_num,
                    .e_frac_f32,
                    .e_frac_f64,
                    .e_dec,
                    .e_dec_small,
                    .e_num_from_numeral,
                    .e_str_segment,
                    .e_str,
                    .e_bytes_literal,
                    .e_lookup_local,
                    .e_lookup_external,
                    .e_lookup_associated_local,
                    .e_lookup_associated,
                    .e_lookup_associated_resolved,
                    .e_lookup_required,
                    .e_list,
                    .e_empty_list,
                    .e_tuple,
                    .e_match,
                    .e_if,
                    .e_call,
                    .e_record,
                    .e_empty_record,
                    .e_block,
                    .e_nominal,
                    .e_nominal_external,
                    .e_lambda,
                    .e_binop,
                    .e_unary_minus,
                    .e_interpolation,
                    .e_structural_eq,
                    .e_structural_hash,
                    .e_tuple_access,
                    .e_runtime_error,
                    .e_crash,
                    .e_dbg,
                    .e_expect_err,
                    .e_expect,
                    .e_ellipsis,
                    .e_anno_only,
                    .e_derived_method,
                    .e_return,
                    .e_break,
                    .e_for,
                    .e_run_low_level,
                    => {},
                    .e_deferred_import_ref => base.invariant("compiler invariant violated: deferred import reference reached a stage that runs after import resolution", .{}),
                }
            },
            .pattern_applied_tag => {
                const pattern = store.getPattern(@fromBackingInt(@intCast(raw_node_idx)));
                switch (pattern) {
                    .applied_tag => |tag_pattern| try visitor.tag(tag_pattern.name),
                    .assign,
                    .var_assign,
                    .as,
                    .nominal,
                    .nominal_external,
                    .record_destructure,
                    .list,
                    .tuple,
                    .num_literal,
                    .small_dec_literal,
                    .dec_literal,
                    .frac_f32_literal,
                    .frac_f64_literal,
                    .num_from_numeral_literal,
                    .str_literal,
                    .str_interpolation,
                    .underscore,
                    .runtime_error,
                    => {},
                    .deferred_import_ref => base.invariant("compiler invariant violated: deferred import reference pattern reached a stage that runs after import resolution", .{}),
                }
            },
            .type_header => {
                const header = store.getTypeHeader(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.typeName(header.name);
                try visitor.typeName(header.relative_name);
            },
            .ty_apply,
            .ty_lookup,
            .ty_tag,
            => {
                const anno = store.getTypeAnno(@fromBackingInt(@intCast(raw_node_idx)));
                switch (anno) {
                    .apply => |apply| try visitor.typeName(apply.name),
                    .lookup => |lookup| try visitor.typeName(lookup.name),
                    .tag => |tag_anno| try visitor.tag(tag_anno.name),
                    .rigid_var,
                    .rigid_var_lookup,
                    .underscore,
                    .tag_union,
                    .tuple,
                    .record,
                    .@"fn",
                    .parens,
                    .malformed,
                    => {},
                }
            },
            .ty_record_field, .ty_record_field_defaulted => {
                const field = store.getAnnoRecordField(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.recordField(field.name);
            },
            .where_method,
            .where_alias,
            => {
                const where_clause = store.getWhereClause(@fromBackingInt(@intCast(raw_node_idx)));
                switch (where_clause) {
                    .w_method => |method| try visitor.method(method.method_name),
                    // The alias reference is a type-anno node of its own, and
                    // is visited there.
                    .w_alias => {},
                    .w_malformed => {},
                }
            },
            .exposed_item => {
                const item = store.getExposedItem(@fromBackingInt(@intCast(raw_node_idx)));
                try visitor.exportName(item.name);
                if (item.alias) |alias| try visitor.exportName(alias);
            },
            .statement_decl,
            .statement_var,
            .statement_var_uninitialized,
            .statement_reassign,
            .statement_crash,
            .statement_dbg,
            .statement_expr,
            .statement_expect,
            .statement_for,
            .statement_while,
            .statement_infinite_loop,
            .statement_breakable_loop,
            .statement_break,
            .statement_return,
            .statement_import,
            .statement_alias_decl,
            .statement_nominal_decl,
            .statement_where_alias_decl,
            .statement_type_anno,
            .statement_type_var_alias,
            .expr_var,
            .expr_tuple,
            .expr_tuple_access,
            .expr_list,
            .expr_empty_list,
            .expr_call,
            .expr_record,
            .expr_empty_record,
            .expr_interpolation,
            .expr_structural_eq,
            .expr_structural_hash,
            .expr_static_dispatch,
            .expr_external_lookup,
            .expr_associated_lookup_local,
            .expr_associated_lookup,
            .expr_associated_lookup_resolved,
            .expr_required_lookup,
            .expr_apply,
            .expr_string,
            .expr_string_segment,
            .expr_bytes_literal,
            .expr_num,
            .expr_frac_f32,
            .expr_frac_f64,
            .expr_dec,
            .expr_dec_small,
            .expr_num_from_numeral,
            .expr_nominal,
            .expr_nominal_external,
            .expr_lambda,
            .expr_record_update,
            .expr_bin_op,
            .expr_unary_minus,
            .expr_suffix_single_question,
            .expr_if_then_else,
            .expr_match,
            .expr_dbg,
            .expr_crash,
            .expr_expect_err,
            .expr_block,
            .expr_ellipsis,
            .expr_anno_only,
            .expr_derived_method,
            .expr_low_level,
            .expr_run_low_level,
            .expr_expect,
            .expr_for,
            .expr_record_builder,
            .expr_return,
            .expr_break,
            .match_branch,
            .match_branch_pattern,
            .annotation,
            .ty_apply_external,
            .ty_rigid_var,
            .ty_rigid_var_lookup,
            .ty_underscore,
            .ty_tag_union,
            .ty_tuple,
            .ty_record,
            .ty_fn,
            .ty_parens,
            .ty_lookup_external,
            .ty_malformed,
            .where_malformed,
            .pattern_identifier,
            .pattern_var_identifier,
            .pattern_as,
            .pattern_nominal,
            .pattern_nominal_external,
            .pattern_record_destructure,
            .pattern_list,
            .pattern_tuple,
            .pattern_num_literal,
            .pattern_dec_literal,
            .pattern_num_from_numeral_literal,
            .pattern_f32_literal,
            .pattern_f64_literal,
            .pattern_small_dec_literal,
            .pattern_str_literal,
            .pattern_str_interpolation,
            .pattern_underscore,
            .lambda_capture,
            .def,
            .if_branch,
            .type_var_slot,
            .malformed,
            .diag_not_implemented,
            .diag_invalid_num_literal,
            .diag_empty_single_quote,
            .diag_empty_tuple,
            .diag_ident_already_in_scope,
            .diag_ident_not_in_scope,
            .diag_read_uninitialized_var,
            .diag_self_referential_definition,
            .diag_circular_value_definition,
            .diag_local_reference_before_definition,
            .diag_mutually_recursive_local_definitions,
            .diag_erroneous_value_use,
            .diag_erroneous_value_expr,
            .diag_qualified_ident_does_not_exist,
            .diag_invalid_top_level_statement,
            .diag_invalid_associated_statement,
            .diag_expr_not_canonicalized,
            .diag_expr_syntax_error,
            .diag_unreachable_string_pattern_capture,
            .diag_pattern_arg_invalid,
            .diag_pattern_not_canonicalized,
            .diag_malformed_type_annotation,
            .diag_malformed_where_clause,
            .diag_where_clause_not_allowed_in_type_decl,
            .diag_where_alias_constraint_not_on_receiver,
            .diag_open_ext_not_allowed_in_type_decl,
            .diag_unnamed_field_not_allowed_in_structural_record,
            .diag_optional_field_cannot_have_default,
            .diag_record_default_reference_cycle,
            .diag_type_module_missing_matching_type,
            .diag_type_module_has_alias_not_nominal,
            .diag_default_app_missing_main,
            .diag_default_app_wrong_arity,
            .diag_cannot_import_default_app,
            .diag_type_name_case_mismatch,
            .diag_module_header_deprecated,
            .diag_roc_version_mismatch,
            .diag_redundant_expose_main_type,
            .diag_invalid_main_type_rename_in_exposing,
            .diag_var_across_function_boundary,
            .diag_shadowing_warning,
            .diag_binding_name_does_not_match_mutability,
            .diag_var_in_binder_pattern,
            .diag_type_redeclared,
            .diag_undeclared_type,
            .diag_undeclared_type_var,
            .diag_type_alias_but_needed_nominal,
            .diag_type_alias_redeclared,
            .diag_file_import_not_found,
            .diag_file_import_io_error,
            .diag_file_import_absolute_path,
            .diag_file_import_not_utf8,
            .diag_module_not_found,
            .diag_value_not_exposed,
            .diag_type_not_exposed,
