test "mixed field-access segment labels are lowering-visible" {
    const allocator = std.testing.allocator;
    var module_env = try ModuleEnv.init(allocator, "");
    defer module_env.deinit();
    try module_env.initCIRFields("Test");

    const required_name = try module_env.insertIdent(Ident.for_text("required_field"));
    const optional_name = try module_env.insertIdent(Ident.for_text("optional_field"));
    const receiver = try module_env.addExpr(.{ .e_empty_record = .{} }, base.Region.zero());

    const path = try module_env.startFieldAccessPath(2);
    _ = module_env.appendFieldAccessPathSegmentAssumeCapacity(path, .{
        .name = optional_name,
        .mode = .optional,
    }, base.Region.zero());
    _ = module_env.appendFieldAccessPathSegmentAssumeCapacity(path, .{
        .name = required_name,
        .mode = .required,
    }, base.Region.zero());
    const segments = module_env.finishFieldAccessPath(path);
    _ = try module_env.addExpr(.{ .e_field_access = .{
        .receiver = receiver,
        .segments = segments,
    } }, base.Region.zero());

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(&module_env, &names);

    const idents = module_env.getIdentStoreConst();
    try std.testing.expect(names.lookupRecordFieldIdent(idents, required_name) != null);
    try std.testing.expect(names.lookupRecordFieldIdent(idents, optional_name) != null);
    verifyLoweringVisibleNamesInterned(&module_env, &names);
}

/// Public `loweringView` function.
pub fn loweringView(checked: *const CheckedModule) Allocator.Error!LoweringModuleView {
    return .{
        .module = checked,
        .roots = try checked.rootRequests(),
        .relation_modules = &.{},
    };
}

/// Public `loweringViewWithRelations` function.
pub fn loweringViewWithRelations(
    checked: *const CheckedModule,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!LoweringModuleView {
    return .{
        .module = checked,
        .roots = try checked.rootRequests(),
        .relation_modules = relation_modules,
    };
}

/// Inputs from imported modules and platform relation checking that participate
/// in the checked module cache identity.
pub const CheckedModuleKeyInputs = struct {
    imports: []const CheckedImport = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
};

/// Compute the checked module cache identity for a module environment whose
/// imports are resolved, and the checked data it depends on. The identity
/// reads only the environment's source inputs, content identity, and resolved
/// imports, so it needs no typed module graph.
pub fn checkedModuleKeyFromModuleEnv(
    allocator: Allocator,
    module_env: *const ModuleEnv,
    inputs: CheckedModuleKeyInputs,
) Allocator.Error!CheckedModuleKey {
    var identity = try CheckedModuleIdentity.compute(allocator, module_env, inputs);
    defer identity.deinit(allocator);
    return identity.key;
}

/// A checked module's identity: its key and what the key is computed from
/// beside the module's identity hash. A function of the module's source
/// inputs, its direct imports' keys and its checking context, computed by the
/// one function both a cache probe and opening the module call.
pub const CheckedModuleIdentity = struct {
    key: CheckedModuleKey,
    source_hash: [32]u8,
    checking_context_identity: CheckingContextIdentity,
    direct_import_module_keys: []CheckedModuleKey,

    /// The identity of `module_env`, whose imports are resolved, checked in
    /// the context `inputs` names.
    pub fn compute(
        allocator: Allocator,
        module_env: *const ModuleEnv,
        inputs: CheckedModuleKeyInputs,
    ) Allocator.Error!CheckedModuleIdentity {
        var checking_context_identity = try CheckingContextIdentity.fromModule(
            allocator,
            module_env,
            inputs.imports,
            inputs.platform_requirement_context,
        );
        errdefer checking_context_identity.deinit(allocator);
        const direct_import_module_keys = try directImportModuleKeysFromModule(allocator, module_env, inputs.imports);
        const source_hash = hashModuleSourceInputs(module_env);
        return .{
            .key = CheckedModuleKey.computeFromIdentityHash(
                source_hash,
                computeStableModuleIdentityHash(module_env),
                checking_context_identity,
                direct_import_module_keys,
            ),
            .source_hash = source_hash,
            .checking_context_identity = checking_context_identity,
            .direct_import_module_keys = direct_import_module_keys,
        };
    }

    pub fn deinit(self: *CheckedModuleIdentity, allocator: Allocator) void {
        self.checking_context_identity.deinit(allocator);
        allocator.free(self.direct_import_module_keys);
        self.* = undefined;
    }
};

/// Inference admission is deliberately separate from module identity. The
/// producer-owned checking scope supplies dependency facts and owner equality;
/// the full imported implementation keys continue to key every checked module.
pub fn inferenceKeyFromModuleEnv(
    module_env: *const ModuleEnv,
    scope_hash: [32]u8,
    platform_requirement_owner: ?u32,
    source_pin_validation: [32]u8,
    missing_public_types: []const []const u8,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update("roc-inference-inputs-v2");
    hasher.update(&hashModuleSourceInputs(module_env));
    hasher.update(&scope_hash);
    hashByteSlice(&hasher, module_env.module_name);
    hashByteSlice(&hasher, @tagName(module_env.module_kind));
    hashByteSlice(&hasher, @tagName(module_env.module_role));
    if (platform_requirement_owner) |owner| {
        hasher.update(&.{1});
        hashU32(&hasher, owner);
    } else hasher.update(&.{0});
    hasher.update(&source_pin_validation);
    const imports = module_env.imports.imports.items.items;
    hashU32(&hasher, @intCast(imports.len));
    for (imports, 0..) |name, i| {
        hashByteSlice(&hasher, module_env.getString(name));
        const import_idx: CIR.Import.Idx = @fromBackingInt(@as(u32, @intCast(i)));
        hashU32(&hasher, module_env.imports.getResolvedModule(import_idx) orelse std.math.maxInt(u32));
    }
    hashU32(&hasher, @intCast(missing_public_types.len));
    for (missing_public_types) |name| hashByteSlice(&hasher, name);
    return hasher.finalResult();
}

/// The defaulted-field expressions this module declares that its checked
/// types or its record constructions name, ascending.
fn moduleDefaultExprs(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_source_types: *const CheckedSourceTypes,
) Allocator.Error![]CIR.Expr.Idx {
    const module_env = module.moduleEnvConst();
    const self_origin = try names.internModuleIdentity(module_env.moduleIdentityHash(module_env.selfModuleIdentity()));
    var defaults = std.ArrayList(CIR.Expr.Idx).empty;
    errdefer defaults.deinit(allocator);
    for (checked_source_types.store.publishedRecordFields()) |field| {
        const default = field.kind.defaultIdentity() orelse continue;
        const default_origin = default.origin() orelse
            checkedModuleInvariant("checked defaulted field kind carried no default identity", .{});
        if (default_origin != self_origin) continue;
        try defaults.append(allocator, @fromBackingInt(@intCast(default.expr_node)));
    }
    for (module_env.record_omitted_defaults.items.items) |omitted| {
        const origin_module = try names.internModuleIdentity(module_env.moduleIdentityHash(omitted.origin_module));
        if (origin_module != self_origin) continue;
        try defaults.append(allocator, @fromBackingInt(@intCast(omitted.default_expr_node)));
    }
    std.mem.sort(CIR.Expr.Idx, defaults.items, {}, struct {
        fn lessThan(_: void, a: CIR.Expr.Idx, b: CIR.Expr.Idx) bool {
            return @backingInt(a) < @backingInt(b);
        }
    }.lessThan);
    var len: usize = 0;
    for (defaults.items) |default| {
        if (len > 0 and defaults.items[len - 1] == default) continue;
        defaults.items[len] = default;
        len += 1;
    }
    defaults.shrinkRetainingCapacity(len);
    return defaults.toOwnedSlice(allocator);
}

/// A module's checked tables: its procedure templates, method registry,
/// static dispatch plans, compile-time roots, entry wrappers, top-level
/// values with their procedure bindings, callable-eval and constant
/// templates, hoisted constants and resolved value references. One slot of
/// the module's analyses computes them together
/// (`ModuleAnalyses.checkedTables`), because each is built from and completes
/// the others; nothing here is serialized.
pub const CheckedTables = struct {
    method_registry: static_dispatch.MethodRegistry,
    static_dispatch_plans: static_dispatch.StaticDispatchPlanTable,
    resolved_value_refs: ResolvedValueRefTable,
    checked_procedure_templates: CheckedProcedureTemplateTable,
    entry_wrappers: EntryWrapperTable,
    top_level_procedure_bindings: TopLevelProcedureBindingTable,
    callable_eval_templates: CallableEvalTemplateTable,
    compile_time_roots: CompileTimeRootTable,
    top_level_values: TopLevelValueTable,
    hoisted_constants: HoistedConstTable,
    const_templates: ConstTemplateTable,

    pub fn destroy(self: *CheckedTables, allocator: Allocator) void {
        self.method_registry.deinit(allocator);
        self.static_dispatch_plans.deinit(allocator);
        self.resolved_value_refs.deinit(allocator);
        self.checked_procedure_templates.deinit(allocator);
        self.entry_wrappers.deinit(allocator);
        self.top_level_procedure_bindings.deinit(allocator);
        self.callable_eval_templates.deinit(allocator);
        self.compile_time_roots.deinit(allocator);
        self.top_level_values.deinit(allocator);
        self.hoisted_constants.deinit(allocator);
        self.const_templates.deinit(allocator);
        allocator.destroy(self);
    }
};

/// The checked tables of `owner`, an opened module, computed from its live
/// checked data: its environment, sealed solver store and recorded outputs,
/// its body analyses, and the modules its resolver resolves. The types the
/// tables name that have no solver variable (the empty record of a
/// valueless root, entry wrapper function types and their schemes) are
/// created through the module's type store, each creation after every slot
/// read that precedes it.
pub fn computeCheckedTables(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!*CheckedTables {
    const env = owner.module_env;
    const module_idx = owner.module_identity.module_idx;
    var module_data = TypedCIR.ModuleData.readOnly(env);
    const module = TypedCIR.Module.readOnly(allocator, module_idx, &module_data);
    const analyses = owner.analyses();
    const io = analyses.io;
    const module_body_analyses = owner.body_analyses orelse checkedModuleInvariant("checked tables were demanded of a view without body analyses", .{});
    const module_index = &module_body_analyses.index;
    const names: *canonical.CanonicalNameStore = @constCast(owner.canonical_names);
    const store = owner.checked_types.store orelse checkedModuleInvariant("checked tables were demanded of a view without a type store", .{});
    const module_key = owner.key;
    const owner_module = module_key.digest();
    // A module given no resolver reads no other module.
    const resolver = analyses.resolver orelse no_import_views.resolver();

    const promoted_local_procedures = env.promoted_local_procedures.items.items;
    const selected_hoisted_roots = env.selected_hoisted_roots.items.items;
    var checked_types = try CheckedSourceTypes.init(allocator, module, .{
        .module_index = module_index,
        .selected_hoisted_roots = selected_hoisted_roots,
        .promoted_local_procedures = promoted_local_procedures,
    }, store, owner.checked_types, owner_module, resolver);
    defer checked_types.deinit();

    const imports = try directImportModules(allocator, owner, resolver);
    defer allocator.free(imports);
    // An associated lookup names its target's module by content identity:
    // a module the module's direct imports and its types' name owners
    // reach.
    const reached = try analyses.reachedImports(owner_module, owner.direct_import_module_keys, store);
    // The tables read the nominal representations of the module's types and
    // of the types of every module it reaches, whose capabilities, with the
    // module's own, exist before the tables create any type
    // (`demandCheckedTablesInputs`).
    const bodies_for = struct {
        fn make(view: ImportedModuleView, body_index: *BodyAnalyses, tables: checked_bodies_mod.Tables) CheckedBodies {
            return .{ .env = view.module_env, .names = view.canonical_names, .types = view.checked_types, .analyses = body_index, .tables = tables };
        }
    }.make;

    const default_exprs = try moduleDefaultExprs(allocator, module, names, &checked_types);
    defer allocator.free(default_exprs);
    const body_tables = checked_bodies_mod.Tables{ .module = owner_module };

    const value_binding_defs = env.store.sliceDefs(env.value_binding_defs);

    const tables = try allocator.create(CheckedTables);
    errdefer allocator.destroy(tables);

    var checked_procedure_templates = try CheckedProcedureTemplateTable.fromModule(allocator, module, value_binding_defs, owner_module, &checked_types, module_index);
    errdefer checked_procedure_templates.deinit(allocator);
    try checked_procedure_templates.appendPromotedLocalProcedures(allocator, module, owner_module, &checked_types, module_index, promoted_local_procedures);
    const template_lookup = checked_procedure_templates.asLookup(module_idx);

    var static_dispatch_plans = try static_dispatch.StaticDispatchPlanTable.fromModule(allocator, module, names, &checked_types, bodies_for(owner, module_body_analyses, body_tables));
    errdefer static_dispatch_plans.deinit(allocator);

    // A module has no app relation; only a pairing binds its requirements.
    const platform_required_bindings = PlatformRequiredBindingTable{};

    // A valueless root's type is the empty record, a type with no solver
    // variable, and a pattern-validation hoisted constant's scheme is that
    // type's synthetic scheme.
    const valueless = valuelessRootTypes(selected_hoisted_roots);
    var empty_record: ?CheckedTypeId = null;
    var empty_record_scheme: ?CheckedTypeSchemeId = null;
    if (valueless.empty_record) {
        store.beginCreation(io);
        errdefer store.endCreation(io);
        const root = try store.ensureEmptyRecordRoot(allocator);
        empty_record = root;
        if (valueless.validation_scheme) empty_record_scheme = try store.ensureSchemeForRoot(allocator, root);
        try store.finishCreation(allocator, io);
    }

    var compile_time_roots = try CompileTimeRootTable.fromModule(allocator, module, value_binding_defs, &checked_types, module_index, &checked_procedure_templates, empty_record);
    errdefer compile_time_roots.deinit(allocator);

    var entry_wrappers = EntryWrapperTable{};
    errdefer entry_wrappers.deinit(allocator);
    if (compile_time_roots.roots.len != 0) {
        store.beginCreation(io);
        errdefer store.endCreation(io);
        try checked_procedure_templates.appendEntryWrappersForRoots(allocator, owner_module, store, &entry_wrappers, compile_time_roots.roots);
        try store.finishCreation(allocator, io);
    }

    var top_level_procedure_bindings = TopLevelProcedureBindingTable.initEmpty();
    errdefer top_level_procedure_bindings.deinit(allocator);
    var callable_eval_templates = CallableEvalTemplateTable{};
    errdefer callable_eval_templates.deinit(allocator);
    var const_templates = ConstTemplateTable{};
    errdefer const_templates.deinit(allocator);

    var top_level_values = try TopLevelValueTable.fromModule(allocator, module, value_binding_defs, names, module_index, &checked_procedure_templates, &callable_eval_templates, &top_level_procedure_bindings, &const_templates, module_key, &compile_time_roots, &checked_types);
    errdefer top_level_values.deinit(allocator);

    var hoisted_constants = try HoistedConstTable.fromRoots(allocator, module, module_key, empty_record_scheme, &compile_time_roots, &const_templates, &checked_types);
    errdefer hoisted_constants.deinit(allocator);

    var selected_hoisted_callables = try SelectedHoistedCallableTable.fromRoots(allocator, module, &compile_time_roots, &callable_eval_templates, &top_level_procedure_bindings, &checked_types, checked_procedure_templates.promoted);
    defer selected_hoisted_callables.deinit(allocator);

    var resolved_value_refs = try ResolvedValueRefTable.fromModule(allocator, module, module_key, imports, reached, &checked_procedure_templates, owner.platformRequiredDeclarations(), &platform_required_bindings, &top_level_values, &selected_hoisted_callables, &hoisted_constants, &checked_types);
    errdefer resolved_value_refs.deinit(allocator);
    applyBindingResolutions(env, &callable_eval_templates, &top_level_procedure_bindings);

    var method_binding_targets = MethodBindingTargets{
        .allocator = allocator,
        .module = module,
        .owner = owner_module,
        .module_index = module_index,
        .resolved_value_refs = &resolved_value_refs,
        .procedure_bindings = &top_level_procedure_bindings,
        .callable_eval_templates = &callable_eval_templates,
        .templates = &checked_procedure_templates,
        .resolver = resolver,
    };
    defer method_binding_targets.deinit();
    var method_registry = try static_dispatch.MethodRegistry.fromModule(allocator, module, names, owner_module, &template_lookup, &checked_types, module_index, &method_binding_targets);
    errdefer method_registry.deinit(allocator);

    var resolved_tables = body_tables;
    resolved_tables.refs = &resolved_value_refs;
    resolved_tables.plans = &static_dispatch_plans;
    var ordinary_diagnostics = try body_analyses.diagnosticErrors(allocator, bodies_for(owner, module_body_analyses, resolved_tables), .ordinary);
    defer ordinary_diagnostics.deinit(allocator);

    try sealCheckedProcedureTemplateRefs(allocator, module, &checked_types, bodies_for(owner, module_body_analyses, resolved_tables), &ordinary_diagnostics, default_exprs, &compile_time_roots, &entry_wrappers, &checked_procedure_templates, &static_dispatch_plans, &method_registry, &resolved_value_refs);

    sealConstEvalTemplatesForRoots(&const_templates, &compile_time_roots, &entry_wrappers, &checked_procedure_templates, &top_level_values, &hoisted_constants);

    tables.* = .{
        .method_registry = method_registry,
        .static_dispatch_plans = static_dispatch_plans,
        .resolved_value_refs = resolved_value_refs,
        .checked_procedure_templates = checked_procedure_templates,
        .entry_wrappers = entry_wrappers,
        .top_level_procedure_bindings = top_level_procedure_bindings,
        .callable_eval_templates = callable_eval_templates,
        .compile_time_roots = compile_time_roots,
        .top_level_values = top_level_values,
        .hoisted_constants = hoisted_constants,
        .const_templates = const_templates,
    };
    return tables;
}

/// Demand what `computeCheckedTables` reads of modules other than `owner`:
/// the export rows of its direct imports and of every module they and its
/// types' name owners reach, and the interface capabilities of those modules
/// and its own.
pub fn demandCheckedTablesInputs(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!void {
    const analyses = owner.analyses();
    const resolver = analyses.resolver orelse no_import_views.resolver();
    const store = owner.checked_types.store orelse checkedModuleInvariant("checked tables were demanded of a view without a type store", .{});
    const imports = try directImportModules(allocator, owner, resolver);
    defer allocator.free(imports);
    const reached = try analyses.reachedImports(owner.key.digest(), owner.direct_import_module_keys, store);
    _ = try owner.checked_types.interfaceCapabilities();
    for (imports) |import| {
        _ = try import.view.checked_types.interfaceCapabilities();
        _ = try import.view.exportRows();
    }
    for (reached) |view| {
        _ = try view.checked_types.interfaceCapabilities();
        _ = try view.exportRows();
    }
}

/// The import views of a module that reads no other module.
const no_import_views = CheckedImportViews{ .current_owner = .{}, .direct = &.{} };

/// The direct imports of `owner` as checking resolved them: each resolved
/// import's module index in the importing build, key and view.
fn directImportModules(allocator: Allocator, owner: ImportedModuleView, resolver: ModuleResolver) Allocator.Error![]CheckedImport {
    const imports = &owner.module_env.imports;
    const count = imports.imports.items.items.len;
    var result = std.ArrayList(CheckedImport).empty;
    errdefer result.deinit(allocator);
    for (0..count) |raw| {
        const import_idx: CIR.Import.Idx = @fromBackingInt(@as(u32, @intCast(raw)));
        const module_idx = imports.getResolvedModule(import_idx) orelse continue;
        const key = owner.importKey(import_idx) orelse checkedModuleInvariant("a resolved import has no key", .{});
        try result.append(allocator, .{ .module_idx = module_idx, .key = key, .view = resolver.require(key.digest()) });
    }
    return try result.toOwnedSlice(allocator);
}

/// Resolves a method bound by reference (`method = f`) for
/// `MethodRegistry.fromModule`, from the module's resolved value references
/// and procedure bindings: the method's value is followed through exact
/// procedure aliases, in this module and the modules they forward into, to
/// the procedure it reaches. This is the chain Monotype and Boxy compose an
/// alias-bound method's instantiation along (design.md "Procedure Aliases").
/// Every module the chain enters is one this module reaches through its
/// imports, whose checked tables are computed before this module's
/// (`demandCheckedTablesInputs`).
const MethodBindingTargets = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    owner: ModuleId,
    module_index: *const ModuleIndex,
    resolved_value_refs: *const ResolvedValueRefTable,
    procedure_bindings: *const TopLevelProcedureBindingTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    templates: *const CheckedProcedureTemplateTable,
    resolver: ModuleResolver,
    /// The declaring statement of each local declaration's pattern, built
    /// on the first method that reaches an unpromoted local procedure.
    decl_statements: ?[]?CIR.Statement.Idx = null,

    fn deinit(self: *MethodBindingTargets) void {
        if (self.decl_statements) |statements| self.allocator.free(statements);
        self.* = undefined;
    }

    pub fn methodBindingTarget(
        self: *MethodBindingTargets,
        binding_expr: CIR.Expr.Idx,
        method_owner: static_dispatch.MethodOwner,
    ) Allocator.Error!?static_dispatch.ReferencedMethodTarget {
        // The module whose references the current lookup is in: null for
        // this one.
        var view: ?ImportedModuleView = null;
        var expr = binding_expr;
        while (true) {
            const refs: *const ResolvedValueRefTable = if (view) |imported| try imported.valueRefs() else self.resolved_value_refs;
            const ref_id = refs.lookupIdByExpr(expr) orelse {
                // The binding's value is not a reference.
                if (view != null) checkedModuleInvariant("a forwarded procedure alias lookup had no resolved reference", .{});
                return null;
            };
            const use: ProcedureUseTemplate = switch (refs.records[@backingInt(ref_id)].ref) {
                .local_proc => |local| {
                    if (view != null) checkedModuleInvariant("a top-level procedure alias forwarded to a local procedure", .{});
                    if (local.is_alias) {
                        expr = local.expr;
                        continue;
                    }
                    return try self.localProcedureTarget(local);
                },
                .top_level_proc, .imported_proc, .promoted_top_level_proc, .hosted_proc => |use| use,
                .platform_required_proc => |required| required.procedure,
                // A value, not a procedure: an associated value.
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                => return null,
            };
            const body = try self.useBody(use) orelse {
                const hosted = switch (use.binding) {
                    .hosted => |hosted| hosted,
                    .top_level, .imported, .platform_required => checkedModuleInvariant("a procedure use with no binding body was not hosted", .{}),
                };
                return try self.procedureTarget(null, hosted.proc, hosted.template, use, method_owner);
            };
            switch (body.body) {
                .direct_template => |direct| {
                    const template = switch (direct.template) {
                        .checked => |template| template,
                        .lifted, .synthetic => checkedModuleInvariant("a method's procedure alias reached a template checking did not publish", .{}),
                    };
                    return try self.procedureTarget(body.view, direct.proc_value, template, use, method_owner);
                },
                // An alias of a computed callable is not a forward: the
                // method's value is evaluated, not a procedure.
                .callable_eval_template => |template_id| {
                    const template = if (body.view) |imported|
                        (try imported.checkedTables()).callable_eval_templates.get(template_id)
                    else
                        self.callable_eval_templates.get(template_id);
                    expr = template.forwarded_lookup orelse return null;
                    view = body.view;
                },
                .checked_error => return .rejected,
            }
        }
    }

    /// The binding body of a procedure use and the module that owns it (null
    /// for this one). Hosted procedures have no binding body.
    fn useBody(self: *const MethodBindingTargets, use: ProcedureUseTemplate) Allocator.Error!?ProcedureUseBody {
        const top_level: ModuleTopLevelProcedureBindingRef = switch (use.binding) {
            .top_level => |top_level| top_level,
            .platform_required => |required| .{ .module = required.module, .binding = required.procedure_binding },
            .hosted => return null,
            .imported => |imported| {
                const view = self.resolver.require(imported.module);
                const binding = (try view.exportRows()).procedureBinding(imported.def, imported.pattern) orelse
                    checkedModuleInvariant("an imported procedure use was not exported by its checked module", .{});
                return .{ .view = view, .body = binding.body };
            },
        };
        if (top_level.module.eql(self.owner)) return .{ .view = null, .body = self.procedure_bindings.get(top_level.binding).body };
        const view = self.resolver.require(top_level.module);
        return .{ .view = view, .body = (try view.checkedTables()).top_level_procedure_bindings.get(top_level.binding).body };
    }

    /// The target of the procedure `template`, owned by `view` (null for this
    /// module), that `use` reaches.
    fn procedureTarget(
        self: *const MethodBindingTargets,
        view: ?ImportedModuleView,
        proc: canonical.ProcedureValueRef,
        template_ref: canonical.ProcedureTemplateRef,
        use: ProcedureUseTemplate,
        method_owner: static_dispatch.MethodOwner,
    ) Allocator.Error!static_dispatch.ReferencedMethodTarget {
        const table: *const CheckedProcedureTemplateTable = if (view) |imported| &(try imported.checkedTables()).checked_procedure_templates else self.templates;
        const template = table.get(template_ref.template);
        // A promoted local procedure has no source definition and is always
        // callable.
        if (template_ref.proc_base.sourceDef()) |raw_def| {
            const def: CIR.Def.Idx = @fromBackingInt(@intCast(raw_def));
            const entry = table.lookupEntryByDef(def) orelse
                checkedModuleInvariant("a method's procedure alias reached a source definition with no template", .{});
            switch (entry.kind) {
                .callable => {},
                .structural => |kind| return .{ .target = .{
                    .kind = .{ .structural = kind },
                    .callable = if (view == null)
                        .{ .source = self.module.defType(def) }
                    else
                        .binding,
                } },
            }
        }
        return .{ .target = .{
            .kind = .{ .procedure = .{
                .proc = proc,
                .template = template_ref,
                .runtime_target = static_dispatch.procedureRuntimeTarget(
                    use.intrinsic,
                    use.iterator_procedure,
                    template.provided_low_level,
                    method_owner,
                ),
            } },
            .callable = .{ .template_root = template.checked_fn_root },
        } };
    }

    /// The target of an unpromoted local procedure a method's chain of local
    /// bindings reaches, declared at its own statement.
    fn localProcedureTarget(self: *MethodBindingTargets, local: LocalProcedureBinding) Allocator.Error!?static_dispatch.ReferencedMethodTarget {
        const statement = (try self.declStatements())[@backingInt(local.binder)] orelse
            checkedModuleInvariant("a local procedure binding had no declaring statement", .{});
        if (!self.module_index.reachesPattern(local.binder)) return null;
        if (!self.module_index.reachesStatement(statement)) return null;
        return .{ .target = .{
            .kind = .{ .local_proc = .{
                .binder = local.binder,
                .expr = local.expr,
                .context_anchor = statement,
            } },
            .callable = .{ .source = self.module.exprType(local.expr) },
        } };
    }

    fn declStatements(self: *MethodBindingTargets) Allocator.Error![]?CIR.Statement.Idx {
        if (self.decl_statements) |statements| return statements;
        const node_count = self.module.nodeCount();
        const statements = try self.allocator.alloc(?CIR.Statement.Idx, node_count);
        @memset(statements, null);
        var raw_node: u32 = 0;
        while (raw_node < node_count) : (raw_node += 1) {
            if (self.module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .statement_decl) continue;
            const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node));
            const statement_data = self.module.getStatement(statement);
            if (std.meta.activeTag(statement_data) != .s_decl) continue;
            statements[@backingInt(statement_data.s_decl.pattern)] = statement;
        }
        self.decl_statements = statements;
        return statements;
    }
};

/// Whether a module's selected hoisted roots include a valueless one, whose
/// type is the empty record, and a pattern-validation one, whose hoisted
/// constant's scheme is that type's synthetic scheme.
fn valuelessRootTypes(selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot) struct { empty_record: bool, validation_scheme: bool } {
    var empty_record = false;
    var validation_scheme = false;
    for (selected_hoisted_roots) |selected| switch (selected.body) {
        .pattern_validation => {
            empty_record = true;
            if (selected.value_kind == .data_constant) validation_scheme = true;
        },
        .valueless_binding => empty_record = true,
        .expr, .pattern_error, .pattern_extraction => {},
    };
    return .{ .empty_record = empty_record, .validation_scheme = validation_scheme };
}

/// Open the live checked module of `inputs.module_env_storage`, whose type
/// store checking sealed: its identity, name store, synthesized-type store
/// and analyses over its `ModuleEnv` and imports, with its inference and
/// evaluation outputs. Every embedder opens a module this way, right after
/// checking it and when loading its stored outputs; the module computes
/// every other fact on demand.
pub fn openCheckedModule(
    allocator: Allocator,
    inputs: OpenInputs,
) Allocator.Error!CheckedModule {
    const module_env = inputs.module_env_storage.envConst();
    if (std.debug.runtime_safety and !module_env.types.isSealed()) {
        base.invariant("a checked module was opened from a module whose type store checking never sealed", .{});
    }
    const module_idx = inputs.module_idx;
    var module_data = TypedCIR.ModuleData.readOnly(module_env);
    const module = TypedCIR.Module.readOnly(allocator, module_idx, &module_data);
    const idents = module.identStoreConst();

    var canonical_names = canonical.CanonicalNameStore.init(allocator);
    // The module owns the name store and the type store once it is formed:
    // its slots grow them from then on.
    var stores_moved = false;
    errdefer if (!stores_moved) canonical_names.deinit();
    const module_name = try canonical_names.internModuleName(module_env.module_name);
    const display_module_name = try canonical_names.internModuleIdent(idents, module_env.display_module_name_idx);
    const module_identity = ModuleIdentity{
        .stable_hash = computeStableModuleIdentityHash(module_env),
        .module_idx = module_idx,
        .module_name = module_name,
        .display_module_name = display_module_name,
        .kind = module_env.module_kind,
    };
    // Intern this module's content identity up front so the module's
    // analyses (e.g. interface capability collection) resolve it by lookup.
    _ = try canonical_names.internModuleIdentity(&module_identity.stable_hash);

    try internLoweringVisibleNames(module_env, &canonical_names);
    _ = try canonical_names.internTagLabel("#Missing");
    _ = try canonical_names.internTagLabel("#Present");

    var identity = try CheckedModuleIdentity.compute(allocator, module_env, .{
        .imports = inputs.imports,
        .platform_requirement_context = inputs.platform_requirement_context,
    });
    errdefer identity.deinit(allocator);

    try internProvidedExportNames(module_env, &canonical_names);
    try internHostedSymbolNames(module_env, &canonical_names);

    const promoted_local_procedures = module_env.promoted_local_procedures.items.items;
    const selected_hoisted_roots = module_env.selected_hoisted_roots.items.items;
    const analyses = try BodyAnalyses.create(allocator, inputs.io, module_env, promoted_local_procedures);
    var analyses_owned = true;
    errdefer if (analyses_owned) analyses.destroy();
    const module_index = &analyses.index;
    const module_analyses = try ModuleAnalyses.create(allocator, inputs.io, null);
    var module_analyses_owned = true;
    errdefer if (module_analyses_owned) module_analyses.destroy();
    try module_analyses.attachExplicitRoots(inputs.explicit_roots);
    // The module's types read the nominal representations of the types of
    // every module it imports or resolves against.
    for (inputs.imports) |import| _ = try import.view.checked_types.interfaceCapabilities();
    for (inputs.available_modules) |available| _ = try available.checked_types.interfaceCapabilities();
    if (inputs.resolver) |resolver| {
        module_analyses.attachResolver(resolver);
    } else {
        try module_analyses.attachImportViews(inputs.imports, inputs.available_modules);
    }

    // Omitted defaults name their fields and origin modules through the
    // module's names.
    for (module_env.record_omitted_defaults.items.items) |omitted| {
        _ = try canonical_names.internRecordFieldIdent(idents, omitted.field_name);
        _ = try canonical_names.internModuleIdentity(module_env.moduleIdentityHash(omitted.origin_module));
    }

    const sealed_keys = try sealed_type_keys.SealedTypeKeys.create(allocator, inputs.io, module_env);
    var sealed_keys_owned = true;
    errdefer if (sealed_keys_owned) sealed_keys.destroy();
    var checked_type_store = try CheckedTypeStore.fromModule(allocator, module, &canonical_names, identity.key.digest(), inputs.imports, inputs.available_modules, module_index, selected_hoisted_roots, promoted_local_procedures, sealed_keys);
    errdefer if (!stores_moved) checked_type_store.deinit(allocator);
    checked_type_store.markPublished();
    checked_type_store.releaseSuperseded(allocator);

    var inference: InferenceOutput = .{};
    var serialized_backing: ?[]align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8 = null;
    var serialized_backing_borrowed = false;
    var stored_evaluation: ?EvaluationOutput = null;
    switch (inputs.outputs) {
        .checked => |checked| inference = try checked.dupe(allocator),
        .stored => |stored| {
            const serialized: *const CheckedModule.Serialized = @ptrCast(@alignCast(stored.backing.ptr));
            inference = serialized.inference.deserialize(@intFromPtr(stored.backing.ptr));
            stored_evaluation = serialized.evaluation.deserialize(@intFromPtr(stored.backing.ptr), allocator);
            serialized_backing = stored.backing;
            serialized_backing_borrowed = stored.backing_borrowed;
        },
    }
    errdefer if (serialized_backing == null) inference.deinit(allocator);

    var checked = CheckedModule{
        .key = identity.key,
        .source_hash = identity.source_hash,
        .canonical_names = canonical_names,
        .module_identity = module_identity,
        .checking_context_identity = identity.checking_context_identity,
        .direct_import_module_keys = identity.direct_import_module_keys,
        .module_env = inputs.module_env_storage,
        .checked_types = checked_type_store,
        .inference = inference,
        .evaluation = EvaluationOutput.init(allocator),
        .serialized_backing = serialized_backing,
        .serialized_backing_borrowed = serialized_backing_borrowed,
        .body_analyses = analyses,
        .module_analyses = module_analyses,
    };
    // The module owns the key slots from here on, and its views name its
    // own name store (`typesView`). It owns the body analyses once it is
    // returned.
    sealed_keys_owned = false;
    checked.checked_types.key_names = null;
    // Other threads read the module's names from here on, while its
    // analyses intern into them, exactly as they read its types.
    checked.canonical_names.markPublished();
    checked.attachCapabilitySource();
    stores_moved = true;
    errdefer {
        if (checked.checked_types.sealed_keys) |keys| keys.destroy();
        checked.checked_types.deinit(allocator);
        checked.canonical_names.deinit();
    }
    checked.openToAnalyses();
    checked.evaluation = switch (inputs.outputs) {
        .stored => stored_evaluation.?,
        // The evaluation output starts with an entry for every compile-time
        // root and constant template, which the module's checked tables hold.
        .checked => try preparedEvaluationOutput(allocator, try checked.checkedTables()),
    };
    analyses_owned = false;
    module_analyses_owned = false;
    return checked;
}

/// Evaluate every compile-time root of `checked`, a module opened right
/// after checking, and finish its evaluation output.
pub fn evaluateOpenedModule(
    allocator: Allocator,
    checked: *CheckedModule,
    compile_time_finalizer: CompileTimeFinalizer,
    imports: []const CheckedImport,
    available_modules: []const ImportedModuleView,
    problem_store: ?*problem.Store,
) CompileTimeFinalizer.Error!void {
    std.debug.assert(checked.evaluation.state == .prepared);
    try compile_time_finalizer.run(allocator, checked, imports, available_modules, &.{}, problem_store);
    checked.evaluation.state = .finalized;
    try checked.verifyComplete();
}

/// Why the baked Builtin module cannot be opened.
pub const OpenBakedBuiltinError = Allocator.Error || error{ CorruptBuiltinOutputs, BuiltinOutputsVersionMismatch, CorruptSerializedData };

/// Open the Builtin module `env` from `blob`, its baked stored outputs
/// followed by their layout-version trailer. Every compile-time root of
/// Builtin is complete in them, so no embedder evaluates one again.
pub fn openBakedBuiltin(
    allocator: Allocator,
    io: std.Io,
    env: *ModuleEnv,
    blob: []const u8,
) OpenBakedBuiltinError!CheckedModule {
    // A mismatched trailer means the embedded blob is stale relative to this
    // compiler (a build-system inconsistency), which is rejected rather than
    // read as a differently-shaped struct.
    const serialized_bytes = try CheckedModule.splitVersionTrailer(blob);
    const backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8 = @alignCast(@constCast(blob[0..serialized_bytes.len]));
    const serialized: *const CheckedModule.Serialized = @ptrCast(backing.ptr);
    try serialized.validate(backing.len);
    return openCheckedModule(allocator, .{
        .module_env_storage = .{ .static_builtin = env },
        .module_idx = 0,
        .io = io,
        .outputs = .{ .stored = .{ .backing = backing, .backing_borrowed = true } },
    });
}

/// A freshly opened module's evaluation output, awaiting evaluation: an
/// entry for every row of its root table, holding the payload the row starts
/// with, and for every constant template with a body.
fn preparedEvaluationOutput(
    allocator: Allocator,
    tables: *const CheckedTables,
) Allocator.Error!EvaluationOutput {
    const compile_time_roots = &tables.compile_time_roots;
    const const_templates = &tables.const_templates;
    var evaluation = EvaluationOutput.init(allocator);
    errdefer evaluation.deinit(allocator);
    evaluation.state = .prepared;
    const rows = try allocator.alloc(RootOutput, compile_time_roots.roots.len);
    defer allocator.free(rows);
    for (rows, compile_time_roots.roots) |*row, root| row.* = .{
        .id = root.id,
        .payload = switch (root.kind) {
            .expect => .expect,
            .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => .pending,
        },
    };
    try evaluation.addRoots(allocator, true, rows);
    const owners = try const_templates.evaluatedOwners(allocator);
    defer allocator.free(owners);
    try evaluation.addConsts(allocator, owners);
    return evaluation;
}

const ProvidedExportKindExpectation = struct {
    procedure_roots: usize,
    deferred_procedure_roots: usize = 0,
    data_exports: usize,
    procedure_exports: usize,
};

fn expectProvidedExportKind(
    source: []const u8,
    expected: ProvidedExportKindExpectation,
) (@import("test/TestEnv.zig").TestEnvError || CompileTimeFinalizer.Error || error{ CorruptSerializedData, CorruptBuiltinOutputs, BuiltinOutputsVersionMismatch })!void {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const allocator = std.testing.allocator;

    var test_env = try TestEnv.init("PlatformDataExportTest", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    // The baked builtin module is the opened form of the builtin module
    // `test_env` checked against, so it serves as the real direct import.
    var builtin_checked = try openBakedBuiltin(allocator, std.testing.io, test_env.builtin_module.env, compiled_builtins.builtin_outputs_bin[0..]);
    defer builtin_checked.deinitRetainingModuleEnv(allocator);

    const sources = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.builtin_module.env },
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &sources);
    defer modules.deinit();
    const imports = [_]CheckedImport{.{
        .module_idx = 0,
        .key = builtin_checked.key,
        .view = importedView(&builtin_checked),
    }};

    // Prepared metadata is enough: the root and export tables are computed
    // before any compile-time evaluation runs.
    var checked = try openCheckedModule(allocator, .{
        .module_idx = 1,
        .io = std.testing.io,
        .module_env_storage = .{ .checked_source = test_env.module_env },
        .imports = &imports,
        .outputs = .{ .checked = .{} },
    });
    defer checked.deinitRetainingModuleEnv(allocator);

    var provided_runtime_roots: usize = 0;
    for ((try checked.rootRequests()).runtime_requests) |root| {
        if (root.kind == .provided_export) provided_runtime_roots += 1;
    }
    var deferred_procedure_roots: usize = 0;
    for ((try checked.rootRequests()).requests) |root| {
        if (root.kind == .provided_export and root.requires_pairing) deferred_procedure_roots += 1;
    }
    try std.testing.expectEqual(expected.deferred_procedure_roots, deferred_procedure_roots);

    var provided_data_exports: usize = 0;
    var provided_procedure_exports: usize = 0;
    for ((try checked.providedExports()).exports) |provided| {
        switch (provided) {
            .data => provided_data_exports += 1,
            .procedure => provided_procedure_exports += 1,
            .checked_error => {},
        }
    }

    try std.testing.expectEqual(expected.procedure_roots, provided_runtime_roots);
    try std.testing.expectEqual(expected.data_exports, provided_data_exports);
    try std.testing.expectEqual(expected.procedure_exports, provided_procedure_exports);
}

fn unionFieldCount(comptime Union: type) usize {
    return @typeInfo(Union).@"union".field_names.len;
}

