    const next = try names.internRecordFieldLabel("next");

    const first_fields = try allocator.alloc(CheckedRecordField, 1);
    first_fields[0] = .{ .name = next, .ty = first };
    try store.fillSyntheticTypeRoot(allocator, first, .{ .record = .{
        .fields = first_fields,
