// Round-trip tests for transform-A sub-stores (POD-element slices). Each store
// keeps its `[]T` representation; only `Serialized`/`deserialize` are added.
// Tests fill elements with deterministic bytes (including padding) and assert
// the deserialized slice is byte-identical, which validates the wiring for any
// POD element shape without needing valid field literals.

fn isSliceField(comptime FT: type) bool {
    const info = @typeInfo(FT);
    return info == .pointer and info.pointer.size == .slice;
}

/// Generic transform-A round-trip: for a store whose fields are all POD-element
/// slices or lists, allocate + byte-fill each field, serialize, deserialize, and assert
/// every field is byte-identical (incl. padding) after relocation. Validates the
/// per-field serialize/deserialize wiring for any POD element shape.
fn expectAllSliceStoreRoundTrips(comptime Store: type) store_serialize.TestError!void {
    const gpa = std.testing.allocator;
    var store: Store = .{};
    inline for (@typeInfo(Store).@"struct".field_names) |field_name| {
        // A nested store round-trips through its own `Serialized` form.
        if (comptime isNestedStoreField(@FieldType(Store, field_name))) continue;
        // A scalar field is written inline, with no buffer to round-trip.
        if (comptime @typeInfo(@FieldType(Store, field_name)) == .@"enum") continue;
        const slice = comptime isSliceField(@FieldType(Store, field_name));
        const Elem = std.meta.Child(if (slice) @FieldType(Store, field_name) else @FieldType(@FieldType(Store, field_name), "items"));
        // Give lists spare capacity to prove serialization only writes live rows.
        const buf = try gpa.alloc(Elem, if (slice) 3 else 7);
        store_serialize.poisonSlice(Elem, buf, 0x5A);
        store_serialize.zeroSlicePadding(Elem, buf);
        @field(store, field_name) = if (slice) buf else .{ .items = buf[0..3], .capacity = buf.len, .pointer_stability = .{} };
    }
    defer inline for (@typeInfo(Store).@"struct".field_names) |field_name| {
        if (comptime isSliceField(@FieldType(Store, field_name))) {
            gpa.free(@field(store, field_name));
        } else if (comptime @typeInfo(@FieldType(Store, field_name)) != .@"enum") {
            @field(store, field_name).deinit(gpa);
        }
    };

    const rt = try store_serialize.roundTripForTest(gpa, Store, &store);
    defer gpa.free(rt.buffer);
    inline for (@typeInfo(Store).@"struct".field_names) |field_name| {
        if (comptime isNestedStoreField(@FieldType(Store, field_name))) continue;
        // A scalar field is written inline, with no buffer to round-trip.
        if (comptime @typeInfo(@FieldType(Store, field_name)) == .@"enum") continue;
        const slice = comptime isSliceField(@FieldType(Store, field_name));
        const before = if (slice) @field(store, field_name) else @field(store, field_name).items;
        const after = if (slice) @field(rt.loaded, field_name) else @field(rt.loaded, field_name).items;
        try store_serialize.expectSlicesByteEqual(std.meta.Child(@TypeOf(before)), before, after);
    }
}

/// Whether a store field is itself a store with its own `Serialized` form.
fn isNestedStoreField(comptime T: type) bool {
    return @typeInfo(T) == .@"struct" and @hasDecl(T, "Serialized");
}

test "transform-A stores: serialize/deserialize round-trip preserves every slice field" {
    try expectAllSliceStoreRoundTrips(RootRequestTable);
    try expectAllSliceStoreRoundTrips(PlatformRequirementRelationTable);
}

/// Module analyses whose public API dependencies are `dependencies` and
/// whose export closures are empty, set before any consumer reads them.
fn testOpenedModuleAnalyses(allocator: Allocator, dependencies: PublicApiDependencies) Allocator.Error!*ModuleAnalyses {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    const analyses = try ModuleAnalyses.create(allocator, std.testing.io, null);
    errdefer analyses.destroy();
    analyses.markOpened();
    const published = try allocator.create(PublicApiDependencies);
    errdefer allocator.destroy(published);
    const checked_modules = try allocator.dupe(ModuleId, dependencies.modules);
    errdefer allocator.free(checked_modules);
    published.* = .{ .modules = checked_modules, .type_owner_modules = try allocator.dupe(ModuleId, dependencies.type_owner_modules) };
    std.debug.assert(analyses.public_api_dependencies.acquire(std.testing.io) == .claimed);
    analyses.public_api_dependencies.publish(std.testing.io, published);
    const closures = try allocator.create(ExportClosures);
    closures.* = .{};
    std.debug.assert(analyses.export_closures.acquire(std.testing.io) == .claimed);
    analyses.export_closures.publish(std.testing.io, closures);
    return analyses;
}

fn testVisibilityImportedView(
    key: CheckedModuleKey,
    module_env: *const ModuleEnv,
    analyses: *ModuleAnalyses,
) ImportedModuleView {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    return .{
        .key = key,
        .module_env = module_env,
        .canonical_names = undefined,
        .module_identity = .{
            .stable_hash = key.bytes,
            .module_idx = 0,
            // Visibility collection reads only the stable identity hash.
            .module_name = undefined,
            .display_module_name = undefined,
            .kind = .package,
        },
        .module_analyses = analyses,
        .checked_types = undefined,
        .platform_required_bindings = undefined,
        .evaluation = undefined,
        .const_store = undefined,
    };
}

test "lowering visibility follows recursive public API and type-owner dependencies deterministically" {
    const gpa = std.testing.allocator;

    var env_root = try ModuleEnv.init(gpa, "");
    defer env_root.deinit();
    var env_a = try ModuleEnv.init(gpa, "");
    defer env_a.deinit();
    var env_b = try ModuleEnv.init(gpa, "");
    defer env_b.deinit();
    var env_c = try ModuleEnv.init(gpa, "");
    defer env_c.deinit();
    var env_d = try ModuleEnv.init(gpa, "");
    defer env_d.deinit();
    var env_e = try ModuleEnv.init(gpa, "");
    defer env_e.deinit();
    var env_builtin = try ModuleEnv.init(gpa, "");
    defer env_builtin.deinit();
    env_builtin.module_role = .builtin;

    const root_key = testCheckedModuleKey(0xF0);
    const key_a = testCheckedModuleKey(0x05);
    const key_b = testCheckedModuleKey(0x01);
    const key_c = testCheckedModuleKey(0x03);
    const key_d = testCheckedModuleKey(0x02);
    const key_e = testCheckedModuleKey(0x04);
    const key_builtin = testCheckedModuleKey(0x06);

    const root_public = [_]ModuleId{key_b.digest()};
    const root_type_owners = [_]ModuleId{key_c.digest()};
    const a_public = [_]ModuleId{ key_c.digest(), key_builtin.digest() };
    const a_type_owners = [_]ModuleId{key_e.digest()};
    const d_type_owners = [_]ModuleId{key_b.digest()};

    const analyses = [_]*ModuleAnalyses{
        try testOpenedModuleAnalyses(gpa, .{ .modules = &root_public, .type_owner_modules = &root_type_owners }),
        try testOpenedModuleAnalyses(gpa, .{ .modules = &a_public, .type_owner_modules = &a_type_owners }),
        try testOpenedModuleAnalyses(gpa, .{}),
        try testOpenedModuleAnalyses(gpa, .{}),
        try testOpenedModuleAnalyses(gpa, .{ .type_owner_modules = &d_type_owners }),
        try testOpenedModuleAnalyses(gpa, .{}),
        try testOpenedModuleAnalyses(gpa, .{}),
    };
    defer for (analyses) |module_analyses| module_analyses.destroy();

    const views = [_]ImportedModuleView{
        testVisibilityImportedView(key_a, &env_a, analyses[1]),
        testVisibilityImportedView(key_b, &env_b, analyses[2]),
        testVisibilityImportedView(key_c, &env_c, analyses[3]),
        testVisibilityImportedView(key_d, &env_d, analyses[4]),
        testVisibilityImportedView(key_e, &env_e, analyses[5]),
        testVisibilityImportedView(key_builtin, &env_builtin, analyses[6]),
    };

    const checked_types = CheckedTypeStore{};
    // The owner's root requests are empty.
    const root_requests = try gpa.create(RootRequestTable);
    root_requests.* = .{};
    std.debug.assert(analyses[0].root_requests.acquire(std.testing.io) == .claimed);
    analyses[0].root_requests.publish(std.testing.io, root_requests);
    // The owner's checked tables are empty.
    const tables = try gpa.create(CheckedTables);
    tables.* = .{
        .method_registry = .{},
        .static_dispatch_plans = .{},
        .resolved_value_refs = .{},
        .checked_procedure_templates = .{},
        .entry_wrappers = .{},
        .top_level_procedure_bindings = .{},
        .callable_eval_templates = .{},
        .compile_time_roots = .{},
        .top_level_values = .{},
        .hoisted_constants = .{},
        .const_templates = .{},
    };
    std.debug.assert(analyses[0].checked_tables.acquire(std.testing.io) == .claimed);
    analyses[0].checked_tables.publish(std.testing.io, tables);
    // The owner exports nothing.
    const export_rows = try gpa.create(ExportRows);
    export_rows.* = .{};
    std.debug.assert(analyses[0].export_rows.acquire(std.testing.io) == .claimed);
    analyses[0].export_rows.publish(std.testing.io, export_rows);
    const platform_required_bindings = PlatformRequiredBindingTable{};
    const direct_imports = [_]CheckedModuleKey{ key_d, key_a, key_a, key_builtin };
    var owner = testVisibilityImportedView(root_key, &env_root, analyses[0]);
    owner.direct_import_module_keys = &direct_imports;
    owner.checked_types = checked_types.view();
    owner.platform_required_bindings = &platform_required_bindings;

    const resolver_views = CheckedImportViews{ .current_owner = root_key.digest(), .direct = &.{}, .available = &views };
    var visibility = try computeLoweringVisibility(gpa, owner, resolver_views.resolver());
    defer visibility.deinit(gpa);

    const expected = [_]CheckedModuleKey{ key_b, key_d, key_c, key_e, key_a };
    try std.testing.expectEqual(@as(usize, expected.len), visibility.module_ids.len);
    for (expected, visibility.module_ids) |want, got| {
        try std.testing.expectEqualSlices(u8, &want.bytes, &got.bytes);
    }
}

test "issue 11290: builtin backing declarations share their formals" {
    const gpa = std.testing.allocator;
    var names = canonical.CanonicalNameStore.init(gpa);
    defer names.deinit();
    const module_identity = try names.internModuleIdentity(&(@as([32]u8, @splat(0x90))));
    var store = CheckedTypeStore{};
    defer store.deinit(gpa);
    try attachTestSynthesizedKeys(gpa, &store, &names);

    // Publish in a different order from the builtin enum, with unrelated
    // statement ids. Lookup must follow builtin identity, not either order.
    const empty: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    try std.testing.expectEqual(empty, try store.appendRootRow(gpa, .payload));
    try store.payloads.append(gpa, .empty_record);
    for ([_]CheckedBuiltinNominal{ .set, .dict }) |owner| {
        const root: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
        const args = try gpa.alloc(CheckedTypeId, if (owner == .dict) 2 else 1);
        @memset(args, empty);
        const payload = try store.commitPayload(gpa, .{ .nominal = .{
            .name = try names.internTypeName(if (owner == .dict) "Dict" else "Set"),
            .origin_module = module_identity,
            .owner_module = testCheckedModuleKey(0x90).digest(),
            .source_decl = 100 + @as(u32, @backingInt(owner)),
            .builtin = owner,
            .is_opaque = false,
            .representation = .{ .builtin = owner },
            .args = args,
        } });
        try std.testing.expectEqual(root, try store.appendRootRow(gpa, .payload));
        try store.payloads.append(gpa, payload);
        try appendCheckedNominalDeclarationFromPayload(gpa, &store, root, empty, &.{});
        // Re-publication reuses both the template and its index entry.
        try appendCheckedNominalDeclarationFromPayload(gpa, &store, root, empty, &.{});
    }
    try std.testing.expectEqual(@as(usize, 2), store.nominal_declarations.items().len);

    store.markPublished();
    for ([_]CheckedTypeStoreView{store.view()}) |view| {
        for ([_]CheckedBuiltinNominal{ .dict, .set }) |owner| {
            const declaration = view.builtinNominalDeclaration(owner).?;
            const nominal = view.payload(declaration.declaration_root).nominal;
            try std.testing.expectEqual(owner, nominal.builtin.?);
            try std.testing.expectEqual(empty, view.nominalBackingTemplateForPayload(nominal).?);
            try std.testing.expectEqual(@as(usize, if (owner == .dict) 2 else 1), declaration.formalArgs(view).len);
            try std.testing.expectEqual(declaration.id, view.nominalDeclarationForPayload(nominal).?.id);
        }
        try std.testing.expect(view.builtinNominalDeclaration(.list) == null);
    }
}

test "module source input hash uses explicit file dependency state" {
    const gpa = std.testing.allocator;

    var missing_env = try ModuleEnv.init(gpa, "");
    defer missing_env.deinit();
    try missing_env.initCIRFields("Test");
    const missing_idx = try missing_env.recordFileDependency("data.txt", 0, 0);
    missing_env.setFileDependencyMissing(missing_idx);
    const missing_hash = hashModuleSourceInputs(&missing_env);

    missing_env.file_dependencies.items.items[@backingInt(missing_idx)].content_hash = @as([32]u8, @splat(0xFE));
    const missing_hash_after_payload_change = hashModuleSourceInputs(&missing_env);
    try std.testing.expectEqualSlices(u8, &missing_hash, &missing_hash_after_payload_change);

    var unreadable_env = try ModuleEnv.init(gpa, "");
    defer unreadable_env.deinit();
    try unreadable_env.initCIRFields("Test");
    const unreadable_idx = try unreadable_env.recordFileDependency("data.txt", 0, 0);
    unreadable_env.setFileDependencyUnreadable(unreadable_idx);
    const unreadable_hash = hashModuleSourceInputs(&unreadable_env);

    var present_env = try ModuleEnv.init(gpa, "");
    defer present_env.deinit();
    try present_env.initCIRFields("Test");
    const present_idx = try present_env.recordFileDependency("data.txt", 0, 0);
    present_env.setFileDependencyContentHash(present_idx, @as([32]u8, @splat(0)));
    const present_hash = hashModuleSourceInputs(&present_env);

    const missing_bits: u256 = @bitCast(missing_hash);
    const unreadable_bits: u256 = @bitCast(unreadable_hash);
    const present_bits: u256 = @bitCast(present_hash);

    try std.testing.expect(missing_bits != unreadable_bits);
    try std.testing.expect(missing_bits != present_bits);
    try std.testing.expect(unreadable_bits != present_bits);
}

test "compile-time root read table keeps earlier rows beside newly evaluated roots" {
    const allocator = std.testing.allocator;
    const Ref = CompileTimeRootReadTable.Ref;
    const first_reads = [_]Ref{.{ .module = @as([32]u8, @splat(1)), .root = @fromBackingInt(4) }};
    var first = try CompileTimeRootReadTable.merge(allocator, .{}, &.{
        .{ .root = @fromBackingInt(1), .reads = &first_reads },
    });
    defer first.deinit(allocator);
    try std.testing.expectEqual(@as(usize, 0), first.readsOf(testIndexId(ComptimeRootKey, 0)).len);
    try std.testing.expectEqualSlices(Ref, &first_reads, first.readsOf(@fromBackingInt(1)));

    const later_reads = [_]Ref{
        .{ .module = @as([32]u8, @splat(2)), .root = testIndexId(ComptimeRootKey, 0) },
        .{ .module = @as([32]u8, @splat(1)), .root = @fromBackingInt(4) },
    };
    var later = try CompileTimeRootReadTable.merge(allocator, first, &.{
        .{ .root = @fromBackingInt(2), .reads = &later_reads },
    });
    defer later.deinit(allocator);
    try std.testing.expectEqualSlices(Ref, &first_reads, later.readsOf(@fromBackingInt(1)));
    try std.testing.expectEqualSlices(Ref, &later_reads, later.readsOf(@fromBackingInt(2)));
    try std.testing.expectEqual(@as(usize, 0), later.readsOf(testIndexId(ComptimeRootKey, 0)).len);
    try later.validate();
}

test "SERIALIZED_VERSION_HASH golden value" {
    // Tripwire: an *accidental* change to `CheckedModule.Serialized`'s layout
    // would make previously-baked Builtin outputs / cached outputs relocate into a
    // mismatched struct. It flips this hash and fails here. On an *intentional* layout
    // change, replace the golden bytes below with the assertion output. Bump
    // `serialized_layout_version` only for semantic changes the structural hash
    // cannot observe, as documented at that discriminant.
    const golden: [32]u8 = .{
        0x8E, 0xBF, 0x7A, 0x86, 0x90, 0x27, 0xD5, 0x2D, 0xEE, 0xDE, 0xD7, 0xD5, 0xE7, 0x33, 0xB6, 0x0B,
        0x05, 0x24, 0xF2, 0x64, 0x87, 0xE9, 0x0A, 0x1B, 0x9B, 0x03, 0xEB, 0x63, 0x78, 0x42, 0xFC, 0xAE,
    };
    try std.testing.expectEqualSlices(u8, &golden, &CheckedModule.SERIALIZED_VERSION_HASH);
}

test "closed direct evidence excludes specialization-dependent nested recipes" {
    const evidence_0 = static_dispatch.EvidenceNodeId{ .index = 0, .owner = .module };
    const evidence_1 = static_dispatch.EvidenceNodeId{ .index = 1, .owner = .module };
    const evidence_2 = static_dispatch.EvidenceNodeId{ .index = 2, .owner = .module };
    const evidence_3 = static_dispatch.EvidenceNodeId{ .index = 3, .owner = .module };
    const evidence_4 = static_dispatch.EvidenceNodeId{ .index = 4, .owner = .module };
    const evidence_5 = static_dispatch.EvidenceNodeId{ .index = 5, .owner = .module };
    const def_0 = testIndexId(CIR.Def.Idx, 0);
    const def_1 = testIndexId(CIR.Def.Idx, 1);
    const callable_ty = testIndexId(CheckedTypeId, 0);
    const local_binder = testIndexId(CIR.Pattern.Idx, 0);
    const local_expr = testIndexId(CIR.Expr.Idx, 0);
    const context_anchor = testIndexId(CIR.Statement.Idx, 0);

    var refs = [_]static_dispatch.CheckedEvidence{
        .{ .dispatcher_ty = callable_ty, .resolution = .{ .constraint = .{ .index = .{ .depth = 0, .index = 0 } } } },
        .{ .dispatcher_ty = callable_ty, .resolution = .{ .direct = evidence_0 } },
        .{ .dispatcher_ty = callable_ty, .resolution = .{ .direct = evidence_1 } },
    };
    const procedure_target = static_dispatch.MethodTarget{
        .module_idx = 0,
        .def_idx = def_0,
        .kind = .{ .procedure = .{ .proc = undefined, .template = undefined } },
        .callable_ty = callable_ty,
    };
    const local_target = static_dispatch.MethodTarget{
        .module_idx = 0,
        .def_idx = def_1,
        .kind = .{ .local_proc = .{
            .binder = local_binder,
            .expr = local_expr,
            .context_anchor = context_anchor,
        } },
        .callable_ty = callable_ty,
    };
    var nodes = [_]static_dispatch.EvidenceNode{
        .{ .target = procedure_target, .instantiation = .monomorphic, .nested = .{ .resolved = .{} } },
        .{ .target = procedure_target, .instantiation = .monomorphic, .nested = .from_callable },
        .{ .target = procedure_target, .instantiation = .monomorphic, .nested = .{ .resolved = .{ .start = 0, .len = 1 } } },
        .{ .target = procedure_target, .instantiation = .monomorphic, .nested = .{ .resolved = .{ .start = 1, .len = 1 } } },
        .{ .target = procedure_target, .instantiation = .monomorphic, .nested = .{ .resolved = .{ .start = 2, .len = 1 } } },
        .{ .target = local_target, .instantiation = .monomorphic, .nested = .{ .resolved = .{} } },
    };
    var states = @as([nodes.len]DirectEvidenceClosure, @splat(.unknown));

    try std.testing.expect(try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_0, &states));
    try std.testing.expect(!try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_1, &states));
    try std.testing.expect(!try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_2, &states));
    try std.testing.expect(try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_3, &states));
    try std.testing.expect(!try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_4, &states));
    try std.testing.expect(!try directEvidenceIsClosed(std.testing.allocator, &nodes, &refs, evidence_5, &states));
}

test "opening a module releases each resource exactly once under allocation failure" {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const gpa = std.testing.allocator;

    var builtin_module = try @import("can").BuiltinStatic.moduleView(
        gpa,
        compiled_builtins.builtin_bin[0..],
        "Builtin",
        compiled_builtins.builtin_source,
    );
    var checked_owns_module = false;
    errdefer if (!checked_owns_module) builtin_module.deinit();
    var builtin_checked = try openBakedBuiltin(gpa, std.testing.io, builtin_module.env, compiled_builtins.builtin_outputs_bin[0..]);
    checked_owns_module = true;
    defer builtin_checked.deinit(gpa);

    // Aliases only: value definitions and nominal types would request
    // compile-time roots that only real evaluation can fill.
    var env = try TestEnv.init("OomOpen",
        \\Pair(a, b) : (a, b)
        \\Wrapper(a) : { value : a, extra : Pair(a, Str) }
        \\Choice(a) : [Missing, Found(a, List(Str))]
        \\Step(a) : a -> Choice(a)
    );
    defer env.deinit();
    try env.assertNoErrors();
    const sources = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = builtin_module.env },
        .{ .precompiled = env.module_env },
    };
    var modules = try TypedCIR.Modules.init(gpa, &sources);
    defer modules.deinit();
    const imports = [_]CheckedImport{.{
        .module_idx = 0,
        .key = builtin_checked.key,
        .view = importedView(&builtin_checked),
    }};
    const available = [_]ImportedModuleView{importedView(&builtin_checked)};

    const NoRoots = struct {
        fn finalize(
            _: ?*anyopaque,
            _: Allocator,
            checked: *CheckedModule,
            _: []const CheckedImport,
            _: []const ImportedModuleView,
            _: []const ImportedModuleView,
            _: ?*problem.Store,
        ) CompileTimeFinalizer.Error!void {
            std.debug.assert((try checked.rootRequests()).requests.len == 0);
        }
    };
    const finalizer = CompileTimeFinalizer{ .finalize = &NoRoots.finalize };

    const Attempt = struct {
        fn run(
            failing: Allocator,
            module_env: *ModuleEnv,
            direct: []const CheckedImport,
            views: []const ImportedModuleView,
            finalize: CompileTimeFinalizer,
        ) CompileTimeFinalizer.Error!void {
            var checked = try openCheckedModule(failing, .{
                .module_idx = 1,
                .io = std.testing.io,
                .module_env_storage = .{ .checked_source = module_env },
                .imports = direct,
                .available_modules = views,
                .outputs = .{ .checked = .{} },
            });
            defer checked.deinitRetainingModuleEnv(failing);
            try evaluateOpenedModule(failing, &checked, finalize, direct, views, null);
        }
    };
    // SafeAllocator's in-place growth depends on neighboring allocations.
    // Keep its ownership checks, but force deterministic allocation points
    // when sweeping allocation failures of opening the module.
    var no_resize = std.testing.FailingAllocator.init(gpa, .{ .resize_fail_index = 0 });
    try std.testing.checkAllAllocationFailures(no_resize.allocator(), Attempt.run, .{ env.module_env, &imports, &available, finalizer });
}

test "issue 11128 source scheme publication names each source root once" {
    const TestEnv = @import("test/TestEnv.zig");
    const gpa = std.testing.allocator;
    var env = try TestEnv.init("Schemes",
        \\identity = |x| x
        \\pair = |x, y| (x, y)
        \\same = |x| (x, x)
        \\plus = |x| x + 1
        \\identity_alias = identity
    );
    defer env.deinit();
    try env.assertNoErrors();
    const sources = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = env.module_env },
        .{ .precompiled = env.builtin_module.env },
    };
    var modules = try TypedCIR.Modules.init(gpa, &sources);
    defer modules.deinit();
    const module = modules.module(0);
    var counter = std.testing.FailingAllocator.init(gpa, .{});
    const allocator = counter.allocator();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    const import_views = CheckedImportViews{ .current_owner = .{}, .direct = &.{} };
    const test_keys = try attachTestSealedTypes(allocator, module, &names, import_views, &store);
    defer test_keys.destroy();
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    var module_index = try ModuleIndex.build(allocator, module.moduleEnvConst(), &.{});
    defer module_index.deinit(allocator);
    const defs = env.module_env.store.sliceDefs(env.module_env.global_value_defs);
    for (defs) |def| _ = try appendCheckedTypeRoot(allocator, module, &store, &active, module.defType(def));
    var source_types = try CheckedSourceTypes.init(allocator, module, .{
        .module_index = &module_index,
        .selected_hoisted_roots = &.{},
        .promoted_local_procedures = &.{},
    }, &store, store.view(), .{}, import_views.resolver());
    defer source_types.deinit();
    for (defs) |def| {
        const expected = try canonical_type_keys.schemeFromVar(gpa, module.typeStoreConst(), module.moduleEnvConst(), module.defType(def));
        try std.testing.expectEqualDeep(expected, try store.view().schemeKey(source_types.schemeForSourceVar(module, module.defType(def))));
    }
    // Each source root names one scheme, its root's own id: reading the
    // schemes again allocates nothing.
    const allocations = counter.allocated_bytes;
    for (0..128) |_| {
        for (defs) |def| _ = source_types.schemeForSourceVar(module, module.defType(def));
    }
    try std.testing.expectEqual(allocations, counter.allocated_bytes);
}

test "compile-time debug store validates message ranges" {
    const allocator = std.testing.allocator;
    const messages = [_][]const u8{ "first", "second" };
    var inputs: [messages.len]CompileTimeDebugStore.Input = undefined;
    for (messages, &inputs, 0..) |message, *input, index| {
        input.* = .{ .root = @fromBackingInt(@intCast(index)), .message = message };
    }
    var observations = try CompileTimeDebugStore.init(allocator, &inputs);
    defer observations.deinit(allocator);
    try observations.validate();
    try std.testing.expectEqualStrings("second", observations.message(observations.entries[1]));
    const malformed: CompileTimeDebugStore = .{
        .entries = &.{.{ .root = observations.entries[0].root, .message_start = 2, .message_len = std.math.maxInt(u32) }},
        .bytes = "abc",
    };
    try std.testing.expectError(error.CorruptSerializedData, malformed.validate());
    const outside: CompileTimeDebugStore = .{
        .entries = &.{.{ .root = observations.entries[0].root, .message_start = 4, .message_len = 0 }},
        .bytes = "abc",
    };
    try std.testing.expectError(error.CorruptSerializedData, outside.validate());
}

/// Test scaffolding for the direct-dispatch classification predicate: a
/// callable `{} -> [Unavailable]tail` over the given row tail.
fn testCallableWithRowTail(
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    tail: CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    const unit = try store.appendSyntheticPayloadRoot(allocator, .empty_record);
    const tags = try allocator.alloc(CheckedTag, 1);
    tags[0] = .{ .name = try names.internTagLabel("Unavailable") };
    const row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = tags,
        .ext = tail,
    } });
    return try store.appendSyntheticFunctionRoot(allocator, .pure, &.{unit}, row);
}

fn testRowTail(
    allocator: Allocator,
    store: *CheckedTypeStore,
    payload: CheckedTypePayloadBuild,
) Allocator.Error!CheckedTypeId {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    const tail = try store.reserveSyntheticTypeRoot(allocator);
    try testFillSyntheticVariableRoot(allocator, store, tail, payload);
    return tail;
}

test "direct dispatch classification treats only a body-local defaultable row tail as closed" {
    const allocator = std.testing.allocator;

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();

    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &store, &names);

    var identity_index = EnclosingIdentityIndex.init(allocator, &names, &store);
    defer identity_index.deinit();
    const nothing_enclosing = EnclosingDispatchIdentity{
        .index = &identity_index,
        .sites = &.{},
        .scopes = &.{},
    };

    // Each variable arm of the predicate, with nothing enclosing quantifying
    // the tail: only the defaultable, unconstrained flex is closed.
    const rigid_tail = try testRowTail(allocator, &store, .{ .rigid = .{ .row_default = .empty_tag_union } });
    const open_tail = try testRowTail(allocator, &store, .{ .flex = .{} });
    const numeric_tail = try testRowTail(allocator, &store, .{ .flex = .{
        .numeric_default_phase = .mono_specialization,
        .row_default = .empty_tag_union,
    } });
    const unit = try store.appendSyntheticPayloadRoot(allocator, .empty_record);
    const method_callable = try store.appendSyntheticFunctionRoot(allocator, .pure, &.{unit}, unit);
    const constraints = try allocator.alloc(CheckedStaticDispatchConstraint, 1);
    constraints[0] = .{
        .fn_name = try names.internMethodName("wrapped"),
        .fn_ty = method_callable,
        .origin = .method_call,
    };
    const constrained_tail = try testRowTail(allocator, &store, .{ .flex = .{
        .constraints = constraints,
        .row_default = .empty_tag_union,
    } });
    const local_tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });

    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        try testCallableWithRowTail(allocator, &names, &store, rigid_tail),
        nothing_enclosing,
    ));
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        try testCallableWithRowTail(allocator, &names, &store, open_tail),
        nothing_enclosing,
    ));
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        try testCallableWithRowTail(allocator, &names, &store, numeric_tail),
        nothing_enclosing,
    ));
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        try testCallableWithRowTail(allocator, &names, &store, constrained_tail),
        nothing_enclosing,
    ));
    const local_callable = try testCallableWithRowTail(allocator, &names, &store, local_tail);
    try std.testing.expect(try store.rootContainsIdentityVariables(local_callable));
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        local_callable,
        nothing_enclosing,
    ));
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        unit,
        nothing_enclosing,
    ));

    // The same defaultable tail is parametric once an enclosing scheme
    // quantifies it: the template root, a generalized-local scope's root,
    // or a scope's ancestor.
    const quantified_tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });
    const quantifying_root = try testCallableWithRowTail(allocator, &names, &store, quantified_tail);
    const quantified_callable = try testCallableWithRowTail(allocator, &names, &store, quantified_tail);
    const quantifying_site = [_]EnclosingDispatchSite{.{ .template_root = quantifying_root, .scope = .root }};
    const unrelated_site = [_]EnclosingDispatchSite{.{ .template_root = local_callable, .scope = .root }};
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &quantifying_site, .scopes = &.{} },
    ));
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &unrelated_site, .scopes = &.{} },
    ));

    // A plan referenced from two spans (a hoisted compile-time root under
    // its def template and its entry wrapper) is parametric when either
    // referencing context quantifies the tail, whichever is walked first.
    const second_quantifies = [_]EnclosingDispatchSite{
        .{ .template_root = local_callable, .scope = .root },
        .{ .template_root = quantifying_root, .scope = .root },
    };
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &second_quantifies, .scopes = &.{} },
    ));
    const neither_quantifies = [_]EnclosingDispatchSite{
        .{ .template_root = local_callable, .scope = .root },
        .{ .template_root = null, .scope = .root },
    };
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &neither_quantifies, .scopes = &.{} },
    ));

    const scopes = [_]DispatchRefScope{
        .{
            .parent = null,
            .scheme_var = testIndexId(Var, 0),
            .scheme_root = quantifying_root,
            .checked_expr = testIndexId(CIR.Expr.Idx, 0),
        },
        .{
            .parent = testIndexId(DispatchScopeId, 0),
            .scheme_var = testIndexId(Var, 1),
            .scheme_root = local_callable,
            .checked_expr = testIndexId(CIR.Expr.Idx, 1),
        },
    };
    const outer_scope_site = [_]EnclosingDispatchSite{.{ .template_root = local_callable, .scope = .{ .generalized = testIndexId(DispatchScopeId, 0) } }};
    const inner_scope_site = [_]EnclosingDispatchSite{.{ .template_root = local_callable, .scope = .{ .generalized = testIndexId(DispatchScopeId, 1) } }};
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &outer_scope_site, .scopes = &scopes },
    ));
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        quantified_callable,
        .{ .index = &identity_index, .sites = &inner_scope_site, .scopes = &scopes },
    ));
    const unrelated_tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });
    const unrelated_inner_site = [_]EnclosingDispatchSite{.{ .template_root = quantifying_root, .scope = .{ .generalized = @fromBackingInt(@intCast(1)) } }};
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        try testCallableWithRowTail(allocator, &names, &store, unrelated_tail),
        .{ .index = &identity_index, .sites = &unrelated_inner_site, .scopes = &scopes },
    ));
}

test "direct dispatch classification follows instantiation clones to the scheme that quantifies them" {
    const allocator = std.testing.allocator;

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();

    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &store, &names);

    var identity_index = EnclosingIdentityIndex.init(allocator, &names, &store);
    defer identity_index.deinit();

    // A template `{} -> [Unavailable]tail` whose body dispatches at exactly
    // that callable: specializing the plan callable against the target
    // clones the tail, and the clone must still count as the template's.
    const tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });
    const template_root = try testCallableWithRowTail(allocator, &names, &store, tail);
    const instantiated = try instantiateResolvedDispatchTargetCallable(allocator, testDispatchSubstitutionTypes(&store, &names), template_root, template_root);
    const instantiated_tail = switch (store.payload(checkedFunctionPayload(&store, instantiated, "test callable").ret)) {
        .tag_union => |tag_union| tag_union.ext,
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        .empty_tag_union,
        => return error.TestUnexpectedResult,
    };
    try std.testing.expect(store.payload(instantiated_tail) == .flex);
    try std.testing.expectEqual(tail, store.identityOrigin(instantiated_tail));

    const template_site = [_]EnclosingDispatchSite{.{ .template_root = template_root, .scope = .root }};
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        instantiated,
        .{ .index = &identity_index, .sites = &template_site, .scopes = &.{} },
    ));
    try std.testing.expect(try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        instantiated,
        .{ .index = &identity_index, .sites = &.{}, .scopes = &.{} },
    ));

    // A relation-substituted template root is itself a clone; both sides
    // resolve to the same origin.
    var template_substitution = CheckedTypeSubstitution.init(allocator, &.{}, &.{});
    defer template_substitution.deinit();
    const substituted_root = try store.cloneCheckedTypeRootSubstituting(allocator, template_root, &template_substitution);
    const substituted_site = [_]EnclosingDispatchSite{.{ .template_root = substituted_root, .scope = .root }};
    try std.testing.expect(!try callableIdentityIsSpecializationIndependent(
        allocator,
        &store,
        instantiated,
        .{ .index = &identity_index, .sites = &substituted_site, .scopes = &.{} },
    ));

    // A target and a plan with distinct tails: identity against identity
    // records no substitution (`collectDispatchPlanIdentitySubstitutions`),
    // so the plan's tail survives and the surviving clone's origin is the
    // plan's, never the target's.
    const target_tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });
    const target_root = try testCallableWithRowTail(allocator, &names, &store, target_tail);
    const plan_tail = try testRowTail(allocator, &store, .{ .flex = .{ .row_default = .empty_tag_union } });
    const plan_root = try testCallableWithRowTail(allocator, &names, &store, plan_tail);
    const specialized = try instantiateResolvedDispatchTargetCallable(allocator, testDispatchSubstitutionTypes(&store, &names), target_root, plan_root);
    const specialized_tail = switch (store.payload(checkedFunctionPayload(&store, specialized, "test callable").ret)) {
        .tag_union => |tag_union| tag_union.ext,
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        .empty_tag_union,
        => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(plan_tail, store.identityOrigin(specialized_tail));
    try std.testing.expect(store.identityOrigin(specialized_tail) != target_tail);

    // A relation-substituted clone of the plan root as the plan: the
    // surviving tail's origin is two clones deep, and `identityOrigin`
    // walks the chain to the published variable.
    var plan_substitution = CheckedTypeSubstitution.init(allocator, &.{}, &.{});
    defer plan_substitution.deinit();
    const plan_clone = try store.cloneCheckedTypeRootSubstituting(allocator, plan_root, &plan_substitution);
    const plan_clone_tail = switch (store.payload(checkedFunctionPayload(&store, plan_clone, "test callable").ret)) {
        .tag_union => |tag_union| tag_union.ext,
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        .empty_tag_union,
        => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(plan_tail, store.identity_origins.get(plan_clone_tail).?);
    const respecialized = try instantiateResolvedDispatchTargetCallable(allocator, testDispatchSubstitutionTypes(&store, &names), target_root, plan_clone);
    const respecialized_tail = switch (store.payload(checkedFunctionPayload(&store, respecialized, "test callable").ret)) {
        .tag_union => |tag_union| tag_union.ext,
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        .empty_tag_union,
        => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(plan_clone_tail, store.identity_origins.get(respecialized_tail).?);
    try std.testing.expectEqual(plan_tail, store.identityOrigin(respecialized_tail));

    // Every clone above is a synthetic variable root with a declared origin;
    // a synthetic variable root that declares none trips `identityOrigin`'s
    // invariant (not exercised here: invariants abort the process), which is
    // what stops a forgotten clone origin from reading as an unquantified
    // tail. A declared fresh instance is its own origin.
    try std.testing.expect(store.synthetic_variable_roots.contains(respecialized_tail));
    try std.testing.expect(store.synthetic_variable_roots.contains(plan_tail));
    try std.testing.expectEqual(plan_tail, store.identityOrigin(plan_tail));
}

test "issue 11737: identical callable contract vectors share their checked storage" {
    const allocator = std.testing.allocator;
    var pass: EvidencePass = undefined;
    pass.allocator = allocator;
    pass.owner = .module;
    pass.evidence_refs = .empty;
    pass.callable_contract_buckets = .empty;
    pass.callable_contracts = .empty;
    defer pass.evidence_refs.deinit(allocator);
    defer pass.callable_contract_buckets.deinit(allocator);
    defer pass.callable_contracts.deinit(allocator);
    const contract = [_]static_dispatch.CheckedEvidence{.{
        .dispatcher_ty = @fromBackingInt(@intCast(1)),
        .resolution = .unreachable_value,
    }};
    const first = try pass.internCallableContracts(&contract);
    const repeated = try pass.internCallableContracts(&contract);
    try std.testing.expectEqual(first, repeated);
    try std.testing.expectEqual(@as(usize, 1), pass.evidence_refs.items.len);
    var different = contract;
    different[0].resolution = .checked_error;
    try std.testing.expect(!std.meta.eql(first, try pass.internCallableContracts(&different)));
}

test "checked polarity alias publication erases hidden arguments and preserves backing" {
    const allocator = std.testing.allocator;
    const TestEnv = @import("test/TestEnv.zig");
    var env = try TestEnv.init("HiddenAlias",
        \\Result(a) : [Ok(a), Err]
        \\value : {} -> Result({})
        \\value = |_| crash "unused"
    );
    defer env.deinit();
    try env.assertNoErrors();
    const source_modules = [_]TypedCIR.Modules.SourceModule{.{ .precompiled = env.module_env }};
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);
    const defs = env.module_env.store.sliceDefs(env.module_env.all_defs);
    const function = env.module_env.types.resolveVar(ModuleEnv.varFrom(defs[defs.len - 1])).desc.content.structure.fn_pure;
    const raw_alias = env.module_env.types.resolveVar(function.ret).desc.content.alias;
    try std.testing.expectEqual(@as(u32, 1), raw_alias.source_arg_count);
    try std.testing.expectEqual(@as(usize, 1), env.module_env.types.sliceAliasHiddenArgs(raw_alias).len);
    const raw_backing = env.module_env.types.resolveVar(env.module_env.types.getAliasBackingVar(raw_alias)).desc.content.structure.tag_union;
    try std.testing.expectEqual(env.module_env.types.resolveVar(raw_backing.ext).var_, env.module_env.types.resolveVar(env.module_env.types.sliceAliasHiddenArgs(raw_alias)[0]).var_);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
    defer test_keys.destroy();
    const root = try appendCheckedTypeRoot(allocator, module, &store, &active, function.ret);
    const alias = store.payload(root).alias;
    try std.testing.expectEqual(@as(usize, 1), alias.args.len);
    const row = store.payload(alias.backing).tag_union;
    try std.testing.expect(store.payload(row.ext) == .flex);
    const source_key = try canonical_type_keys.fromVar(allocator, module.typeStoreConst(), module.moduleEnvConst(), function.ret);
    try std.testing.expectEqualSlices(u8, &source_key.bytes, &(try store.rootKey(root)).bytes);
}
